    fun init() {
        synchronized(activeHooks) { activeHooks += this }
        if (!installed.compareAndSet(false, true)) return
        val initStarted = SystemClock.uptimeMillis()
        val initialState = state
        val ringScale = storyRingScaleFactor(initialState)
        val shouldInstallNetwork = shouldInstallNetworkHooks(initialState)
        val anyDownloadFeature = hasAnyDownloadFeature()
        val shouldInstallIntentClipboard = shouldInstallIntentAndClipboardHooks(initialState)
        val shouldInstallPreferences = shouldInstallPreferenceHooks(initialState)
        val shouldInstallImageHooks = shouldInstallImageUrlHooks(initialState)
        val shouldInstallActivity = shouldInstallActivityHooks(initialState)
        val shouldInstallView = shouldInstallViewHooks(initialState)
        val shouldInstallScrollBusy = shouldInstallScrollBusyHooks(initialState)
        val shouldInstallDexKit = shouldInstallDexKitHooks(initialState)
        logInfo(
            "Installing Instagram hooks from ${initialState.source}: " +
                "privacy=${initialState.isGhostSeen || initialState.isGhostTyping || initialState.isGhostStory}, " +
                "localPlus=${initialState.localInstagramPlus}, storyLongPress=${initialState.enableStoryTrayLongPressActions}, " +
                "dmContext=${initialState.enableDmContextMenuOptions}, keepUnsent=${initialState.keepUnsentMessages}, " +
                "ui=${initialState.hasAnyFeedSuppression()}, downloads=$anyDownloadFeature, " +
                "network=${initialState.isAdBlockEnabled || initialState.isAnalyticsBlocked || initialState.disableTrackingLinks}"
        )
        logInfo(
            "Instagram diagnostics config confirmRefresh=${initialState.enableConfirmRefresh}/${initialState.confirmRefreshScope} " +
                "startSoundFeed=${initialState.feedVideosStartWithSound} startSoundStories=${initialState.storiesStartWithSound} " +
                "adBlock=${initialState.isAdBlockEnabled} analyticsBlock=${initialState.isAnalyticsBlocked} " +
                "downloadMode=${initialState.reelDownloadControlMode} postDownload=${initialState.enablePostDownload} " +
                "reelDownload=${initialState.enableReelDownload} dmContext=${initialState.enableDmContextMenuOptions} " +
                "keepUnsent=${initialState.keepUnsentMessages} preventDmAutoscroll=${initialState.preventDmMessageListAutoscroll}"
        )
        installHookStep("ScreenshotWindow") { installScreenshotAndWindowHooks() }
        installHookStep("Activity", shouldInstallActivity) { installActivityHooks() }
        installHookStep("DevOptionsStable", initialState.isDevEnabled) { ensureDevOptionsStableHooks("startup") }
        installHookStep("KeepWarmReceiverGuard") { installKeepWarmReceiverGuard() }
        installHookStep("View", shouldInstallView) { installViewHooks() }
        installHookStep("FlickPerf", shouldInstallScrollBusy) { installFlickPerfRecyclerHooks() }
        installHookStep("DirectMessageBehavior", initialState.preventDmMessageListAutoscroll) { installDirectMessageBehaviorHooks() }
        installHookStep("KeepUnsentRecyclerView", initialState.keepUnsentMessages) { installKeepUnsentRecyclerViewHooks() }
        installHookStep("StoryTrayMenuInjection", initialState.enableStoryTrayLongPressActions) { installMenuInjectionHooks() }
        installHookStep("DirectMessageContextMenu", initialState.enableDmContextMenuOptions || initialState.keepUnsentMessages) { installDirectMessageContextMenuHook() }
        installHookStep("SponsoredRecycler", initialState.isAdBlockEnabled) { installSponsoredRecyclerHook() }
        installHookStep("Text", initialState.keepUnsentMessages || hasAnyTextViewWork(initialState)) { installTextHooks() }
        installHookStep("StaticLayoutDateFormat", initialState.enableCustomDateFormat && initialState.customDateFormatComments) { installStaticLayoutDateFormatHooks() }
        installHookStep("IntentClipboard", shouldInstallIntentClipboard) { installIntentAndClipboardHooks() }
        installHookStep("NotesLocationSpoof", hasValidNotesLocationSpoof(initialState)) { installInstagramMapLocationSpoofHooks() }
        installHookStep("ConfirmRefresh", initialState.enableConfirmRefresh) { installConfirmRefreshHooks() }
        installHookStep("Preferences", shouldInstallPreferences) { installPreferenceHooks() }
        installHookStep("RecentSearch", initialState.doNotSaveRecentSearches || initialState.enableHideChats) { installRecentSearchHooks() }
        installHookStep("Resources", ringScale != 1f) { installResourceHooks() }
        installHookStep("ManualVideoOverlay", initialState.disableVideoAutoPlay) { installManualVideoPlayOverlayHooks() }
        installHookStep("Gesture", false) { installGestureHooks() }
        installHookStep("InstagramImage", shouldInstallImageHooks) { installInstagramImageHooks() }
        installHookStep("PostMediaUrlCapture", shouldInstallGenericPostMediaUrlCapture(initialState)) { installPostMediaUrlCaptureHooks() }
        installHookStep("HighQualityUpload", initialState.enableHighQualityStoryUpload) {
            installHighQualityUploadHooks()
            installHeicUploadFallbackHooks()
        }
        installHookStep("StartVideosWithSound", initialState.feedVideosStartWithSound || initialState.storiesStartWithSound) { installStartVideosWithSoundHooks() }
        installHookStep(
            "StoryVideoReflection",
            initialState.enableStoryDownload || initialState.enablePostDownload || initialState.enableReelDownload || initialState.enableReelThumbnailDownload
        ) {
            initStoryVideoVersionReflection()
        }
        installHookStep("MediaDownloadReflection", anyDownloadFeature || initialState.enableDmContextMenuOptions) { initMediaDownloadReflection() }
        installHookStep("CustomEmojiFont", initialState.customEmojiFontEnabled) { InstagramCustomEmojiFontHooks.install(androidContext, appClassLoader) }
        installHookStep("ShareSheetEmojiShortcuts", initialState.enableShareSheetEmojiShortcuts) { InstagramShareSheetEmojiShortcutHooks.install(appClassLoader) }
        installHookStep("DisableShareSheetGroupCreation", initialState.disableGroupCreationFromShareSheet) { InstagramShareSheetGroupCreationHooks.install(appClassLoader) }
        installHookStep("ActivityHistory", initialState.enableActivityHistory) { InstagramActivityHistoryHooks.install(androidContext, appClassLoader) }
        installHookStep("Network", shouldInstallNetwork) {
            installOkHttpHooks()
            installTigonHooks()
        }
        installHookStep("DexKit", shouldInstallDexKit) { installDexKitHooks() }
        if (initialState.enableHideChats) scheduleDirectChatDatabaseSnapshot("startup", 8_000L)
        logInfo(
            "Instagram hook init complete elapsed=${SystemClock.uptimeMillis() - initStarted}ms " +
                "dexMethods=${hookedDexMethods.size} refreshUiGuards=$confirmRefreshUiGuardHookedClasses"
        )
    }

    private fun installScreenshotAndWindowHooks() {
        val hook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (!state.allowScreenshots) return
                val flags = param.args.getOrNull(0) as? Int ?: return
                if ((flags and WindowManager.LayoutParams.FLAG_SECURE) != 0) {
                    if (param.method.name == "addFlags") {
                        param.args[0] = flags and WindowManager.LayoutParams.FLAG_SECURE.inv()
                    } else if (param.args.size >= 2) {
                        val mask = param.args[1] as? Int ?: return
                        param.args[0] = flags and WindowManager.LayoutParams.FLAG_SECURE.inv()
                        param.args[1] = mask and WindowManager.LayoutParams.FLAG_SECURE.inv()
                    }
                    logInfo("Stripped Instagram secure screenshot flag")
                }
            }
        }
        runSafe("Window screenshot hooks") {
            XposedBridge.hookAllMethods(Window::class.java, "addFlags", hook)
            XposedBridge.hookAllMethods(Window::class.java, "setFlags", hook)
        }
    }

    private fun installActivityHooks() {
        if (!activityHooksInstalled.compareAndSet(false, true)) return
        runSafe("Activity lifecycle hooks") {
            fun applyMonetActivity(activity: Activity) {
                currentActivity = activity
                activeActivities.add(activity)
                rememberInstagramFragmentActivity(activity)
                return
                refreshMonetPalette(activity)
                applyMonetToActivity(activity)
            }
            val monetActivityHook = object : XC_MethodHook() {
                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    applyMonetActivity(param.thisObject as? Activity ?: return)
                }
            }
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onCreate",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        rememberInstagramFragmentActivity(activity)
                        maybeHandleDevOptionsIntent(activity, activity.intent, "onCreate")
                    }

                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        currentActivity = activity
                        rememberInstagramFragmentActivity(activity)
                        maybeOpenPendingDevOptions(activity, "onCreate")
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onResume",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        currentActivity = activity
                        rememberInstagramFragmentActivity(activity)
                        maybeHandleDevOptionsIntent(activity, activity.intent, "onResume")
                        maybeOpenPendingDevOptions(activity, "onResume")
                        applySmoothActivityTuning(activity)
                        activity.window?.decorView?.postDelayed({ applySmoothActivityTuning(activity) }, 750L)
                        if (state.allowScreenshots) activity.window?.clearFlags(WindowManager.LayoutParams.FLAG_SECURE)
                        rememberRoot(activity.window?.decorView)
                        if (false) {
                            refreshMonetPalette(activity)
                            applyMonetToActivity(activity)
                        }
                        refreshActivity(activity, "onResume")
                        wireInstagramEntryPoints(activity)
                        maybeProbeInstantUploadButton(activity, 40L, 120L, 260L, 520L, 900L, 1_450L)
                        applyGhostIndicator(activity)
                        applyCaptureOverlay(activity)
                        clickDefaultNavigationTab(activity)
                        activity.window?.decorView?.postDelayed({
                            InstagramFeatureStatus.maybeShowLoadedToast(activity, state)
                        }, 1_500L)
                    }
                }
            )
            listOf("onStart", "onPostResume", "onAttachedToWindow", "setContentView").forEach { methodName ->
                runCatching { XposedBridge.hookAllMethods(Activity::class.java, methodName, monetActivityHook) }
            }
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onNewIntent",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        currentActivity = activity
                        rememberInstagramFragmentActivity(activity)
                        maybeHandleDevOptionsIntent(activity, param.args.firstOrNull() as? Intent, "onNewIntent")
                        maybeOpenPendingDevOptions(activity, "onNewIntent")
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onWindowFocusChanged",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (param.args.firstOrNull() != true) return
                        val activity = param.thisObject as? Activity ?: return
                        applySmoothActivityTuning(activity)
                        applyMonetActivity(activity)
                        maybeProbeInstantUploadButton(activity, 40L, 140L, 320L, 700L, 1_200L)
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "dispatchTouchEvent",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        val event = param.args.firstOrNull() as? MotionEvent ?: return
                        noteInputScrollBusy(event)
                        if (ENABLE_FLICK_PERF_DIAGNOSTICS) rememberFlickPerfDispatchStart(event)
                        val purrfectStartedNanos = if (ENABLE_FLICK_PERF_DIAGNOSTICS) {
                            SystemClock.elapsedRealtimeNanos()
                        } else {
                            0L
                        }
                        try {
                            val action = event.actionMasked
                            val root = activity.window?.decorView
                            if (action == MotionEvent.ACTION_MOVE) {
                                if (isDirectMessageAutoscrollPreventionEnabled() &&
                                    hasActiveDirectMessageAutoscrollGuard()
                                ) {
                                    releaseDirectMessageAutoscrollFromRootTouch(root, event)
                                }
                                return
                            }
                            if (action == MotionEvent.ACTION_DOWN ||
                                action == MotionEvent.ACTION_UP ||
                                action == MotionEvent.ACTION_CANCEL
                            ) {
                                updateDmTouchDispatchHooksForRoot(root, "activity-touch")
                            }
                            if (isDirectMessageAutoscrollPreventionEnabled()) {
                                when (action) {
                                    MotionEvent.ACTION_DOWN -> if (dmDirectSurfaceActive || dmMessageListViewRef?.get()?.isShown == true) {
                                        noteDirectMessageListUserTouchFromRoot(root, event)
                                    }
                                    MotionEvent.ACTION_MOVE -> if (hasActiveDirectMessageAutoscrollGuard()) {
                                        releaseDirectMessageAutoscrollFromRootTouch(root, event)
                                    }
                                }
                            }
                            rememberStoryShareTouch(activity, event)
                            if (action == MotionEvent.ACTION_DOWN) {
                                rememberInstagramSoundTouchDown(event)
                            } else if (action == MotionEvent.ACTION_UP) {
                                rememberManualInstagramSoundMuteFromTouch(event)
                            }
                            if (action == MotionEvent.ACTION_DOWN) {
                                rememberDmPotentialLongPressTouchPoint(event)
                                rememberDmMessageActionRootTouchPoint(root, event)
                            }
                            if (action == MotionEvent.ACTION_UP) {
                                if (shouldHandleInstantUploadTouch(activity)) {
                                    hideInstantUploadOnShelfTap(activity, event)
                                    maybeProbeInstantUploadButton(activity, 60L, 180L, 420L, 900L, 1_800L, 3_000L)
                                }
                                if (hasCachedDirectTouchSurface()) handleNativeDmUnsendActivityTouch(activity, event)
                            }
                            if (handleUploadTouch(activity, event)) {
                                flickPerfActivityClaimedBy = "dm-upload-touch"
                                param.result = true
                            }
                        } finally {
                            if (ENABLE_FLICK_PERF_DIAGNOSTICS) {
                                flickPerfPurrfectBeforeNanos.set(SystemClock.elapsedRealtimeNanos() - purrfectStartedNanos)
                            }
                        }
                    }

                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!ENABLE_FLICK_PERF_DIAGNOSTICS) return
                        val activity = param.thisObject as? Activity ?: return
                        val event = param.args.firstOrNull() as? MotionEvent ?: return
                        finishFlickPerfActivityDispatch(activity, event, param.result == true)
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "dispatchKeyEvent",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        val event = param.args.firstOrNull() as? KeyEvent ?: return
                        if (event.action == KeyEvent.ACTION_UP && event.keyCode == KeyEvent.KEYCODE_BACK) {
                            logInstantUploadDebug("back-key-before-restore", activity)
                            restoreInstantUploadWithFirstOpenPass(activity)
                        }
                    }
                }
            )
            runCatching {
                XposedBridge.hookAllMethods(
                    Activity::class.java,
                    "onBackPressed",
                    object : XC_MethodHook() {
                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            val activity = param.thisObject as? Activity ?: return
                            logInstantUploadDebug("onBackPressed-after-before-restore", activity)
                            restoreInstantUploadWithFirstOpenPass(activity)
                        }
                    }
                )
            }
            XposedBridge.hookAllMethods(
                Instrumentation::class.java,
                "callActivityOnPause",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val throwable = param.throwable ?: return
                        val activity = param.args.firstOrNull() as? Activity ?: return
                        if (!shouldSuppressDmModalPauseCrash(activity, throwable)) return
                        logInfo("Suppressed Instagram DM modal pause crash after custom action")
                        param.throwable = null
                    }
                }
            )
            listOf("callActivityOnStop", "callActivityOnDestroy").forEach { methodName ->
                runCatching {
                    XposedBridge.hookAllMethods(
                        Instrumentation::class.java,
                        methodName,
                        object : XC_MethodHook() {
                            override fun afterHookedMethod(param: MethodHookParam<*>) {
                                val throwable = param.throwable ?: return
                                val activity = param.args.firstOrNull() as? Activity ?: return
                                if (!shouldSuppressDmModalPauseCrash(activity, throwable)) return
                                logInfo("Suppressed Instagram DM modal ${methodName.removePrefix("callActivityOn").lowercase(Locale.US)} crash after custom action")
                                param.throwable = null
                            }
                        }
                    )
                }
            }
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onDestroy",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity
                        quickToggleButtons.remove(activity)
                        activity?.let {
                            captureOverlayStates.remove(it)?.remove()
                            if (currentActivity == it) currentActivity = null
                            activeActivities.remove(it)
                        }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onActivityResult",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val requestCode = param.args.getOrNull(0) as? Int ?: return
                        if (requestCode == REQUEST_PICK_INSTANT_IMAGE) {
                            if (!state.enableUploadInstantsFromGallery) return
                            val activity = param.thisObject as? Activity ?: return
                            val resultCode = param.args.getOrNull(1) as? Int ?: Activity.RESULT_CANCELED
                            val data = param.args.getOrNull(2) as? Intent
                            handlePickedInstantImage(activity, resultCode, data)
                            param.result = null
                            return
                        }
                        if (!state.enableDmAnyFileUpload) return
                        if (requestCode != REQUEST_PICK_ANY_FILE) return
                        val activity = param.thisObject as? Activity ?: return
                        val resultCode = param.args.getOrNull(1) as? Int ?: Activity.RESULT_CANCELED
                        val data = param.args.getOrNull(2) as? Intent
                        handlePickedAnyFile(activity, resultCode, data)
                        param.result = null
                    }
                }
            )
        }
    }

    private fun applySmoothActivityTuning(activity: Activity) {
        runCatching {
            val window = activity.window ?: return@runCatching
            val display = activity.display
            val fastestMode = display?.supportedModes?.maxByOrNull { it.refreshRate }
            val maxRefreshRate = fastestMode?.refreshRate ?: 120f
            window.attributes = window.attributes.apply {
                if (fastestMode != null) preferredDisplayModeId = fastestMode.modeId
                preferredRefreshRate = maxRefreshRate.coerceAtLeast(90f)
                flags = flags or WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED
            }
            applyMaximumViewFrameRate(window.decorView, maxRefreshRate.coerceAtLeast(90f))
        }
    }

    private fun applyMaximumViewFrameRate(view: View?, refreshRate: Float) {
        if (view == null || Build.VERSION.SDK_INT < Build.VERSION_CODES.R) return
        runCatching {
            View::class.java
                .getMethod("setFrameRate", java.lang.Float.TYPE, java.lang.Integer.TYPE)
                .invoke(view, refreshRate, 0)
        }
    }

    private fun installViewHooks() {
        if (!viewHooksInstalled.compareAndSet(false, true)) return
        val attachHook = object : XC_MethodHook() {
            override fun afterHookedMethod(param: MethodHookParam<*>) {
                val view = param.thisObject as? View ?: return
                if (shouldBypassGlobalViewHookForScroll(view)) {
                    applyExplicitHiddenUiFast(view, "attach-scroll")
                    return
                }
                rememberRoot(view)
                processView(view, "attach")
            }
        }
        runSafe("View hooks") {
            XposedBridge.hookAllMethods(View::class.java, "onAttachedToWindow", attachHook)
            XposedBridge.hookAllMethods(
                ViewGroup::class.java,
                "addView",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val child = param.args.firstOrNull { it is View } as? View ?: return
                        if (shouldBypassGlobalViewHookForScroll(child)) {
                            applyExplicitHiddenUiFast(child, "addView-scroll")
                            return
                        }
                        processView(child, "addView")
                        (param.thisObject as? View)?.let { parent ->
                            maybeScheduleStoryRingPassForAddedView(parent, child)
                            if (state.isAdBlockEnabled) hideSponsoredSurfaceIfNeeded(parent)
                            if (state.enableStoryTrayLongPressActions) maybeInjectStoryTrayActionsIntoNativeMenu(parent)
                            if (state.enableProfileDownload && suppressProfileActionBarChildHook.get() != true && parent is ViewGroup && isProfileShareCardFast(parent)) {
                                scheduleProfileCardInjection(parent, 64L)
                            }
                        }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                ViewStub::class.java,
                "inflate",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        (param.result as? View)?.let { view ->
                            if (shouldBypassGlobalViewHookForScroll(view)) {
                                applyExplicitHiddenUiFast(view, "inflate-scroll")
                            } else {
                                processView(view, "inflate")
                            }
                        }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                ViewGroup::class.java,
                "onViewAdded",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableProfileDownload || suppressProfileActionBarChildHook.get() == true) return
                        val parent = param.thisObject as? ViewGroup ?: return
                        ensureProfileResourceIds(parent.context)
                        if (isProfileShareCardFast(parent)) scheduleProfileCardInjection(parent, 64L)
                    }
                }
            )
            XposedBridge.hookAllMethods(
                ViewGroup::class.java,
                "removeAllViews",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableProfileDownload || suppressProfileActionBarChildHook.get() == true) return
                        val parent = param.thisObject as? ViewGroup ?: return
                        ensureProfileResourceIds(parent.context)
                        if (isProfileShareCardFast(parent)) scheduleProfileCardInjection(parent, 96L)
                    }
                }
            )
            if (hiddenUiCallbackHooksInstalled.compareAndSet(false, true)) {
                XposedBridge.hookAllMethods(
                    View::class.java,
                    "setVisibility",
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (hiddenUiInternalChange.get() == true) return
                            val view = param.thisObject as? View ?: return
                            if (!needsHiddenUiCallbackWork(view)) return
                            if (shouldEnforceHiddenUiView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = View.GONE
                            } else if (hasAnyViewHideRule() && shouldHideView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = View.GONE
                            }
                        }
                    }
                )
                XposedBridge.hookAllMethods(
                    View::class.java,
                    "setAlpha",
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (hiddenUiInternalChange.get() == true) return
                            val view = param.thisObject as? View ?: return
                            if (!needsHiddenUiCallbackWork(view)) return
                            if (shouldEnforceHiddenUiView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = 0f
                            } else if (hasAnyViewHideRule() && shouldHideView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = 0f
                            }
                        }
                    }
                )
                XposedBridge.hookAllMethods(
                    View::class.java,
                    "setEnabled",
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (hiddenUiInternalChange.get() == true) return
                            val view = param.thisObject as? View ?: return
                            if (!needsHiddenUiCallbackWork(view)) return
                            if (shouldEnforceHiddenUiView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = false
                            } else if (hasAnyViewHideRule() && shouldHideView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = false
                            }
                        }
                    }
                )
                XposedBridge.hookAllMethods(
                    View::class.java,
                    "setClickable",
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (hiddenUiInternalChange.get() == true) return
                            val view = param.thisObject as? View ?: return
                            if (!needsHiddenUiCallbackWork(view)) return
                            if (shouldEnforceHiddenUiView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = false
                            } else if (hasAnyViewHideRule() && shouldHideView(view)) {
                                rememberHiddenUiState(view)
                                param.args[0] = false
                            }
                        }
                    }
                )
                XposedBridge.hookAllMethods(
                    View::class.java,
                    "setLayoutParams",
                    object : XC_MethodHook() {
                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            if (hiddenUiInternalChange.get() == true) return
                            val view = param.thisObject as? View ?: return
                            if (!needsHiddenUiCallbackWork(view)) return
                            if (shouldEnforceHiddenUiView(view)) {
                                rememberHiddenUiState(view)
                                forceHiddenUiView(view)
                            } else if (hasAnyViewHideRule() && shouldHideView(view)) {
                                rememberHiddenUiState(view)
                                forceHiddenLayout(view)
                            }
                        }
                    }
                )
                listOf("setPadding", "setPaddingRelative").forEach { methodName ->
                    XposedBridge.hookAllMethods(
                        View::class.java,
                        methodName,
                        object : XC_MethodHook() {
                            override fun afterHookedMethod(param: MethodHookParam<*>) {
                                if (hiddenUiInternalChange.get() == true) return
                                val view = param.thisObject as? View ?: return
                                if (!needsHiddenUiCallbackWork(view)) return
                                enforceComposerUiAdjustment(view)
                            }
                        }
                    )
                }
            }
            XposedBridge.hookAllMethods(
                View::class.java,
                "performLongClick",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        rememberKeepUnsentActionRowFromLongClick(view)
                        rememberDmMessageActionLongPress(view, "performLongClick")
                        if (handleUploadLongPress(view) || handleInstantUploadClick(view) || handleInstantDownloadClick(view) || handleDirectSeenLongPress(view) || handleEntryPointLongPress(view) || handleStoryTrayLongPress(view) || handleCopyLongPress(view) || handleCaptureLongPress(view)) {
                            param.result = true
                        }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                View::class.java,
                "performClick",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        rememberManualInstagramSoundMute(view)
                        noteDirectComposerSendClick(view)
                        if (handleUploadClick(view) || handleInstantUploadClick(view) || handleInstantDownloadClick(view) || handleCopyBioMenuClick(view)) param.result = true
                        if (handleDmMessageActionOverlayClick(view)) param.result = true
                    }

                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        handleDmMessageActionOverlayClick(view)
                    }
                }
            )
            XposedBridge.hookAllMethods(
                View::class.java,
                "setContentDescription",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        if (shouldBypassGlobalViewHookForScroll(view)) return
                        val description = param.args.firstOrNull()?.toString()?.trim()?.lowercase(Locale.US) ?: return
                        when (description) {
                            "turn sound on" -> {
                                soundOffControlViews.remove(view)
                                maybeAutoEnableInstagramSound(view)
                            }
                            "turn sound off" -> rememberVisibleSoundOffControl(view, "content-description")
                        }
                    }
                }
            )
            updateDmTouchDispatchHooksForRoot(currentActivity?.window?.decorView, "view-hooks-init")
        }
    }

    private fun needsDmTouchDispatchHooks(current: InstagramFeatureState = state): Boolean =
        current.enableDmContextMenuOptions ||
            current.keepUnsentMessages

    private fun updateDmTouchDispatchHooksForRoot(root: View?, reason: String) {
        val current = state
        if (!needsDmTouchDispatchHooks(current)) {
            uninstallDmTouchDispatchHooks("$reason:disabled")
            return
        }
        val base = root?.rootView ?: root
        if (base == null) {
            uninstallDmTouchDispatchHooks("$reason:no-root")
            return
        }
        if (reason == "activity-touch" && dmTouchDispatchHooksInstalled) {
            uninstallDmTouchDispatchHooks("$reason:cleanup")
            return
        }
        val allowOverlayScan = reason == "direct-view" || dmTouchDispatchHooksInstalled
        if (shouldInstallDmTouchDispatchHooksForRoot(base, current, allowOverlayScan)) {
            installDmTouchDispatchHooks("$reason:message-actions")
        } else {
            uninstallDmTouchDispatchHooks("$reason:no-message-actions")
        }
    }

    private fun maybeActivateDmTouchDispatchHooksFromView(view: View, current: InstagramFeatureState) {
        if (!needsDmTouchDispatchHooks(current)) return
        val root = view.rootView ?: view
        if (dmTouchDispatchHooksInstalled && hasRecentDmTouchHookSurface(root)) return
        if (!isPotentialDmTouchHookMarker(view)) return
        updateDmTouchDispatchHooksForRoot(view.rootView ?: view, "direct-view")
    }

    private fun shouldInstallDmTouchDispatchHooksForRoot(
        root: View,
        current: InstagramFeatureState,
        allowOverlayScan: Boolean
    ): Boolean {
        if (!needsDmTouchDispatchHooks(current)) return false
        if (hasRecentDmTouchHookSurface(root)) return true
        if (!allowOverlayScan) return false
        return rootContainsActiveDmMessageActionsOverlay(root) || hasPurrfectDmActionRowsVisible(root)
    }

    private fun hasRecentDmTouchHookSurface(root: View?, maxAgeMs: Long = 420L): Boolean {
        val base = root?.rootView ?: root ?: return false
        val now = SystemClock.uptimeMillis()
        if (dmOverlayRootRef?.get() === base &&
            now - dmOverlayRootCheckAtMs in 0L..maxAgeMs &&
            dmOverlayRootActive
        ) {
            return true
        }
        if (dmActiveOverlayRootRef?.get() === base &&
            now - dmActiveOverlayCheckAtMs in 0L..maxAgeMs &&
            dmActiveOverlayVisibleCached
        ) {
            return true
        }
        if (dmPurrfectRowsRootRef?.get() === base &&
            now - dmPurrfectRowsCheckAtMs in 0L..maxAgeMs &&
            dmPurrfectRowsVisibleCached
        ) {
            return true
        }
        return false
    }

    private fun isPotentialDmTouchHookMarker(view: View): Boolean {
        val id = view.id
        if (id != View.NO_ID && id != 0) {
            val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
            if (name == "context_menu" ||
                name == "message_actions_fragment" ||
                name == "message_actions_container" ||
                name.contains("message_actions") ||
                name.contains("context_menu")
            ) {
                return true
            }
        }
        if (view is TextView && actionFromDmCustomLabel(view.text?.toString()) >= 0) return true
        val cls = view.javaClass.name.lowercase(Locale.US)
        return cls.contains("popupdecorview") ||
            cls.contains("contextmenu") ||
            cls.contains("messageactions")
    }

    private fun installDmTouchDispatchHooks(reason: String) {
        synchronized(dmTouchDispatchHookLock) {
            if (dmTouchDispatchHooksInstalled) return
            val viewHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    val started = SystemClock.elapsedRealtimeNanos()
                    try {
                        handleDmViewDispatchTouch(param)
                    } finally {
                        recordFlickPerfNestedHook(started)
                    }
                }
            }
            val groupHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    val started = SystemClock.elapsedRealtimeNanos()
                    try {
                        handleDmViewGroupDispatchTouch(param)
                    } finally {
                        recordFlickPerfNestedHook(started)
                    }
                }
            }
            dmTouchDispatchUnhooks.addAll(XposedBridge.hookAllMethods(View::class.java, "dispatchTouchEvent", viewHook))
            dmTouchDispatchUnhooks.addAll(XposedBridge.hookAllMethods(ViewGroup::class.java, "dispatchTouchEvent", groupHook))
            dmTouchDispatchHooksInstalled = true
        }
        logDmTouchDispatchHookState("installed", reason)
    }

    private fun uninstallDmTouchDispatchHooks(reason: String) {
        val unhooks = synchronized(dmTouchDispatchHookLock) {
            if (!dmTouchDispatchHooksInstalled) return
            dmTouchDispatchHooksInstalled = false
            val copy = dmTouchDispatchUnhooks.toList()
            dmTouchDispatchUnhooks.clear()
            copy
        }
        unhooks.forEach { unhook -> runCatching { unhook.unhook() } }
        logDmTouchDispatchHookState("uninstalled", reason)
    }

    private fun logDmTouchDispatchHookState(action: String, reason: String) {
        val now = SystemClock.uptimeMillis()
        if (now - dmTouchDispatchLastLogAtMs < 700L) return
        dmTouchDispatchLastLogAtMs = now
        logInfo("DM touch dispatch hooks $action reason=$reason")
    }

    private fun handleDmViewDispatchTouch(param: XC_MethodHook.MethodHookParam<*>) {
        val view = param.thisObject as? View ?: return
        val event = param.args.firstOrNull() as? MotionEvent ?: return
        val action = event.actionMasked
        val autoscrollPrevention = isDirectMessageAutoscrollPreventionEnabled()
        if (autoscrollPrevention) {
            when (action) {
                MotionEvent.ACTION_DOWN -> {
                    if (dmDirectSurfaceActive || dmOverlayRootActive || isLikelyDirectTouchPath(view)) {
                        noteDirectComposerTouch(view, event)
                    }
                }
                MotionEvent.ACTION_MOVE -> {
                    if ((dmDirectSurfaceActive || dmOverlayRootActive || hasActiveDirectMessageAutoscrollGuard()) &&
                        shouldRunDirectMessageMoveMaintenance(event)
                    ) {
                        releaseDirectMessageAutoscrollFromTouch(view, event)
                        noteDirectMessageListManualScroll(view)
                    }
                    return
                }
            }
        } else if (action == MotionEvent.ACTION_MOVE) {
            return
        }
        if (action == MotionEvent.ACTION_DOWN && shouldAttemptKeepUnsentTouchCapture(view)) {
            val root = view.rootView ?: view
            rememberKeepUnsentActionRowFromTouchedView(view, event)
            rememberKeepUnsentActionRowFromRawTouchDeferred(root, event, view)
        }
        val current = state
        if (current.enableDmContextMenuOptions &&
            action == MotionEvent.ACTION_DOWN &&
            isLikelyDirectTouchPath(view)
        ) {
            rememberDmOverlayGestureDown(view, event)
        } else if (current.enableDmContextMenuOptions &&
            (action == MotionEvent.ACTION_CANCEL || action == MotionEvent.ACTION_OUTSIDE)
        ) {
            clearDmOverlayGestureDown()
        }
        if (!current.enableDmContextMenuOptions) return
        val cachedDirectSurface = hasCachedDirectTouchSurface()
        val localLikelyDirectPath = action == MotionEvent.ACTION_DOWN && isLikelyDirectTouchPath(view)
        if (!cachedDirectSurface && !localLikelyDirectPath) return
        val activeDmRuntime = cachedDirectSurface && hasActiveDmActionRuntime()
        val likelyDirectTouchPath =
            localLikelyDirectPath ||
                (activeDmRuntime && isLikelyDirectTouchPath(view))
        val mayBeDirectTouch = dmDirectSurfaceActive ||
            dmOverlayRootActive ||
            (action == MotionEvent.ACTION_DOWN &&
                likelyDirectTouchPath &&
                isDirectMessageSurfaceActive())
        if (!mayBeDirectTouch) return
        if (action == MotionEvent.ACTION_DOWN) rememberDmMessageActionTouchCandidate(view, event)
        if (handleDmMessageActionOverlayTouch(view, event)) param.result = true
    }

    private fun handleDmViewGroupDispatchTouch(param: XC_MethodHook.MethodHookParam<*>) {
        if (!state.enableDmContextMenuOptions) return
        val group = param.thisObject as? ViewGroup ?: return
        val event = param.args.firstOrNull() as? MotionEvent ?: return
        val action = event.actionMasked
        if (action == MotionEvent.ACTION_MOVE) return
        if (action == MotionEvent.ACTION_CANCEL || action == MotionEvent.ACTION_OUTSIDE) {
            clearDmOverlayGestureDown()
            return
        }
        val cachedDirectSurface = hasCachedDirectTouchSurface()
        val localLikelyDirectPath = action == MotionEvent.ACTION_DOWN && isLikelyDirectTouchPath(group)
        if (!cachedDirectSurface && !localLikelyDirectPath) return
        val activeDmRuntime = cachedDirectSurface && hasActiveDmActionRuntime()
        val likelyDirectTouchPath =
            localLikelyDirectPath ||
                (activeDmRuntime && isLikelyDirectTouchPath(group))
        if (action == MotionEvent.ACTION_DOWN && likelyDirectTouchPath) rememberDmOverlayGestureDown(group, event)
        val mayBeDirectTouch = dmDirectSurfaceActive ||
            dmOverlayRootActive ||
            (action == MotionEvent.ACTION_DOWN &&
                likelyDirectTouchPath &&
                isDirectMessageSurfaceActive())
        if (!mayBeDirectTouch) return
        if (handleDmMessageActionOverlayTouch(group, event)) param.result = true
    }

    private fun recordFlickPerfNestedHook(startedNanos: Long) {
        if (!ENABLE_FLICK_PERF_DIAGNOSTICS) return
        if (flickPerfDispatchStartNanos.get() <= 0L) return
        val elapsed = (SystemClock.elapsedRealtimeNanos() - startedNanos).coerceAtLeast(0L)
        flickPerfNestedPurrfectNanos.set(flickPerfNestedPurrfectNanos.get() + elapsed)
        flickPerfNestedHookCalls.set((flickPerfNestedHookCalls.get() + 1).coerceAtMost(100_000))
    }

    private fun installDirectMessageBehaviorHooks() {
        val recyclerClass = listOf(
            "androidx.recyclerview.widget.RecyclerView",
            "android.support.v7.widget.RecyclerView"
        ).firstNotNullOfOrNull { className -> runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() }
            ?: return
        runSafe("Direct message RecyclerView behavior hooks") {
            XposedBridge.hookAllMethods(
                recyclerClass,
                "dispatchTouchEvent",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        val event = param.args.firstOrNull() as? MotionEvent ?: return
                        if (isDirectMessageAutoscrollPreventionEnabled() && isDirectMessageListView(view)) {
                            when (event.actionMasked) {
                                MotionEvent.ACTION_DOWN -> noteDirectMessageListUserTouch(view)
                                MotionEvent.ACTION_MOVE -> releaseDirectMessageAutoscrollForManualScroll(view)
                            }
                        }
                    }
                }
            )
            hookRecyclerPositionScroll(recyclerClass, "scrollToPosition")
            hookRecyclerPositionScroll(recyclerClass, "smoothScrollToPosition")
            hookRecyclerDeltaScroll(recyclerClass, "scrollBy")
            hookRecyclerDeltaScroll(recyclerClass, "smoothScrollBy")
            hookRecyclerRequestChildFocus(recyclerClass)
            hookRecyclerRequestChildRectangle(recyclerClass)
            hookRecyclerOnScrolled(recyclerClass)
            hookRecyclerOffsetChildren(recyclerClass)
            hookRecyclerLayoutManagerScrolls("androidx.recyclerview.widget.LinearLayoutManager")
            hookRecyclerLayoutManagerScrolls("android.support.v7.widget.LinearLayoutManager")
            hookRecyclerLayoutManagerScrolls("androidx.recyclerview.widget.StaggeredGridLayoutManager")
            hookRecyclerLayoutManagerScrolls("android.support.v7.widget.StaggeredGridLayoutManager")
        }
    }

    private fun installFlickPerfRecyclerHooks() {
        if (!flickPerfRecyclerHooked.compareAndSet(false, true)) return
        val recyclerClass = listOf(
            "androidx.recyclerview.widget.RecyclerView",
            "android.support.v7.widget.RecyclerView"
        ).firstNotNullOfOrNull { className -> runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() }
            ?: return
        runSafe("Instagram FlickPerf RecyclerView hook") {
            XposedBridge.hookAllMethods(
                recyclerClass,
                "onScrolled",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        val dx = param.args.getOrNull(0) as? Int ?: 0
                        val dy = param.args.getOrNull(1) as? Int ?: 0
                        recordFlickPerfRecyclerScrolled(view, dx, dy)
                    }
                }
            )
            logInfo("Installed Instagram FlickPerf RecyclerView observer")
        }
    }

    private fun installKeepWarmReceiverGuard() {
        if (!keepWarmReceiverGuardHooked.compareAndSet(false, true)) return
        runSafe("Instagram KeepWarmReceiver guard") {
            val cls = runCatching {
                Class.forName("com.instagram.util.startup.appwarmer.KeepWarmReceiver", false, appClassLoader)
                    .asSubclass(BroadcastReceiver::class.java)
            }.getOrNull() ?: return@runSafe
            val onReceive = cls.methods.firstOrNull { method ->
                method.name == "onReceive" &&
                    method.parameterTypes.size == 2 &&
                    Context::class.java.isAssignableFrom(method.parameterTypes[0]) &&
                    Intent::class.java.isAssignableFrom(method.parameterTypes[1])
            } ?: return@runSafe
            XposedBridge.hookMethod(
                onReceive,
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!shouldSuppressKeepWarmReceiverDuringScroll()) return
                        param.result = null
                        logInfoThrottled("keepwarm:suppressed-scroll", 8_000L) {
                            "Suppressed Instagram KeepWarmReceiver during active scroll"
                        }
                    }
                }
            )
            logInfo("Installed Instagram KeepWarmReceiver scroll guard")
        }
    }

    private fun shouldSuppressKeepWarmReceiverDuringScroll(now: Long = SystemClock.uptimeMillis()): Boolean {
        if (now > scrollHotUntilMs()) return false
        if (dmDirectSurfaceActive || dmOverlayRootActive || hasCachedDirectTouchSurface()) return false
        return true
    }

    private fun noteInputScrollBusy(event: MotionEvent) {
        val extensionMs = when (event.actionMasked) {
            MotionEvent.ACTION_MOVE -> 1_100L
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> 900L
            MotionEvent.ACTION_DOWN -> 520L
            else -> return
        }
        val until = SystemClock.uptimeMillis() + extensionMs
        if (until > flickPerfInputBusyUntilMs) flickPerfInputBusyUntilMs = until
        noteActivityHistoryScrollBusy(until)
    }

    private fun rememberFlickPerfDispatchStart(event: MotionEvent) {
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN,
            MotionEvent.ACTION_MOVE,
            MotionEvent.ACTION_UP,
            MotionEvent.ACTION_CANCEL -> {
                val busyUntil = SystemClock.uptimeMillis() + 1_100L
                flickPerfInputBusyUntilMs = busyUntil
                noteActivityHistoryScrollBusy(busyUntil)
                flickPerfDispatchStartNanos.set(SystemClock.elapsedRealtimeNanos())
                flickPerfNestedPurrfectNanos.set(0L)
                flickPerfNestedHookCalls.set(0)
            }
        }
    }

    private fun finishFlickPerfActivityDispatch(activity: Activity, event: MotionEvent, activityResult: Boolean) {
        val action = event.actionMasked
        val startNanos = flickPerfDispatchStartNanos.get()
        flickPerfDispatchStartNanos.set(0L)
        val dispatchMs = if (startNanos > 0L) {
            ((SystemClock.elapsedRealtimeNanos() - startNanos).coerceAtLeast(0L) / 1_000_000f)
        } else {
            0f
        }
        val purrfectBeforeMs = (flickPerfPurrfectBeforeNanos.get().coerceAtLeast(0L) / 1_000_000f)
        flickPerfPurrfectBeforeNanos.set(0L)
        val purrfectNestedMs = (flickPerfNestedPurrfectNanos.get().coerceAtLeast(0L) / 1_000_000f)
        val nestedHookCalls = flickPerfNestedHookCalls.get()
        flickPerfNestedPurrfectNanos.set(0L)
        flickPerfNestedHookCalls.set(0)
        val now = SystemClock.uptimeMillis()
        when (action) {
            MotionEvent.ACTION_DOWN -> {
                flickPerfDownEventMs = event.eventTime
                flickPerfDownWallMs = now
                flickPerfDownX = event.rawX
                flickPerfDownY = event.rawY
                flickPerfUpWallMs = 0L
                flickPerfUpX = -1f
                flickPerfUpY = -1f
                flickPerfDurationMs = 0L
                flickPerfDistanceX = 0f
                flickPerfDistanceY = 0f
                flickPerfEventCount = 1
                flickPerfMaxDispatchMs = dispatchMs
                flickPerfDownDispatchMs = dispatchMs
                flickPerfUpDispatchMs = 0f
                flickPerfMaxPurrfectBeforeMs = purrfectBeforeMs
                flickPerfDownPurrfectBeforeMs = purrfectBeforeMs
                flickPerfUpPurrfectBeforeMs = 0f
                flickPerfMaxPurrfectNestedMs = purrfectNestedMs
                flickPerfDownPurrfectNestedMs = purrfectNestedMs
                flickPerfUpPurrfectNestedMs = 0f
                flickPerfNestedHookCallTotal = nestedHookCalls
                flickPerfActivityClaimedBy = "-"
                flickPerfAwaitScrollUntilMs = 0L
                flickPerfSurfaceAtDown = flickPerfActivitySurfaceHint(activity)
                flickPerfRootRef = activity.window?.decorView?.rootView?.let(::WeakReference)
            }
            MotionEvent.ACTION_MOVE -> {
                if (flickPerfDownWallMs <= 0L) return
                flickPerfEventCount = (flickPerfEventCount + 1).coerceAtMost(10_000)
                if (dispatchMs > flickPerfMaxDispatchMs) flickPerfMaxDispatchMs = dispatchMs
                if (purrfectBeforeMs > flickPerfMaxPurrfectBeforeMs) flickPerfMaxPurrfectBeforeMs = purrfectBeforeMs
                if (purrfectNestedMs > flickPerfMaxPurrfectNestedMs) flickPerfMaxPurrfectNestedMs = purrfectNestedMs
                flickPerfNestedHookCallTotal = (flickPerfNestedHookCallTotal + nestedHookCalls).coerceAtMost(100_000)
            }
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                if (flickPerfDownWallMs <= 0L) return
                flickPerfEventCount = (flickPerfEventCount + 1).coerceAtMost(10_000)
                if (dispatchMs > flickPerfMaxDispatchMs) flickPerfMaxDispatchMs = dispatchMs
                if (purrfectBeforeMs > flickPerfMaxPurrfectBeforeMs) flickPerfMaxPurrfectBeforeMs = purrfectBeforeMs
                if (purrfectNestedMs > flickPerfMaxPurrfectNestedMs) flickPerfMaxPurrfectNestedMs = purrfectNestedMs
                flickPerfNestedHookCallTotal = (flickPerfNestedHookCallTotal + nestedHookCalls).coerceAtMost(100_000)
                flickPerfUpDispatchMs = dispatchMs
                flickPerfUpPurrfectBeforeMs = purrfectBeforeMs
                flickPerfUpPurrfectNestedMs = purrfectNestedMs
                flickPerfUpWallMs = now
                flickPerfUpX = event.rawX
                flickPerfUpY = event.rawY
                flickPerfDistanceX = event.rawX - flickPerfDownX
                flickPerfDistanceY = event.rawY - flickPerfDownY
                flickPerfDurationMs = (event.eventTime - flickPerfDownEventMs).takeIf { it >= 0L }
                    ?: (now - flickPerfDownWallMs).coerceAtLeast(0L)
                if (action == MotionEvent.ACTION_UP && isMeasuredShortVerticalFlick()) {
                    val generation = flickPerfGeneration + 1
                    flickPerfGeneration = generation
                    flickPerfScrollLoggedGeneration = 0L
                    flickPerfAwaitScrollUntilMs = now + 1_250L
                    val velocityY = abs(flickPerfDistanceY) / flickPerfDurationMs.coerceAtLeast(1L).toFloat()
                    if (shouldEmitFlickPerfDetail(now)) {
                        logInfo(
                            "FlickPerf short-flick gen=$generation surface=$flickPerfSurfaceAtDown " +
                                "duration=${flickPerfDurationMs}ms dx=${flickPerfDistanceX.toInt()} dy=${flickPerfDistanceY.toInt()} " +
                                "velocityY=${formatFlickMs(velocityY)}px/ms events=$flickPerfEventCount dispatchDown=${formatFlickMs(flickPerfDownDispatchMs)}ms " +
                                "dispatchUp=${formatFlickMs(flickPerfUpDispatchMs)}ms dispatchMax=${formatFlickMs(flickPerfMaxDispatchMs)}ms " +
                                "purrfectBeforeDown=${formatFlickMs(flickPerfDownPurrfectBeforeMs)}ms " +
                                "purrfectBeforeUp=${formatFlickMs(flickPerfUpPurrfectBeforeMs)}ms " +
                                "purrfectBeforeMax=${formatFlickMs(flickPerfMaxPurrfectBeforeMs)}ms " +
                                "purrfectNestedDown=${formatFlickMs(flickPerfDownPurrfectNestedMs)}ms " +
                                "purrfectNestedUp=${formatFlickMs(flickPerfUpPurrfectNestedMs)}ms " +
                                "purrfectNestedMax=${formatFlickMs(flickPerfMaxPurrfectNestedMs)}ms " +
                                "nestedCalls=$flickPerfNestedHookCallTotal dmTouchHooks=$dmTouchDispatchHooksInstalled " +
                                "activityResult=$activityResult claimedBy=$flickPerfActivityClaimedBy " +
                                "keepUnsent=${state.keepUnsentMessages} dmContext=${state.enableDmContextMenuOptions}"
                        )
                        if (shouldRunFlickPerfFrameSampler()) startFlickPerfFrameSampler(generation)
                        mainHandler.postDelayed({
                            if (flickPerfGeneration == generation &&
                                flickPerfScrollLoggedGeneration != generation &&
                                SystemClock.uptimeMillis() <= flickPerfAwaitScrollUntilMs + 80L
                            ) {
                                flickPerfScrollLoggedGeneration = generation
                                logInfo(
                                    "FlickPerf no-observer-scroll gen=$generation surface=$flickPerfSurfaceAtDown " +
                                        "after=${SystemClock.uptimeMillis() - flickPerfUpWallMs}ms " +
                                        "duration=${flickPerfDurationMs}ms dy=${flickPerfDistanceY.toInt()} " +
                                        "dispatchMax=${formatFlickMs(flickPerfMaxDispatchMs)}ms " +
                                        "purrfectBeforeMax=${formatFlickMs(flickPerfMaxPurrfectBeforeMs)}ms " +
                                        "purrfectNestedMax=${formatFlickMs(flickPerfMaxPurrfectNestedMs)}ms " +
                                        "nestedCalls=$flickPerfNestedHookCallTotal keepUnsent=${state.keepUnsentMessages}"
                                )
                            }
                        }, 700L)
                    } else {
                        flickPerfScrollLoggedGeneration = generation
                        flickPerfAwaitScrollUntilMs = 0L
                    }
                }
            }
        }
    }

    private fun isMeasuredShortVerticalFlick(): Boolean {
        val absDx = abs(flickPerfDistanceX)
        val absDy = abs(flickPerfDistanceY)
        return flickPerfDurationMs in 20L..360L &&
            absDy >= 160f &&
            absDy >= absDx * 1.25f
    }

    private fun startFlickPerfFrameSampler(generation: Long) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            mainHandler.post { startFlickPerfFrameSampler(generation) }
            return
        }
        val until = SystemClock.uptimeMillis() + 900L
        flickPerfFrameGeneration = generation
        flickPerfFrameUntilMs = until
        flickPerfFrameLastNanos = 0L
        flickPerfFrameSamples = 0
        flickPerfFrameJank17 = 0
        flickPerfFrameJank33 = 0
        flickPerfFrameJank50 = 0
        flickPerfFrameMaxMs = 0f
        runCatching {
            Choreographer.getInstance().postFrameCallback(object : Choreographer.FrameCallback {
                override fun doFrame(frameTimeNanos: Long) {
                    if (flickPerfFrameGeneration != generation) return
                    val last = flickPerfFrameLastNanos
                    if (last > 0L && frameTimeNanos > last) {
                        val frameMs = (frameTimeNanos - last) / 1_000_000f
                        flickPerfFrameSamples = (flickPerfFrameSamples + 1).coerceAtMost(10_000)
                        if (frameMs > 17f) flickPerfFrameJank17++
                        if (frameMs > 33f) flickPerfFrameJank33++
                        if (frameMs > 50f) flickPerfFrameJank50++
                        if (frameMs > flickPerfFrameMaxMs) flickPerfFrameMaxMs = frameMs
                    }
                    flickPerfFrameLastNanos = frameTimeNanos
                    if (SystemClock.uptimeMillis() < flickPerfFrameUntilMs) {
                        Choreographer.getInstance().postFrameCallback(this)
                    } else {
                        logInfo(
                            "FlickPerf frames gen=$generation surface=$flickPerfSurfaceAtDown " +
                                "samples=$flickPerfFrameSamples jank17=$flickPerfFrameJank17 " +
                                "jank33=$flickPerfFrameJank33 jank50=$flickPerfFrameJank50 " +
                                "maxFrame=${formatFlickMs(flickPerfFrameMaxMs)}ms " +
                                "dispatchMax=${formatFlickMs(flickPerfMaxDispatchMs)}ms " +
                                "purrfectNestedMax=${formatFlickMs(flickPerfMaxPurrfectNestedMs)}ms " +
                                "keepUnsent=${state.keepUnsentMessages}"
                        )
                    }
                }
            })
        }.onFailure { throwable -> logError("Failed starting FlickPerf frame sampler", throwable) }
    }

    private fun shouldRunFlickPerfFrameSampler(): Boolean = ENABLE_FLICK_PERF_DIAGNOSTICS

    private fun recordFlickPerfRecyclerScrolled(view: View, dx: Int, dy: Int) {
        if (dx == 0 && dy == 0) return
        noteInstagramScrollBusy(dx, dy)
        if (!ENABLE_FLICK_PERF_DIAGNOSTICS) return
        val now = SystemClock.uptimeMillis()
        val until = flickPerfAwaitScrollUntilMs
        if (until <= 0L || now > until) return
        val generation = flickPerfGeneration
        if (generation <= 0L || flickPerfScrollLoggedGeneration == generation) return
        val root = flickPerfRootRef?.get()
        if (root != null && view.rootView !== root) return
        flickPerfScrollLoggedGeneration = generation
        flickPerfAwaitScrollUntilMs = 0L
        val offset = runCatching {
            view.javaClass.methods.firstOrNull { method ->
                method.name == "computeVerticalScrollOffset" && method.parameterTypes.isEmpty()
            }?.invoke(view) as? Int
        }.getOrNull() ?: -1
        logInfo(
            "FlickPerf first-scroll gen=$generation surface=${flickPerfScrollableSurfaceHint(view)} " +
            "age=${now - flickPerfUpWallMs}ms dx=$dx dy=$dy offset=$offset " +
            "flickDy=${flickPerfDistanceY.toInt()} duration=${flickPerfDurationMs}ms events=$flickPerfEventCount " +
            "dispatchMax=${formatFlickMs(flickPerfMaxDispatchMs)}ms " +
            "purrfectBeforeMax=${formatFlickMs(flickPerfMaxPurrfectBeforeMs)}ms " +
            "purrfectNestedMax=${formatFlickMs(flickPerfMaxPurrfectNestedMs)}ms " +
            "nestedCalls=$flickPerfNestedHookCallTotal recycler=${describeViewBrief(view)}"
        )
    }

    private fun noteInstagramScrollBusy(dx: Int, dy: Int) {
        val now = SystemClock.uptimeMillis()
        val distance = abs(dx) + abs(dy)
        val extensionMs = when {
            distance >= 72 -> 1_000L
            distance >= 16 -> 750L
            else -> 520L
        }
        val until = now + extensionMs
        if (until > instagramScrollBusyUntilMs) instagramScrollBusyUntilMs = until
        noteActivityHistoryScrollBusy(until)
    }

    private fun noteActivityHistoryScrollBusy(untilMs: Long) {
        if (state.enableActivityHistory) InstagramActivityHistoryHooks.noteScrollBusyUntil(untilMs)
    }

    private fun scrollHotUntilMs(): Long = maxOf(flickPerfInputBusyUntilMs, instagramScrollBusyUntilMs)

    private fun isInstagramScrollHot(now: Long = SystemClock.uptimeMillis()): Boolean =
        now <= scrollHotUntilMs()

    private fun shouldDeferScrollSensitiveWork(now: Long = SystemClock.uptimeMillis()): Boolean {
        if (!isInstagramScrollHot(now)) return false
        return true
    }

    private fun shouldBypassGlobalViewHookForScroll(view: View?): Boolean {
        if (!isInstagramScrollHot()) return false
        if (view != null && hasCachedDirectTouchSurface() && hasLocalDirectTouchHint(view)) return false
        return true
    }

    private fun shouldDeferGenericMediaCaptureForScroll(now: Long = SystemClock.uptimeMillis()): Boolean {
        val until = scrollHotUntilMs()
        return until > 0L && now <= until + 5_000L
    }

    private fun shouldEmitFlickPerfDetail(now: Long): Boolean {
        if (flickPerfMaxPurrfectBeforeMs > 1.25f ||
            flickPerfMaxPurrfectNestedMs > 0.75f ||
            flickPerfNestedHookCallTotal > 0
        ) {
            flickPerfLastLogAtMs = now
            return true
        }
        if (now - flickPerfLastLogAtMs < 2_500L) return false
        flickPerfLastLogAtMs = now
        return true
    }

    private fun noteScrollDeferredWork(view: View?, kind: String, reason: String) {
        val now = SystemClock.uptimeMillis()
        incrementScrollDeferredWork(kind)
        if (ENABLE_FLICK_PERF_DIAGNOSTICS && now - scrollDeferredLastLogAtMs >= 8_000L) {
            scrollDeferredLastLogAtMs = now
            logInfo(
                "ScrollHot deferred work views=$scrollDeferredProcessViews text=$scrollDeferredTextViews " +
                    "media=$scrollDeferredMediaUrls remainingMs=${(scrollHotUntilMs() - now).coerceAtLeast(0L)} reason=$reason"
            )
        }
        if (kind != "media" && shouldScheduleScrollIdleCatchUp()) {
            scheduleScrollIdleProcessPass(view, reason, now)
        }
    }

    private fun incrementScrollDeferredWork(kind: String) {
        when (kind) {
            "text" -> if (scrollDeferredTextViews < 1_000_000) scrollDeferredTextViews++
            "media" -> if (scrollDeferredMediaUrls < 1_000_000) scrollDeferredMediaUrls++
            else -> if (scrollDeferredProcessViews < 1_000_000) scrollDeferredProcessViews++
        }
    }

    private fun shouldScheduleScrollIdleCatchUp(): Boolean {
        val current = state
        if (needsRootScan(current)) return true
        if (!current.isGhostSeen && !current.enableDmAnyFileUpload) return false
        return dmDirectSurfaceActive || dmOverlayRootActive || hasCachedDirectTouchSurface()
    }

    private fun scheduleScrollIdleProcessPass(view: View?, reason: String, now: Long = SystemClock.uptimeMillis()) {
        val root = view?.rootView ?: view ?: currentActivity?.window?.decorView ?: return
        val targetUntil = scrollHotUntilMs() + 140L
        if (targetUntil <= now) return
        if (now - scrollIdleScanLastScheduleAtMs < 260L && scrollIdleScanScheduledUntilMs > 0L) return
        scrollIdleScanLastScheduleAtMs = now
        if (scrollIdleScanScheduledUntilMs >= targetUntil - 80L) return
        scrollIdleScanScheduledUntilMs = targetUntil
        val delay = (targetUntil - now).coerceIn(220L, 1_500L)
        mainHandler.postDelayed({
            scrollIdleScanScheduledUntilMs = 0L
            val runAt = SystemClock.uptimeMillis()
            if (runAt <= scrollHotUntilMs()) {
                scheduleScrollIdleProcessPass(root, "reschedule:$reason")
                return@postDelayed
            }
            if (!root.isAttachedToWindow) return@postDelayed
            scanTree(root, "scroll-idle:$reason", 260)
        }, delay)
    }

    private fun flickPerfActivitySurfaceHint(activity: Activity): String {
        if (hasCachedDirectTouchSurface()) return "direct-cached"
        val name = activity.javaClass.name.substringAfterLast('.').lowercase(Locale.US)
        return when {
            name.contains("reel") || name.contains("clips") -> "reels-activity"
            name.contains("direct") -> "direct-activity"
            name.contains("modal") -> "modal-activity"
            else -> name.ifBlank { "activity" }
        }
    }

    private fun flickPerfScrollableSurfaceHint(view: View): String {
        val haystack = buildString {
            var current: View? = view
            repeat(8) {
                val node = current ?: return@repeat
                append(' ').append(resourceEntryName(node).orEmpty())
                append(' ').append(node.javaClass.name)
                current = node.parent as? View
            }
        }.lowercase(Locale.US)
        return when {
            haystack.contains("direct") || haystack.contains("message_list") || haystack.contains("thread") -> "direct"
            haystack.contains("clips") || haystack.contains("reel") -> "reels"
            haystack.contains("feed") || haystack.contains("timeline") -> "feed"
            else -> "scroll"
        }
    }

    private fun formatFlickMs(value: Float): String =
        String.format(Locale.US, "%.2f", value)

    private fun installKeepUnsentRecyclerViewHooks() {
        if (!keepUnsentRecyclerHooksInstalled.compareAndSet(false, true)) return
        val recyclerClass = listOf(
            "androidx.recyclerview.widget.RecyclerView",
            "android.support.v7.widget.RecyclerView"
        ).firstNotNullOfOrNull { className -> runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() }
            ?: return
        hookRecyclerAdapterBindViewHolder(recyclerClass)
    }

    private fun hookRecyclerPositionScroll(recyclerClass: Class<*>, methodName: String) {
        runCatching {
            XposedBridge.hookAllMethods(
                recyclerClass,
                methodName,
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        val position = param.args.firstOrNull() as? Int ?: return
                        if (shouldBlockDirectMessageAutoscroll(view, position)) param.result = null
                    }
                }
            )
        }
    }

