                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            val recycler = recyclerViewFromLayoutManager(param.thisObject) ?: return
                            val position = param.args.firstOrNull { it is Int } as? Int ?: return
                            if (shouldBlockDirectMessageAutoscroll(recycler, position)) param.result = null
                        }
                    }
                )
            }
        }
        listOf("scrollVerticallyBy", "scrollHorizontallyBy").forEach { methodName ->
            runCatching {
                XposedBridge.hookAllMethods(
                    cls,
                    methodName,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            val recycler = recyclerViewFromLayoutManager(param.thisObject) ?: return
                            if (shouldBlockDirectMessageAutoscroll(recycler, null)) param.result = 0
                        }
                    }
                )
            }
        }
    }

    private fun installSponsoredRecyclerHook() {
        if (!sponsoredRecyclerHooked.compareAndSet(false, true)) return
        runSafe("Sponsored RecyclerView rows") {
            val adapterClass = listOf(
                "androidx.recyclerview.widget.RecyclerView\$Adapter",
                "android.support.v7.widget.RecyclerView\$Adapter"
            ).firstNotNullOfOrNull { className -> runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() }
                ?: return@runSafe
            XposedBridge.hookAllMethods(
                adapterClass,
                "bindViewHolder",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.isAdBlockEnabled || param.args.isEmpty()) return
                        val itemView = getViewHolderItemView(param.args[0]) ?: return
                        if (itemView.rootView == itemView || sponsoredHiddenViews.contains(itemView)) return
                        if (shouldBypassGlobalViewHookForScroll(itemView) || shouldDeferScrollSensitiveWork()) {
                            deferSponsoredBindCheck(itemView)
                            return
                        }
                        if (hasDirectSponsoredSignal(itemView)) hideSponsoredContainer(itemView)
                    }
                }
            )
        }
    }

    private fun deferSponsoredBindCheck(itemView: View) {
        if (!state.isAdBlockEnabled) return
        if (sponsoredDeferredBindScheduled.get()) return
        sponsoredDeferredBindViews.add(itemView)
        scheduleDeferredSponsoredBindCheck()
    }

    private fun scheduleDeferredSponsoredBindCheck() {
        if (!sponsoredDeferredBindScheduled.compareAndSet(false, true)) return
        val now = SystemClock.uptimeMillis()
        val delay = (scrollHotUntilMs() + 140L - now).coerceIn(180L, 1_500L)
        mainHandler.postDelayed({
            sponsoredDeferredBindScheduled.set(false)
            if (!state.isAdBlockEnabled) {
                sponsoredDeferredBindViews.clear()
                return@postDelayed
            }
            if (shouldDeferScrollSensitiveWork()) {
                scheduleDeferredSponsoredBindCheck()
                return@postDelayed
            }
            val views = synchronized(sponsoredDeferredBindViews) {
                sponsoredDeferredBindViews.toList().also { sponsoredDeferredBindViews.clear() }
            }
            views.forEach { view ->
                if (!view.isAttachedToWindow || sponsoredHiddenViews.contains(view)) return@forEach
                if (hasDirectSponsoredSignal(view)) hideSponsoredContainer(view)
            }
            if (sponsoredDeferredBindViews.isNotEmpty()) scheduleDeferredSponsoredBindCheck()
        }, delay)
    }

    private fun installTextHooks() {
        if (!textHooksInstalled.compareAndSet(false, true)) return
        runSafe("TextView hooks") {
            XposedBridge.hookAllMethods(
                TextView::class.java,
                "setText",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val textView = param.thisObject as? TextView ?: return
                        val current = state
                        val renderedText = param.args.firstOrNull() as? CharSequence ?: textView.text
                        if (current.localInstagramPlus &&
                            maybeHideLocalInstagramPlusStoryPeekUpsellTextFast(
                                textView,
                                renderedText,
                                textView.contentDescription
                            )
                        ) {
                            return
                        }
                        if (shouldBypassGlobalViewHookForScroll(textView)) return
                        if (shouldDeferScrollSensitiveWork()) {
                            incrementScrollDeferredWork("text")
                            return
                        }
                        processTextViewFastOrBroad(
                            textView,
                            current,
                            renderedText,
                            textView.contentDescription,
                            isStoryViewerSurfaceFast(textView)
                        )
                    }
                }
            )
            XposedBridge.hookAllMethods(
                View::class.java,
                "setContentDescription",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val view = param.thisObject as? View ?: return
                        val current = state
                        val textView = view as? TextView
                        if (textView != null &&
                            current.localInstagramPlus &&
                            maybeHideLocalInstagramPlusStoryPeekUpsellTextFast(
                                textView,
                                textView.text,
                                param.args.firstOrNull() as? CharSequence
                            )
                        ) {
                            return
                        }
                        if (shouldBypassGlobalViewHookForScroll(view)) return
                        if (shouldDeferScrollSensitiveWork()) {
                            incrementScrollDeferredWork("text")
                            return
                        }
                        if (current.doNotSaveRecentSearches) clearVisibleRecentSearchRowIfNeeded(view)
                        textView ?: return
                        processTextViewFastOrBroad(
                            textView,
                            current,
                            textView.text,
                            param.args.firstOrNull() as? CharSequence,
                            isStoryViewerSurfaceFast(textView)
                        )
                    }
                }
            )
        }
    }

    private fun installStaticLayoutDateFormatHooks() {
        if (!staticLayoutDateHooksInstalled.compareAndSet(false, true)) return
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return
        runSafe("StaticLayout comment date hooks") {
            val layoutHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    rewriteCommentDateLayoutArgs(param.args)
                }
            }
            XposedBridge.hookAllMethods(
                StaticLayout.Builder::class.java,
                "obtain",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableCustomDateFormat || !state.customDateFormatComments) return
                        if (param.args.size < 5) return
                        val source = param.args.getOrNull(0) as? CharSequence ?: return
                        val start = param.args.getOrNull(1) as? Int ?: return
                        val end = param.args.getOrNull(2) as? Int ?: return
                        val paint = param.args.getOrNull(3) as? TextPaint ?: return
                        val width = param.args.getOrNull(4) as? Int
                        val replacement = rewriteStaticLayoutCommentDateText(source, start, end, paint, width) ?: return
                        val fittedPaint = fittedCommentDatePaint(paint, replacement, width)
                        param.args[0] = replacement
                        param.args[1] = 0
                        param.args[2] = replacement.length
                        param.args[3] = fittedPaint
                        if (width != null && fittedPaint === paint) {
                            param.args[4] = commentDateLayoutWidth(width, paint, replacement)
                        }
                    }
                }
            )
            XposedBridge.hookAllConstructors(StaticLayout::class.java, layoutHook)
            XposedBridge.hookAllMethods(BoringLayout::class.java, "make", layoutHook)
        }
    }

    private fun rewriteCommentDateLayoutArgs(args: Array<Any?>?) {
        if (!state.enableCustomDateFormat || !state.customDateFormatComments) return
        val actualArgs = args ?: return
        val textIndex = actualArgs.indexOfFirst { it is CharSequence }
        if (textIndex < 0) return
        val paintIndex = actualArgs.indexOfFirst { it is TextPaint }
        if (paintIndex < 0) return
        val paint = actualArgs[paintIndex] as? TextPaint ?: return
        val source = actualArgs[textIndex] as? CharSequence ?: return
        var start = 0
        var end = source.length
        var startIndex = -1
        var endIndex = -1
        if (textIndex + 2 < actualArgs.size && actualArgs[textIndex + 1] is Int && actualArgs[textIndex + 2] is Int) {
            startIndex = textIndex + 1
            endIndex = textIndex + 2
            start = actualArgs[startIndex] as Int
            end = actualArgs[endIndex] as Int
        }
        val widthIndex = ((paintIndex + 1) until actualArgs.size).firstOrNull { actualArgs[it] is Int }
        val width = widthIndex?.let { actualArgs[it] as? Int }
        val replacement = rewriteStaticLayoutCommentDateText(source, start, end, paint, width) ?: return
        val fittedPaint = fittedCommentDatePaint(paint, replacement, width)
        actualArgs[textIndex] = replacement
        actualArgs[paintIndex] = fittedPaint
        if (startIndex >= 0 && endIndex >= 0) {
            actualArgs[startIndex] = 0
            actualArgs[endIndex] = replacement.length
        }
        if (widthIndex != null && width != null && fittedPaint === paint) {
            actualArgs[widthIndex] = commentDateLayoutWidth(width, paint, replacement)
        }
    }

    private fun commentDateLayoutWidth(current: Int, paint: TextPaint, text: String): Int {
        if (current <= 0) return current
        val measured = (paint.measureText(text) + paint.textSize.coerceAtLeast(16f) * 0.7f).roundToInt()
        return maxOf(current, measured.coerceAtLeast(1))
    }

    private fun fittedCommentDatePaint(paint: TextPaint, text: String, availableWidth: Int?): TextPaint {
        val width = availableWidth?.takeIf { it > 4 }?.toFloat() ?: return paint
        val measured = paint.measureText(text)
        if (measured <= 0f || measured <= width) return paint
        val scale = ((width - 1f) / measured).coerceIn(0.32f, 1f)
        if (scale >= 0.98f) return paint
        return TextPaint(paint).apply { textScaleX = paint.textScaleX * scale }
    }

    private fun rewriteStaticLayoutCommentDateText(
        source: CharSequence,
        start: Int,
        end: Int,
        paint: TextPaint? = null,
        availableWidth: Int? = null
    ): String? {
        val safeStart = start.coerceIn(0, source.length)
        val safeEnd = end.coerceIn(safeStart, source.length)
        val length = safeEnd - safeStart
        if (length <= 0 || length > 96) return null

        var hasDigit = false
        var hasLetter = false
        var markerCandidate = false
        for (index in safeStart until safeEnd) {
            val ch = source[index]
            when (ch) {
                '\n', '\r' -> return null
                'c', 'C', 'j', 'J', 'w', 'W', 'v', 'V', 'h', 'H', 'r', 'R', 'a', 'A' -> markerCandidate = true
            }
            if (ch.isDigit()) hasDigit = true
            if (ch.isLetter()) hasLetter = true
        }

        val now = SystemClock.uptimeMillis()
        if (!hasDigit) {
            if (length <= 64 && markerCandidate) {
                val clean = cleanInstagramDateText(source.subSequence(safeStart, safeEnd).toString())
                if (isCommentDateSurfaceMarker(clean) ||
                    (now <= commentDateSurfaceActiveUntilMs && isCommentDateSurfaceExtensionMarker(clean))
                ) {
                    commentDateSurfaceActiveUntilMs = now + 30_000L
                }
            }
            return null
        }
        if (!hasLetter) return null

        val clean = cleanInstagramDateText(source.subSequence(safeStart, safeEnd).toString())
        if (clean.isEmpty() || clean.length > 64 || formattedDateLikePattern.matches(clean)) return null
        if (isCommentDateSurfaceMarker(clean)) {
            commentDateSurfaceActiveUntilMs = now + 30_000L
            return null
        }
        if (now > commentDateSurfaceActiveUntilMs) return null
        if (!looksLikeInstagramDate(clean)) return null
        val date = parseInstagramDate(clean) ?: return null
        return formatCommentInlineDate(date, paint, availableWidth)
    }

    private val commentInlineDateFormatter = object : ThreadLocal<SimpleDateFormat>() {
        override fun initialValue(): SimpleDateFormat = SimpleDateFormat("M/d HH:mm", Locale.getDefault())
    }

    private val compactCommentInlineDateFormatter = object : ThreadLocal<SimpleDateFormat>() {
        override fun initialValue(): SimpleDateFormat = SimpleDateFormat("HH:mm", Locale.getDefault())
    }

    private fun formatCommentInlineDate(date: Date, paint: TextPaint?, availableWidth: Int?): String {
        val formatted = formatCustomInstagramDate(date)
        val activePaint = paint ?: return formatted
        val dateTime = runCatching { commentInlineDateFormatter.get().format(date) }.getOrDefault(formatted)
        val compact = runCatching { compactCommentInlineDateFormatter.get().format(date) }.getOrDefault(dateTime)
        val width = availableWidth?.takeIf { it > 0 }?.toFloat()
        if (width != null) {
            val slack = activePaint.textSize.coerceAtLeast(16f) * 0.75f
            if (activePaint.measureText(formatted) <= width + slack) return formatted
            if (activePaint.measureText(dateTime) <= width + slack) return dateTime
            return compact
        }
        val maxInlineWidth = activePaint.textSize.coerceAtLeast(16f) * 5.5f
        if (activePaint.measureText(formatted) <= maxInlineWidth) return formatted
        return dateTime
    }

    private fun isCommentDateSurfaceMarker(raw: String): Boolean {
        val lower = raw.lowercase(Locale.US)
        return lower == "comments" ||
            lower == "comment" ||
            lower == "view comments" ||
            (lower.contains("comments") && (lower.startsWith("view") || lower.startsWith("all") || lower.startsWith("hide"))) ||
            lower.contains("join the conversation") ||
            lower.contains("add a comment") ||
            lower.contains("what do you think") ||
            lower.contains("reply") ||
            lower.startsWith("view replies") ||
            lower.startsWith("view reply")
    }

    private fun isCommentDateSurfaceByView(view: View): Boolean {
        var current: View? = view
        var depth = 0
        while (current != null && depth < 8) {
            val entryName = resourceEntryName(current)
            if (entryName != null) {
                val lower = entryName.lowercase(Locale.US)
                if (lower.contains("comment") || lower.contains("_ufi_") || lower.contains("row_feed_comment")) return true
            }
            val className = current.javaClass.name.lowercase(Locale.US)
            if (className.contains("comment") && !className.contains("comment_")) return true
            current = current.parent as? View
            depth++
        }
        return false
    }

    private fun isCommentDateSurfaceContextActive(): Boolean {
        return SystemClock.uptimeMillis() <= commentDateSurfaceActiveUntilMs
    }

    private fun isCommentDateSurfaceExtensionMarker(raw: String): Boolean {
        val lower = raw.lowercase(Locale.US)
        return lower == "reply" ||
            lower.startsWith("view replies") ||
            lower.startsWith("view reply") ||
            lower.startsWith("hide replies") ||
            lower.startsWith("hide reply")
    }

    private fun installMenuInjectionHooks() {
        if (!menuInjectionHooksInstalled.compareAndSet(false, true)) return
        runSafe("Instagram menu item injection hooks") {
            XposedBridge.hookAllMethods(
                AlertDialog.Builder::class.java,
                "setItems",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (param.args.size < 2) return
                        val labels = param.args[0] as? Array<*> ?: return
                        val listener = param.args[1] as? DialogInterface.OnClickListener ?: return
                        maybeAppendStoryTrayItems(labels, listener)?.let { replacement ->
                            param.args[0] = replacement.first
                            param.args[1] = replacement.second
                        }
                    }
                }
            )
        }
    }

    private fun maybeAppendStoryTrayItems(
        labels: Array<*>,
        original: DialogInterface.OnClickListener
    ): Pair<Array<CharSequence>, DialogInterface.OnClickListener>? {
        val pending = validPendingStoryTrayMenu() ?: return null
        val originalLabels = labels.mapNotNull { it as? CharSequence }
        if (originalLabels.size != labels.size) return null
        if (originalLabels.any { it.toString().contains("profile picture", ignoreCase = true) || it.toString().contains("cover photo", ignoreCase = true) }) return null
        val extraLabels = mutableListOf<CharSequence>()
        val extraUrls = mutableListOf<String>()
        pending.media.profileUrl?.let {
            extraLabels += "View profile picture"
            extraUrls += it
        }
        pending.media.coverUrl?.let {
            extraLabels += "View cover photo"
            extraUrls += it
        }
        if (extraLabels.isEmpty()) return null
        val merged = (originalLabels + extraLabels).toTypedArray()
        val listener = DialogInterface.OnClickListener { dialog, which ->
            if (which < originalLabels.size) {
                original.onClick(dialog, which)
                return@OnClickListener
            }
            val index = (which - originalLabels.size).coerceIn(extraUrls.indices)
            showImagePreview(pending.activity, extraLabels[index].toString(), extraUrls[index])
        }
        logInfo("Injected Story tray actions into Instagram menu extra=${extraLabels.size}")
        pendingStoryTrayMenu = null
        return merged to listener
    }

    private fun maybeInjectStoryTrayActionsIntoNativeMenu(view: View) {
        val pending = validPendingStoryTrayMenu() ?: return
        val container = findInstagramNativeActionMenuContainer(view) ?: return
        if (!nativeMenuLooksLikeStoryTrayMenu(container)) return
        if (!storyTrayInjectedMenuContainers.add(container)) return
        val rows = buildList<Pair<String, String>> {
            pending.media.profileUrl?.let { add("View profile picture" to it) }
            pending.media.coverUrl?.let { add("View cover photo" to it) }
        }
        if (rows.isEmpty() || containsStoryTrayInjectedLabels(container)) return
        val context = container.context
        if (container.childCount > 0) {
            container.addView(View(context).apply {
                setBackgroundColor(Color.argb(45, 255, 255, 255))
            }, ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(1)))
        }
        rows.forEach { (label, url) ->
            container.addView(TextView(context).apply {
                text = label
                setTextColor(Color.WHITE)
                textSize = 16f
                gravity = Gravity.CENTER_VERTICAL
                minHeight = dp(52)
                setPadding(dp(24), 0, dp(24), 0)
                isClickable = true
                setOnClickListener { showImagePreview(pending.activity, label, url) }
            }, ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(56)))
        }
        container.requestLayout()
        (container.parent as? View)?.requestLayout()
        logInfo("Injected Story tray actions into native Instagram menu rows=${rows.size}")
        pendingStoryTrayMenu = null
    }

    private fun scheduleNativeMenuInjection(root: View?) {
        root ?: return
        longArrayOf(80L, 220L, 420L, 900L, 1_450L, 1_900L).forEach { delay ->
            mainHandler.postDelayed({
                if (state.enableStoryTrayLongPressActions) findNativeMenuContainers(root) { maybeInjectStoryTrayActionsIntoNativeMenu(it) }
            }, delay)
        }
    }

    private fun validPendingStoryTrayMenu(): PendingStoryTrayMenu? {
        val pending = pendingStoryTrayMenu ?: return null
        if (System.currentTimeMillis() - pending.createdAtMs < 4_000L) return pending
        pendingStoryTrayMenu = null
        return null
    }

    private fun findInstagramNativeActionMenuContainer(view: View): ViewGroup? {
        var current: View? = view
        repeat(6) {
            val group = current as? ViewGroup ?: return@repeat
            val name = resourceEntryName(group).orEmpty().lowercase(Locale.US)
            val className = group.javaClass.name.lowercase(Locale.US)
            if ((name.contains("bottom_sheet") || name.contains("context") || name.contains("menu") ||
                    name.contains("action_sheet") || name == "recycler_view" ||
                    (name.contains("sheet") && nativeMenuHasActionRows(group)) ||
                    className.contains("bottomsheet") || className.contains("contextmenu")) &&
                group.childCount in 1..24
            ) {
                return nativeMenuInjectionParent(group)
            }
            current = group.parent as? View
        }
        return null
    }

    private fun findNativeMenuContainers(root: View, onContainer: (View) -> Unit) {
        var visited = 0
        fun visit(view: View, depth: Int) {
            if (depth > 12 || visited++ > 420) return
            val group = view as? ViewGroup ?: return
            val name = resourceEntryName(group).orEmpty().lowercase(Locale.US)
            if (name.contains("action_sheet") || name.contains("bottom_sheet") ||
                name.contains("context_menu") || name == "recycler_view"
            ) {
                onContainer(group)
            }
            for (i in 0 until group.childCount) visit(group.getChildAt(i), depth + 1)
        }
        visit(root, 0)
    }

    private fun nativeMenuInjectionParent(group: ViewGroup): ViewGroup? {
        val parent = group.parent as? ViewGroup
        val parentName = parent?.let { resourceEntryName(it) }.orEmpty().lowercase(Locale.US)
        return when {
            group is LinearLayout -> group
            parent is LinearLayout && parentName.contains("action_sheet") -> parent
            parent is LinearLayout && nativeMenuHasActionRows(group) -> parent
            else -> null
        }
    }

    private fun nativeMenuHasActionRows(root: ViewGroup): Boolean {
        fun scan(view: View, depth: Int): Boolean {
            if (depth > 4) return false
            if (view is TextView) {
                val text = view.text?.toString()?.lowercase(Locale.US).orEmpty()
                if (text.contains("view profile") || text.contains("mute") ||
                    text.contains("report") || text.contains("block") ||
                    text.contains("creator") || text.contains("hide suggestion")
                ) return true
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) if (scan(view.getChildAt(i), depth + 1)) return true
            }
            return false
        }
        return scan(root, 0)
    }

    private fun nativeMenuLooksLikeStoryTrayMenu(root: ViewGroup): Boolean {
        var hasViewProfile = false
        var hasMute = false
        var hasSuggestionOnly = false
        fun scan(view: View, depth: Int) {
            if (depth > 5) return
            if (view is TextView) {
                val text = view.text?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
                if (text == "view profile") hasViewProfile = true
                if (text == "mute") hasMute = true
                if (text == "hide suggestion") hasSuggestionOnly = true
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) scan(view.getChildAt(i), depth + 1)
            }
        }
        scan(root, 0)
        return hasViewProfile && hasMute && !hasSuggestionOnly
    }

    private fun containsStoryTrayInjectedLabels(root: ViewGroup): Boolean {
        return containsMenuLabel(root, "View profile picture") || containsMenuLabel(root, "View cover photo")
    }

    private fun containsMenuLabel(root: ViewGroup, label: String): Boolean {
        fun scan(view: View, depth: Int): Boolean {
            if (depth > 5) return false
            if (view is TextView) {
                val text = view.text?.toString().orEmpty()
                if (text.equals(label, ignoreCase = true)) return true
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) if (scan(view.getChildAt(i), depth + 1)) return true
            }
            return false
        }
        return scan(root, 0)
    }

    private fun installIntentAndClipboardHooks() {
        if (!intentClipboardHooksInstalled.compareAndSet(false, true)) return
        runSafe("Clipboard and Intent hooks") {
            XposedBridge.hookAllMethods(
                ClipboardManager::class.java,
                "setPrimaryClip",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val clip = param.args.firstOrNull() as? ClipData ?: return
                        rewriteCopyBioClipData(clip)?.let {
                            param.args[0] = it
                            return
                        }
                        val sanitized = sanitizeClipData(clip)
                        if (sanitized != null) param.args[0] = sanitized
                    }
                }
            )
            XposedBridge.hookAllMethods(
                ClipboardManager::class.java,
                "setText",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableCopyBio || System.currentTimeMillis() > copyBioMenuActiveUntilMs) return
                        val copied = param.args.firstOrNull()?.toString().orEmpty()
                        if (!looksLikeInstagramProfileUrl(copied)) return
                        val bio = lastSeenBioText?.trim().orEmpty()
                        if (isReliableBioText(bio)) param.args[0] = bio
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Intent::class.java,
                "putExtra",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (param.args.size != 2 || param.args[0] !is String) return
                        val intent = param.thisObject as? Intent
                        val key = param.args[0] as String
                        val value = param.args[1]
                        if (state.enableDmAnyFileUpload && key == Intent.EXTRA_MIME_TYPES && value is Array<*> && looksLikePicker(intent)) {
                            @Suppress("UNCHECKED_CAST")
                            param.args[1] = mergeMimeTypes(value.filterIsInstance<String>().toTypedArray())
                            return
                        }
                        when (value) {
                            is String -> param.args[1] = sanitizeTextForSharing(value)
                            is CharSequence -> param.args[1] = sanitizeTextForSharing(value.toString())
                            is Uri -> sanitizeUri(value)?.let { param.args[1] = it }
                            is ArrayList<*> -> {
                                var changed = false
                                val rewritten = ArrayList<Uri>()
                                value.forEach { item ->
                                    val uri = item as? Uri ?: return@forEach
                                    rewritten += sanitizeUri(uri)?.also { changed = true } ?: uri
                                }
                                if (changed && rewritten.size == value.size) param.args[1] = rewritten
                            }
                        }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Intent::class.java,
                "setData",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val uri = param.args.firstOrNull() as? Uri ?: return
                        sanitizeUri(uri, allowShareDomainRewrite = false)?.let { param.args[0] = it }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Intent::class.java,
                "setDataAndType",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val uri = param.args.firstOrNull() as? Uri ?: return
                        sanitizeUri(uri, allowShareDomainRewrite = false)?.let { param.args[0] = it }
                    }
                }
            )
            val launchHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    val intents = param.args.filterIsInstance<Intent>()
                    val context = param.thisObject as? Context
                    intents.forEach { intent ->
                        if (context == null || !isInstagramInternalNavigationIntent(context, intent)) {
                            sanitizeIntent(intent)
                        }
                        if (state.enableDmAnyFileUpload) widenFilePicker(intent)
                    }
                    if (state.openLinksExternally && param.method.name == "startActivity") {
                        val intent = intents.firstOrNull()
                        if (intent != null && context != null && launchExternalBrowserIfNeeded(context, intent)) {
                            param.result = null
                            return
                        }
                    }
                }
            }
            XposedBridge.hookAllMethods(Activity::class.java, "startActivity", launchHook)
            XposedBridge.hookAllMethods(Activity::class.java, "startActivityForResult", launchHook)
            XposedBridge.hookAllMethods(ContextWrapper::class.java, "startActivity", launchHook)
            XposedBridge.hookAllMethods(
                Intent::class.java,
                "setType",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableDmAnyFileUpload) return
                        val intent = param.thisObject as? Intent ?: return
                        if (looksLikePicker(intent) && shouldWidenType(param.args.firstOrNull() as? String)) {
                            param.args[0] = "*/*"
                            intent.putExtra(Intent.EXTRA_MIME_TYPES, broadMimeTypes)
                        }
                    }
                }
            )
        }
    }

    private fun installConfirmRefreshHooks() {
        if (!confirmRefreshHooksInstalled.compareAndSet(false, true)) return
        val refreshClasses = listOf(
            "X.G56",
            "p000X.G56",
            "com.instagram.ui.widget.refresh.IgSwipeRefreshLayout",
            "com.instagram.p131ui.widget.refresh.IgSwipeRefreshLayout",
            "androidx.swiperefreshlayout.widget.SwipeRefreshLayout",
            "android.support.v4.widget.SwipeRefreshLayout",
            "com.instagram.features.clips.viewer.ui.ClipsSwipeRefreshLayout",
            "instagram.features.clips.viewer.p154ui.HomecomingSwipeRefreshLayout",
            "instagram.features.clips.viewer.ui.HomecomingSwipeRefreshLayout",
            "com.instagram.ui.widget.refresh.RefreshableNestedScrollingParent"
        )
        var directHookedClasses = 0
        refreshClasses.forEach { className ->
            runCatching {
                val cls = Class.forName(className, false, appClassLoader)
                var classHooked = false
                var methodCount = 0
                cls.declaredMethods
                    .filter { method ->
                        method.name == "setOnRefreshListener" &&
                            method.parameterTypes.size == 1 &&
                            method.parameterTypes[0].isInterface
                    }
                    .forEach { method ->
                        method.isAccessible = true
                        val listenerClass = method.parameterTypes[0]
                        XposedBridge.hookMethod(
                            method,
                            object : XC_MethodHook() {
                                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                    val original = param.args.firstOrNull() ?: return
                                    if (Proxy.isProxyClass(original.javaClass)) return
                                    param.args[0] = wrapRefreshListener(param.thisObject, original, listenerClass)
                                }
                            }
                        )
                        classHooked = true
                        methodCount++
                    }
                if (classHooked) {
                    confirmRefreshUiGuardHookedClasses++
                    directHookedClasses++
                    logInfo("Hooked refresh listener class=$className methods=$methodCount")
                }
            }
        }
        var mrqHookedClasses = 0
        listOf("X.MRQ", "p000X.MRQ").forEach { className ->
            runCatching {
                val cls = Class.forName(className, false, appClassLoader)
                var classHooked = false
                cls.declaredMethods
                    .filter { method -> method.name == "FFM" && method.parameterTypes.isEmpty() && method.returnType == java.lang.Void.TYPE }
                    .forEach { method ->
                        method.isAccessible = true
                        XposedBridge.hookMethod(
                            method,
                            object : XC_MethodHook() {
                                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                    if (!state.enableConfirmRefresh) return
                                    val surface = currentForegroundOrLikelyRefreshSurface() ?: run {
                                        logRefreshDecision("mrq-no-surface", null, "ignored", "no foreground feed/reels")
                                        return
                                    }
                                    if (!state.shouldConfirmRefresh(surface)) {
                                        logRefreshDecision("mrq-scope", surface, "allowed", "scope=${state.confirmRefreshScope}")
                                        return
                                    }
                                    if (isRefreshAllowed(surface)) {
                                        logRefreshDecision("mrq-allowed", surface, "allowed", "recent user confirmation")
                                        return
                                    }
                                    clearVisibleRefreshSpinners(currentActivity)
                                    if (isRefreshDialogPending(surface)) {
                                        logRefreshDecision("mrq-pending", surface, "blocked", "dialog already pending")
                                        param.result = null
                                        return
                                    }
                                    setRefreshDialogPending(surface, true)
                                    logRefreshDecision("mrq-dialog", surface, "dialog", "showing confirm dialog")
                                    showConfirmRefreshDialog(
                                        surface,
                                        onConfirm = {
                                            setRefreshDialogPending(surface, false)
                                            allowRefreshSurface(surface, 3_000L)
                                            logRefreshDecision("mrq-confirm", surface, "allowed", "user confirmed")
                                            runCatching { XposedBridge.invokeOriginalMethod(method, param.thisObject, emptyArray<Any>()) }
                                                .onFailure { logError("Confirmed refresh callback failed", it) }
                                        },
                                        onCancel = {
                                            setRefreshDialogPending(surface, false)
                                            clearVisibleRefreshSpinners(currentActivity)
                                            logRefreshDecision("mrq-cancel", surface, "blocked", "user cancelled")
                                        }
                                    )
                                    param.result = null
                                }
                            }
                        )
                        classHooked = true
                    }
                if (classHooked) {
                    confirmRefreshUiGuardHookedClasses++
                    mrqHookedClasses++
                    logInfo("Hooked MRQ refresh callback class=$className")
                }
            }
        }
        logInfo(
            "Confirm-refresh direct hooks installed listenerClasses=$directHookedClasses mrqClasses=$mrqHookedClasses " +
                "totalUiGuards=$confirmRefreshUiGuardHookedClasses scope=${state.confirmRefreshScope}"
        )
    }

    private fun installConfirmRefreshDexListenerHooks() {
        var hooked = 0
        val hookedOwners = HashSet<String>()
        dexBridge.findMethodsByName("setOnRefreshListener", returnType = "void", paramCount = 1).forEach { method ->
            val params = method.parameterTypes
            if (params.size != 1 || !params[0].isInterface) return@forEach
            val signature = "${methodKey(method)}:confirm_refresh_listener"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                val listenerClass = params[0]
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            val original = param.args.firstOrNull() ?: return
                            if (Proxy.isProxyClass(original.javaClass)) return
                            param.args[0] = wrapRefreshListener(param.thisObject, original, listenerClass)
                        }
                    }
                )
                if (hookedOwners.add(method.declaringClass.name)) hooked++
                logInfo("Hooked Dex refresh listener ${method.declaringClass.name}.${method.name}")
            }.onFailure { logError("Failed Dex refresh listener hook $signature", it) }
        }
        if (hooked > 0) logInfo("Dex refresh guard hooked classes=$hooked")
        if (hooked > 0) confirmRefreshUiGuardHookedClasses += hooked
    }

    private fun wrapRefreshListener(refreshView: Any?, original: Any, listenerClass: Class<*>): Any {
        return Proxy.newProxyInstance(listenerClass.classLoader, arrayOf(listenerClass)) { proxy, method, args ->
            val isRefreshCallback = method.name == "onRefresh" || (method.name == "FFM" && method.parameterTypes.isEmpty())
            if (!state.enableConfirmRefresh || !isRefreshCallback) {
                return@newProxyInstance method.invoke(original, *(args ?: emptyArray()))
            }
            val surface = surfaceForRefreshView(refreshView as? View)
            if (surface == null) {
                logRefreshDecision("listener-no-surface", null, "allowed", "refreshView=${(refreshView as? View)?.let(::describeViewBrief) ?: refreshView?.javaClass?.name}")
                return@newProxyInstance method.invoke(original, *(args ?: emptyArray()))
            }
            if (!state.shouldConfirmRefresh(surface)) {
                logRefreshDecision("listener-scope", surface, "allowed", "scope=${state.confirmRefreshScope}")
                return@newProxyInstance method.invoke(original, *(args ?: emptyArray()))
            }
            if (isRefreshAllowed(surface)) {
                logRefreshDecision("listener-allowed", surface, "allowed", "recent user confirmation")
                return@newProxyInstance method.invoke(original, *(args ?: emptyArray()))
            }
            setRefreshing(refreshView, false)
            if (!isRefreshSurfaceForeground(surface)) {
                logRefreshDecision("listener-hidden", surface, "blocked", "spinner released")
                return@newProxyInstance defaultResult(method.returnType)
            }
            if (isRefreshDialogPending(surface)) {
                logRefreshDecision("listener-pending", surface, "blocked", "dialog already pending")
                return@newProxyInstance defaultResult(method.returnType)
            }
            setRefreshDialogPending(surface, true)
            logRefreshDecision("listener-dialog", surface, "dialog", "showing confirm dialog")
            showConfirmRefreshDialog(
                surface,
                onConfirm = {
                    setRefreshDialogPending(surface, false)
                    allowRefreshSurface(surface, 3_000L)
                    logRefreshDecision("listener-confirm", surface, "allowed", "user confirmed")
                    runCatching { method.invoke(original, *(args ?: emptyArray())) }
                        .onFailure { logError("Confirmed refresh listener failed", it) }
                },
                onCancel = {
                    setRefreshDialogPending(surface, false)
                    setRefreshing(refreshView, false)
                    logRefreshDecision("listener-cancel", surface, "blocked", "user cancelled")
                }
            )
            defaultResult(method.returnType)
        }
    }

    private fun installNotificationHooks() {
        runSafe("Notification hooks") {
            val hook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    val notification = param.args.filterIsInstance<Notification>().firstOrNull() ?: return
                    if (shouldBlockNotification(notification)) {
                        param.result = null
                        logInfo("Blocked Instagram DM media notification")
                    }
                }
            }
            listOf("notify", "notifyAsUser", "notifyAsPackage").forEach { method ->
                XposedBridge.hookAllMethods(NotificationManager::class.java, method, hook)
            }
        }
    }

    private fun installPreferenceHooks() {
        if (!preferenceHooksInstalled.compareAndSet(false, true)) return
        runSafe("SharedPreferences hooks") {
            val prefsClass = Class.forName("android.app.SharedPreferencesImpl")
            XposedBridge.hookAllMethods(
                prefsClass,
                "getBoolean",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val key = param.args.firstOrNull()?.toString()?.lowercase() ?: return
                        when {
                            state.disableVideoAutoPlay && key.contains("autoplay") && isReelsAutoplaySurfaceActive() && key.contains("disable") -> param.result = false
                            state.disableVideoAutoPlay && key.contains("autoplay") && isFeedAutoplaySurfaceActive() -> param.result = false
                            state.enableHighQualityStoryUpload && (key.contains("high_quality") || key.contains("usehighestquality")) -> param.result = true
                        }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                prefsClass,
                "getInt",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val key = param.args.firstOrNull()?.toString()?.lowercase(Locale.US) ?: return
                        val value = storyUploadQualityPreferenceOverride(key) ?: return
                        param.result = value
                    }
                }
            )
            val editorClass = Class.forName("android.app.SharedPreferencesImpl\$EditorImpl")
            val editorHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    val key = param.args.firstOrNull()?.toString()?.lowercase() ?: return
                    if (state.doNotSaveRecentSearches && looksLikeRecentSearchStorageKey(key)) {
                        param.result = param.thisObject
                    }
                }
            }
            XposedBridge.hookAllMethods(editorClass, "putBoolean", editorHook)
            XposedBridge.hookAllMethods(editorClass, "putString", editorHook)
            XposedBridge.hookAllMethods(editorClass, "putStringSet", editorHook)
        }
    }

    private fun installRecentSearchHooks() {
        val insertHook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                val table = param.args.firstOrNull() as? String ?: return
                val values = param.args.firstOrNull { it is ContentValues } as? ContentValues
                maybeCollectDirectChatNamesFromStorageWrite(table, values)
                if (!state.doNotSaveRecentSearches) return
                if (looksLikeRecentSearchStorageKey(table) || contentValuesLookLikeRecentSearch(values)) {
                    param.result = 1L
                    logInfo("Blocked Instagram recent-search database write")
                }
            }
        }
        val updateHook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                val table = param.args.firstOrNull() as? String ?: return
                val values = param.args.firstOrNull { it is ContentValues } as? ContentValues
                maybeCollectDirectChatNamesFromStorageWrite(table, values)
                if (!state.doNotSaveRecentSearches) return
                if (looksLikeRecentSearchStorageKey(table) || contentValuesLookLikeRecentSearch(values)) {
                    param.result = 0
                    logInfo("Blocked Instagram recent-search database update")
                }
            }
        }
        val execHook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (!state.doNotSaveRecentSearches) return
                val sql = param.args.firstOrNull()?.toString()?.trim()?.lowercase(Locale.US) ?: return
                if (isRecentSearchWriteSql(sql)) {
                    param.result = null
                    logInfo("Blocked Instagram recent-search SQL")
                }
            }
        }
        val statementHook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (!state.doNotSaveRecentSearches) return
                val sql = sqliteStatementSql(param.thisObject)?.trim()?.lowercase(Locale.US) ?: return
                if (!isRecentSearchWriteSql(sql)) return
                param.result = when ((param.method as? Method)?.name) {
                    "executeInsert" -> 1L
                    "executeUpdateDelete" -> 0
                    else -> null
                }
                logInfo("Blocked Instagram recent-search SQLiteStatement")
            }
        }
        val compileStatementHook = object : XC_MethodHook() {
            override fun afterHookedMethod(param: MethodHookParam<*>) {
                val sql = param.args.firstOrNull()?.toString() ?: return
                val statement = param.result ?: return
                sqliteStatementSqlCache[statement] = sql
            }
        }
        runSafe("Recent search privacy SQLite hooks") {
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "compileStatement", compileStatementHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "insert", insertHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "insertOrThrow", insertHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "replace", insertHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "replaceOrThrow", insertHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "insertWithOnConflict", insertHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "update", updateHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "updateWithOnConflict", updateHook)
            XposedBridge.hookAllMethods(SQLiteDatabase::class.java, "execSQL", execHook)
            XposedBridge.hookAllMethods(SQLiteStatement::class.java, "execute", statementHook)
            XposedBridge.hookAllMethods(SQLiteStatement::class.java, "executeInsert", statementHook)
            XposedBridge.hookAllMethods(SQLiteStatement::class.java, "executeUpdateDelete", statementHook)
        }
    }

    private fun sqliteStatementSql(statement: Any?): String? {
        sqliteStatementSqlCache[statement]?.let { return it }
        var cls: Class<*>? = statement?.javaClass ?: return null
        while (cls != null && cls != Any::class.java) {
            listOf("mSql", "sql").forEach { fieldName ->
                runCatching {
                    val field = cls.getDeclaredField(fieldName)
                    field.isAccessible = true
                    (field.get(statement) as? String)?.let { return it }
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun contentValuesLookLikeRecentSearch(values: ContentValues?): Boolean {
        values ?: return false
        var hasSearch = false
        var hasPersistence = false
        values.valueSet().forEach { entry ->
            val text = "${entry.key} ${entry.value}".lowercase(Locale.US)
            if (looksLikeRecentSearchStorageKey(text) || looksLikeRecentSearchPersistenceUrl(text)) return true
            if (text.contains("search") || text.contains("serp") || text.contains("typeahead")) hasSearch = true
            if (text.contains("recent") || text.contains("history") || text.contains("nullstate") ||
                text.contains("keyword") || text.contains("entity") || text.contains("profile_grid")
            ) {
                hasPersistence = true
            }
        }
        return hasSearch && hasPersistence
    }

    private fun isRecentSearchWriteSql(sql: String): Boolean {
        return looksLikeRecentSearchStorageKey(sql) &&
            (sql.startsWith("insert") ||
                sql.startsWith("replace") ||
                sql.startsWith("update") ||
                sql.startsWith("delete") ||
                sql.startsWith("with "))
    }

    private fun looksLikeRecentSearchStorageKey(value: String?): Boolean {
        val lower = value?.lowercase(Locale.US).orEmpty()
        return lower.contains("recent_search") ||
            lower.contains("recentsearch") ||
            lower.contains("search_history") ||
            lower.contains("searchhistory") ||
            lower.contains("keyword_search") ||
            lower.contains("search_nullstate") ||
            lower.contains("nullstate_search") ||
            lower.contains("search_typeahead") ||
            lower.contains("typeahead_search") ||
            lower.contains("search_recent") ||
            lower.contains("recently_searched") ||
            lower.contains("search_session")
    }

