        if (s.localInstagramPlus) {
            installDexKitStep("LocalInstagramPlusEntrypointGates") { installLocalInstagramPlusEntrypointGateHook() }
            installDexKitStep("LocalInstagramPlusStoryPeekGate") { installLocalInstagramPlusStoryPeekGateHook() }
            installDexKitStep("LocalInstagramPlusStoryPeekMenu") { installLocalInstagramPlusStoryPeekMenuHook() }
            installDexKitStep("LocalInstagramPlusAppIconCard") { installLocalInstagramPlusAppIconCardHook() }
            installDexKitStep("LocalInstagramPlusAppIconController") { installLocalInstagramPlusAppIconControllerHook() }
            installDexKitStep("LocalInstagramPlusAppIconState") { installLocalInstagramPlusAppIconStateHook() }
