    private fun shouldInstallPostVideoUrlCapture(current: InstagramFeatureState = state): Boolean {
        // On-demand media extraction avoids a global getUrl hook that fires thousands of times while scrolling.
        return current.enablePostDownload && ENABLE_GENERIC_POST_VIDEO_URL_CAPTURE
    }

    private fun installDexKitStep(name: String, block: () -> Unit) {
        val started = SystemClock.uptimeMillis()
        runCatching(block)
            .onSuccess {
                logInfo("DexKit step installed name=$name elapsed=${SystemClock.uptimeMillis() - started}ms")
            }
            .onFailure {
                logError("DexKit step failed name=$name elapsed=${SystemClock.uptimeMillis() - started}ms", it)
            }
    }

