    private fun installLocalInstagramPlusDirectConfigClassLoadHook() {
        if (!localPlusDirectConfigClassLoadHookInstalled.compareAndSet(false, true)) return
        val mobileConfigTypes = localInstagramPlusMobileConfigTypes()
        if (mobileConfigTypes.isEmpty()) {
            logInfo("Local Instagram Plus direct MobileConfig class-load hook skipped: interface missing")
            return
