        XposedBridge.hookAllMethods(
            ClassLoader::class.java,
            "loadClass",
            object : XC_MethodHook() {
                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    if (!state.localInstagramPlus && !state.restoreOldPostReelContextMenu) return
                    val clazz = param.result as? Class<*> ?: return
                    if (clazz.isInterface || Modifier.isAbstract(clazz.modifiers)) return
                    if (clazz.name.startsWith("java.") || clazz.name.startsWith("android.")) return
                    if (mobileConfigTypes.none { type -> type.isAssignableFrom(clazz) }) return
                    val methods = clazz.declaredMethods
                        .filter(::isLocalInstagramPlusDirectMobileConfigBoolMethod)
                        .distinctBy(::methodKey)
                    if (methods.isEmpty()) return
                    val hooked = hookLocalInstagramPlusDirectConfigFlagMethods(methods, "classload")
                    if (hooked > 0 && localPlusDirectConfigHookedOwners.add(clazz.name)) {
                        val names = methods.joinToString { "${it.name}/${it.parameterTypes.size}" }
                        logInfo(
                            "Installed Local Instagram Plus class-load MobileConfig bool hook(s)=$hooked " +
                                "class=${clazz.name} methods=$names"
                        )
                    }
                }
            }
        )
        logInfo("Installed Local Instagram Plus direct MobileConfig class-load mapper")
    }

