    private fun removeLocalInstagramPlusStoryPeekUpsellRows(
        args: Array<Any?>?,
        paramTypes: Array<Class<*>>,
        method: Method
    ): Int {
        args ?: return 0
        var removed = 0
        args.indices.forEach { index ->
            val list = args[index] as? List<*> ?: return@forEach
            if (list.isEmpty()) return@forEach
            val removeIndices = list.indices.filter { itemIndex ->
                isLocalInstagramPlusStoryPeekUpsellMenuItem(list[itemIndex])
            }
            if (removeIndices.isEmpty()) return@forEach

            @Suppress("UNCHECKED_CAST")
            val mutable = list as? MutableList<Any?>
            val removedInPlace = mutable?.let { target ->
                runCatching {
                    removeIndices.asReversed().forEach { itemIndex -> target.removeAt(itemIndex) }
                    true
                }.getOrDefault(false)
            } == true
            if (removedInPlace) {
                removed += removeIndices.size
                return@forEach
            }

            val removeIndexSet = removeIndices.toHashSet()
            val replacement = ArrayList<Any?>(list.size - removeIndices.size)
            list.forEachIndexed { itemIndex, item ->
                if (itemIndex !in removeIndexSet) replacement += item
            }
            val paramType = paramTypes.getOrNull(index)
            if (paramType == null || paramType.isAssignableFrom(replacement.javaClass)) {
                args[index] = replacement
                removed += removeIndices.size
            } else {
                logLocalInstagramPlusStoryPeekMenu(
                    method,
                    "detected upsell model rows=${removeIndices.size} but preserved typed menu arg=${paramType.name}"
                )
            }
        }
        return removed
    }

