    private fun isLocalInstagramPlusStoryPeekPreviewUpsellItem(item: Any?): Boolean {
        item ?: return false
        return localInstagramPlusStoryPeekMenuItemLabels(item)
            .any { label -> label.trim().equals("See preview", ignoreCase = true) }
    }

    private fun shouldSuppressLocalInstagramPlusStoryPeekSubtitle(item: Any?): Boolean {
        item ?: return false
        val labels = localInstagramPlusStoryPeekMenuItemLabels(item)
        return labels.isEmpty() || labels.any { label ->
            label.trim().equals("See preview", ignoreCase = true)
        }
    }

    private fun localInstagramPlusStoryPeekMenuItemLabels(item: Any): List<String> {
        val methods = localInstagramPlusStoryPeekMenuLabelMethods(item.javaClass)
        if (methods.isEmpty()) return emptyList()
        val labels = ArrayList<String>(methods.size)
        methods.forEach { method ->
            val resId = runCatching { (method.invoke(item) as? Number)?.toInt() }.getOrNull() ?: return@forEach
            localInstagramPlusStringResource(resId)?.let { label -> labels += label }
        }
        return labels
    }

    private fun localInstagramPlusStoryPeekMenuLabelMethods(type: Class<*>): List<Method> {
        localPlusStoryPeekMenuLabelMethods[type]?.let { return it }
        val candidates = LinkedHashSet<Method>()
        fun collect(current: Class<*>?) {
            if (current == null || current == Any::class.java) return
            current.declaredMethods.forEach { method -> candidates += method }
            current.interfaces.forEach { iface -> collect(iface) }
            collect(current.superclass)
        }
        collect(type)
        val methods = candidates
            .filter { method ->
                !Modifier.isStatic(method.modifiers) &&
                    method.name != "DNL" &&
                    method.parameterTypes.isEmpty() &&
                    method.returnType == java.lang.Integer.TYPE
            }
            .onEach { method -> method.isAccessible = true }
            .take(32)
        return localPlusStoryPeekMenuLabelMethods.putIfAbsent(type, methods) ?: methods
    }

    private fun localInstagramPlusStringResource(resId: Int): String? {
        if (resId < 0x01000000) return null
        return runCatching { androidContext.getString(resId) }.getOrNull()
    }

    private fun isLocalInstagramPlusStoryPeekUpsellLabel(label: String?): Boolean {
        val normalized = label?.trim()?.lowercase(Locale.US).orEmpty()
        return normalized == "try instagram plus" ||
            normalized == "try instagram+" ||
            (normalized.contains("try") && normalized.contains("instagram plus")) ||
            (normalized.contains("try") && normalized.contains("instagram+"))
    }

    private fun couldBeLocalInstagramPlusStoryPeekUpsellLabel(label: CharSequence?): Boolean {
        val length = label?.length ?: return false
        if (length == 0 || length > 96) return false
        return label.indexOf("try", ignoreCase = true) >= 0 &&
            label.indexOf("instagram", ignoreCase = true) >= 0
    }

    private fun maybeHideLocalInstagramPlusStoryPeekUpsellTextFast(
        textView: TextView,
        rawCandidate: CharSequence?,
        descriptionCandidate: CharSequence?
    ): Boolean {
        if (!couldBeLocalInstagramPlusStoryPeekUpsellLabel(rawCandidate) &&
            !couldBeLocalInstagramPlusStoryPeekUpsellLabel(descriptionCandidate)
        ) {
            return false
        }
        return maybeHideLocalInstagramPlusStoryPeekUpsellText(
            textView,
            rawCandidate?.toString().orEmpty(),
            descriptionCandidate?.toString().orEmpty()
        )
    }

    private fun maybeHideLocalInstagramPlusStoryPeekUpsellText(textView: TextView, raw: String, rawDescription: String): Boolean {
        if (!isLocalInstagramPlusStoryPeekUpsellLabel(raw) &&
            !isLocalInstagramPlusStoryPeekUpsellLabel(rawDescription)
        ) return false
        val firstHide = localPlusStoryPeekUpsellHiddenViews.add(textView)
        runCatching {
            if (textView.text?.isNotEmpty() == true) textView.text = ""
            textView.contentDescription = null
            textView.alpha = 0f
            textView.visibility = View.GONE
            textView.layoutParams = (textView.layoutParams ?: ViewGroup.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            )).apply {
                height = 0
            }
            textView.requestLayout()
            (textView.parent as? View)?.requestLayout()
            if (firstHide) {
                logInfo(
                    "Local Instagram Plus story peek visible upsell text hidden " +
                        "view=${textView.javaClass.name} text=${raw.ifBlank { rawDescription }.take(80)}"
                )
            }
        }.onFailure { logError("Failed hiding Local Instagram Plus story peek visible upsell row", it) }
        return true
    }

    private fun logLocalInstagramPlusStoryPeekMenu(method: Method, detail: String) {
        val key = "${method.declaringClass.name}.${method.name}:$detail"
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusStoryPeekMenuLogTimes[key] ?: 0L
        if (now - previous < 5_000L) return
        localPlusStoryPeekMenuLogTimes[key] = now
        if (localPlusStoryPeekMenuLogTimes.size > 100) localPlusStoryPeekMenuLogTimes.clear()
        logInfo("Local Instagram Plus story peek menu $detail method=${method.declaringClass.name}.${method.name}")
    }

    private fun discoverLocalInstagramPlusDirectConfigBoolMethods(): List<Method> {
        val candidates = LinkedHashSet<Method>()
        val interfaceMethods = localInstagramPlusMobileConfigTypes()
            .flatMap { type -> type.declaredMethods.toList() }
            .filter(::isLocalInstagramPlusDirectMobileConfigBoolMethod)

        interfaceMethods.forEach { interfaceMethod ->
            candidates += dexBridge.findMethodsByName(
                interfaceMethod.name,
                returnType = "boolean",
                paramCount = interfaceMethod.parameterTypes.size
            )
        }

        candidates += dexBridge.findMethodsByParamTypes("boolean", "long")
        candidates += dexBridge.findMethodsByParamTypes("boolean", "long", "boolean")
        candidates += dexBridge.findMethodsByParamTypesWithWildcards("boolean", listOf(null, "long"))
        candidates += dexBridge.findMethodsByParamTypesWithWildcards("boolean", listOf(null, "long", "boolean"))

        return candidates
            .filter(::isLocalInstagramPlusDirectMobileConfigBoolMethod)
            .filter(::isLocalInstagramPlusMobileConfigOwner)
            .filterNot { method -> method.declaringClass.isInterface || Modifier.isAbstract(method.modifiers) }
            .distinctBy(::methodKey)
    }

    private fun localInstagramPlusMobileConfigTypes(): List<Class<*>> {
        return listOf(
            "com.facebook.mobileconfig.factory.MobileConfigUnsafeContext",
            "X.0A4",
            "p000X.C0A4"
        ).mapNotNull { className ->
            runCatching { Class.forName(className, false, appClassLoader) }.getOrNull()
        }.distinctBy { it.name }
    }

    private fun isLocalInstagramPlusMobileConfigOwner(method: Method): Boolean {
        val owner = method.declaringClass
        return localInstagramPlusMobileConfigTypes().any { type -> type.isAssignableFrom(owner) }
    }

    private fun isLocalInstagramPlusDirectMobileConfigBoolMethod(method: Method): Boolean {
        if (method.returnType != java.lang.Boolean.TYPE && method.returnType != java.lang.Boolean::class.java) return false
        val params = method.parameterTypes
        if (params.isEmpty() || params.size > 3) return false
        if (params.none { it == java.lang.Long.TYPE || it == java.lang.Long::class.java }) return false
        return params.withIndex().all { (index, type) ->
            when (index) {
                0 -> type == java.lang.Long.TYPE ||
                    type == java.lang.Long::class.java ||
                    !type.isPrimitive
                1 -> type == java.lang.Long.TYPE ||
                    type == java.lang.Long::class.java ||
                    type == java.lang.Boolean.TYPE ||
                    type == java.lang.Boolean::class.java
                2 -> type == java.lang.Boolean.TYPE || type == java.lang.Boolean::class.java
                else -> false
            }
        }
    }

    private fun hookLocalInstagramPlusDirectConfigFlagMethods(methods: List<Method>, source: String): Int {
        if (methods.isEmpty()) return 0
        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:local_instagram_plus_direct_config_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            applyLocalInstagramPlusConfigOverride(param, method, traceDirectConfig = true)
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed Local Instagram Plus direct MobileConfig bool hook $signature", it) }
        }
        return hooked
    }

    private fun installLocalInstagramPlusEntrypointGateHook() {
        val gateClass = findFirstClass("X.0LXH", "p000X.C0LXH", "X.C0LXH")
        if (gateClass == null) {
            logInfo("Local Instagram Plus entrypoint gate class not found")
            return
        }
        val methods = gateClass.declaredMethods
            .filter(::isLocalInstagramPlusEntrypointGateMethod)
            .distinctBy(::methodKey)
        if (methods.isEmpty()) {
            logInfo("Local Instagram Plus entrypoint gate method not found class=${gateClass.name}")
            return
        }

        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:local_instagram_plus_entrypoint_gate"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.localInstagramPlus) return
                            val entrypoint = param.args?.firstOrNull { it is String } as? String ?: return
                            val override = LOCAL_INSTAGRAM_PLUS_ENTRYPOINT_OVERRIDES[entrypoint] ?: return
                            param.result = override
                            logLocalInstagramPlusEntrypointDecision(entrypoint, override, method)
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed Local Instagram Plus entrypoint gate hook $signature", it) }
        }
        logInfo("Installed Local Instagram Plus entrypoint gate hook(s)=$hooked class=${gateClass.name}")
    }

    private fun isLocalInstagramPlusEntrypointGateMethod(method: Method): Boolean {
        return Modifier.isStatic(method.modifiers) &&
            (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) &&
            method.parameterTypes.size == 2 &&
            method.parameterTypes[1] == String::class.java
    }

    private fun logLocalInstagramPlusEntrypointDecision(entrypoint: String, value: Boolean, method: Method) {
        val key = "entrypoint:$entrypoint:$value"
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusConfigLogTimes[key] ?: 0L
        if (now - previous < 10_000L) return
        localPlusConfigLogTimes[key] = now
        if (localPlusConfigLogTimes.size > 180) localPlusConfigLogTimes.clear()
        logInfo(
            "Local Instagram Plus entrypoint override entrypoint=$entrypoint value=$value " +
                "method=${method.declaringClass.name}.${method.name}"
        )
    }

    private fun installLocalInstagramPlusConfigFlagHook() {
        val cacheKey = "LocalInstagramPlusMobileConfigBool_v1"
        val cached = if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods(cacheKey, appClassLoader).orEmpty()
                .filter(::isLocalInstagramPlusMobileConfigBoolMethod)
        } else {
            emptyList()
        }

        if (cached.isNotEmpty()) {
            val hooked = hookLocalInstagramPlusConfigFlagMethods(cached, "cached")
            if (hooked > 0) {
                logInfo("Installed Local Instagram Plus config bool hook(s)=$hooked source=cached candidates=${cached.size}")
                return
            }
            logInfo("Local Instagram Plus cached config bool candidates did not hook; retrying DexKit discovery")
        }

        val discovered = discoverLocalInstagramPlusConfigBoolMethods()
        if (discovered.isNotEmpty()) InstagramDexKitCache.saveMethods(cacheKey, discovered)
        val hooked = hookLocalInstagramPlusConfigFlagMethods(discovered, "dex")
        if (hooked > 0) {
            logInfo("Installed Local Instagram Plus config bool hook(s)=$hooked source=dex candidates=${discovered.size}")
        } else {
            logInfo("Local Instagram Plus config bool getter not found")
        }
    }

    private fun discoverLocalInstagramPlusConfigBoolMethods(): List<Method> {
        val candidates = LinkedHashSet<Method>()
        dexBridge.findMethodsUsingStrings("__fbt_null__")
            .filter { method ->
                method.returnType == String::class.java &&
                    method.parameterTypes.isNotEmpty()
            }
            .forEach { stringMethod ->
                val wrapperType = stringMethod.parameterTypes.firstOrNull() ?: return@forEach
                stringMethod.declaringClass.declaredMethods
                    .filter { method -> isLocalInstagramPlusMobileConfigBoolMethod(method, wrapperType) }
                    .forEach { candidates += it }
            }
        return candidates.distinctBy(::methodKey)
    }

    private fun isLocalInstagramPlusMobileConfigBoolMethod(method: Method): Boolean {
        return (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) &&
            method.parameterTypes.size == 3 &&
            method.parameterTypes.any { it == java.lang.Long.TYPE || it == java.lang.Long::class.java }
    }

    private fun isLocalInstagramPlusMobileConfigBoolMethod(method: Method, wrapperType: Class<*>): Boolean {
        return isLocalInstagramPlusMobileConfigBoolMethod(method) &&
            method.parameterTypes.firstOrNull() == wrapperType
    }

    private fun hookLocalInstagramPlusConfigFlagMethods(methods: List<Method>, source: String): Int {
        if (methods.isEmpty()) return 0
        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:local_instagram_plus_config_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            applyLocalInstagramPlusConfigOverride(param, method, traceDirectConfig = false)
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed Local Instagram Plus config bool hook $signature", it) }
        }
        return hooked
    }

    private fun applyLocalInstagramPlusConfigOverride(
        param: XC_MethodHook.MethodHookParam<*>,
        method: Method,
        traceDirectConfig: Boolean
    ) {
        val specifier = param.args?.firstOrNull { arg -> arg is Long } as? Long ?: return
        if (state.restoreOldPostReelContextMenu) {
            RESTORE_OLD_CONTEXT_MENU_BOOL_OVERRIDES[specifier]?.let { override ->
                param.result = override
                logInstagramRawConfigDecision("old_context_menu", specifier, override, method)
                return
            }
        }
        if (!state.localInstagramPlus) return
        LOCAL_INSTAGRAM_PLUS_RAW_BOOL_OVERRIDES[specifier]?.let { override ->
            param.result = override
            logInstagramRawConfigDecision("local_instagram_plus", specifier, override, method)
            return
        }
        val configId = localInstagramPlusConfigId(specifier) ?: return
        val override = LOCAL_INSTAGRAM_PLUS_BOOL_OVERRIDES[configId]
        if (override == null) {
            if (traceDirectConfig) logLocalInstagramPlusDirectConfigTrace(configId, specifier, method)
            logLocalInstagramPlusConfigObserved(configId, specifier, method)
            return
        }
        param.result = override
        logLocalInstagramPlusConfigDecision(configId, specifier, override, method)
    }

    private fun logInstagramRawConfigDecision(feature: String, specifier: Long, value: Boolean, method: Method) {
        val key = "$feature:$specifier:$value"
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusConfigLogTimes[key] ?: 0L
        if (now - previous < 10_000L) return
        localPlusConfigLogTimes[key] = now
        if (localPlusConfigLogTimes.size > 180) localPlusConfigLogTimes.clear()
        logInfo(
            "Instagram raw config override feature=$feature specifier=$specifier value=$value " +
                "method=${method.declaringClass.name}.${method.name}"
        )
    }

    private fun localInstagramPlusConfigId(specifier: Long): String? {
        localPlusConfigIdCache[specifier]?.let { return it }
        val universeId = decodeMobileConfigUniverseId(specifier) ?: return null
        val shifted = specifier ushr 16
        val wideParam = ((specifier ushr 62) and 1L) == 1L
        val paramId = if (wideParam) shifted and 0xffffL else shifted and 0xfffL
        val configId = "$universeId::$paramId"
        if (localPlusConfigIdCache.size > 768) localPlusConfigIdCache.clear()
        localPlusConfigIdCache[specifier] = configId
        return configId
    }

    private fun decodeMobileConfigUniverseId(specifier: Long): String? {
        val method = mobileConfigUniverseIdMethod ?: findMobileConfigUniverseIdMethod()
        if (method == null) {
            if (!mobileConfigUniverseIdMethodMissing) {
                mobileConfigUniverseIdMethodMissing = true
                logInfo("Local Instagram Plus config decoder helper not found")
            }
            return null
        }
        return runCatching {
            (method.invoke(null, specifier) as? Number)?.toInt()?.toString()
        }.onFailure {
            logError("Local Instagram Plus config decoder failed", it)
        }.getOrNull()
    }

    private fun findMobileConfigUniverseIdMethod(): Method? {
        if (mobileConfigUniverseIdMethodMissing) return null
        listOf("X.0B3D", "p000X.C0B3D").forEach { className ->
            runCatching {
                val cls = Class.forName(className, false, appClassLoader)
                cls.declaredMethods.firstOrNull { method ->
                    method.name == "A00" &&
                        method.parameterTypes.size == 1 &&
                        method.parameterTypes[0] == java.lang.Long.TYPE &&
                        (method.returnType == java.lang.Integer.TYPE || method.returnType == java.lang.Integer::class.java)
                }?.let { method ->
                    method.isAccessible = true
                    mobileConfigUniverseIdMethod = method
                    logInfo("Local Instagram Plus config decoder helper=$className.${method.name}")
                    return method
                }
            }
        }
        mobileConfigUniverseIdMethodMissing = true
        return null
    }

    private fun logLocalInstagramPlusConfigDecision(configId: String, specifier: Long, value: Boolean, method: Method) {
        val key = "$configId:$value"
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusConfigLogTimes[key] ?: 0L
        if (now - previous < 10_000L) return
        localPlusConfigLogTimes[key] = now
        if (localPlusConfigLogTimes.size > 160) localPlusConfigLogTimes.clear()
        logInfo(
            "Local Instagram Plus config override id=$configId value=$value specifier=$specifier " +
                "method=${method.declaringClass.name}.${method.name}"
        )
    }

    private fun logLocalInstagramPlusDirectConfigTrace(configId: String, specifier: Long, method: Method) {
        if (!localPlusDirectConfigTraceLogTimes.containsKey(configId) && localPlusDirectConfigTraceLogTimes.size >= 60) return
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusDirectConfigTraceLogTimes[configId] ?: 0L
        if (now - previous < 60_000L) return
        localPlusDirectConfigTraceLogTimes[configId] = now
        logInfo(
            "Local Instagram Plus direct config trace id=$configId specifier=$specifier noOverride=true " +
                "method=${method.declaringClass.name}.${method.name}"
        )
    }

    private fun logLocalInstagramPlusConfigObserved(configId: String, specifier: Long, method: Method) {
        val universe = configId.substringBefore("::")
        if (!LOCAL_INSTAGRAM_PLUS_CONFIG_UNIVERSES.contains(universe)) return
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusObservedConfigLogTimes[configId] ?: 0L
        if (now - previous < 30_000L) return
        localPlusObservedConfigLogTimes[configId] = now
        if (localPlusObservedConfigLogTimes.size > 120) localPlusObservedConfigLogTimes.clear()
        logInfo(
            "Local Instagram Plus config observed id=$configId specifier=$specifier noOverride=true " +
                "method=${method.declaringClass.name}.${method.name}"
        )
    }

    private fun installOldPostReelContextMenuReelControllerHook() {
        runSafe("Old post/reel reel controller hook") {
            val cacheKey = "OldPostReelContextMenuReelController_v2"
            val cached = if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethods(cacheKey, appClassLoader).orEmpty()
                    .filter(::isOldPostReelContextMenuReelOpenMethod)
            } else {
                emptyList()
            }
            val methods = if (cached.isNotEmpty()) {
                cached
            } else {
                val directClasses = listOf("X.0A9u", "X.C0A9u", "p000X.C0A9u")
                    .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
                val discoveredClasses = dexBridge.findMethodsUsingStrings("ClipsOrganicMediaItemViewMoreOptionsController")
                    .map { it.declaringClass }
                (directClasses + discoveredClasses)
                    .distinctBy { it.name }
                    .flatMap { it.declaredMethods.toList() }
                    .filter(::isOldPostReelContextMenuReelOpenMethod)
                    .distinctBy(::methodKey)
                    .also { found -> if (found.isNotEmpty()) InstagramDexKitCache.saveMethods(cacheKey, found) }
            }
            val hookedController = hookOldPostReelContextMenuReelOpenMethods(methods)
            val hookedSource = installOldPostReelContextMenuClipsViewerSourceHook()
            if (hookedController > 0 || hookedSource > 0) {
                val names = methods.take(8)
                    .joinToString { "${it.declaringClass.name}.${it.name}:${it.parameterTypes.size}" }
                logInfo(
                    "Installed old post/reel reel-controller hook(s)=$hookedController " +
                        "sourceHooks=$hookedSource methods=$names"
                )
            } else {
                logInfo("Old post/reel reel-controller hook not found")
            }
        }
    }

    private fun isOldPostReelContextMenuReelOpenMethod(method: Method): Boolean {
        if (method.returnType != java.lang.Void.TYPE) return false
        val params = method.parameterTypes
        if (params.isEmpty() || !View::class.java.isAssignableFrom(params[0])) return false
        if (!Modifier.isStatic(method.modifiers) && params.size == 3) {
            return params.drop(1).all(::isOldPostReelContextMenuControllerParam)
        }
        if (Modifier.isStatic(method.modifiers) && params.size >= 5 && params.any { it == method.declaringClass }) {
            return params.drop(1).all { type ->
                type == java.lang.Boolean.TYPE || isOldPostReelContextMenuControllerParam(type)
            }
        }
        return false
    }

    private fun isOldPostReelContextMenuControllerParam(type: Class<*>): Boolean {
        return !type.isPrimitive &&
            !type.name.startsWith("java.") &&
            !type.name.startsWith("android.")
    }

    private fun hookOldPostReelContextMenuReelOpenMethods(methods: List<Method>): Int {
        var hooked = 0
        val logTimes = ConcurrentHashMap<String, Long>()
        methods.forEach { method ->
            val signature = "${methodKey(method)}:old_context_reel_controller"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.restoreOldPostReelContextMenu) return
                            oldPostReelContextMenuOpenDepth.set(oldPostReelContextMenuOpenDepth.get() + 1)
                            val key = "${method.declaringClass.name}.${method.name}"
                            val now = SystemClock.elapsedRealtime()
                            val previous = logTimes[key] ?: 0L
                            if (now - previous >= 2_000L) {
                                logTimes[key] = now
                                if (logTimes.size > 40) logTimes.clear()
                                val view = param.args?.firstOrNull() as? View
                                val viewLocation = IntArray(2)
                                if (view != null) runCatching { view.getLocationOnScreen(viewLocation) }
                                logInfo(
                                    "Old post/reel reel controller opening method=${method.declaringClass.name}.${method.name} " +
                                        "static=${Modifier.isStatic(method.modifiers)} depth=${oldPostReelContextMenuOpenDepth.get()} " +
                                        "source=${oldPostReelContextMenuControllerSource(param.thisObject)} " +
                                        "view=${view?.javaClass?.name ?: "null"} id=${view?.let(::resourceEntryName).orEmpty()} " +
                                        "shown=${view?.isShown} loc=${viewLocation[0]},${viewLocation[1]} size=${view?.width ?: 0}x${view?.height ?: 0} " +
                                        "args=${param.args?.map { oldPostReelSafeValueSummary(it) }?.joinToString("|")?.take(900).orEmpty()}"
                                )
                            }
                        }

                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            val depth = oldPostReelContextMenuOpenDepth.get()
                            if (depth <= 1) oldPostReelContextMenuOpenDepth.set(0) else oldPostReelContextMenuOpenDepth.set(depth - 1)
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed old post/reel reel-controller hook $signature", it) }
        }
        return hooked
    }

    private fun installOldPostReelContextMenuClipsViewerSourceHook(): Int {
        val sourceClass = findFirstClass(
            "com.instagram.clips.intf.ClipsViewerSource",
            "com.instagram.clips.model.ClipsViewerSource"
        ) ?: return 0
        val methods = sourceClass.declaredMethods
            .filter { method ->
                !Modifier.isStatic(method.modifiers) &&
                    method.name == "A0C" &&
                    method.returnType == java.lang.Boolean.TYPE &&
                    method.parameterTypes.isEmpty()
            }
        var hooked = 0
        val logTimes = ConcurrentHashMap<String, Long>()
        methods.forEach { method ->
            val signature = "${methodKey(method)}:old_context_reel_source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.restoreOldPostReelContextMenu || oldPostReelContextMenuOpenDepth.get() <= 0) return
                            param.result = true
                            val source = param.thisObject?.toString().orEmpty()
                            val now = SystemClock.elapsedRealtime()
                            val previous = logTimes[source] ?: 0L
                            if (now - previous >= 2_000L) {
                                logTimes[source] = now
                                if (logTimes.size > 40) logTimes.clear()
                                logInfo(
                                    "Old post/reel reel source forced classic branch source=$source " +
                                        "depth=${oldPostReelContextMenuOpenDepth.get()} method=${method.declaringClass.name}.${method.name} " +
