    private fun oldPostReelContextInvocationHasMarker(param: XC_MethodHook.MethodHookParam<*>): Boolean {
        param.args?.forEach { arg ->
            if (oldPostReelContextValueHasMarker(arg)) return true
        }
        return oldPostReelContextValueHasMarker(param.thisObject)
    }

    private fun oldPostReelContextMarkerSummary(param: XC_MethodHook.MethodHookParam<*>): String {
        val markers = LinkedHashSet<String>()
        fun collect(value: Any?, depth: Int = 0) {
            if (markers.size >= 6 || value == null || depth > 1) return
            when (value) {
                is String -> if (isOldPostReelContextMarker(value)) markers += value.take(96)
                is Bundle -> value.keySet().forEach { key ->
                    if (isOldPostReelContextMarker(key)) markers += key.take(96)
                    collect(value.get(key), depth + 1)
                }
                is Map<*, *> -> value.entries.take(12).forEach { entry ->
                    collect(entry.key, depth + 1)
                    collect(entry.value, depth + 1)
                }
            }
        }
        param.args?.forEach(::collect)
        collect(param.thisObject)
        return markers.joinToString("|").ifBlank { "<none>" }
    }

    private fun oldPostReelContextValueHasMarker(value: Any?, depth: Int = 0): Boolean {
        if (value == null || depth > 1) return false
        when (value) {
            is String -> return isOldPostReelContextMarker(value)
            is Bundle -> {
                value.keySet().forEach { key ->
                    if (isOldPostReelContextMarker(key) || oldPostReelContextValueHasMarker(value.get(key), depth + 1)) return true
                }
                return false
            }
            is Map<*, *> -> {
                for (entry in value.entries.take(16)) {
                    if (oldPostReelContextValueHasMarker(entry.key, depth + 1) ||
                        oldPostReelContextValueHasMarker(entry.value, depth + 1)
                    ) return true
                }
                return false
            }
        }
        if (depth >= 1) return false
        val cls = value.javaClass
        if (cls.isPrimitive || cls.isArray || cls.name.startsWith("java.") || cls.name.startsWith("android.")) return false
        return runCatching {
            cls.declaredFields
                .asSequence()
                .filterNot { Modifier.isStatic(it.modifiers) }
                .take(32)
                .any { field ->
                    field.isAccessible = true
                    val fieldValue = field.get(value)
                    fieldValue is String && isOldPostReelContextMarker(fieldValue)
                }
        }.getOrDefault(false)
    }

    private fun isOldPostReelContextMarker(value: String): Boolean {
        val lower = value.lowercase(Locale.US)
        return lower.contains("contextual_entrypoint_overflow_menu") ||
            lower.contains("content_deep_dive") ||
            lower.contains("contentdeepdive") ||
            lower.contains("feed_content_deep_dive") ||
            lower.contains("reels_viewer_content_deep_dive") ||
            lower == "content_deep_dive"
    }

