    private fun hookOldPostReelContextMenuListFilterMethods(methods: List<Method>, source: String): Int {
        var hooked = 0
        val logTimes = ConcurrentHashMap<String, Long>()
        val classicOptions = setOf("COPY_LINK", "COPY_FUNDRAISER_LINK", "SHARE_LINK", "SHARE", "SAVE", "UNSAVE")
        val reducedOptions = setOf("WHY_AM_I_SEEING_THIS", "SEE_MORE", "SEE_FEWER", "ABOUT_THIS_ACCOUNT", "REPORT")
        val optionClassName = "com.instagram.feed.media.mediaoption.MediaOption\$Option"

        fun optionName(value: Any?): String? {
            if (value == null) return null
            if (value.javaClass.name == optionClassName) return value.toString()
            var cls: Class<*>? = value.javaClass
            while (cls != null && cls != Any::class.java) {
                cls.declaredFields.firstOrNull { field -> field.type.name == optionClassName }?.let { field ->
                    return runCatching {
                        field.isAccessible = true
                        field.get(value)?.toString()
                    }.getOrNull()
                }
                cls = cls.superclass
            }
            return null
        }

        fun optionNames(list: List<*>?): List<String> = list.orEmpty().mapNotNull(::optionName)

        fun hasOldMenuSignature(options: List<String>): Boolean {
            return options.any { it in classicOptions } && options.any { it in reducedOptions }
        }

        fun logFilter(method: Method, input: List<String>, current: List<String>, restored: List<String>) {
            val key = "${method.declaringClass.name}.${method.name}:${input.joinToString("|")}:${current.joinToString("|")}"
            val now = SystemClock.elapsedRealtime()
            val previous = logTimes[key] ?: 0L
            if (now - previous < 2_000L) return
            logTimes[key] = now
            if (logTimes.size > 80) logTimes.clear()
            logInfo(
                "Old post/reel context menu list filter restored method=${method.declaringClass.name}.${method.name} " +
                    "input=${input.size}:${input.joinToString("|").take(260)} " +
                    "current=${current.size}:${current.joinToString("|").take(220)} " +
                    "restored=${restored.size}:${restored.joinToString("|").take(260)}"
            )
        }

        methods.forEach { method ->
            val signature = "${methodKey(method)}:old_context_list_filter_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            if (!state.restoreOldPostReelContextMenu) return
                            val inputRows = param.args.getOrNull(0) as? List<*> ?: return
                            val inputOptions = optionNames(inputRows)
                            if (!hasOldMenuSignature(inputOptions)) return
                            val currentOptions = optionNames(param.result as? List<*>)
                            if (currentOptions.any { it in classicOptions } &&
                                currentOptions.size >= inputOptions.size &&
                                currentOptions.none { it == "QR_CODE" }
                            ) return

                            val restoredRows = java.util.ArrayList<Any?>()
                            val seenOptions = LinkedHashSet<String>()
                            val droppedOptions = mutableListOf<String>()
                            inputRows.forEach { row ->
                                val option = optionName(row) ?: return@forEach
                                if (option == "QR_CODE") {
                                    droppedOptions += option
                                    return@forEach
                                }
                                if (seenOptions.add(option)) restoredRows += row
                            }
                            if (restoredRows.isEmpty()) return
                            val restoredOptions = optionNames(restoredRows)
                            param.result = restoredRows
                            logFilter(method, inputOptions, currentOptions, restoredOptions + droppedOptions.map { "dropped:$it" })
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed old post/reel context list-filter hook $signature", it) }
        }
        return hooked
    }

