        val dividerClass = findFirstClass("X.ORl", "X.C61862ORl")

        methods.forEach { method ->
            val cvvClass = method.parameterTypes.getOrNull(1) ?: return@forEach
            val iconMethod = method.declaringClass.declaredMethods.firstOrNull { candidate ->
                candidate.returnType == java.lang.Void.TYPE &&
                    candidate.parameterTypes.size == 2 &&
                    candidate.parameterTypes[0] == optionClass &&
                    candidate.parameterTypes[1] == cvvClass
            }?.apply { isAccessible = true }
            val rowMethod = method.declaringClass.declaredMethods.firstOrNull { candidate ->
                val params = candidate.parameterTypes
                candidate.returnType == java.lang.Void.TYPE &&
                    params.size == 4 &&
                    params[0] == optionClass &&
                    params[1] == cvvClass &&
                    params[2] == java.lang.Integer::class.java &&
                    params[3] == String::class.java
            }?.apply { isAccessible = true }
            if (iconMethod == null || rowMethod == null) {
                logInfo(
                    "Old post/reel classic sheet add-methods missing show=${method.declaringClass.name}.${method.name} " +
                        "icon=${iconMethod != null} row=${rowMethod != null}"
                )
                return@forEach
            }

            val signature = "${methodKey(method)}:old_context_classic_sheet_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.restoreOldPostReelContextMenu) return
                            val helper = param.thisObject ?: return
                            val sheetModel = param.args.getOrNull(1) ?: return
                            val anchorView = param.args.getOrNull(0) as? View
                            val handled = rewriteOldPostReelClassicSheetModel(
                                context = anchorView?.context,
                                helper = helper,
                                sheetModel = sheetModel,
                                optionClass = optionClass,
                                iconMethod = iconMethod,
                                rowMethod = rowMethod,
                                dividerClass = dividerClass,
                                showMethod = method,
                                logTimes = logTimes
                            )
                            if (handled) param.result = null
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed old post/reel classic sheet hook $signature", it) }
        }
        return hooked
    }

    private fun rewriteOldPostReelClassicSheetModel(
        context: Context?,
        helper: Any,
        sheetModel: Any,
        optionClass: Class<*>,
        iconMethod: Method,
        rowMethod: Method,
        dividerClass: Class<*>?,
        showMethod: Method,
        logTimes: ConcurrentHashMap<String, Long>
    ): Boolean {
        val originalSummary = oldPostReelSheetModelSummary(sheetModel)
        val hasThreeIconRail =
            originalSummary.contains("SHARE|COPY_LINK|SAVE") ||
                originalSummary.contains("SHARE_LINK|COPY_LINK|SAVE") ||
                originalSummary.contains("SHARE|COPY_FUNDRAISER_LINK|SAVE") ||
                originalSummary.contains("SHARE_LINK|COPY_FUNDRAISER_LINK|SAVE")
        val hasQrIcon = originalSummary.contains("QR_CODE")
        if (hasThreeIconRail && !hasQrIcon) {
            logOldPostReelBottomSheetRewrite(
                logTimes,
                "classic_already_icon_rail:${showMethod.declaringClass.name}.${showMethod.name}:${originalSummary.take(160)}",
                "Old post/reel classic sheet already icon rail method=${showMethod.declaringClass.name}.${showMethod.name} " +
                    "summary=${originalSummary.take(360)}"
            )
            return false
        }

        fun option(name: String): Any? =
            optionClass.enumConstants?.firstOrNull { it.toString() == name }

        val primaryList = oldPostReelPrimarySheetList(sheetModel) as? MutableList<Any?>
        val actionHeader = oldPostReelActionSheetLists(sheetModel).firstOrNull()
        val headerClickFallbacks = LinkedHashMap<String, View.OnClickListener>()
        val headerActionMethod = oldPostReelHeaderActionMethod(oldPostReelDeclaredMethodsInHierarchy(sheetModel.javaClass))
            ?.apply { isAccessible = true }
        val expectedPrimaryRowClassName = primaryList?.firstOrNull { it != null }?.javaClass?.name

        fun compatibleAddedRows(list: MutableList<Any?>, added: List<Any?>, source: String): List<Any?> {
            val expected = expectedPrimaryRowClassName ?: return added.filterNotNull()
            val compatible = ArrayList<Any?>(added.size)
            added.forEach { row ->
                if (row != null && row.javaClass.name == expected) {
                    compatible += row
                } else {
                    list.remove(row)
                    logInfo(
                            "Old post/reel classic row removed reason=incompatible_row source=$source " +
                            "expected=$expected actual=${row?.javaClass?.name ?: "null"} " +
                            "label=${context?.let { oldPostReelSheetRowLabel(it, row) }.orEmpty()}"
                    )
                }
            }
            return compatible
        }

        fun iconDrawableForOption(option: Any?): Int =
            runCatching { option?.javaClass?.getMethod("getIconDrawable")?.invoke(option) as? Int ?: 0 }.getOrDefault(0)

        fun invokeHeaderIcon(names: List<String>, label: String): String? {
            val list = primaryList ?: return null
            val ctx = context ?: return null
            for (name in names) {
                val value = option(name) ?: continue
                val beforeSize = list.size
                val added = runCatching {
                    iconMethod.invoke(helper, value, sheetModel)
                    list.drop(beforeSize)
                }.onFailure { logError("Old post/reel classic icon add failed option=$name", it) }
                    .getOrDefault(emptyList())
                val row = added.firstOrNull()
                added.forEach { list.remove(it) }
                if (row == null) continue
                val rawListener = oldPostReelSheetRowClick(row)
                if (rawListener == null) {
                    logInfo("Old post/reel classic header icon missing listener option=$name row=${row.javaClass.name}")
                    continue
                }
                val icon = oldPostReelSheetRowIcon(row).takeIf { it != 0 } ?: iconDrawableForOption(value)
                val listener = View.OnClickListener { view ->
                    logOldPostReelBottomSheetRewrite(
                        logTimes,
                        "classic_header_click:${showMethod.declaringClass.name}.${showMethod.name}:$label:$name",
                        "Old post/reel classic sheet header click dispatch label=$label option=$name " +
                            "method=${showMethod.declaringClass.name}.${showMethod.name}"
                    )
                    rawListener.onClick(view)
                }
                val headerMethod = headerActionMethod
                if (headerMethod != null) {
                    val callbackBase = headerMethod.parameterTypes[1]
                    val callback = createOldPostReelHeaderCallback(listener, callbackBase)
                    if (callback != null) {
                        val actionKey = label.lowercase(Locale.US)
                            .replace(Regex("[^a-z0-9_]+"), "_")
                            .trim('_')
                            .ifBlank { name.lowercase(Locale.US) }
                        val invoked = runCatching {
                            headerMethod.invoke(sheetModel, ctx, callback, actionKey, label, label, 1.0f, icon, true)
                            true
                        }.onFailure {
                            logError("Old post/reel classic header method invoke failed option=$name label=$label method=${headerMethod.name}", it)
                        }.getOrDefault(false)
                        if (invoked) {
                            headerClickFallbacks[oldPostReelNormalizeSheetLabel(label)] = listener
                            logOldPostReelBottomSheetRewrite(
                                logTimes,
                                "classic_header_icon:${showMethod.declaringClass.name}.${showMethod.name}:$label:$name",
                                "Old post/reel classic sheet header icon added label=$label option=$name icon=$icon " +
                                    "path=method:${headerMethod.name} callback=${callback.javaClass.name}"
                            )
                            return name
                        }
                    } else {
                        logInfo(
                            "Old post/reel classic header callback create failed option=$name label=$label " +
                                "base=${oldPostReelTypeSummary(callbackBase, 520)}"
                        )
                    }
                }
                val header = actionHeader
                val action = createOldPostReelHeaderAction(
                    ctx,
                    label,
                    icon,
                    listener,
                    headerActionMethod?.parameterTypes?.getOrNull(1)
                )
                if (action == null || header == null) {
                    logInfo(
                        "Old post/reel classic header action create failed option=$name label=$label icon=$icon " +
                            "headerMethod=${headerActionMethod?.name} actionHeader=${header != null}"
                    )
                    continue
                }
                header.add(action)
                headerClickFallbacks[oldPostReelNormalizeSheetLabel(label)] = listener
                logOldPostReelBottomSheetRewrite(
                    logTimes,
                    "classic_header_icon:${showMethod.declaringClass.name}.${showMethod.name}:$label:$name",
                    "Old post/reel classic sheet header icon added label=$label option=$name icon=$icon " +
                        "path=action row=${row.javaClass.name} headerSize=${header.size}"
                )
                return name
            }
            return null
        }

        fun invokeIcon(name: String): Boolean {
            val value = option(name) ?: return false
            return runCatching {
                iconMethod.invoke(helper, value, sheetModel)
                true
            }.onFailure { logError("Old post/reel classic icon add failed option=$name", it) }.getOrDefault(false)
        }

        fun invokeRow(name: String): Boolean {
            val value = option(name) ?: return false
            val list = primaryList ?: return false
            val beforeSize = list.size
            return runCatching {
                rowMethod.invoke(helper, value, sheetModel, null, null)
                compatibleAddedRows(list, list.drop(beforeSize), "row:$name").isNotEmpty()
            }.onFailure {
                compatibleAddedRows(list, list.drop(beforeSize), "row:$name:failure")
                logError("Old post/reel classic row add failed option=$name", it)
            }.getOrDefault(false)
        }

        fun createCustomHeaderAction(names: List<String>, label: String): OldPostReelMenuAction? {
            val list = primaryList ?: return null
            for (name in names) {
                val value = option(name) ?: continue
                val beforeSize = list.size
                val added = runCatching {
                    iconMethod.invoke(helper, value, sheetModel)
                    list.drop(beforeSize)
                }.onFailure { logError("Old post/reel custom classic icon create failed option=$name", it) }
                    .getOrDefault(emptyList())
                val row = added.firstOrNull()
                added.forEach { list.remove(it) }
                if (row == null) continue
                val rawListener = oldPostReelSheetRowClick(row) ?: continue
                val icon = oldPostReelSheetRowIcon(row).takeIf { it != 0 } ?: iconDrawableForOption(value)
                val listener = View.OnClickListener { view ->
                    logOldPostReelBottomSheetRewrite(
                        logTimes,
                        "classic_custom_header_click:${showMethod.declaringClass.name}.${showMethod.name}:$label:$name",
                        "Old post/reel classic custom header click dispatch label=$label option=$name"
                    )
                    rawListener.onClick(view)
                }
                return OldPostReelMenuAction(name, label, icon, listener, enabled = true)
            }
            return null
        }

        fun createCustomRowAction(
            names: List<String>,
            labelOverride: String? = null,
            dividerBefore: Boolean = false
        ): OldPostReelMenuAction? {
            val list = primaryList ?: return null
            val ctx = context ?: androidContext
            for (name in names) {
                val value = option(name) ?: continue
                val beforeSize = list.size
                val added = runCatching {
                    rowMethod.invoke(helper, value, sheetModel, null, null)
                    compatibleAddedRows(list, list.drop(beforeSize), "custom_row:$name")
                }.onFailure {
                    compatibleAddedRows(list, list.drop(beforeSize), "custom_row:$name:failure")
                    logError("Old post/reel custom classic row create failed option=$name", it)
                }.getOrDefault(emptyList())
                val row = added.firstOrNull()
                added.forEach { list.remove(it) }
                if (row == null) continue
                val rawListener = oldPostReelSheetRowClick(row) ?: continue
                val label = labelOverride ?: oldPostReelSheetRowLabel(ctx, row)?.takeIf { it.isNotBlank() }
                    ?: oldPostReelLabelForOption(name)
                val icon = oldPostReelSheetRowIcon(row).takeIf { it != 0 } ?: iconDrawableForOption(value)
                val destructive = name == "REPORT" || name.contains("DELETE") || name.contains("REMOVE")
                val listener = View.OnClickListener { view ->
                    logOldPostReelBottomSheetRewrite(
                        logTimes,
                        "classic_custom_row_click:${showMethod.declaringClass.name}.${showMethod.name}:$label:$name",
                        "Old post/reel classic custom row click dispatch label=$label option=$name"
                    )
                    rawListener.onClick(view)
                }
                return OldPostReelMenuAction(
                    optionName = name,
                    label = label,
                    icon = icon,
                    listener = listener,
                    destructive = destructive,
                    enabled = true,
                    dividerBefore = dividerBefore
                )
            }
            return null
        }

        fun classicSheetLooksReel(): Boolean {
            val sinceReelMenuMs = SystemClock.elapsedRealtime() - lastReelDownloadMenuBuildAtMs
            return sinceReelMenuMs in 0L..3_000L ||
                isReelsAutoplaySurfaceActive() ||
                helper.javaClass.name.contains("clips", ignoreCase = true) ||
                originalSummary.contains("clips", ignoreCase = true) ||
                originalSummary.contains("0LtM", ignoreCase = true)
        }

        fun addControlledReelDownloadRow(): Boolean {
            val list = primaryList ?: return false
            val ctx = context ?: return false
            val activity = findActivity(ctx) ?: currentActivity ?: return false
            val media = findMediaObject(helper)
                ?: findMediaObject(sheetModel)
                ?: lastReelDownloadMediaRef?.get()
                ?: return false.also {
                    logInfo("Old post/reel controlled reel row skipped reason=media_missing helper=${helper.javaClass.name}")
                }
            val controller = lastReelDownloadControllerRef?.get() ?: helper
            val templateOption = option("WHY_AM_I_SEEING_THIS")
                ?: option("ABOUT_THIS_ACCOUNT")
                ?: option("REPORT")
                ?: return false
            val beforeSize = list.size
            val added = runCatching {
                rowMethod.invoke(helper, templateOption, sheetModel, null, null)
                compatibleAddedRows(list, list.drop(beforeSize), "controlled_reel_download_template")
            }.onFailure {
                compatibleAddedRows(list, list.drop(beforeSize), "controlled_reel_download_template:failure")
                logError("Old post/reel controlled reel row template add failed", it)
            }.getOrDefault(emptyList())
            val row = added.firstOrNull() ?: return false.also {
                logInfo("Old post/reel controlled reel row skipped reason=template_row_missing")
            }
            added.drop(1).forEach { list.remove(it) }
            val offeredAtMs = SystemClock.elapsedRealtime()
            val listener = View.OnClickListener {
                val ageMs = SystemClock.elapsedRealtime() - offeredAtMs
                if (ageMs in 0L..650L) {
                    logOldPostReelBottomSheetRewrite(
                        logTimes,
                        "classic_controlled_reel_download_initial_click:${showMethod.declaringClass.name}.${showMethod.name}",
                        "Old post/reel controlled reel download click suppressed reason=initial_sheet_guard ageMs=$ageMs"
                    )
                    return@OnClickListener
                }
                handleReelDownloadClick(activity, media, controller)
            }
            val labelSet = oldPostReelSetSheetRowLabel(row, "Download")
            val clickSet = oldPostReelSetSheetRowClick(row, listener)
            val iconSet = oldPostReelSetSheetRowIcon(row, resolveMediaOptionDownloadIcon(ctx))
            if (!labelSet || !clickSet) {
                list.remove(row)
                logInfo(
                    "Old post/reel controlled reel row removed reason=mutate_failed " +
                        "labelSet=$labelSet clickSet=$clickSet iconSet=$iconSet row=${row.javaClass.name}"
                )
                return false
            }
            logDownloadControlGate("reel_classic_sheet_row", "offered")
            logOldPostReelBottomSheetRewrite(
                logTimes,
                "classic_controlled_reel_download_added:${showMethod.declaringClass.name}.${showMethod.name}",
                "Old post/reel controlled reel row added row=${row.javaClass.name} iconSet=$iconSet " +
                    "media=${media.javaClass.name} controller=${controller.javaClass.name}"
            )
            return true
        }

        val reelSheet = classicSheetLooksReel()
        val customHeaderActions = listOfNotNull(
            createCustomHeaderAction(listOf("SHARE_LINK", "SHARE"), "Share"),
            createCustomHeaderAction(listOf("COPY_LINK", "COPY_FUNDRAISER_LINK"), "Link"),
            createCustomHeaderAction(listOf("SAVE", "UNSAVE"), "Save")
        )
        val customRowActions = mutableListOf<OldPostReelMenuAction>()
        if (reelSheet && (state.enableReelDownload || state.enableReelThumbnailDownload) && shouldOfferDownloadContextMenu()) {
            createCustomRowAction(listOf("DOWNLOAD"), "Download")?.let { customRowActions += it }
        } else if (!reelSheet && state.enablePostDownload && shouldOfferDownloadContextMenu()) {
            val nativeDownload = createCustomRowAction(listOf("DOWNLOAD", "0LtM"), "Download")
            if (nativeDownload != null) {
                customRowActions += nativeDownload
            } else {
                context?.let { ctx ->
                    createOldPostReelPostDownloadAction(
                        context = ctx,
                        media = findMediaObject(helper) ?: findMediaObject(sheetModel),
                        fallbackRoot = helper,
                        source = "classic_fast:${showMethod.declaringClass.name}.${showMethod.name}",
                        logStage = { stage, detail ->
                            logOldPostReelBottomSheetRewrite(
                                logTimes,
                                "classic_post_download:$stage:${showMethod.declaringClass.name}.${showMethod.name}",
                                detail()
                            )
                        }
                    )?.let { customRowActions += it }
                }
            }
        }
        createCustomRowAction(listOf("WHY_AM_I_SEEING_THIS"), "Why you're seeing this post")?.let { customRowActions += it }
        createCustomRowAction(listOf("NOT_INTERESTED", "SEE_FEWER", "SEE_FEWER_CONNECTED"), "Not interested")?.let { customRowActions += it }
        createCustomRowAction(listOf("INTERESTED", "SEE_MORE"), "Interested")?.let { customRowActions += it }
        if (!reelSheet) {
            createCustomRowAction(listOf("ABOUT_THIS_ACCOUNT"), "About this account")?.let { customRowActions += it }
        }
        createCustomRowAction(listOf("REPORT"), "Report")?.let { customRowActions += it }
        createCustomRowAction(
            listOf("MANAGE_SUGGESTED_CONTENT", "MANAGE_SUGGESTED_CONTENT_CARRERA", "SEE_YOUR_ALGORITHM"),
            "Manage content preferences",
            dividerBefore = customRowActions.isNotEmpty()
        )?.let { customRowActions += it }

        if (context != null && customHeaderActions.size >= 3 && customRowActions.isNotEmpty()) {
            if (showOldPostReelCustomContextMenu(
                    context,
                    customHeaderActions,
                    customRowActions,
                    "classic_fast:${showMethod.declaringClass.name}.${showMethod.name}"
                )
            ) {
                logOldPostReelBottomSheetRewrite(
                    logTimes,
                    "classic_custom_shown:${showMethod.declaringClass.name}.${showMethod.name}:${customHeaderActions.size}:${customRowActions.size}",
                    "Old post/reel classic custom sheet shown headers=${customHeaderActions.joinToString("|") { it.optionName }} " +
                        "rows=${customRowActions.joinToString("|") { it.optionName }} reelSheet=$reelSheet " +
                        "before=${originalSummary.take(320)}"
                )
                return true
            }
        }

        clearOldPostReelSheetModel(sheetModel)

        val iconRequests = listOf(
            "Share" to listOf("SHARE_LINK", "SHARE"),
            "Link" to listOf("COPY_LINK", "COPY_FUNDRAISER_LINK"),
            "Save" to listOf("SAVE", "UNSAVE")
        )
        val icons = iconRequests.mapNotNull { (label, names) ->
            invokeHeaderIcon(names, label)
                ?: names.firstOrNull(::invokeIcon)
        }
        val controlledReelDownloadAdded =
            reelSheet &&
                (state.enableReelDownload || state.enableReelThumbnailDownload) &&
                shouldOfferDownloadContextMenu() &&
                addControlledReelDownloadRow()
        if (reelSheet && !controlledReelDownloadAdded) {
            logDownloadControlGate("reel_classic_sheet_row", "suppressed")
        }
        val classicInfoRows = if (reelSheet) {
            // ABOUT_THIS_ACCOUNT appends an incompatible row class on this Reels sheet variant.
            listOf("WHY_AM_I_SEEING_THIS", "NOT_INTERESTED", "INTERESTED", "REPORT")
        } else {
            listOf("WHY_AM_I_SEEING_THIS", "NOT_INTERESTED", "INTERESTED", "ABOUT_THIS_ACCOUNT", "REPORT")
        }
        val rowRequestsBeforeDivider =
            (if (!reelSheet && state.enablePostDownload && shouldOfferDownloadContextMenu()) listOf("DOWNLOAD") else emptyList()) +
                classicInfoRows
        val rowsBeforeDivider = rowRequestsBeforeDivider.filter(::invokeRow)
        val dividerAdded = !reelSheet && addOldPostReelClassicSheetDivider(sheetModel, dividerClass)
        val rowsAfterDivider = listOf("MANAGE_SUGGESTED_CONTENT").filter(::invokeRow)

        if (context != null && headerClickFallbacks.isNotEmpty()) {
            scheduleOldPostReelHeaderClickFallback(context, headerClickFallbacks)
        }

        val key = "${showMethod.declaringClass.name}.${showMethod.name}:${icons.joinToString("|")}:${rowsBeforeDivider.joinToString("|")}:${rowsAfterDivider.joinToString("|")}"
        val now = SystemClock.elapsedRealtime()
        val previous = logTimes[key] ?: 0L
        if (now - previous >= 2_000L) {
            logTimes[key] = now
            if (logTimes.size > 60) logTimes.clear()
            logInfo(
                "Old post/reel classic sheet restored method=${showMethod.declaringClass.name}.${showMethod.name} " +
                    "icons=${icons.joinToString("|")} rows=${(rowsBeforeDivider + rowsAfterDivider).joinToString("|")} " +
                    "reelSheet=$reelSheet controlledReelDownload=$controlledReelDownloadAdded " +
                    "headerMethod=${headerActionMethod?.name}:${headerActionMethod?.parameterTypes?.getOrNull(1)?.name} " +
                    "headerFallbacks=${headerClickFallbacks.keys.joinToString("|")} divider=$dividerAdded " +
                    "before=${originalSummary.take(260)} after=${oldPostReelSheetModelSummary(sheetModel).take(320)}"
            )
        }
        return false
    }

    private fun clearOldPostReelSheetModel(sheetModel: Any) {
        sheetModel.javaClass.declaredFields
            .filterNot { Modifier.isStatic(it.modifiers) }
            .forEach { field ->
                runCatching {
                    field.isAccessible = true
                    val value = field.get(sheetModel)
                    if (value is MutableList<*>) {
                        value.clear()
                    } else if (!Modifier.isFinal(field.modifiers) && CharSequence::class.java.isAssignableFrom(field.type)) {
                        field.set(sheetModel, null)
                    }
                }
            }
    }

    private fun addOldPostReelClassicSheetDivider(sheetModel: Any, dividerClass: Class<*>?): Boolean {
        val list = oldPostReelPrimarySheetList(sheetModel) ?: return false
        val divider = runCatching {
            dividerClass?.getDeclaredConstructor()?.apply { isAccessible = true }?.newInstance()
        }.getOrNull() ?: return false
        return runCatching {
            @Suppress("UNCHECKED_CAST")
            (list as MutableList<Any?>).add(divider)
            true
        }.getOrDefault(false)
    }

    private fun oldPostReelPrimarySheetList(sheetModel: Any): MutableList<*>? {
        val fields = oldPostReelDeclaredFieldsInHierarchy(sheetModel.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .onEach { it.isAccessible = true }
        fields.firstOrNull { java.util.LinkedList::class.java.isAssignableFrom(it.type) }?.let { field ->
            (runCatching { field.get(sheetModel) }.getOrNull() as? MutableList<*>)?.let { return it }
        }
        fields.firstOrNull { java.util.List::class.java.isAssignableFrom(it.type) }?.let { field ->
            return runCatching { field.get(sheetModel) }.getOrNull() as? MutableList<*>
        }
        return null
    }

    private fun oldPostReelSheetModelSummary(sheetModel: Any): String {
        return runCatching {
            oldPostReelDeclaredFieldsInHierarchy(sheetModel.javaClass)
                .filterNot { Modifier.isStatic(it.modifiers) }
                .mapNotNull { field ->
                    field.isAccessible = true
                    val value = field.get(sheetModel)
                    when (value) {
                        is List<*> -> {
                            val itemNames = value.mapNotNull(::oldPostReelSheetItemName).joinToString("|").take(160)
                            "${field.name}=${value.size}[$itemNames]"
                        }
                        is CharSequence -> "${field.name}=${value.toString().take(80)}"
                        else -> null
                    }
                }
                .joinToString(";")
        }.getOrDefault("<summary-error>")
    }

    private fun oldPostReelDeclaredFieldsInHierarchy(type: Class<*>): List<Field> {
        val fields = ArrayList<Field>()
        var current: Class<*>? = type
        while (current != null && current != Any::class.java) {
            fields += current.declaredFields
            current = current.superclass
        }
        return fields
    }

    private fun oldPostReelDeclaredMethodsInHierarchy(type: Class<*>): List<Method> {
        val methods = ArrayList<Method>()
        var current: Class<*>? = type
        while (current != null && current != Any::class.java) {
            methods += current.declaredMethods
            current = current.superclass
        }
        return methods
    }

    private fun oldPostReelMethodSummary(methods: Collection<Method>, maxChars: Int = 360): String =
        methods.joinToString("|") { method ->
            "${method.declaringClass.name}.${method.name}:${method.parameterTypes.joinToString(",") { it.name }}->${method.returnType.name}"
        }.take(maxChars)

    private fun installOldPostReelContextMenuBottomSheetModelHook() {
        runSafe("Old post/reel bottom sheet model hook") {
            val presenterClass = findFirstClass("X.PLg", "X.C64246PLg")
            if (presenterClass == null) {
                logInfo("Old post/reel bottom sheet model hook presenter class not found")
                return@runSafe
            }
            val methods = presenterClass.declaredMethods.filter { method ->
                method.returnType == java.lang.Void.TYPE &&
                    method.parameterTypes.size == 1 &&
                    Context::class.java.isAssignableFrom(method.parameterTypes[0])
            }
            val logTimes = ConcurrentHashMap<String, Long>()
            var hooked = 0
            methods.forEach { method ->
                val signature = "${methodKey(method)}:old_context_bottom_sheet_model"
                if (!hookedDexMethods.add(signature)) return@forEach
                runCatching {
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                if (!state.restoreOldPostReelContextMenu) return
                                val presenter = param.thisObject ?: return
                                val context = param.args.firstOrNull() as? Context ?: return
                                val sheetModel = oldPostReelField(presenter, "A09") ?: return
                                if (tryShowOldPostReelCustomFromSheetModelRows(context, sheetModel, method, logTimes)) {
                                    param.result = null
                                    return
                                }
                                rewriteOldPostReelBottomSheetModel(context, sheetModel, method, logTimes)
                            }
                        }
                    )
                    hooked++
                }.onFailure { logError("Failed old post/reel bottom sheet model hook $signature", it) }
            }
            logInfo("Installed old post/reel bottom sheet model hook(s)=$hooked class=${presenterClass.name}")
        }
    }

    private fun tryShowOldPostReelCustomFromSheetModelRows(
        context: Context,
        sheetModel: Any,
        showMethod: Method,
        logTimes: ConcurrentHashMap<String, Long>
    ): Boolean {
        val primaryList = oldPostReelPrimarySheetList(sheetModel) as? MutableList<Any?> ?: return false
        if (primaryList.isEmpty()) return false
        val originalRows = primaryList.toList()
        val used = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())

        fun rowLabel(row: Any?): String = oldPostReelSheetRowLabel(context, row).orEmpty()
        fun normalized(row: Any?): String = oldPostReelNormalizeSheetLabel(rowLabel(row))
        fun optionName(row: Any?): String = oldPostReelSheetItemName(row).orEmpty()
        fun matchesAny(value: String, names: Set<String>): Boolean =
            names.any { wanted -> value.equals(wanted, ignoreCase = true) }

        fun takeRow(
            optionNames: Set<String>,
            labelMatches: Set<String> = emptySet(),
            labelPredicate: (String) -> Boolean = { false }
        ): Any? {
            val row = originalRows.firstOrNull { candidate ->
                candidate != null &&
                    candidate !in used &&
                    (
                        matchesAny(optionName(candidate), optionNames) ||
                            normalized(candidate) in labelMatches ||
                            labelPredicate(normalized(candidate))
                        )
            } ?: return null
            used += row
            return row
        }

        fun buildAction(
            row: Any,
            label: String,
            preferredOptionName: String,
            destructive: Boolean = false,
            dividerBefore: Boolean = false
        ): OldPostReelMenuAction? {
            val rawListener = oldPostReelSheetRowClick(row) ?: return null
            val rawOptionName = optionName(row)
            val resolvedOptionName = rawOptionName.takeIf { raw ->
                raw.isNotBlank() &&
                    (
                        raw == "0LtM" ||
                            raw.contains('_') ||
                            raw == raw.uppercase(Locale.US)
                        )
            } ?: preferredOptionName
            val listener = View.OnClickListener { view ->
                logOldPostReelBottomSheetRewrite(
                    logTimes,
                    "model_custom_click:${showMethod.declaringClass.name}.${showMethod.name}:$label:$resolvedOptionName",
                    "Old post/reel bottom sheet custom row click dispatch label=$label option=$resolvedOptionName " +
                        "method=${showMethod.declaringClass.name}.${showMethod.name}"
                )
                rawListener.onClick(view)
            }
            return OldPostReelMenuAction(
                optionName = resolvedOptionName.ifBlank { preferredOptionName },
                label = label,
                icon = oldPostReelSheetRowIcon(row),
                listener = listener,
                destructive = destructive,
                enabled = true,
                dividerBefore = dividerBefore
            )
        }

        val shareRow = takeRow(
            setOf("SHARE_LINK", "SHARE"),
            setOf("share", "share to", "send to")
        )
        val linkRow = takeRow(
            setOf("COPY_LINK", "COPY_FUNDRAISER_LINK"),
            setOf("link", "copy link", "copy fundraiser link")
        )
        val saveRow = takeRow(
            setOf("SAVE", "UNSAVE"),
            setOf("save", "saved", "unsave")
        )
        val headerActions = listOfNotNull(
            shareRow?.let { buildAction(it, "Share", "SHARE_LINK") },
            linkRow?.let { buildAction(it, "Link", "COPY_LINK") },
            saveRow?.let { buildAction(it, "Save", "SAVE") }
        )
        if (headerActions.size < 3) return false

        val rowActions = mutableListOf<OldPostReelMenuAction>()
        val nativeDownloadRow = takeRow(setOf("DOWNLOAD", "0LtM"), setOf("download"))
        if (nativeDownloadRow != null) {
            buildAction(nativeDownloadRow, "Download", "DOWNLOAD")?.let(rowActions::add)
        } else if (!isReelsAutoplaySurfaceActive()) {
            createOldPostReelPostDownloadAction(
                context = context,
                media = findMediaObject(sheetModel),
                fallbackRoot = sheetModel,
                source = "model_rows:${showMethod.declaringClass.name}.${showMethod.name}",
                logStage = { stage, detail ->
                    logOldPostReelBottomSheetRewrite(
                        logTimes,
                        "model_post_download:$stage:${showMethod.declaringClass.name}.${showMethod.name}",
                        detail()
                    )
                }
            )?.let(rowActions::add)
        }
        takeRow(
            setOf("WHY_AM_I_SEEING_THIS"),
            setOf("why you're seeing this post", "why you are seeing this post"),
            { it.startsWith("why ") }
        )?.let {
            buildAction(it, "Why you're seeing this post", "WHY_AM_I_SEEING_THIS")?.let(rowActions::add)
        }
        takeRow(
            setOf("NOT_INTERESTED", "SEE_FEWER", "SEE_FEWER_CONNECTED"),
            setOf("not interested", "see fewer", "see fewer like this")
        )?.let {
            buildAction(it, "Not interested", "SEE_FEWER")?.let(rowActions::add)
        }
        takeRow(
            setOf("INTERESTED", "SEE_MORE"),
            setOf("interested", "see more", "see more like this")
        )?.let {
            buildAction(it, "Interested", "SEE_MORE")?.let(rowActions::add)
        }
        takeRow(setOf("ABOUT_THIS_ACCOUNT"), setOf("about this account"))?.let {
            buildAction(it, "About this account", "ABOUT_THIS_ACCOUNT")?.let(rowActions::add)
        }
        takeRow(setOf("REPORT"), setOf("report"))?.let {
            buildAction(it, "Report", "REPORT", destructive = true)?.let(rowActions::add)
        }
        takeRow(
            setOf("MANAGE_SUGGESTED_CONTENT", "MANAGE_SUGGESTED_CONTENT_CARRERA", "SEE_YOUR_ALGORITHM"),
            setOf("manage content preferences", "manage suggested content", "see your algorithm")
        )?.let {
            buildAction(
                it,
                "Manage content preferences",
                "MANAGE_SUGGESTED_CONTENT",
                dividerBefore = rowActions.isNotEmpty()
            )?.let(rowActions::add)
        }
        if (rowActions.isEmpty()) return false

        val sawPostReelRows = rowActions.any {
            it.optionName in setOf(
                "WHY_AM_I_SEEING_THIS",
                "SEE_FEWER",
                "SEE_MORE",
                "ABOUT_THIS_ACCOUNT",
                "REPORT",
                "MANAGE_SUGGESTED_CONTENT",
                "MANAGE_SUGGESTED_CONTENT_CARRERA",
                "SEE_YOUR_ALGORITHM"
            )
        }
        if (!sawPostReelRows) return false

        val shown = showOldPostReelCustomContextMenu(
            context,
            headerActions,
            rowActions,
            "model_rows:${showMethod.declaringClass.name}.${showMethod.name}"
        )
        if (shown) {
            logOldPostReelBottomSheetRewrite(
                logTimes,
                "model_custom_shown:${showMethod.declaringClass.name}.${showMethod.name}:${headerActions.size}:${rowActions.size}",
                "Old post/reel bottom sheet custom sheet shown source=model_rows " +
                    "headers=${headerActions.joinToString("|") { it.optionName }} " +
                    "rows=${rowActions.joinToString("|") { it.optionName }} " +
                    "beforeRows=${oldPostReelBottomSheetRowDetails(context, originalRows).take(520)}"
            )
        }
        return shown
    }

    private fun rewriteOldPostReelBottomSheetModel(
        context: Context,
        sheetModel: Any,
        showMethod: Method,
        logTimes: ConcurrentHashMap<String, Long>
    ): Boolean {
        val primaryList = oldPostReelPrimarySheetList(sheetModel) as? MutableList<Any?> ?: return false
        if (primaryList.isEmpty()) return false
        val actionLists = oldPostReelActionSheetLists(sheetModel)
        if (actionLists.isEmpty()) return false

        val originalSummary = oldPostReelSheetModelSummary(sheetModel)
        val existingHeaderLabels = oldPostReelHeaderLabels(context, actionLists)
        if (existingHeaderLabels.containsAll(listOf("share", "link", "save")) &&
            existingHeaderLabels.none { it == "qr code" || it.startsWith("qr code") }
        ) {
            return false
        }

        val originalRows = primaryList.toList()
        val used = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun label(row: Any?): String = oldPostReelSheetRowLabel(context, row).orEmpty()
        fun normalized(row: Any?): String = oldPostReelNormalizeSheetLabel(label(row))
        fun takeRow(predicate: (String) -> Boolean): Any? {
            val row = originalRows.firstOrNull { candidate ->
                candidate != null && candidate !in used && predicate(normalized(candidate))
            } ?: return null
            used += row
            return row
        }

        val share = takeRow { it == "share to" || it == "share" || it == "send to" }
        val link = takeRow { it == "copy link" || it == "link" || it == "copy fundraiser link" }
        val save = takeRow { it == "save" || it == "saved" || it == "unsave" }
        val iconRows = listOfNotNull(
            share?.let { OldPostReelHeaderRow(it, "Share") },
            link?.let { OldPostReelHeaderRow(it, "Link") },
            save?.let { OldPostReelHeaderRow(it, label(it).takeIf(String::isNotBlank) ?: "Save") }
        )
        if (iconRows.size < 3) {
            if (originalRows.any { row ->
                    val name = normalized(row)
                    name in setOf("qr code", "copy link", "share to", "save") ||
                        name.startsWith("why ") ||
                        name == "report"
                }
            ) {
                logOldPostReelBottomSheetRewrite(
                    logTimes,
                    "skip:${showMethod.declaringClass.name}.${showMethod.name}:${originalSummary.take(160)}",
                    "Old post/reel bottom sheet restore skipped reason=missing_icon_rows method=${showMethod.declaringClass.name}.${showMethod.name} " +
                        "rows=${oldPostReelBottomSheetRowDetails(context, originalRows).take(420)}"
                )
            }
            return false
        }

        val actionHeader = actionLists.first()
        actionLists.forEach { it.clear() }
        val createdLabels = mutableListOf<String>()
        val headerClickFallbacks = LinkedHashMap<String, View.OnClickListener>()
        iconRows.forEach { header ->
            val row = header.row
            val rawListener = oldPostReelSheetRowClick(row) ?: return@forEach
            val optionName = oldPostReelSheetItemName(row).orEmpty()
            val listener = View.OnClickListener { view ->
                logOldPostReelBottomSheetRewrite(
                    logTimes,
                    "model_header_click:${showMethod.declaringClass.name}.${showMethod.name}:${header.label}:$optionName",
                    "Old post/reel bottom sheet header click dispatch label=${header.label} option=$optionName " +
                        "method=${showMethod.declaringClass.name}.${showMethod.name}"
                )
                rawListener.onClick(view)
            }
            val icon = oldPostReelSheetRowIcon(row)
            val action = createOldPostReelHeaderAction(context, header.label, icon, listener) ?: return@forEach
            actionHeader.add(action)
            createdLabels += header.label
            headerClickFallbacks[oldPostReelNormalizeSheetLabel(header.label)] = listener
        }
        if (createdLabels.size < 3) {
            actionLists.forEach { it.clear() }
            return false
        }

        val orderedRows = mutableListOf<Any?>()
        fun addTaken(predicate: (String) -> Boolean): Any? =
            takeRow(predicate)?.also { orderedRows += it }

        addTaken { it == "download" }
        addTaken { it.startsWith("why ") || it == "why you're seeing this post" || it == "why you are seeing this post" }
        addTaken { it == "not interested" || it == "see fewer" || it == "see fewer like this" }
        addTaken { it == "interested" || it == "see more" || it == "see more like this" }
        addTaken { it == "about this account" }
        addTaken { it == "report" }
        val manageRow = addTaken {
            it == "manage content preferences" ||
                it == "manage suggested content" ||
                it == "see your algorithm"
        }
        val dividerClass = findFirstClass("X.ORl", "X.C61862ORl")
        if (manageRow != null) {
            orderedRows.remove(manageRow)
            newOldPostReelDivider(dividerClass)?.let { orderedRows += it }
            orderedRows += manageRow
        }

        originalRows.forEach { row ->
            if (row == null || row in used) return@forEach
            val name = normalized(row)
            if (oldPostReelIsHeaderCandidateLabel(name) || oldPostReelIsNewContextMenuLabel(name) || name.isNotBlank()) used += row
        }

        primaryList.clear()
        primaryList.addAll(orderedRows)

        logOldPostReelBottomSheetRewrite(
            logTimes,
            "restore:${showMethod.declaringClass.name}.${showMethod.name}:${createdLabels.joinToString("|")}:${orderedRows.size}:${originalSummary.take(160)}",
            "Old post/reel bottom sheet icon rail restored method=${showMethod.declaringClass.name}.${showMethod.name} " +
                "icons=${createdLabels.joinToString("|")} manage=${manageRow != null} " +
                "beforeRows=${oldPostReelBottomSheetRowDetails(context, originalRows).take(420)} " +
                "after=${oldPostReelSheetModelSummary(sheetModel).take(360)}"
        )
        scheduleOldPostReelHeaderClickFallback(context, headerClickFallbacks)
        return true
    }

    private data class OldPostReelHeaderRow(val row: Any, val label: String)

    private data class OldPostReelMenuAction(
        val optionName: String,
        val label: String,
        val icon: Int,
        val listener: View.OnClickListener,
        val destructive: Boolean = false,
        val enabled: Boolean = true,
        val dividerBefore: Boolean = false
    )

    private fun createOldPostReelPostDownloadAction(
        context: Context,
        media: Any?,
        fallbackRoot: Any?,
        source: String,
        logStage: ((String, () -> String) -> Unit)? = null
    ): OldPostReelMenuAction? {
        if (!state.enablePostDownload || !shouldOfferDownloadContextMenu()) return null
        val resolvedMedia = media ?: findMediaObject(fallbackRoot)
        val offeredAtMs = SystemClock.elapsedRealtime()
        return OldPostReelMenuAction(
            optionName = "DOWNLOAD",
            label = "Download",
            icon = resolveMediaOptionDownloadIcon(context),
            listener = View.OnClickListener {
                val ageMs = SystemClock.elapsedRealtime() - offeredAtMs
                if (ageMs in 0L..120L) {
                    logStage?.invoke("post_download_click_suppressed") {
                        "Old post/reel post download click suppressed source=$source reason=initial_more_tap_guard ageMs=$ageMs"
                    }
                    return@OnClickListener
                }
                logStage?.invoke("post_download_click") {
                    "Old post/reel post download click source=$source media=${resolvedMedia?.javaClass?.name ?: "missing"}"
                }
                handlePostDownloadFromMedia(context, resolvedMedia, fallbackRoot)
            },
            enabled = true
        )
    }

    private fun oldPostReelBottomSystemInset(activity: Activity): Int {
        val decor = activity.window?.decorView
        val inset = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            decor?.rootWindowInsets
                ?.getInsets(android.view.WindowInsets.Type.systemBars())
                ?.bottom ?: 0
        } else {
            @Suppress("DEPRECATION")
            decor?.rootWindowInsets?.systemWindowInsetBottom ?: 0
        }
        if (inset > 0) return inset
        val id = activity.resources.getIdentifier("navigation_bar_height", "dimen", "android")
        return if (id > 0) activity.resources.getDimensionPixelSize(id) else 0
    }

    private fun showOldPostReelCustomContextMenu(
        context: Context,
        headerActions: List<OldPostReelMenuAction>,
        rowActions: List<OldPostReelMenuAction>,
        source: String,
        onShown: (() -> Unit)? = null,
        onDismissed: (() -> Unit)? = null
    ): Boolean {
        val activity = findActivity(context) ?: currentActivity
        if (activity == null || !isActivityUsable(activity)) {
            logInfo("Old post/reel custom context menu skipped reason=activity_missing source=$source")
            return false
        }
        val headers = headerActions
            .filter {
                val label = oldPostReelNormalizeSheetLabel(it.label)
                label != "qr code" && !oldPostReelIsNewContextMenuLabel(label)
            }
            .distinctBy { it.optionName.ifBlank { oldPostReelNormalizeSheetLabel(it.label) } }
            .take(3)
        val rows = rowActions
            .filter {
                val label = oldPostReelNormalizeSheetLabel(it.label)
                label != "qr code" && !oldPostReelIsNewContextMenuLabel(label)
            }
            .distinctBy { it.optionName.ifBlank { oldPostReelNormalizeSheetLabel(it.label) } }
        if (headers.isEmpty() && rows.isEmpty()) return false

        fun render(): Boolean {
            if (!isActivityUsable(activity)) return false
            val density = activity.resources.displayMetrics.density
            val dark = (activity.resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
            val sheetBg = if (dark) Color.rgb(17, 24, 28) else Color.WHITE
            val tileBg = if (dark) Color.rgb(36, 40, 46) else Color.rgb(245, 245, 245)
            val rowDivider = if (dark) Color.rgb(37, 43, 48) else Color.rgb(219, 219, 219)
            val handleColor = if (dark) Color.rgb(168, 174, 180) else Color.rgb(150, 150, 150)
            val textPrimary = if (dark) Color.WHITE else Color.rgb(38, 38, 38)
            val textSecondary = if (dark) Color.rgb(245, 245, 245) else Color.rgb(38, 38, 38)
            val reportText = Color.rgb(237, 73, 86)
            val disabledText = if (dark) Color.rgb(120, 125, 130) else Color.rgb(145, 145, 145)
            val radius = 30f * density
            val bottomInset = oldPostReelBottomSystemInset(activity)
            val bottomPadding = (14 * density).roundToInt() + bottomInset
            val dialog = Dialog(activity, android.R.style.Theme_Translucent_NoTitleBar).apply {
                requestWindowFeature(Window.FEATURE_NO_TITLE)
                setCancelable(true)
                setCanceledOnTouchOutside(true)
            }
            val root = FrameLayout(activity).apply {
                isClickable = true
                background = ColorDrawable(Color.TRANSPARENT)
            }
            val dimView = View(activity).apply {
                setBackgroundColor(Color.argb(82, 0, 0, 0))
                alpha = 0f
                isClickable = true
            }
            root.addView(dimView, FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
            ))
            val sheet = LinearLayout(activity).apply {
                orientation = LinearLayout.VERTICAL
                isClickable = true
                background = GradientDrawable().apply {
                    setColor(sheetBg)
                    cornerRadii = floatArrayOf(radius, radius, radius, radius, 0f, 0f, 0f, 0f)
                }
                setPadding(0, (11 * density).roundToInt(), 0, bottomPadding)
                translationY = activity.resources.displayMetrics.heightPixels.toFloat()
            }
            val rowScroll = ScrollView(activity).apply {
                isFillViewport = false
                isVerticalScrollBarEnabled = false
                overScrollMode = View.OVER_SCROLL_IF_CONTENT_SCROLLS
                clipToPadding = false
            }
            val rowContainer = LinearLayout(activity).apply {
                orientation = LinearLayout.VERTICAL
            }

            var closing = false
            var dismissedCallbackSent = false
            fun notifyDismissed() {
                if (dismissedCallbackSent) return
                dismissedCallbackSent = true
                onDismissed?.invoke()
            }
            dialog.setOnDismissListener { notifyDismissed() }

            fun finishDismiss(afterDismiss: (() -> Unit)? = null) {
                runCatching { dialog.dismiss() }
                afterDismiss?.invoke()
            }

            fun dismissWithBottomSheetAnimation(afterDismiss: (() -> Unit)? = null) {
                if (closing) return
                closing = true
                val targetY = (sheet.height.takeIf { it > 0 } ?: activity.resources.displayMetrics.heightPixels).toFloat()
                runCatching {
                    dimView.animate()
                        .alpha(0f)
                        .setDuration(130L)
                        .setInterpolator(android.view.animation.AccelerateInterpolator())
                        .start()
                    sheet.animate()
                        .translationY(targetY)
                        .setDuration(170L)
                        .setInterpolator(android.view.animation.AccelerateInterpolator())
                        .withEndAction { finishDismiss(afterDismiss) }
                        .start()
                }.onFailure {
                    finishDismiss(afterDismiss)
                }
            }

            dimView.setOnClickListener { dismissWithBottomSheetAnimation() }
            dialog.setOnKeyListener { _, keyCode, event ->
                if (keyCode == KeyEvent.KEYCODE_BACK && event.action == KeyEvent.ACTION_UP) {
                    dismissWithBottomSheetAnimation()
                    true
                } else {
                    false
                }
            }

            fun invokeAction(action: OldPostReelMenuAction, clicked: View) {
                dismissWithBottomSheetAnimation {
                    runCatching { action.listener.onClick(clicked) }
                        .onFailure { logError("Old post/reel custom context menu action failed option=${action.optionName} label=${action.label}", it) }
                }
            }

            fun displayLabel(action: OldPostReelMenuAction): String =
                when (action.optionName) {
                    "WHY_AM_I_SEEING_THIS" -> "Why you're seeing this post"
                    "MANAGE_SUGGESTED_CONTENT", "MANAGE_SUGGESTED_CONTENT_CARRERA", "SEE_YOUR_ALGORITHM" -> "Manage content preferences"
                    else -> action.label
                }

            fun fallbackIconFor(action: OldPostReelMenuAction): Int =
                when (action.optionName) {
                    "SHARE_LINK", "SHARE" -> android.R.drawable.ic_menu_share
                    "COPY_LINK", "COPY_FUNDRAISER_LINK" -> android.R.drawable.ic_menu_upload
                    "SAVE", "UNSAVE" -> android.R.drawable.ic_menu_save
                    "WHY_AM_I_SEEING_THIS" -> android.R.drawable.ic_menu_info_details
                    "ABOUT_THIS_ACCOUNT" -> android.R.drawable.ic_menu_myplaces
                    "REPORT" -> android.R.drawable.ic_dialog_alert
                    "MANAGE_SUGGESTED_CONTENT", "MANAGE_SUGGESTED_CONTENT_CARRERA", "SEE_YOUR_ALGORITHM" -> android.R.drawable.ic_menu_manage
                    "DOWNLOAD" -> android.R.drawable.stat_sys_download_done
                    else -> 0
                }

            fun customLineIconFor(action: OldPostReelMenuAction, color: Int): Drawable? =
                when (action.optionName) {
                    "NOT_INTERESTED", "SEE_FEWER", "SEE_FEWER_CONNECTED" -> OldPostReelLineIconDrawable(
                        OldPostReelLineIconDrawable.TYPE_EYE_SLASH,
                        color
                    )
                    "INTERESTED", "SEE_MORE" -> OldPostReelLineIconDrawable(
                        OldPostReelLineIconDrawable.TYPE_EYE,
                        color
                    )
                    else -> null
                }

            fun addIconView(parent: ViewGroup, action: OldPostReelMenuAction, sizeDp: Int, color: Int) {
                customLineIconFor(action, color)?.let { drawable ->
                    parent.addView(ImageView(activity).apply {
                        setImageDrawable(drawable)
                        scaleType = ImageView.ScaleType.CENTER_INSIDE
                    }, FrameLayout.LayoutParams((sizeDp * density).roundToInt(), (sizeDp * density).roundToInt(), Gravity.CENTER))
                    return
                }
                val resId = action.icon.takeIf { it != 0 } ?: fallbackIconFor(action)
                if (resId != 0) {
                    parent.addView(ImageView(activity).apply {
                        runCatching { setImageResource(resId) }
                            .onFailure {
                                val fallback = fallbackIconFor(action)
                                if (fallback != 0) runCatching { setImageResource(fallback) }
                            }
                        setColorFilter(color)
                        scaleType = ImageView.ScaleType.CENTER_INSIDE
                    }, FrameLayout.LayoutParams((sizeDp * density).roundToInt(), (sizeDp * density).roundToInt(), Gravity.CENTER))
                } else {
                    parent.addView(TextView(activity).apply {
                        text = displayLabel(action).take(1)
                        setTextColor(color)
                        setTextSize(TypedValue.COMPLEX_UNIT_SP, (sizeDp * 0.65f).coerceAtLeast(14f))
                        typeface = Typeface.DEFAULT_BOLD
                        gravity = Gravity.CENTER
                    }, FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT))
                }
            }

            sheet.addView(View(activity).apply {
                background = roundedDrawable(handleColor, 2f)
            }, LinearLayout.LayoutParams((44 * density).roundToInt(), (4 * density).roundToInt()).apply {
                gravity = Gravity.CENTER_HORIZONTAL
                bottomMargin = (18 * density).roundToInt()
            })

            if (headers.isNotEmpty()) {
                val header = LinearLayout(activity).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER
                    setPadding((28 * density).roundToInt(), 0, (28 * density).roundToInt(), (14 * density).roundToInt())
                }
                headers.forEach { action ->
                    val item = LinearLayout(activity).apply {
                        orientation = LinearLayout.VERTICAL
                        gravity = Gravity.CENTER
                        alpha = if (action.enabled) 1f else 0.45f
                        isEnabled = action.enabled
                        isClickable = action.enabled
                        setOnClickListener { if (action.enabled) invokeAction(action, it) }
                    }
                    val iconFrame = FrameLayout(activity).apply {
                        background = roundedDrawable(tileBg, 20f)
                    }
                    addIconView(iconFrame, action, 28, if (action.enabled) textPrimary else disabledText)
                    item.addView(iconFrame, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, (56 * density).roundToInt()).apply {
                        gravity = Gravity.CENTER_HORIZONTAL
                    })
                    item.addView(TextView(activity).apply {
                        text = displayLabel(action)
                        setTextColor(if (action.enabled) textPrimary else disabledText)
                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)
                        gravity = Gravity.CENTER
                        maxLines = 1
                    }, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = (8 * density).roundToInt()
                    })
                    header.addView(item, LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                        leftMargin = (5 * density).roundToInt()
                        rightMargin = (5 * density).roundToInt()
                    })
                }
                sheet.addView(header)
            }

            rows.forEach { action ->
                if (action.dividerBefore) {
                    rowContainer.addView(View(activity).apply { setBackgroundColor(rowDivider) }, LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        1
                    ).apply {
                        topMargin = (6 * density).roundToInt()
                        bottomMargin = (6 * density).roundToInt()
                    })
                }
                val row = LinearLayout(activity).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    alpha = if (action.enabled) 1f else 0.45f
                    isEnabled = action.enabled
                    isClickable = action.enabled
                    setPadding((24 * density).roundToInt(), 0, (28 * density).roundToInt(), 0)
                    setOnClickListener { if (action.enabled) invokeAction(action, it) }
                }
                val rowIcon = FrameLayout(activity)
                addIconView(rowIcon, action, 26, if (action.destructive) reportText else textPrimary)
                row.addView(rowIcon, LinearLayout.LayoutParams((34 * density).roundToInt(), ViewGroup.LayoutParams.MATCH_PARENT).apply {
                    rightMargin = (16 * density).roundToInt()
                })
                row.addView(TextView(activity).apply {
                    text = displayLabel(action)
                    setTextColor(if (action.destructive) reportText else if (action.enabled) textSecondary else disabledText)
                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)
                    gravity = Gravity.CENTER_VERTICAL
                    maxLines = 2
                }, LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, 1f))
                rowContainer.addView(row, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, (60 * density).roundToInt()))
            }
            if (rows.isNotEmpty()) {
                rowScroll.addView(rowContainer, FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT,
                    ViewGroup.LayoutParams.WRAP_CONTENT
                ))
                sheet.addView(rowScroll, LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT,
                    ViewGroup.LayoutParams.WRAP_CONTENT
                ))
            }

            root.addView(sheet, FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT,
                Gravity.BOTTOM
            ))
            dialog.setContentView(root)
            return runCatching {
                dialog.show()
                dialog.window?.let { window ->
                    window.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                    window.setGravity(Gravity.BOTTOM)
                    window.setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT)
                    window.clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND)
                    val attrs = window.attributes
                    attrs.dimAmount = 0f
                    window.attributes = attrs
                }
                sheet.post {
                    if (!dialog.isShowing || closing) return@post
                    val rootHeight = root.height.takeIf { it > 0 } ?: activity.resources.displayMetrics.heightPixels
                    val maxSheetHeight = (rootHeight - (24 * density).roundToInt()).coerceAtLeast((280 * density).roundToInt())
                    val sheetHeight = sheet.height.takeIf { it > 0 } ?: sheet.measuredHeight
                    val scrollHeight = rowScroll.height.takeIf { it > 0 } ?: rowScroll.measuredHeight
                    if (sheetHeight > maxSheetHeight && scrollHeight > 0) {
                        val fixedHeight = (sheetHeight - scrollHeight).coerceAtLeast(0)
                        val maxRowsHeight = (maxSheetHeight - fixedHeight)
                            .coerceAtLeast((180 * density).roundToInt())
                            .coerceAtMost(scrollHeight)
                        val params = rowScroll.layoutParams as? LinearLayout.LayoutParams
                        if (params != null && params.height != maxRowsHeight) {
                            params.height = maxRowsHeight
                            rowScroll.layoutParams = params
                            rowScroll.requestLayout()
                        }
                    }
                    dimView.animate()
                        .alpha(1f)
                        .setDuration(120L)
                        .setInterpolator(android.view.animation.DecelerateInterpolator())
                        .start()
                    sheet.animate()
                        .translationY(0f)
                        .setDuration(220L)
                        .setInterpolator(android.view.animation.DecelerateInterpolator())
                        .start()
                }
                logInfo(
                    "Old post/reel custom context menu shown source=$source " +
                        "headers=${headers.joinToString("|") { it.optionName.ifBlank { it.label } }} " +
                        "rows=${rows.joinToString("|") { it.optionName.ifBlank { it.label } }}"
                )
                onShown?.invoke()
                true
            }.onFailure {
                notifyDismissed()
                logError("Failed showing old post/reel custom context menu source=$source", it)
            }.getOrDefault(false)
        }

        return if (Looper.myLooper() == Looper.getMainLooper()) {
            render()
        } else {
            mainHandler.post { render() }
            true
        }
    }

    private fun tryShowOldPostReelPreemptiveCustomMediaOverflow(
        context: Context,
        media: Any,
        mediaState: Any,
        helper: Any,
        helperClass: Class<*>,
        createHelpers: List<Method>,
        filterList: Collection<*>?,
        mediaIndex: Int,
        includeSelfOptions: Boolean,
        optionClass: Class<*>,
        mediaOverflowLooksReel: Boolean,
        key: String,
        logMediaOverflowStage: (String, () -> String) -> Unit
    ): Boolean {
        val startedAtMs = SystemClock.elapsedRealtime()
        val filterOptionNames = filterList.orEmpty().mapTo(LinkedHashSet()) { it?.toString().orEmpty() }
        val failures = mutableListOf<String>()

        fun optionByName(name: String): Any? =
            optionClass.enumConstants?.firstOrNull { it.toString() == name }

        fun iconDrawable(option: Any?): Int =
            runCatching { option?.javaClass?.getMethod("getIconDrawable")?.invoke(option) as? Int ?: 0 }.getOrDefault(0)

        fun preferredOptionName(names: List<String>): String? =
            names.firstOrNull { it in filterOptionNames && optionByName(it) != null }
                ?: names.firstOrNull { optionByName(it) != null }

        fun resolveOverflowForClick(names: List<String>, stageName: String): Pair<Any, List<Any>>? {
            for (candidate in createHelpers) {
                val candidateHelper = runCatching {
                    candidate.invoke(null, media, mediaState, helper, mediaIndex, includeSelfOptions)
                }.onFailure {
                    failures += "click_factory_failed:${candidate.name}:${it.javaClass.simpleName}"
                }.getOrNull() ?: continue
                val allMows = oldPostReelMediaOverflowMows(candidateHelper, null)
                val filteredMows = oldPostReelMediaOverflowMows(candidateHelper, filterList)
                val allOptionNames = allMows.mapNotNull(::oldPostReelMowOptionName)
                val filteredOptionNames = filteredMows.mapNotNull(::oldPostReelMowOptionName)
                val mows = if (allOptionNames.any { it in names }) allMows else filteredMows
                if (mows.isNotEmpty() || allMows.isNotEmpty()) {
                    logMediaOverflowStage("preemptive click helper:$stageName") {
                        "factory=${candidate.name}:${candidateHelper.javaClass.name} " +
                            "all=${allOptionNames.joinToString("|").take(420)} " +
                            "filtered=${filteredOptionNames.joinToString("|").take(420)}"
                    }
                    return candidateHelper to mows.ifEmpty { allMows }
                }
            }
            failures += "click_helper_missing:$stageName"
            return null
        }

        fun clickForOptions(names: List<String>, stageName: String): View.OnClickListener? {
            if (names.none { optionByName(it) != null }) {
                failures += "option_missing:$stageName:${names.joinToString("|")}"
                return null
            }
            return View.OnClickListener { clicked ->
                val clickStartedAtMs = SystemClock.elapsedRealtime()
                logMediaOverflowStage("preemptive click dispatch:$stageName") {
                    "options=${names.joinToString("|")}"
                }
                val resolved = resolveOverflowForClick(names, stageName)
                if (resolved == null) {
                    logMediaOverflowStage("preemptive click skipped:$stageName") {
                        "reason=helper_missing failures=${failures.joinToString("|").take(500)}"
                    }
                    return@OnClickListener
                }
                val (resolvedOverflowHelper, mows) = resolved
                val mow = names.firstNotNullOfOrNull { wanted ->
                    mows.firstOrNull { oldPostReelMowOptionName(it) == wanted }
                }
                val optionName = mow?.let(::oldPostReelMowOptionName)
                    ?: preferredOptionName(names)
                    ?: names.first()
                val option = mow?.let(::oldPostReelMowOptionValue) ?: optionByName(optionName)
                val directClickMethod = oldPostReelMediaOverflowOptionHandler(resolvedOverflowHelper, optionClass)
                if (option != null && directClickMethod != null) {
                    runCatching {
                        directClickMethod.invoke(resolvedOverflowHelper, option)
                    }.onSuccess {
                        logMediaOverflowStage("preemptive click complete:$optionName") {
                            "path=direct handler=${directClickMethod.declaringClass.name}.${directClickMethod.name} " +
                                "elapsed=${SystemClock.elapsedRealtime() - clickStartedAtMs}ms"
                        }
                    }.onFailure { throwable ->
                        logError("Old post/reel preemptive direct click failed option=$optionName", throwable)
                    }
                    return@OnClickListener
                }

                val clickClass = findFirstClass("X.AzB", "X.ViewOnClickListenerC27986AzB")
                val clickCtor = clickClass?.declaredConstructors?.firstOrNull { ctor ->
                    ctor.parameterTypes.size == 3 && ctor.parameterTypes[0] == java.lang.Integer.TYPE
                }?.apply { isAccessible = true }
                if (mow != null && clickCtor != null) {
                    runCatching {
                        (clickCtor.newInstance(39, mow, resolvedOverflowHelper) as? View.OnClickListener)?.onClick(clicked)
                    }.onSuccess {
                        logMediaOverflowStage("preemptive click complete:$optionName") {
                            "path=legacy handler=${clickClass.name} elapsed=${SystemClock.elapsedRealtime() - clickStartedAtMs}ms"
                        }
                    }.onFailure { throwable ->
                        logError("Old post/reel preemptive legacy click failed option=$optionName", throwable)
                    }
                } else {
                    logMediaOverflowStage("preemptive click skipped:$optionName") {
                        "reason=handler_missing direct=${directClickMethod != null} legacy=${clickCtor != null} mow=${mow != null}"
                    }
                }
            }
        }

        fun action(
            names: List<String>,
            label: String,
            destructive: Boolean = false,
            dividerBefore: Boolean = false
        ): OldPostReelMenuAction? {
            val optionName = preferredOptionName(names) ?: names.firstOrNull()
                ?: return null
            val listener = clickForOptions(names, label) ?: return null
            return OldPostReelMenuAction(
                optionName = optionName,
                label = label,
                icon = iconDrawable(optionByName(optionName)),
                listener = listener,
                destructive = destructive,
                enabled = true,
                dividerBefore = dividerBefore
            )
        }

        val headerActions = listOfNotNull(
            action(listOf("SHARE_LINK", "SHARE"), "Share"),
            action(listOf("COPY_LINK", "COPY_FUNDRAISER_LINK"), "Link"),
            action(listOf("SAVE", "UNSAVE"), "Save")
        )
        val rowActions = mutableListOf<OldPostReelMenuAction>()
        if (mediaOverflowLooksReel && (state.enableReelDownload || state.enableReelThumbnailDownload) && shouldOfferDownloadContextMenu()) {
            val activity = findActivity(context) ?: currentActivity
            if (activity != null && isActivityUsable(activity)) {
                val offeredAtMs = SystemClock.elapsedRealtime()
                rowActions += OldPostReelMenuAction(
                    optionName = "DOWNLOAD",
                    label = "Download",
                    icon = resolveMediaOptionDownloadIcon(context),
                    listener = View.OnClickListener {
                        val ageMs = SystemClock.elapsedRealtime() - offeredAtMs
                        if (ageMs in 0L..120L) {
                            logMediaOverflowStage("preemptive download click suppressed") {
                                "reason=initial_more_tap_guard ageMs=$ageMs"
                            }
                            return@OnClickListener
                        }
                        handleReelDownloadClick(activity, media, helper)
                    }
                )
                logDownloadControlGate("reel_preemptive_row", "offered")
            }
        } else if (!mediaOverflowLooksReel && state.enablePostDownload && shouldOfferDownloadContextMenu()) {
            createOldPostReelPostDownloadAction(
                context = context,
                media = media,
                fallbackRoot = helper,
                source = "preemptive:$key",
                logStage = logMediaOverflowStage
            )?.let {
                rowActions += it
                logDownloadControlGate("post_preemptive_row", "offered")
            }
        }
        action(listOf("WHY_AM_I_SEEING_THIS"), "Why you're seeing this post")?.let { rowActions += it }
        action(listOf("NOT_INTERESTED", "SEE_FEWER", "SEE_FEWER_CONNECTED"), "Not interested")?.let { rowActions += it }
        action(listOf("INTERESTED", "SEE_MORE"), "Interested")?.let { rowActions += it }
        if (!mediaOverflowLooksReel) {
            action(listOf("ABOUT_THIS_ACCOUNT"), "About this account")?.let { rowActions += it }
        }
        action(listOf("REPORT"), "Report", destructive = true)?.let { rowActions += it }
        action(
            listOf("MANAGE_SUGGESTED_CONTENT", "MANAGE_SUGGESTED_CONTENT_CARRERA", "SEE_YOUR_ALGORITHM"),
            "Manage content preferences",
            dividerBefore = rowActions.isNotEmpty()
        )?.let { rowActions += it }

        if (headerActions.size < 3 || rowActions.isEmpty()) {
            logMediaOverflowStage("preemptive custom skipped") {
                "reason=incomplete headers=${headerActions.map { it.optionName }.joinToString("|")} " +
                    "rows=${rowActions.map { it.optionName }.joinToString("|")} failures=${failures.joinToString("|").take(500)}"
            }
            return false
        }

        val shown = showOldPostReelCustomContextMenu(context, headerActions, rowActions, "preemptive:$key")
        if (shown) {
            logMediaOverflowStage("preemptive custom shown") {
                "elapsed=${SystemClock.elapsedRealtime() - startedAtMs}ms " +
                    "headers=${headerActions.joinToString("|") { it.optionName }} " +
                    "rows=${rowActions.joinToString("|") { it.optionName }} " +
                    "helperClass=${helperClass.name}"
            }
        }
        return shown
    }

    private fun tryShowOldPostReelFastCustomMediaOverflow(
        context: Context,
        media: Any,
        helper: Any,
        helperClass: Class<*>,
        overflowHelper: Any,
        mows: List<Any>,
        optionNames: List<String>,
        optionClass: Class<*>,
        directClickMethod: Method?,
        clickCtor: Constructor<*>?,
        manageClickCtor: Constructor<*>?,
        mediaOverflowLooksReel: Boolean,
        key: String,
        logMediaOverflowStage: (String, () -> String) -> Unit
    ): Boolean {
        val startedAtMs = SystemClock.elapsedRealtime()
        val headerActions = mutableListOf<OldPostReelMenuAction>()
        val rowActions = mutableListOf<OldPostReelMenuAction>()
        val headerKeys = LinkedHashSet<String>()
        val rowKeys = LinkedHashSet<String>()
        val used = LinkedHashSet<Any>()
        val failures = mutableListOf<String>()

        fun optionByName(name: String): Any? =
            optionClass.enumConstants?.firstOrNull { it.toString() == name }

        fun iconDrawable(option: Any?): Int =
            runCatching { option?.javaClass?.getMethod("getIconDrawable")?.invoke(option) as? Int ?: 0 }.getOrDefault(0)

        fun customActionKey(action: OldPostReelMenuAction): String =
            action.optionName.ifBlank { oldPostReelNormalizeSheetLabel(action.label) }

        fun rememberHeader(action: OldPostReelMenuAction) {
            if (headerKeys.add(customActionKey(action))) headerActions += action
        }

        fun rememberRow(action: OldPostReelMenuAction) {
            if (rowKeys.add(customActionKey(action))) rowActions += action
        }

        fun clickFor(mow: Any): View.OnClickListener? {
            val option = oldPostReelMowOptionValue(mow)
            val optionName = option?.toString() ?: oldPostReelMowOptionName(mow).orEmpty()
            if (option != null && directClickMethod != null) {
                return View.OnClickListener {
                    logMediaOverflowStage("fast click dispatch:$optionName") {
                        "path=direct handler=${directClickMethod.declaringClass.name}.${directClickMethod.name} option=$optionName"
                    }
                    runCatching {
                        directClickMethod.invoke(overflowHelper, option)
                    }.onSuccess {
                        logMediaOverflowStage("fast click complete:$optionName") {
                            "path=direct handler=${directClickMethod.declaringClass.name}.${directClickMethod.name} option=$optionName"
                        }
                    }.onFailure { throwable ->
                        logError("Old post/reel fast custom direct click failed option=$optionName", throwable)
                    }
                }
            }

            val ctor = clickCtor ?: run {
                failures += "click_missing:$optionName"
                return null
            }
            return runCatching { ctor.newInstance(39, mow, overflowHelper) as? View.OnClickListener }
                .map { original ->
                    original?.let {
                        View.OnClickListener { view ->
                            logMediaOverflowStage("fast click dispatch:$optionName") {
                                "path=legacy handler=${it.javaClass.name} option=$optionName"
                            }
                            it.onClick(view)
                        }
                    }
                }
                .onFailure { failures += "legacy_click_failed:$optionName:${it.javaClass.simpleName}" }
                .getOrNull()
        }

        fun clickForOption(optionName: String): View.OnClickListener? {
            val option = optionByName(optionName) ?: return null.also { failures += "option_missing:$optionName" }
            val direct = directClickMethod ?: return null.also { failures += "direct_click_missing:$optionName" }
            return View.OnClickListener {
                logMediaOverflowStage("fast click dispatch:$optionName") {
                    "path=direct_fallback handler=${direct.declaringClass.name}.${direct.name} option=$optionName"
                }
                runCatching {
                    direct.invoke(overflowHelper, option)
                }.onSuccess {
                    logMediaOverflowStage("fast click complete:$optionName") {
                        "path=direct_fallback handler=${direct.declaringClass.name}.${direct.name} option=$optionName"
                    }
                }.onFailure { throwable ->
                    logError("Old post/reel fast custom fallback click failed option=$optionName", throwable)
                }
            }
        }

        fun findMow(vararg names: String): Any? =
            names.firstNotNullOfOrNull { wanted ->
                mows.firstOrNull { mow -> mow !in used && oldPostReelMowOptionName(mow) == wanted }
            }?.also { used += it }

        fun addHeader(mow: Any?, label: String): Boolean {
            mow ?: return false
            val optionName = oldPostReelMowOptionName(mow) ?: return false.also { failures += "header_option_missing:$label" }
            val listener = clickFor(mow) ?: return false
            val option = optionByName(optionName)
            rememberHeader(
                OldPostReelMenuAction(
                    optionName = optionName,
                    label = label,
                    icon = oldPostReelIconForMow(helperClass, mow, option) ?: iconDrawable(option),
                    listener = listener,
                    enabled = true
                )
            )
            return true
        }

        fun addRowForMow(mow: Any?, forcedLabel: String? = null, dividerBefore: Boolean = false): Boolean {
            mow ?: return false
            val optionName = oldPostReelMowOptionName(mow) ?: return false.also { failures += "row_option_missing:${mow.javaClass.name}" }
            val listener = clickFor(mow) ?: return false
            val option = optionByName(optionName)
            val label = forcedLabel ?: oldPostReelMowText(mow) ?: oldPostReelLabelForOption(optionName)
            val destructive = optionName in setOf("REPORT", "DELETE", "DELETE_NOW") || optionName.contains("REMOVE")
            rememberRow(
                OldPostReelMenuAction(
                    optionName = optionName,
                    label = label,
                    icon = oldPostReelIconForMow(helperClass, mow, option) ?: iconDrawable(option),
                    listener = listener,
                    destructive = destructive,
                    enabled = true,
                    dividerBefore = dividerBefore
                )
            )
            return true
        }

        fun addRowForOption(optionName: String, label: String, dividerBefore: Boolean = false): Boolean {
            val listener = clickForOption(optionName) ?: return false
            val option = optionByName(optionName)
            val destructive = optionName in setOf("REPORT", "DELETE", "DELETE_NOW") || optionName.contains("REMOVE")
            rememberRow(
                OldPostReelMenuAction(
                    optionName = optionName,
                    label = label,
                    icon = iconDrawable(option),
                    listener = listener,
                    destructive = destructive,
                    enabled = true,
                    dividerBefore = dividerBefore
                )
            )
            return true
        }

        fun isDownloadMow(mow: Any): Boolean {
            val optionName = oldPostReelMowOptionName(mow).orEmpty()
            val normalizedOption = optionName.lowercase(Locale.US)
            val label = oldPostReelNormalizeSheetLabel(oldPostReelMowText(mow).orEmpty())
            return optionName == "DOWNLOAD" ||
                normalizedOption == "download" ||
                normalizedOption == "upload" ||
                optionName == "0LtM" ||
                label == "download"
        }

        fun findDownloadMow(): Any? =
            mows.firstOrNull { mow -> mow !in used && isDownloadMow(mow) }?.also { used += it }

        fun addExplicitReelDownloadRow(): Boolean {
            if (!mediaOverflowLooksReel || (!state.enableReelDownload && !state.enableReelThumbnailDownload)) return false
            if (!shouldOfferDownloadContextMenu()) {
                logDownloadControlGate("reel_classic_fast_row", "suppressed")
                return false
            }
            val activity = findActivity(context) ?: currentActivity
            if (activity == null || activity.isFinishing || activity.isDestroyed) {
                failures += "reel_download_activity_missing"
                return false
            }
            val offeredAtMs = SystemClock.elapsedRealtime()
            val listener = View.OnClickListener {
                val ageMs = SystemClock.elapsedRealtime() - offeredAtMs
                if (ageMs in 0L..120L) {
                    logMediaOverflowStage("fast download click suppressed") {
                        "reason=initial_more_tap_guard ageMs=$ageMs"
                    }
                    return@OnClickListener
                }
                handleReelDownloadClick(activity, media, helper)
            }
            rememberRow(
                OldPostReelMenuAction(
                    optionName = "DOWNLOAD",
                    label = "Download",
                    icon = resolveMediaOptionDownloadIcon(context),
                    listener = listener
                )
            )
            logDownloadControlGate("reel_classic_fast_row", "offered")
            return true
        }

        fun addExplicitPostDownloadRow(): Boolean {
            if (mediaOverflowLooksReel || !state.enablePostDownload) return false
            if (!shouldOfferDownloadContextMenu()) {
                logDownloadControlGate("post_classic_fast_row", "suppressed")
                return false
            }
            val action = createOldPostReelPostDownloadAction(
                context = context,
                media = media,
                fallbackRoot = helper,
                source = "fast:$key",
                logStage = logMediaOverflowStage
            ) ?: return false.also { failures += "post_download_action_missing" }
            rememberRow(action)
            logDownloadControlGate("post_classic_fast_row", "offered")
            return true
        }

        addHeader(findMow("SHARE_LINK", "SHARE"), "Share")
        addHeader(findMow("COPY_LINK", "COPY_FUNDRAISER_LINK"), "Link")
        val save = findMow("SAVE", "UNSAVE")
        addHeader(save, save?.let(::oldPostReelMowText) ?: "Save")

        if (mediaOverflowLooksReel) {
            val nativeDownloadMows = mows.filter { mow -> mow !in used && isDownloadMow(mow) }
            used.addAll(nativeDownloadMows)
            if (nativeDownloadMows.isNotEmpty()) {
                logMediaOverflowStage("fast native download suppressed") {
                    "reason=avoid_open_tap_auto_download options=${nativeDownloadMows.mapNotNull(::oldPostReelMowOptionName).joinToString("|")} " +
                        "labels=${nativeDownloadMows.mapNotNull(::oldPostReelMowText).joinToString("|")}"
                }
            }
            addExplicitReelDownloadRow()
        } else {
            if (!addRowForMow(findDownloadMow(), "Download")) {
                addExplicitPostDownloadRow()
            }
        }

        addRowForMow(findMow("WHY_AM_I_SEEING_THIS"), "Why you're seeing this post") ||
            addRowForOption("WHY_AM_I_SEEING_THIS", "Why you're seeing this post")
        addRowForMow(findMow("NOT_INTERESTED", "SEE_FEWER", "SEE_FEWER_CONNECTED"))
        addRowForMow(findMow("INTERESTED", "SEE_MORE"))
        addRowForMow(findMow("ABOUT_THIS_ACCOUNT"))
        addRowForMow(findMow("REPORT"))

        val manageMow = findMow("MANAGE_SUGGESTED_CONTENT_CARRERA", "MANAGE_SUGGESTED_CONTENT", "SEE_YOUR_ALGORITHM")
        val shouldAddManage = optionNames.any { it in setOf("WHY_AM_I_SEEING_THIS", "SEE_FEWER", "SEE_MORE", "NOT_INTERESTED", "INTERESTED") }
        if (manageMow != null) {
            addRowForMow(manageMow, "Manage content preferences", dividerBefore = rowActions.isNotEmpty())
        } else if (shouldAddManage && manageClickCtor != null) {
            val manageOption = optionByName("MANAGE_SUGGESTED_CONTENT_CARRERA") ?: optionByName("MANAGE_SUGGESTED_CONTENT")
            val manageListener = runCatching { manageClickCtor.newInstance(helper, 20) as? View.OnClickListener }.getOrNull()
            if (manageListener != null) {
                rememberRow(
                    OldPostReelMenuAction(
                        optionName = "MANAGE_SUGGESTED_CONTENT",
                        label = "Manage content preferences",
                        icon = iconDrawable(manageOption),
                        listener = manageListener,
                        dividerBefore = rowActions.isNotEmpty()
                    )
                )
            }
        }

        val suppressed = RESTORE_OLD_CONTEXT_MENU_SUPPRESSED_OPTION_NAMES + setOf(
            "META_AI_DEP_ASK",
            "CONTENT_DEEP_DIVE",
            "SHARE_LINK",
            "SHARE",
            "COPY_LINK",
            "COPY_FUNDRAISER_LINK",
            "SAVE",
            "UNSAVE",
            "DOWNLOAD",
            "QR_CODE",
            "MANAGE_SUGGESTED_CONTENT",
            "MANAGE_SUGGESTED_CONTENT_CARRERA",
            "SEE_YOUR_ALGORITHM"
        )
        val extraSuppressedOptions = mows.filter { mow ->
            mow !in used &&
                !(mediaOverflowLooksReel && isDownloadMow(mow)) &&
                oldPostReelMowOptionName(mow)?.let { it !in suppressed } == true
        }.mapNotNull(::oldPostReelMowOptionName)
        if (extraSuppressedOptions.isNotEmpty()) {
            logMediaOverflowStage("fast extra rows suppressed") {
                "reason=match_classic_target options=${extraSuppressedOptions.joinToString("|").take(240)}"
            }
        }

        if (headerActions.size < 3 || rowActions.isEmpty()) {
            logMediaOverflowStage("fast custom skipped") {
                "reason=incomplete headers=${headerActions.map { it.optionName }.joinToString("|")} " +
                    "rows=${rowActions.map { it.optionName }.joinToString("|")} failures=${failures.joinToString("|").take(700)}"
            }
            return false
        }

        val shown = showOldPostReelCustomContextMenu(context, headerActions, rowActions, "fast:$key")
        if (shown) {
            logMediaOverflowStage("fast custom shown") {
                "elapsed=${SystemClock.elapsedRealtime() - startedAtMs}ms " +
                    "headers=${headerActions.map { it.optionName }.joinToString("|")} " +
                    "rows=${rowActions.map { it.optionName }.joinToString("|")} " +
                    "failures=${failures.joinToString("|").take(500)}"
            }
        }
        return shown
    }

    private fun oldPostReelActionSheetLists(sheetModel: Any): List<MutableList<Any?>> {
        return oldPostReelDeclaredFieldsInHierarchy(sheetModel.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .filter { java.util.List::class.java.isAssignableFrom(it.type) && !java.util.LinkedList::class.java.isAssignableFrom(it.type) }
            .mapNotNull { field ->
                runCatching {
                    field.isAccessible = true
                    @Suppress("UNCHECKED_CAST")
                    field.get(sheetModel) as? MutableList<Any?>
                }.getOrNull()
            }
    }

    private fun oldPostReelHeaderLabels(context: Context, actionLists: List<List<Any?>>): List<String> =
        actionLists.flatten().mapNotNull { oldPostReelSheetRowLabel(context, it) }
            .map(::oldPostReelNormalizeSheetLabel)

    private fun oldPostReelSheetRowLabel(context: Context, item: Any?): String? {
        if (item == null) return null
        val fields = oldPostReelDeclaredFieldsInHierarchy(item.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .onEach { it.isAccessible = true }
        val stringFieldNames = listOf("A08", "A0B", "A05", "A0A", "A06", "A07", "A0C", "A0D")
        stringFieldNames.forEach { name ->
            fields.firstOrNull { it.name == name && CharSequence::class.java.isAssignableFrom(it.type) }?.let { field ->
                val value = runCatching { field.get(item) as? CharSequence }.getOrNull()?.toString()
                if (!value.isNullOrBlank()) return value
            }
        }
        val resourceFieldNames = listOf("A03", "A07")
        resourceFieldNames.forEach { name ->
            fields.firstOrNull { it.name == name && it.type == java.lang.Integer.TYPE }?.let { field ->
                val resId = runCatching { field.getInt(item) }.getOrDefault(0)
                if (resId > 0) {
                    val value = runCatching { context.getString(resId) }.getOrNull()
                    if (!value.isNullOrBlank()) return value
                }
            }
        }
        return oldPostReelSheetItemName(item)
    }

    private fun oldPostReelNormalizeSheetLabel(label: String): String =
        label.replace('\n', ' ')
            .replace('\r', ' ')
            .trim()
            .lowercase(Locale.US)
            .replace(Regex("\\s+"), " ")

    private fun oldPostReelSheetRowIcon(item: Any?): Int {
        if (item == null) return 0
        val fields = oldPostReelDeclaredFieldsInHierarchy(item.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .onEach { it.isAccessible = true }
        listOf("A01", "A06").forEach { name ->
            fields.firstOrNull { it.name == name && it.type == java.lang.Integer.TYPE }?.let { field ->
                val value = runCatching { field.getInt(item) }.getOrDefault(0)
                if (value > 0) return value
            }
        }
        return 0
    }

    private fun oldPostReelSheetRowClick(item: Any?): View.OnClickListener? {
        if (item == null) return null
        return oldPostReelDeclaredFieldsInHierarchy(item.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .firstNotNullOfOrNull { field ->
                if (!View.OnClickListener::class.java.isAssignableFrom(field.type)) return@firstNotNullOfOrNull null
                runCatching {
                    field.isAccessible = true
                    field.get(item) as? View.OnClickListener
                }.getOrNull()
            }
    }

    private fun oldPostReelSetSheetRowLabel(item: Any?, label: String): Boolean {
        if (item == null) return false
        var changed = false
        oldPostReelDeclaredFieldsInHierarchy(item.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .filter { CharSequence::class.java.isAssignableFrom(it.type) }
            .forEach { field ->
                runCatching {
                    field.isAccessible = true
                    field.set(item, label)
                    changed = true
                }
            }
        return changed
    }

    private fun oldPostReelSetSheetRowIcon(item: Any?, icon: Int): Boolean {
        if (item == null || icon <= 0) return false
        var changed = false
        oldPostReelDeclaredFieldsInHierarchy(item.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .filter { it.type == java.lang.Integer.TYPE && it.name in setOf("A01", "A06") }
            .forEach { field ->
                runCatching {
                    field.isAccessible = true
                    field.setInt(item, icon)
                    changed = true
                }
