    private fun createOldPostReelHeaderAction(
        context: Context,
        label: String,
        icon: Int,
        listener: View.OnClickListener,
        callbackBase: Class<*>? = null
    ): Any? {
        val builderClass = findFirstClass("X.cnK", "X.C95171cnK") ?: return null
        val actionClass = findFirstClass("X.cVk", "X.C94366cVk") ?: return null
        val callback = createOldPostReelHeaderCallback(listener, callbackBase) ?: return null
        return runCatching {
            val builder = builderClass.declaredConstructors.firstOrNull { ctor ->
                val params = ctor.parameterTypes
                params.size == 2 && Context::class.java.isAssignableFrom(params[0]) && params[1] == String::class.java
            }?.apply { isAccessible = true }?.newInstance(context, label.lowercase(Locale.US).replace(" ", "_"))
                ?: return@runCatching null
            oldPostReelSetField(builder, "A05", label)
            oldPostReelSetField(builder, "A04", callback)
            oldPostReelSetField(builder, "A00", 1.0f)
            oldPostReelSetField(builder, "A06", label)
            oldPostReelSetField(builder, "A07", false)
            oldPostReelSetField(builder, "A08", true)
            if (icon > 0) {
                builderClass.declaredMethods.firstOrNull { method ->
                    method.returnType == java.lang.Void.TYPE &&
                        method.parameterTypes.size == 1 &&
                        method.parameterTypes[0] == java.lang.Integer.TYPE
                }?.apply { isAccessible = true }?.invoke(builder, icon)
            }
            actionClass.declaredConstructors.firstOrNull { ctor ->
                ctor.parameterTypes.size == 1 && ctor.parameterTypes[0].isAssignableFrom(builderClass)
            }?.apply { isAccessible = true }?.newInstance(builder)
        }.onFailure { logError("Old post/reel header action create failed label=$label icon=$icon", it) }.getOrNull()
    }

    private fun createOldPostReelHeaderCallback(listener: View.OnClickListener, callbackBase: Class<*>? = null): Any? {
        createOldPostReelCallbackProxy(listener, callbackBase)?.let { return it }
        createOldPostReelFunction0Callback(listener, callbackBase)?.let { return it }
        val functionClass = oldPostReelKotlinFunctionClass("kotlin.jvm.functions.Function1", callbackBase?.classLoader)
            ?: return null.also {
                logOldPostReelBottomSheetRewrite(
                    recentInfoLogs,
                    "old_post_reel_function1_class_missing:${callbackBase?.name}",
                    "Old post/reel header Function1 class missing base=${callbackBase?.name}"
                )
            }
        val callbackClass = oldPostReelHeaderCallbackClass(callbackBase) ?: return null
        val wrapperClass = oldPostReelHeaderWrapperClass(functionClass) ?: return null
        return runCatching {
            val wrapper = wrapperClass.declaredConstructors.firstOrNull { it.parameterTypes.isEmpty() }
                ?.apply { isAccessible = true }
                ?.newInstance() ?: return@runCatching null
            val function = Proxy.newProxyInstance(
                functionClass.classLoader,
                arrayOf(functionClass)
            ) { proxy, method, args ->
                when (method.name) {
                    "invoke" -> {
                        listener.onClick(args?.firstOrNull() as? View)
                        Unit
                    }
                    "toString" -> "PurrfectOldPostReelHeaderClick"
                    "hashCode" -> System.identityHashCode(proxy)
                    "equals" -> proxy === args?.firstOrNull()
                    else -> null
                }
            }
            oldPostReelSetField(wrapper, "A01", function)
            callbackClass.declaredConstructors.firstOrNull { ctor ->
                val params = ctor.parameterTypes
                params.size == 2 && params[1] == java.lang.Integer.TYPE
            }?.apply { isAccessible = true }?.newInstance(wrapper, 1)
        }.onFailure { logError("Old post/reel header callback create failed", it) }.getOrNull()
    }

    private fun createOldPostReelCallbackProxy(listener: View.OnClickListener, callbackBase: Class<*>?): Any? {
        if (callbackBase == null || !callbackBase.isInterface) return null
        return runCatching {
            Proxy.newProxyInstance(callbackBase.classLoader ?: appClassLoader, arrayOf(callbackBase)) { proxy, method, args ->
                when (method.name) {
                    "invoke", "onClick", "accept", "apply" -> {
                        listener.onClick(args?.firstOrNull() as? View)
                        defaultResult(method.returnType) ?: Unit
                    }
                    "toString" -> "PurrfectOldPostReelHeaderCallback"
                    "hashCode" -> System.identityHashCode(proxy)
                    "equals" -> proxy === args?.firstOrNull()
                    else -> defaultResult(method.returnType)
                }
            }
        }.onFailure {
            logError("Old post/reel header callback proxy failed base=${callbackBase.name}", it)
        }.getOrNull()
    }

    private fun createOldPostReelFunction0Callback(listener: View.OnClickListener, callbackBase: Class<*>?): Any? {
        if (callbackBase == null) return null
        val callbackClass = findFirstClass("X.0G9q", "X.C410160G9q")
            ?.takeIf { callbackBase.isAssignableFrom(it) } ?: return null.also {
                logOldPostReelBottomSheetRewrite(
                    recentInfoLogs,
                    "old_post_reel_function0_callback_impl_missing:${callbackBase.name}",
                    "Old post/reel header Function0 callback impl missing base=${oldPostReelTypeSummary(callbackBase, 620)} " +
                        "lookup=${oldPostReelClassLookupReport(listOf("X.0G9q", "X.C410160G9q"), 700)}"
                )
            }
        val function0Class = oldPostReelKotlinFunctionClass("kotlin.jvm.functions.Function0", callbackClass.classLoader)
            ?: return null.also {
                logOldPostReelBottomSheetRewrite(
                    recentInfoLogs,
                    "old_post_reel_function0_class_missing:${callbackBase.name}",
                    "Old post/reel header Function0 class missing base=${callbackBase.name} impl=${callbackClass.name}"
                )
            }
        val ctor = callbackClass.declaredConstructors.firstOrNull { constructor ->
            val params = constructor.parameterTypes
            params.size == 3 && params[0] == java.lang.Integer.TYPE
        }?.apply { isAccessible = true } ?: return null.also {
            logOldPostReelBottomSheetRewrite(
                recentInfoLogs,
                "old_post_reel_function0_ctor_missing:${callbackBase.name}",
                "Old post/reel header Function0 callback ctor missing base=${callbackBase.name} impl=${oldPostReelTypeSummary(callbackClass, 760)}"
            )
        }
        return runCatching {
            val function = Proxy.newProxyInstance(function0Class.classLoader ?: appClassLoader, arrayOf(function0Class)) { proxy, method, args ->
                when (method.name) {
                    "invoke" -> {
                        listener.onClick(null)
                        defaultResult(method.returnType) ?: Unit
                    }
                    "toString" -> "PurrfectOldPostReelHeaderFunction0"
                    "hashCode" -> System.identityHashCode(proxy)
                    "equals" -> proxy === args?.firstOrNull()
                    else -> defaultResult(method.returnType)
                }
            }
            ctor.newInstance(7, function, null).also { callback ->
                logOldPostReelBottomSheetRewrite(
                    recentInfoLogs,
                    "old_post_reel_function0_callback_created:${callbackBase.name}",
                    "Old post/reel header Function0 callback created base=${callbackBase.name} impl=${callbackClass.name} " +
                        "function=${function0Class.name} ctor=${oldPostReelConstructorSummary(callbackClass, 240)} callback=${callback?.javaClass?.name}"
                )
            }
        }.onFailure {
            logError("Old post/reel header Function0 callback failed base=${callbackBase.name} impl=${callbackClass.name}", it)
        }.getOrNull()
    }

    private fun oldPostReelKotlinFunctionClass(name: String, preferredLoader: ClassLoader?): Class<*>? {
        val loaders = listOfNotNull(
            preferredLoader,
            appClassLoader,
            InstagramHooks::class.java.classLoader,
            Thread.currentThread().contextClassLoader
        ).distinct()
        loaders.forEach { loader ->
            runCatching { Class.forName(name, false, loader) }.getOrNull()?.let { return it }
        }
        return runCatching { Class.forName(name) }.getOrNull()
    }

