    private fun oldPostReelBottomSheetRowDetails(context: Context, rows: List<Any?>): String =
        rows.joinToString("|") { row ->
            val label = oldPostReelSheetRowLabel(context, row).orEmpty().replace("|", "/")
            val icon = oldPostReelSheetRowIcon(row)
            val listener = oldPostReelSheetRowClick(row)?.javaClass?.name ?: "-"
            "${row?.javaClass?.name ?: "null"}:$label:icon=$icon:click=$listener"
        }

    private fun oldPostReelSafeValueSummary(value: Any?): String {
        if (value == null) return "null"
        return runCatching {
            when (value) {
                is CharSequence -> value.toString().replace('\n', ' ').replace('\r', ' ').take(80)
                is Number, is Boolean -> value.toString()
                is Collection<*> -> {
                    val items = value.take(5).joinToString(",") { oldPostReelSafeValueSummary(it).take(40) }
                    "${value.javaClass.name}[size=${value.size};$items]"
                }
                is Map<*, *> -> "${value.javaClass.name}[size=${value.size}]"
                is View -> "View(${value.javaClass.name})"
                is Context -> "Context(${value.javaClass.name})"
                else -> {
                    val cls = value.javaClass
                    if (cls.isEnum) value.toString() else cls.name
                }
            }
        }.getOrDefault(value.javaClass.name)
    }

    private fun oldPostReelShallowFieldSummary(value: Any?, maxFields: Int = 18, maxChars: Int = 900): String {
        if (value == null) return "null"
        return runCatching {
            oldPostReelDeclaredFieldsInHierarchy(value.javaClass)
                .asSequence()
                .filterNot { Modifier.isStatic(it.modifiers) }
                .take(maxFields)
                .joinToString("|") { field ->
                    field.isAccessible = true
                    "${field.name}:${field.type.name}=${oldPostReelSafeValueSummary(field.get(value)).take(90)}"
                }
                .take(maxChars)
        }.getOrDefault("<fields-error:${value.javaClass.name}>")
    }

    private fun oldPostReelCollectionSummary(values: Collection<*>?, maxItems: Int = 14, maxChars: Int = 900): String {
        if (values == null) return "null"
        return values.take(maxItems)
            .joinToString("|") { value -> oldPostReelSafeValueSummary(value).replace("|", "/").take(80) }
            .let { "${values.javaClass.name}[size=${values.size};$it]" }
            .take(maxChars)
    }

    private fun oldPostReelMowDetails(mows: Collection<Any>, maxItems: Int = 14, maxChars: Int = 1800): String =
        mows.take(maxItems).joinToString(" || ") { mow ->
            val option = oldPostReelMowOptionName(mow).orEmpty()
            val text = oldPostReelMowText(mow).orEmpty().replace('\n', ' ').replace('\r', ' ')
            val enabled = oldPostReelMowEnabled(mow)
            "${mow.javaClass.name}{option=$option;text=${text.take(80)};enabled=$enabled;" +
                "fields=${oldPostReelShallowFieldSummary(mow, 8, 260)}}"
        }.take(maxChars)

    private fun oldPostReelConstructorSummary(type: Class<*>?, maxChars: Int = 600): String {
        if (type == null) return "null"
        return runCatching {
            type.declaredConstructors.joinToString("|") { ctor ->
                "${type.name}(${ctor.parameterTypes.joinToString(",") { it.name }})"
            }.take(maxChars)
        }.getOrDefault("<ctor-error:${type.name}>")
    }

    private fun oldPostReelTypeSummary(type: Class<*>?, maxChars: Int = 1000): String {
        if (type == null) return "null"
        return runCatching {
            val methods = type.declaredMethods
                .filterNot { Modifier.isStatic(it.modifiers) }
                .joinToString("|") { method ->
                    "${method.name}(${method.parameterTypes.joinToString(",") { it.name }}):${method.returnType.name}"
                }
                .take(420)
            val fields = oldPostReelDeclaredFieldsInHierarchy(type)
                .filterNot { Modifier.isStatic(it.modifiers) }
                .take(14)
                .joinToString("|") { field -> "${field.name}:${field.type.name}" }
                .take(260)
            "name=${type.name} interface=${type.isInterface} abstract=${Modifier.isAbstract(type.modifiers)} " +
                "super=${type.superclass?.name} interfaces=${type.interfaces.joinToString(",") { it.name }.take(260)} " +
                "ctors=${oldPostReelConstructorSummary(type, 260)} fields=$fields methods=$methods"
        }.getOrDefault("<type-error:${type.name}>").take(maxChars)
    }

    private fun oldPostReelHeaderCallbackReport(callbackBase: Class<*>?, maxClasses: Int = 18, maxChars: Int = 1800): String {
        val functionName = runCatching { Class.forName("kotlin.jvm.functions.Function1", false, appClassLoader).name }
            .getOrDefault("kotlin.jvm.functions.Function1")
        val names = LinkedHashSet<String>()
        listOf(
            "X.TLt",
            "X.C73834TLt",
            "X.0G9q",
            "X.C410160G9q",
            "X.0RLr",
            "X.C693410RLr",
            callbackBase?.name
        ).filterNotNull().forEach { names += it }
        runCatching { names += dexBridge.findClassNamesWithFieldNames("\$t", "A00").take(160) }
        runCatching { names += dexBridge.findClassNamesWithFieldNames("\$t", "A00", "A01").take(160) }
        runCatching { names += dexBridge.findClassNamesWithFieldTypes(functionName).take(120) }
        return names.asSequence()
            .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
            .distinctBy { it.name }
            .filter { cls ->
                cls == callbackBase ||
                    callbackBase == null ||
                    callbackBase.isAssignableFrom(cls) ||
                    cls.interfaces.any { iface -> iface.name == callbackBase.name }
            }
            .take(maxClasses)
            .joinToString(" || ") { cls -> oldPostReelTypeSummary(cls, 360) }
            .ifBlank { "<none> base=${oldPostReelTypeSummary(callbackBase, 520)}" }
            .take(maxChars)
    }

    private fun oldPostReelClassLookupReport(names: Collection<String>, maxChars: Int = 1200): String =
        names.distinct().joinToString("|") { name ->
            runCatching {
                val cls = Class.forName(name, false, appClassLoader)
                "$name=ok:onClick=${View.OnClickListener::class.java.isAssignableFrom(cls)};ctors=${oldPostReelConstructorSummary(cls, 220)}"
            }.getOrElse { throwable ->
                "$name=miss:${throwable.javaClass.simpleName}:${throwable.message.orEmpty().take(90)}"
            }
        }.take(maxChars)

    private fun oldPostReelLegacyClickCandidateReport(maxClasses: Int = 24, maxChars: Int = 1800): String {
        val names = LinkedHashSet<String>()
        names += "X.AzB"
        names += "X.ViewOnClickListenerC27986AzB"
        runCatching { names += dexBridge.findClassNamesWithFieldNames("\$t", "A00", "A01").take(80) }
        runCatching {
            names += dexBridge.findMethodsUsingNumbersConstrained(listOf(39), paramCount = 1, returnType = "void")
                .map { it.declaringClass.name }
                .take(80)
        }
        return names.mapNotNull { name ->
            runCatching { Class.forName(name, false, appClassLoader) }.getOrNull()
        }
            .distinctBy { it.name }
            .filter { cls ->
                View.OnClickListener::class.java.isAssignableFrom(cls) &&
                    cls.declaredConstructors.any { ctor ->
                        ctor.parameterTypes.size == 3 && ctor.parameterTypes[0] == java.lang.Integer.TYPE
                    }
            }
            .take(maxClasses)
            .joinToString("|") { cls ->
                "${cls.name}:fields=${oldPostReelDeclaredFieldsInHierarchy(cls).filterNot { Modifier.isStatic(it.modifiers) }.joinToString(",") { "${it.name}:${it.type.name}" }.take(180)}"
            }
            .ifBlank { "<none>" }
            .take(maxChars)
    }

    private fun oldPostReelMediaOverflowOptionHandler(overflowHelper: Any, optionClass: Class<*>): Method? =
        oldPostReelDeclaredMethodsInHierarchy(overflowHelper.javaClass)
            .firstOrNull { candidate ->
                !Modifier.isStatic(candidate.modifiers) &&
                    candidate.returnType == java.lang.Void.TYPE &&
                    candidate.parameterTypes.size == 1 &&
                    candidate.parameterTypes[0].isAssignableFrom(optionClass)
            }?.apply { isAccessible = true }

    private fun oldPostReelHeaderActionMethod(methods: Collection<Method>): Method? =
        methods.firstOrNull { candidate ->
            val params = candidate.parameterTypes
            candidate.returnType == java.lang.Void.TYPE &&
                params.size == 8 &&
                Context::class.java.isAssignableFrom(params[0]) &&
                !params[1].isPrimitive &&
                params[2] == String::class.java &&
                params[3] == String::class.java &&
                params[4] == String::class.java &&
                params[5] == java.lang.Float.TYPE &&
                params[6] == java.lang.Integer.TYPE &&
                params[7] == java.lang.Boolean.TYPE
        }?.apply { isAccessible = true }

    private fun oldPostReelHeaderCallbackClass(callbackBase: Class<*>?): Class<*>? {
        fun matches(cls: Class<*>): Boolean =
            (callbackBase == null || callbackBase.isAssignableFrom(cls)) &&
                cls.declaredConstructors.any { ctor ->
                    val params = ctor.parameterTypes
                    params.size == 2 && !params[0].isPrimitive && params[1] == java.lang.Integer.TYPE
                }

        listOf("X.TLt", "X.C73834TLt").forEach { name ->
            runCatching { Class.forName(name, false, appClassLoader) }.getOrNull()
                ?.takeIf(::matches)
                ?.let { return it }
        }

        val names = LinkedHashSet<String>()
        runCatching { names += dexBridge.findClassNamesWithFieldNames("\$t", "A00").take(140) }
        return names.asSequence()
            .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
            .distinctBy { it.name }
            .firstOrNull(::matches)
    }

    private fun oldPostReelHeaderWrapperClass(functionClass: Class<*>): Class<*>? {
        fun matches(cls: Class<*>): Boolean =
            cls.declaredConstructors.any { it.parameterTypes.isEmpty() } &&
                oldPostReelDeclaredFieldsInHierarchy(cls).any { field ->
                    !Modifier.isStatic(field.modifiers) &&
                        field.name == "A01" &&
                        field.type.isAssignableFrom(functionClass)
                }

        listOf("X.POB").forEach { name ->
            runCatching { Class.forName(name, false, appClassLoader) }.getOrNull()
                ?.takeIf(::matches)
                ?.let { return it }
        }

        val names = LinkedHashSet<String>()
        runCatching { names += dexBridge.findClassNamesWithFieldTypes(functionClass.name).take(80) }
        return names.asSequence()
            .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
            .distinctBy { it.name }
            .firstOrNull(::matches)
    }

    private fun scheduleOldPostReelHeaderClickFallback(
        context: Context,
        listeners: Map<String, View.OnClickListener>
    ) {
        if (listeners.isEmpty()) return
        val activity = findActivity(context) ?: currentActivity ?: return
        val root = activity.window?.decorView ?: return
        val stableListeners = LinkedHashMap(listeners)
        listOf(120L, 420L, 900L, 1_600L, 2_600L).forEach { delayMs ->
            mainHandler.postDelayed({
                val liveRoot = (findActivity(context) ?: currentActivity)?.window?.decorView ?: root
                val bindReport = bindOldPostReelHeaderClickFallback(liveRoot, stableListeners)
                logOldPostReelBottomSheetRewrite(
                    recentInfoLogs,
                    "old_post_reel_header_click_fallback_bound:${stableListeners.keys.joinToString(",")}:$delayMs",
                    "Old post/reel media overflow header click fallback delay=$delayMs $bindReport " +
                        "labels=${stableListeners.keys.joinToString("|")} root=${liveRoot.javaClass.name}"
                )
            }, delayMs)
        }
    }

    private fun bindOldPostReelHeaderClickFallback(
        root: View,
        listeners: Map<String, View.OnClickListener>
    ): String {
        var visited = 0
        var bound = 0
        val candidates = mutableListOf<String>()

        fun hasActionSheetHeaderAncestor(view: View): Boolean {
            var current = view.parent as? View
            repeat(8) {
                val name = current?.let { resourceEntryName(it) }.orEmpty()
                if (name == "custom_header_view" || name == "action_sheet_container") return true
                current = current?.parent as? View
            }
            return false
        }

        fun clickableTarget(view: View): View? {
            if (view.isClickable) return view
            var current = view.parent as? View
            repeat(4) {
                val candidate = current ?: return null
                if (candidate.isClickable) return candidate
                current = candidate.parent as? View
            }
            return null
        }

        fun bindableHeaderTarget(view: View, hasHeaderAncestor: Boolean, looksLikeHeader: Boolean): View? {
            clickableTarget(view)?.let { target ->
                val targetId = resourceEntryName(target).orEmpty()
                if (hasHeaderAncestor || targetId.isBlank()) return target
            }
            val ownId = resourceEntryName(view).orEmpty()
            if (hasHeaderAncestor || (looksLikeHeader && ownId.isBlank())) return view
            return null
        }

        fun locationSummary(view: View): String {
            val location = IntArray(2)
            runCatching { view.getLocationOnScreen(location) }
            return "${location[0]},${location[1]} ${view.width}x${view.height}"
        }

        fun visit(view: View) {
            if (visited++ > 1_400) return
            val label = oldPostReelNormalizeSheetLabel(view.contentDescription?.toString().orEmpty())
            val listener = listeners[label]
            if (listener != null && view.isShown) {
                val hasHeaderAncestor = hasActionSheetHeaderAncestor(view)
                val looksLikeHeader = oldPostReelLooksLikeRenderedHeaderIcon(view)
                val target = bindableHeaderTarget(view, hasHeaderAncestor, looksLikeHeader)
                if (candidates.size < 12) {
                    candidates += "$label view=${view.javaClass.name} id=${resourceEntryName(view)} loc=${locationSummary(view)} " +
                        "click=${view.isClickable} target=${target?.javaClass?.name ?: "null"} targetId=${target?.let(::resourceEntryName).orEmpty()} " +
                        "ancestor=$hasHeaderAncestor geometry=$looksLikeHeader"
                }
                if (target != null && (hasHeaderAncestor || looksLikeHeader)) {
                    target.isClickable = true
                    target.setOnClickListener { clicked ->
                        logOldPostReelBottomSheetRewrite(
                            recentInfoLogs,
                            "old_post_reel_header_click_fallback_dispatch:$label",
                            "Old post/reel media overflow header click fallback dispatch label=$label " +
                                "view=${clicked.javaClass.name} target=${target.javaClass.name}"
                        )
                        listener.onClick(clicked)
                    }
                    target.setOnTouchListener { touched, event ->
                        if (event.action == MotionEvent.ACTION_UP) {
                            logOldPostReelBottomSheetRewrite(
                                recentInfoLogs,
                                "old_post_reel_header_touch_fallback_dispatch:$label",
                                "Old post/reel media overflow header touch fallback dispatch label=$label " +
                                    "view=${touched.javaClass.name} target=${target.javaClass.name}"
                            )
                            listener.onClick(touched)
                        }
                        true
                    }
                    bound++
                }
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) visit(view.getChildAt(i))
            }
        }

        visit(root)
        return "bound=$bound visited=$visited candidates=${candidates.joinToString(" || ").take(1200)}"
    }

    private fun oldPostReelLooksLikeRenderedHeaderIcon(view: View): Boolean {
        val label = oldPostReelNormalizeSheetLabel(view.contentDescription?.toString().orEmpty())
        if (label !in setOf("share", "link", "save")) return false
        if (view.width < 80 || view.height < 80) return false
        val location = IntArray(2)
        view.getLocationOnScreen(location)
        val rootHeight = view.rootView?.height ?: 0
        return location[1] in 700..1800 && (rootHeight <= 0 || location[1] < rootHeight - 480)
    }

    private fun logOldPostReelBottomSheetRewrite(
        logTimes: ConcurrentHashMap<String, Long>,
        key: String,
        message: String
    ) {
        val now = SystemClock.elapsedRealtime()
        val previous = logTimes[key] ?: 0L
        if (now - previous < 2_000L) return
        logTimes[key] = now
        if (logTimes.size > 80) logTimes.clear()
        logInfo(message)
    }

    private fun oldPostReelSheetItemName(item: Any?): String? {
        if (item == null) return null
        val cls = item.javaClass
        cls.declaredFields.firstOrNull { field ->
            field.type.name == "com.instagram.feed.media.mediaoption.MediaOption\$Option"
        }?.let { field ->
            return runCatching {
                field.isAccessible = true
                field.get(item)?.toString()
            }.getOrNull()
        }
        cls.declaredFields.firstOrNull { field ->
            field.type == String::class.java && field.name in setOf("A0D", "A08", "A07")
        }?.let { field ->
            return runCatching {
                field.isAccessible = true
                field.get(item)?.toString()
            }.getOrNull()
        }
        return cls.simpleName.ifEmpty { cls.name.substringAfterLast('.') }
    }

    private fun installOldPostReelContextMenuMediaOverflowSheetHook() {
        runSafe("Old post/reel media overflow sheet hook") {
            val cacheKey = "OldPostReelContextMenuMediaOverflowSheet_v1"
            val cached = if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethods(cacheKey, appClassLoader).orEmpty()
                    .filter(::isOldPostReelContextMenuMediaOverflowBuildMethod)
            } else {
                emptyList()
            }
            if (cached.isNotEmpty()) {
                val hooked = hookOldPostReelContextMenuMediaOverflowBuildMethods(cached, "cached")
                if (hooked > 0) {
                    logInfo("Installed old post/reel media overflow sheet hook(s)=$hooked source=cached candidates=${cached.size}")
                    return@runSafe
                }
                logInfo("Old post/reel media overflow cached candidates did not hook; retrying DexKit discovery")
            }

            val directClasses = listOf("X.8vN", "X.C226548vN")
                .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
            val discoveredClasses = dexBridge.findClassNamesUsingStrings("MediaOverflowBottomSheetHelper")
                .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
            val discovered = (directClasses + discoveredClasses)
                .distinctBy { it.name }
                .flatMap { cls -> cls.declaredMethods.toList() }
                .filter(::isOldPostReelContextMenuMediaOverflowBuildMethod)
                .distinctBy(::methodKey)

            if (discovered.isNotEmpty()) InstagramDexKitCache.saveMethods(cacheKey, discovered)
            val hooked = hookOldPostReelContextMenuMediaOverflowBuildMethods(discovered, "dex")
            if (hooked > 0) {
                val names = discovered.take(6).joinToString { "${it.declaringClass.name}.${it.name}:${it.parameterTypes.joinToString { p -> p.name }}" }
                logInfo("Installed old post/reel media overflow sheet hook(s)=$hooked source=dex candidates=${discovered.size} methods=$names")
            } else {
                logInfo("Old post/reel media overflow sheet hook not found")
            }
        }
    }

    private fun isOldPostReelContextMenuMediaOverflowBuildMethod(method: Method): Boolean {
        if (!Modifier.isStatic(method.modifiers) || method.returnType != java.lang.Void.TYPE) return false
        val params = method.parameterTypes
        return params.size == 6 &&
            params.any { it == method.declaringClass } &&
            java.util.List::class.java.isAssignableFrom(params[3]) &&
            params[4] == java.lang.Integer.TYPE &&
            params[5] == java.lang.Boolean.TYPE
    }

    private fun hookOldPostReelContextMenuMediaOverflowBuildMethods(methods: List<Method>, source: String): Int {
        var hooked = 0
        val logTimes = ConcurrentHashMap<String, Long>()
        methods.forEach { method ->
            val signature = "${methodKey(method)}:old_context_media_overflow_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.restoreOldPostReelContextMenu) return
                            val restored = rebuildAndShowOldPostReelMediaOverflowSheet(method, param.args, logTimes)
                            if (restored) param.result = null
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed old post/reel media overflow sheet hook $signature", it) }
        }
        return hooked
    }

    private fun rebuildAndShowOldPostReelMediaOverflowSheet(
        buildMethod: Method,
        args: Array<Any?>,
        logTimes: ConcurrentHashMap<String, Long>
    ): Boolean {
        return runCatching {
            val key = "${buildMethod.declaringClass.name}.${buildMethod.name}"
            fun logMediaOverflowStage(stage: String, detail: () -> String) {
                val now = SystemClock.elapsedRealtime()
                val logKey = "$key:$stage"
                val previous = logTimes[logKey] ?: 0L
                if (now - previous >= 2_000L) {
                    logTimes[logKey] = now
                    if (logTimes.size > 80) logTimes.clear()
                    logInfo("Old post/reel media overflow $stage ${detail().take(2800)} method=$key")
                }
            }
            fun abort(reason: String, detail: () -> String = { "" }): Boolean {
                logMediaOverflowStage("restore skipped") {
                    "reason=$reason args=${args.map { it?.javaClass?.name ?: "null" }.joinToString("|").take(260)} ${detail()}"
                }
                return false
            }

            val media = args.getOrNull(0) ?: return@runCatching abort("missing_media")
            val mediaState = args.getOrNull(1) ?: return@runCatching abort("missing_media_state")
            val helper = args.getOrNull(2) ?: return@runCatching abort("missing_helper")
            val filterList = args.getOrNull(3) as? Collection<*>
            val mediaIndex = args.getOrNull(4) as? Int ?: return@runCatching abort("missing_media_index")
            val includeSelfOptions = args.getOrNull(5) as? Boolean ?: false
            val helperSurfaceSummary = oldPostReelShallowFieldSummary(helper, 16, 900)
            val sinceReelDownloadMenuBuildMs = SystemClock.elapsedRealtime() - lastReelDownloadMenuBuildAtMs
            val mediaOverflowLooksReel =
                helper.javaClass.name.contains("clips", ignoreCase = true) ||
                    media.javaClass.name.contains("clips", ignoreCase = true) ||
                    mediaState.javaClass.name.contains("clips", ignoreCase = true) ||
                    helperSurfaceSummary.contains("clips", ignoreCase = true) ||
                    helperSurfaceSummary.contains("reel", ignoreCase = true) ||
                    sinceReelDownloadMenuBuildMs in 0L..1_500L
            logMediaOverflowStage("restore invoked") {
                "helper=${helper.javaClass.name} filter=${filterList?.size ?: -1} index=$mediaIndex " +
                    "includeSelf=$includeSelfOptions media=${media.javaClass.name} state=${mediaState.javaClass.name} " +
                    "reelSurface=$mediaOverflowLooksReel sinceReelMenuMs=$sinceReelDownloadMenuBuildMs helperFields=$helperSurfaceSummary " +
                    "filterItems=${oldPostReelCollectionSummary(filterList, 16, 700)}"
            }

            val helperClass = buildMethod.declaringClass
            val createHelpers = helperClass.declaredMethods.filter { candidate ->
                Modifier.isStatic(candidate.modifiers) &&
                    candidate.returnType != java.lang.Void.TYPE &&
                    candidate.parameterTypes.size == 5 &&
                    candidate.parameterTypes[0].isAssignableFrom(media.javaClass) &&
                    candidate.parameterTypes[1].isAssignableFrom(mediaState.javaClass) &&
                    candidate.parameterTypes[2] == helperClass &&
                    candidate.parameterTypes[3] == java.lang.Integer.TYPE &&
                    candidate.parameterTypes[4] == java.lang.Boolean.TYPE
            }.onEach { it.isAccessible = true }
            if (createHelpers.isEmpty()) {
                return@runCatching abort("create_helper_missing") {
                    "helperMethods=${oldPostReelMethodSummary(helperClass.declaredMethods.toList(), 900)}"
                }
            }
            val fragment = oldPostReelField(helper, "A01") ?: return@runCatching abort("fragment_missing")
            val context = fragment.javaClass.methods.firstOrNull { it.name == "requireContext" && it.parameterTypes.isEmpty() }
                ?.invoke(fragment) as? Context ?: return@runCatching abort("context_missing")
            val optionClass = runCatching {
                Class.forName("com.instagram.feed.media.mediaoption.MediaOption\$Option", false, appClassLoader)
            }.getOrNull() ?: return@runCatching abort("option_class_missing")
            if (tryShowOldPostReelPreemptiveCustomMediaOverflow(
                    context = context,
                    media = media,
                    mediaState = mediaState,
                    helper = helper,
                    helperClass = helperClass,
                    createHelpers = createHelpers,
                    filterList = filterList,
                    mediaIndex = mediaIndex,
                    includeSelfOptions = includeSelfOptions,
                    optionClass = optionClass,
                    mediaOverflowLooksReel = mediaOverflowLooksReel,
                    key = key,
                    logMediaOverflowStage = { stage, detail -> logMediaOverflowStage(stage, detail) }
                )
            ) {
                return@runCatching true
            }
            val userSession = oldPostReelField(helper, "A04") ?: return@runCatching abort("user_session_missing")
            var overflowHelper: Any? = null
            var mows: List<Any> = emptyList()
            val createSummaries = mutableListOf<String>()
            val mowSummaries = mutableListOf<String>()
            for (candidate in createHelpers) {
                val candidateHelper = runCatching {
                    candidate.invoke(null, media, mediaState, helper, mediaIndex, includeSelfOptions)
                }.getOrNull()
                val candidateAllMows = candidateHelper?.let { oldPostReelMediaOverflowMows(it, null) }.orEmpty()
                val candidateFilteredMows = candidateHelper?.let { oldPostReelMediaOverflowMows(it, filterList) }.orEmpty()
                val candidateMows = candidateAllMows.takeIf { list ->
                    list.mapNotNull(::oldPostReelMowOptionName)
                        .any { it in setOf("SHARE_LINK", "SHARE", "COPY_LINK", "COPY_FUNDRAISER_LINK", "SAVE", "UNSAVE") }
                } ?: candidateFilteredMows
                createSummaries += "${candidate.name}:${candidate.returnType.name}:${candidateHelper?.javaClass?.name ?: "null"}:${candidateAllMows.size}/${candidateFilteredMows.size}"
                mowSummaries += "${candidate.name}:all=${candidateAllMows.mapNotNull(::oldPostReelMowOptionName).joinToString(",").take(220)}:" +
                    "filtered=${candidateFilteredMows.mapNotNull(::oldPostReelMowOptionName).joinToString(",").take(220)}"
                if (candidateHelper != null && candidateMows.isNotEmpty()) {
                    overflowHelper = candidateHelper
                    mows = candidateMows
                    break
                }
            }
            val resolvedOverflowHelper = overflowHelper ?: return@runCatching abort(
                "mows_empty"
            ) {
                "factories=${createSummaries.joinToString("|").take(700)} " +
                    "mows=${mowSummaries.joinToString(" || ").take(1200)}"
            }
            val optionNames = mows.mapNotNull(::oldPostReelMowOptionName)
            if (!optionNames.any { it in setOf("SHARE_LINK", "SHARE", "COPY_LINK", "COPY_FUNDRAISER_LINK", "SAVE", "UNSAVE") }) {
                return@runCatching abort("classic_icon_options_missing") {
                    "options=${optionNames.joinToString("|").take(500)} mows=${oldPostReelMowDetails(mows)}"
                }
            }
            if (mediaOverflowLooksReel) {
                logMediaOverflowStage("reel detector matched") {
                    "sinceReelMenuMs=$sinceReelDownloadMenuBuildMs sourceOptions=${optionNames.joinToString("|").take(700)} " +
                        "helper=${helper.javaClass.name} media=${media.javaClass.name} state=${mediaState.javaClass.name} " +
                        "helperFields=$helperSurfaceSummary mows=${oldPostReelMowDetails(mows)}"
                }
            }
            logMediaOverflowStage("helper resolved") {
                "factories=${createSummaries.joinToString("|").take(700)} " +
                    "selectedHelper=${resolvedOverflowHelper.javaClass.name} " +
                    "selectedFields=${oldPostReelShallowFieldSummary(resolvedOverflowHelper, 20, 1100)} " +
                    "options=${optionNames.joinToString("|").take(700)} " +
                    "mows=${oldPostReelMowDetails(mows)}"
            }

            val directClickMethod = oldPostReelMediaOverflowOptionHandler(resolvedOverflowHelper, optionClass)
            val clickClass = if (directClickMethod == null) findFirstClass("X.AzB", "X.ViewOnClickListenerC27986AzB") else null
            val clickCtor = clickClass?.declaredConstructors?.firstOrNull { ctor ->
                ctor.parameterTypes.size == 3 && ctor.parameterTypes[0] == java.lang.Integer.TYPE
            }?.apply { isAccessible = true }
            if (directClickMethod == null && clickCtor == null) {
                return@runCatching abort("click_handler_missing") {
                    "lookup=${oldPostReelClassLookupReport(listOf("X.AzB", "X.ViewOnClickListenerC27986AzB"))} " +
                        "legacyCandidates=${oldPostReelLegacyClickCandidateReport()} " +
                        "overflowMethods=${oldPostReelMethodSummary(oldPostReelDeclaredMethodsInHierarchy(resolvedOverflowHelper.javaClass), 1200)} " +
                        "overflowFields=${oldPostReelShallowFieldSummary(resolvedOverflowHelper, 20, 1100)} " +
                        "mows=${oldPostReelMowDetails(mows)}"
                }
            }
            val manageClickClass = findFirstClass("X.Nnr", "X.ViewOnClickListenerC60398Nnr")
            val manageClickCtor = manageClickClass?.declaredConstructors?.firstOrNull { ctor ->
                ctor.parameterTypes.size == 2 && ctor.parameterTypes[1] == java.lang.Integer.TYPE
            }?.apply { isAccessible = true }

            if (tryShowOldPostReelFastCustomMediaOverflow(
                    context = context,
                    media = media,
                    helper = helper,
                    helperClass = helperClass,
                    overflowHelper = resolvedOverflowHelper,
                    mows = mows,
                    optionNames = optionNames,
                    optionClass = optionClass,
                    directClickMethod = directClickMethod,
                    clickCtor = clickCtor,
                    manageClickCtor = manageClickCtor,
                    mediaOverflowLooksReel = mediaOverflowLooksReel,
                    key = key,
                    logMediaOverflowStage = { stage, detail -> logMediaOverflowStage(stage, detail) }
                )
            ) {
                return@runCatching true
            }

            val showSheet = helperClass.declaredMethods.firstOrNull { candidate ->
                Modifier.isStatic(candidate.modifiers) &&
                    candidate.returnType == java.lang.Void.TYPE &&
                    candidate.parameterTypes.size == 5 &&
                    candidate.parameterTypes[0].isAssignableFrom(media.javaClass) &&
                    candidate.parameterTypes[4] == helperClass &&
                    isOldPostReelContextMenuSheetModelClass(candidate.parameterTypes[2])
            }?.apply { isAccessible = true } ?: return@runCatching abort("show_sheet_missing") {
                "candidates=" + helperClass.declaredMethods
                    .filter { Modifier.isStatic(it.modifiers) && it.returnType == java.lang.Void.TYPE && it.parameterTypes.size == 5 }
                    .joinToString("|") { method -> "${method.name}:${method.parameterTypes.joinToString(",") { it.name }}" }
                    .take(700)
            }
            val cvvClass = showSheet.parameterTypes[2]
            val cvv = cvvClass.declaredConstructors.firstOrNull { ctor ->
                ctor.parameterTypes.size == 2 && ctor.parameterTypes[1] == String::class.java
            }?.apply { isAccessible = true }?.newInstance(userSession, "MediaOverflowBottomSheetHelper")
                ?: return@runCatching abort("cvv_ctor_missing class=${cvvClass.name}")

            val cvvMethods = oldPostReelDeclaredMethodsInHierarchy(cvvClass)
            val fullRowMethod = cvvMethods.firstOrNull { candidate ->
                val params = candidate.parameterTypes
                candidate.returnType == java.lang.Void.TYPE &&
                    params.size == 10 &&
                    Context::class.java.isAssignableFrom(params[0]) &&
                    View.OnClickListener::class.java.isAssignableFrom(params[1]) &&
                    (params[2] == String::class.java || CharSequence::class.java.isAssignableFrom(params[2])) &&
                    params[4] == java.lang.Float.TYPE &&
                    params[5] == java.lang.Integer.TYPE
            }?.apply { isAccessible = true }
            val compactRowMethod = cvvMethods.firstOrNull { candidate ->
                val params = candidate.parameterTypes
                candidate.returnType == java.lang.Void.TYPE &&
                    params.size == 5 &&
                    Context::class.java.isAssignableFrom(params[0]) &&
                    View.OnClickListener::class.java.isAssignableFrom(params[1]) &&
                    (params[2] == String::class.java || CharSequence::class.java.isAssignableFrom(params[2])) &&
                    params[3] == java.lang.Integer.TYPE &&
                    params[4] == java.lang.Boolean.TYPE
            }?.apply { isAccessible = true }
            val simpleRowMethod = cvvMethods.firstOrNull { candidate ->
                val params = candidate.parameterTypes
                candidate.returnType == java.lang.Void.TYPE &&
                    params.size == 4 &&
                    Context::class.java.isAssignableFrom(params[0]) &&
                    View.OnClickListener::class.java.isAssignableFrom(params[1]) &&
                    (params[2] == String::class.java || CharSequence::class.java.isAssignableFrom(params[2])) &&
                    params[3] == java.lang.Integer.TYPE
            }?.apply { isAccessible = true }
            val headerActionMethod = oldPostReelHeaderActionMethod(cvvMethods)
            if (fullRowMethod == null && compactRowMethod == null && simpleRowMethod == null) {
                return@runCatching abort(
                    "row_method_missing"
                ) {
                    "class=${cvvClass.name} methods=${oldPostReelMethodSummary(cvvMethods, 1200)} " +
                        "cvvFields=${oldPostReelShallowFieldSummary(cvv, 20, 1100)}"
                }
            }
            val primaryList = oldPostReelPrimarySheetList(cvv) as? MutableList<Any?>
                ?: return@runCatching abort("primary_list_missing class=${cvvClass.name}")
            val actionHeader = oldPostReelActionSheetLists(cvv).firstOrNull()
                ?: return@runCatching abort("action_header_missing class=${cvvClass.name}")
            val dividerClass = findFirstClass("X.ORl", "X.C61862ORl")
            logMediaOverflowStage("sheet builder resolved") {
                "cvv=${cvvClass.name} primary=${primaryList.size} actionHeader=${actionHeader.size} " +
                    "rows=full:${fullRowMethod?.name} compact:${compactRowMethod?.name} simple:${simpleRowMethod?.name} " +
                    "header=${headerActionMethod?.name}:${headerActionMethod?.parameterTypes?.getOrNull(1)?.name} " +
                    "headerBase=${oldPostReelTypeSummary(headerActionMethod?.parameterTypes?.getOrNull(1), 680)} " +
                    "clickPath=${directClickMethod?.let { "direct:${it.declaringClass.name}.${it.name}" } ?: "legacy:${clickClass?.name}"} " +
                    "legacyLookup=${oldPostReelClassLookupReport(listOf("X.AzB", "X.ViewOnClickListenerC27986AzB"), 700)} " +
                    "manageClick=${manageClickClass?.name}:${manageClickCtor != null} cvvFields=${oldPostReelShallowFieldSummary(cvv, 20, 1100)}"
            }

            fun optionByName(name: String): Any? =
                optionClass.enumConstants?.firstOrNull { it.toString() == name }

            fun iconDrawable(option: Any?): Int =
                runCatching { option?.javaClass?.getMethod("getIconDrawable")?.invoke(option) as? Int ?: 0 }.getOrDefault(0)

            val renderFailures = mutableListOf<String>()
            var headerCallbackReportLogged = false
            val headerClickFallbacks = LinkedHashMap<String, View.OnClickListener>()
            val customHeaderActions = mutableListOf<OldPostReelMenuAction>()
            val customRowActions = mutableListOf<OldPostReelMenuAction>()
            val customHeaderKeys = LinkedHashSet<String>()
            val customRowKeys = LinkedHashSet<String>()
            var customDividerBeforeNextRow = false

            fun customActionKey(action: OldPostReelMenuAction): String =
                action.optionName.ifBlank { oldPostReelNormalizeSheetLabel(action.label) }

            fun rememberCustomHeader(action: OldPostReelMenuAction) {
                if (customHeaderKeys.add(customActionKey(action))) customHeaderActions += action
            }

            fun rememberCustomRow(action: OldPostReelMenuAction) {
                if (customRowKeys.add(customActionKey(action))) customRowActions += action
            }

            fun clickFor(mow: Any): View.OnClickListener? {
                val option = oldPostReelMowOptionValue(mow)
                val optionName = option?.toString() ?: oldPostReelMowOptionName(mow).orEmpty()
                if (option != null && directClickMethod != null) {
                    return object : View.OnClickListener {
                        override fun onClick(view: View) {
                            logMediaOverflowStage("click dispatch:$optionName") {
                                "path=direct handler=${directClickMethod.declaringClass.name}.${directClickMethod.name} option=$optionName"
                            }
                            runCatching {
                                directClickMethod.invoke(resolvedOverflowHelper, option)
                                logMediaOverflowStage("click complete:$optionName") {
                                    "path=direct handler=${directClickMethod.declaringClass.name}.${directClickMethod.name} option=$optionName"
                                }
                            }.onFailure { throwable ->
                                logError("Old post/reel media overflow direct click failed option=$optionName", throwable)
                            }
                        }
                    }
                }
                val ctor = clickCtor ?: run {
                    renderFailures += "click_missing:$optionName"
                    return null
                }
                return runCatching { ctor.newInstance(39, mow, resolvedOverflowHelper) as? View.OnClickListener }
                    .map { original ->
                        if (original == null) {
                            null
                        } else {
                            View.OnClickListener { view ->
                                logMediaOverflowStage("click dispatch:$optionName") {
                                    "path=legacy handler=${original.javaClass.name} option=$optionName"
                                }
                                original.onClick(view)
                            }
                        }
                    }
                    .onFailure { renderFailures += "legacy_click_failed:$optionName:${it.javaClass.simpleName}" }
                    .getOrNull()
            }

            fun addIcon(mow: Any, label: String): Boolean {
                val optionName = oldPostReelMowOptionName(mow) ?: return false.also { renderFailures += "icon_option_missing:$label" }
                val listener = clickFor(mow) ?: return false
                val option = optionByName(optionName)
                val icon = iconDrawable(option)
                rememberCustomHeader(OldPostReelMenuAction(optionName, label, icon, listener, enabled = true))
                val headerMethod = headerActionMethod
                if (headerMethod != null) {
                    val callbackBase = headerMethod.parameterTypes[1]
                    val callback = createOldPostReelHeaderCallback(listener, callbackBase)
                        ?: return false.also {
                            if (!headerCallbackReportLogged) {
                                headerCallbackReportLogged = true
                                logMediaOverflowStage("header callback unresolved") {
                                    "base=${oldPostReelTypeSummary(callbackBase, 760)} " +
                                        "report=${oldPostReelHeaderCallbackReport(callbackBase)}"
                                }
                            }
                            renderFailures += "icon_callback_create_failed:$optionName:$label:${callbackBase.name}"
                        }
                    val actionKey = label.lowercase(Locale.US)
                        .replace(Regex("[^a-z0-9_]+"), "_")
                        .trim('_')
                        .ifBlank { optionName.lowercase(Locale.US) }
                    return runCatching {
                        headerMethod.invoke(cvv, context, callback, actionKey, label, label, 1.0f, icon, true)
                        headerClickFallbacks[oldPostReelNormalizeSheetLabel(label)] = listener
                        logMediaOverflowStage("icon added:$optionName") {
                            "label=$label actionKey=$actionKey icon=$icon callback=${callback.javaClass.name} fallbackLabels=${headerClickFallbacks.keys.joinToString("|")}"
                        }
                        true
                    }.onFailure { throwable ->
                        renderFailures += "icon_header_invoke_failed:$optionName:$label:${throwable.javaClass.simpleName}"
                    }.getOrDefault(false)
                }
                val action = createOldPostReelHeaderAction(context, label, icon, listener)
                    ?: return false.also { renderFailures += "icon_action_create_failed:$optionName:$label" }
                actionHeader.add(action)
                headerClickFallbacks[oldPostReelNormalizeSheetLabel(label)] = listener
                logMediaOverflowStage("icon added:$optionName") {
                    "label=$label icon=$icon path=legacy_action fallbackLabels=${headerClickFallbacks.keys.joinToString("|")}"
                }
                return true
            }

            fun invokeRow(
                listener: View.OnClickListener,
                label: String,
                icon: Int,
                destructive: Boolean,
                enabled: Boolean
            ) {
                when {
                    fullRowMethod != null -> fullRowMethod.invoke(cvv, context, listener, label, null, 1.0f, icon, 0, destructive, enabled, true)
                    compactRowMethod != null -> compactRowMethod.invoke(cvv, context, listener, label, icon, destructive)
                    simpleRowMethod != null -> simpleRowMethod.invoke(cvv, context, listener, label, icon)
                }
            }

            fun addRow(mow: Any): Boolean {
                val optionName = oldPostReelMowOptionName(mow) ?: return false.also { renderFailures += "row_option_missing:${mow.javaClass.name}" }
                val listener = clickFor(mow) ?: return false
                val option = optionByName(optionName)
                val label = oldPostReelMowText(mow) ?: oldPostReelLabelForOption(optionName)
                val destructive = optionName in setOf("REPORT", "DELETE", "DELETE_NOW") || optionName.contains("REMOVE")
                val icon = oldPostReelIconForMow(helperClass, mow, option) ?: iconDrawable(option)
                val enabled = oldPostReelMowEnabled(mow)
                rememberCustomRow(
                    OldPostReelMenuAction(
                        optionName = optionName,
                        label = label,
                        icon = icon,
                        listener = listener,
                        destructive = destructive,
                        enabled = true,
                        dividerBefore = customDividerBeforeNextRow
                    )
                )
                customDividerBeforeNextRow = false
                return runCatching {
                    invokeRow(listener, label, icon, destructive, enabled)
                    true
                }.onFailure { throwable ->
                    renderFailures += "row_invoke_failed:$optionName:${throwable.javaClass.simpleName}"
                }.getOrDefault(false)
            }

            fun isDownloadMow(mow: Any): Boolean {
                val optionName = oldPostReelMowOptionName(mow).orEmpty()
                val normalizedOption = optionName.lowercase(Locale.US)
                val label = oldPostReelNormalizeSheetLabel(oldPostReelMowText(mow).orEmpty())
                return optionName == "DOWNLOAD" ||
                    normalizedOption == "download" ||
                    normalizedOption == "upload" ||
                    optionName == "0LtM" ||
                    label == "download"
            }

            fun addExplicitReelDownloadRow(): Boolean {
                if (!mediaOverflowLooksReel || (!state.enableReelDownload && !state.enableReelThumbnailDownload)) return false
                if (!shouldOfferDownloadContextMenu()) {
                    logDownloadControlGate("reel_classic_row", "suppressed")
                    return false
                }
                val activity = findActivity(context) ?: currentActivity
                if (activity == null || activity.isFinishing || activity.isDestroyed) {
                    renderFailures += "reel_download_activity_missing"
                    return false
                }
                val offeredAtMs = SystemClock.elapsedRealtime()
                val listener = View.OnClickListener {
                    val ageMs = SystemClock.elapsedRealtime() - offeredAtMs
                    if (ageMs in 0L..650L) {
                        logMediaOverflowStage("download click suppressed") {
                            "reason=initial_more_tap_guard ageMs=$ageMs"
                        }
                        return@OnClickListener
                    }
                    handleReelDownloadClick(activity, media, helper)
                }
                rememberCustomRow(
                    OldPostReelMenuAction(
                        optionName = "DOWNLOAD",
                        label = "Download",
                        icon = resolveMediaOptionDownloadIcon(context),
                        listener = listener
                    )
                )
                return runCatching {
                    invokeRow(listener, "Download", resolveMediaOptionDownloadIcon(context), false, true)
                    logDownloadControlGate("reel_classic_row", "offered")
                    true
                }.onFailure { throwable ->
                    renderFailures += "reel_download_row_failed:${throwable.javaClass.simpleName}"
                    logError("Old post/reel explicit reel download row failed", throwable)
                }.getOrDefault(false)
            }

            val used = LinkedHashSet<Any>()
            fun findMow(vararg names: String): Any? =
                names.firstNotNullOfOrNull { wanted ->
                    mows.firstOrNull { mow -> mow !in used && oldPostReelMowOptionName(mow) == wanted }
                }?.also { used += it }

            val share = findMow("SHARE_LINK", "SHARE")
            val link = findMow("COPY_LINK", "COPY_FUNDRAISER_LINK")
            val save = findMow("SAVE", "UNSAVE")
            var iconCount = 0
            var rowCount = 0
            listOf(
                share to "Share",
                link to "Link",
                save to (save?.let(::oldPostReelMowText) ?: "Save")
            ).forEach { (mow, label) -> if (mow != null && addIcon(mow, label)) iconCount++ }

            val nativeDownloadMows = if (mediaOverflowLooksReel) {
                mows.filter { mow -> mow !in used && isDownloadMow(mow) }.also { downloadMows -> used.addAll(downloadMows) }
            } else {
                emptyList()
            }
            if (nativeDownloadMows.isNotEmpty()) {
                logMediaOverflowStage("native download suppressed") {
                    "reason=avoid_open_tap_auto_download options=${nativeDownloadMows.mapNotNull(::oldPostReelMowOptionName).joinToString("|")} " +
                        "labels=${nativeDownloadMows.mapNotNull(::oldPostReelMowText).joinToString("|")} explicitPurrfectRow=${state.enableReelDownload || state.enableReelThumbnailDownload}"
                }
            }
            if (addExplicitReelDownloadRow()) rowCount++

            listOf(
                arrayOf("WHY_AM_I_SEEING_THIS"),
                arrayOf("NOT_INTERESTED", "SEE_FEWER", "SEE_FEWER_CONNECTED"),
                arrayOf("INTERESTED", "SEE_MORE"),
                arrayOf("ABOUT_THIS_ACCOUNT"),
                arrayOf("REPORT")
            ).forEach { names -> findMow(*names)?.let { if (addRow(it)) rowCount++ } }
            val manageMow = findMow("MANAGE_SUGGESTED_CONTENT_CARRERA", "MANAGE_SUGGESTED_CONTENT", "SEE_YOUR_ALGORITHM")

            val suppressed = RESTORE_OLD_CONTEXT_MENU_SUPPRESSED_OPTION_NAMES + setOf(
                "META_AI_DEP_ASK",
                "CONTENT_DEEP_DIVE",
                "SHARE_LINK",
                "SHARE",
                "COPY_LINK",
                "COPY_FUNDRAISER_LINK",
                "SAVE",
                "UNSAVE",
                "DOWNLOAD",
                "QR_CODE",
                "MANAGE_SUGGESTED_CONTENT",
                "MANAGE_SUGGESTED_CONTENT_CARRERA",
                "SEE_YOUR_ALGORITHM"
            )
            val extraSuppressedOptions = mows.filter { mow ->
                mow !in used &&
                    !(mediaOverflowLooksReel && isDownloadMow(mow)) &&
                    oldPostReelMowOptionName(mow)?.let { it !in suppressed } == true
            }.mapNotNull(::oldPostReelMowOptionName)
            if (extraSuppressedOptions.isNotEmpty()) {
                logMediaOverflowStage("extra native rows suppressed") {
                    "reason=match_classic_target options=${extraSuppressedOptions.joinToString("|").take(240)}"
                }
            }

            val shouldAddManage = optionNames.any { it in setOf("WHY_AM_I_SEEING_THIS", "SEE_FEWER", "SEE_MORE", "NOT_INTERESTED", "INTERESTED") }
            var manageAdded = false
            if (manageMow != null) {
                addOldPostReelClassicSheetDivider(cvv, dividerClass)
                customDividerBeforeNextRow = customRowActions.isNotEmpty()
                if (addRow(manageMow)) {
                    rowCount++
                    manageAdded = true
                }
            } else if (shouldAddManage && manageClickCtor != null) {
                addOldPostReelClassicSheetDivider(cvv, dividerClass)
                val manageOption = optionByName("MANAGE_SUGGESTED_CONTENT_CARRERA") ?: optionByName("MANAGE_SUGGESTED_CONTENT")
                val manageListener = runCatching { manageClickCtor.newInstance(helper, 20) as? View.OnClickListener }.getOrNull()
                if (manageListener != null) {
                    val manageIcon = iconDrawable(manageOption)
                    rememberCustomRow(
                        OldPostReelMenuAction(
                            optionName = "MANAGE_SUGGESTED_CONTENT",
                            label = "Manage content preferences",
                            icon = manageIcon,
                            listener = manageListener,
                            dividerBefore = customRowActions.isNotEmpty()
                        )
                    )
                    if (runCatching {
                            invokeRow(manageListener, "Manage content preferences", manageIcon, false, true)
                            true
                        }.onFailure { throwable ->
                            renderFailures += "manage_row_invoke_failed:${throwable.javaClass.simpleName}"
                        }.getOrDefault(false)
                    ) {
                        manageAdded = true
                    }
                }
            }

            if (primaryList.isEmpty()) {
                if (showOldPostReelCustomContextMenu(context, customHeaderActions, customRowActions, "primary_empty:$key")) {
                    logInfo(
                        "Old post/reel media overflow custom fallback used reason=primary_empty " +
                            "headers=${customHeaderActions.size} rows=${customRowActions.size} manage=$manageAdded " +
                            "failures=${renderFailures.joinToString("|").take(700)}"
                    )
                    return@runCatching true
                }
                return@runCatching abort("rendered_primary_list_empty") {
                    "icons=$iconCount rows=$rowCount manage=$manageAdded failures=${renderFailures.joinToString("|").take(900)} " +
                        "rendered=${oldPostReelSheetModelSummary(cvv).take(700)}"
                }
            }
            if (iconCount < 3) {
                if (showOldPostReelCustomContextMenu(context, customHeaderActions, customRowActions, "icon_fallback:$key")) {
                    logInfo(
                        "Old post/reel media overflow custom fallback used reason=icon_rail_incomplete " +
                            "nativeIcons=$iconCount customHeaders=${customHeaderActions.size} rows=${customRowActions.size} " +
                            "manage=$manageAdded failures=${renderFailures.joinToString("|").take(700)}"
                    )
                    return@runCatching true
                }
                return@runCatching abort("rendered_icon_rail_incomplete") {
                    "icons=$iconCount rows=$rowCount manage=$manageAdded failures=${renderFailures.joinToString("|").take(900)} " +
                        "actionHeader=${oldPostReelHeaderLabels(context, oldPostReelActionSheetLists(cvv)).joinToString("|").take(500)} " +
                        "rendered=${oldPostReelSheetModelSummary(cvv).take(700)}"
                }
            }
            logMediaOverflowStage("render prepared") {
                "icons=$iconCount rows=$rowCount manage=$manageAdded failures=${renderFailures.joinToString("|").take(900)} " +
                    "summary=${oldPostReelSheetModelSummary(cvv).take(900)} " +
                    "primaryRows=${oldPostReelBottomSheetRowDetails(context, primaryList.toList()).take(900)}"
            }
            showSheet.invoke(null, media, null, cvv, null, helper)
            scheduleOldPostReelHeaderClickFallback(context, headerClickFallbacks)

            val now = SystemClock.elapsedRealtime()
            val previous = logTimes[key] ?: 0L
            if (now - previous >= 2_000L) {
                logTimes[key] = now
                if (logTimes.size > 30) logTimes.clear()
                logInfo(
                    "Old post/reel media overflow sheet restored method=$key " +
                        "clickPath=${directClickMethod?.let { "direct:${it.declaringClass.name}.${it.name}" } ?: "legacy:${clickClass?.name}"} " +
                        "icons=$iconCount rows=$rowCount manage=$manageAdded " +
                        "sourceOptions=${optionNames.joinToString("|").take(260)} " +
                        "rendered=${oldPostReelSheetModelSummary(cvv).take(320)}"
                )
            }
            true
        }.onFailure { logError("Failed rebuilding old post/reel media overflow sheet", it) }.getOrDefault(false)
    }

    private fun oldPostReelMediaOverflowMows(overflowHelper: Any, filterList: Collection<*>?): List<Any> {
        val exact = runCatching {
            val menuCreator = oldPostReelField(overflowHelper, "A0R") ?: return@runCatching emptyList()
            val lazyOptions = oldPostReelField(menuCreator, "A0C") ?: return@runCatching emptyList()
            val options = lazyOptions.javaClass.methods.firstOrNull { it.name == "getValue" && it.parameterTypes.isEmpty() }
                ?.invoke(lazyOptions) as? Collection<*>
            oldPostReelFilterMows(options.orEmpty().filterNotNull(), filterList)
        }.getOrDefault(emptyList())
        if (exact.isNotEmpty()) return exact
        return oldPostReelFilterMows(
            oldPostReelCollectMows(overflowHelper, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0),
            filterList
        )
    }

    private fun oldPostReelFilterMows(options: Collection<Any>, filterList: Collection<*>?): List<Any> {
        if (filterList.isNullOrEmpty()) return options.toList()
        val allowed = filterList.mapTo(LinkedHashSet()) { it?.toString() }
        return options.filter { mow -> oldPostReelMowOptionName(mow) in allowed }
    }

    private fun oldPostReelCollectMows(value: Any?, seen: MutableSet<Any>, depth: Int): List<Any> {
        if (value == null || depth > 5 || !seen.add(value)) return emptyList()
        val className = value.javaClass.name
        if (value is CharSequence || value is Number || value is Boolean || value.javaClass.isEnum) return emptyList()
        if (value is Collection<*>) {
            val direct = value.filterNotNull().filter { oldPostReelMowOptionName(it) != null }
            if (direct.isNotEmpty()) return direct
            return value.filterNotNull().flatMap { oldPostReelCollectMows(it, seen, depth + 1) }
        }
        if (
            value is Context ||
            value is View ||
            className.startsWith("android.") ||
            className.startsWith("androidx.") ||
            className.startsWith("java.") ||
            className.startsWith("kotlin.")
        ) {
            return emptyList()
        }
        if (oldPostReelMowOptionName(value) != null) return listOf(value)
        value.javaClass.methods.firstOrNull { it.name == "getValue" && it.parameterTypes.isEmpty() }?.let { method ->
            val lazyValue = runCatching {
                method.isAccessible = true
                method.invoke(value)
            }.getOrNull()
            val lazyMows = oldPostReelCollectMows(lazyValue, seen, depth + 1)
            if (lazyMows.isNotEmpty()) return lazyMows
        }
        return runCatching {
            val collected = mutableListOf<Any>()
            var cls: Class<*>? = value.javaClass
            while (cls != null && cls != Any::class.java) {
                cls.declaredFields
                    .asSequence()
                    .filterNot { Modifier.isStatic(it.modifiers) }
                    .filterNot { it.type.isPrimitive || it.type == String::class.java || Number::class.java.isAssignableFrom(it.type) }
                    .forEach { field ->
                        val fieldValue = runCatching {
                            field.isAccessible = true
                            field.get(value)
                        }.getOrNull()
                        if (fieldValue != null) collected.addAll(oldPostReelCollectMows(fieldValue, seen, depth + 1))
                    }
                cls = cls.superclass
            }
            collected.distinctBy { System.identityHashCode(it) }
        }.getOrDefault(emptyList())
    }

    private fun oldPostReelField(instance: Any, name: String): Any? =
        runCatching {
            var type: Class<*>? = instance.javaClass
            while (type != null) {
                val field = type.declaredFields.firstOrNull { it.name == name }
                if (field != null) {
                    field.isAccessible = true
                    return@runCatching field.get(instance)
                }
                type = type.superclass
            }
            null
        }.getOrNull()

    private fun oldPostReelSetField(instance: Any, name: String, value: Any?) {
        runCatching {
            var type: Class<*>? = instance.javaClass
            while (type != null) {
                val field = type.declaredFields.firstOrNull { it.name == name }
                if (field != null) {
                    field.isAccessible = true
                    field.set(instance, value)
                    return@runCatching
                }
                type = type.superclass
            }
        }
    }

    private fun oldPostReelMowOptionName(mow: Any): String? =
        oldPostReelMowOptionValue(mow)?.toString()

    private fun oldPostReelMowOptionValue(value: Any): Any? {
        if (oldPostReelIsMediaOptionClass(value.javaClass)) return value
        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.firstOrNull { field -> oldPostReelIsMediaOptionClass(field.type) }?.let { field ->
                return runCatching {
                    field.isAccessible = true
                    field.get(value)
                }.getOrNull()
            }
            cls = cls.superclass
        }
        return null
    }

    private fun oldPostReelIsMediaOptionClass(type: Class<*>): Boolean {
        if (type.name == "com.instagram.feed.media.mediaoption.MediaOption\$Option") return true
        if (!type.isEnum) return false
        return runCatching {
            type.enumConstants.orEmpty().any { constant ->
                val name = constant?.toString().orEmpty()
                name == "SAVE" || name == "SHARE_LINK" || name == "COPY_LINK" || name == "QR_CODE"
            }
        }.getOrDefault(false)
    }

    private fun oldPostReelMowText(mow: Any): String? =
        (oldPostReelField(mow, "A02") as? CharSequence)?.toString()

    private fun oldPostReelMowEnabled(mow: Any): Boolean =
        (oldPostReelField(mow, "A03") as? Boolean) ?: true

    private fun oldPostReelLabelForOption(optionName: String): String =
        optionName.lowercase().split('_').joinToString(" ") { part ->
            part.replaceFirstChar { ch -> ch.titlecase() }
        }

    private fun oldPostReelIconForMow(helperClass: Class<*>, mow: Any, option: Any?): Int? =
        runCatching {
            helperClass.declaredMethods.firstOrNull { candidate ->
                Modifier.isStatic(candidate.modifiers) &&
                    candidate.returnType == java.lang.Integer.TYPE &&
                    candidate.parameterTypes.size == 1 &&
                    candidate.parameterTypes[0].isAssignableFrom(mow.javaClass)
            }?.apply { isAccessible = true }?.invoke(null, mow) as? Int
        }.getOrNull() ?: runCatching {
            option?.javaClass?.getMethod("getIconDrawable")?.invoke(option) as? Int
        }.getOrNull()

    private fun installLocalInstagramPlusBenefitHook() {
        val cacheKey = "LocalInstagramPlusActiveBenefit_v2"
        val cached = if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods(cacheKey, appClassLoader).orEmpty()
                .filter(::isLocalInstagramPlusBenefitMethod)
        } else {
            emptyList()
        }

        if (cached.isNotEmpty()) {
            val hooked = hookLocalInstagramPlusBenefitMethods(cached, "cached")
            if (hooked > 0) {
                logInfo("Installed Local Instagram Plus benefit hook(s)=$hooked source=cached candidates=${cached.size}")
                return
            }
            logInfo("Local Instagram Plus cached candidates did not hook; retrying DexKit discovery")
        }

        val discovered = discoverLocalInstagramPlusBenefitMethods()
        if (discovered.isNotEmpty()) InstagramDexKitCache.saveMethods(cacheKey, discovered)
        val hooked = hookLocalInstagramPlusBenefitMethods(discovered, "dex")
        if (hooked > 0) {
            logInfo("Installed Local Instagram Plus benefit hook(s)=$hooked source=dex candidates=${discovered.size}")
        } else {
            logInfo("Local Instagram Plus benefit checker not found; requesting DexKit cache refresh")
            InstagramDexKitCache.requestBackgroundScan(androidContext, "local Instagram Plus benefit checker missing")
        }
    }

    private fun installLocalInstagramPlusAppIconCardHook() {
        val cacheKey = "LocalInstagramPlusAppIconCardRender_v1"
        val cached = if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods(cacheKey, appClassLoader).orEmpty()
                .filter(::isLocalInstagramPlusAppIconCardRenderMethod)
        } else {
            emptyList()
        }

        if (cached.isNotEmpty()) {
            val hooked = hookLocalInstagramPlusAppIconCardRenderMethods(cached, "cached")
            if (hooked > 0) {
                logInfo("Installed Local Instagram Plus app icon card hook(s)=$hooked source=cached candidates=${cached.size}")
                return
            }
            logInfo("Local Instagram Plus cached app icon card candidates did not hook; retrying DexKit discovery")
        }

        val discovered = discoverLocalInstagramPlusAppIconCardRenderMethods()
        if (discovered.isNotEmpty()) InstagramDexKitCache.saveMethods(cacheKey, discovered)
        val hooked = hookLocalInstagramPlusAppIconCardRenderMethods(discovered, "dex")
        if (hooked > 0) {
            logInfo("Installed Local Instagram Plus app icon card hook(s)=$hooked source=dex candidates=${discovered.size}")
        } else {
            logInfo("Local Instagram Plus app icon card renderer not found")
        }
    }

    private fun discoverLocalInstagramPlusAppIconCardRenderMethods(): List<Method> {
        val candidates = LinkedHashSet<Method>()
        listOf("X.0Uvy", "p000X.C0Uvy", "X.AbstractC774890Uvy").forEach { className ->
            runCatching {
                val clazz = Class.forName(className, false, appClassLoader)
                candidates += clazz.declaredMethods.filter(::isLocalInstagramPlusAppIconCardRenderMethod)
            }
        }
        dexBridge.findMethodsUsingStrings(
            "com.instagram.aura.appicon.ui.AuraAppIconCell (AuraAppIconPickerContent.kt:184)"
        )
            .filter(::isLocalInstagramPlusAppIconCardRenderMethod)
            .forEach { method -> candidates += method }

        val filtered = candidates.distinctBy(::methodKey)
        if (filtered.isNotEmpty()) {
            logInfo(
                "Local Instagram Plus app icon card discovery candidates=${filtered.size} " +
                    filtered.take(6).joinToString { method ->
                        "${method.declaringClass.name}.${method.name}(${method.parameterTypes.joinToString { it.simpleName }})"
                    }
            )
        }
        return filtered
    }

    private fun isLocalInstagramPlusAppIconCardRenderMethod(method: Method): Boolean {
        return Modifier.isStatic(method.modifiers) &&
            method.returnType == java.lang.Void.TYPE &&
            method.parameterTypes.any { type -> localInstagramPlusAppIconStatusField(type) != null }
    }

    private fun hookLocalInstagramPlusAppIconCardRenderMethods(methods: List<Method>, source: String): Int {
        if (methods.isEmpty()) return 0
        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:local_instagram_plus_app_icon_card_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.localInstagramPlus) return
                            val args = param.args.orEmpty()
                            val beforeStatus = args.firstNotNullOfOrNull(::localInstagramPlusAppIconItemStatusName)
                            val changed = args.sumOf { arg -> normalizeLocalInstagramPlusAppIconItems(arg) }
                            val afterStatus = args.firstNotNullOfOrNull(::localInstagramPlusAppIconItemStatusName)
                            if (beforeStatus != null || afterStatus != null) {
                                logLocalInstagramPlusAppIconState(
                                    method,
                                    "render-card status=${beforeStatus ?: "unknown"}->${afterStatus ?: "unknown"} changed=$changed"
                                )
                            }
                            if (changed > 0) {
                                logLocalInstagramPlusAppIconState(method, "normalized-card-statuses=$changed render")
                            }
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed Local Instagram Plus app icon card hook $signature", it) }
        }
        return hooked
    }

    private fun installLocalInstagramPlusAppIconControllerHook() {
        val candidates = discoverLocalInstagramPlusAppIconControllerMethods()
        val hooked = hookLocalInstagramPlusAppIconControllerMethods(candidates, "direct")
        if (hooked > 0) {
            logInfo("Installed Local Instagram Plus app icon controller hook(s)=$hooked source=direct candidates=${candidates.size}")
        } else {
            logInfo("Local Instagram Plus app icon controller not found")
        }
    }

    private fun discoverLocalInstagramPlusAppIconControllerMethods(): List<Method> {
        val candidates = LinkedHashSet<Method>()
        listOf("X.0EMX", "p000X.C0EMX", "X.C0EMX").forEach { className ->
            runCatching {
                val clazz = Class.forName(className, false, appClassLoader)
                candidates += clazz.declaredMethods.filter(::isLocalInstagramPlusAppIconControllerMethod)
            }
        }
        val filtered = candidates.distinctBy(::methodKey)
        if (filtered.isNotEmpty()) {
            logInfo(
                "Local Instagram Plus app icon controller discovery candidates=${filtered.size} " +
