    private fun localInstagramPlusAppIconArg(args: Array<Any?>?): Any? {
        return args?.firstOrNull { value ->
            !localInstagramPlusAppIconComponentName(value).isNullOrBlank()
        }
    }

    private fun normalizeLocalInstagramPlusAppIconState(value: Any?): Int {
        value ?: return 0
        var changed = 0
        runCatching {
            value.javaClass.declaredFields
                .filter { field -> !Modifier.isStatic(field.modifiers) }
                .forEach { field ->
                    field.isAccessible = true
                    changed += normalizeLocalInstagramPlusAppIconItems(field.get(value))
                    if (field.type == java.lang.Integer::class.java) {
                        val current = field.get(value) as? Number
                        if (current != null && current.toInt() != 0) {
                            field.set(value, java.lang.Integer.valueOf(0))
                            changed++
                        }
                    }
                }
        }.onFailure { logError("Local Instagram Plus app icon state normalize failed", it) }
        return changed
    }

    private fun applyLocalInstagramPlusLauncherIcon(context: Context, targetIcon: Any) {
        val targetComponent = localInstagramPlusAppIconComponentName(targetIcon)
        val targetName = localInstagramPlusAppIconDisplayName(targetIcon)
        if (targetComponent.isNullOrBlank()) {
            logInfo("Local Instagram Plus app icon switch skipped; missing target component for ${targetIcon.javaClass.name}")
            return
        }

        runCatching {
            val appContext = context.applicationContext ?: context
            val packageName = appContext.packageName
            val packageManager = appContext.packageManager
            val icons = localInstagramPlusAppIconValues(targetIcon.javaClass)
            if (icons.isEmpty()) {
                logInfo("Local Instagram Plus app icon switch skipped; no icon values for ${targetIcon.javaClass.name}")
                return
            }

            var enabled = 0
            var disabled = 0
            icons.forEach { icon ->
                val component = localInstagramPlusAppIconComponentName(icon) ?: return@forEach
                val mode = if (component == targetComponent) {
                    android.content.pm.PackageManager.COMPONENT_ENABLED_STATE_ENABLED
                } else {
                    android.content.pm.PackageManager.COMPONENT_ENABLED_STATE_DISABLED
                }
                val componentName = ComponentName(packageName, component)
                if (packageManager.getComponentEnabledSetting(componentName) != mode) {
                    packageManager.setComponentEnabledSetting(
                        componentName,
                        mode,
                        android.content.pm.PackageManager.DONT_KILL_APP
                    )
                    if (mode == android.content.pm.PackageManager.COMPONENT_ENABLED_STATE_ENABLED) enabled++ else disabled++
                }
            }

            setLocalInstagramPlusCurrentAppIcon(targetIcon, icons.firstOrNull {
                localInstagramPlusAppIconComponentName(it) == targetComponent
            } ?: targetIcon)

            logInfo(
                "Local Instagram Plus app icon switch applied target=${targetName ?: targetComponent} " +
                    "component=$targetComponent enabled=$enabled disabled=$disabled values=${icons.size}"
            )
        }.onFailure { error ->
            logError("Local Instagram Plus app icon switch apply failed target=${targetName ?: targetComponent}", error)
        }
    }

    private fun localInstagramPlusAppIconValues(type: Class<*>): List<Any> {
        return runCatching {
            val values = type.methods.firstOrNull { method ->
                Modifier.isStatic(method.modifiers) &&
                    method.name == "values" &&
                    method.parameterTypes.isEmpty() &&
                    method.returnType.isArray
            }?.invoke(null)
            (values as? Array<*>)?.filterNotNull().orEmpty()
        }.getOrDefault(emptyList())
    }

    private fun setLocalInstagramPlusCurrentAppIcon(targetIcon: Any, currentIcon: Any) {
        runCatching {
            targetIcon.javaClass.declaredFields
                .firstOrNull { field ->
                    Modifier.isStatic(field.modifiers) &&
                        field.type == targetIcon.javaClass &&
                        field.name == "A02"
                }
                ?.apply { isAccessible = true }
                ?.set(null, currentIcon)
        }
    }

    private fun localInstagramPlusAppIconIdentity(icon: Any?): String {
        icon ?: return "<null>"
        val name = localInstagramPlusAppIconDisplayName(icon) ?: icon.javaClass.name
        val component = localInstagramPlusAppIconComponentName(icon) ?: "component=?"
        return "$name/$component"
    }

