                .mapNotNull { field ->
                    field.isAccessible = true
                    (field.get(icon) as? String)?.trim()
                }
                .firstOrNull { value ->
                    value.isNotBlank() && !value.contains('.') && !value.contains('/')
                }
        }.getOrNull()
    }

    private fun localInstagramPlusAppIconComponentName(icon: Any?): String? {
        icon ?: return null
        return runCatching {
            icon.javaClass.declaredFields
