    private fun normalizeLocalInstagramPlusAppIconItem(item: Any?): Int {
        item ?: return 0
        val statusField = localInstagramPlusAppIconStatusField(item.javaClass) ?: return 0
        val current = runCatching {
            statusField.isAccessible = true
            statusField.get(item)
        }.getOrNull() ?: return 0
        val statusName = localInstagramPlusAppIconStatusName(current) ?: return 0
        if (statusName != "IG_PLUS_LOCKED" && statusName != "CANNES") return 0
        val available = localInstagramPlusAvailableAppIconStatus(current.javaClass) ?: return 0
        return runCatching {
            statusField.set(item, available)
            1
        }.onFailure { logError("Local Instagram Plus app icon card status write failed", it) }
            .getOrDefault(0)
    }

