        if (isLocalInstagramPlusAppIconStateShape(controller)) {
            changed += normalizeLocalInstagramPlusAppIconState(controller)
        }
        runCatching {
            controller.javaClass.declaredFields
                .filter { field -> !Modifier.isStatic(field.modifiers) }
