                        changed += normalizeLocalInstagramPlusAppIconState(value)
                    }
                    val holderValue = localInstagramPlusAppIconStateHolderValue(value)
                    changed += normalizeLocalInstagramPlusAppIconItems(holderValue)
                    if (isLocalInstagramPlusAppIconStateShape(holderValue)) {
                        changed += normalizeLocalInstagramPlusAppIconState(holderValue)
                    }
