        }
        return runCatching {
            controller.javaClass.declaredFields
                .asSequence()
                .filter { field -> !Modifier.isStatic(field.modifiers) }
                .mapNotNull { field ->
                    field.isAccessible = true
                    val value = field.get(controller)
                    localInstagramPlusAppIconStateSummary(value)
