    private fun localInstagramPlusAppIconStateSummary(value: Any?): String? {
        value ?: return null
        if (!isLocalInstagramPlusAppIconStateShape(value)) return null
        val modes = ArrayList<String>()
        var itemsSummary: String? = null
        runCatching {
            value.javaClass.declaredFields
                .filter { field -> !Modifier.isStatic(field.modifiers) }
                .forEach { field ->
                    field.isAccessible = true
                    val fieldValue = field.get(value)
                    if (field.type == java.lang.Integer::class.java) {
                        (fieldValue as? Number)?.toInt()?.let { modes += "${field.name}=$it" }
                    }
                    if (itemsSummary == null) {
                        itemsSummary = localInstagramPlusAppIconItemsSummary(fieldValue)
                    }
                }
        }
        return "state modes=[${modes.joinToString()}] ${itemsSummary ?: "items=none"}"
    }

    private fun localInstagramPlusAppIconItemsSummary(value: Any?): String? {
        val iterable = value as? Iterable<*> ?: return null
        val counts = LinkedHashMap<String, Int>()
        var total = 0
        iterable.forEach { item ->
            val status = localInstagramPlusAppIconItemStatusName(item) ?: return@forEach
            counts[status] = (counts[status] ?: 0) + 1
            total++
        }
        if (total == 0) return null
        return "items=$total ${counts.entries.joinToString(prefix = "{", postfix = "}") { "${it.key}=${it.value}" }}"
    }

    private fun isLocalInstagramPlusAppIconStateShape(value: Any?): Boolean {
        value ?: return false
        val fields = value.javaClass.declaredFields.filter { field -> !Modifier.isStatic(field.modifiers) }
        if (fields.count { field -> field.type == java.lang.Integer::class.java } == 0) return false
        return fields.any { field ->
            Iterable::class.java.isAssignableFrom(field.type) ||
                Collection::class.java.isAssignableFrom(field.type) ||
                List::class.java.isAssignableFrom(field.type)
        }
    }

