    private fun localInstagramPlusAvailableAppIconStatus(type: Class<*>): Any? {
        return runCatching {
            type.declaredFields
                .filter { field -> Modifier.isStatic(field.modifiers) && field.type == type }
                .firstNotNullOfOrNull { field ->
                    field.isAccessible = true
                    field.get(null)?.takeIf { value -> localInstagramPlusAppIconStatusName(value) == "IG_PLUS_AVAILABLE" }
                }
