    private fun localInstagramPlusAppIconStatusName(value: Any?): String? {
        value ?: return null
        val direct = runCatching {
            value.javaClass.declaredFields
                .filter { field -> !Modifier.isStatic(field.modifiers) && field.type == String::class.java }
                .firstNotNullOfOrNull { field ->
                    field.isAccessible = true
                    (field.get(value) as? String)?.trim()
                }
        }.getOrNull()
        return direct?.takeIf { name ->
            name == "IG_PLUS_AVAILABLE" || name == "IG_PLUS_LOCKED" || name == "CANNES" || name == "DEFAULT"
        }
    }

    private fun logLocalInstagramPlusAppIconState(method: Method, detail: String) {
        val key = detail
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusAppIconLogTimes[key] ?: 0L
        if (now - previous < 5_000L) return
        localPlusAppIconLogTimes[key] = now
        if (localPlusAppIconLogTimes.size > 80) localPlusAppIconLogTimes.clear()
        logInfo("Local Instagram Plus app icon state $detail method=${method.declaringClass.name}.${method.name}")
    }

