                candidates += clazz.declaredMethods.filter(::isLocalInstagramPlusBenefitEnumMethod)
            }
        }

        val enumTypes = localInstagramPlusBenefitEnumTypes()
        val refs = (
            dexBridge.findMethodRefsUsingStrings("consumer_subs_custom_app_icon_picker") +
                dexBridge.findMethodRefsUsingStrings("AURA_IG_CONTEXTUAL_CUSTOM_APP_ICON_UPSELL_DIALOG") +
