            )
        refs.flatMap { ref -> ref.invokes }
            .mapNotNull { ref -> ref.method }
            .filter { method -> isLocalInstagramPlusBenefitEnumMethod(method, enumTypes) }
            .forEach { method -> candidates += method }

        val filtered = candidates
            .filter(::isLocalInstagramPlusBenefitEnumMethod)
            .distinctBy(::methodKey)
        if (filtered.isNotEmpty()) {
            logInfo(
                "Local Instagram Plus enum benefit discovery candidates=${filtered.size} " +
                    filtered.take(8).joinToString { method ->
                        "${method.declaringClass.name}.${method.name}(${method.parameterTypes.joinToString { it.simpleName }})"
                    }
            )
        }
        return filtered
    }

    private fun localInstagramPlusBenefitEnumTypes(): Set<Class<*>> {
        return dexBridge.findMethodsUsingStrings("CUSTOM_APP_ICON", "DIRECT_MESSAGE_PEEK")
            .map { method -> method.declaringClass }
            .filter(::isLocalInstagramPlusBenefitEnumType)
            .toSet()
    }

    private fun isLocalInstagramPlusBenefitEnumType(type: Class<*>): Boolean {
        if (type.isPrimitive || type == String::class.java || CharSequence::class.java.isAssignableFrom(type)) return false
        val fields = type.declaredFields
        return fields.any { field -> field.type == String::class.java } &&
            fields.count { field -> Modifier.isStatic(field.modifiers) && field.type == type } >= 2
    }

    private fun isLocalInstagramPlusBenefitEnumMethod(method: Method): Boolean {
        return isLocalInstagramPlusBenefitEnumMethod(method, emptySet())
    }

    private fun isLocalInstagramPlusBenefitEnumMethod(method: Method, enumTypes: Set<Class<*>>): Boolean {
        if (!Modifier.isStatic(method.modifiers)) return false
        if (method.returnType != java.lang.Boolean.TYPE && method.returnType != java.lang.Boolean::class.java) return false
        val params = method.parameterTypes
        if (params.size != 2) return false
        return params.any { type ->
            enumTypes.contains(type) ||
                isLocalInstagramPlusBenefitEnumType(type)
        }
    }

    private fun hookLocalInstagramPlusBenefitEnumMethods(methods: List<Method>, source: String): Int {
        if (methods.isEmpty()) return 0
        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:local_instagram_plus_enum_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.localInstagramPlus) return
                            val benefit = param.args
                                ?.asSequence()
                                ?.mapNotNull(::localInstagramPlusBenefitName)
                                ?.firstOrNull()
                            if (benefit.isNullOrBlank()) {
                                logLocalInstagramPlusBenefitDecision("enum:${method.parameterTypes.joinToString { it.simpleName }}", "skipped-unrecognized-enum", method)
                                return
                            }
                            if (shouldSkipLocalInstagramPlusBenefit(benefit)) {
                                logLocalInstagramPlusBenefitDecision(benefit, "skipped-guarded-enum", method)
                                return
                            }
                            param.result = true
                            logLocalInstagramPlusBenefitDecision(benefit, "enabled-enum", method)
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed Local Instagram Plus enum benefit hook $signature", it) }
        }
        return hooked
    }

    private fun discoverLocalInstagramPlusBenefitMethods(): List<Method> {
        val candidates = LinkedHashSet<Method>()
        val markerSets = listOf(
            listOf("isBenefitActive: Is benefit ", " active: "),
            listOf("CUSTOM_APP_ICON"),
            listOf("DIRECT_MESSAGE_PEEK"),
            listOf("CUSTOM_PROFILE_BIO_FONT"),
            listOf("STORY_VIEWER_LIST"),
            listOf("message_peek_thread_preview"),
            listOf("aura_app_icon_picker")
        )

        markerSets.forEach { markers ->
            candidates += dexBridge.findMethodsUsingStringsConstrained(
                markers,
                paramCount = 1,
                returnType = "boolean"
            )
        }

        if (candidates.isEmpty()) {
            listOf(
                "isBenefitActive",
                "CUSTOM_APP_ICON",
                "DIRECT_MESSAGE_PEEK",
                "CUSTOM_PROFILE_BIO_FONT",
                "STORY_VIEWER_LIST"
            ).forEach { marker ->
                candidates += dexBridge.findMethodsUsingStrings(marker)
            }
        }
        val filtered = candidates
            .filter(::isLocalInstagramPlusBenefitMethod)
            .distinctBy(::methodKey)
        if (filtered.isNotEmpty()) {
            logInfo(
                "Local Instagram Plus benefit discovery candidates=${filtered.size} " +
                    filtered.take(8).joinToString { method ->
                        "${method.declaringClass.name}.${method.name}(${method.parameterTypes.joinToString { it.simpleName }})"
                    }
            )
        }
        return filtered
    }

    private fun isLocalInstagramPlusBenefitMethod(method: Method): Boolean {
        if (method.returnType != java.lang.Boolean.TYPE && method.returnType != java.lang.Boolean::class.java) return false
        val params = method.parameterTypes
        if (params.size != 1) return false
        val type = params[0]
        return type == String::class.java ||
            CharSequence::class.java.isAssignableFrom(type) ||
            type.isEnum ||
            (!type.isPrimitive &&
                type != java.lang.Boolean::class.java &&
                !Number::class.java.isAssignableFrom(type))
    }

    private fun hookLocalInstagramPlusBenefitMethods(methods: List<Method>, source: String): Int {
        if (methods.isEmpty()) return 0
        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:local_instagram_plus_$source"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.localInstagramPlus) return
                            val benefitArg = param.args?.firstOrNull()
                            val benefit = localInstagramPlusBenefitName(benefitArg)
                            if (benefit.isNullOrBlank()) {
                                val argType = benefitArg?.javaClass?.name ?: "<null>"
                                logLocalInstagramPlusBenefitDecision(argType, "skipped-unrecognized-arg", method)
                                return
                            }
                            if (shouldSkipLocalInstagramPlusBenefit(benefit)) {
                                logLocalInstagramPlusBenefitDecision(benefit, "skipped-guarded", method)
                                return
                            }
                            param.result = true
                            logLocalInstagramPlusBenefitDecision(benefit, "enabled", method)
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed Local Instagram Plus benefit hook $signature", it) }
        }
        return hooked
    }

    private fun localInstagramPlusBenefitName(value: Any?): String? {
        value ?: return null
        when (value) {
            is String -> return value.trim().takeIf(::looksLikeLocalInstagramPlusBenefitName)
            is CharSequence -> return value.toString().trim().takeIf(::looksLikeLocalInstagramPlusBenefitName)
            is Enum<*> -> return value.name.takeIf(::looksLikeLocalInstagramPlusBenefitName)
        }

        listOf("name", "getName", "getId", "getType", "getBenefitType").forEach { methodName ->
            val direct = runCatching {
                val method = value.javaClass.methods.firstOrNull { candidate ->
                    candidate.name == methodName &&
                        candidate.parameterTypes.isEmpty() &&
                        String::class.java.isAssignableFrom(candidate.returnType)
                } ?: return@runCatching null
                method.isAccessible = true
                (method.invoke(value) as? String)?.trim()
            }.getOrNull()
            if (!direct.isNullOrBlank() && looksLikeLocalInstagramPlusBenefitName(direct)) return direct
        }

        runCatching {
            value.javaClass.declaredFields
                .filter { field -> !Modifier.isStatic(field.modifiers) && field.type == String::class.java }
                .take(12)
                .forEach { field ->
                    field.isAccessible = true
                    val candidate = (field.get(value) as? String)?.trim()
                    if (!candidate.isNullOrBlank() && looksLikeLocalInstagramPlusBenefitName(candidate)) return candidate
                }
        }

        val rendered = runCatching { value.toString().trim() }.getOrNull().orEmpty()
        if (rendered.isNotEmpty() &&
            !rendered.contains('@') &&
            looksLikeLocalInstagramPlusBenefitName(rendered)
        ) {
            return rendered
        }
        return null
    }

    private fun looksLikeLocalInstagramPlusBenefitName(value: String): Boolean {
        val lower = value.lowercase(Locale.US)
        return lower.contains("benefit") ||
            lower.contains("aura") ||
            lower.contains("ig_plus") ||
            lower.contains("instagram_plus") ||
            lower.contains("message_peek") ||
            lower.contains("direct_message_peek") ||
            lower.contains("custom_app_icon") ||
            lower.contains("app_icon") ||
            lower.contains("bio_font") ||
            lower.contains("story_viewer") ||
            lower.contains("custom_profile_bio_font")
    }

    private fun shouldSkipLocalInstagramPlusBenefit(benefit: String): Boolean {
        val lower = benefit.lowercase(Locale.US)
        return lower.contains("disappear") ||
            lower.contains("vanish") ||
            lower.contains("ephemeral") ||
            lower.contains("e2ee") ||
            lower.contains("encrypt") ||
            lower.contains("armadillo")
    }

    private fun logLocalInstagramPlusBenefitDecision(benefit: String, decision: String, method: Method) {
        val safeBenefit = benefit.replace('\n', ' ').replace('\r', ' ').take(160)
        val key = "$decision:${safeBenefit.take(96)}"
        val now = SystemClock.elapsedRealtime()
        val previous = localPlusBenefitLogTimes[key] ?: 0L
        if (now - previous < 10_000L) return
        localPlusBenefitLogTimes[key] = now
        if (localPlusBenefitLogTimes.size > 160) localPlusBenefitLogTimes.clear()
        logInfo(
            "Local Instagram Plus benefit $decision benefit=$safeBenefit " +
                "method=${method.declaringClass.name}.${method.name}"
        )
    }

    private fun installDmFileAttachmentBridgeHooks() {
        hookUserSessionCapture()
        hookDirectFileServiceConstructors("X.04tv", isBroadcaster = true)
        hookDirectFileServiceConstructors("X.04tm", isBroadcaster = false)
        hookDirectFileServiceProvider("X.04tx", isBroadcaster = true)
        hookDirectFileServiceProvider("p000X.C04tx", isBroadcaster = true)
        hookDirectFileServiceProvider("X.04tn", isBroadcaster = false)
        hookDirectFileServiceProvider("p000X.C04tn", isBroadcaster = false)
        runCatching {
            val cls = Class.forName("com.instagram.pendingmedia.service.upload.UploadFileStep", false, appClassLoader)
            XposedBridge.hookAllMethods(
                cls,
                "H1d",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val pending = getField(param.args.firstOrNull(), "A07") ?: return
                        val key = getField(pending, "A4m") as? String ?: return
                        val upload = pendingDirectFileUploads[key] ?: return
                        val attachment = getField(pending, "A3M")?.toString()?.takeIf { it != "null" } ?: return
                        if (!upload.broadcastStarted.compareAndSet(false, true)) return
                        mainHandler.post {
                            broadcastDirectFileAttachment(upload, attachment)
                        }
                    }
                }
            )
            logInfo("Installed DM file upload completion bridge")
        }.onFailure { logError("DM file upload completion bridge failed", it) }
    }

    private fun hookUserSessionCapture() {
        runCatching {
            val cls = Class.forName("com.instagram.common.session.UserSession", false, appClassLoader)
            XposedBridge.hookAllConstructors(
                cls,
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        lastInstagramUserSession = param.thisObject
                    }
                }
            )
            logInfo("Installed DM file UserSession capture")
        }.onFailure { logError("DM file UserSession capture failed", it) }
    }

    private fun hookDirectFileServiceConstructors(className: String, isBroadcaster: Boolean) {
        runCatching {
            val cls = Class.forName(className, false, appClassLoader)
            XposedBridge.hookAllConstructors(
                cls,
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val service = param.thisObject ?: return
                        findUserSession(service)?.let { lastInstagramUserSession = it }
                        if (isBroadcaster) {
                            lastDirectFileBroadcaster = service
                        } else {
                            lastDirectMediaCoordinator = service
                        }
                    }
                }
            )
            logInfo("Installed DM file ${if (isBroadcaster) "broadcast" else "upload"} constructor bridge on $className")
        }.onFailure { logError("DM file constructor bridge failed for $className", it) }
    }

    private fun hookDirectFileServiceProvider(className: String, isBroadcaster: Boolean) {
        runCatching {
            val cls = Class.forName(className, false, appClassLoader)
            XposedBridge.hookAllMethods(
                cls,
                "B00",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        param.args.firstOrNull()?.takeIf { it.javaClass.name == "com.instagram.common.session.UserSession" }?.let {
                            lastInstagramUserSession = it
                        }
                        val service = param.result ?: return
                        if (isBroadcaster) {
                            lastDirectFileBroadcaster = service
                        } else {
                            lastDirectMediaCoordinator = service
                        }
                    }
                }
            )
            logInfo("Installed DM file ${if (isBroadcaster) "broadcast" else "upload"} provider bridge on $className")
        }.onFailure { logError("DM file provider bridge failed for $className", it) }
    }

    private fun installBottomSheetNavigatorHook() {
        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethod("BottomSheet", appClassLoader)?.let { cached ->
                val signature = "${methodKey(cached)}:BottomSheet_cached"
                if (hookedDexMethods.add(signature)) {
                    XposedBridge.hookMethod(cached, object : XC_MethodHook() {})
                    logInfo("DexKit cached hook installed: BottomSheet -> $signature")
                    return
                }
            }
        }
        val method = dexBridge.findMethodsUsingStrings("BottomSheetConstants")
            .firstOrNull { candidate ->
                candidate.declaringClass.name == "com.instagram.mainactivity.InstagramMainActivity" &&
                    !Modifier.isStatic(candidate.modifiers) &&
                    Modifier.isFinal(candidate.modifiers) &&
                    candidate.returnType != Void.TYPE &&
                    candidate.parameterTypes.isEmpty()
            } ?: return
        val signature = "${methodKey(method)}:BottomSheet"
        if (!hookedDexMethods.add(signature)) return
        runCatching {
            method.isAccessible = true
            XposedBridge.hookMethod(method, object : XC_MethodHook() {})
            InstagramDexKitCache.saveMethod("BottomSheet", method)
            logInfo("DexKit hook installed: BottomSheet -> $signature")
        }.onFailure { logError("Failed DexKit hook BottomSheet $signature", it) }
    }

    private fun installPostVideoUrlCaptureHook() {
        initStoryVideoVersionReflection()
        val videoVersionClass = storyVideoVersionIntfClass ?: return
        val hook = object : XC_MethodHook() {
            override fun afterHookedMethod(param: MethodHookParam<*>) {
                if (!state.enablePostDownload) return
                val url = param.result as? String ?: return
                if (!shouldRememberGenericMediaUrlNow()) return
                if (looksLikeMediaUrl(url) && !looksLikeProfileImageUrl(url)) rememberMediaUrl(url)
            }
        }
        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods("VideoUrlCapture", appClassLoader)
                ?.takeIf { it.isNotEmpty() }
                ?.let { cached ->
                    cached.forEach { method ->
                        val signature = "${methodKey(method)}:VideoUrlCapture_cached"
                        if (hookedDexMethods.add(signature)) XposedBridge.hookMethod(method, hook)
                    }
                    logInfo("DexKit cached hook installed: VideoUrlCapture methods=${cached.size}")
                    resolveUsernameGetter()
                    return
                }
        }
        val hooked = ArrayList<Method>()
        dexBridge.findMethodsByName("getUrl", paramCount = 0)
            .filter { method ->
                method.returnType == String::class.java &&
                    videoVersionClass.isAssignableFrom(method.declaringClass)
            }
            .forEach { method ->
                val signature = "${methodKey(method)}:VideoUrlCapture"
                if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                    XposedBridge.hookMethod(method, hook)
                    hooked += method
                    logInfo("DexKit hook installed: VideoUrlCapture -> $signature")
                }.onFailure { logError("Failed DexKit hook VideoUrlCapture $signature", it) }
            }
        if (hooked.isNotEmpty()) InstagramDexKitCache.saveMethods("VideoUrlCapture", hooked)
        resolveUsernameGetter()
    }

    private fun installVideoAutoPlayDexHook() {
        val hook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (!state.disableVideoAutoPlay) return
                when {
                    isReelsAutoplaySurfaceActive() -> param.result = false
                    isFeedAutoplaySurfaceActive() -> param.result = true
                }
