            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(method, hook)
                InstagramDexKitCache.saveMethod("AutoPlayDisable", method)
                logInfo("DexKit hook installed: VideoAutoPlay -> $signature")
            }.onFailure { logError("Failed DexKit hook VideoAutoPlay $signature", it) }
        }
    }

    private fun rememberManualInstagramSoundMute(view: View?) {
        if (!looksLikeInstagramMuteControl(view)) return
        markManualInstagramSoundMute("view-click view=${describeViewBrief(view)}")
    }

    private fun rememberInstagramSoundTouchDown(event: MotionEvent) {
        if (!state.feedVideosStartWithSound && !state.storiesStartWithSound) return
        lastInstagramSoundTouchDownTime = event.downTime
        lastInstagramSoundTouchDownX = event.rawX
        lastInstagramSoundTouchDownY = event.rawY
    }

    private fun shouldForceInstagramSound(): Boolean {
        if (!state.feedVideosStartWithSound && !state.storiesStartWithSound) return false
        if (shouldDeferStartWithSoundForInputBusy()) return false
        if (!userMutedInstagramSoundUntilRestart) return true
        logInfoThrottled("sound:manual-muted-skip", 6_000L) {
            "Start-with-sound skipped because manual Instagram mute is active until restart"
        }
        return false
    }

    private fun shouldDeferStartWithSoundForInputBusy(
        now: Long = SystemClock.uptimeMillis(),
        logSkip: Boolean = false
    ): Boolean {
        val busyUntil = scrollHotUntilMs()
        if (now > busyUntil || hasCachedDirectTouchSurface()) return false
        if (logSkip) {
            logInfoThrottled("sound:input-busy-skip", 2_000L) {
                "Start-with-sound skipped during active scroll remainingMs=${busyUntil - now}"
            }
        }
        return true
    }

    private fun rememberManualInstagramSoundMuteFromTouch(event: MotionEvent) {
        if (autoSoundTapInProgress || userMutedInstagramSoundUntilRestart) return
        if (!state.feedVideosStartWithSound && !state.storiesStartWithSound) return
        if (!isLikelyShortTap(event)) return
        val hit = synchronized(soundOffControlViews) {
            soundOffControlViews.firstOrNull { control -> visibleViewContainsRawPoint(control, event.rawX, event.rawY) }
        }
        if (hit != null) {
            rememberSoundOffCandidateTouch(event, hit, "touch-hit")
            markManualInstagramSoundMute(
                "touch-hit x=${event.rawX.toInt()} y=${event.rawY.toInt()} view=${describeViewBrief(hit)} bounds=${viewBoundsForLog(hit)}"
            )
            return
        }
        val near = synchronized(soundOffControlViews) {
            soundOffControlViews.firstOrNull { control -> visibleViewNearRawPoint(control, event.rawX, event.rawY) }
        }
        if (near != null) {
            rememberSoundOffCandidateTouch(event, near, "touch-near")
            logInfoThrottled("sound:manual-touch-near", 3_000L) {
                "Manual Instagram mute candidate touch near sound-off control x=${event.rawX.toInt()} y=${event.rawY.toInt()} " +
                    "view=${describeViewBrief(near)} bounds=${viewBoundsForLog(near)}"
            }
            return
        }
    }

    private fun markManualInstagramSoundMute(reason: String): Boolean {
        if (autoSoundTapInProgress) return false
        if (userMutedInstagramSoundUntilRestart) return true
        if (!state.feedVideosStartWithSound && !state.storiesStartWithSound) return false
        userMutedInstagramSoundUntilRestart = true
        logInfo("Manual Instagram mute detected reason=$reason; start-with-sound disabled until Instagram restart")
        return true
    }

    private fun rememberVisibleSoundOffControl(view: View, reason: String) {
        if (!state.feedVideosStartWithSound && !state.storiesStartWithSound) return
        if (shouldDeferStartWithSoundForInputBusy(logSkip = false)) return
        val added = soundOffControlViews.add(view)
        if (added) {
            logInfoThrottled("sound:off-control-seen:${view.javaClass.name}:${resourceEntryName(view).orEmpty()}", 4_000L) {
                "Observed visible Instagram sound-off control reason=$reason view=${describeViewBrief(view)} bounds=${viewBoundsForLog(view)}"
            }
        }
    }

    private fun rememberSoundOffCandidateTouch(event: MotionEvent, view: View?, reason: String) {
        lastSoundOffCandidateTouchAtMs = event.eventTime
        lastSoundOffCandidateTouchX = event.rawX.toInt()
        lastSoundOffCandidateTouchY = event.rawY.toInt()
        lastSoundOffCandidateReason = reason
        lastSoundOffCandidateView = "${describeViewBrief(view)} bounds=${viewBoundsForLog(view)}"
    }

    private fun maybeRememberManualInstagramSoundMuteFromVolume(source: String, vararg values: Any?): Boolean {
        if (autoSoundTapInProgress || userMutedInstagramSoundUntilRestart) return userMutedInstagramSoundUntilRestart
        if (!state.feedVideosStartWithSound && !state.storiesStartWithSound) return false
        val volumes = values.mapNotNull { (it as? Number)?.toFloat() }
        if (volumes.isEmpty() || volumes.any { it > 0.05f }) return false
        val age = SystemClock.uptimeMillis() - lastSoundOffCandidateTouchAtMs
        if (age in 0..1_800L) {
            return markManualInstagramSoundMute(
                "volume-mute source=$source values=${formatVolumeArgsForLog(volumes)} " +
                    "touchAgeMs=$age touch=${lastSoundOffCandidateTouchX},${lastSoundOffCandidateTouchY} " +
                    "touchReason=$lastSoundOffCandidateReason touchView=$lastSoundOffCandidateView"
            )
        }
        logInfoThrottled("sound:volume-mute-without-touch:$source", 6_000L) {
            "Observed Instagram volume mute source=$source values=${formatVolumeArgsForLog(volumes)} " +
                "without recent sound-off touch ageMs=$age; still forcing sound"
        }
        return false
    }

    private fun formatVolumeArgsForLog(values: List<Float>): String =
        values.joinToString(prefix = "[", postfix = "]") { String.format(Locale.US, "%.2f", it) }

    private fun visibleSoundOffControlCount(): Int = synchronized(soundOffControlViews) {
        soundOffControlViews.count(::isVisibleSoundOffControl)
    }

    private fun visibleSoundOffControlsForLog(limit: Int = 3): String = synchronized(soundOffControlViews) {
        soundOffControlViews.asSequence()
            .filter(::isVisibleSoundOffControl)
            .take(limit)
            .joinToString(separator = " | ") { "${describeViewBrief(it)} bounds=${viewBoundsForLog(it)}" }
            .ifBlank { "none" }
    }

    private fun isVisibleSoundOffControl(view: View): Boolean =
        view.isAttachedToWindow &&
            view.isShown &&
            view.width > 0 &&
            view.height > 0 &&
            view.contentDescription?.toString()?.trim()?.lowercase(Locale.US) == "turn sound off"

    private fun viewBoundsForLog(view: View?): String {
        if (view == null) return "null"
        if (!view.isAttachedToWindow) return "detached"
        val location = IntArray(2)
        return runCatching {
            view.getLocationOnScreen(location)
            "[${location[0]},${location[1]}][${location[0] + view.width},${location[1] + view.height}]"
        }.getOrDefault("unknown")
    }

    private fun isLikelyShortTap(event: MotionEvent): Boolean {
        if (event.eventTime < event.downTime || event.eventTime - event.downTime > 650L) return false
        if (lastInstagramSoundTouchDownTime != event.downTime) return false
        val root = currentActivity?.window?.decorView
        val slop = root?.context?.let { ViewConfiguration.get(it).scaledTouchSlop } ?: 24
        return abs(event.rawX - lastInstagramSoundTouchDownX) <= slop &&
            abs(event.rawY - lastInstagramSoundTouchDownY) <= slop
    }

    private fun isRealUserGestureRecentlyActive(now: Long = SystemClock.uptimeMillis()): Boolean {
        if (autoSoundTapInProgress) return true
        val downAge = now - flickPerfDownWallMs
        val upAge = now - flickPerfUpWallMs
        val downWithoutUp = flickPerfDownWallMs > 0L &&
            (flickPerfUpWallMs <= 0L || flickPerfUpWallMs < flickPerfDownWallMs) &&
            downAge in 0L..900L
        return downWithoutUp ||
            upAge in 0L..850L ||
            (flickPerfAwaitScrollUntilMs > 0L && now <= flickPerfAwaitScrollUntilMs) ||
            now <= instagramScrollBusyUntilMs
    }

    private fun visibleViewNearRawPoint(view: View, rawX: Float, rawY: Float): Boolean {
        if (!view.isAttachedToWindow || !view.isShown || view.width <= 0 || view.height <= 0) return false
        if (view.contentDescription?.toString()?.trim()?.lowercase(Locale.US) != "turn sound off") return false
        val location = IntArray(2)
        view.getLocationOnScreen(location)
        val expand = dp(view, 48).toFloat()
        val left = location[0].toFloat() - expand
        val top = location[1].toFloat() - expand
        return rawX >= left && rawX <= left + view.width + expand * 2f &&
            rawY >= top && rawY <= top + view.height + expand * 2f
    }

    private fun maybeAutoEnableInstagramSound(view: View, current: InstagramFeatureState = state) {
        if (!current.feedVideosStartWithSound && !current.storiesStartWithSound) return
        if (shouldDeferStartWithSoundForInputBusy(logSkip = false)) return
        if (userMutedInstagramSoundUntilRestart) {
            logInfoThrottled("sound:auto-enable-manual-muted", 6_000L) {
                "Auto-sound skipped visible control because manual Instagram mute is active until restart view=${describeViewBrief(view)}"
            }
            return
        }
        if (!view.isAttachedToWindow || !view.isShown) return
        val description = view.contentDescription?.toString()?.trim()?.lowercase(Locale.US) ?: return
        if (description == "turn sound off") {
            rememberVisibleSoundOffControl(view, "visible-pass")
            return
        }
        if (description != "turn sound on") return
        if (!autoSoundClickedViews.add(view)) return
        logInfoThrottled("sound:auto-enable-queued", 4_000L) {
            "Auto-sound queued tap view=${describeViewBrief(view)} feed=${current.feedVideosStartWithSound} stories=${current.storiesStartWithSound}"
        }
        fun attemptTap(attempt: Int) {
            val delay = if (attempt == 0) 0L else 140L
            view.postDelayed({
            if (userMutedInstagramSoundUntilRestart) return@postDelayed
            val activeDescription = view.contentDescription?.toString()?.trim()?.lowercase(Locale.US)
            if (!view.isAttachedToWindow || !view.isShown || activeDescription != "turn sound on") {
                autoSoundClickedViews.remove(view)
                logInfoThrottled("sound:auto-enable-skipped", 4_000L) {
                    "Auto-sound tap skipped attached=${view.isAttachedToWindow} shown=${view.isShown} description=$activeDescription"
                }
                return@postDelayed
            }
            if (view.width <= 0 || view.height <= 0) {
                if (attempt < 5) {
                    logInfoThrottled("sound:auto-enable-wait-layout", 2_000L) {
                        "Auto-sound waiting for mute control layout attempt=$attempt view=${describeViewBrief(view)}"
                    }
                    attemptTap(attempt + 1)
                } else {
                    autoSoundClickedViews.remove(view)
                    logInfoThrottled("sound:auto-enable-no-bounds", 4_000L) {
                        "Auto-sound tap abandoned; mute control never received bounds view=${describeViewBrief(view)}"
                    }
                }
                return@postDelayed
            }
            if (isRealUserGestureRecentlyActive()) {
                autoSoundClickedViews.remove(view)
                val retryDelay = (scrollHotUntilMs() - SystemClock.uptimeMillis()).coerceIn(450L, 1_600L)
                view.postDelayed({ maybeAutoEnableInstagramSound(view, state) }, retryDelay)
                return@postDelayed
            }
            val now = SystemClock.uptimeMillis()
            if (now - lastAutoSoundDispatchAtMs < 1_200L) {
                autoSoundClickedViews.remove(view)
                view.postDelayed({ maybeAutoEnableInstagramSound(view, state) }, 1_200L)
                return@postDelayed
            }
            lastAutoSoundDispatchAtMs = now
            val dispatched = runCatching { dispatchCenteredTap(view) }
                .onFailure { logError("Failed auto-enabling Instagram sound", it) }
                .getOrDefault(false)
            view.postDelayed({
                if (userMutedInstagramSoundUntilRestart) return@postDelayed
                val afterDescription = view.contentDescription?.toString()?.trim()?.lowercase(Locale.US)
                if (view.isAttachedToWindow && view.isShown && afterDescription == "turn sound on" && attempt < 5) {
                    logInfoThrottled("sound:auto-enable-retry", 2_000L) {
                        "Auto-sound tap did not change control; retrying attempt=$attempt dispatched=$dispatched view=${describeViewBrief(view)}"
                    }
                    attemptTap(attempt + 1)
                    return@postDelayed
                }
                if (afterDescription == "turn sound on") {
                    autoSoundClickedViews.remove(view)
                    logInfoThrottled("sound:auto-enable-dispatch-failed", 4_000L) {
                        "Auto-sound tap dispatch failed dispatched=$dispatched view=${describeViewBrief(view)}"
                    }
                } else {
                    logInfo("Auto-enabled Instagram sound from visible mute control dispatched=$dispatched after=$afterDescription")
                }
            }, 220L)
            }, delay)
        }
        attemptTap(0)
    }

    private fun dispatchCenteredTap(view: View): Boolean {
        if (isRealUserGestureRecentlyActive()) return false
        if (!view.isAttachedToWindow || !view.isShown || view.width <= 0 || view.height <= 0) return false
        return try {
            autoSoundTapInProgress = true
            val target = soundTapTarget(view)
            val clicked = target.callOnClick() || target.performClick()
            clicked || (target !== view && (view.callOnClick() || view.performClick()))
        } finally {
            autoSoundTapInProgress = false
        }
    }

    private fun soundTapTarget(view: View): View {
        var current: View? = view
        repeat(8) {
            val candidate = current ?: return@repeat
            if (candidate.isClickable || candidate.hasOnClickListeners()) return candidate
            current = candidate.parent as? View
        }
        return view
    }

    private fun visibleViewContainsRawPoint(view: View, rawX: Float, rawY: Float): Boolean {
        if (!view.isAttachedToWindow || !view.isShown || view.width <= 0 || view.height <= 0) return false
        if (view.contentDescription?.toString()?.trim()?.lowercase(Locale.US) != "turn sound off") return false
        val location = IntArray(2)
        view.getLocationOnScreen(location)
        val left = location[0].toFloat()
        val top = location[1].toFloat()
        return rawX >= left && rawX <= left + view.width && rawY >= top && rawY <= top + view.height
    }

    private fun looksLikeInstagramMuteControl(view: View?): Boolean {
        var current = view
        repeat(4) {
            val active = current ?: return false
            val combined = buildString {
                append(active.contentDescription?.toString().orEmpty())
                append(' ')
                append((active as? TextView)?.text?.toString().orEmpty())
                append(' ')
                append(resourceEntryName(active).orEmpty())
            }.lowercase(Locale.US)
            if (combined.contains("turn sound on")) return false
            if (combined.contains("turn sound off") ||
                combined.contains("mute audio") ||
                combined.contains("mute video") ||
                combined.contains("mute sound") ||
                combined.contains("sound off")
            ) return true
            current = active.parent as? View
        }
        return false
    }

    private fun installVideoPrepareSkipHook() {
        if (!state.disableVideoAutoPlay) return
        val hook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (!state.disableVideoAutoPlay || isReelsAutoplaySurfaceActive() || stackLooksLikeDownloadOrUpload()) return
                val hasExplicitAutoplayFalse = param.args.any { it is Boolean && it == false }
                if (!hasExplicitAutoplayFalse) return
                param.result = null
                logInfo("Skipped Instagram feed video prepare while autoplay is disabled")
            }
        }
        val cached = if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods("VideoPrepareSkip", appClassLoader).orEmpty()
        } else {
            emptyList()
        }
        var hooked = 0
        cached.forEach { method ->
            val signature = "${methodKey(method)}:VideoPrepareSkip_cached"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(method, hook)
                hooked++
            }.onFailure { logError("Failed cached video prepare skip hook $signature", it) }
        }
        if (hooked > 0) {
            logInfo("Installed cached video prepare skip hooks=$hooked")
            return
        }
        val methods = dexBridge.findMethodsUsingStrings("prepareVideo: clipsItemId")
            .filter { method ->
                method.returnType == java.lang.Void.TYPE &&
                    method.parameterTypes.any { it == java.lang.Boolean.TYPE || it == java.lang.Boolean::class.java }
            }
        val saved = mutableListOf<Method>()
        methods.forEach { method ->
            val signature = "${methodKey(method)}:VideoPrepareSkip"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(method, hook)
                saved += method
                hooked++
                logInfo("Installed video prepare skip hook -> $signature")
            }.onFailure { logError("Failed video prepare skip hook $signature", it) }
        }
        if (saved.isNotEmpty()) InstagramDexKitCache.saveMethods("VideoPrepareSkip", saved)
    }

    private fun installAv1AvoidanceHooks() {
        installEarlyDav1dLibraryBlock()
        installEarlyDav1dAdapterBlock()
        hookPlatformAv1CodecSelection()
        val classNames = linkedSetOf<String>()
        classNames += dexBridge.findClassNamesUsingStrings("Dav1dDecoder")
        classNames += dexBridge.findClassNamesUsingStrings("dav1d")
        classNames += dexBridge.findClassNamesUsingStrings("video/av01")
        classNames += dexBridge.findClassNamesUsingStrings("AV1_INSTANTIATION")
        var hooked = 0
        hooked += hookDav1dInstantiation(classNames)
        classNames.take(40).forEach { className ->
            val cls = runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() ?: return@forEach
            cls.declaredMethods.forEach { method ->
                if (!isAv1CapabilityMethod(method)) return@forEach
                val signature = "${methodKey(method)}:av1_avoidance"
                if (!hookedDexMethods.add(signature)) return@forEach
                runCatching {
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                if (!shouldAvoidAv1ForPlayback(param)) return
                                when (method.returnType) {
                                    java.lang.Boolean.TYPE, java.lang.Boolean::class.java -> param.result = false
                                    java.lang.Integer.TYPE, java.lang.Integer::class.java -> param.result = 0
                                }
                            }
                        }
                    )
                    hooked++
                }.onFailure { logError("Failed AV1 avoidance hook $signature", it) }
            }
        }
        if (classNames.isNotEmpty()) logInfo("AV1 avoidance classes=${classNames.take(8).joinToString()}")
        logInfo("Installed AV1 avoidance hooks=$hooked classes=${classNames.size}")
    }

    private fun installEarlyDav1dLibraryBlock() {
        if (earlyDav1dLibraryBlockInstalled) return
        runSafe("Early Dav1d library block") {
            val loaderClass = runCatching { Class.forName("X.029W", false, appClassLoader) }.getOrNull() ?: return@runSafe
            var hooked = 0
            loaderClass.declaredMethods
                .filter { method ->
                    method.name == "loadLibrary" &&
                        method.parameterTypes.isNotEmpty() &&
                        method.parameterTypes[0] == String::class.java &&
                        method.returnType == Boolean::class.javaPrimitiveType
                }
                .forEach { method ->
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                val library = param.args.firstOrNull() as? String ?: return
                                if (!isDav1dLibraryName(library)) return
                                logInfo("Blocked Instagram Dav1d library load: $library")
                                param.result = false
                            }
                        }
                    )
                    hooked++
                }
            earlyDav1dLibraryBlockInstalled = hooked > 0
            if (hooked > 0) logInfo("Installed early Dav1d library block hooks=$hooked")
        }
    }

    private fun isDav1dLibraryName(value: String): Boolean {
        val lower = value.lowercase(Locale.US)
        return lower == "dav1dexo" || lower.contains("dav1d")
    }

    private fun installEarlyDav1dSystemLoadBlock() {
        if (earlyDav1dSystemLoadBlockInstalled) return
        earlyDav1dSystemLoadBlockInstalled = true
        runSafe("Early Dav1d system load block") {
            val hook = object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (stackLooksLikeDownloadOrUpload()) return
                    val library = param.args.firstOrNull() as? String ?: return
                    if (!isDav1dLibraryName(library)) return
                    param.throwable = UnsatisfiedLinkError("Purrfect disabled Instagram Dav1d playback decoder")
                    logInfo("Blocked Dav1d system library load: $library")
                }
            }
            var hooked = 0
            runCatching {
                XposedBridge.hookAllMethods(System::class.java, "loadLibrary", hook)
                hooked++
            }.onFailure { logError("Failed System.loadLibrary Dav1d block", it) }
            runCatching {
                XposedBridge.hookAllMethods(Runtime::class.java, "loadLibrary0", hook)
                hooked++
            }.onFailure { logError("Failed Runtime.loadLibrary0 Dav1d block", it) }
            runCatching {
                XposedBridge.hookAllMethods(Runtime::class.java, "load0", hook)
                hooked++
            }.onFailure { logError("Failed Runtime.load0 Dav1d block", it) }
            if (hooked > 0) logInfo("Installed Dav1d system load block hooks=$hooked")
        }
    }

    private fun installEarlyDav1dAdapterBlock() {
        if (earlyDav1dAdapterBlockInstalled) return
        runSafe("Early Dav1d adapter block") {
            var hooked = 0
            runCatching { Class.forName("exoplayer2.av1.src.Dav1dMediaCodecAdapter", false, appClassLoader) }
                .getOrNull()
                ?.let { hooked += hookDav1dAdapterRuntimeClass(it) }
            runCatching { Class.forName("exoplayer2.av1.src.Dav1dDecoder", false, appClassLoader) }
                .getOrNull()
                ?.let { hooked += hookDav1dDecoderRuntimeClass(it) }
            earlyDav1dAdapterBlockInstalled = hooked > 0
            if (hooked > 0) logInfo("Installed early Dav1d adapter block hooks=$hooked")
        }
    }

    private fun installDav1dClassLoadMapper() {
        if (dav1dClassLoadMapperInstalled) return
        dav1dClassLoadMapperInstalled = true
        runSafe("Dav1d class-load mapper") {
            XposedBridge.hookAllMethods(
                ClassLoader::class.java,
                "loadClass",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val name = param.args.firstOrNull() as? String ?: return
                        val cls = param.result as? Class<*> ?: return
                        when (name) {
                            "exoplayer2.av1.src.Dav1dMediaCodecAdapter" -> hookDav1dAdapterRuntimeClass(cls)
                            "exoplayer2.av1.src.Dav1dDecoder" -> hookDav1dDecoderRuntimeClass(cls)
                        }
                    }
                }
            )
            logInfo("Installed Dav1d class-load mapper")
        }
    }

    private fun runtimeClassKey(cls: Class<*>): String {
        return "${cls.name}@${System.identityHashCode(cls.classLoader)}"
    }

    private fun hookDav1dAdapterRuntimeClass(cls: Class<*>): Int {
        if (!hookedDav1dRuntimeClasses.add(runtimeClassKey(cls) + ":adapter")) return 0
        var hooked = 0
        cls.declaredMethods
            .filter { it.name == "configure" || it.name == "createDav1dDecoder" }
            .forEach { method ->
                runCatching {
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                if (stackLooksLikeDownloadOrUpload()) return
                                val format = param.args.firstOrNull { it is MediaFormat } as? MediaFormat
                                val mime = format?.let { runCatching { it.getString(MediaFormat.KEY_MIME) }.getOrNull() }.orEmpty()
                                if (method.name == "configure" && mime.isNotBlank() && !isAv1Mime(mime)) return
                                param.result = null
                                logInfo("Blocked Instagram Dav1d adapter ${method.name}${if (mime.isBlank()) "" else " for $mime"}")
                            }
                        }
                    )
                    hooked++
                }.onFailure { logError("Failed runtime Dav1d adapter hook ${cls.name}.${method.name}", it) }
            }
        if (hooked > 0) logInfo("Hooked runtime Dav1d adapter ${cls.name} methods=$hooked")
        return hooked
    }

    private fun hookDav1dDecoderRuntimeClass(cls: Class<*>): Int {
        if (!hookedDav1dRuntimeClasses.add(runtimeClassKey(cls) + ":decoder")) return 0
        var hooked = 0
        cls.declaredConstructors.forEach { constructor ->
            runCatching {
                constructor.isAccessible = true
                XposedBridge.hookMethod(
                    constructor,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (stackLooksLikeDownloadOrUpload()) return
                            param.throwable = IllegalStateException("Purrfect disabled Instagram Dav1d playback decoder")
                            logInfo("Blocked Instagram Dav1d decoder constructor")
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed runtime Dav1d decoder hook ${cls.name}", it) }
        }
        if (hooked > 0) logInfo("Hooked runtime Dav1d decoder ${cls.name} constructors=$hooked")
        return hooked
    }

    private fun hookDav1dInstantiation(classNames: Set<String>): Int {
        var hooked = 0
        classNames
            .filter { name ->
                val lower = name.lowercase(Locale.US)
                lower.contains("dav1ddecoder") || lower.contains("dav1dmediacodecadapter")
            }
            .forEach { className ->
                val cls = runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() ?: return@forEach
                if (cls.name.lowercase(Locale.US).contains("dav1dmediacodecadapter")) {
                    cls.declaredMethods
                        .filter { method -> method.name == "configure" && method.parameterTypes.any { it == MediaFormat::class.java } }
                        .forEach { method ->
                            val signature = "${methodKey(method)}:dav1d_configure_block"
                            if (!hookedDexMethods.add(signature)) return@forEach
                            runCatching {
                                method.isAccessible = true
                                XposedBridge.hookMethod(
                                    method,
                                    object : XC_MethodHook() {
                                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                            if (stackLooksLikeDownloadOrUpload()) return
                                            val format = param.args.firstOrNull { it is MediaFormat } as? MediaFormat ?: return
                                            val mime = runCatching { format.getString(MediaFormat.KEY_MIME) }.getOrNull().orEmpty()
                                            if (!isAv1Mime(mime)) return
                                            param.result = null
                                            logInfo("Blocked Instagram Dav1d adapter configure for $mime")
                                        }
                                    }
                                )
                                hooked++
                            }.onFailure { logError("Failed Dav1d configure block $signature", it) }
                        }
                    cls.declaredMethods
                        .filter { method -> method.name == "createDav1dDecoder" }
                        .forEach { method ->
                            val signature = "${methodKey(method)}:dav1d_create_block"
                            if (!hookedDexMethods.add(signature)) return@forEach
                            runCatching {
                                method.isAccessible = true
                                XposedBridge.hookMethod(
                                    method,
                                    object : XC_MethodHook() {
                                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                            if (stackLooksLikeDownloadOrUpload()) return
                                            param.result = null
                                            logInfo("Blocked Instagram Dav1d decoder creation: ${cls.name}")
                                        }
                                    }
                                )
                                hooked++
                            }.onFailure { logError("Failed Dav1d create block $signature", it) }
                        }
                }
                if (cls.name.lowercase(Locale.US).contains("dav1ddecoder")) {
                    cls.declaredMethods
                        .filter { method -> method.name == "dav1dInit" || method.name == "dav1dInit2" }
                        .forEach { method ->
                            val signature = "${methodKey(method)}:dav1d_native_init_block"
                            if (!hookedDexMethods.add(signature)) return@forEach
                            runCatching {
                                method.isAccessible = true
                                XposedBridge.hookMethod(
                                    method,
                                    object : XC_MethodHook() {
                                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                            if (stackLooksLikeDownloadOrUpload()) return
                                            param.result = 0L
                                            logInfo("Blocked Instagram Dav1d native init: ${method.name}")
                                        }
                                    }
                                )
                                hooked++
                            }.onFailure { logError("Failed Dav1d native init block $signature", it) }
                        }
                }
                cls.declaredConstructors.forEach { constructor ->
                    val signature = "${constructor.declaringClass.name}#<init>/${constructor.parameterTypes.size}:dav1d_block"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    runCatching {
                        constructor.isAccessible = true
                        XposedBridge.hookMethod(
                            constructor,
                            object : XC_MethodHook() {
                                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                    if (stackLooksLikeDownloadOrUpload()) return
                                    param.throwable = IllegalStateException("Purrfect disabled Instagram Dav1d playback decoder")
                                    logInfo("Blocked Instagram Dav1d playback decoder: ${cls.name}")
                                }
                            }
                        )
                        hooked++
                    }.onFailure { logError("Failed Dav1d instantiation block $signature", it) }
                }
            }
        return hooked
    }

    private fun hookPlatformAv1CodecSelection() {
        runSafe("Platform AV1 codec selection") {
            XposedBridge.hookAllMethods(
                MediaCodecList::class.java,
                "findDecoderForFormat",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val format = param.args.firstOrNull() as? MediaFormat ?: return
                        val mime = runCatching { format.getString(MediaFormat.KEY_MIME) }.getOrNull().orEmpty()
                        if (isAv1Mime(mime)) {
                            param.result = null
                            logInfo("Avoided platform AV1 decoder selection")
                        }
                    }
                }
            )
        }
    }

    private fun isAv1CapabilityMethod(method: Method): Boolean {
        val returnsSupported = method.returnType == java.lang.Boolean.TYPE ||
            method.returnType == java.lang.Boolean::class.java ||
            method.returnType == java.lang.Integer.TYPE ||
            method.returnType == java.lang.Integer::class.java
        if (!returnsSupported) return false
        val owner = method.declaringClass.name.lowercase(Locale.US)
        val name = method.name.lowercase(Locale.US)
        if (owner.contains("dav1d") || owner.contains("av1")) return true
        if (name.contains("support") || name.contains("select") || name.contains("can") || name.startsWith("is")) return true
        return method.parameterTypes.any { type ->
            val typeName = type.name.lowercase(Locale.US)
            typeName.contains("format") || typeName.contains("codec") || typeName.contains("mime")
        }
    }

    private fun shouldAvoidAv1ForPlayback(param: XC_MethodHook.MethodHookParam<*>): Boolean {
        if (stackLooksLikeDownloadOrUpload()) return false
        return argsContainAv1(param.args) || param.thisObject?.javaClass?.name?.lowercase(Locale.US)?.let {
            it.contains("dav1d") || it.contains("av1")
        } == true
    }

    private fun argsContainAv1(args: Array<Any?>?): Boolean {
        args.orEmpty().forEach { arg ->
            if (objectContainsAv1(arg, 0, Collections.newSetFromMap(IdentityHashMap()))) return true
        }
        return false
    }

    private fun objectContainsAv1(value: Any?, depth: Int, visited: MutableSet<Any>): Boolean {
        value ?: return false
        if (depth > 2) return false
        if (value is String) return isAv1Mime(value) || value.contains("av01", ignoreCase = true) || value.contains("dav1d", ignoreCase = true)
        if (value is MediaFormat) {
            val mime = runCatching { value.getString(MediaFormat.KEY_MIME) }.getOrNull().orEmpty()
            return isAv1Mime(mime)
        }
        val cls = value.javaClass
        if (cls.isPrimitive || value is Number || value is Boolean || cls.name.startsWith("java.lang")) return false
        if (!visited.add(value)) return false
        var current: Class<*>? = cls
        while (current != null && current != Any::class.java) {
            current.declaredFields.forEach { field ->
                if (field.type != String::class.java && !field.type.name.lowercase(Locale.US).contains("format")) return@forEach
                runCatching {
                    field.isAccessible = true
                    if (objectContainsAv1(field.get(value), depth + 1, visited)) return true
                }
            }
            current = current.superclass
        }
        return false
    }

    private fun stackLooksLikeDownloadOrUpload(): Boolean {
        return Thread.currentThread().stackTrace.take(48).any { frame ->
            val text = "${frame.className}.${frame.methodName}".lowercase(Locale.US)
            text.contains("download") || text.contains("upload") || text.contains("transcode")
        }
    }

    private fun isAv1Mime(value: String): Boolean {
        val lower = value.lowercase(Locale.US)
        return lower == "video/av01" || lower == "video/av1" || lower.contains("av01")
    }

    private fun stackLooksLikeReelsPlayback(): Boolean {
        return Thread.currentThread().stackTrace.take(48).any { frame ->
            val text = "${frame.className}.${frame.methodName}".lowercase(Locale.US)
            text.contains("clips") ||
                text.contains("reelviewer") ||
                text.contains("reel_viewer") ||
                text.contains("reelsviewer") ||
                text.contains("clipsviewer")
        }
    }

    private fun isReelsAutoplaySurfaceActive(): Boolean {
        if (stackLooksLikeReelsPlayback()) return true
        val now = System.currentTimeMillis()
        if (now - reelsAutoplaySurfaceCheckAtMs < 350L) return reelsAutoplaySurfaceActive
        reelsAutoplaySurfaceCheckAtMs = now
        val activity = currentActivity
        val root = activity?.window?.decorView
        reelsAutoplaySurfaceActive = activity?.let { isAnySelected(it, "clips_tab") } == true ||
            hasVisibleIdContaining(root, "clips_viewer", "clips_tab_view_pager", "clips_viewer_video_layout")
        if (reelsAutoplaySurfaceActive && activity != null) applySmoothActivityTuning(activity)
        return reelsAutoplaySurfaceActive
    }

    private fun isFeedAutoplaySurfaceActive(): Boolean {
        if (stackLooksLikeReelsPlayback()) return false
        if (Thread.currentThread().stackTrace.take(48).any { frame ->
                val text = "${frame.className}.${frame.methodName}".lowercase(Locale.US)
                text.contains("feed") || text.contains("timeline") || text.contains("media_viewer")
            }
        ) return true
        val activity = currentActivity ?: return false
        val root = activity.window?.decorView
        if (hasVisibleIdContaining(root, "clips_viewer", "clips_tab_view_pager", "clips_viewer_video_layout")) return false
        return isAnySelected(activity, "feed_tab", "current_feed_tab") ||
            (isAnyVisible(activity, "feed_tab", "current_feed_tab") &&
                !isAnySelected(activity, "direct_tab", "search_tab", "clips_tab"))
    }

    private fun installDoubleTapLikeDexHooks() {
        var cachedFeedHooked = false
        var cachedReelsHooked = false
        if (InstagramDexKitCache.isCacheValid()) {
            cachedFeedHooked = InstagramDexKitCache.loadMethod("DoubleTapLike", appClassLoader)?.let { method ->
                hookDoubleTapMethods("DoubleTapLike", listOf(method)) { stackLooksLikeDoubleTapCallback() } > 0
            } == true
            val cachedLegacyReelsHooked = InstagramDexKitCache.loadMethod("DoubleTapLikeReels", appClassLoader)?.let { method ->
                hookDoubleTapMethods("DoubleTapLikeReels", listOf(method)) { stackLooksLikeDoubleTapCallback() } > 0
            } == true
            val cachedGestureReelsHooked = InstagramDexKitCache.loadMethods("DoubleTapLikeReelsGestures", appClassLoader)?.let { methods ->
                hookDoubleTapMethods("DoubleTapLikeReelsGestures", methods) { param ->
                    looksLikeClipsDoubleTapGesture(param.thisObject)
                } > 0
            } == true
            cachedReelsHooked = cachedLegacyReelsHooked || cachedGestureReelsHooked
            if (cachedFeedHooked && cachedGestureReelsHooked) {
                logInfo("DexKit cached hook installed: DoubleTapLike")
                return
            }
        }

        if (!cachedFeedHooked) {
            val feedMethods = dexBridge.findMethodsUsingStrings("double_tap_on_liked", "used_double_tap")
            if (hookDoubleTapMethods("DoubleTapLike", feedMethods) { stackLooksLikeDoubleTapCallback() } > 0) {
                feedMethods.firstOrNull()?.let { InstagramDexKitCache.saveMethod("DoubleTapLike", it) }
                cachedFeedHooked = true
            }
        }

        val reelsGestureMethods = dexBridge.findMethodsByName("onDoubleTap", returnType = "boolean", paramCount = 1)
            .filter { method ->
                method.parameterTypes.singleOrNull()?.name == MotionEvent::class.java.name &&
                    isLikelyClipsGestureClass(method.declaringClass)
            }
        if (hookDoubleTapMethods("DoubleTapLikeReelsGestures", reelsGestureMethods) { param ->
                looksLikeClipsDoubleTapGesture(param.thisObject)
            } > 0
        ) {
            InstagramDexKitCache.saveMethods("DoubleTapLikeReelsGestures", reelsGestureMethods)
            cachedReelsHooked = true
        }

        val reelsLegacyMethods = dexBridge.findMethodsUsingStrings("clips_doubletap", "LIKE_FIRED")
        if (hookDoubleTapMethods("DoubleTapLikeReels", reelsLegacyMethods) {
            stackLooksLikeDoubleTapCallback()
            } > 0
        ) {
            reelsLegacyMethods.firstOrNull()?.let { InstagramDexKitCache.saveMethod("DoubleTapLikeReels", it) }
            cachedReelsHooked = true
        }

        if (!cachedFeedHooked) logInfo("DoubleTapLike feed method not found")
        if (!cachedReelsHooked) logInfo("DoubleTapLike reels entry not found")
    }

    private fun hookDoubleTapMethods(
        name: String,
        methods: List<Method>,
        shouldBlock: (XC_MethodHook.MethodHookParam<*>) -> Boolean
    ): Int {
        var hooked = 0
        methods.forEach { method ->
            val signature = "${methodKey(method)}:$name"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.disableDoubleTapLike || !shouldBlock(param)) return
                            blockDoubleTapLike(param, method)
                        }
                    }
                )
                hooked++
                logInfo("DexKit hook installed: $name -> $signature")
            }.onFailure { logError("Failed DexKit hook $name $signature", it) }
        }
        return hooked
    }

    private fun blockDoubleTapLike(param: XC_MethodHook.MethodHookParam<*>, method: Method) {
        param.result = if (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) {
            true
        } else {
            null
        }
    }

    private fun stackLooksLikeDoubleTapCallback(): Boolean {
        return Thread.currentThread().stackTrace.any { frame ->
            frame.methodName == "onDoubleTap" || frame.methodName == "onDoubleTapEvent"
        }
    }

    private fun isLikelyClipsGestureClass(clazz: Class<*>?): Boolean {
        if (clazz == null || !GestureDetector.SimpleOnGestureListener::class.java.isAssignableFrom(clazz)) return false
        var score = 0
        var current: Class<*>? = clazz
        while (current != null && current != Any::class.java) {
            current.declaredFields.forEach { field ->
                val typeName = field.type.name
                if (typeName == "com.instagram.clips.intf.ClipsViewerConfig") score += 3
                if (typeName == "com.instagram.common.session.UserSession") score += 1
                if (typeName == "android.view.GestureDetector") score += 1
                if (typeName == "android.view.ScaleGestureDetector") score += 1
                if (typeName.contains("ClipsViewer")) score += 2
            }
            current = current.superclass
        }
        return score >= 4
    }

    private fun looksLikeClipsDoubleTapGesture(target: Any?): Boolean {
        target ?: return false
        if (isLikelyClipsGestureClass(target.javaClass)) return true
        var current: Class<*>? = target.javaClass
        while (current != null && current != Any::class.java) {
            current.declaredFields.forEach { field ->
                runCatching {
                    if (!View::class.java.isAssignableFrom(field.type)) return@forEach
                    field.isAccessible = true
                    val value = field.get(target) as? View ?: return@forEach
                    if (looksLikeClipsView(value)) return true
                }
            }
            current = current.superclass
        }
        return false
    }

    private fun looksLikeClipsView(view: View): Boolean {
        var current: View? = view
        while (current != null) {
            val entryName = resourceEntryName(current)
            if (entryName != null && (
                    entryName.contains("clips_video_container") ||
                        entryName.contains("clips_viewer_video_layout") ||
                        entryName.contains("sponsored_clips_showreel_view")
                    )
            ) {
                return true
            }
            current = current.parent as? View
        }
        return false
    }

