    private fun clearExpiryTimestamp(target: Any?) {
        if (target == null) return
        val now = System.currentTimeMillis()
        val year2100 = 4_102_444_800_000L
        var cls: Class<*>? = target.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (field.type != java.lang.Long.TYPE) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.getLong(target)
                    if (value > now && value < year2100) field.setLong(target, 0L)
                }
            }
            cls = cls.superclass
        }
    }

    private fun installKeepUnsentMessagesHooks() {
        runSafe("Keep unsent messages hooks") {
            loadKeepUnsentDeletedIds(androidContext)
            fun hookKeepUnsentMethods(
                cacheKey: String,
                signatureSuffix: String,
                methods: List<Method>,
                hook: XC_MethodHook,
                afterHook: ((Method) -> Int)? = null,
                save: Boolean = true
            ): Int {
                var hooked = 0
                val saved = ArrayList<Method>()
                methods.forEach { method ->
                    val signature = "${methodKey(method)}:$signatureSuffix"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    runCatching {
                        method.isAccessible = true
                        XposedBridge.hookMethod(method, hook)
                        saved += method
                        hooked++
                        afterHook?.let { hooked += it(method) }
                    }.onFailure { logError("Failed keep-unsent hook $signature", it) }
                }
                if (save && saved.isNotEmpty()) InstagramDexKitCache.saveMethods(cacheKey, saved)
                return hooked
            }

            fun hookCachedKeepUnsentMethods(
                cacheKey: String,
                signatureSuffix: String,
                hook: XC_MethodHook,
                afterHook: ((Method) -> Int)? = null,
                validator: (Method) -> Boolean = { true }
            ): Int {
                if (!InstagramDexKitCache.isCacheValid()) return 0
                val cached = InstagramDexKitCache.loadMethods(cacheKey, appClassLoader).orEmpty()
                    .filter(validator)
                if (cached.isEmpty()) return 0
                val hooked = hookKeepUnsentMethods(cacheKey, signatureSuffix, cached, hook, afterHook, save = false)
                if (hooked > 0) logInfo("Installed cached keep-unsent hooks $cacheKey=$hooked")
                return hooked
            }

            fun isRenderMethod(method: Method): Boolean = method.parameterTypes.size == 1

            fun isProcessMethod(method: Method): Boolean =
                method.returnType == Void.TYPE &&
                    method.parameterTypes.size == 4 &&
                    method.parameterTypes[1] == String::class.java &&
                    List::class.java.isAssignableFrom(method.parameterTypes[2]) &&
                    method.parameterTypes[3] == java.lang.Boolean.TYPE

            fun isRealtimeRemoveMethod(method: Method): Boolean = method.parameterTypes.size == 8

            fun isStoreDeleteMethod(method: Method): Boolean =
                method.returnType == Void.TYPE &&
                    method.parameterTypes.size == 5 &&
                    method.parameterTypes[1] == java.lang.Integer::class.java &&
                    method.parameterTypes[2] == String::class.java &&
                    method.parameterTypes[3] == String::class.java &&
                    method.parameterTypes[4] == java.lang.Boolean.TYPE

            fun isLegacyPushMethod(method: Method): Boolean =
                method.returnType == Void.TYPE &&
                    method.parameterTypes.isNotEmpty() &&
                    !Modifier.isStatic(method.modifiers)

            fun hookCachedStoreDeleteMethods(hook: XC_MethodHook): Int {
                if (!InstagramDexKitCache.isCacheValid()) return 0
                val cached = InstagramDexKitCache.loadMethods("KeepUnsent_store_delete", appClassLoader).orEmpty()
                if (cached.isEmpty()) return 0
                var hooked = 0
                cached.forEach { method ->
                    if (method.returnType != Void.TYPE) return@forEach
                    val signature = "${methodKey(method)}:keep_unsent_store_delete_cached"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    runCatching {
                        method.isAccessible = true
                        XposedBridge.hookMethod(method, hook)
                        hooked++
                        if (isStoreDeleteMethod(method)) {
                            hooked += hookKeepUnsentStoreDeleteWrappers(method.declaringClass, hook).size
                        }
                    }.onFailure { logError("Failed cached keep-unsent store hook $signature", it) }
                }
                if (hooked > 0) logInfo("Installed cached keep-unsent hooks KeepUnsent_store_delete=$hooked")
                return hooked
            }

            val renderHook = object : XC_MethodHook() {
                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    if (!state.keepUnsentMessages) return
                    val result = param.result as? List<*> ?: return
                    val filtered = filterRemoveOperations(result)
                    if (filtered !== result) param.result = filtered
                }
            }
            var renderHooks = hookCachedKeepUnsentMethods(
                "KeepUnsent_render_results",
                "keep_unsent_render_cached",
                renderHook,
                validator = ::isRenderMethod
            )
            if (renderHooks == 0) {
                renderHooks = hookKeepUnsentMethods(
                    "KeepUnsent_render_results",
                    "keep_unsent_render",
                    dexBridge.findMethodsUsingStringsConstrained(
                        listOf("replace_message", "remove_message", "noop"),
                        paramCount = 1
                    ).filter(::isRenderMethod),
                    renderHook
                )
            }

            val processHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (!state.keepUnsentMessages) return
                    val operations = param.args?.getOrNull(2) as? List<*> ?: return
                    val deleteIds = collectRemoveOperationIds(operations)
                    if (deleteIds.isNotEmpty()) {
                        rememberKeepUnsentDeletedIds(deleteIds, operations)
                        rememberScopedDeleteIds(param, deleteIds)
                    }
                    val filtered = filterRemoveOperations(operations)
                    if (filtered !== operations) param.args[2] = filtered
                }

                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    restoreScopedDeleteIds(param)
                }
            }
            var processHooks = hookCachedKeepUnsentMethods(
                "KeepUnsent_process_ops",
                "keep_unsent_process_cached",
                processHook,
                validator = ::isProcessMethod
            )
            if (processHooks == 0) {
                processHooks = hookKeepUnsentMethods(
                    "KeepUnsent_process_ops",
                    "keep_unsent_process",
                    dexBridge.findMethodsUsingStringsConstrained(
                        listOf("process_start", "process_end"),
                        paramCount = 4,
                        returnType = "void"
                    ).filter(::isProcessMethod),
                    processHook
                )
            }

            val realtimeHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (!state.keepUnsentMessages) return
                    val deleteIds = collectRealtimeRemoveIds(param.args)
                    if (deleteIds.isNotEmpty()) {
                        rememberKeepUnsentDeletedIds(deleteIds, param.args)
                        rememberScopedDeleteIds(param, deleteIds)
                    }
                }

                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    restoreScopedDeleteIds(param)
                }
            }
            var realtimeHooks = hookCachedKeepUnsentMethods(
                "KeepUnsent_delta_remove",
                "keep_unsent_delta_remove_cached",
                realtimeHook,
                validator = ::isRealtimeRemoveMethod
            )
            if (realtimeHooks == 0) {
                realtimeHooks = hookKeepUnsentMethods(
                    "KeepUnsent_delta_remove",
                    "keep_unsent_delta_remove",
                    dexBridge.findMethodsUsingStringsConstrained(
                        listOf(
                            "NewMessageDeltaProcessor",
                            "Invalid DirectMessage format",
                            "persist_message_success",
                            "remove"
                        ),
                        paramCount = 8
                    ).filter(::isRealtimeRemoveMethod),
                    realtimeHook
                )
            }

            val legacyHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (state.keepUnsentMessages && containsLegacyDeleteItemPayload(param.args)) {
                        rememberKeepUnsentDeletedIds(collectUsefulIdsDeep(param.args), param.args)
                        param.result = null
                    }
                }
            }
            var legacyHooks = hookCachedKeepUnsentMethods(
                "KeepUnsent_legacy_push",
                "keep_unsent_legacy_cached",
                legacyHook,
                validator = ::isLegacyPushMethod
            )
            if (legacyHooks == 0) {
                val legacyMethods = dexBridge.findMethodsUsingStrings(
                    "direct_v2_delete_item",
                    "direct_v2_edit_message",
                    "direct_v2_reply_reminder"
                ).map { it.declaringClass }
                    .toSet()
                    .flatMap { clazz ->
                        clazz.declaredMethods
                            .filter(::isLegacyPushMethod)
                    }
                legacyHooks = hookKeepUnsentMethods("KeepUnsent_legacy_push", "keep_unsent_legacy", legacyMethods, legacyHook)
            }

            val storeHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (!state.keepUnsentMessages) return
                    if (isScopedRemoteDelete(param.args) || isOneIdServerDelete(param.args)) {
                        rememberKeepUnsentDeletedIds(collectUsefulIdsDeep(param.args), param.args)
                        param.result = null
                    }
                }
            }
            var storeHooks = hookCachedStoreDeleteMethods(storeHook)
            if (storeHooks == 0) {
                val discoveredStoreMethods = dexBridge.findMethodsUsingStringsConstrained(
                    listOf("Client context should not be null if messageId is null."),
                    paramCount = 5,
                    returnType = "void"
                ).filter(::isStoreDeleteMethod)
                val wrapperMethods = ArrayList<Method>()
                storeHooks = hookKeepUnsentMethods(
                    "KeepUnsent_store_delete",
                    "keep_unsent_store_delete",
                    discoveredStoreMethods,
                    storeHook,
                    afterHook = { method ->
                        val wrappers = hookKeepUnsentStoreDeleteWrappers(method.declaringClass, storeHook)
                        wrapperMethods += wrappers
                        wrappers.size
                    },
                    save = false
                )
                if (discoveredStoreMethods.isNotEmpty() || wrapperMethods.isNotEmpty()) {
                    InstagramDexKitCache.saveMethods("KeepUnsent_store_delete", discoveredStoreMethods + wrapperMethods)
                }
            }

            val rowHooks = installKeepUnsentDeletedIndicatorHooks()

            logInfo("Installed keep-unsent hooks render=$renderHooks process=$processHooks realtime=$realtimeHooks legacy=$legacyHooks store=$storeHooks rows=$rowHooks")
        }
    }

    private fun filterRemoveOperations(operations: List<*>): List<*> {
        var changed = false
        val filtered = ArrayList<Any?>()
        operations.forEach { operation ->
            if (isLikelyRemoveMessageOperation(operation)) {
                rememberKeepUnsentDeletedIds(collectStringFields(operation), operation)
                changed = true
            } else {
                filtered += operation
            }
        }
        return if (changed) filtered else operations
    }

    private fun isLikelyRemoveMessageOperation(operation: Any?): Boolean {
        if (operation == null) return false
        val className = operation.javaClass.name
        if (className.endsWith(".WH1") || operation.javaClass.simpleName == "WH1") return true

        var stringFieldCount = 0
        var hasMessageModelObject = false
        var nonStringObjects = 0
        var cls: Class<*>? = operation.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(operation) ?: return@forEach
                    if (value is String) {
                        stringFieldCount++
                    } else if (!isPrimitiveLike(value)) {
                        nonStringObjects++
                        if (looksLikeDirectMessageModel(value)) hasMessageModelObject = true
                    }
                }
            }
            cls = cls.superclass
        }
        return stringFieldCount >= 2 && nonStringObjects > 0 && !hasMessageModelObject
    }

    private fun containsLegacyDeleteItemPayload(args: Array<Any?>?): Boolean {
        return args?.any { containsStringFieldValue(it, "direct_v2_delete_item") } == true
    }

    private fun containsStringFieldValue(value: Any?, target: String): Boolean {
        if (value == null) return false
        if (value == target) return true
        var cls: Class<*>? = value.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type != String::class.java) return@forEach
                val found = runCatching {
                    field.isAccessible = true
                    field.get(value) == target
                }.getOrDefault(false)
                if (found) return true
            }
            cls = cls.superclass
        }
        return false
    }

    private fun isOneIdServerDelete(args: Array<Any?>?): Boolean {
        if (args == null) return false
        val clientContext: String?
        val messageId: String?
        if (args.size == 3) {
            clientContext = args.getOrNull(1) as? String
            messageId = args.getOrNull(2) as? String
        } else if (args.size == 5) {
            clientContext = args.getOrNull(2) as? String
            messageId = args.getOrNull(3) as? String
        } else {
            return false
        }
        return isUsefulMessageId(clientContext) xor isUsefulMessageId(messageId)
    }

    private fun isUsefulMessageId(value: String?): Boolean {
        val trimmed = value?.trim().orEmpty()
        val lower = trimmed.lowercase(Locale.US)
        return trimmed.length >= 4 &&
            lower !in setOf("null", "none", "remove", "remove_message", "direct_v2_delete_item")
    }

    private fun looksLikeDirectMessageModel(value: Any?): Boolean {
        if (value == null) return false
        var hasMessageIdGetter = false
        var hasClientContextGetter = false
        var cls: Class<*>? = value.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 4) {
            cls.declaredMethods.forEach { method ->
                if (method.parameterTypes.isNotEmpty() || method.returnType != String::class.java) return@forEach
                if (method.name == "A0o") hasMessageIdGetter = true
                if (method.name == "A0p") hasClientContextGetter = true
            }
            cls = cls.superclass
        }
        return hasMessageIdGetter && hasClientContextGetter
    }

    private fun isPrimitiveLike(value: Any): Boolean {
        val cls = value.javaClass
        return value is Number ||
            value is Boolean ||
            value is Char ||
            cls.isEnum
    }

    private fun installCopyBioModelHooks() {
        runSafe("Copy bio model hooks") {
            var hooked = 0
            arrayOf("com.instagram.user.model.LiveTreeUserDict", "p000X.C2A5", "X.C2A5").forEach { className ->
                hooked += hookBiographyStringMethods(className, exactOnly = true)
            }
            hooked += hookBiographyHashMethods()
            hooked += hookDexDiscoveredBiographyClasses()
            hooked += hookProfileActionSheetControllers()
            logInfo("Installed copy-bio source-style hooks=$hooked")
        }
    }

    private var copyBioClassesCached = false
    private val copyBioCachedClassNames = HashSet<String>()

    private fun hookDexDiscoveredBiographyClasses(): Int {
        val persisted = if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadString("CopyBio_Classes")
        } else null
        if (!persisted.isNullOrBlank()) {
            val classNames = persisted.split('\u0000').filter { it.isNotBlank() }
            return classNames.sumOf { hookBiographyStringMethods(it, exactOnly = false) }
        }
        if (copyBioClassesCached) {
            return copyBioCachedClassNames.sumOf { hookBiographyStringMethods(it, exactOnly = false) }
        }
        var hooked = 0
        val seen = HashSet<String>()
        arrayOf("biography", "biography_with_entities", "profile_header_bio").forEach { marker ->
            dexBridge.findClassNamesUsingStrings(marker).forEach { className ->
                if (!seen.add(className)) return@forEach
                hooked += hookBiographyStringMethods(className, exactOnly = false)
            }
        }
        copyBioClassesCached = true
        copyBioCachedClassNames.addAll(seen)
        if (seen.isNotEmpty()) {
            InstagramDexKitCache.saveString("CopyBio_Classes", seen.joinToString("\u0000"))
        }
        return hooked
    }

    private fun hookBiographyStringMethods(className: String, exactOnly: Boolean): Int {
        val cls = runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() ?: return 0
        var hooked = 0
        cls.declaredMethods.forEach { method ->
            if (method.parameterTypes.isNotEmpty() || method.returnType != String::class.java) return@forEach
            if (exactOnly && method.name != "BCv") return@forEach
            if (!exactOnly && !looksLikeBiographyGetterMethod(cls, method)) return@forEach
            val signature = "${cls.name}.${method.name}:copy_bio_getter"
            if (!hookedDexMethods.add(signature)) return@forEach
            method.isAccessible = true
            XposedBridge.hookMethod(
                method,
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableCopyBio) return
                        val bio = (param.result as? String)?.trim().orEmpty()
                        if (!isReliableBioText(bio)) return
                        rememberBioText(findUsernameOnModel(param.thisObject), bio)
                    }
                }
            )
            hooked++
        }
        return hooked
    }

    private fun hookBiographyHashMethods(): Int {
        var hooked = 0
        dexBridge.findMethodsUsingNumbers(BIOGRAPHY_HASH).forEach { method ->
            if (method.returnType != String::class.java && method.returnType != Any::class.java) return@forEach
            val signature = "${method.declaringClass.name}.${method.name}:copy_bio_hash"
            if (!hookedDexMethods.add(signature)) return@forEach
            method.isAccessible = true
            XposedBridge.hookMethod(
                method,
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableCopyBio) return
                        val bio = (param.result as? String)?.trim().orEmpty()
                        if (bio.isBlank() || isNeverBioText(bio.lowercase(Locale.US))) return
                        val model = param.thisObject ?: param.args?.firstOrNull()
                        rememberExactBioText(findUsernameOnModel(model), bio, "hash:${method.name}")
                    }
                }
            )
            hooked++
        }
        return hooked
    }

    private fun hookProfileActionSheetControllers(): Int {
        var hooked = 0
        dexBridge.findClassNamesUsingStrings("copy_profile_url").forEach { className ->
            val cls = runCatching { Class.forName(className, false, appClassLoader) }.getOrNull() ?: return@forEach
            runCatching {
                XposedBridge.hookAllConstructors(
                    cls,
                    object : XC_MethodHook() {
                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            if (state.enableCopyBio || state.showFollowerToast) rememberProfileControllerUser(param.thisObject)
                        }
                    }
                )
            }
            cls.declaredMethods.filter { it.parameterTypes.size <= 3 }.forEach { method ->
                val signature = "${cls.name}.${method.name}:copy_bio_controller"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (state.enableCopyBio || state.showFollowerToast) rememberProfileControllerUser(param.thisObject)
                        }
                    }
                )
            }
            hooked++
        }
        return hooked
    }

    private fun rememberProfileControllerUser(controller: Any?) {
        val user = findInstagramUserObject(controller) ?: return
        val username = extractUsernameFromUser(user)
        if (state.showFollowerToast) rememberFollowDisplayName(user, username)
        val bio = extractBiographyFromUser(user)?.trim().orEmpty()
        if (bio.isBlank() || isNeverBioText(bio.lowercase(Locale.US))) return
        rememberBioText(username, bio)
        currentProfileBioText = bio
        currentProfileUsername = normalizeUsername(username).ifBlank { null }
        currentProfileBioAtMs = System.currentTimeMillis()
    }

    private fun findInstagramUserObject(owner: Any?): Any? {
        if (owner == null) return null
        if (owner.javaClass.name == "com.instagram.user.model.User") return owner
        var cls: Class<*>? = owner.javaClass
        var checked = 0
        while (cls != null && cls != Any::class.java && checked < 80) {
            cls.declaredFields.forEach { field ->
                if (checked++ >= 80) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(owner)
                    if (value?.javaClass?.name == "com.instagram.user.model.User") return value
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun extractUsernameFromUser(user: Any?): String? {
        if (user != null && (userClass?.isInstance(user) == true || user.javaClass.name == "com.instagram.user.model.User")) {
            userUsernameGetter?.let { getter ->
                runCatching { getter.invoke(user) as? String }
                    .getOrNull()
                    ?.takeIf { normalizeUsername(it).isNotBlank() }
                    ?.let { return it }
            }
        }
        invokeStringNoArg(user, "getUsername")?.takeIf { normalizeUsername(it).isNotBlank() }?.let { return it }
        return findUsernameOnModel(userDict(user))
    }

    private fun extractBiographyFromUser(user: Any?): String? {
        val dict = userDict(user)
        invokeStringNoArg(dict, "BCv")?.let { return it }
        return invokeBiographyByHash(dict)
    }

    private fun userDict(user: Any?): Any? {
        if (user == null) return null
        return runCatching {
            val field = user.javaClass.getDeclaredField("A00")
            field.isAccessible = true
            field.get(user)
        }.getOrNull()
    }

    private fun invokeBiographyByHash(dict: Any?): String? {
        if (dict == null) return null
        var cls: Class<*>? = dict.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredMethods.forEach { method ->
                runCatching {
                    val params = method.parameterTypes
                    method.isAccessible = true
                    val value = when {
                        Modifier.isStatic(method.modifiers) &&
                            params.size == 2 &&
                            params[0].isAssignableFrom(dict.javaClass) &&
                            params[1] == java.lang.Integer.TYPE &&
                            (method.returnType == Any::class.java || method.returnType == String::class.java) ->
                            method.invoke(null, dict, BIOGRAPHY_HASH)
                        !Modifier.isStatic(method.modifiers) &&
                            params.size == 1 &&
                            params[0] == java.lang.Integer.TYPE &&
                            (method.returnType == Any::class.java || method.returnType == String::class.java) ->
                            method.invoke(dict, BIOGRAPHY_HASH)
                        else -> null
                    }
                    if (value is String) return value
                }
            }
            cls = cls.superclass
        }
        cls = dict.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                runCatching {
                    field.isAccessible = true
                    val value = field.get(dict) ?: return@forEach
                    val getter = value.javaClass.getMethod("getOptionalStringValueByHashCode", java.lang.Integer.TYPE)
                    (getter.invoke(value, BIOGRAPHY_HASH) as? String)?.let { return it }
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun maybeInstallCopyBioLongPress(textView: TextView) {
        if (!isProfileBioText(textView)) return
        rememberBioText(null, textView.text)
        synchronized(copyBioHookedTextViews) {
            if (!copyBioHookedTextViews.add(textView)) return
        }
        textView.isLongClickable = true
        textView.setOnLongClickListener { view ->
            val text = (view as? TextView)?.text?.toString()?.trim().orEmpty()
            if (text.isBlank()) return@setOnLongClickListener false
            copyTextToClipboard(view.context, "Instagram bio", text, "Bio copied")
            true
        }
    }

    private fun maybeRememberProfileBioCandidate(textView: TextView) {
        val text = textView.text?.toString()?.trim().orEmpty()
        if (text.isBlank() || isNeverBioText(text.lowercase(Locale.US))) return
        val name = resourceEntryName(textView).orEmpty()
        val exactBioId = name == "profile_header_bio_text" ||
            name == "pbia_profile_header_bio" ||
            name == "biography" ||
            (name.contains("profile", ignoreCase = true) && name.contains("bio", ignoreCase = true))
        val score = scoreBioCandidate(textView.rootView, textView, text)
        val likelyBio = isReliableBioText(text) && (exactBioId || score >= 45 || (hasProfileBioAncestor(textView) && score >= 25))
        if (!likelyBio) return
        rememberBioText(findVisibleProfileUsername(textView.rootView), text)
    }

    private fun maybeInjectProfileMenuCopyBio(anchor: TextView) {
        val text = anchor.text?.toString()?.trim().orEmpty()
        if (!text.equals("Copy profile URL", ignoreCase = true) && !text.equals("Copy profile url", ignoreCase = true)) return
        synchronized(copyBioProfileMenuRows) { copyBioProfileMenuRows.add(anchor) }
        rememberVisibleBio(anchor.rootView)
        copyBioMenuActiveUntilMs = System.currentTimeMillis() + 120_000L
        anchor.text = "Copy bio"
        anchor.isLongClickable = false
        val row = findMenuActionRow(anchor)
        val action = View.OnClickListener { view -> copyVisibleBio(view.context, anchor.rootView) }
        anchor.setOnClickListener(action)
        row?.takeIf { it !== anchor }?.let {
            it.isClickable = true
            it.setOnClickListener(action)
        }
    }

    private fun handleCopyBioMenuClick(view: View): Boolean {
        if (!state.enableCopyBio || handlingCopyBioMenuClick.get()) return false
        if (!isCopyBioProfileMenuClickTarget(view)) return false
        handlingCopyBioMenuClick.set(true)
        return try {
            copyBioMenuActiveUntilMs = System.currentTimeMillis() + 120_000L
            rememberVisibleBio(view.rootView)
            copyVisibleBio(view.context, view.rootView)
            true
        } finally {
            handlingCopyBioMenuClick.set(false)
        }
    }

    private fun copyVisibleBio(context: Context, root: View?) {
        val bio = bestKnownBioForRoot(root)
        if (!isReliableBioText(bio)) {
            Toast.makeText(context, "No bio found", Toast.LENGTH_SHORT).show()
            return
        }
        copyTextToClipboard(context, "Instagram bio", bio, "Bio copied")
    }

    private fun bestKnownBioForRoot(root: View?): String {
        val searchRoot = bestProfileSearchRoot(root)
        rememberVisibleBio(searchRoot)
        val visibleUsername = findVisibleProfileUsername(searchRoot)
        val current = currentProfileBioText?.takeIf { System.currentTimeMillis() - currentProfileBioAtMs < 5 * 60_000L }
        val currentUser = currentProfileUsername
        if (isReliableBioText(current) &&
            (visibleUsername == null || currentUser == null || currentUser == normalizeUsername(visibleUsername))
        ) {
            return current!!.trim()
        }
        val visible = scanVisibleBioText(searchRoot)
        if (isReliableBioText(visible)) return visible.trim()
        val cached = normalizeUsername(visibleUsername).takeIf { it.isNotBlank() }?.let { recentBiosByUsername[it] }
        if (isReliableBioText(cached)) return cached!!.trim()
        if (lastSeenBioUsername != null &&
            visibleUsername != null &&
            lastSeenBioUsername == normalizeUsername(visibleUsername) &&
            isReliableBioText(lastSeenBioText)
        ) {
            return lastSeenBioText!!.trim()
        }
        return ""
    }

    private fun rememberVisibleBio(root: View?) {
        val searchRoot = bestProfileSearchRoot(root)
        val bio = scanVisibleBioText(searchRoot)
        if (isReliableBioText(bio)) rememberBioText(findVisibleProfileUsername(searchRoot), bio)
    }

    private fun bestProfileSearchRoot(root: View?): View? {
        val decor = currentActivity?.window?.decorView
        if (decor != null && (root == null || decor === root || decor.height >= root.height)) return decor
        return root
    }

    private fun scanVisibleBioText(root: View?): String {
        if (root == null) return ""
        val best = BioCandidate("", Int.MIN_VALUE)
        var visited = 0
        fun visit(view: View) {
            if (visited++ > 600) return
            if (view is TextView) {
                val text = view.text?.toString()?.trim().orEmpty()
                val score = scoreBioCandidate(root, view, text)
                if (score > best.score) {
                    best.text = text
                    best.score = score
                }
            }
            if (view is ViewGroup) for (i in 0 until view.childCount) visit(view.getChildAt(i))
        }
        visit(root)
        return if (best.score >= 45 && isReliableBioText(best.text)) best.text else ""
    }

    private fun isProfileBioText(textView: TextView): Boolean {
        val text = textView.text?.toString()?.trim().orEmpty()
        val name = resourceEntryName(textView).orEmpty().lowercase(Locale.US)
        if (name.contains("translation") || name.contains("translate")) return false
        if (isNeverBioText(text.lowercase(Locale.US))) return false
        if (name == "profile_header_bio_text" ||
            name == "pbia_profile_header_bio" ||
            name == "biography" ||
            (name.contains("profile") && name.contains("bio"))
        ) {
            return text.isNotBlank()
        }
        if (text.length < 2 || text.length > 300) return false
        if (text.startsWith("@")) return false
        return name.contains("bio") && hasProfileBioAncestor(textView)
    }

    private fun hasProfileBioAncestor(view: View): Boolean {
        var current: View? = view
        repeat(8) {
            val hay = "${current?.let { resourceEntryName(it) }.orEmpty()} ${current?.javaClass?.name.orEmpty()}".lowercase(Locale.US)
            if ((hay.contains("profile") && hay.contains("bio")) ||
                hay.contains("profile_header") ||
                hay.contains("pbia_profile") ||
                hay.contains("user_profile_header")
            ) {
                return true
            }
            current = current?.parent as? View
        }
        return false
    }

    private fun findVisibleProfileUsername(root: View?): String? {
        if (root == null) return null
        val best = UsernameCandidate(null, Int.MIN_VALUE)
        var visited = 0
        fun visit(view: View) {
            if (visited++ > 700) return
            if (view is TextView) {
                val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
                val raw = view.text?.toString()?.trim().orEmpty()
                val username = normalizeUsername(raw)
                if (username.isNotBlank() && raw.length <= 64) {
                    var score = 0
                    if (name.contains("username")) score += 80
                    if (name.contains("profile_header") || name.contains("action_bar")) score += 35
                    if (raw.startsWith("@")) score += 20
                    if (hasProfileBioAncestor(view)) score += 10
                    if (raw.contains(" ")) score -= 60
                    runCatching {
                        val loc = IntArray(2)
                        view.getLocationOnScreen(loc)
                        if (loc[1] < maxOf(240, (view.rootView.height * 0.35f).roundToInt())) score += 20
                    }
                    if (score > best.score) {
                        best.username = username
                        best.score = score
                    }
                }
            }
            if (view is ViewGroup) for (i in 0 until view.childCount) visit(view.getChildAt(i))
        }
        visit(root)
        return best.username?.takeIf { best.score >= 15 }
    }

    private fun rememberBioText(username: String?, bioValue: CharSequence?) {
        val bio = bioValue?.toString()?.trim().orEmpty()
        if (!isReliableBioText(bio)) return
        lastSeenBioText = bio
        val cleanUser = normalizeUsername(username)
        if (cleanUser.isNotBlank()) {
            lastSeenBioUsername = cleanUser
            recentBiosByUsername[cleanUser] = bio
        }
        if (copyBioLogCount++ < 12) logInfo("Cached Instagram bio${cleanUser.takeIf { it.isNotBlank() }?.let { " for @$it" }.orEmpty()}")
    }

    private fun rememberExactBioText(username: String?, bioValue: CharSequence?, source: String) {
        val bio = bioValue?.toString()?.trim().orEmpty()
        if (bio.isBlank() || isNeverBioText(bio.lowercase(Locale.US))) return
        lastSeenBioText = bio
        val cleanUser = normalizeUsername(username)
        if (cleanUser.isNotBlank()) {
            lastSeenBioUsername = cleanUser
            recentBiosByUsername[cleanUser] = bio
        }
        if (copyBioLogCount++ < 20) logInfo("Cached exact Instagram bio source=$source${cleanUser.takeIf { it.isNotBlank() }?.let { " for @$it" }.orEmpty()}")
    }

    private fun findUsernameOnModel(model: Any?): String? {
        if (model == null) return null
        arrayOf("getUsername", "DJy", "BKR", "A0r").forEach { methodName ->
            val value = invokeStringNoArg(model, methodName)
            if (normalizeUsername(value).isNotBlank()) return value
        }
        var cls: Class<*>? = model.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 3) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.type != String::class.java) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(model) as? String
                    if (normalizeUsername(value).isNotBlank() && field.name.lowercase(Locale.US).contains("user")) return value
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun invokeStringNoArg(target: Any?, methodName: String): String? {
        val value = invokeNoArgDeep(target, methodName)
        return value as? String
    }

    private fun looksLikeBiographyGetterMethod(cls: Class<*>, method: Method): Boolean {
        val hay = "${cls.name} ${method.name}".lowercase(Locale.US)
        return hay.contains("biograph") || hay.contains("profile_header_bio") || hay.contains("bio_text")
    }

    private fun isReliableBioText(value: String?): Boolean {
        val text = value?.trim().orEmpty()
        if (text.length < 2 || text.length > 500) return false
        val lower = text.lowercase(Locale.US)
        if (isNeverBioText(lower)) return false
        if (looksLikeLinkOnly(text) || looksLikeDisplayNameOnly(text)) return false
        return looksLikeBioContent(text)
    }

    private fun scoreBioCandidate(root: View?, textView: TextView, value: String?): Int {
        val text = value?.trim().orEmpty()
        if (text.length < 2 || text.length > 500) return Int.MIN_VALUE
        val lower = text.lowercase(Locale.US)
        if (isNeverBioText(lower)) return Int.MIN_VALUE
        val name = resourceEntryName(textView).orEmpty().lowercase(Locale.US)
        val exactBioId = name.contains("bio") || name.contains("biography")
        if (!exactBioId) return Int.MIN_VALUE
        if (looksLikeLinkOnly(text)) return Int.MIN_VALUE

        var score = 120
        if (hasProfileBioAncestor(textView)) score += 35
        if (text.contains('\n')) score += 45
        if (lower.contains("@") || lower.contains("http") || lower.contains("linktr") ||
            lower.contains(".com") || lower.contains("mail")
        ) {
            score += 12
        }
        if (text.contains(" ") || text.contains(":")) score += 15
        score += minOf(30, text.length / 4)
        runCatching {
            val loc = IntArray(2)
            textView.getLocationOnScreen(loc)
            val rootHeight = root?.height ?: textView.rootView?.height ?: 0
            if (rootHeight > 0 && loc[1] > rootHeight * 0.58f) score -= 120
            if (rootHeight > 0 && loc[1] < rootHeight * 0.08f) score -= 40
        }
        return score
    }

    private fun looksLikeLinkOnly(value: String?): Boolean {
        val text = value?.trim().orEmpty()
        if (text.isBlank() || text.contains('\n')) return false
        val compact = text.lowercase(Locale.US).replace(" ", "")
        val urlish = compact.startsWith("http://") ||
            compact.startsWith("https://") ||
            compact.startsWith("www.") ||
            compact.startsWith("linktr.ee/") ||
            compact.contains("instagram.com/") ||
            compact.contains("youtube.com/") ||
            compact.contains("youtu.be/") ||
            compact.contains(".com/") ||
            compact.endsWith(".com") ||
            compact.contains(".in/") ||
            compact.endsWith(".in")
        val emailish = compact.matches(emailPattern)
        return (urlish || emailish) && text.split(whitespacePattern).size <= 2
    }

    private fun looksLikeDisplayNameOnly(value: String?): Boolean {
        val text = value?.trim().orEmpty()
        if (text.length < 2 || text.length > 48) return false
        val lower = text.lowercase(Locale.US)
        if (text.contains('\n') || lower.contains("@") || lower.contains("http")) return false
        if (text.contains("|") || text.contains(":") || text.contains("/") || text.contains("&")) return false
        if (text.split(whitespacePattern).size > 2) return false
        if (text.any { it.isDigit() }) return false
        var offset = 0
        while (offset < text.length) {
            val codePoint = text.codePointAt(offset)
            val type = Character.getType(codePoint)
            if (type == Character.OTHER_SYMBOL.toInt() || type == Character.MATH_SYMBOL.toInt()) return false
            offset += Character.charCount(codePoint)
        }
        return text.matches(displayNamePattern)
    }

    private fun looksLikeBioContent(value: String?): Boolean {
        val text = value?.trim().orEmpty()
        if (text.length < 2 || text.length > 500) return false
        val lower = text.lowercase(Locale.US)
        if (isNeverBioText(lower) || looksLikeLinkOnly(text) || looksLikeDisplayNameOnly(text)) return false
        if (text.contains('\n')) return true
        if (text.split(whitespacePattern).size >= 3) return true
        if (text.contains("|") || text.contains(":") || text.contains("/") || text.contains("&")) return true
        var offset = 0
        while (offset < text.length) {
            val codePoint = text.codePointAt(offset)
            val type = Character.getType(codePoint)
            if (type == Character.OTHER_SYMBOL.toInt() || type == Character.MATH_SYMBOL.toInt()) return true
            offset += Character.charCount(codePoint)
        }
        return false
    }

    private fun isNeverBioText(lower: String): Boolean {
        if (lower.isBlank()) return true
        if (lower.matches(Regex("@?\\d{6,}"))) return true
        if (lower.contains("translation")) return true
        return lower == "copy bio" ||
            lower == "copy profile url" ||
            lower == "copy profile link" ||
            lower == "edit profile" ||
            lower == "message" ||
            lower == "follow" ||
            lower == "following" ||
            lower == "id" ||
            lower == "posts" ||
            lower == "followers" ||
            lower == "restrict" ||
            lower == "block" ||
            lower == "report" ||
            lower == "about this account" ||
            lower == "hide your story" ||
            lower == "share this profile" ||
            lower == "qr code" ||
            lower == "add your bio" ||
            lower == "see translation" ||
            lower == "view translation" ||
            lower == "translate" ||
            lower == "original" ||
            lower.matches(Regex("\\d+(\\.\\d+)?[km]?")) ||
            lower.endsWith(" posts") ||
            lower.endsWith(" followers") ||
            lower.endsWith(" following") ||
            lower.contains("followers") ||
            lower.contains("following") ||
            lower.contains("posts")
    }

    private fun normalizeUsername(value: String?): String {
        val clean = value?.trim()?.removePrefix("@").orEmpty()
        if (clean.length !in 2..30) return ""
        if (!clean.matches(Regex("[A-Za-z0-9._]+"))) return ""
        val lower = clean.lowercase(Locale.US)
        if (lower == "id" || isNeverBioText(lower)) return ""
        return if (lower == "instagram" || lower == "meta") lower else lower
    }

    private fun findMenuActionRow(child: View): View? {
        var current: View? = child
        var best: View? = child
        repeat(8) {
            val parent = current?.parent as? View ?: return best
            if (parent.javaClass.name.contains("RecyclerView")) return current
            best = parent
            current = parent
        }
        return best
    }

    private fun isCopyBioProfileMenuClickTarget(view: View): Boolean {
        if (!containsExactText(view, "copy bio", 0, intArrayOf(0))) return false
        var current: View? = view
        repeat(7) {
            val hay = "${current?.javaClass?.name.orEmpty()} ${current?.let { resourceEntryName(it) }.orEmpty()}".lowercase(Locale.US)
            if (hay.contains("recyclerview") || hay.contains("action_sheet") || hay.contains("menu") || hay.contains("sheet")) return true
            current = current?.parent as? View
        }
        return false
    }

    private fun containsExactText(view: View?, lowerNeedle: String, depth: Int, visited: IntArray): Boolean {
        if (view == null || depth > 5 || visited[0]++ > 120) return false
        if (view is TextView && view.text?.toString()?.trim()?.lowercase(Locale.US) == lowerNeedle) return true
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) if (containsExactText(view.getChildAt(i), lowerNeedle, depth + 1, visited)) return true
        }
        return false
    }

    private fun rewriteCopyBioClipData(clip: ClipData): ClipData? {
        if (!state.enableCopyBio || System.currentTimeMillis() > copyBioMenuActiveUntilMs || !looksLikeInstagramProfileUrlClip(clip)) return null
        val bio = lastSeenBioText?.trim().orEmpty()
        if (!isReliableBioText(bio)) return null
        return ClipData.newPlainText("Instagram bio", bio)
    }

    private fun looksLikeInstagramProfileUrlClip(clip: ClipData): Boolean {
        for (i in 0 until clip.itemCount) {
            val item = clip.getItemAt(i)
            if (looksLikeInstagramProfileUrl(item.text?.toString()) || looksLikeInstagramProfileUrl(item.uri?.toString())) return true
        }
        return false
    }

    private fun looksLikeInstagramProfileUrl(value: String?): Boolean {
        val text = value?.trim().orEmpty()
        if (!text.contains("instagram.com/")) return false
        val uri = runCatching { Uri.parse(text) }.getOrNull() ?: return false
        val host = uri.host?.lowercase(Locale.US).orEmpty()
        if (!host.endsWith("instagram.com")) return false
        val segments = uri.pathSegments.orEmpty().filter { it.isNotBlank() }
        return segments.size == 1 && normalizeUsername(segments[0]).isNotBlank()
    }

    private fun installCommentCopyLongPressHooks() {
        runSafe("Copy comment long-press hook") {
            val hook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (!state.enableCopyComment) return
                    val text = extractCommentText(param.thisObject)?.trim().orEmpty()
                    if (text.isBlank()) return
                    val context = currentActivity ?: return
                    showCommentCopyPopup(context, text)
                }
            }
            if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethods("CommentCopy_LongPress", appClassLoader)
                    ?.takeIf { it.isNotEmpty() }
                    ?.let { cached ->
                        cached.forEach { method ->
                            val signature = "${methodKey(method)}:copy_comment_cached"
                            if (hookedDexMethods.add(signature)) XposedBridge.hookMethod(method, hook)
                        }
                        logInfo("Installed cached copy-comment long-press hooks=${cached.size}")
                        return@runSafe
                    }
            }
            val classFallbacks = dexBridge.findClassNamesUsingStrings("fb_comment_long_press")
                .flatMap { className ->
                    runCatching { Class.forName(className, false, appClassLoader).declaredMethods.toList() }
                        .getOrDefault(emptyList())
                }
            val candidates = (dexBridge.findMethodsUsingStrings("fb_comment_long_press") +
                dexBridge.findMethodsUsingStrings("comment_row_component") +
                classFallbacks)
                .filter { it.name == "onLongPress" }
                .distinctBy(::methodKey)
            var hooked = 0
            candidates.forEach { method ->
                val signature = "${method.declaringClass.name}.${method.name}:copy_comment"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(method, hook)
                hooked++
            }
            if (candidates.isNotEmpty()) InstagramDexKitCache.saveMethods("CommentCopy_LongPress", candidates)
            logInfo("Installed copy-comment long-press hooks=$hooked")
        }
    }

    private fun extractCommentText(gestureListener: Any?): String? {
        if (gestureListener == null) return null
        if (InstagramDexKitCache.isCacheValid()) {
            val itemClass = InstagramDexKitCache.loadString("CommentCopy_ItemClass_v3")
            val textField = InstagramDexKitCache.loadString("CommentCopy_TextField_v3")
            if (!itemClass.isNullOrBlank() && !textField.isNullOrBlank()) {
                runCatching {
                    val item = findCommentItemByClass(gestureListener, itemClass) ?: return@runCatching null
                    if (!looksLikeCommentCopyItem(item)) return@runCatching null
                    val field = item.javaClass.getDeclaredField(textField)
                    field.isAccessible = true
                    (field.get(item) as? String)?.takeIf { isLikelyReadableCommentText(it) }
                }.getOrNull()?.let { return it }
            }
        }
        return discoverCommentText(gestureListener)
    }

    private fun findCommentItemByClass(gestureListener: Any, targetClassName: String): Any? {
        gestureListener.javaClass.declaredFields.forEach { first ->
            if (!isObfuscatedObjectField(first)) return@forEach
            runCatching {
                first.isAccessible = true
                val holder = first.get(gestureListener) ?: return@forEach
                holder.javaClass.declaredFields.forEach { second ->
                    if (!isObfuscatedObjectField(second)) return@forEach
                    runCatching {
                        second.isAccessible = true
                        val item = second.get(holder)
                        if (item != null && item.javaClass.name == targetClassName) return item
                    }
                }
            }
        }
        return null
    }

    private fun discoverCommentText(gestureListener: Any): String? {
        val userClass = runCatching { Class.forName("com.instagram.user.model.User", false, gestureListener.javaClass.classLoader) }.getOrNull()
        gestureListener.javaClass.declaredFields.forEach { first ->
            if (!isObfuscatedObjectField(first)) return@forEach
            runCatching {
                first.isAccessible = true
                val holder = first.get(gestureListener) ?: return@forEach
                holder.javaClass.declaredFields.forEach { second ->
                    if (!isObfuscatedObjectField(second)) return@forEach
                    runCatching {
                        second.isAccessible = true
                        val item = second.get(holder) ?: return@forEach
                        if (userClass != null && !hasFieldOfType(item.javaClass, userClass)) return@forEach
                        if (!looksLikeCommentCopyItem(item)) return@forEach
                        val (fieldName, text) = findBestCommentTextField(item) ?: return@forEach
                        InstagramDexKitCache.saveString("CommentCopy_ItemClass_v3", item.javaClass.name)
                        InstagramDexKitCache.saveString("CommentCopy_TextField_v3", fieldName)
                        logInfo("Copy comment cached ${item.javaClass.name}.$fieldName")
                        return text
                    }
                }
            }
        }
        return null
    }

    private fun looksLikeCommentCopyItem(item: Any): Boolean {
        val cls = item.javaClass
        val name = cls.name.lowercase(Locale.US)
        if (name.contains("media") || name.contains("feed")) return false
        if (hasFieldTypeName(cls, "com.instagram.feed.media.Media")) return false
        if (hasFieldTypeName(cls, "com.instagram.model.mediasize.ExtendedImageUrl")) return false
        if (hasFieldTypeName(cls, "com.instagram.common.typedurl.ImageUrl")) return false
        return true
    }

    private fun findBestCommentTextField(item: Any): Pair<String, String>? {
        var bestName: String? = null
        var bestValue: String? = null
        item.javaClass.declaredFields.forEach { field ->
            if (field.type != String::class.java) return@forEach
            runCatching {
                field.isAccessible = true
                val value = (field.get(item) as? String)?.trim().orEmpty()
                if (!isLikelyReadableCommentText(value)) return@forEach
                if (bestValue == null || value.length > bestValue!!.length) {
                    bestName = field.name
                    bestValue = value
                }
            }
        }
        return bestName?.let { name -> bestValue?.let { value -> name to value } }
    }

    private fun isLikelyReadableCommentText(value: String): Boolean {
        val text = value.trim()
        if (text.isBlank()) return false
        if (text.matches(Regex("\\d+"))) return false
        if (text.matches(Regex("\\d+_\\d+"))) return false
        if (text.startsWith("http", ignoreCase = true)) return false
        if (text.startsWith("{") || text.startsWith("[") || text.contains("\"__typename\"")) return false
        if (text.any { it.code in 0x00..0x08 || it.code in 0x0E..0x1F }) return false
        val compact = text.filterNot(Char::isWhitespace)
        if (compact.length >= 48 && compact.all { it.isLetterOrDigit() || it == '+' || it == '/' || it == '=' || it == '_' || it == '-' }) {
            return false
        }
        if (compact.length >= 32 && compact.all { it in '0'..'9' || it.lowercaseChar() in 'a'..'f' }) return false
        val readable = text.count { it.isLetterOrDigit() || it.isWhitespace() || Character.getType(it) == Character.OTHER_SYMBOL.toInt() }
        return readable >= (text.length * 0.45f).roundToInt().coerceAtLeast(1)
    }

    private fun isObfuscatedObjectField(field: Field): Boolean {
        val type = field.type
        if (type.isPrimitive || type == String::class.java) return false
        val name = type.name
        return !name.startsWith("android.") && !name.startsWith("java.") && !name.startsWith("kotlin.") && !name.startsWith("androidx.")
    }

    private fun hasFieldOfType(cls: Class<*>, target: Class<*>): Boolean {
        return cls.declaredFields.any { target.isAssignableFrom(it.type) }
    }

    private fun hasFieldTypeName(cls: Class<*>, targetTypeName: String): Boolean {
        var current: Class<*>? = cls
        while (current != null && current != Any::class.java) {
            if (current.declaredFields.any { field -> field.type.name == targetTypeName }) return true
            current = current.superclass
        }
        return false
    }

    private fun showCommentCopyPopup(context: Context, text: String) {
        mainHandler.post {
            runCatching {
                AlertDialog.Builder(context)
                    .setTitle("Copy Comment")
                    .setMessage(text)
                    .setPositiveButton("Copy") { _, _ -> copyTextToClipboard(context, "comment", text, "Comment copied") }
                    .setNeutralButton("Select") { _, _ -> showCommentSelectDialog(context, text) }
                    .show()
            }.onFailure { logError("Copy comment popup failed", it) }
        }
    }

    private fun showCommentSelectDialog(context: Context, text: String) {
        val input = EditText(context).apply {
            setText(text)
            setTextIsSelectable(true)
            isFocusableInTouchMode = true
            setSelection(0, text.length)
            minLines = 3
            maxLines = 8
        }
        AlertDialog.Builder(context)
            .setTitle("Select Comment")
            .setView(input)
            .setPositiveButton("Copy Selected") { _, _ ->
                val start = input.selectionStart.coerceAtLeast(0)
                val end = input.selectionEnd.coerceAtLeast(0)
                val selected = if (end > start) text.substring(start, end) else text
                copyTextToClipboard(context, "comment", selected, "Comment copied")
            }
            .setNeutralButton("Copy All") { _, _ -> copyTextToClipboard(context, "comment", text, "Comment copied") }
            .show()
    }

    private fun copyTextToClipboard(context: Context, label: String, text: String, toast: String) {
        val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as? ClipboardManager ?: return
        clipboard.setPrimaryClip(ClipData.newPlainText(label, text))
        Toast.makeText(context, toast, Toast.LENGTH_SHORT).show()
    }

    private fun collectRemoveOperationIds(operations: List<*>): Set<String> {
        val ids = HashSet<String>()
        operations.forEach { operation ->
            if (isLikelyRemoveMessageOperation(operation)) ids += collectStringFields(operation)
        }
        return ids
    }

    private fun collectRealtimeRemoveIds(args: Array<Any?>?): Set<String> {
        if (args == null || !containsStringFieldValue(args.getOrNull(1), "remove")) return emptySet()
        val ids = HashSet<String>()
        args.forEach { arg ->
            if (arg is Map<*, *>) {
                arg.values.filterIsInstance<String>().forEach { addUsefulId(it, ids) }
            }
        }
        return ids
    }

    private fun rememberScopedDeleteIds(param: XC_MethodHook.MethodHookParam<*>, deleteIds: Set<String>) {
        val previous = remoteDeleteIds.get()
        param.setObjectExtra("ie_keep_unsent_has_scoped_delete_ids", true)
        param.setObjectExtra("ie_keep_unsent_previous_delete_ids", previous)
        remoteDeleteIds.set((previous.orEmpty() + deleteIds).toSet())
    }

    @Suppress("UNCHECKED_CAST")
    private fun restoreScopedDeleteIds(param: XC_MethodHook.MethodHookParam<*>) {
        if (param.getObjectExtra("ie_keep_unsent_has_scoped_delete_ids") != true) return
        val previous = param.getObjectExtra("ie_keep_unsent_previous_delete_ids") as? Set<String>
        if (previous != null) remoteDeleteIds.set(previous) else remoteDeleteIds.remove()
    }

    private fun isScopedRemoteDelete(args: Array<Any?>?): Boolean {
        val ids = remoteDeleteIds.get().orEmpty()
        if (ids.isEmpty() || args == null) return false
        return args.any { it is String && ids.contains(it.trim()) }
    }

    private fun collectStringFields(target: Any?): Set<String> {
        val ids = HashSet<String>()
        if (target == null) return ids
        var cls: Class<*>? = target.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type != String::class.java) return@forEach
                runCatching {
                    field.isAccessible = true
                    addUsefulId(field.get(target) as? String, ids)
                }
            }
            cls = cls.superclass
        }
        return ids
    }

    private fun collectUsefulIdsDeep(target: Any?): Set<String> {
        val ids = HashSet<String>()
        collectUsefulIdsDeep(target, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        return ids
    }

    private fun collectUsefulIdsDeep(target: Any?, out: MutableSet<String>, seen: MutableSet<Any>, depth: Int) {
        if (target == null || depth > 3) return
        when (target) {
            is String -> {
                addUsefulId(target, out)
                return
            }
            is Array<*> -> {
                target.forEach { collectUsefulIdsDeep(it, out, seen, depth + 1) }
                return
            }
            is Iterable<*> -> {
                target.take(33).forEach { collectUsefulIdsDeep(it, out, seen, depth + 1) }
                return
            }
            is Map<*, *> -> {
                target.values.take(33).forEach { collectUsefulIdsDeep(it, out, seen, depth + 1) }
                return
            }
        }
        if (isPrimitiveLike(target) || !seen.add(target)) return
        var cls: Class<*>? = target.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type.isPrimitive) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(target) ?: return@forEach
                    if (value is String) addUsefulId(value, out) else if (!isPrimitiveLike(value)) {
                        collectUsefulIdsDeep(value, out, seen, depth + 1)
                    }
                }
            }
            cls = cls.superclass
        }
    }

    private fun rememberKeepUnsentDeletedIds(ids: Collection<String>, source: Any? = null) {
        logKeepUnsentDebug(
            "delete-event rawIds=${formatKeepUnsentIds(ids)} source=${source?.javaClass?.name.orEmpty()}"
        )
        val messageIds = extractDeletedMessageIds(ids)
        logKeepUnsentDebug("delete-event extractedIds=${formatKeepUnsentIds(messageIds)}")
        val deletedTexts = (collectKeepUnsentDeletedTexts(source) + recentKeepUnsentTextsForIds(messageIds))
            .mapNotNull(::normalizeKeepUnsentMessageText)
            .filter(::isPersistableKeepUnsentDeletedText)
            .distinct()
        logKeepUnsentDebug("delete-event extractedTexts=${formatKeepUnsentTexts(deletedTexts)}")
        if (messageIds.isEmpty() && deletedTexts.isEmpty()) {
            logKeepUnsentDebug("delete-event skipped: no trustworthy id or text")
            return
        }
        logInfo(
            "Keep-unsent delete event accepted ids=${formatKeepUnsentIds(messageIds)} " +
                "texts=${formatKeepUnsentTexts(deletedTexts)} source=${source?.javaClass?.name.orEmpty()}"
        )
        var added = 0
        val deletedAt = System.currentTimeMillis()
        if (messageIds.isNotEmpty()) {
            synchronized(keepUnsentDeletedIds) {
                messageIds.forEach { id ->
                    val key = id.trim()
                    if (!keepUnsentDeletedIds.containsKey(key)) added++
                    keepUnsentDeletedIds[key] = deletedAt
                }
            }
            if (added > 0) {
                markKeepUnsentPersistDirty(androidContext, "delete-ids")
                logInfo("Marked unsent Direct message ids: $added")
            }
        }
        if (deletedTexts.isNotEmpty()) {
            rememberKeepUnsentDeletedTexts(deletedTexts, deletedAt)
            decorateRecentKeepUnsentActionAnchor(deletedAt, messageIds, deletedTexts)
            decorateKeepUnsentTextRows(deletedTexts, deletedAt)
            scheduleKeepUnsentTextDecorationRetries(deletedTexts, deletedAt)
        }
        if (messageIds.isNotEmpty()) {
            rememberKeepUnsentTemporalDeleteCandidate(deletedAt)
            scanVisibleKeepUnsentRowsSoon("delete-event", 0L)
            scanVisibleKeepUnsentRowsSoon("delete-event-retry", 180L)
            decorateKeepUnsentBoundRows(messageIds)
            mainHandler.postDelayed({ decorateKeepUnsentBoundRows(messageIds) }, 220L)
            decorateRecentKeepUnsentActionAnchor(deletedAt, messageIds, deletedTexts)
            mainHandler.postDelayed({ decorateRecentKeepUnsentActionAnchor(deletedAt, messageIds, deletedTexts) }, 220L)
        }
    }

    private fun loadKeepUnsentDeletedIds(context: Context?) {
        if (keepUnsentPersistedLoaded || context == null) return
        synchronized(keepUnsentPersistLock) {
            if (keepUnsentPersistedLoaded) return
            runCatching {
                val app = context.applicationContext ?: context
                val savedPrefs = app.getSharedPreferences(KEEP_UNSENT_PREFS, Context.MODE_PRIVATE)
                val saved = savedPrefs.getStringSet(KEEP_UNSENT_PREF_IDS, null)
                saved.orEmpty().forEach { id ->
                    val parts = id.split("|", limit = 2)
                    val key = parts[0].trim()
                    val at = parts.getOrNull(1)?.toLongOrNull() ?: 0L
                    if (isMessageScopedId(key, allowNumeric = true)) keepUnsentDeletedIds[key] = at
                }
                val savedTexts = savedPrefs.getStringSet(KEEP_UNSENT_PREF_TEXTS, null)
                savedTexts.orEmpty().forEach { entry ->
                    runCatching {
                        val json = JSONObject(entry)
                        val text = normalizeKeepUnsentMessageText(json.optString("text"))
                        val at = json.optLong("at", 0L)
                        if (text != null && isPersistableKeepUnsentDeletedText(text) && at > 0L) keepUnsentDeletedTexts[text] = at
                    }
                }
                val savedTextsJson = savedPrefs.getString(KEEP_UNSENT_PREF_TEXTS_JSON, null)
                if (!savedTextsJson.isNullOrBlank()) {
                    runCatching {
                        val array = JSONArray(savedTextsJson)
                        for (i in 0 until array.length()) {
                            val json = array.optJSONObject(i) ?: continue
                            val text = normalizeKeepUnsentMessageText(json.optString("text"))
                            val at = json.optLong("at", 0L)
                            if (text != null && isPersistableKeepUnsentDeletedText(text) && at > 0L) keepUnsentDeletedTexts[text] = at
                        }
                    }
                }
                keepUnsentPersistedLoaded = true
                val idCount = synchronized(keepUnsentDeletedIds) { keepUnsentDeletedIds.size }
                val textCount = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts.size }
                logInfo("Keep-unsent persisted state loaded ids=$idCount texts=$textCount context=${context.packageName}")
            }.onFailure { logError("Failed loading unsent Direct ids", it) }
        }
    }

    private fun markKeepUnsentPersistDirty(context: Context?, reason: String) {
        synchronized(keepUnsentPersistLock) {
            keepUnsentPersistDirty = true
            keepUnsentPersistGeneration++
        }
        scheduleKeepUnsentPersistIfDirty(context, reason)
    }

    private fun persistKeepUnsentDeletedIds(context: Context?) {
        scheduleKeepUnsentPersistIfDirty(context, "legacy")
    }

    private fun scheduleKeepUnsentPersistIfDirty(context: Context?, reason: String) {
        if (context == null || !keepUnsentPersistDirty) return
        val app = context.applicationContext ?: context
        var generation = 0L
        var shouldSchedule = false
        synchronized(keepUnsentPersistLock) {
            if (keepUnsentPersistDirty && !keepUnsentPersistScheduled) {
                keepUnsentPersistScheduled = true
                generation = keepUnsentPersistGeneration
                shouldSchedule = true
            }
        }
        if (!shouldSchedule) return
        runCatching {
            keepUnsentPersistExecutor.execute {
                writeKeepUnsentPersistSnapshot(app, generation, reason)
            }
        }.onFailure { error ->
            synchronized(keepUnsentPersistLock) {
                keepUnsentPersistScheduled = false
            }
            logError("Failed scheduling keep-unsent Direct prefs persistence", error)
        }
    }

    private fun writeKeepUnsentPersistSnapshot(context: Context, generation: Long, reason: String) {
        var committed = false
        var idsCount = 0
        var textsCount = 0
        runCatching {
            val ids = synchronized(keepUnsentDeletedIds) {
                keepUnsentDeletedIds.entries.map { "${it.key}|${it.value}" }
            }
                .takeLast(MAX_KEEP_UNSENT_IDS)
                .filterTo(HashSet()) { isMessageScopedId(it.substringBefore("|"), allowNumeric = true) }
            val textEntries = synchronized(keepUnsentDeletedTexts) {
                keepUnsentDeletedTexts.entries.toList().takeLast(MAX_KEEP_UNSENT_IDS)
            }
            val texts = HashSet<String>()
            val textsJson = JSONArray()
            textEntries.forEach { entry ->
                val text = entry.key
                val at = entry.value
                if (isPersistableKeepUnsentDeletedText(text) && at > 0L) {
                    val json = JSONObject().put("text", text).put("at", at)
                    texts += json.toString()
                    textsJson.put(json)
                }
            }
            val ok = context.getSharedPreferences(KEEP_UNSENT_PREFS, Context.MODE_PRIVATE)
                .edit()
                .putStringSet(KEEP_UNSENT_PREF_IDS, ids)
                .putStringSet(KEEP_UNSENT_PREF_TEXTS, texts)
                .putString(KEEP_UNSENT_PREF_TEXTS_JSON, textsJson.toString())
                .commit()
            committed = ok
            idsCount = ids.size
            textsCount = texts.size
        }.onFailure { logError("Failed persisting unsent Direct ids", it) }

        var reschedule = false
        synchronized(keepUnsentPersistLock) {
            keepUnsentPersistScheduled = false
            if (committed && keepUnsentPersistGeneration == generation) {
                keepUnsentPersistDirty = false
            } else if (committed && keepUnsentPersistDirty) {
                reschedule = true
            }
        }
        if (committed) {
            logInfoThrottled("keep-unsent:prefs-commit", 2_500L) {
                "Keep-unsent prefs committed ids=$idsCount texts=$textsCount reason=$reason"
            }
        } else {
            logInfo("Failed committing unsent Direct prefs ids=$idsCount texts=$textsCount reason=$reason")
        }
        if (reschedule) scheduleKeepUnsentPersistIfDirty(context, "coalesced")
    }

    private fun persistKeepUnsentDeletedTextOnce(context: Context?, text: String, deletedAt: Long) {
        if (deletedAt <= 0L) return
        val normalized = normalizeKeepUnsentMessageText(text) ?: return
        if (!isPersistableKeepUnsentDeletedText(normalized)) return
        var changed = false
        synchronized(keepUnsentDeletedTexts) {
            if (keepUnsentDeletedTexts[normalized] != deletedAt) {
                keepUnsentDeletedTexts[normalized] = deletedAt
                changed = true
            }
        }
        val firstMarkerPersist = synchronized(keepUnsentRenderedMarkerPersistedTexts) {
            if (keepUnsentRenderedMarkerPersistedTexts.contains(normalized)) {
                false
            } else {
                keepUnsentRenderedMarkerPersistedTexts.add(normalized)
                while (keepUnsentRenderedMarkerPersistedTexts.size > MAX_KEEP_UNSENT_IDS) {
                    keepUnsentRenderedMarkerPersistedTexts.remove(keepUnsentRenderedMarkerPersistedTexts.first())
                }
                true
            }
        }
        if (changed || firstMarkerPersist) {
            logInfoThrottled("keep-unsent:text-persist-request", 1_500L) {
                "Keep-unsent text persist queued text=${formatKeepUnsentText(normalized)} at=$deletedAt context=${context?.packageName ?: "-"}"
            }
            markKeepUnsentPersistDirty(context, "text-marker")
        } else {
            scheduleKeepUnsentPersistIfDirty(context, "text-marker-dirty")
            logKeepUnsentDebug("persist-text skipped already queued text=${formatKeepUnsentText(normalized)}")
        }
    }

    private fun keepUnsentDeletedAt(ids: Set<String>): Long {
        val rowIds = extractRowBindableIds(ids).filterNot { keepUnsentAmbiguousBoundIds.contains(it) }.toSet()
        if (rowIds.isEmpty()) return 0L
        synchronized(keepUnsentDeletedIds) {
            rowIds.firstNotNullOfOrNull { keepUnsentDeletedIds[it.trim()] }?.let { return it }
            if (rowIds.size > 4) return 0L
            keepUnsentDeletedIds.forEach { (deletedId, deletedAt) ->
                if (rowIds.any { idsLikelyMatch(it, deletedId) }) {
                    logKeepUnsentFuzzyMatchOnce()
                    return deletedAt
                }
            }
        }
        return 0L
    }

    private fun containsKeepUnsentDeletedId(ids: Set<String>): Boolean {
        return keepUnsentDeletedAt(ids) > 0L
    }

    private fun extractDeletedMessageIds(ids: Collection<String>?): Set<String> {
        val parsed = HashSet<String>()
        val fallback = HashSet<String>()
        ids.orEmpty().forEach { raw ->
            val trimmed = raw.trim()
            collectUriMessageIds(trimmed, parsed, strictMessageOnly = true)
            if (isMessageScopedId(trimmed, allowNumeric = true)) fallback += trimmed
        }
        val result = if (parsed.isNotEmpty()) parsed else fallback
        if (!ids.isNullOrEmpty()) {
            logKeepUnsentDebug(
                "extract-delete-ids raw=${formatKeepUnsentIds(ids)} parsed=${formatKeepUnsentIds(parsed)} fallback=${formatKeepUnsentIds(fallback)} result=${formatKeepUnsentIds(result)}"
            )
        }
        return result
    }

    private fun extractRowBindableIds(ids: Collection<String>?): Set<String> {
        val out = HashSet<String>()
        ids.orEmpty().forEach { id ->
            if (isMessageScopedId(id, allowNumeric = true)) out += id.trim()
        }
        if (!ids.isNullOrEmpty()) {
            logKeepUnsentDebug("extract-row-ids raw=${formatKeepUnsentIds(ids)} result=${formatKeepUnsentIds(out)}")
        }
        return out
    }

    private fun addUsefulId(value: String?, out: MutableSet<String>) {
        val trimmed = value?.trim().orEmpty()
        if (trimmed.isBlank()) return
        if (collectUriMessageIds(trimmed, out, strictMessageOnly = false)) return
        if (isUsefulMessageId(trimmed)) out += trimmed
    }

    private fun collectKeepUnsentDeletedTexts(source: Any?): Set<String> {
        val out = LinkedHashSet<String>()
        collectKeepUnsentDeletedTexts(source, out, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        return out.take(8).toSet()
    }

    private fun collectKeepUnsentActionTexts(source: Any?): List<String> {
        val out = LinkedHashSet<String>()
        collectKeepUnsentActionTexts(source, out, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        return out
            .mapNotNull(::normalizeKeepUnsentMessageText)
            .filter(::isPersistableKeepUnsentDeletedText)
            .filterNot(::isDmMessageActionMenuOrChromeText)
            .distinct()
            .take(6)
    }

    private fun collectKeepUnsentActionTexts(source: Any?, out: MutableSet<String>, seen: MutableSet<Any>, depth: Int) {
        if (source == null || depth > 6 || out.size >= 24) return
        when (source) {
            is CharSequence -> {
                normalizeKeepUnsentMessageText(source)?.let(out::add)
                return
            }
            is Array<*> -> {
                source.take(48).forEach { collectKeepUnsentActionTexts(it, out, seen, depth + 1) }
                return
            }
            is Iterable<*> -> {
                source.take(48).forEach { collectKeepUnsentActionTexts(it, out, seen, depth + 1) }
                return
            }
            is Map<*, *> -> {
                source.values.take(48).forEach { collectKeepUnsentActionTexts(it, out, seen, depth + 1) }
                return
            }
        }
        if (isPrimitiveLike(source) || source is View || !seen.add(source)) return
        val className = source.javaClass.name
        if (className.startsWith("android.") ||
            className.startsWith("androidx.") ||
            className.startsWith("java.") ||
            className.startsWith("kotlin.") ||
            className.contains("UserSession")
        ) return
        var cls: Class<*>? = source.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 5 && out.size < 24) {
            cls.declaredFields.forEach { field ->
                if (out.size >= 24 || Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type.isPrimitive) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(source) ?: return@forEach
                    if (value is CharSequence) {
                        normalizeKeepUnsentMessageText(value)?.let(out::add)
                    } else if (!isPrimitiveLike(value) && value !is View) {
                        collectKeepUnsentActionTexts(value, out, seen, depth + 1)
                    }
                }
            }
            cls.declaredMethods
                .asSequence()
                .filter { method ->
                    !Modifier.isStatic(method.modifiers) &&
                        !method.isSynthetic &&
                        method.parameterTypes.isEmpty() &&
                        CharSequence::class.java.isAssignableFrom(method.returnType)
                }
                .take(16)
                .forEach { method ->
                    runCatching {
                        method.isAccessible = true
                        val value = method.invoke(source) as? CharSequence ?: return@runCatching
                        normalizeKeepUnsentMessageText(value)?.let(out::add)
                    }
                }
            cls = cls.superclass
        }
    }

    private fun collectKeepUnsentDeletedTexts(source: Any?, out: MutableSet<String>, seen: MutableSet<Any>, depth: Int) {
        if (source == null || depth > 3 || out.size >= 8) return
        when (source) {
            is CharSequence -> {
                normalizeKeepUnsentMessageText(source)?.let(out::add)
                return
            }
            is Array<*> -> {
                source.take(24).forEach { collectKeepUnsentDeletedTexts(it, out, seen, depth + 1) }
                return
            }
            is Iterable<*> -> {
                source.take(24).forEach { collectKeepUnsentDeletedTexts(it, out, seen, depth + 1) }
                return
            }
            is Map<*, *> -> {
                source.values.take(24).forEach { collectKeepUnsentDeletedTexts(it, out, seen, depth + 1) }
                return
            }
        }
        if (isPrimitiveLike(source) || source is View || !seen.add(source)) return
        var cls: Class<*>? = source.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 4 && out.size < 8) {
            cls.declaredFields.forEach { field ->
                if (out.size >= 8 || Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type.isPrimitive) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(source) ?: return@forEach
                    if (value is CharSequence) {
                        normalizeKeepUnsentMessageText(value)?.let(out::add)
                    } else if (!isPrimitiveLike(value) && value !is View) {
                        collectKeepUnsentDeletedTexts(value, out, seen, depth + 1)
                    }
                }
            }
            cls = cls.superclass
        }
    }

    private fun normalizeKeepUnsentMessageText(value: CharSequence?): String? {
        val text = cleanMessageDeletedLines(value).trim()
        if (text.isBlank() || text.length > 500) return null
        val lower = text.lowercase(Locale.US)
        if (lower.length < 2) return null
        if (lower.all { it in '0'..'9' }) return null
        if (lower.startsWith("-") && lower.drop(1).all { it in '0'..'9' }) return null
        if (lower == KEEP_UNSENT_MARKER_TEXT.lowercase(Locale.US)) return null
        if (lower.contains("://") || lower.startsWith("{") || lower.startsWith("[") || lower.contains("\"")) return null
        if (lower.contains("direct_v2") || lower.contains("remove_message") || lower.contains("delete_item")) return null
        if (lower.contains("message is no longer available") && lower.contains("unsent")) return null
        if (lower in setOf(
                "remove",
                "delete",
                "replace",
                "replace_message",
                "noop",
                "default",
                "process_start",
                "process_end",
                "deltamessagedelete",
                "slideuqppdeletemessage"
            )
        ) {
            return null
        }
        if (looksLikeKeepUnsentInternalIdentifier(text)) return null
        return text
    }

    private fun looksLikeKeepUnsentInternalIdentifier(value: String): Boolean {
        val text = value.trim()
        val lower = text.lowercase(Locale.US)
        if (lower.count { it == ':' } == 1 &&
            lower.filterNot { it == '-' || it == ':' }.all { it in '0'..'9' }
        ) {
            return true
        }
        if (isUuidLike(lower)) return true
        if (lower.startsWith("mid.") || lower.startsWith("mid$") || lower.startsWith("mid:")) return true
        if (lower.contains("messageid") || lower.contains("client_context")) return true
        val canonical = canonicalMessageId(lower)
        if (canonical.length < 24) return false
        if (text.any { it.isWhitespace() }) return false
        val digitCount = canonical.count { it in '0'..'9' }
        val letterCount = canonical.count { it in 'a'..'z' }
        if (digitCount == canonical.length) return true
        if (canonical.length >= 28 && digitCount >= 4 && letterCount >= 4) return true
        return canonical.length >= 32 && digitCount >= 12
    }

    private fun collectUriMessageIds(value: String?, out: MutableSet<String>, strictMessageOnly: Boolean): Boolean {
        if (value.isNullOrBlank() || !value.contains("=")) return false
        var added = false
        runCatching {
            val uri = Uri.parse(value)
            arrayOf("did", "id", "message_id", "item_id", "client_context", "client_context_id").forEach { name ->
                val queryValue = uri.getQueryParameter(name)?.trim().orEmpty()
                if (queryValue.isNotBlank()) {
                    if (strictMessageOnly) {
                        if (isMessageScopedId(queryValue, allowNumeric = true)) added = out.add(queryValue) || added
                    } else {
                        val before = out.size
                        if (isUsefulMessageId(queryValue)) out += queryValue
                        added = added || out.size != before
                    }
                }
            }
        }
        return added
    }

    private fun isMessageScopedId(value: String?, allowNumeric: Boolean): Boolean {
        if (!isUsefulMessageId(value)) return false
        val trimmed = value!!.trim()
        val lower = trimmed.lowercase(Locale.US)
        if (lower.contains("?") || lower.contains("=") || lower.contains("://")) return false
        if (lower.contains("thread") || lower.contains("inbox") || lower.contains("cursor")) return false
        if (lower.contains("viewer") || lower.contains("sender") || lower.contains("recipient")) return false
        if (isUuidLike(lower) || lower.startsWith("mid") || lower.contains("messageid")) return true
        val canonical = canonicalMessageId(lower)
        if (canonical.length < 8) return false
        val hasDigit = canonical.any { it in '0'..'9' }
        val hasLetter = canonical.any { it in 'a'..'z' }
        if (hasDigit && hasLetter && canonical.length >= 12) return true
        return allowNumeric && !hasLetter && hasDigit && canonical.length >= 10
    }

    private fun isUuidLike(value: String?): Boolean {
        if (value == null || value.length != 36) return false
        return value.withIndex().all { (index, c) ->
            if (index in setOf(8, 13, 18, 23)) c == '-' else c in '0'..'9' || c in 'a'..'f'
        }
    }

    private fun idsLikelyMatch(left: String?, right: String?): Boolean {
        if (left == null || right == null) return false
        val trimmedLeft = left.trim()
        val trimmedRight = right.trim()
        if (trimmedLeft == trimmedRight) return true
        val canonicalLeft = canonicalMessageId(trimmedLeft)
        val canonicalRight = canonicalMessageId(trimmedRight)
        if (canonicalLeft.length < 8 || canonicalRight.length < 8) return false
        if (canonicalLeft == canonicalRight) return true
        val sharedLength = minOf(canonicalLeft.length, canonicalRight.length)
        if (sharedLength >= 12 && (canonicalLeft.contains(canonicalRight) || canonicalRight.contains(canonicalLeft))) return true
        val tailLength = minOf(18, sharedLength)
        return tailLength >= 12 &&
            canonicalLeft.takeLast(tailLength) == canonicalRight.takeLast(tailLength)
    }

    private fun canonicalMessageId(value: String?): String {
        if (value == null) return ""
        return buildString(value.length) {
            value.trim().lowercase(Locale.US).forEach { c ->
                if (c in 'a'..'z' || c in '0'..'9') append(c)
            }
        }
    }

    private fun logKeepUnsentFuzzyMatchOnce() {
        if (!keepUnsentFuzzyMatchSeen) {
            keepUnsentFuzzyMatchSeen = true
            logInfo("Matched deleted Direct row with compatible message id")
        }
    }

    private fun hookKeepUnsentStoreDeleteWrappers(storeClass: Class<*>, hook: XC_MethodHook? = null): List<Method> {
        val hooked = ArrayList<Method>()
        storeClass.declaredMethods.forEach { method ->
            val params = method.parameterTypes
            if (method.returnType != Void.TYPE || params.size != 3 || params[1] != String::class.java || params[2] != String::class.java) {
                return@forEach
            }
            val signature = "${storeClass.name}.${method.name}:keep_unsent_store_delete_wrapper"
            if (!hookedDexMethods.add(signature)) return@forEach
            method.isAccessible = true
            XposedBridge.hookMethod(
                method,
                hook ?: object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!state.keepUnsentMessages) return
                        if (isScopedRemoteDelete(param.args) || isOneIdServerDelete(param.args)) {
                            rememberKeepUnsentDeletedIds(collectUsefulIdsDeep(param.args), param.args)
                            param.result = null
                        }
                    }
                }
            )
            hooked += method
        }
        return hooked
    }

    private fun installKeepUnsentDeletedIndicatorHooks(): Int {
        val hook = object : XC_MethodHook() {
            override fun afterHookedMethod(param: MethodHookParam<*>) {
                if (!state.keepUnsentMessages || param.args == null || param.args.size < 2) return
                val bound = findKeepUnsentRowBinding(param.args) ?: return
                val rowIds = bound.first
                val rowRoot = bound.second
                if (rowRoot == null || rowIds.isEmpty()) return
                loadKeepUnsentDeletedIds(rowRoot.context)
                scheduleKeepUnsentPersistIfDirty(rowRoot.context, "row-bind")
                if (!keepUnsentRowDecoratorSeen) {
                    keepUnsentRowDecoratorSeen = true
                    logInfo("Keep-unsent deleted marker row binder active")
                }
                rememberKeepUnsentBoundRows(rowIds, rowRoot)
                applyKeepUnsentDeletedMarkerFromSignals(rowRoot, rowIds)
            }
        }

        var hooked = 0
        val hookedMethods = ArrayList<Method>()
        fun hookRowMethod(method: Method, suffix: String): Boolean {
            val signature = "${methodKey(method)}:$suffix"
            if (!hookedDexMethods.add(signature)) return false
            return runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(method, hook)
                hookedMethods += method
                hooked++
                true
            }.onFailure { logError("Failed keep-unsent row hook $signature", it) }.getOrDefault(false)
        }

        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods("KeepUnsent_row_decorator", appClassLoader)
                .orEmpty()
                .filter { it.returnType == Void.TYPE && it.parameterTypes.size == 2 }
                .forEach { method -> hookRowMethod(method, "keep_unsent_row_cached") }
        }

        arrayOf("X.8Ox", "p000X.AbstractC215078Ox").forEach { className ->
            runCatching {
                val cls = Class.forName(className, false, appClassLoader)
                cls.declaredMethods.forEach { method ->
                    if (method.name != "A0J" || method.returnType != Void.TYPE || method.parameterTypes.size != 2) return@forEach
                    hookRowMethod(method, "keep_unsent_row_known")
                }
            }
        }
        if (hooked > 0) {
            if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString("KeepUnsent_row_decorator_missing", "0")
            return hooked
        }
        if (InstagramDexKitCache.isCacheValid() &&
            InstagramDexKitCache.loadString("KeepUnsent_row_decorator_missing") == "1"
        ) {
            return 0
        }

        val tagId = resolveInstagramRId("message_content_view_tag").takeIf { it != 0 } ?: 2131437280
        val textId = resolveInstagramRId("direct_text_message_text_view").takeIf { it != 0 } ?: 2131432340
        val contentId = resolveInstagramRId("message_content_horizontal_linear_layout").takeIf { it != 0 } ?: 2131437270
        val dexCandidates = LinkedHashSet<Method>()
        dexCandidates += dexBridge.findMethodsUsingNumbersConstrained(
            listOf(tagId),
            paramCount = 2,
            returnType = "void"
        )
        dexCandidates += dexBridge.findMethodsUsingNumbersConstrained(
            listOf(textId),
            paramCount = 2,
            returnType = "void"
        )
        dexCandidates += dexBridge.findMethodsUsingNumbersConstrained(
            listOf(contentId),
            paramCount = 2,
            returnType = "void"
        )
        if (dexCandidates.isEmpty()) {
            dexCandidates += dexBridge.findMethodsUsingNumbers(tagId, textId, contentId)
                .filter { method ->
                    method.returnType == Void.TYPE &&
                        method.parameterTypes.size in 2..4 &&
                        !Modifier.isStatic(method.modifiers)
                }
        }
        dexCandidates
            .filter { it.returnType == Void.TYPE && it.parameterTypes.size in 2..4 }
            .forEach { method -> hookRowMethod(method, "keep_unsent_row_dex") }
        if (hookedMethods.isNotEmpty()) {
            InstagramDexKitCache.saveMethods("KeepUnsent_row_decorator", hookedMethods)
            if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString("KeepUnsent_row_decorator_missing", "0")
        }
        if (hooked == 0) {
            if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString("KeepUnsent_row_decorator_missing", "1")
            logInfo("Keep-unsent deleted marker row binder not found; using Direct view fallback")
        }
        return hooked
    }

    private fun findKeepUnsentRowBinding(args: Array<Any?>): Pair<Set<String>, View>? {
        for (modelIndex in args.indices) {
            val rowIds = collectRowIds(args[modelIndex])
            if (rowIds.isEmpty()) continue
            for (holderIndex in args.indices) {
                if (holderIndex == modelIndex) continue
                val rowRoot = findViewHolderRootForKeepUnsent(args[holderIndex]) ?: continue
                return rowIds to rowRoot
            }
        }
        return null
    }

    private fun resolveInstagramRId(name: String): Int {
        arrayOf(
            "androidx.compose.ui.tooling.data.R\$id",
            "androidx.compose.ui.tooling.data.C0010R\$id",
            "androidx.compose.p003ui.tooling.data.C0010R\$id"
        ).forEach { className ->
            runCatching {
                val cls = Class.forName(className, false, appClassLoader)
                val field = cls.getDeclaredField(name)
                field.isAccessible = true
                return field.getInt(null)
            }
        }
        return 0
    }

    private fun collectRowIds(rowModel: Any?): Set<String> {
        val ids = HashSet<String>()
        addRowMessageId(invokeStringLikeNoArg(rowModel, "getKey"), ids, allowLooseKey = true)
        invokeNoArgDeep(rowModel, "getKey")?.takeIf { it !is String && !isPrimitiveLike(it) }?.let {
            collectRowIdentityIds(it, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        }
        collectRowIdentityIds(rowModel, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        arrayOf("BS5", "BRw", "Cj0").forEach { methodName ->
            collectRowIdentityIds(invokeNoArgDeep(rowModel, methodName), ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        }
        collectDirectMessageGetterIds(rowModel, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        return ids
    }

    private fun handleKeepUnsentDirectTextViewChanged(textView: TextView) {
        if (!state.keepUnsentMessages) return
        if (!hasCachedDirectTouchSurface()) return
        if (!hasLocalDirectTouchHint(textView) && !dmDirectSurfaceActive && !dmOverlayRootActive) return
        if (!isKeepUnsentDirectTextMessageTextView(textView)) return
        if (!isKeepUnsentDirectViewPath(textView)) return
        val renderedText = textView.text
        discardStaleKeepUnsentTextViewOriginal(textView, renderedText)
        val renderedDescription = textView.contentDescription
        val persistedFromMarker = persistKeepUnsentMarkerTextFromRenderedText(textView.context, renderedText) != null ||
            persistKeepUnsentMarkerTextFromRenderedText(textView.context, renderedDescription) != null
        if (persistedFromMarker) {
            logKeepUnsentDebug("rendered marker observed text=${formatKeepUnsentText(renderedText?.toString())} desc=${formatKeepUnsentText(renderedDescription?.toString())}")
            allowKeepUnsentMarkerMultiline(textView)
            return
        }
        rememberKeepUnsentDirectTextViewBinding(textView)
        if (maybeApplyKeepUnsentMarkerFromDirectTextView(textView)) return
    }

    private fun discardStaleKeepUnsentTextViewOriginal(textView: TextView, renderedText: CharSequence?) {
        val currentNormalized = normalizeKeepUnsentMessageText(renderedText) ?: return
        synchronized(keepUnsentMarkedTextOriginals) {
            val stored = keepUnsentMarkedTextOriginals[textView]?.let(::cleanMessageDeletedLines) ?: return
            val storedNormalized = normalizeKeepUnsentMessageText(stored) ?: return
            if (storedNormalized != currentNormalized) {
                keepUnsentMarkedTextOriginals.remove(textView)
                logKeepUnsentDebug(
                    "inline-marker recycled view reset stored=${formatKeepUnsentText(storedNormalized)} current=${formatKeepUnsentText(currentNormalized)}"
                )
            }
        }
    }

    private fun persistKeepUnsentMarkerTextFromRenderedText(context: Context?, rendered: CharSequence?): String? {
        val value = rendered?.toString().orEmpty()
        if (!value.contains(KEEP_UNSENT_MARKER_TEXT)) return null
        val text = normalizeKeepUnsentMessageText(value) ?: return null
        if (!isPersistableKeepUnsentDeletedText(text)) return null
        loadKeepUnsentDeletedIds(context)
        val knownAt = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts[text] ?: 0L }
        logKeepUnsentDebug("marker text recovered from rendered view text=${formatKeepUnsentText(text)} knownAt=$knownAt")
        persistKeepUnsentDeletedTextOnce(context, text, knownAt.takeIf { it > 0L } ?: System.currentTimeMillis())
        return text
    }

    private fun maybeApplyKeepUnsentMarkerFromDirectTextView(textView: TextView): Boolean {
        val text = normalizeKeepUnsentMessageText(textView.text) ?: return false
        loadKeepUnsentDeletedIds(textView.context)
        val textDeletedAt = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts[text] ?: 0L }
        if (textDeletedAt <= 0L) return false
        val rowRoot = nearestKeepUnsentRowRoot(textView) ?: textView
        rememberKeepUnsentVisibleRowTextMapping(rowRoot, text)
        val rowIds = extractRowBindableIds(collectKeepUnsentViewRowIds(rowRoot, rowRoot) + collectKeepUnsentRecyclerHolderIds(rowRoot))
        val idDeletedAt = if (rowIds.isEmpty()) 0L else keepUnsentDeletedAt(rowIds)
        val deletedAt = when {
            idDeletedAt > 0L -> maxOf(idDeletedAt, textDeletedAt)
            rowIds.isNotEmpty() -> {
                logKeepUnsentDebug(
                    "persisted text match skipped because row ids do not match deleted ids text=${formatKeepUnsentText(text)} ids=${formatKeepUnsentIds(rowIds)}"
                )
                0L
            }
            shouldApplyKeepUnsentTextOnlyMarker(rowRoot, text) -> textDeletedAt
            else -> 0L
        }
        if (deletedAt <= 0L) return false
        logKeepUnsentDebug("persisted text matched visible row text=${formatKeepUnsentText(text)} deletedAt=$deletedAt idMatch=${idDeletedAt > 0L}")
        if (textView.text?.toString().orEmpty().contains(KEEP_UNSENT_MARKER_TEXT)) {
            allowKeepUnsentMarkerMultiline(textView)
            return true
        }
        return applyKeepUnsentDeletedMarkerToTextView(textView, deletedAt, "direct-text-match")
    }

    private fun maybeBindKeepUnsentRowFromView(view: View, knownCandidate: Boolean = false) {
        if (!state.keepUnsentMessages) return
        if (!isKeepUnsentConversationSurfaceActive(view)) return
        if (!knownCandidate && !isKeepUnsentMessageContentCandidate(view)) return
        if (!isKeepUnsentDirectViewPath(view)) return
        if (view is TextView && isKeepUnsentDirectTextMessageTextView(view)) {
            rememberKeepUnsentDirectTextViewBinding(view)
            maybeApplyKeepUnsentMarkerFromDirectTextView(view)
            return
        }
        if (!keepUnsentViewCandidateSeen) {
            keepUnsentViewCandidateSeen = true
            logInfo("Keep-unsent Direct view fallback candidate ${describeViewBrief(view)}")
        }
        val rowRoot = nearestKeepUnsentRowRoot(view) ?: return
        if (findKeepUnsentDirectTextView(rowRoot) != null) {
            rememberKeepUnsentVisibleTextRow(rowRoot)
            return
        }
        if (!shouldProcessKeepUnsentRowNow(rowRoot)) return
        rememberKeepUnsentVisibleTextRow(rowRoot)
        val rowIds = collectKeepUnsentViewRowIds(view, rowRoot)
            .toMutableSet()
            .also { it += collectKeepUnsentRecyclerHolderIds(rowRoot) }
        rememberKeepUnsentRecentRowText(rowRoot, rowIds)
        loadKeepUnsentDeletedIds(view.context)
        scheduleKeepUnsentPersistIfDirty(view.context, "view-bind")
        if (rowIds.isEmpty()) {
            applyKeepUnsentDeletedMarkerFromSignals(rowRoot, emptySet())
            if (!keepUnsentViewNoIdsSeen) {
                keepUnsentViewNoIdsSeen = true
                logInfo("Keep-unsent Direct view fallback found no row ids view=${describeViewBrief(view)} root=${describeViewBrief(rowRoot)}")
            }
            if (rowRoot.width > 0 && rowRoot.height > 0 && !keepUnsentViewNoIdsLaidOutSeen) {
                keepUnsentViewNoIdsLaidOutSeen = true
                logInfo("Keep-unsent Direct laid-out row still has no ids view=${describeViewBrief(view)} root=${describeViewBrief(rowRoot)}")
            }
            return
        }
        if (!keepUnsentRowDecoratorSeen) {
            keepUnsentRowDecoratorSeen = true
            logInfo("Keep-unsent deleted marker view fallback active")
        }
        rememberKeepUnsentBoundRows(rowIds, rowRoot)
        applyKeepUnsentDeletedMarkerFromSignals(rowRoot, rowIds)
    }

    private fun shouldProcessKeepUnsentRowNow(rowRoot: View): Boolean {
        val existingMarker = findKeepUnsentMarkerView(rowRoot) != null ||
            ((findViewByResourceName(rowRoot, "direct_text_message_text_view") as? TextView)
                ?.text
                ?.toString()
                ?.contains(KEEP_UNSENT_MARKER_TEXT) == true)
        if (existingMarker && keepUnsentDeletedTextAt(rowRoot) > 0L) return false
        val now = SystemClock.uptimeMillis()
        val last = keepUnsentRowLastProcessedAt[rowRoot] ?: 0L
        if (now - last < 900L) return false
        keepUnsentRowLastProcessedAt[rowRoot] = now
        return true
    }

    private fun findKeepUnsentMarkerView(root: View?): View? {
        if (root == null) return null
        if (root.tag == KEEP_UNSENT_MARKER_TAG) return root
        val group = root as? ViewGroup ?: return null
        for (i in 0 until group.childCount) {
            findKeepUnsentMarkerView(group.getChildAt(i))?.let { return it }
        }
        return null
    }

    private fun scheduleKeepUnsentViewRowRetry(rowRoot: View) {
        val attempt = synchronized(keepUnsentViewRetryCounts) {
            val next = (keepUnsentViewRetryCounts[rowRoot] ?: 0) + 1
            if (next > 2) return
            keepUnsentViewRetryCounts[rowRoot] = next
            next
        }
        rowRoot.postDelayed({
            if (rowRoot.parent != null) maybeBindKeepUnsentRowFromView(rowRoot)
        }, when (attempt) {
            1 -> 160L
            else -> 350L
        })
    }

    private fun maybeBindKeepUnsentRowFromHolder(
        holder: Any?,
        adapter: Any? = null,
        position: Int = -1,
        rowRootOverride: View? = null
    ) {
        val rowRoot = rowRootOverride ?: findViewHolderRootForKeepUnsent(holder) ?: return
        if (!isKeepUnsentDirectViewPath(rowRoot)) return
        if (!isKeepUnsentConversationSurfaceActive(rowRoot)) return
        if (!containsKeepUnsentMessageContent(rowRoot)) return
        if (!keepUnsentRecyclerBindSeen) {
            keepUnsentRecyclerBindSeen = true
            logInfo("Keep-unsent RecyclerView fallback bind holder=${holder?.javaClass?.name} root=${describeViewBrief(rowRoot)}")
        }
        val rowIds = HashSet<String>()
        rememberKeepUnsentVisibleTextRow(rowRoot)
        rowIds += collectRowIds(holder)
        if (adapter != null && position >= 0) {
            val adapterIds = collectKeepUnsentAdapterItemIds(adapter, position)
            if (adapterIds.isNotEmpty()) {
                logKeepUnsentDebug("holder-bind adapter position=$position ids=${formatKeepUnsentIds(adapterIds)} rowText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))}")
                rowIds += adapterIds
            }
        }
        rowIds += collectKeepUnsentViewRowIds(rowRoot, rowRoot)
        rememberKeepUnsentRecentRowText(rowRoot, rowIds)
        loadKeepUnsentDeletedIds(rowRoot.context)
        scheduleKeepUnsentPersistIfDirty(rowRoot.context, "holder-bind")
        if (rowIds.isEmpty()) {
            applyKeepUnsentDeletedMarkerFromSignals(rowRoot, emptySet())
            if (!keepUnsentHolderNoIdsSeen) {
                keepUnsentHolderNoIdsSeen = true
                logInfo("Keep-unsent RecyclerView fallback found no row ids holder=${holder?.javaClass?.name} root=${describeViewBrief(rowRoot)}")
            }
            return
        }
        logKeepUnsentDebug("holder-bind final ids=${formatKeepUnsentIds(rowIds)} rowText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))}")
        if (!keepUnsentRowDecoratorSeen) {
            keepUnsentRowDecoratorSeen = true
            logInfo("Keep-unsent deleted marker RecyclerView fallback active")
        }
        rememberKeepUnsentBoundRows(rowIds, rowRoot)
        applyKeepUnsentDeletedMarkerFromSignals(rowRoot, rowIds)
    }

    private fun containsKeepUnsentMessageContent(view: View?): Boolean {
        if (view == null) return false
        if (isKeepUnsentMessageContentCandidate(view)) return true
        if (view !is ViewGroup) return false
        for (i in 0 until view.childCount) {
            if (containsKeepUnsentMessageContent(view.getChildAt(i))) return true
        }
        return false
    }

    private fun shouldInspectKeepUnsentRowBinding(view: View): Boolean {
        if (!state.keepUnsentMessages) return false
        if (!hasCachedDirectTouchSurface()) return false
        if (isKeepUnsentConversationSurfaceActive(view) && isKeepUnsentDirectViewPath(view)) return true

        val now = SystemClock.elapsedRealtime()
        if (now - keepUnsentLastNonDirectProcessSkipLogAtMs > 5_000L) {
            keepUnsentLastNonDirectProcessSkipLogAtMs = now
            logInfo(
                "Skipped keep-unsent row binding outside Direct " +
                    "view=${describeViewBrief(view)} root=${describeViewBrief(view.rootView ?: view)}"
            )
        }
        return false
    }

    private fun isKeepUnsentMessageContentCandidate(view: View): Boolean {
        if (isKnownKeepUnsentMessageContentResource(view)) return true
        if (!dmDirectSurfaceActive && !dmOverlayRootActive) return false
        val name = resourceEntryName(view).orEmpty()
        if (name == "direct_text_message_text_view" ||
            name == "message_content" ||
            name == "message_content_horizontal_linear_layout" ||
            name == "direct_text_message_text_view_stub"
        ) {
            return true
        }
        val tagId = instagramResourceId(view.context, "message_content_view_tag")
        return tagId != 0 && runCatching { view.getTag(tagId) != null }.getOrDefault(false)
    }

    private fun isKnownKeepUnsentMessageContentResource(view: View): Boolean {
        return hasInstagramResourceId(view, "direct_text_message_text_view") ||
            hasInstagramResourceId(view, "message_content") ||
            hasInstagramResourceId(view, "message_content_horizontal_linear_layout") ||
            hasInstagramResourceId(view, "direct_text_message_text_view_stub")
    }

    private fun isKeepUnsentDirectTextMessageTextView(view: View): Boolean {
        if (hasInstagramResourceId(view, "direct_text_message_text_view")) return true
        if (!dmDirectSurfaceActive && !dmOverlayRootActive) return false
        return resourceEntryName(view) == "direct_text_message_text_view"
    }

    private fun nearestKeepUnsentRowRoot(view: View): View? {
        var current: View? = view
        var best: View? = view
        repeat(8) {
            val node = current ?: return@repeat
            val parent = node.parent as? View
            if (parent != null && parent.javaClass.name.contains("RecyclerView")) return node
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            val cls = node.javaClass.name.lowercase(Locale.US)
            if ((name.contains("message") || name.contains("direct") || cls.contains("recyclerview")) &&
                (node.width > 0 || node.height > 0 || best?.parent == null)
            ) {
                best = node
            }
            if (parent == null || parent.javaClass.name.contains("RecyclerView")) return best
            current = parent
        }
        return best
    }

    private fun scanVisibleKeepUnsentRowsSoon(reason: String, delayMs: Long) {
        val root = currentActivity?.window?.decorView ?: return
        if (!isKeepUnsentConversationSurfaceActive(root)) return
        mainHandler.postDelayed({
            if (!state.keepUnsentMessages || !root.isAttachedToWindow || !isKeepUnsentConversationSurfaceActive(root)) return@postDelayed
            logKeepUnsentDebug("visible-row-scan reason=$reason")
            scanVisibleKeepUnsentRowsOnly(root)
            resolveKeepUnsentTemporalDeleteCandidates()
        }, delayMs)
    }

    private fun scanVisibleKeepUnsentRowsAfterListVisible(reason: String, list: View? = dmMessageListViewRef?.get()) {
        if (!state.keepUnsentMessages) return
        if (!isKeepUnsentConversationSurfaceActive(list ?: currentActivity?.window?.decorView)) return
        if (reason == "manual-scroll" || reason == "list-touch" || reason == "composer-touch" || reason == "bindViewHolder") {
            logKeepUnsentDebug("visible keep-unsent scan skipped during $reason; direct text bind is synchronous")
            return
        }
        val target = list?.takeIf { it.isShown && isDirectMessageListView(it) } ?: currentActivity?.window?.decorView ?: return
        val now = SystemClock.uptimeMillis()
        if (now - keepUnsentLastVisibleListScanAtMs < 650L) return
        keepUnsentLastVisibleListScanAtMs = now
        target.post { scanVisibleKeepUnsentRowsOnly(target) }
        logKeepUnsentDebug("scheduled visible keep-unsent scan reason=$reason")
    }

    private fun schedulePersistVisibleKeepUnsentRenderedMarkers(reason: String) {
        logInfo("Scheduled keep-unsent rendered marker persistence reason=$reason")
        listOf(120L, 420L, 1_200L, 2_400L, 5_000L, 8_000L).forEach { delay ->
            mainHandler.postDelayed({
                persistVisibleKeepUnsentRenderedMarkers(reason)
            }, delay)
        }
    }

    private fun persistVisibleKeepUnsentRenderedMarkers(reason: String) {
        val root = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) }
            ?: currentActivity?.window?.decorView
            ?: return
        if (!isKeepUnsentConversationSurfaceActive(root)) return
        val persisted = persistVisibleKeepUnsentRenderedMarkers(root, intArrayOf(900))
        val accessibilityPersisted = persistAccessibilityKeepUnsentRenderedMarkers(root)
        val total = persisted + accessibilityPersisted
        logInfo("Keep-unsent rendered marker sweep reason=$reason count=$total view=$persisted accessibility=$accessibilityPersisted root=${describeViewBrief(root)}")
        if (total > 0) logKeepUnsentDebug("persisted rendered keep-unsent markers reason=$reason count=$total")
    }

    private fun persistVisibleKeepUnsentRenderedMarkers(view: View?, budget: IntArray): Int {
        if (view == null || budget[0]-- <= 0 || !view.isShown) return 0
        var persisted = 0
        if (view is TextView && resourceEntryName(view) == "direct_text_message_text_view") {
            val rendered = view.text?.toString().orEmpty()
            val described = view.contentDescription?.toString().orEmpty()
            val value = when {
                rendered.contains(KEEP_UNSENT_MARKER_TEXT) -> rendered
                described.contains(KEEP_UNSENT_MARKER_TEXT) -> described
                else -> ""
            }
            if (value.isNotBlank()) {
                val text = normalizeKeepUnsentMessageText(value)
                if (text != null) {
                    val knownAt = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts[text] ?: 0L }
                    persistKeepUnsentDeletedTextOnce(view.context, text, knownAt.takeIf { it > 0L } ?: System.currentTimeMillis())
                    allowKeepUnsentMarkerMultiline(view)
                    persisted++
                }
            }
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                persisted += persistVisibleKeepUnsentRenderedMarkers(view.getChildAt(i), budget)
                if (budget[0] <= 0) return persisted
            }
        }
        return persisted
    }

    private fun persistAccessibilityKeepUnsentRenderedMarkers(root: View): Int {
        return runCatching {
            val node = root.createAccessibilityNodeInfo() ?: return@runCatching 0
            try {
                persistAccessibilityKeepUnsentRenderedMarkers(node, root.context, intArrayOf(1_200))
            } finally {
                node.recycle()
            }
        }.getOrElse {
            logError("Keep-unsent accessibility marker sweep failed", it)
            0
        }
    }

    private fun persistAccessibilityKeepUnsentRenderedMarkers(
        node: AccessibilityNodeInfo?,
        context: Context?,
        budget: IntArray
    ): Int {
        if (node == null || budget[0]-- <= 0) return 0
        var persisted = 0
        val text = node.text?.toString().orEmpty()
        val description = node.contentDescription?.toString().orEmpty()
        val viewId = runCatching { node.viewIdResourceName.orEmpty() }.getOrDefault("")
        val rendered = when {
            text.contains(KEEP_UNSENT_MARKER_TEXT) -> text
            description.contains(KEEP_UNSENT_MARKER_TEXT) -> description
            else -> ""
        }
        if (rendered.isNotBlank() &&
            (viewId.endsWith(":id/direct_text_message_text_view") ||
                viewId.endsWith("/direct_text_message_text_view") ||
                rendered.contains('\n'))
        ) {
            val normalized = normalizeKeepUnsentMessageText(rendered)
            if (normalized != null && isPersistableKeepUnsentDeletedText(normalized)) {
                val knownAt = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts[normalized] ?: 0L }
                persistKeepUnsentDeletedTextOnce(context ?: androidContext, normalized, knownAt.takeIf { it > 0L } ?: System.currentTimeMillis())
                persisted++
            }
        }
        for (i in 0 until node.childCount) {
            val child = runCatching { node.getChild(i) }.getOrNull() ?: continue
            try {
                persisted += persistAccessibilityKeepUnsentRenderedMarkers(child, context, budget)
            } finally {
                child.recycle()
            }
            if (budget[0] <= 0) return persisted
        }
        return persisted
    }

    private fun scanVisibleKeepUnsentRowsOnly(root: View) {
        val started = SystemClock.uptimeMillis()
        loadKeepUnsentDeletedIds(root.context)
        val rows = ArrayList<View>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        collectVisibleKeepUnsentTextRowRoots(scanRoot, rows, intArrayOf(650))
        val distinct = rows.distinctBy { System.identityHashCode(it) }
        var applied = 0
        distinct.forEach { rowRoot ->
            rememberKeepUnsentVisibleTextRow(rowRoot)
            keepUnsentDeletedTextAt(rowRoot).takeIf { it > 0L }?.let {
                applied++
                applyKeepUnsentDeletedMarker(rowRoot, it)
            }
        }
        logKeepUnsentDebug("visible-row-scan complete rows=${distinct.size} applied=$applied elapsed=${SystemClock.uptimeMillis() - started}ms root=${describeViewBrief(scanRoot)}")
    }

    private fun collectKeepUnsentViewRowIds(view: View, rowRoot: View): Set<String> {
        val ids = HashSet<String>()
        val tagIds = intArrayOf(
            instagramResourceId(view.context, "message_content_view_tag"),
            2131437280
        ).filter { it != 0 }.distinct()
        var current: View? = view
        repeat(8) {
            val node = current ?: return@repeat
            collectRowIdentityIds(node.tag, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
            tagIds.forEach { tagId ->
                runCatching {
                    collectRowIdentityIds(node.getTag(tagId), ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
                }
            }
            if (node === rowRoot) return@repeat
            current = node.parent as? View
        }
        return ids
    }

    private fun collectKeepUnsentRecyclerHolderIds(rowRoot: View): Set<String> {
        var child: View? = rowRoot
        var parent = child?.parent
        while (child != null && parent is View) {
            val parentView = parent as View
            if (parentView.javaClass.name.contains("RecyclerView")) {
                val ids = HashSet<String>()
                val holder = invokeRecyclerChildViewHolder(parentView, child)
                val position = invokeRecyclerChildPosition(parentView, child)
                val childIndex = (parentView as? ViewGroup)?.indexOfChild(child) ?: -1
                if (holder == null) {
                    if (!keepUnsentRecyclerHolderNullSeen) {
                        keepUnsentRecyclerHolderNullSeen = true
                        logInfo("Keep-unsent RecyclerView holder lookup returned null recycler=${describeViewBrief(parentView)} child=${describeViewBrief(child)} position=$position childIndex=$childIndex")
                    }
                } else {
                    logKeepUnsentDebug("view-holder lookup holder=${holder.javaClass.name} position=$position childIndex=$childIndex rowText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))}")
                    ids += collectRowIds(holder)
                }
                ids += collectKeepUnsentAdapterPositionIds(parentView, child)
                logKeepUnsentDebug("view-holder ids=${formatKeepUnsentIds(ids)} rowText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))}")
                return ids
            }
            child = parentView
            parent = child.parent
        }
        logKeepUnsentDebug("view-holder lookup skipped: no RecyclerView parent rowText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))} root=${describeViewBrief(rowRoot)}")
        return emptySet()
    }

    private fun invokeRecyclerChildViewHolder(recyclerView: View, child: View): Any? {
        arrayOf("getChildViewHolder", "findContainingViewHolder").forEach { name ->
            invokeOneArgDeep(recyclerView, name, child)?.let { return it }
        }
        var cls: Class<*>? = recyclerView.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 6) {
            cls.declaredMethods.forEach { method ->
                if ((method.name == "findContainingViewHolder" ||
                        method.name == "getChildViewHolder" ||
                        method.name == "getChildViewHolderInt") &&
                    method.parameterTypes.size == 1 &&
                    View::class.java.isAssignableFrom(method.parameterTypes[0])
                ) {
                    val holder = runCatching {
                        method.isAccessible = true
                        method.invoke(recyclerView, child)
                    }.getOrNull()
                    if (holder != null) return holder
                }
            }
            cls = cls.superclass
        }
        recyclerViewHolderFromLayoutParams(child)?.let { return it }
        return null
    }

    private fun recyclerViewHolderFromLayoutParams(child: View): Any? {
        val params = runCatching { child.layoutParams }.getOrNull() ?: return null
        val fieldsForLog = ArrayList<String>(10)
        var cls: Class<*>? = params.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 5) {
            cls.declaredFields.forEach { field ->
                val lower = field.name.lowercase(Locale.US)
                if (fieldsForLog.size < 10) fieldsForLog += "${field.name}:${field.type.name.substringAfterLast('.')}"
                if (!lower.contains("holder") && !lower.contains("viewholder")) return@forEach
                val value = runCatching {
                    field.isAccessible = true
                    field.get(params)
                }.getOrNull() ?: return@forEach
                logInfoThrottled("recycler:layout-holder:${params.javaClass.name}:${value.javaClass.name}", 1_500L) {
                    "Recycler holder recovered from layout params child=${describeViewBrief(child)} " +
                        "params=${params.javaClass.name} field=${field.name} holder=${value.javaClass.name}"
                }
                return value
            }
            cls = cls.superclass
        }
        logInfoThrottled("recycler:layout-holder-miss:${params.javaClass.name}:${describeViewBrief(child)}", 1_500L) {
            "Recycler holder missing in layout params child=${describeViewBrief(child)} " +
                "params=${params.javaClass.name} fields=${fieldsForLog.joinToString("|").ifBlank { "-" }}"
        }
        return null
    }

    private fun collectKeepUnsentAdapterPositionIds(recyclerView: View, child: View): Set<String> {
        val position = invokeRecyclerChildPosition(recyclerView, child)
        val childIndex = (recyclerView as? ViewGroup)?.indexOfChild(child) ?: -1
        if (position < 0 && childIndex < 0) {
            if (!keepUnsentAdapterPositionMissingSeen) {
                keepUnsentAdapterPositionMissingSeen = true
                logInfo("Keep-unsent adapter-position fallback could not resolve position recycler=${describeViewBrief(recyclerView)} child=${describeViewBrief(child)}")
            }
            return emptySet()
        }
        val ids = HashSet<String>()
        val adapter = invokeNoArgDeep(recyclerView, "getAdapter")
            ?: invokeNoArgDeep(recyclerView, "getBindingAdapter")
        if (adapter != null) {
            if (position >= 0) ids += collectKeepUnsentAdapterItemIds(adapter, position)
            if (ids.isEmpty() && childIndex >= 0 && childIndex != position) {
                ids += collectKeepUnsentAdapterItemIds(adapter, childIndex)
            }
            if (ids.size > 4) {
                if (!keepUnsentAdapterPositionNoIdsSeen) {
                    keepUnsentAdapterPositionNoIdsSeen = true
                    logInfo("Keep-unsent adapter-position fallback rejected broad row ids position=$position childIndex=$childIndex ids=${ids.size} adapter=${adapter.javaClass.name}")
                }
                return emptySet()
            }
        }
        if (ids.isNotEmpty()) {
            if (!keepUnsentAdapterPositionSeen) {
                keepUnsentAdapterPositionSeen = true
                logInfo("Keep-unsent adapter-position fallback resolved row ids position=$position childIndex=$childIndex ids=${ids.size}")
            }
        } else if (!keepUnsentAdapterPositionNoIdsSeen) {
            keepUnsentAdapterPositionNoIdsSeen = true
            logInfo("Keep-unsent adapter-position fallback found no ids position=$position childIndex=$childIndex adapter=${adapter?.javaClass?.name}")
            if (adapter != null && !keepUnsentAdapterShapeSeen) {
                keepUnsentAdapterShapeSeen = true
                logInfo("Keep-unsent adapter shape ${describeKeepUnsentAdapterShape(adapter)}")
            }
        }
        return ids
    }

    private fun invokeRecyclerChildPosition(recyclerView: View, child: View): Int {
        arrayOf("getChildAdapterPosition", "getChildLayoutPosition", "getChildPosition").forEach { name ->
            val result = invokeOneArgDeep(recyclerView, name, child)
            if (result is Number) return result.toInt()
        }
        val holder = invokeRecyclerChildViewHolder(recyclerView, child) ?: recyclerViewHolderFromLayoutParams(child)
        val holderPosition = recyclerViewHolderPosition(holder)
        if (holderPosition >= 0) {
            logInfoThrottled("recycler:holder-position:${holder?.javaClass?.name}:${describeViewBrief(child)}", 1_500L) {
                "Recycler child position recovered from holder class=${holder?.javaClass?.name ?: "-"} " +
                    "position=$holderPosition child=${describeViewBrief(child)} recycler=${describeViewBrief(recyclerView)}"
            }
            return holderPosition
        }
        return -1
    }

    private fun recyclerViewHolderPosition(holder: Any?): Int {
        holder ?: return -1
        arrayOf(
            "getBindingAdapterPosition",
            "getAbsoluteAdapterPosition",
            "getAdapterPosition",
            "getLayoutPosition",
            "getOldPosition"
        ).forEach { name ->
            val result = invokeNoArgDeep(holder, name)
            if (result is Number && result.toInt() >= 0) return result.toInt()
        }
        var cls: Class<*>? = holder.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 6) {
            cls.declaredFields.forEach { field ->
                val lower = field.name.lowercase(Locale.US)
                if (!lower.contains("position") && field.name !in setOf("mPosition", "mOldPosition", "mPreLayoutPosition")) return@forEach
                val value = runCatching {
                    field.isAccessible = true
                    field.get(holder)
                }.getOrNull() as? Number ?: return@forEach
                val position = value.toInt()
                if (position >= 0) return position
            }
            cls = cls.superclass
        }
        return -1
    }

    private fun collectKeepUnsentAdapterItemIds(adapter: Any, position: Int): Set<String> {
        val ids = HashSet<String>()
        collectKeepUnsentAdapterItemIds(adapter, position, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
        return ids
    }

    private fun collectKeepUnsentAdapterItemIds(
        adapter: Any?,
        position: Int,
        ids: MutableSet<String>,
        seen: MutableSet<Any>,
        depth: Int
    ) {
        if (adapter == null || depth > 1 || isPrimitiveLike(adapter) || !seen.add(adapter)) return
        arrayOf("getItem", "getItemAt", "getItemAtPosition").forEach { name ->
            invokeOneArgDeep(adapter, name, position)?.let { item ->
                collectRowIdentityIds(item, ids, Collections.newSetFromMap(IdentityHashMap<Any, Boolean>()), 0)
            }
        }
        collectKeepUnsentAdapterListIds(adapter, position, ids)
    }

    private fun collectKeepUnsentAdapterListIds(adapter: Any, position: Int, ids: MutableSet<String>) {
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        var cls: Class<*>? = adapter.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 5) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                runCatching {
                    field.isAccessible = true
                    when (val value = field.get(adapter)) {
                        is List<*> -> collectKeepUnsentNearbyListItems(value, position, ids, seen)
                        is Array<*> -> collectKeepUnsentNearbyListItems(value.asList(), position, ids, seen)
                    }
                }
            }
            cls = cls.superclass
        }
    }

    private fun collectKeepUnsentNearbyListItems(
        items: List<*>,
        position: Int,
        ids: MutableSet<String>,
        seen: MutableSet<Any>
    ) {
        if (items.isEmpty()) return
        intArrayOf(position).forEach { index ->
            if (index in items.indices) {
                collectRowIdentityIds(items[index], ids, seen, 0)
            }
        }
    }

    private fun invokeOneArgDeep(target: Any?, methodName: String, arg: Any?): Any? {
        if (target == null) return null
        var cls: Class<*>? = target.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 8) {
            cls.declaredMethods.forEach { method ->
                if (method.name == methodName && method.parameterTypes.size == 1 && isReflectArgCompatible(method.parameterTypes[0], arg)) {
                    return runCatching {
                        method.isAccessible = true
                        method.invoke(target, arg)
                    }.getOrNull()
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun isReflectArgCompatible(type: Class<*>, arg: Any?): Boolean {
        if (arg == null) return !type.isPrimitive
        if (type.isAssignableFrom(arg.javaClass)) return true
        if (arg is Int) {
            return type == Integer.TYPE || type == Integer::class.java ||
                type == Long::class.javaPrimitiveType || type == java.lang.Long::class.java
        }
        return false
    }

    private fun shouldTraverseKeepUnsentAdapter(value: Any?, depth: Int): Boolean {
        if (value == null || depth >= 3 || value is View || isPrimitiveLike(value)) return false
        val className = value.javaClass.name
        if (className.startsWith("android.") ||
            className.startsWith("androidx.") ||
            className.startsWith("java.") ||
            className.startsWith("kotlin.")
        ) return false
        val lower = className.lowercase(Locale.US)
        return lower.contains("adapter") ||
            lower.contains("binder") ||
            lower.contains("model") ||
            lower.contains("message") ||
            lower.contains("direct") ||
            className.startsWith("X.")
    }

    private fun describeKeepUnsentAdapterShape(adapter: Any): String {
        val parts = ArrayList<String>()
        var cls: Class<*>? = adapter.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 3 && parts.size < 18) {
            cls.declaredFields.forEach { field ->
                if (parts.size >= 18 || Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(adapter)
                    val summary = when (value) {
                        null -> "null"
                        is Collection<*> -> "${value.javaClass.simpleName}[${value.size}]"
                        is Array<*> -> "Array[${value.size}]"
                        else -> value.javaClass.name
                    }
                    parts += "${field.name}:${summary}"
                }
            }
            cls = cls.superclass
        }
        return "${adapter.javaClass.name} fields=${parts.joinToString(",")}"
    }

    private fun collectRowIdentityIds(target: Any?, ids: MutableSet<String>, seen: MutableSet<Any>, depth: Int) {
        if (target == null || depth > 4) return
        when (target) {
            is String -> {
                addRowMessageId(target, ids, allowLooseKey = depth > 0)
                return
            }
            is Array<*> -> {
                target.take(24).forEach { collectRowIdentityIds(it, ids, seen, depth + 1) }
                return
            }
            is Iterable<*> -> {
                target.take(24).forEach { collectRowIdentityIds(it, ids, seen, depth + 1) }
                return
            }
            is Map<*, *> -> {
                target.values.take(24).forEach { collectRowIdentityIds(it, ids, seen, depth + 1) }
                return
            }
        }
        if (isPrimitiveLike(target) || !seen.add(target)) return
        val scopedIdentityObject = looksLikeDirectMessageIdentityObject(target)
        if (isMessageIdentifierObject(target)) collectMessageIdentifierFields(target, ids)

        arrayOf("getKey", "A0o", "A0p", "A0r", "A0s").forEach { methodName ->
            val value = invokeNoArgDeep(target, methodName)
            if (value is String) {
                if (methodName == "getKey") addRowMessageId(value, ids, allowLooseKey = true) else addMessageIdentifierId(value, ids)
            } else if (value != null && !isPrimitiveLike(value)) {
                collectRowIdentityIds(value, ids, seen, depth + 1)
            }
        }
        arrayOf("BS4", "CHD", "Baq", "BX3", "A0e").forEach { methodName ->
            invokeNoArgDeep(target, methodName)?.takeIf { !isPrimitiveLike(it) }?.let {
                collectRowIdentityIds(it, ids, seen, depth + 1)
            }
        }

        var cls: Class<*>? = target.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type.isPrimitive) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(target) ?: return@forEach
                    if (value is String) addRowMessageId(value, ids, allowLooseKey = scopedIdentityObject || depth > 0)
                    else if (shouldTraverseRowIdentityObject(value, depth)) collectRowIdentityIds(value, ids, seen, depth + 1)
                }
            }
            cls = cls.superclass
        }
    }

    private fun looksLikeDirectMessageIdentityObject(target: Any?): Boolean {
        val lower = target?.javaClass?.name?.lowercase(Locale.US).orEmpty()
        return lower.contains("message") ||
            lower.contains("direct") ||
            lower.contains("threaditem") ||
            lower.contains("identifier") ||
            lower.contains("itemid")
    }

    private fun collectDirectMessageGetterIds(target: Any?, ids: MutableSet<String>, seen: MutableSet<Any>, depth: Int) {
        if (target == null || depth > 3 || isPrimitiveLike(target) || !seen.add(target)) return
        arrayOf("A0o", "A0p", "A0r", "A0s").forEach { addMessageIdentifierId(invokeStringLikeNoArg(target, it), ids) }
        var cls: Class<*>? = target.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type.isPrimitive || field.type == String::class.java) return@forEach
                runCatching {
                    field.isAccessible = true
                    val value = field.get(target) ?: return@forEach
                    if (!isPrimitiveLike(value)) collectDirectMessageGetterIds(value, ids, seen, depth + 1)
                }
            }
            cls = cls.superclass
        }
    }

    private fun addRowMessageId(value: String?, out: MutableSet<String>, allowLooseKey: Boolean): Boolean {
        val trimmed = value?.trim().orEmpty()
        if (!isMessageScopedId(trimmed, allowNumeric = allowLooseKey)) return false
        return out.add(trimmed)
    }

    private fun addMessageIdentifierId(value: String?, out: MutableSet<String>): Boolean {
        val trimmed = value?.trim().orEmpty()
        if (!isMessageScopedId(trimmed, allowNumeric = true)) return false
        return out.add(trimmed)
    }

    private fun isMessageIdentifierObject(target: Any?): Boolean {
        val className = target?.javaClass?.name?.lowercase(Locale.US).orEmpty()
        return className.contains("messageidentifier") ||
            className.contains("directmessageidentifier") ||
            className.contains("messageid")
    }

    private fun collectMessageIdentifierFields(target: Any?, ids: MutableSet<String>) {
        var cls: Class<*>? = target?.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic || field.type != String::class.java) return@forEach
                runCatching {
                    field.isAccessible = true
                    addMessageIdentifierId(field.get(target) as? String, ids)
                }
            }
            cls = cls.superclass
        }
    }

    private fun shouldTraverseRowIdentityObject(value: Any?, depth: Int): Boolean {
        if (value == null || depth >= 4 || value is View || isPrimitiveLike(value)) return false
        val className = value.javaClass.name
        if (className.startsWith("android.") ||
            className.startsWith("androidx.") ||
            className.startsWith("java.") ||
            className.startsWith("kotlin.") ||
            className.contains("UserSession")
        ) return false
        val lower = className.lowercase(Locale.US)
        return depth < 2 ||
            lower.contains("message") ||
            lower.contains("direct") ||
            lower.contains("identifier") ||
            className.startsWith("p000X.")
    }

    private fun rememberKeepUnsentBoundRows(ids: Set<String>, rowRoot: View) {
        val rowIds = extractRowBindableIds(ids)
        if (rowIds.isEmpty()) return
        if (!keepUnsentRowBindingSeen) {
            keepUnsentRowBindingSeen = true
            logInfo("Keep-unsent bound Direct row ids: ${rowIds.size}")
        }
        synchronized(keepUnsentBoundRows) {
            rowIds.forEach { rawId ->
                val id = rawId.trim()
                if (keepUnsentAmbiguousBoundIds.contains(id)) return@forEach
                val existing = keepUnsentBoundRows[id]?.get()
                if (existing != null && existing.parent != null && existing !== rowRoot) {
                    keepUnsentBoundRows.remove(id)
                    keepUnsentAmbiguousBoundIds += id
                    while (keepUnsentAmbiguousBoundIds.size > MAX_KEEP_UNSENT_IDS) {
                        keepUnsentAmbiguousBoundIds.remove(keepUnsentAmbiguousBoundIds.first())
                    }
                    logKeepUnsentDebug("bound-id ambiguous id=${formatKeepUnsentId(id)} oldText=${formatKeepUnsentText(keepUnsentRowMessageText(existing))} newText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))}")
                } else {
                    keepUnsentBoundRows[id] = WeakReference(rowRoot)
                }
            }
        }
        rememberKeepUnsentRecentRowText(rowRoot, rowIds)
    }

    private fun rememberKeepUnsentVisibleTextRow(rowRoot: View) {
        loadKeepUnsentDeletedIds(rowRoot.context)
        ensureKeepUnsentInlineMarkerVisible(rowRoot)
        val text = keepUnsentRowMessageText(rowRoot) ?: return
        logKeepUnsentDebug("visible-text-row text=${formatKeepUnsentText(text)} root=${describeViewBrief(rowRoot)}")
        rememberKeepUnsentVisibleRowTextMapping(rowRoot, text)
        rememberKeepUnsentRecentRowText(rowRoot, emptySet(), text, collectIdsIfMissing = false)
        val textDeletedAt = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts[text] ?: 0L }
        if (textDeletedAt <= 0L) return
        val rowIds = extractRowBindableIds(collectKeepUnsentViewRowIds(rowRoot, rowRoot) + collectKeepUnsentRecyclerHolderIds(rowRoot))
        val idDeletedAt = if (rowIds.isEmpty()) 0L else keepUnsentDeletedAt(rowIds)
        val deletedAt = when {
            idDeletedAt > 0L -> maxOf(idDeletedAt, textDeletedAt)
            rowIds.isNotEmpty() -> 0L
            shouldApplyKeepUnsentTextOnlyMarker(rowRoot, text) -> textDeletedAt
            else -> 0L
        }
        if (deletedAt > 0L) applyKeepUnsentDeletedMarker(rowRoot, deletedAt)
    }

    private fun rememberKeepUnsentDeletedTexts(texts: Collection<String>, deletedAt: Long) {
        var added = 0
        var changed = false
        synchronized(keepUnsentDeletedTexts) {
            texts.mapNotNull(::normalizeKeepUnsentMessageText).forEach { text ->
                if (!isPersistableKeepUnsentDeletedText(text)) return@forEach
                if (!keepUnsentDeletedTexts.containsKey(text)) added++
                if (keepUnsentDeletedTexts[text] != deletedAt) changed = true
                keepUnsentDeletedTexts[text] = deletedAt
            }
        }
        logKeepUnsentDebug("remember-deleted-texts normalized=${formatKeepUnsentTexts(texts)} added=$added")
        if (changed) {
            markKeepUnsentPersistDirty(androidContext, "deleted-texts")
        }
        if (added > 0) logInfo("Marked unsent Direct message texts: $added")
    }

    private fun rememberKeepUnsentDirectTextViewBinding(textView: TextView) {
        val text = normalizeKeepUnsentMessageText(textView.text) ?: return
        if (!isPersistableKeepUnsentDeletedText(text)) return
        val rowRoot = nearestKeepUnsentRowRoot(textView) ?: textView
        logKeepUnsentDebug("direct-text binding text=${formatKeepUnsentText(text)} row=${describeViewBrief(rowRoot)}")
        rememberKeepUnsentVisibleRowTextMapping(rowRoot, text)
        rememberKeepUnsentRecentRowText(rowRoot, emptySet(), text, collectIdsIfMissing = false)
    }

    private fun rememberKeepUnsentVisibleRowTextMapping(rowRoot: View, text: String) {
        synchronized(keepUnsentVisibleRowsByText) {
            val rows = keepUnsentVisibleRowsByText.getOrPut(text) { mutableListOf() }
            rows.removeAll { ref ->
                val row = ref.get()
                row == null || row.parent == null || row === rowRoot || keepUnsentRowMessageText(row) != text
            }
            rows += WeakReference(rowRoot)
            while (rows.size > 4) rows.removeAt(0)
        }
    }

    private fun rememberKeepUnsentRecentRowText(
        rowRoot: View,
        ids: Set<String> = emptySet(),
        rawText: String? = null,
        collectIdsIfMissing: Boolean = true
    ) {
        val text = normalizeKeepUnsentMessageText(rawText ?: keepUnsentRowMessageText(rowRoot)) ?: return
        if (!isPersistableKeepUnsentDeletedText(text)) return
        val now = System.currentTimeMillis()
        val bounds = Rect()
        val boundsSource = findKeepUnsentDirectTextView(rowRoot) ?: rowRoot
        val hasBounds = boundsSource.getGlobalVisibleRect(bounds) || rowRoot.getGlobalVisibleRect(bounds)
        val entry = KeepUnsentRecentText(
            text = text,
            atMs = now,
            left = if (hasBounds) bounds.left else -1,
            top = if (hasBounds) bounds.top else -1,
            right = if (hasBounds) bounds.right else -1,
            bottom = if (hasBounds) bounds.bottom else -1
        )
        keepUnsentRecentTextByRow[rowRoot] = entry
        val rowIds = extractRowBindableIds(
            if (ids.isEmpty() && collectIdsIfMissing) {
                collectKeepUnsentViewRowIds(rowRoot, rowRoot) + collectKeepUnsentRecyclerHolderIds(rowRoot)
            } else {
                ids
            }
        )
        logKeepUnsentDebug(
            "recent-row-text stored text=${formatKeepUnsentText(text)} ids=${formatKeepUnsentIds(rowIds)} bounds=${entry.left},${entry.top},${entry.right},${entry.bottom} row=${describeViewBrief(rowRoot)}"
        )
        if (rowIds.isEmpty()) return
        synchronized(keepUnsentRecentTextById) {
            rowIds.forEach { rawId ->
                val id = rawId.trim()
                if (id.isNotBlank() && !keepUnsentAmbiguousBoundIds.contains(id)) keepUnsentRecentTextById[id] = entry
            }
        }
    }

    private fun recentKeepUnsentTextsForIds(ids: Collection<String>): List<String> {
        val lookupIds = (extractDeletedMessageIds(ids) + extractRowBindableIds(ids))
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinct()
        if (lookupIds.isEmpty()) return emptyList()
        val now = System.currentTimeMillis()
        val output = LinkedHashSet<String>()
        synchronized(keepUnsentRecentTextById) {
            lookupIds.forEach { id ->
                keepUnsentRecentTextById[id]
                    ?.takeIf { now - it.atMs in 0L..KEEP_UNSENT_RECENT_TEXT_TTL_MS }
                    ?.let { output += it.text }
            }
            if (output.isEmpty()) {
                keepUnsentRecentTextById.forEach { (boundId, entry) ->
                    if (now - entry.atMs !in 0L..KEEP_UNSENT_RECENT_TEXT_TTL_MS) return@forEach
                    if (lookupIds.any { lookup -> idsLikelyMatch(boundId, lookup) }) output += entry.text
                }
            }
        }
        if (output.isNotEmpty()) logInfo("Recovered keep-unsent Direct text from recent ids: ${output.size}")
        return output.toList()
    }

    private fun recentKeepUnsentTextNearLastTouch(): String? {
        val touchAge = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
        if (touchAge !in 0..30_000L) return null
        val x = dmLastMessageActionTouchX.toInt()
        val y = dmLastMessageActionTouchY.toInt()
        if (x < 0 || y < 0) return null
        currentActivity?.window?.decorView?.let { root ->
            keepUnsentAccessibilityTextAtPoint(root, x, y)?.let { return it }
        }
        val now = System.currentTimeMillis()
        val entries = LinkedHashSet<KeepUnsentRecentText>()
        synchronized(keepUnsentRecentTextByRow) {
            entries += keepUnsentRecentTextByRow.values.filter { now - it.atMs in 0L..KEEP_UNSENT_RECENT_TEXT_TTL_MS }
        }
        synchronized(keepUnsentRecentTextById) {
            entries += keepUnsentRecentTextById.values.filter { now - it.atMs in 0L..KEEP_UNSENT_RECENT_TEXT_TTL_MS }
        }
        if (entries.isEmpty()) {
            logInfo("Keep-unsent recent text recovery failed: cache empty touchAge=$touchAge x=$x y=$y")
            return null
        }
        val touchSlop = dp(currentActivity?.window?.decorView ?: return null, 72)
        val nearTouch = entries
            .filter { it.hasBounds && x in (it.left - touchSlop)..(it.right + touchSlop) && y in (it.top - touchSlop)..(it.bottom + touchSlop) }
            .minByOrNull { it.distanceTo(x, y) }
        val chosen = nearTouch ?: entries.maxByOrNull { it.atMs }?.takeIf { now - it.atMs <= 2 * 60 * 1000L }
        if (chosen != null) {
            logInfo(
                "Recovered keep-unsent Direct text from recent visible row text=${formatKeepUnsentText(chosen.text)} " +
                    "nearTouch=${nearTouch != null} distance=${chosen.distanceTo(x, y)} entries=${entries.size}"
            )
        } else {
            logInfo("Keep-unsent recent text recovery failed: no near/fresh row touchAge=$touchAge entries=${entries.size} x=$x y=$y")
        }
        return chosen?.text
    }

    private fun keepUnsentAccessibilityTextAtPoint(root: View, rawX: Int, rawY: Int): String? {
        return runCatching {
            val hits = ArrayList<Pair<String, Int>>()
            val decorNodes = intArrayOf(0)
            val node = root.createAccessibilityNodeInfo()
            if (node != null) {
                try {
                    collectKeepUnsentAccessibilityTextHits(node, rawX, rawY, hits, intArrayOf(1_200), decorNodes)
                } finally {
                    node.recycle()
                }
            }
            val providerStats = intArrayOf(0, 0, 0)
            if (hits.isEmpty()) {
                collectKeepUnsentAccessibilityProviderTextHits(
                    root,
                    rawX,
                    rawY,
                    hits,
                    viewBudget = intArrayOf(600),
                    nodeBudget = intArrayOf(1_200),
                    stats = providerStats
                )
            }
            val chosen = hits.minByOrNull { it.second }?.first
            if (chosen != null) {
                logInfo(
                    "Recovered keep-unsent Direct text from accessibility touch text=${formatKeepUnsentText(chosen)} " +
                        "x=$rawX y=$rawY hits=${hits.size} decorNodes=${decorNodes[0]} providerViews=${providerStats[0]} " +
                        "providers=${providerStats[1]} providerNodes=${providerStats[2]}"
                )
            } else {
                logInfo(
                    "Keep-unsent accessibility touch found no message text x=$rawX y=$rawY decorNodes=${decorNodes[0]} " +
                        "providerViews=${providerStats[0]} providers=${providerStats[1]} providerNodes=${providerStats[2]}"
                )
            }
            chosen
        }.getOrElse {
            logError("Keep-unsent accessibility touch recovery failed", it)
            null
        }
    }

    private fun collectKeepUnsentAccessibilityTextHits(
        node: AccessibilityNodeInfo?,
        rawX: Int,
        rawY: Int,
        hits: MutableList<Pair<String, Int>>,
        budget: IntArray,
        visited: IntArray? = null,
        visitedIndex: Int = 0
    ) {
        if (node == null || budget[0]-- <= 0) return
        visited?.let { it[visitedIndex]++ }
        val rect = Rect()
        runCatching { node.getBoundsInScreen(rect) }
        if (!rect.isEmpty && rect.contains(rawX, rawY)) {
            val viewId = runCatching { node.viewIdResourceName.orEmpty() }.getOrDefault("")
            val text = node.text?.toString().orEmpty()
            val description = node.contentDescription?.toString().orEmpty()
            keepUnsentAccessibilityMessageText(text, description, viewId)?.let { normalized ->
                hits += normalized to (rect.width().coerceAtLeast(1) * rect.height().coerceAtLeast(1))
            }
        }
        for (i in 0 until node.childCount) {
            val child = runCatching { node.getChild(i) }.getOrNull() ?: continue
            try {
                collectKeepUnsentAccessibilityTextHits(child, rawX, rawY, hits, budget, visited, visitedIndex)
            } finally {
                child.recycle()
            }
            if (budget[0] <= 0) return
        }
    }

    private fun collectKeepUnsentAccessibilityProviderTextHits(
        view: View?,
        rawX: Int,
        rawY: Int,
        hits: MutableList<Pair<String, Int>>,
        viewBudget: IntArray,
        nodeBudget: IntArray,
        stats: IntArray
    ) {
        if (view == null || viewBudget[0]-- <= 0 || view.visibility != View.VISIBLE) return
        val rect = Rect()
        if (!view.getGlobalVisibleRect(rect) || rect.isEmpty || !rect.contains(rawX, rawY)) return
        stats[0]++
        val provider = runCatching { view.accessibilityNodeProvider }.getOrNull()
        if (provider != null) {
            stats[1]++
            val beforeHits = hits.size
            val providerNode = runCatching {
                provider.createAccessibilityNodeInfo(AccessibilityNodeProvider.HOST_VIEW_ID)
            }.getOrNull()
            if (providerNode != null) {
                try {
                    collectKeepUnsentAccessibilityTextHits(providerNode, rawX, rawY, hits, nodeBudget, stats, 2)
                } finally {
                    providerNode.recycle()
                }
            }
            if (hits.size == beforeHits && nodeBudget[0] > 0) {
                val searched = runCatching {
                    provider.findAccessibilityNodeInfosByText("", AccessibilityNodeProvider.HOST_VIEW_ID).orEmpty()
                }.getOrDefault(emptyList())
                searched.asSequence().take(120).forEach { node ->
                    try {
                        collectKeepUnsentAccessibilityTextHits(node, rawX, rawY, hits, nodeBudget, stats, 2)
                    } finally {
                        node.recycle()
                    }
                    if (nodeBudget[0] <= 0) return@forEach
                }
            }
        }
        if (view is ViewGroup) {
            for (i in view.childCount - 1 downTo 0) {
                collectKeepUnsentAccessibilityProviderTextHits(view.getChildAt(i), rawX, rawY, hits, viewBudget, nodeBudget, stats)
                if (viewBudget[0] <= 0 || nodeBudget[0] <= 0) return
            }
        }
    }

    private fun keepUnsentAccessibilityMessageText(text: String, description: String, viewId: String): String? {
        val raw = text.ifBlank { description }
        val normalized = normalizeKeepUnsentMessageText(raw) ?: return null
        if (!isPersistableKeepUnsentDeletedText(normalized)) return null
        val lower = normalized.lowercase(Locale.US)
        if (lower.startsWith("double tap to") || lower.startsWith("view photo") || lower.startsWith("view video")) return null
        val lowerDesc = description.lowercase(Locale.US)
        if (lowerDesc.startsWith("view photo") || lowerDesc.startsWith("view video")) return null
        val lowerId = viewId.lowercase(Locale.US)
        if (lowerId.contains("visual") ||
            lowerId.contains("digest") ||
            lowerId.contains("footer") ||
            lowerId.contains("header") ||
            lowerId.contains("username") ||
            lowerId.contains("profile_attribution") ||
            lowerId.endsWith("/title_text") ||
            lowerId.endsWith(":id/title_text")
        ) {
            return null
        }
        return normalized
    }

    private fun isPersistableKeepUnsentDeletedText(text: String): Boolean {
        val normalized = normalizeKeepUnsentMessageText(text) ?: return false
        return normalized.length >= MIN_KEEP_UNSENT_PERSISTED_TEXT_LENGTH &&
            !isDmMessageActionMenuOrChromeText(normalized)
    }

    private fun markRecentKeepUnsentNativeUnsend(root: View? = null, rawX: Float? = null, rawY: Float? = null, retryAfterOverlayClose: Boolean = false) {
        val existingLastText = keepUnsentLastActionRowText
        if (existingLastText == null || !isPersistableKeepUnsentDeletedText(existingLastText)) {
            rememberNewestVisibleKeepUnsentActionRow("native-unsend")
        }
        val deletedAt = System.currentTimeMillis()
        val overlayActive = root?.let { rootContainsActiveDmMessageActionsOverlay(it) || hasPurrfectDmActionRowsVisible(it) } == true
        val snapshotRow = keepUnsentLastActionRowRoot?.get()
            ?.let { nearestKeepUnsentRowRoot(it) }
            ?.takeIf(::hasKeepUnsentDirectTextRow)
        val touchRow = findKeepUnsentRowNearLastMessageActionTouch()
            ?.takeIf(::hasKeepUnsentDirectTextRow)
        val pointRow = if (!overlayActive && root != null && rawX != null && rawY != null) {
            findKeepUnsentRowAtScreenPoint(root, rawX, rawY)?.takeIf(::hasKeepUnsentDirectTextRow)
        } else {
            null
        }
        val rowRoot = snapshotRow ?: touchRow ?: pointRow
        val lastActionText = keepUnsentLastActionRowText?.takeIf(::isPersistableKeepUnsentDeletedText)
        val rowIds = rowRoot?.let { collectKeepUnsentViewRowIds(it, it) + collectKeepUnsentRecyclerHolderIds(it) }.orEmpty()
        val rowMatchesActionSnapshot = rowRoot != null && (
            rowRoot === snapshotRow ||
                rowRoot === touchRow ||
                (rowIds.isNotEmpty() && keepUnsentLastActionRowIds.any { snapshotId ->
                    rowIds.any { rowId -> rowId == snapshotId || idsLikelyMatch(rowId, snapshotId) }
                })
            )
        val trustedRowIds = if (rowMatchesActionSnapshot) rowIds else emptySet()
        val rowText = if (rowMatchesActionSnapshot) rowRoot?.let { keepUnsentRowMessageText(it) } else null
        val deletedIds = extractDeletedMessageIds(trustedRowIds + keepUnsentLastActionRowIds)
        val cachedTexts = recentKeepUnsentTextsForIds(trustedRowIds + keepUnsentLastActionRowIds)
            .filter(::isPersistableKeepUnsentDeletedText)
        val touchRecoveredText = if (deletedIds.isEmpty() && rowMatchesActionSnapshot && rowText == null && lastActionText == null && cachedTexts.isEmpty()) {
            recentKeepUnsentTextNearLastTouch()
        } else {
            null
        }
        val deletedTexts = (listOfNotNull(rowText, lastActionText, touchRecoveredText) + cachedTexts)
            .mapNotNull(::normalizeKeepUnsentMessageText)
            .filter(::isPersistableKeepUnsentDeletedText)
            .distinct()
        logInfo(
            "Keep-unsent native-unsend summary retry=$retryAfterOverlayClose root=${describeViewBrief(root)} row=${describeViewBrief(rowRoot)} " +
                "raw=${rawX?.toInt() ?: -1},${rawY?.toInt() ?: -1} rowText=${formatKeepUnsentText(rowText)} " +
                "lastText=${formatKeepUnsentText(lastActionText)} cachedTexts=${formatKeepUnsentTexts(cachedTexts)} " +
                "touchText=${formatKeepUnsentText(touchRecoveredText)} rowIds=${formatKeepUnsentIds(rowIds)} " +
                "rowMatches=$rowMatchesActionSnapshot lastIds=${formatKeepUnsentIds(keepUnsentLastActionRowIds)} deletedIds=${formatKeepUnsentIds(deletedIds)} " +
                "deletedTexts=${formatKeepUnsentTexts(deletedTexts)}"
        )

        if (deletedIds.isNotEmpty()) {
            var changed = false
            synchronized(keepUnsentDeletedIds) {
                deletedIds.forEach { id ->
                    val key = id.trim()
                    if (keepUnsentDeletedIds[key] != deletedAt) changed = true
                    keepUnsentDeletedIds[key] = deletedAt
                }
            }
            if (changed) {
                markKeepUnsentPersistDirty(androidContext, "native-unsend-ids")
            }
            rememberKeepUnsentTemporalDeleteCandidate(deletedAt)
            decorateKeepUnsentBoundRows(deletedIds)
            mainHandler.postDelayed({ decorateKeepUnsentBoundRows(deletedIds) }, 220L)
        }

        if (deletedTexts.isNotEmpty()) {
            rememberKeepUnsentDeletedTexts(deletedTexts, deletedAt)
            deletedTexts.forEach { persistKeepUnsentDeletedTextOnce(androidContext, it, deletedAt) }
            decorateKeepUnsentTextRows(deletedTexts, deletedAt)
            scheduleKeepUnsentTextDecorationRetries(deletedTexts, deletedAt)
        } else {
            logInfo("Keep-unsent native-unsend had no recoverable message text; marker may be visual-only unless rendered sweep recovers it")
        }
        val decorated = decorateRecentKeepUnsentActionAnchor(deletedAt, deletedIds, deletedTexts)
        logInfo("Keep-unsent native-unsend decoration decorated=$decorated rowPresent=${rowRoot != null} texts=${deletedTexts.size} ids=${deletedIds.size}")
        if (!decorated && rowMatchesActionSnapshot && hasKeepUnsentDirectTextRow(rowRoot)) {
            val stableRowText = rowText ?: lastActionText ?: rowRoot?.let { keepUnsentRowMessageText(it) }
            if (stableRowText != null) {
                logInfo("Keep-unsent native-unsend applying direct row fallback text=${formatKeepUnsentText(stableRowText)}")
                rememberKeepUnsentDeletedTexts(listOf(stableRowText), deletedAt)
                persistKeepUnsentDeletedTextOnce(rowRoot!!.context, stableRowText, deletedAt)
                scheduleKeepUnsentTextDecorationRetries(listOf(stableRowText), deletedAt)
            } else {
                logInfo("Keep-unsent native-unsend direct row fallback had no stable text row=${describeViewBrief(rowRoot)}")
            }
            applyKeepUnsentDeletedMarker(rowRoot!!, deletedAt)
        }
        scanVisibleKeepUnsentRowsSoon("native-unsend", 0L)
        scanVisibleKeepUnsentRowsSoon("native-unsend-retry", 180L)
        schedulePersistVisibleKeepUnsentRenderedMarkers("native-unsend")
        mainHandler.postDelayed({ decorateRecentKeepUnsentActionAnchor(deletedAt, deletedIds, deletedTexts) }, 220L)
        if (!retryAfterOverlayClose && rawX != null && rawY != null && deletedIds.isEmpty()) {
            val tapX = rawX
            val tapY = rawY
            mainHandler.postDelayed({
                val latestRoot = currentActivity?.window?.decorView ?: root
                if (latestRoot != null) markRecentKeepUnsentNativeUnsend(latestRoot, tapX, tapY, retryAfterOverlayClose = true)
            }, 90L)
        }
    }

    private fun findKeepUnsentRowAtScreenPoint(root: View, rawX: Float, rawY: Float): View? {
        findKeepUnsentLooseTextRowAtScreenPoint(root, rawX.toInt(), rawY.toInt(), intArrayOf(900))?.let { return it }
        findKeepUnsentTextRowAtScreenPoint(root, rawX.toInt(), rawY.toInt(), intArrayOf(900))?.let { return it }
        val rows = ArrayList<View>()
        collectVisibleKeepUnsentTextRowRoots(root, rows, intArrayOf(650))
        val rect = Rect()
        val distinct = rows.distinctBy { System.identityHashCode(it) }
        distinct.firstOrNull { row ->
            row.getGlobalVisibleRect(rect) && rect.contains(rawX.toInt(), rawY.toInt())
        }?.let { return it }
        return distinct
            .filter { row ->
                row.getGlobalVisibleRect(rect) &&
                    rawY.toInt() in (rect.top - dp(row, 36))..(rect.bottom + dp(row, 36)) &&
                    rawX >= rect.left - dp(row, 48) &&
                    rawX <= rect.right + dp(row, 48)
            }
            .minByOrNull { row ->
                row.getGlobalVisibleRect(rect)
                abs(rect.centerY() - rawY.toInt())
            }
    }

    private fun findKeepUnsentTextRowAtScreenPoint(view: View?, rawX: Int, rawY: Int, budget: IntArray): View? {
        if (view == null || budget[0]-- <= 0 || view.visibility != View.VISIBLE) return null
        val rect = Rect()
        if (!view.getGlobalVisibleRect(rect) || !rect.contains(rawX, rawY)) return null
        if (view is TextView && isKeepUnsentMessageTextCandidate(view)) {
            nearestKeepUnsentRowRoot(view)?.let { return it }
        }
        if (view is ViewGroup) {
            for (i in view.childCount - 1 downTo 0) {
                findKeepUnsentTextRowAtScreenPoint(view.getChildAt(i), rawX, rawY, budget)?.let { return it }
                if (budget[0] <= 0) return null
            }
        }
        return null
    }

    private fun findKeepUnsentLooseTextRowAtScreenPoint(view: View?, rawX: Int, rawY: Int, budget: IntArray): View? {
        if (view == null || budget[0]-- <= 0 || view.visibility != View.VISIBLE) return null
        val rect = Rect()
        if (view is TextView && isKeepUnsentMessageTextCandidate(view) && view.getGlobalVisibleRect(rect) && rect.contains(rawX, rawY)) {
            nearestKeepUnsentRowRoot(view)?.let { return it }
        }
        if (view is ViewGroup) {
            for (i in view.childCount - 1 downTo 0) {
                findKeepUnsentLooseTextRowAtScreenPoint(view.getChildAt(i), rawX, rawY, budget)?.let { return it }
                if (budget[0] <= 0) return null
            }
        }
        return null
    }

    private fun decorateRecentKeepUnsentActionAnchor(
        deletedAt: Long,
        deletedIds: Set<String>,
        deletedTexts: Collection<String> = emptySet()
    ): Boolean {
        val normalizedDeletedTexts = deletedTexts.mapNotNull(::normalizeKeepUnsentMessageText).toSet()
        val candidates = listOfNotNull(
            keepUnsentLastActionRowRoot?.get(),
            findKeepUnsentRowNearLastMessageActionTouch(),
            recentDmMessageActionAnchor()
        ).distinctBy { System.identityHashCode(nearestKeepUnsentRowRoot(it) ?: it) }
        logKeepUnsentDebug("decorate-anchor candidates=${candidates.size} ids=${formatKeepUnsentIds(deletedIds)} texts=${formatKeepUnsentTexts(normalizedDeletedTexts)}")
        candidates.forEach { anchor ->
            val rowRoot = nearestKeepUnsentRowRoot(anchor) ?: return@forEach
            if (findViewByResourceName(rowRoot, "direct_text_message_text_view") == null) return@forEach
            val rowText = keepUnsentRowMessageText(rowRoot)
            val rowIds = collectKeepUnsentViewRowIds(rowRoot, rowRoot) + collectKeepUnsentRecyclerHolderIds(rowRoot)
            val idsMatch = rowIds.isNotEmpty() && deletedIds.any { rowIds.contains(it) }
            val textMatches = rowText != null && rowText in normalizedDeletedTexts
            val touchMatches = isLastMessageActionTouchInsideRow(rowRoot)
            val recentActionMatches = isRecentKeepUnsentActionRow(rowRoot, rowIds, rowText)
            logKeepUnsentDebug(
                "decorate-anchor candidate row=${describeViewBrief(rowRoot)} rowText=${formatKeepUnsentText(rowText)} " +
                    "rowIds=${formatKeepUnsentIds(rowIds)} idsMatch=$idsMatch textMatch=$textMatches touchMatch=$touchMatches recentMatch=$recentActionMatches"
            )
            if (!idsMatch && !textMatches && !touchMatches && !recentActionMatches) return@forEach
            rowText?.let { text ->
                rememberKeepUnsentVisibleTextRow(rowRoot)
                rememberKeepUnsentDeletedTexts(listOf(text), deletedAt)
                persistKeepUnsentDeletedTextOnce(rowRoot.context, text, deletedAt)
            }
            applyKeepUnsentDeletedMarker(rowRoot, deletedAt)
            return true
        }
        return false
    }

    private fun isRecentKeepUnsentActionRow(rowRoot: View, rowIds: Set<String>, rowText: String?): Boolean {
        val age = System.currentTimeMillis() - keepUnsentLastActionRowAtMs
        if (age !in 0..30_000L) return false
        keepUnsentLastActionRowRoot?.get()?.let { if (it === rowRoot) return true }
        val snapshotIds = keepUnsentLastActionRowIds
        if (snapshotIds.isNotEmpty() && rowIds.any { it in snapshotIds }) return true
        val snapshotText = keepUnsentLastActionRowText
        return snapshotText != null && rowText != null && snapshotText == rowText && isLastMessageActionTouchInsideRow(rowRoot)
    }

    private fun isLastMessageActionTouchInsideRow(rowRoot: View): Boolean {
        val age = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
        if (age !in 0..15_000L) return false
        val x = dmLastMessageActionTouchX.toInt()
        val y = dmLastMessageActionTouchY.toInt()
        if (x < 0 || y < 0) return false
        val rect = Rect()
        return rowRoot.getGlobalVisibleRect(rect) && rect.contains(x, y)
    }

    private fun findKeepUnsentRowNearLastMessageActionTouch(): View? {
        val age = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
        if (age !in 0..15_000L) return null
        val x = dmLastMessageActionTouchX.toInt()
        val y = dmLastMessageActionTouchY.toInt()
        if (x < 0 || y < 0) return null
        val root = currentActivity?.window?.decorView ?: return null
        val rows = ArrayList<View>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        collectVisibleKeepUnsentTextRowRoots(scanRoot, rows, intArrayOf(650))
        val distinct = rows.distinctBy { System.identityHashCode(it) }
        val rect = Rect()
        distinct.forEach { row ->
            if (row.getGlobalVisibleRect(rect) && rect.contains(x, y)) return row
        }
        return distinct
            .filter { it.getGlobalVisibleRect(rect) && y in (rect.top - dp(it, 24))..(rect.bottom + dp(it, 24)) }
            .minByOrNull {
                it.getGlobalVisibleRect(rect)
                val cx = rect.centerX()
                abs(cx - x)
            }
    }

    private fun findKeepUnsentRowNearViewCenter(view: View): View? {
        val rect = Rect()
        if (!view.getGlobalVisibleRect(rect)) return null
        val root = view.rootView ?: currentActivity?.window?.decorView ?: return null
        return findKeepUnsentRowAtScreenPoint(root, rect.centerX().toFloat(), rect.centerY().toFloat())
    }

    private fun decorateKeepUnsentTextRows(texts: Collection<String>, deletedAt: Long) {
        val normalized = texts.mapNotNull(::normalizeKeepUnsentMessageText).distinct()
        if (normalized.isEmpty()) {
            logKeepUnsentDebug("decorate-text skipped: no normalized texts raw=${formatKeepUnsentTexts(texts)}")
            return
        }
        val broadNormalized = normalized.filter(::isPersistableKeepUnsentDeletedText)
        if (broadNormalized.isEmpty()) {
            logKeepUnsentDebug("decorate-text skipped broad scan for ambiguous short text=${formatKeepUnsentTexts(normalized)}")
            return
        }
        val views = ArrayList<View>()
        synchronized(keepUnsentVisibleRowsByText) {
            broadNormalized.forEach { text ->
                val rows = keepUnsentVisibleRowsByText[text] ?: return@forEach
                rows.removeAll { it.get()?.parent == null }
                rows.lastOrNull()?.get()?.let { views += it }
            }
        }
        logKeepUnsentDebug("decorate-text mapMatches=${views.size} wanted=${formatKeepUnsentTexts(broadNormalized)}")
        if (views.isEmpty()) {
            val scanned = findVisibleKeepUnsentTextRows(broadNormalized)
            logKeepUnsentDebug("decorate-text scanMatches=${scanned.size} wanted=${formatKeepUnsentTexts(broadNormalized)}")
            views += scanned
        }
        if (views.isEmpty()) {
            logKeepUnsentDebug("decorate-text skipped: no exact visible row for ${formatKeepUnsentTexts(broadNormalized)}")
            return
        }
        views.distinctBy { System.identityHashCode(it) }.forEach {
            logKeepUnsentDebug("decorate-text applying rowText=${formatKeepUnsentText(keepUnsentRowMessageText(it))} root=${describeViewBrief(it)}")
            applyKeepUnsentDeletedMarker(it, deletedAt)
        }
    }

    private fun scheduleKeepUnsentTextDecorationRetries(texts: Collection<String>, deletedAt: Long) {
        val normalized = texts.mapNotNull(::normalizeKeepUnsentMessageText).distinct()
        if (normalized.isEmpty() || deletedAt <= 0L) return
        listOf(120L, 350L, 900L, 1_600L).forEach { delay ->
            mainHandler.postDelayed({
                if (state.keepUnsentMessages) decorateKeepUnsentTextRows(normalized, deletedAt)
            }, delay)
        }
    }

    private fun findVisibleKeepUnsentTextRows(texts: Collection<String>): List<View> {
        val root = currentActivity?.window?.decorView ?: return emptyList()
        val wanted = texts.toSet()
        val out = ArrayList<View>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        findVisibleKeepUnsentTextRows(scanRoot, wanted, out, intArrayOf(650))
        return out.distinctBy { System.identityHashCode(it) }.takeLast(2)
    }

    private fun shouldApplyKeepUnsentTextOnlyMarker(rowRoot: View, text: String): Boolean {
        val now = System.currentTimeMillis()
        val recent = synchronized(keepUnsentRecentTextByRow) {
            keepUnsentRecentTextByRow[rowRoot]?.takeIf { it.text == text && now - it.atMs in 0L..KEEP_UNSENT_RECENT_TEXT_TTL_MS }
        }
        if (recent == null) {
            logKeepUnsentDebug("text-only marker skipped: row not recently bound text=${formatKeepUnsentText(text)} row=${describeViewBrief(rowRoot)}")
            return false
        }
        val visibleMatches = countVisibleKeepUnsentRowsWithText(text, 2)
        if (visibleMatches > 1) {
            logKeepUnsentDebug("text-only marker skipped: duplicate visible rows=$visibleMatches text=${formatKeepUnsentText(text)}")
            return false
        }
        return true
    }

    private fun countVisibleKeepUnsentRowsWithText(text: String, limit: Int): Int {
        val root = currentActivity?.window?.decorView ?: return 0
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        val seen = Collections.newSetFromMap(IdentityHashMap<View, Boolean>())
        fun visit(view: View?, budget: IntArray): Int {
            if (view == null || budget[0]-- <= 0 || !view.isShown) return 0
            var count = 0
            if (view is TextView && isKeepUnsentMessageTextCandidate(view) && normalizeKeepUnsentMessageText(view.text) == text) {
                val row = nearestKeepUnsentRowRoot(view) ?: view
                if (seen.add(row)) count++
                if (count >= limit) return count
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) {
                    count += visit(view.getChildAt(i), budget)
                    if (count >= limit) return count
                }
            }
            return count
        }
        return visit(scanRoot, intArrayOf(650))
    }

    private fun findVisibleKeepUnsentTextRows(view: View?, texts: Set<String>, out: MutableList<View>, budget: IntArray) {
        if (view == null || budget[0]-- <= 0 || !view.isShown) return
        if (view is TextView && isKeepUnsentMessageTextCandidate(view)) {
            val text = normalizeKeepUnsentMessageText(view.text)
            if (text != null && text in texts) {
                nearestKeepUnsentRowRoot(view)?.let { out += it }
                logKeepUnsentDebug("visible-scan exact text=${formatKeepUnsentText(text)} view=${describeViewBrief(view)}")
            } else if (text != null) {
                logKeepUnsentDebug("visible-scan candidate text=${formatKeepUnsentText(text)} wanted=${formatKeepUnsentTexts(texts)}")
            }
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                findVisibleKeepUnsentTextRows(view.getChildAt(i), texts, out, budget)
                if (budget[0] <= 0) return
            }
        }
    }

    private fun collectVisibleKeepUnsentTextRowRoots(view: View?, out: MutableList<View>, budget: IntArray) {
        if (view == null || budget[0]-- <= 0 || !view.isShown) return
        if (view is TextView && isKeepUnsentMessageTextCandidate(view)) {
            nearestKeepUnsentRowRoot(view)?.let { out += it }
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                collectVisibleKeepUnsentTextRowRoots(view.getChildAt(i), out, budget)
                if (budget[0] <= 0) return
            }
        }
    }

    private fun isKeepUnsentDirectTextView(view: TextView): Boolean {
        if (resourceEntryName(view) == "direct_text_message_text_view") return true
        val text = normalizeKeepUnsentMessageText(view.text) ?: return false
        if (!isPersistableKeepUnsentDeletedText(text) || isDmMessageActionMenuOrChromeText(text)) return false
        if (hasKeepUnsentVisualMessageAncestor(view)) return false
        val rowRoot = nearestKeepUnsentRowRoot(view) ?: return false
        val descriptor = monetViewDescriptor(rowRoot).lowercase(Locale.US)
        return descriptor.contains("message") || descriptor.contains("direct")
    }

    private fun findNewestVisibleIncomingKeepUnsentRow(): View? {
        val root = currentActivity?.window?.decorView ?: return null
        val rows = ArrayList<View>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        collectVisibleIncomingKeepUnsentRows(scanRoot, rows, intArrayOf(650))
        return rows.distinctBy { System.identityHashCode(it) }.lastOrNull()
    }

    private fun rememberKeepUnsentTemporalDeleteCandidate(deletedAt: Long) {
        val baseline = snapshotVisibleIncomingKeepUnsentTextCounts()
        synchronized(keepUnsentPendingTemporalDeletes) {
            keepUnsentPendingTemporalDeletes += KeepUnsentPendingDelete(deletedAt, baseline, System.currentTimeMillis())
            while (keepUnsentPendingTemporalDeletes.size > 4) keepUnsentPendingTemporalDeletes.removeAt(0)
        }
        logKeepUnsentDebug("temporal-delete baseline=${baseline.entries.joinToString(",") { "${formatKeepUnsentText(it.key)}:${it.value}" }}")
    }

    private fun snapshotVisibleIncomingKeepUnsentTextCounts(): Map<String, Int> {
        val root = currentActivity?.window?.decorView ?: return emptyMap()
        val rows = ArrayList<View>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        collectVisibleIncomingKeepUnsentRows(scanRoot, rows, intArrayOf(650))
        val counts = LinkedHashMap<String, Int>()
        rows.forEach { row ->
            val text = keepUnsentRowMessageText(row) ?: return@forEach
            counts[text] = (counts[text] ?: 0) + 1
        }
        return counts
    }

    private fun resolveKeepUnsentTemporalDeleteCandidates() {
        val pending = synchronized(keepUnsentPendingTemporalDeletes) { keepUnsentPendingTemporalDeletes.toList() }
        if (pending.isEmpty()) return
        val root = currentActivity?.window?.decorView ?: return
        val rows = ArrayList<View>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        collectVisibleIncomingKeepUnsentRows(scanRoot, rows, intArrayOf(650))
        val rowsByText = LinkedHashMap<String, MutableList<View>>()
        rows.distinctBy { System.identityHashCode(it) }.forEach { row ->
            val text = keepUnsentRowMessageText(row) ?: return@forEach
            rowsByText.getOrPut(text) { mutableListOf() } += row
        }
        val now = System.currentTimeMillis()
        val resolved = ArrayList<KeepUnsentPendingDelete>()
        pending.forEach { event ->
            var chosen: View? = null
            var chosenText: String? = null
            rowsByText.forEach { (text, textRows) ->
                val extra = textRows.size - (event.baselineCounts[text] ?: 0)
                if (extra > 0) {
                    chosen = textRows.takeLast(extra).lastOrNull()
                    chosenText = text
                }
            }
            if (chosen != null) {
                logKeepUnsentDebug(
                    "temporal-delete applying text=${formatKeepUnsentText(chosenText)} root=${describeViewBrief(chosen)}"
                )
                chosenText?.let { text ->
                    rememberKeepUnsentDeletedTexts(listOf(text), event.deletedAt)
                }
                applyKeepUnsentDeletedMarker(chosen, event.deletedAt)
                resolved += event
            } else if (now - event.createdAt > 5_000L) {
                logKeepUnsentDebug("temporal-delete expired rows=${rowsByText.mapValues { it.value.size }}")
                resolved += event
            }
        }
        if (resolved.isNotEmpty()) {
            synchronized(keepUnsentPendingTemporalDeletes) {
                keepUnsentPendingTemporalDeletes.removeAll(resolved.toSet())
            }
        }
    }

    private fun collectVisibleIncomingKeepUnsentRows(view: View?, out: MutableList<View>, budget: IntArray) {
        if (view == null || budget[0]-- <= 0 || !view.isShown) return
        if (view is TextView && resourceEntryName(view) == "direct_text_message_text_view") {
            val rowRoot = nearestKeepUnsentRowRoot(view)
            val text = normalizeKeepUnsentMessageText(view.text)
            if (rowRoot != null && text != null && findViewByResourceName(rowRoot, "sender_avatar") != null) {
                out += rowRoot
            }
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                collectVisibleIncomingKeepUnsentRows(view.getChildAt(i), out, budget)
                if (budget[0] <= 0) return
            }
        }
    }

    private fun keepUnsentDeletedTextAt(rowRoot: View, rowIds: Set<String> = emptySet()): Long {
        val text = keepUnsentRowMessageText(rowRoot) ?: return 0L
        val deletedAt = synchronized(keepUnsentDeletedTexts) { keepUnsentDeletedTexts[text] ?: 0L }
        if (deletedAt <= 0L) return 0L
        if (rowIds.isNotEmpty() && keepUnsentDeletedAt(rowIds) <= 0L) {
            logKeepUnsentDebug(
                "row-text match ignored because ids do not match deleted ids text=${formatKeepUnsentText(text)} ids=${formatKeepUnsentIds(rowIds)} root=${describeViewBrief(rowRoot)}"
            )
            return 0L
        }
        if (rowIds.isEmpty() && !shouldApplyKeepUnsentTextOnlyMarker(rowRoot, text)) return 0L
        logKeepUnsentDebug("row-text matched deleted text=${formatKeepUnsentText(text)} root=${describeViewBrief(rowRoot)}")
        return deletedAt
    }

    private fun applyKeepUnsentDeletedMarkerFromSignals(rowRoot: View, rowIds: Set<String>): Long {
        val textDeletedAt = keepUnsentDeletedTextAt(rowRoot, rowIds)
        val idDeletedAt = if (rowIds.isEmpty()) 0L else keepUnsentDeletedAt(rowIds)
        val deletedAt = maxOf(textDeletedAt, idDeletedAt)
        logKeepUnsentDebug(
            "apply-signal row=${describeViewBrief(rowRoot)} ids=${formatKeepUnsentIds(rowIds)} " +
                "textDeletedAt=$textDeletedAt idDeletedAt=$idDeletedAt chosen=$deletedAt rowText=${formatKeepUnsentText(keepUnsentRowMessageText(rowRoot))}"
        )
        if (deletedAt > 0L) {
            applyKeepUnsentDeletedMarker(rowRoot, deletedAt)
        } else if (findKeepUnsentMarkerView(rowRoot) != null ||
            ((findViewByResourceName(rowRoot, "direct_text_message_text_view") as? TextView)
                ?.text
                ?.toString()
                ?.contains(KEEP_UNSENT_MARKER_TEXT) == true)
        ) {
            applyKeepUnsentDeletedMarker(rowRoot, 0L)
        }
        return deletedAt
    }

    private fun keepUnsentRowMessageText(rowRoot: View): String? {
        val textView = findKeepUnsentDirectTextView(rowRoot) ?: return null
        return normalizeKeepUnsentMessageText(textView.text)
    }

    private fun hasKeepUnsentDirectTextRow(rowRoot: View?): Boolean {
        return rowRoot != null && findKeepUnsentDirectTextView(rowRoot) != null
    }

    private fun findKeepUnsentDirectTextView(rowRoot: View): TextView? {
        if (rowRoot is TextView && resourceEntryName(rowRoot) == "direct_text_message_text_view") return rowRoot
        (findViewByResourceName(rowRoot, "direct_text_message_text_view") as? TextView)?.let { return it }
        return findLikelyKeepUnsentTextBubble(rowRoot, intArrayOf(120))
    }

    private fun findLikelyKeepUnsentTextBubble(view: View?, budget: IntArray): TextView? {
        if (view == null || budget[0]-- <= 0 || !view.isShown) return null
        if (view is TextView && isKeepUnsentMessageTextCandidate(view)) return view
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                findLikelyKeepUnsentTextBubble(view.getChildAt(i), budget)?.let { return it }
                if (budget[0] <= 0) return null
            }
        }
        return null
    }

    private fun isKeepUnsentMessageTextCandidate(view: View): Boolean {
        if (view !is TextView) return false
        val text = normalizeKeepUnsentMessageText(view.text) ?: return false
        if (!isPersistableKeepUnsentDeletedText(text)) return false
        if (hasKeepUnsentVisualMessageAncestor(view)) return false
        if (isInsideDmMessageActionsOverlay(view)) return false
        return isKeepUnsentDirectTextView(view) ||
            hasKeepUnsentMessageListAncestor(view)
    }

    private fun hasKeepUnsentVisualMessageAncestor(view: View): Boolean {
        var current: View? = view
        repeat(8) {
            val node = current ?: return false
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            val desc = node.contentDescription?.toString().orEmpty().lowercase(Locale.US)
            if (name.contains("visual") ||
                name.contains("xma") ||
                name.contains("caption") ||
                name.contains("clips") ||
                name.contains("reel") ||
                name.contains("voice_message") ||
                name.contains("media_container") ||
                name.contains("message_content_visual") ||
                desc.startsWith("view photo") ||
                desc.startsWith("view video") ||
                desc.contains("voice message")
            ) {
                return true
            }
            current = node.parent as? View
        }
        return false
    }

    private fun hasKeepUnsentMessageListAncestor(view: View): Boolean {
        var current: View? = view
        repeat(10) {
            val node = current ?: return false
            if (isDirectMessageListView(node)) return true
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            val cls = node.javaClass.name.lowercase(Locale.US)
            if (name == "message_list" ||
                name == "message_content" ||
                name == "message_content_horizontal_linear_layout" ||
                name == "direct_text_message_text_view" ||
                cls.contains("directthreadmessagerecyclerview")
            ) {
                return true
            }
            current = node.parent as? View
        }
        return false
    }

    private fun decorateKeepUnsentBoundRows(ids: Collection<String>) {
        val lookupIds = extractDeletedMessageIds(ids).filterNot { keepUnsentAmbiguousBoundIds.contains(it) }.toList()
        if (lookupIds.isEmpty()) {
            logKeepUnsentDebug("decorate-id skipped: no lookup ids raw=${formatKeepUnsentIds(ids)}")
            return
        }
        val views = ArrayList<View>()
        val seenViews = Collections.newSetFromMap(IdentityHashMap<View, Boolean>())
        val stale = ArrayList<String>()
        var usedCompatibleId = false
        synchronized(keepUnsentBoundRows) {
            lookupIds.forEach { id ->
                val view = keepUnsentBoundRows[id]?.get()
                if (view == null) {
                    stale += id
                    logKeepUnsentDebug("decorate-id no-bound-row id=${formatKeepUnsentId(id)}")
                } else if (seenViews.add(view)) {
                    logKeepUnsentDebug("decorate-id exact id=${formatKeepUnsentId(id)} rowText=${formatKeepUnsentText(keepUnsentRowMessageText(view))}")
                    views += view
                }
            }
            keepUnsentBoundRows.forEach { (boundId, ref) ->
                val view = ref.get()
                if (view == null) {
                    stale += boundId
                } else if (!lookupIds.contains(boundId) && lookupIds.any { idsLikelyMatch(boundId, it) } && seenViews.add(view)) {
                    logKeepUnsentDebug("decorate-id compatible bound=${formatKeepUnsentId(boundId)} lookup=${formatKeepUnsentIds(lookupIds)} rowText=${formatKeepUnsentText(keepUnsentRowMessageText(view))}")
                    views += view
                    usedCompatibleId = true
                }
            }
            stale.forEach { keepUnsentBoundRows.remove(it) }
        }
        if (usedCompatibleId) logKeepUnsentFuzzyMatchOnce()
        if (views.isEmpty() && !keepUnsentMissedDecorationSeen) {
            keepUnsentMissedDecorationSeen = true
            logInfo("Keep-unsent marker had deleted ids but no bound Direct row match yet")
        }
        val deletedAt = lookupIds.firstNotNullOfOrNull { id -> synchronized(keepUnsentDeletedIds) { keepUnsentDeletedIds[id] } } ?: System.currentTimeMillis()
        views.forEach { applyKeepUnsentDeletedMarker(it, deletedAt) }
    }

    private val keepUnsentViewHolderFieldCache = ConcurrentHashMap<Class<*>, Field?>()

    private fun findViewHolderRootForKeepUnsent(holder: Any?): View? {
        if (holder is View) return holder
        if (holder == null) return null
        
        val holderClass = holder.javaClass
        if (keepUnsentViewHolderFieldCache.containsKey(holderClass)) {
            val field = keepUnsentViewHolderFieldCache[holderClass] ?: return null
            return runCatching { 
                field.isAccessible = true
                field.get(holder) as? View 
            }.getOrNull()
        }

        runCatching {
            var cls: Class<*>? = holderClass
            while (cls != null && cls != Any::class.java) {
                if (cls.name.endsWith("RecyclerView\$ViewHolder") || cls.simpleName == "ViewHolder") {
                    val field = cls.getDeclaredField("itemView")
                    field.isAccessible = true
                    keepUnsentViewHolderFieldCache[holderClass] = field
                    return field.get(holder) as? View
                }
                cls = cls.superclass
            }
        }

        findFieldDeep(holderClass, "A0I")?.let { field ->
            runCatching {
                field.isAccessible = true
                val view = field.get(holder) as? View
                if (view != null) {
                    keepUnsentViewHolderFieldCache[holderClass] = field
                    return view
                }
            }
        }

        var cls: Class<*>? = holderClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 5) {
            cls.declaredFields.forEach { field ->
                if (!View::class.java.isAssignableFrom(field.type)) return@forEach
                runCatching {
                    field.isAccessible = true
                    val view = field.get(holder) as? View
                    if (view != null) {
                        keepUnsentViewHolderFieldCache[holderClass] = field
                        return view
                    }
                }
            }
            cls = cls.superclass
        }
        keepUnsentViewHolderFieldCache[holderClass] = null
        return null
    }

    private fun findFieldDeep(start: Class<*>?, name: String): Field? {
        var cls = start
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 8) {
            runCatching { return cls.getDeclaredField(name) }
            cls = cls.superclass
        }
        return null
    }

    private fun invokeNoArgDeep(target: Any?, methodName: String): Any? {
        if (target == null) return null
        var cls: Class<*>? = target.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 6) {
            cls.declaredMethods.forEach { method ->
                if (method.name == methodName && method.parameterTypes.isEmpty()) {
                    return runCatching {
                        method.isAccessible = true
                        method.invoke(target)
                    }.getOrNull()
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun invokeStringLikeNoArg(target: Any?, methodName: String): String? = invokeNoArgDeep(target, methodName)?.toString()

    private fun applyKeepUnsentDeletedMarkerToTextView(textView: TextView, deletedAt: Long, source: String): Boolean {
        if (deletedAt <= 0L) return false
        val current = cleanMessageDeletedLines(textView.text)
        if (current.isBlank()) return false
        val normalized = normalizeKeepUnsentMessageText(current) ?: return false
        if (!isPersistableKeepUnsentDeletedText(normalized)) return false
        val started = SystemClock.uptimeMillis()
        val applied = decorateKeepUnsentTextView(textView, keepUnsentMarkerText(deletedAt), deletedAt, source)
        if (applied) {
            logKeepUnsentDebug(
                "instant-text-marker source=$source elapsed=${SystemClock.uptimeMillis() - started}ms text=${formatKeepUnsentText(normalized)}"
            )
        }
        return applied
    }

    private fun applyKeepUnsentDeletedMarker(rowRoot: View, deletedAt: Long) {
        val started = SystemClock.uptimeMillis()
        val rowTextBefore = keepUnsentRowMessageText(rowRoot)
        logKeepUnsentDebug("apply marker requested deletedAt=$deletedAt row=${describeViewBrief(rowRoot)} rowText=${formatKeepUnsentText(rowTextBefore)}")
        if (deletedAt > 0L) {
            rowTextBefore?.let { text ->
                rememberKeepUnsentDeletedTexts(listOf(text), deletedAt)
                persistKeepUnsentDeletedTextOnce(rowRoot.context, text, deletedAt)
            }
        }
        if (Looper.myLooper() == Looper.getMainLooper()) {
            applyKeepUnsentDeletedMarkerNow(rowRoot, deletedAt, started)
        } else {
            rowRoot.post {
                applyKeepUnsentDeletedMarkerNow(rowRoot, deletedAt, started)
            }
        }
    }

    private fun applyKeepUnsentDeletedMarkerNow(rowRoot: View, deletedAt: Long, started: Long): Boolean {
        return runCatching {
            removeKeepUnsentDeletedMarkers(rowRoot)
            restoreKeepUnsentMarkedText(rowRoot)
            if (deletedAt <= 0L) return@runCatching true
            keepUnsentRowMessageText(rowRoot)?.let { text ->
                rememberKeepUnsentDeletedTexts(listOf(text), deletedAt)
                persistKeepUnsentDeletedTextOnce(rowRoot.context, text, deletedAt)
            }
            if ((findKeepUnsentDirectTextView(rowRoot))?.let { applyKeepUnsentDeletedMarkerToTextView(it, deletedAt, "row-signal") } == true) {
                logKeepUnsentDebug("marker applied inline immediate row=${describeViewBrief(rowRoot)} elapsed=${SystemClock.uptimeMillis() - started}ms")
                return@runCatching true
            }
            val markerText = keepUnsentMarkerText(deletedAt)
            val content = findKeepUnsentMessageContentView(rowRoot)
            val parent = findKeepUnsentMarkerParent(content ?: rowRoot, rowRoot) ?: return@runCatching false
            removeKeepUnsentDeletedMarkers(parent)
            val marker = TextView(parent.context).apply {
                tag = KEEP_UNSENT_MARKER_TAG
                text = markerText
                setTextColor(Color.rgb(160, 166, 173))
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)
                setIncludeFontPadding(false)
                setSingleLine(true)
                gravity = Gravity.START
                alpha = 0.95f
            }
            parent.addView(marker, createKeepUnsentMarkerLayoutParams(parent))
            logKeepUnsentDebug("marker applied child view parent=${describeViewBrief(parent)} row=${describeViewBrief(rowRoot)} elapsed=${SystemClock.uptimeMillis() - started}ms")
            if (!keepUnsentMarkerAppliedSeen) {
                keepUnsentMarkerAppliedSeen = true
                logInfo("Applied keep-unsent Message Deleted indicator")
            }
            true
        }.onFailure { logError("Keep-unsent marker decoration failed", it) }.getOrDefault(false)
    }

    private fun decorateKeepUnsentTextMessage(rowRoot: View, markerText: String, deletedAt: Long): Boolean {
        val textView = findKeepUnsentDirectTextView(rowRoot) ?: return false
        return decorateKeepUnsentTextView(textView, markerText, deletedAt, "row")
    }

    private fun decorateKeepUnsentTextView(textView: TextView, markerText: String, deletedAt: Long, source: String): Boolean {
        val current = cleanMessageDeletedLines(textView.text)
        if (current.isBlank()) return false
        val normalizedCurrent = normalizeKeepUnsentMessageText(current)
        val original = synchronized(keepUnsentMarkedTextOriginals) {
            val stored = keepUnsentMarkedTextOriginals[textView]?.let(::cleanMessageDeletedLines)
            val storedMatchesCurrent = stored?.let { value ->
                val normalizedStored = normalizeKeepUnsentMessageText(value)
                normalizedStored == null || normalizedCurrent == null || normalizedStored == normalizedCurrent
            } ?: false
            val base = if (storedMatchesCurrent) stored ?: current else current
            keepUnsentMarkedTextOriginals[textView] = base
            base
        }
        val normalizedOriginal = normalizeKeepUnsentMessageText(original)
        if (normalizedOriginal != null) {
            rememberKeepUnsentDeletedTexts(listOf(normalizedOriginal), deletedAt)
            persistKeepUnsentDeletedTextOnce(textView.context, normalizedOriginal, deletedAt)
        } else {
            logInfo("Keep-unsent inline marker skipped non-persistable base text=${formatKeepUnsentText(original)}")
        }
        val markerPrefix = "\n"
        val text = SpannableString(original + markerPrefix + markerText)
        val start = original.length + markerPrefix.length
        text.setSpan(ForegroundColorSpan(Color.rgb(160, 166, 173)), start, text.length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        text.setSpan(RelativeSizeSpan(0.78f), start, text.length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        allowKeepUnsentMarkerMultiline(textView)
        textView.text = text
        normalizeKeepUnsentMessageText(text)?.let { renderedText ->
            rememberKeepUnsentDeletedTexts(listOf(renderedText), deletedAt)
            persistKeepUnsentDeletedTextOnce(textView.context, renderedText, deletedAt)
        } ?: logInfo("Keep-unsent inline marker rendered text was not persistable text=${formatKeepUnsentText(text.toString())}")
        logKeepUnsentDebug("inline-marker source=$source marker=${formatKeepUnsentText(markerText)} base=${formatKeepUnsentText(original)}")
        if (!keepUnsentMarkerAppliedSeen) {
            keepUnsentMarkerAppliedSeen = true
            logInfo("Applied keep-unsent Message Deleted indicator")
        }
        return true
    }

    private fun ensureKeepUnsentInlineMarkerVisible(rowRoot: View) {
        val textView = findKeepUnsentDirectTextView(rowRoot) ?: return
        if (!textView.text?.toString().orEmpty().contains(KEEP_UNSENT_MARKER_TEXT)) return
        allowKeepUnsentMarkerMultiline(textView)
    }

    private fun allowKeepUnsentMarkerMultiline(textView: TextView) {
        textView.setSingleLine(false)
        textView.maxLines = Int.MAX_VALUE
        textView.minLines = 2
        textView.ellipsize = null
        textView.includeFontPadding = true
        textView.requestLayout()
        (textView.parent as? View)?.requestLayout()
    }

    private fun cleanMessageDeletedLines(value: CharSequence?): String {
        val text = value?.toString()?.replace("\r\n", "\n")?.replace('\r', '\n').orEmpty()
        val lines = text.split('\n')
        if (lines.size == 1) return text
        return lines.filterNot { it.trim().startsWith(KEEP_UNSENT_MARKER_TEXT) }.joinToString("\n").trimEnd('\n')
    }

    private fun keepUnsentMarkerText(deletedAt: Long): String {
        val timestamp = if (deletedAt > 0L) {
            runCatching { SimpleDateFormat("h:mm a", Locale.getDefault()).format(Date(deletedAt)) }.getOrDefault("")
        } else ""
        return if (timestamp.isBlank()) KEEP_UNSENT_MARKER_TEXT else "$KEEP_UNSENT_MARKER_TEXT | $timestamp"
    }

    private fun findKeepUnsentMessageContentView(root: View): View? {
        findViewByResourceName(root, "direct_text_message_text_view")?.let { return it }
        val tagId = instagramResourceId(root.context, "message_content_view_tag")
        if (tagId != 0) findTaggedView(root, tagId)?.let { return it }
        return findViewByResourceName(root, "message_content_horizontal_linear_layout") ?: root
    }

    private fun findTaggedView(view: View?, tagId: Int): View? {
        if (view == null) return null
        runCatching { if (view.getTag(tagId) != null) return view }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                findTaggedView(view.getChildAt(i), tagId)?.let { return it }
            }
        }
        return null
    }

    private fun findViewByResourceName(view: View?, resourceName: String): View? {
        if (view == null) return null
        if (hasInstagramResourceId(view, resourceName) || resourceEntryName(view) == resourceName) return view
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                findViewByResourceName(view.getChildAt(i), resourceName)?.let { return it }
            }
        }
        return null
    }

    private fun describeViewBrief(view: View?): String {
        if (view == null) return "null"
        val name = resourceEntryName(view).orEmpty().ifBlank { "no-id" }
        return "${view.javaClass.name}#$name ${view.width}x${view.height}"
    }

    private fun describeObjectBrief(value: Any?): String {
        if (value == null) return "null"
        if (value is View) return describeViewBrief(value)
        return "${value.javaClass.name}@${System.identityHashCode(value).toString(16)}"
    }

    private fun logKeepUnsentDebug(message: String) {
        if (!state.keepUnsentMessages) return
        val important = message.startsWith("delete-event") ||
            message.startsWith("temporal-delete") ||
            message.startsWith("visible-row-scan complete")
        if (!important && !ENABLE_KEEP_UNSENT_VERBOSE_LOGS) return
        val now = SystemClock.uptimeMillis()
        val count = keepUnsentDebugLogCount
        if (count >= KEEP_UNSENT_DEBUG_HARD_LOG_LIMIT) return
        if (!important) {
            if (count >= KEEP_UNSENT_DEBUG_LOG_LIMIT) return
            if (now - keepUnsentDebugLastAtMs < KEEP_UNSENT_DEBUG_MIN_INTERVAL_MS) return
        }
        keepUnsentDebugLastAtMs = now
        keepUnsentDebugLogCount = count + 1
        logInfo("Keep-unsent debug $now $message")
    }

    private fun formatKeepUnsentIds(ids: Collection<String>?): String {
        val values = ids.orEmpty().map(::formatKeepUnsentId).take(12)
        return "[${values.joinToString(",")}] size=${ids?.size ?: 0}"
    }

    private fun formatKeepUnsentId(id: String?): String {
        val value = id?.trim().orEmpty()
        if (value.isBlank()) return "blank"
        return "${value.take(16)}${if (value.length > 16) "..." else ""}(len=${value.length})"
    }

    private fun formatKeepUnsentTexts(texts: Collection<String>?): String {
        val values = texts.orEmpty().map(::formatKeepUnsentText).take(8)
        return "[${values.joinToString(" | ")}] size=${texts?.size ?: 0}"
    }

    private fun formatKeepUnsentText(text: String?): String {
        val value = cleanMessageDeletedLines(text).replace('\n', ' ').trim()
        if (value.isBlank()) return "blank"
        val shown = value.take(80).replace("|", "\\|")
        return "\"$shown${if (value.length > 80) "..." else ""}\"(len=${value.length})"
    }

    private fun findKeepUnsentMarkerParent(content: View, rowRoot: View): ViewGroup? {
        if (content is ViewGroup && content !== rowRoot) return content
        (content.parent as? ViewGroup)?.takeIf { it !== rowRoot }?.let { return it }
        var current: View? = content
        while (current != null) {
            if (current is LinearLayout && current.orientation == LinearLayout.VERTICAL) return current
            if (current === rowRoot) break
            current = current.parent as? View
        }
        if (content is ViewGroup && content !is LinearLayout) return content
        var parent = content.parent as? View
        while (parent != null) {
            if (parent is ViewGroup && !(parent is LinearLayout && parent.orientation == LinearLayout.HORIZONTAL)) return parent
            if (parent === rowRoot) break
            parent = parent.parent as? View
        }
        return rowRoot as? ViewGroup
    }

    private fun createKeepUnsentMarkerLayoutParams(parent: ViewGroup): ViewGroup.LayoutParams {
        val top = dp(parent, 2)
        val horizontal = dp(parent, 4)
        val bottom = dp(parent, 1)
        return when (parent) {
            is LinearLayout -> LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = top
                marginStart = horizontal
                gravity = Gravity.START
            }
            is FrameLayout -> FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.BOTTOM or Gravity.START).apply {
                marginStart = horizontal
                bottomMargin = bottom
            }
            else -> ViewGroup.MarginLayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = top
                marginStart = horizontal
            }
        }
    }

    private fun dp(view: View, value: Int): Int =
        TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, value.toFloat(), view.resources.displayMetrics).roundToInt()

    private fun removeKeepUnsentDeletedMarkers(view: View) {
        if (view !is ViewGroup) return
        for (i in view.childCount - 1 downTo 0) {
            val child = view.getChildAt(i)
            if (child.tag == KEEP_UNSENT_MARKER_TAG) view.removeViewAt(i) else removeKeepUnsentDeletedMarkers(child)
        }
    }

    private fun restoreKeepUnsentMarkedText(view: View) {
        if (view is TextView) {
            val original = synchronized(keepUnsentMarkedTextOriginals) { keepUnsentMarkedTextOriginals.remove(view) }
            if (original != null) {
                view.text = cleanMessageDeletedLines(original)
            } else {
                val cleaned = cleanMessageDeletedLines(view.text)
                if (cleaned != view.text?.toString().orEmpty()) view.text = cleaned
            }
            return
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) restoreKeepUnsentMarkedText(view.getChildAt(i))
        }
    }

    private fun ensureDevOptionsStableHooks(reason: String) {
        if (!state.isDevEnabled || devOptionsStableHooksInstalled) return
        val now = SystemClock.uptimeMillis()
        if (now - devOptionsStableHooksLastAttemptMs < 2_000L) return
        devOptionsStableHooksLastAttemptMs = now
        val hooked = installDevOptionsStableHooks(reason)
        if (hooked > 0) devOptionsStableHooksInstalled = true
    }

    private fun installDevOptionsStableHooks(reason: String): Int {
        if (!state.isDevEnabled) return 0
        val start = System.currentTimeMillis()
        logInfo("DevOptions install start reason=$reason cacheValid=${InstagramDexKitCache.isCacheValid()}")
        var installedHooks = 0
        var cachedOrInstalled = false
        if (InstagramDexKitCache.isCacheValid()) {
            val cachedMethod = InstagramDexKitCache.loadMethod("DevOptionsMethod", appClassLoader)
            if (cachedMethod != null) {
                logInfo("DevOptions trying cached structural method: ${cachedMethod.declaringClass.name}.${cachedMethod.name}")
                if (hookBooleanMethodOnce("DevOptionsStructural", cachedMethod, true) { state.isDevEnabled }) {
                    installedHooks++
                    cachedOrInstalled = true
                }
            } else {
                val cachedClass = InstagramDexKitCache.loadString("DevOptionsClass")
                if (!cachedClass.isNullOrBlank()) cachedClass.let { className ->
                    logInfo("DevOptions trying cached boolean class: $className")
                    val cachedHooks = hookDevOptionsUserSessionBooleans(className)
                    installedHooks += cachedHooks
                    cachedOrInstalled = cachedOrInstalled || cachedHooks > 0
                    if (!cachedOrInstalled) logInfo("DevOptions cached class had no usable hooks: $className")
                }
            }
        } else {
            logInfo("DevOptions cache invalid; using known class hooks only")
        }
        runSafe("DevOptions E2E blocker") {
            val cls = Class.forName("com.facebook.endtoend.EndToEnd", false, appClassLoader)
            cls.declaredMethods
                .filter { method ->
                    (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) &&
                        method.parameterTypes.isEmpty() &&
                        (method.name == "A07" ||
                            method.name.contains("enabled", ignoreCase = true) ||
                            method.name.contains("e2e", ignoreCase = true))
                }
                .forEach { method ->
                    hookBooleanMethodOnce("DevOptionsE2E", method, false) { state.isDevEnabled }
                }
        }
        if (!cachedOrInstalled) {
            installDexKitStep("DevOptions Dynamic Discovery") {
                val structuralMethod = dexBridge.findDevOptionsStructuralGate()
                if (structuralMethod != null) {
                    if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveMethod("DevOptionsMethod", structuralMethod)
                    if (hookBooleanMethodOnce("DevOptionsStructural", structuralMethod, true) { state.isDevEnabled }) {
                        installedHooks++
                        cachedOrInstalled = true
                        logInfo("Found DevOptions via structural match: ${structuralMethod.declaringClass.name}.${structuralMethod.name}")
                        return@installDexKitStep
                    }
                }
                
                val ids = longArrayOf(36310834636390667L, 36310830341423371L, 36310856111227168L, 36310864701161762L)
                for (id in ids) {
                    val legacyClass = dexBridge.findDevOptionsLegacyConfigId(id)
                    if (legacyClass != null) {
                        if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString("DevOptionsClass", legacyClass)
                        val hooked = hookDevOptionsUserSessionBooleans(legacyClass)
                        if (hooked > 0) {
                            installedHooks += hooked
                            cachedOrInstalled = true
                            logInfo("Found DevOptions via config ID fallback in $legacyClass (id=$id)")
                            return@installDexKitStep
                        }
                    }
                }
            }
        }

        if (!cachedOrInstalled && installedHooks == 0) {
            val missingKey = "DevOptionsBooleanClass_missing_v1"
            if (InstagramDexKitCache.isCacheValid() && InstagramDexKitCache.loadString(missingKey) == "1") {
                return installedHooks
            } else {
                if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString(missingKey, "1")
                InstagramDexKitCache.requestBackgroundScan(androidContext, "dev options boolean class missing")
            }
        } else if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.saveString("DevOptionsBooleanClass_missing_v1", "0")
        }
        logInfo("DevOptions install complete reason=$reason elapsed=${System.currentTimeMillis() - start}ms; booleanHooks=$installedHooks")
        return installedHooks
    }

    private fun hookDevOptionsUserSessionBooleans(className: String): Int {
        if (missingDevOptionsBooleanClasses.contains(className)) return 0
        var hooked = 0
        runCatching {
            val cls = Class.forName(className, false, appClassLoader)
            cls.declaredMethods
                .filter { method ->
                    (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) &&
                        method.parameterTypes.size == 1 &&
                        method.parameterTypes[0].name == "com.instagram.common.session.UserSession"
                }
                .forEach { method ->
                    if (hookBooleanMethodOnce("DevOptionsStable", method, true) { state.isDevEnabled }) hooked++
                }
        }.onFailure { throwable ->
            if (throwable is ClassNotFoundException) {
                missingDevOptionsBooleanClasses += className
            } else {
                logError("DevOptions class $className", throwable)
            }
        }
        return hooked
    }

    private fun hookBooleanMethodOnce(name: String, method: Method, result: Boolean, enabled: () -> Boolean): Boolean {
        val signature = "${method.declaringClass.name}.${method.name}:${method.parameterTypes.size}:$result"
        if (!hookedDexMethods.add(signature)) return false
        var installed = false
        runCatching {
            method.isAccessible = true
            XposedBridge.hookMethod(
                method,
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (enabled()) param.result = result
                    }
                }
            )
            logInfo("Boolean hook installed: $name -> $signature")
            installed = true
        }.onFailure { logError("Failed boolean hook $name $signature", it) }
        return installed
    }

    private fun installSponsoredModelHooks() {
        if (!sponsoredModelHooksInstalled.compareAndSet(false, true)) return
        runSafe("Sponsored model blockers") {
            val sponsoredContentClass = findFirstClass("X.D4s", "p000X.C33719D4s")
            hookSponsoredControllerMethods(sponsoredContentClass)
            var hooked = 0
            hooked += hookClipsSponsoredMerge(sponsoredContentClass)
            hooked += hookSponsoredResponseSink(sponsoredContentClass)
            hooked += hookFeedDataSource(sponsoredContentClass)
            hooked += hookMainFeedCache(sponsoredContentClass)
            if (hookSponsoredContentInsertItemCheck()) hooked++
            logInfo("Installed sponsored model blockers=$hooked")
        }
    }

    private fun hookSponsoredControllerMethods(sponsoredContentClass: Class<*>?) {
        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods("AdBlockerControllerMethods", appClassLoader)
                ?.takeIf { it.isNotEmpty() }
                ?.let { cached ->
                    val hooked = hookSponsoredControllerTargets(cached, sponsoredContentClass)
                    logInfo("Hooked cached sponsored controller methods=$hooked")
                    return
                }
        }

        val targets = linkedSetOf<Method>()
        listOf(
            "SponsoredContentController.insertItem",
            "SponsoredContentController.processValidatedContent",
            "onSponsoredContentDelivered",
            "onInjectionRuleStatusUpdated"
        ).forEach { marker ->
            dexBridge.findMethodsUsingStrings(marker).forEach { method ->
                if (isSponsoredControllerCandidate(method)) targets += method
            }
        }
        if (targets.isNotEmpty()) {
            InstagramDexKitCache.saveMethods("AdBlockerControllerMethods", targets.toList())
        }
        val hooked = hookSponsoredControllerTargets(targets, sponsoredContentClass)
        if (hooked > 0) {
            logInfo("Hooked sponsored controller methods=$hooked")
        } else {
            logInfo("No sponsored controller methods found")
        }
    }

    private fun hookSponsoredControllerTargets(targets: Collection<Method>, sponsoredContentClass: Class<*>?): Int {
        var hooked = 0
        targets.forEach { method ->
            val signature = "${methodKey(method)}:sponsored_controller"
            if (!hookedDexMethods.add(signature)) return@forEach
            runCatching {
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.isAdBlockEnabled) return
                            if (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) {
                                param.result = false
                            } else {
                                val removed = stripSponsoredListArgs(param, sponsoredContentClass)
                                if (removed > 0) {
                                    logInfo("Stripped sponsored controller list items=$removed from ${method.declaringClass.name}.${method.name}")
                                }
                            }
                        }
                    }
                )
                hooked++
            }.onFailure { logError("Failed sponsored controller hook $signature", it) }
        }
        return hooked
    }

    private fun hookSponsoredContentInsertItemCheck(): Boolean {
        val missingKey = "AdBlocker_insert_item_missing_v1"
        val hook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (state.isAdBlockEnabled) param.result = false
            }
        }

        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethod("AdBlocker", appClassLoader)?.let { method ->
                val signature = "${methodKey(method)}:adblocker_cached"
                if (!hookedDexMethods.add(signature)) return false
                return runCatching {
                    XposedBridge.hookMethod(method, hook)
                    logInfo("Hooked cached SponsoredContentController.insertItem: ${method.declaringClass.name}.${method.name}")
                    true
                }.getOrElse {
                    logError("Failed cached SponsoredContentController hook $signature", it)
                    false
                }
            }
        }

        if (InstagramDexKitCache.isCacheValid() && InstagramDexKitCache.loadString(missingKey) == "1") {
            logInfo("SponsoredContentController.insertItem discovery skipped; cached missing")
            return false
        }

        dexBridge.findMethodsUsingStrings("SponsoredContentController.insertItem")
            .firstOrNull { method -> method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java }
            ?.let { method ->
                val signature = "${methodKey(method)}:adblocker_insert_item"
                if (!hookedDexMethods.add(signature)) return false
                return runCatching {
                    method.isAccessible = true
                    InstagramDexKitCache.saveMethod("AdBlocker", method)
                    if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString(missingKey, "0")
                    XposedBridge.hookMethod(method, hook)
                    logInfo("Hooked SponsoredContentController.insertItem: ${method.declaringClass.name}.${method.name}")
                    true
                }.getOrElse {
                    logError("Failed SponsoredContentController.insertItem hook $signature", it)
                    false
                }
            }
        if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString(missingKey, "1")
        logInfo("No valid SponsoredContentController.insertItem method hooked")
        return false
    }

    private fun isSponsoredControllerCandidate(method: Method): Boolean {
        if (method.returnType == java.lang.Boolean.TYPE || method.returnType == java.lang.Boolean::class.java) return true
        return method.parameterTypes.any { List::class.java.isAssignableFrom(it) }
    }

    private fun stripSponsoredListArgs(param: XC_MethodHook.MethodHookParam<*>, sponsoredContentClass: Class<*>?): Int {
        var removed = 0
        param.args?.indices?.forEach { index ->
            val arg = param.args[index]
            if (arg is List<*> && arg.isNotEmpty()) {
                val kept = ArrayList<Any?>(arg.size)
                var removedFromArg = 0
                arg.forEach { item ->
                    if (isAdPayload(item, sponsoredContentClass)) removedFromArg++ else kept += item
                }
                if (removedFromArg > 0) {
                    param.args[index] = kept
                    removed += removedFromArg
                }
            }
        }
        return removed
    }

    private fun hookClipsSponsoredMerge(sponsoredContentClass: Class<*>?): Int {
        val mergeClass = findFirstClass("X.4Xr", "p000X.AbstractC115434Xr") ?: return 0
        var hooked = 0
        mergeClass.declaredMethods.forEach { method ->
            val params = method.parameterTypes
            if (!Modifier.isStatic(method.modifiers) || params.size != 5 ||
                !List::class.java.isAssignableFrom(params[1]) ||
                !List::class.java.isAssignableFrom(params[2])
            ) return@forEach
            if (hookAdMethodOnce("clips merge", method) { param ->
                    sanitizeAdListArg(param, 1, sponsoredContentClass) + sanitizeAdListArg(param, 2, sponsoredContentClass)
                }
            ) hooked++
        }
        return hooked
    }

    private fun hookSponsoredResponseSink(sponsoredContentClass: Class<*>?): Int {
        val responseClass = findFirstClass("X.4Xv", "p000X.C115474Xv") ?: return 0
        var hooked = 0
        responseClass.declaredMethods.forEach { method ->
            val params = method.parameterTypes
            if (Modifier.isStatic(method.modifiers) || method.returnType != Void.TYPE || params.size != 5 ||
                params[2] != String::class.java || !List::class.java.isAssignableFrom(params[3]) ||
                params[4] != java.lang.Boolean.TYPE
            ) return@forEach
            if (hookAdMethodOnce("sponsored response", method) { param -> sanitizeAdListArg(param, 3, sponsoredContentClass) }) hooked++
        }
        return hooked
    }

    private fun hookFeedDataSource(sponsoredContentClass: Class<*>?): Int {
        val dataSourceClass = findFirstClass("X.BXf", "p000X.AbstractC29367BXf") ?: return 0
        var hooked = 0
        dataSourceClass.declaredMethods.forEach { method ->
            val params = method.parameterTypes
            if (method.returnType != Void.TYPE) return@forEach
            when {
                Modifier.isStatic(method.modifiers) && method.name == "A03" && params.size == 5 && params[0] == dataSourceClass -> {
                    if (hookAdMethodOnce("feed datasource single", method) { param ->
                            if (isAdPayload(param.args.getOrNull(2), sponsoredContentClass)) {
                                param.result = null
                                1
                            } else 0
                        }
                    ) hooked++
                }
                Modifier.isStatic(method.modifiers) && method.name == "A04" && params.size == 2 &&
                    params[0] == dataSourceClass && List::class.java.isAssignableFrom(params[1]) -> {
                    if (hookAdMethodOnce("feed datasource snapshot", method) { param -> sanitizeAdListArg(param, 1, sponsoredContentClass) }) hooked++
                }
                !Modifier.isStatic(method.modifiers) && method.name == "A0D" && params.size == 1 -> {
                    if (hookAdMethodOnce("feed datasource append single", method) { param ->
                            if (isAdPayload(param.args.firstOrNull(), sponsoredContentClass)) {
                                param.result = null
                                1
                            } else 0
                        }
                    ) hooked++
                }
                !Modifier.isStatic(method.modifiers) && method.name == "A0E" && params.size == 1 &&
                    List::class.java.isAssignableFrom(params[0]) -> {
                    if (hookAdMethodOnce("feed datasource append", method) { param -> sanitizeAdListArg(param, 0, sponsoredContentClass) }) hooked++
                }
            }
        }
        return hooked
    }

    private fun hookMainFeedCache(sponsoredContentClass: Class<*>?): Int {
        val cacheClass = findFirstClass("com.instagram.mainfeed.network.MainFeedCacheDataSource") ?: return 0
        var hooked = 0
        cacheClass.declaredMethods.forEach { method ->
            val params = method.parameterTypes
            if (method.returnType != Void.TYPE || Modifier.isStatic(method.modifiers)) return@forEach
            when {
                method.name == "A0G" && params.size == 5 && params[0] == String::class.java &&
                    List::class.java.isAssignableFrom(params[1]) -> {
                    if (hookAdMethodOnce("main feed cache list", method) { param -> sanitizeAdListArg(param, 1, sponsoredContentClass) }) hooked++
                }
                method.name == "A0E" && params.size == 1 && isInstagramFeedItemClass(params[0].name) -> {
                    if (hookAdMethodOnce("main feed cache single", method) { param ->
                            if (isAdPayload(param.args.firstOrNull(), sponsoredContentClass)) {
                                param.result = null
                                1
                            } else 0
                        }
                    ) hooked++
                }
            }
        }
        return hooked
    }

    private fun hookAdMethodOnce(name: String, method: Method, action: (XC_MethodHook.MethodHookParam<*>) -> Int): Boolean {
        val signature = "${methodKey(method)}:$name"
        if (!hookedDexMethods.add(signature)) return false
        return runCatching {
            method.isAccessible = true
            XposedBridge.hookMethod(
                method,
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!state.isAdBlockEnabled) return
                        val removed = action(param)
                        if (removed > 0) logInfo("Stripped $removed sponsored item(s) from $name")
                    }
                }
            )
            true
        }.getOrElse {
            logError("Failed ad method hook $signature", it)
            false
        }
    }

    private fun sanitizeAdListArg(param: XC_MethodHook.MethodHookParam<*>, argIndex: Int, sponsoredContentClass: Class<*>?): Int {
        val args = param.args ?: return 0
        if (argIndex !in args.indices) return 0
        val collection = args[argIndex] as? Collection<*> ?: return 0
        if (collection.isEmpty()) return 0
        val kept = ArrayList<Any?>()
        var removed = 0
        collection.forEach { item ->
            if (isAdPayload(item, sponsoredContentClass)) removed++ else kept += item
        }
        if (removed > 0) args[argIndex] = kept
        return removed
    }

    private fun isAdPayload(item: Any?, sponsoredContentClass: Class<*>?): Boolean {
        if (item == null) return false
        if (isSponsoredContentObject(item, sponsoredContentClass)) return true
        if (looksLikeSponsoredPayloadClass(item.javaClass.name)) return true
        if (isAdMediaObject(item)) return true
        if (isInstagramFeedItemClass(item.javaClass.name)) return isAdMediaObject(invokeNoArg(item, "A05"))
        if (isInstagramClipsItemClass(item.javaClass.name)) {
            if (invokeBooleanNoArg(item, "Dwa")) return true
            val media = invokeNoArg(item, "A06")
            if (isAdMediaObject(media)) return true
            return isAdMediaObject(getFieldValue(item, "A0T"))
        }
        return false
    }

    private fun isSponsoredContentObject(item: Any, sponsoredContentClass: Class<*>?): Boolean {
        if (sponsoredContentClass?.isInstance(item) == true) return true
        val className = item.javaClass.name
        return className == "X.D4s" || className == "p000X.C33719D4s"
    }

    private fun isAdMediaObject(item: Any?): Boolean = item != null && isInstagramObject(item) && invokeBooleanNoArg(item, "Dwa")

    private fun isInstagramFeedItemClass(className: String): Boolean = className == "X.5hx" || className == "p000X.C146455hx"

    private fun isInstagramClipsItemClass(className: String): Boolean = className == "X.5gB" || className == "p000X.C145355gB"

    private fun isInstagramObject(item: Any): Boolean {
        val className = item.javaClass.name
        return className.startsWith("X.") || className.startsWith("p000X.") || className.startsWith("com.instagram.")
    }

    private fun invokeNoArg(target: Any?, methodName: String): Any? {
        if (target == null) return null
        return runCatching {
            val method = target.javaClass.getDeclaredMethod(methodName)
            method.isAccessible = true
            method.invoke(target)
        }.getOrNull()
    }

    private fun invokeBooleanNoArg(target: Any?, methodName: String): Boolean = invokeNoArg(target, methodName) as? Boolean ?: false

    private fun getFieldValue(target: Any?, fieldName: String): Any? {
        if (target == null) return null
        return runCatching {
            val field = target.javaClass.getDeclaredField(fieldName)
            field.isAccessible = true
            field.get(target)
        }.getOrNull()
    }

    private fun findFirstClass(vararg names: String): Class<*>? {
        names.forEach { name ->
            runCatching { Class.forName(name, false, appClassLoader) }.getOrNull()?.let { return it }
        }
        return null
    }

    private fun methodKey(method: Method): String {
        return buildString {
            append(method.declaringClass.name)
            append('#')
            append(method.name)
            append('(')
            method.parameterTypes.forEach { append(it.name).append(',') }
            append("):")
            append(method.returnType.name)
        }
    }

    private fun installNotesLocationFallbackHook() {
        runSafe("Notes location known-class fallback") {
            val cls = Class.forName(
                "com.instagram.direct.inbox.notes.data.repository.GraphqlOptimisticPostOperation",
                false,
                appClassLoader
            )
            cls.declaredMethods
                .filter { it.parameterTypes.isNotEmpty() }
                .forEach { method ->
                    val signature = "${method.declaringClass.name}.${method.name}:notes-fallback"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                if (hasValidNotesLocationSpoof()) applyNotesLocationSpoof(param)
                            }
                        }
                    )
                }
        }
    }

    private fun installInstagramMapLocationSpoofHooks() {
        if (!notesLocationSpoofHooksInstalled.compareAndSet(false, true)) return
        runSafe("Instagram map location spoof hooks") {
            XposedBridge.hookAllMethods(
                Location::class.java,
                "getLatitude",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        notesSpoofCoordinates()?.let { param.result = it.first }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Location::class.java,
                "getLongitude",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        notesSpoofCoordinates()?.let { param.result = it.second }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                LocationManager::class.java,
                "getLastKnownLocation",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        spoofLocation(param.result as? Location)?.let { param.result = it }
                    }
                }
            )
            XposedBridge.hookAllMethods(
                Geocoder::class.java,
                "getFromLocation",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val coords = notesSpoofCoordinates() ?: return
                        if (param.args.size >= 2) {
                            param.args[0] = coords.first
                            param.args[1] = coords.second
                        }
                    }
                }
            )
            hookGoogleLocationResult()
        }
    }

    private fun hookGoogleLocationResult() {
        val cls = runCatching {
            Class.forName("com.google.android.gms.location.LocationResult", false, appClassLoader)
        }.getOrNull() ?: return
        XposedBridge.hookAllMethods(
            cls,
            "getLastLocation",
            object : XC_MethodHook() {
                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    spoofLocation(param.result as? Location)?.let { param.result = it }
                }
            }
        )
        XposedBridge.hookAllMethods(
            cls,
            "getLocations",
            object : XC_MethodHook() {
                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    val locations = (param.result as? List<*>)?.filterIsInstance<Location>() ?: return
                    if (locations.isEmpty()) return
                    val spoofed = locations.map { spoofLocation(it) ?: it }
                    param.result = spoofed
                }
            }
        )
    }

    private fun installNotesLocationRequestHooks() {
        val searches = listOf(
            listOf("location_note_create_info", "latitude"),
            listOf("location_note_create_info", "longitude"),
            listOf("latitude", "longitude", "note"),
            listOf("lat", "lng", "note")
        )
        searches
            .flatMap { strings -> dexBridge.findMethodsUsingStrings(*strings.toTypedArray()) }
            .distinctBy { method -> "${method.declaringClass.name}.${method.name}:${method.parameterTypes.joinToString { it.name }}" }
            .forEach { method ->
                val signature = "${method.declaringClass.name}.${method.name}:notes-location-request"
                if (!hookedDexMethods.add(signature)) return@forEach
                runCatching {
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                if (hasValidNotesLocationSpoof()) applyNotesLocationSpoof(param)
                            }

                            override fun afterHookedMethod(param: MethodHookParam<*>) {
                                val latitude = parsedNotesSpoofLatitude() ?: return
                                val longitude = parsedNotesSpoofLongitude() ?: return
                                if (applyNotesLocationSpoofToObject(param.result, latitude, longitude) && notesSpoofLogCount++ < 30) {
                                    logInfo("Applied Notes location spoof after ${param.method}")
                                }
                            }
                        }
                    )
                    logInfo("DexKit hook installed: NotesLocationRequest -> $signature")
                }.onFailure { logError("Failed Notes location request hook $signature", it) }
            }
    }

    private fun downloadTriggerMode(): String {
        return when (state.reelDownloadControlMode) {
            "like_long_press", "both" -> state.reelDownloadControlMode
            else -> "menu"
        }
    }

    private fun shouldOfferDownloadContextMenu(): Boolean {
        return downloadTriggerMode() != "like_long_press"
    }

    private fun shouldOfferDownloadLikeLongPress(): Boolean {
        return downloadTriggerMode() != "menu"
    }

    private fun logDownloadControlGate(surface: String, decision: String) {
        val now = SystemClock.elapsedRealtime()
        val mode = downloadTriggerMode()
        val key = "$surface|$decision|$mode|${state.enablePostDownload}|${state.enableReelDownload}|${state.enableReelThumbnailDownload}"
        if (key == downloadControlLastLogKey && now - downloadControlLastLogAtMs < 5_000L) return
        downloadControlLastLogKey = key
        downloadControlLastLogAtMs = now
        logInfo(
            "Download control $decision surface=$surface mode=$mode " +
                "post=${state.enablePostDownload} reel=${state.enableReelDownload} " +
                "reelThumb=${state.enableReelThumbnailDownload}"
        )
    }

    private fun installPostDownloadMenuHook() {
        runSafe("Post download menu hook") {
            val optionClassName = "com.instagram.feed.media.mediaoption.MediaOption\$Option"
            val optionClass = Class.forName(optionClassName, false, appClassLoader)
            val downloadOption = optionClass.enumConstants?.firstOrNull { it.toString() == "QR_CODE" }
                ?: optionClass.enumConstants?.firstOrNull { it.toString() == "DOWNLOAD" }
                ?: return@runSafe
            var addButtonMethod: Method? = null
            var creatorClass: Class<*>? = null
            var enumIndex = 0
            var optionIndex = 1
            var selfIndex = 2
            var textIndex = 3
            var listIndex = 4
            fun acceptAddButtonCandidate(method: Method, ownerClass: Class<*>? = null): Boolean {
                if (!Modifier.isStatic(method.modifiers) || method.returnType != java.lang.Void.TYPE) return false
                val methodParams = method.parameterTypes
                if (methodParams.size < 4) return false
                val foundOption = methodParams.indexOfFirst { it == optionClass }
                val foundList = methodParams.indexOfFirst { java.util.ArrayList::class.java.isAssignableFrom(it) }
                if (foundOption < 0 || foundList < 0) return false
                addButtonMethod = method.apply { isAccessible = true }
                creatorClass = ownerClass ?: method.declaringClass
                optionIndex = foundOption
                listIndex = foundList
                selfIndex = methodParams.indexOfFirst { it == creatorClass }.takeIf { it >= 0 }
                    ?: 2.coerceAtMost(methodParams.lastIndex)
                textIndex = methodParams.indexOfFirst { CharSequence::class.java.isAssignableFrom(it) }.takeIf { it >= 0 }
                    ?: 3.coerceAtMost(methodParams.lastIndex)
                enumIndex = methodParams.indices.firstOrNull { methodParams[it].isEnum && it != optionIndex }
                    ?: 0
                InstagramDexKitCache.saveMethod("PostDownload_addButton", method)
                InstagramDexKitCache.saveString(
                    "PostDownload_addButtonIdx",
                    "$enumIndex,$optionIndex,$selfIndex,$textIndex,$listIndex"
                )
                return true
            }

            if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethod("PostDownload_addButton", appClassLoader)?.let { cached ->
                    addButtonMethod = cached.apply { isAccessible = true }
                    creatorClass = cached.declaringClass
                    InstagramDexKitCache.loadString("PostDownload_addButtonIdx")
                        ?.split(',')
                        ?.takeIf { it.size == 5 }
                        ?.mapNotNull { it.toIntOrNull() }
                        ?.takeIf { it.size == 5 }
                        ?.let { indices ->
                            enumIndex = indices[0]
                            optionIndex = indices[1]
                            selfIndex = indices[2]
                            textIndex = indices[3]
                            listIndex = indices[4]
                        }
                    logInfo("Loaded cached post download add-button hook ${cached.declaringClass.name}.${cached.name}")
                }
            }

            if (addButtonMethod == null) {
                val creatorClassNames = dexBridge.findClassNamesUsingStrings("MediaOptionsOverflowMenuCreator").distinct()
                creatorClassNames.forEach { creatorClassName ->
                    if (addButtonMethod != null) return@forEach
                    val cls = runCatching { Class.forName(creatorClassName, false, appClassLoader) }
                        .onFailure { logError("Post download creator class $creatorClassName", it) }
                        .getOrNull()
                        ?: return@forEach
                    cls.declaredMethods.firstOrNull { method -> acceptAddButtonCandidate(method, cls) }
                }
                if (addButtonMethod == null) {
                    dexBridge.findMethodsByParamTypes("void", optionClassName)
                        .firstOrNull { method -> acceptAddButtonCandidate(method, method.declaringClass) }
                }
            }

            val resolvedAddButtonMethod = addButtonMethod ?: run {
                logInfo("Post download add-button method not found")
                return@runSafe
            }
            val resolvedCreatorClass = creatorClass ?: resolvedAddButtonMethod.declaringClass
            val params = resolvedAddButtonMethod.parameterTypes
            if (optionIndex !in params.indices || params[optionIndex] != optionClass) {
                logInfo("Post download add-button option parameter mismatch")
                return@runSafe
            }
            if (listIndex !in params.indices || !java.util.ArrayList::class.java.isAssignableFrom(params[listIndex])) {
                logInfo("Post download add-button list parameter mismatch")
                return@runSafe
            }
            if (selfIndex !in params.indices) selfIndex = 2.coerceAtMost(params.lastIndex)
            if (textIndex !in params.indices) textIndex = 3.coerceAtMost(params.lastIndex)
            if (enumIndex !in params.indices || !params[enumIndex].isEnum) {
                enumIndex = params.indices.firstOrNull { params[it].isEnum && it != optionIndex } ?: run {
                    logInfo("Post download add-button enum parameter not found")
                    return@runSafe
                }
            }
            val buttonEnumValue = params[enumIndex].enumConstants?.firstOrNull { it.toString().equals("normal", true) }
                ?: params[enumIndex].enumConstants?.firstOrNull { it.toString().equals("action", true) }
                ?: params[enumIndex].enumConstants?.firstOrNull()
                ?: run {
                    logInfo("Post download add-button enum value not found")
                    return@runSafe
                }
            val addingDownload = ThreadLocal<Boolean>()
            val restoringOldContextMenuRows = ThreadLocal<Boolean>()
            val processedCreators = Collections.synchronizedSet(Collections.newSetFromMap(WeakHashMap<Any, Boolean>()))
            val restoredOldContextMenuLists = Collections.synchronizedSet(Collections.newSetFromMap(WeakHashMap<Any, Boolean>()))
            val oldContextMenuRowLogTimes = ConcurrentHashMap<String, Long>()
            val oldContextMenuClassicMethods by lazy(LazyThreadSafetyMode.NONE) {
                listOf("A03", "A04", "A05").mapNotNull { name ->
                    resolvedCreatorClass.declaredMethods.firstOrNull { method ->
                        Modifier.isStatic(method.modifiers) &&
                            method.name == name &&
                            method.returnType == java.lang.Void.TYPE &&
                            method.parameterTypes.size == 2 &&
                            method.parameterTypes[0] == resolvedCreatorClass &&
                            java.util.ArrayList::class.java.isAssignableFrom(method.parameterTypes[1])
                    }?.apply { isAccessible = true }
                }.also { methods ->
                    logInfo(
                        "Old post/reel context menu classic row methods=" +
                            methods.joinToString { "${it.declaringClass.name}.${it.name}" }
                    )
                }
            }

            fun oldContextMenuOptionName(value: Any?): String? {
                if (value == null) return null
                if (optionClass.isInstance(value)) return value.toString()
                var cls: Class<*>? = value.javaClass
                while (cls != null && cls != Any::class.java) {
                    cls.declaredFields.firstOrNull { it.type == optionClass }?.let { field ->
                        return runCatching {
                            field.isAccessible = true
                            field.get(value)?.toString()
                        }.getOrNull()
                    }
                    cls = cls.superclass
                }
                return null
            }

            fun oldContextMenuOptionNames(list: java.util.ArrayList<*>): List<String> =
                list.mapNotNull(::oldContextMenuOptionName)

            fun isNativeReelDownloadOption(optionName: String?, text: CharSequence? = null): Boolean {
                val normalizedOption = optionName.orEmpty().lowercase(Locale.US)
                val normalizedText = oldPostReelNormalizeSheetLabel(text?.toString().orEmpty())
                return normalizedOption == "download" ||
                    normalizedOption == "upload" ||
                    normalizedOption == "0ltm" ||
                    normalizedText == "download"
            }

            fun classicContextLooksReel(creator: Any?, options: Collection<String> = emptyList()): Boolean {
                val sinceReelMenuMs = SystemClock.elapsedRealtime() - lastReelDownloadMenuBuildAtMs
                return sinceReelMenuMs in 0L..3_000L ||
                    isReelsAutoplaySurfaceActive() ||
                    creator?.javaClass?.name?.contains("clips", ignoreCase = true) == true ||
                    options.any { option -> isNativeReelDownloadOption(option) && option.equals("0LtM", ignoreCase = true) }
            }

            fun classicContextLooksReel(param: XC_MethodHook.MethodHookParam<*>): Boolean {
                val list = param.args.getOrNull(listIndex) as? java.util.ArrayList<*>
                return classicContextLooksReel(
                    param.args.getOrNull(selfIndex),
                    list?.let(::oldContextMenuOptionNames).orEmpty()
                )
            }

            fun shouldSuppressNewContextMenuOption(optionName: String): Boolean {
                if (optionName == "QR_CODE") return true
                if (optionName.contains("CONTENT_DEEP_DIVE") ||
                    optionName.startsWith("META_AI") ||
                    optionName.startsWith("GEN_AI")
                ) return true
                
                if (oldContextMenuClassicMethods.isNotEmpty() && optionName in RESTORE_OLD_CONTEXT_MENU_SUPPRESSED_OPTION_NAMES) {
                    return true
                }
                return false
            }

            fun logSuppressedNewContextMenuOption(param: XC_MethodHook.MethodHookParam<*>, optionName: String) {
                val creator = param.args.getOrNull(selfIndex)
                val list = param.args.getOrNull(listIndex) as? java.util.ArrayList<*>
                val existingOptions = list?.let { oldContextMenuOptionNames(it).joinToString("|").take(240) }.orEmpty()
                val key = "suppress_new_context:$optionName:${creator?.javaClass?.name}:$existingOptions"
                val now = SystemClock.elapsedRealtime()
                val previous = oldContextMenuRowLogTimes[key] ?: 0L
                if (now - previous < 2_000L) return
                oldContextMenuRowLogTimes[key] = now
                if (oldContextMenuRowLogTimes.size > 120) oldContextMenuRowLogTimes.clear()
                logInfo(
                    "Old post/reel context menu suppressed new-row option=$optionName " +
                        "creator=${creator?.javaClass?.name} existing=$existingOptions"
                )
            }

            fun logOldContextMenuRows(param: XC_MethodHook.MethodHookParam<*>, stage: String) {
                if (!state.restoreOldPostReelContextMenu) return
                val list = param.args.getOrNull(listIndex) as? java.util.ArrayList<*> ?: return
                val creator = param.args.getOrNull(selfIndex)
                val option = param.args.getOrNull(optionIndex)?.toString().orEmpty()
                val text = (param.args.getOrNull(textIndex) as? CharSequence)?.toString().orEmpty()
                val options = oldContextMenuOptionNames(list).joinToString("|").take(240)
                val key = "$stage:${System.identityHashCode(list)}:$option:${list.size}:$options"
                val now = SystemClock.elapsedRealtime()
                val previous = oldContextMenuRowLogTimes[key] ?: 0L
                if (now - previous < 2_000L) return
                oldContextMenuRowLogTimes[key] = now
                if (oldContextMenuRowLogTimes.size > 120) oldContextMenuRowLogTimes.clear()
                logInfo(
                    "Old post/reel context menu row stage=$stage option=$option text=$text " +
                        "listSize=${list.size} options=$options creator=${creator?.javaClass?.name}"
                )
            }

            fun maybeRestoreClassicOldContextMenuRows(param: XC_MethodHook.MethodHookParam<*>) {
                if (!state.restoreOldPostReelContextMenu || restoringOldContextMenuRows.get() == true) return
                val creator = param.args.getOrNull(selfIndex) ?: return
                if (!resolvedCreatorClass.isInstance(creator)) return
                val list = param.args.getOrNull(listIndex) as? java.util.ArrayList<Any?> ?: return
                val currentOption = param.args.getOrNull(optionIndex)?.toString().orEmpty()
                val beforeOptions = oldContextMenuOptionNames(list)
                if (currentOption != "REPORT" && beforeOptions.none { it == "REPORT" }) return
                synchronized(restoredOldContextMenuLists) {
                    if (!restoredOldContextMenuLists.add(list)) return
                }
                val reelContext = classicContextLooksReel(creator, beforeOptions)

                fun hasAny(vararg names: String) = beforeOptions.any { option -> names.any(option::equals) }
                val methods = oldContextMenuClassicMethods.filter { method ->
                    when (method.name) {
                        "A03" -> !hasAny("COPY_LINK", "COPY_FUNDRAISER_LINK")
                        "A04" -> false
                        "A05" -> !hasAny("SHARE_LINK")
                        else -> true
                    }
                }
                if (methods.isEmpty()) {
                    logInfo("Old post/reel context menu already has classic rows options=${beforeOptions.joinToString("|")}")
                    return
                }

                val beforeSize = list.size
                var restoredManageOption = false
                var removedNativeReelDownloadRows = 0
                var restoredReelDownloadOption = false
                restoringOldContextMenuRows.set(true)
                try {
                    methods.forEach { method ->
                        runCatching { method.invoke(null, creator, list) }
                            .onFailure { logError("Old post/reel context menu restore ${method.name}", it) }
                    }
                    if (reelContext) {
                        val iterator = list.listIterator()
                        while (iterator.hasNext()) {
                            val row = iterator.next()
                            val optionName = oldContextMenuOptionName(row)
                            if (isNativeReelDownloadOption(optionName)) {
                                iterator.remove()
                                removedNativeReelDownloadRows++
                            }
                        }
                        if (removedNativeReelDownloadRows > 0) {
                            logInfo(
                                "Old post/reel context menu removed native reel download rows " +
                                    "count=$removedNativeReelDownloadRows beforeOptions=${beforeOptions.joinToString("|")} " +
                                    "afterRestoreOptions=${oldContextMenuOptionNames(list).joinToString("|")}"
                            )
                        }
                        if ((state.enableReelDownload || state.enableReelThumbnailDownload) && shouldOfferDownloadContextMenu()) {
                            val callArgs = param.args.copyOf(resolvedAddButtonMethod.parameterCount)
                            callArgs[enumIndex] = buttonEnumValue
                            callArgs[optionIndex] = downloadOption
                            callArgs[selfIndex] = creator
                            callArgs[textIndex] = "Download"
                            callArgs[listIndex] = list
                            addingDownload.set(true)
                            try {
                                restoredReelDownloadOption = runCatching {
                                    resolvedAddButtonMethod.invoke(null, *callArgs)
                                    true
                                }.onFailure {
                                    logError("Old post/reel context menu restore controlled reel DOWNLOAD", it)
                                }.getOrDefault(false)
                            } finally {
                                addingDownload.remove()
                            }
                            logDownloadControlGate(
                                "reel_classic_context_row",
                                if (restoredReelDownloadOption) "offered" else "failed"
                            )
                        } else {
                            logDownloadControlGate("reel_classic_context_row", "suppressed")
                        }
                    }
                    if (!hasAny("MANAGE_SUGGESTED_CONTENT", "MANAGE_SUGGESTED_CONTENT_CARRERA", "SEE_YOUR_ALGORITHM")) {
                        val manageOption = optionClass.enumConstants?.firstOrNull {
                            it.toString() == "MANAGE_SUGGESTED_CONTENT"
                        }
                        if (manageOption != null) {
                            val callArgs = param.args.copyOf(resolvedAddButtonMethod.parameterCount)
                            callArgs[enumIndex] = buttonEnumValue
                            callArgs[optionIndex] = manageOption
                            callArgs[selfIndex] = creator
                            callArgs[textIndex] = "Manage content preferences"
                            callArgs[listIndex] = list
                            restoredManageOption = runCatching {
                                resolvedAddButtonMethod.invoke(null, *callArgs)
                                true
                            }.onFailure {
                                logError("Old post/reel context menu restore MANAGE_SUGGESTED_CONTENT", it)
                            }.getOrDefault(false)
                        }
                    }
                } finally {
                    restoringOldContextMenuRows.remove()
                }
                logInfo(
                    "Old post/reel context menu restore classic_rows methods=${methods.joinToString { it.name }} manage=$restoredManageOption " +
                        "reelContext=$reelContext nativeReelRowsRemoved=$removedNativeReelDownloadRows " +
                        "controlledReelDownload=$restoredReelDownloadOption " +
                        "before=$beforeSize after=${list.size} beforeOptions=${beforeOptions.joinToString("|")} " +
                        "afterOptions=${oldContextMenuOptionNames(list).joinToString("|")}"
                )
            }

            XposedBridge.hookMethod(
                resolvedAddButtonMethod,
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val optionName = param.args.getOrNull(optionIndex)?.toString().orEmpty()
                        val text = param.args.getOrNull(textIndex) as? CharSequence
                        if (addingDownload.get() != true &&
                            state.restoreOldPostReelContextMenu &&
                            classicContextLooksReel(param) &&
                            isNativeReelDownloadOption(optionName, text)
                        ) {
                            param.result = param.thisObject
                            logInfo(
                                "Old post/reel context menu suppressed native reel download row " +
                                    "option=$optionName text=${text?.toString().orEmpty()} " +
                                    "creator=${param.args.getOrNull(selfIndex)?.javaClass?.name}"
                            )
                            return
                        }
                        if (state.restoreOldPostReelContextMenu && restoringOldContextMenuRows.get() != true) {
                            if (shouldSuppressNewContextMenuOption(optionName)) {
                                param.result = param.thisObject
                                logSuppressedNewContextMenuOption(param, optionName)
                                return
                            }
                        }
                        if (addingDownload.get() == true || !state.enablePostDownload) return
                        if (param.args.getOrNull(optionIndex) == downloadOption) param.result = param.thisObject
                    }

                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (addingDownload.get() == true || restoringOldContextMenuRows.get() == true) return
                        logOldContextMenuRows(param, "after_add")
                        maybeRestoreClassicOldContextMenuRows(param)
                        if (!state.enablePostDownload) return
                        if (!shouldOfferDownloadContextMenu()) {
                            logDownloadControlGate("post_menu", "suppressed")
                            return
                        }
                        if (param.args.getOrNull(optionIndex) == downloadOption) return
                        val creator = param.args.getOrNull(selfIndex)
                            ?: param.args.getOrNull(listIndex)
                            ?: param.args
                        if (param.args.getOrNull(selfIndex) != null &&
                            !resolvedCreatorClass.isInstance(param.args.getOrNull(selfIndex)) &&
                            selfIndex != 2.coerceAtMost(params.lastIndex)
                        ) return
                        if (state.restoreOldPostReelContextMenu && classicContextLooksReel(param)) {
                            logDownloadControlGate("post_menu_reel_classic", "deferred_reel_row")
                            return
                        }
                        synchronized(processedCreators) {
                            if (!processedCreators.add(creator)) return
                        }
                        val callArgs = param.args.copyOf(resolvedAddButtonMethod.parameterCount)
                        callArgs[enumIndex] = buttonEnumValue
                        callArgs[optionIndex] = downloadOption
                        callArgs[textIndex] = "Download"
                        logDownloadControlGate("post_menu", "offered")
                        addingDownload.set(true)
                        try {
                            runCatching {
                                resolvedAddButtonMethod.invoke(null, *callArgs)
                            }.onFailure {
                                logError("Failed to add download button to post menu", it)
                            }
                        } finally {
                            addingDownload.remove()
                        }
                    }
                }
            )

            val clickHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (addingDownload.get() == true) return
                    val clicked = param.args?.firstOrNull { optionClass.isInstance(it) }
                        ?: param.args?.firstOrNull { it?.javaClass?.isEnum == true && it.toString().contains("DOWNLOAD") }
                        ?: return
                    val clickedStr = clicked.toString()
                    if (clicked != downloadOption && clickedStr != "DOWNLOAD" && clickedStr != "QR_CODE") return
                    val stackTrace = android.util.Log.getStackTraceString(Throwable())
                    if (!stackTrace.contains("onClick") && !stackTrace.contains("onTouch") && !stackTrace.contains("performClick")) return
                    val reelClick = (state.enableReelDownload || state.enableReelThumbnailDownload) && isReelsAutoplaySurfaceActive()
                    if (!state.enablePostDownload && !reelClick) return
                    if (!shouldOfferDownloadContextMenu()) {
                        logDownloadControlGate(if (reelClick) "reel_classic_context_click" else "post_menu_click", "suppressed")
                        return
                    }
                    param.result = null
                    val context = findContextInObjectGraph(param.thisObject) ?: currentActivity ?: androidContext
                    val media = findMediaViaMenuCreator(param.thisObject) ?: findMediaObject(param.thisObject)
                    if (reelClick && media != null) {
                        val ageMs = SystemClock.elapsedRealtime() - lastReelDownloadMenuBuildAtMs
                        if (ageMs in 0L..650L) {
                            logDownloadControlGate("reel_classic_context_click", "initial_tap_guard")
                            logInfo("Old post/reel context menu reel download click suppressed reason=initial_open_tap_guard ageMs=$ageMs")
                            return
                        }
                        val activity = findActivity(context) ?: currentActivity
                        if (activity != null && !activity.isFinishing && !activity.isDestroyed) {
                            logDownloadControlGate("reel_classic_context_click", "accepted")
                            mainHandler.post { handleReelDownloadClick(activity, media, param.thisObject ?: media) }
                            return
                        }
                        logDownloadControlGate("reel_classic_context_click", "activity_missing")
                    }
                    if (!state.enablePostDownload) return
                    val urls = media?.let { extractAllMediaDownloadUrls(context, it) }
                        .orEmpty()
                        .ifEmpty { collectCdnUrls(media ?: param.thisObject).take(1) }
                    if (urls.isEmpty()) {
                        Toast.makeText(context, "No media found for post", Toast.LENGTH_SHORT).show()
                        return
                    }
                    val downloadContext = downloadContextFrom(media ?: param.thisObject, "post")
                    val viewIdx = findCarouselIndexFromView(context, urls.size)
                    val carouselIndex = if (viewIdx >= 0) viewIdx else findObjectCarouselIndex(param.thisObject, urls.size)
                    mainHandler.post { showPostDownloadChoices(context, urls.distinct(), downloadContext, carouselIndex) }
                }
            }

            val clickMethods = InstagramDexKitCache.loadMethods("PostDownload_click", appClassLoader)
                ?.takeIf { InstagramDexKitCache.isCacheValid() && it.isNotEmpty() }
                ?: dexBridge.findMethodsByParamTypes("void", optionClassName)
                    .filterNot { Modifier.isStatic(it.modifiers) }
                    .also { if (it.isNotEmpty()) InstagramDexKitCache.saveMethods("PostDownload_click", it) }

            clickMethods.forEach { method ->
                    method.isAccessible = true
                    val signature = "${method.declaringClass.name}.${method.name}:${method.parameterTypes.size}"
                    if (!hookedDexMethods.add("PostDownloadClick:$signature")) return@forEach
                    XposedBridge.hookMethod(method, clickHook)
                }
            logInfo("Installed post download menu hook on ${resolvedAddButtonMethod.declaringClass.name}.${resolvedAddButtonMethod.name}; clickHandlers=${clickMethods.size}")
        }
    }

    private fun installReelDownloadMenuHook() {
        runSafe("Reel download menu hook") {
            val mediaClassName = "com.instagram.feed.media.Media"
            val optionsMethod = InstagramDexKitCache.loadMethod("ReelDownload", appClassLoader)
                ?.takeIf { InstagramDexKitCache.isCacheValid() }
                ?: run {
                    val controllerClass = dexBridge.findMethodsUsingStrings("ClipsOrganicMediaItemViewMoreOptionsController")
                        .firstOrNull()
                        ?.declaringClass
                        ?: return@runSafe
                    controllerClass.declaredMethods.firstOrNull { method ->
                        method.returnType == java.lang.Void.TYPE &&
                            method.parameterTypes.size >= 2 &&
                            method.parameterTypes[0].name == mediaClassName &&
                            !method.parameterTypes[1].isPrimitive &&
                            method.parameterTypes[1] != String::class.java
                    }?.also { InstagramDexKitCache.saveMethod("ReelDownload", it) }
                }
                ?: return@runSafe
            optionsMethod.isAccessible = true
            var buttonAdderMethod: Method? = null
            var activityField: Field? = null

            XposedBridge.hookMethod(
                optionsMethod,
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableReelDownload && !state.enableReelThumbnailDownload) return
                        if (!shouldOfferDownloadContextMenu()) {
                            logDownloadControlGate("reel_menu", "suppressed")
                            return
                        }
                        val controller = param.thisObject ?: return
                        val media = param.args.getOrNull(0) ?: return
                        val buttonAdder = param.args.getOrNull(1) ?: return
                        lastReelDownloadMenuBuildAtMs = SystemClock.elapsedRealtime()
                        lastReelDownloadMediaRef = WeakReference(media)
                        lastReelDownloadControllerRef = WeakReference(controller)
                        if (state.restoreOldPostReelContextMenu) {
                            logDownloadControlGate("reel_menu", "deferred_classic_sheet")
                            logInfo(
                                "Reel download menu deferred to restored sheet " +
                                    "controller=${controller.javaClass.name} media=${media.javaClass.name} " +
                                    "adder=${buttonAdder.javaClass.name}"
                            )
                            return
                        }

                        if (activityField == null) {
                            activityField = controller.javaClass.declaredFields.firstOrNull { Activity::class.java.isAssignableFrom(it.type) }?.apply {
                                isAccessible = true
                            }
                        }
                        val activity = runCatching { activityField?.get(controller) as? Activity }.getOrNull()
                            ?: currentActivity
                            ?: return
                        if (buttonAdderMethod == null) {
                            buttonAdderMethod = buttonAdder.javaClass.declaredMethods.firstOrNull { method ->
                                val p = method.parameterTypes
                                p.size == 4 &&
                                    Context::class.java.isAssignableFrom(p[0]) &&
                                    View.OnClickListener::class.java.isAssignableFrom(p[1]) &&
                                    p[2] == String::class.java &&
                                    p[3] == java.lang.Integer.TYPE
                            }?.apply { isAccessible = true }
                        }
                        val addButton = buttonAdderMethod ?: return
                        val offeredAtMs = SystemClock.elapsedRealtime()
                        val click = View.OnClickListener {
                            val ageMs = SystemClock.elapsedRealtime() - offeredAtMs
                            if (ageMs in 0L..650L) {
                                logDownloadControlGate("reel_menu_click", "initial_tap_guard")
                                logInfo("Reel download menu click suppressed reason=initial_open_tap_guard ageMs=$ageMs")
                                return@OnClickListener
                            }
                            handleReelDownloadClick(activity, media, controller)
                        }
                        logDownloadControlGate("reel_menu", "offered")
                        runCatching { addButton.invoke(buttonAdder, activity, click, "Download", resolveMediaOptionDownloadIcon(activity)) }
                    }
                }
            )
            logInfo("Installed reel download menu hook on ${optionsMethod.declaringClass.name}.${optionsMethod.name}")
        }
    }

    private fun installStoryOverflowHooks() {
        runSafe("Story overflow options hook") {
            initStoryVideoVersionReflection()
            val helpers = linkedSetOf<Class<*>>()
            listOf("X.C8BD", "X.8BD", "p000X.C8BD").forEach { className ->
                runCatching { Class.forName(className, false, appClassLoader) }.getOrNull()?.let { helpers += it }
            }
            val hardcodedHelpers = helpers.size
            var storyOverflowBackgroundScanRequested = false
            fun requestStoryOverflowBackgroundScan(reason: String) {
                if (storyOverflowBackgroundScanRequested) return
                storyOverflowBackgroundScanRequested = true
                InstagramDexKitCache.requestBackgroundScan(androidContext, reason)
            }
            val cachedOptionMethods = if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethods("StoryOverflow_options_v2", appClassLoader).orEmpty()
            } else {
                emptyList()
            }
            if (cachedOptionMethods.isNotEmpty()) {
                cachedOptionMethods.filter(::isStoryOverflowOptionMethod).forEach { helpers += it.declaringClass }
            }
            if (cachedOptionMethods.isEmpty() || helpers.size == hardcodedHelpers) {
                InstagramDexKitCache.loadMethod("StoryDownload_button", appClassLoader)
                    ?.takeIf { InstagramDexKitCache.isCacheValid() }
                    ?.declaringClass
                    ?.let { helpers += it }
                requestStoryOverflowBackgroundScan("story overflow v2 option cache missing")
            }

            var arrayHooks = 0
            var arrayParamHooks = 0
            var clickHooks = 0
            helpers.forEach { helper ->
                helper.declaredMethods.forEach { method ->
                    method.isAccessible = true
                    if ((method.returnType.isArray && CharSequence::class.java.isAssignableFrom(method.returnType.componentType)) ||
                        java.util.Collection::class.java.isAssignableFrom(method.returnType)
                    ) {
                        val signature = "${method.declaringClass.name}.${method.name}:story_options_array"
                        if (hookedDexMethods.add(signature)) {
                            XposedBridge.hookMethod(
                                method,
                                object : XC_MethodHook() {
                                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                                        if (!shouldOfferAnyStoryOption()) return
                                        val res = param.result
                                        if (res is Array<*>) {
                                            val patched = appendStoryOptions(res.filterIsInstance<CharSequence>().toTypedArray())
                                            if (patched !== res) param.result = patched
                                        } else if (res is java.util.Collection<*>) {
                                            val originalStrings = res.filterIsInstance<CharSequence>().toTypedArray()
                                            if (originalStrings.isNotEmpty()) {
                                                val patchedStrings = appendStoryOptions(originalStrings).toList()
                                                val addedStrings = patchedStrings - originalStrings.toSet()
                                                if (addedStrings.isNotEmpty()) {
                                                    val patchedList = ArrayList<Any?>()
                                                    patchedList.addAll(res)
                                                    patchedList.addAll(addedStrings)
                                                    if (res is java.util.ArrayList<*>) {
                                                        param.result = patchedList
                                                        return
                                                    } else {
                                                        param.result = patchedList
                                                        return
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            )
                            arrayHooks++
                        }
                    }
                    if (method.parameterTypes.any { 
                            (it.isArray && CharSequence::class.java.isAssignableFrom(it.componentType)) || 
                            java.util.Collection::class.java.isAssignableFrom(it) 
                        }) {
                        val signature = "${method.declaringClass.name}.${method.name}:story_options_array_param"
                        if (hookedDexMethods.add(signature)) {
                            XposedBridge.hookMethod(
                                method,
                                object : XC_MethodHook() {
                                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                        if (!shouldOfferAnyStoryOption()) return
                                        param.args?.indices?.forEach { index ->
                                            val arg = param.args[index]
                                            if (arg is Array<*>) {
                                                if (!arg.all { it is CharSequence }) return@forEach
                                                val patched = appendStoryOptions(arg.filterIsInstance<CharSequence>().toTypedArray())
                                                if (patched !== arg) param.args[index] = patched
                                            } else if (arg is java.util.Collection<*>) {
                                                val originalStrings = arg.filterIsInstance<CharSequence>().toTypedArray()
                                                if (originalStrings.isNotEmpty()) {
                                                    val patchedStrings = appendStoryOptions(originalStrings).toList()
                                                    val addedStrings = patchedStrings - originalStrings.toSet()
                                                    if (addedStrings.isNotEmpty() && arg is MutableCollection<*>) {
                                                        (arg as MutableCollection<Any>).addAll(addedStrings)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            )
                            arrayParamHooks++
                        }
                    }
                    if (method.returnType == Void.TYPE && method.parameterTypes.any { CharSequence::class.java.isAssignableFrom(it) }) {
                        val signature = "${method.declaringClass.name}.${method.name}:story_option_click"
                        if (hookedDexMethods.add(signature)) {
                            XposedBridge.hookMethod(
                                method,
                                object : XC_MethodHook() {
                                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                        handleStoryOptionClick(param)
                                    }
                                }
                            )
                            clickHooks++
                        }
                    }
                }
            }

            val directClickMethods = if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethods("StoryOverflow_clicks_v2", appClassLoader).orEmpty()
            } else {
                emptyList()
            }.ifEmpty {
                requestStoryOverflowBackgroundScan("story overflow v2 click cache missing")
                InstagramDexKitCache.loadMethod("StoryDownload_click", appClassLoader)
                    ?.takeIf { InstagramDexKitCache.isCacheValid() }
                    ?.let(::listOf)
                    .orEmpty()
            }.filter { it.returnType == Void.TYPE }

            directClickMethods
                .forEach { method ->
                    val signature = "${method.declaringClass.name}.${method.name}:story_download_click"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                handleStoryOptionClick(param)
                            }
                        }
                    )
                    clickHooks++
                }

            logInfo("Installed story overflow hooks arrays=$arrayHooks arrayParams=$arrayParamHooks clicks=$clickHooks helpers=${helpers.size}")
        }
    }

    private fun discoverStoryOverflowOptionMethods(): List<Method> {
        val found = linkedMapOf<String, Method>()
        listOf(
            arrayOf("[INTERNAL] Pause Playback"),
            arrayOf("ReelOptionsFragment.ARGUMENTS_KEY_EXTRA_INITIAL_MEDIA_ID")
        ).forEach { markers ->
            dexBridge.findMethodsUsingStrings(*markers).forEach { method ->
                if (isStoryOverflowOptionMethod(method)) {
                    found.putIfAbsent(methodKey(method), method)
                }
            }
        }
        return found.values.toList()
    }

    private fun isStoryOverflowOptionMethod(method: Method): Boolean {
        val hasOptionArrayReturn = (method.returnType.isArray && CharSequence::class.java.isAssignableFrom(method.returnType.componentType)) || java.util.Collection::class.java.isAssignableFrom(method.returnType)
        val hasOptionArrayParam = method.parameterTypes.any {
            (it.isArray && CharSequence::class.java.isAssignableFrom(it.componentType)) || java.util.Collection::class.java.isAssignableFrom(it)
        }
        val hasOptionClickParam = method.returnType == Void.TYPE &&
            method.parameterTypes.any { CharSequence::class.java.isAssignableFrom(it) }
        return hasOptionArrayReturn || hasOptionArrayParam || hasOptionClickParam
    }

    private fun discoverStoryOverflowClickMethods(): List<Method> {
        val found = linkedMapOf<String, Method>()
        listOf(
            arrayOf("explore_viewer", "friendships/mute_friend_reel/%s/", "[INTERNAL] Pause Playback"),
            arrayOf("ReelOptionsFragment.ARGUMENTS_KEY_EXTRA_INITIAL_MEDIA_ID")
        ).forEach { markers ->
            dexBridge.findMethodsUsingStrings(*markers)
                .filter { method ->
                    method.returnType == Void.TYPE &&
                        method.parameterTypes.any { CharSequence::class.java.isAssignableFrom(it) }
                }
                .forEach { method -> found.putIfAbsent(methodKey(method), method) }
        }
        return found.values.toList()
    }

    private fun shouldOfferMarkSeenStoryOption(): Boolean {
        return state.enableStoryMarkSeenButton || state.enableStoryDownload
    }

    private fun shouldOfferRepostStoryOption(): Boolean {
        return state.enableStoryRepostButton || state.enableStoryDownload
    }

    private fun shouldOfferAnyStoryOption(): Boolean {
        return state.enableStoryDownload || shouldOfferMarkSeenStoryOption() ||
            shouldOfferRepostStoryOption() || state.enableStoryMentions
    }

    private fun initStoryVideoVersionReflection() {
        if (storyVideoVersionIntfClass != null && storyVideoVersionGetUrl != null) return
        runCatching {
            val cls = Class.forName("com.instagram.model.mediasize.VideoVersionIntf", false, appClassLoader)
            storyVideoVersionIntfClass = cls
            storyVideoVersionGetUrl = cls.getMethod("getUrl")
        }
    }

    private fun initMediaDownloadReflection() {
        if (mediaClass != null && mutableMediaDictIntfClass != null && mediaCarouselCandidates.isNotEmpty()) return
        runCatching {
            val resolvedMedia = Class.forName("com.instagram.feed.media.Media", false, appClassLoader)
            mediaClass = resolvedMedia
            val mediaExt = Class.forName("com.instagram.feed.media.MediaExtKt", false, appClassLoader)
            mediaImageUrlMethod = mediaExt.declaredMethods.firstOrNull { method ->
                Modifier.isStatic(method.modifiers) &&
                    method.returnType == String::class.java &&
                    method.parameterTypes.size == 2 &&
                    Context::class.java.isAssignableFrom(method.parameterTypes[0]) &&
                    method.parameterTypes[1] == resolvedMedia
            }?.apply { isAccessible = true }
        }.onFailure { logError("Could not resolve Instagram MediaExt download helpers", it) }

        runCatching {
            val dictClass = Class.forName("com.instagram.feed.media.MutableMediaDictIntf", false, appClassLoader)
            mutableMediaDictIntfClass = dictClass
            val seen = linkedSetOf<String>()
            fun collect(owner: Class<*>) {
                owner.methods
                    .filter { method ->
                        method.parameterTypes.isEmpty() &&
                            List::class.java.isAssignableFrom(method.returnType) &&
                            seen.add(method.name)
                    }
                    .forEach { method ->
                        method.isAccessible = true
                        mediaCarouselCandidates += method
                    }
            }
            collect(dictClass)
        }.onFailure { logError("Could not resolve Instagram mutable media download helpers", it) }
    }

    private fun resolveUsernameGetter() {
        if (userClass != null && userUsernameGetter != null) return
        if (InstagramDexKitCache.isCacheValid()) {
            val cachedClass = InstagramDexKitCache.loadString("UserClass")
            val cachedGetter = InstagramDexKitCache.loadMethod("UsernameGetter", appClassLoader)
            if (!cachedClass.isNullOrBlank()) {
                runCatching { Class.forName(cachedClass, false, appClassLoader) }.getOrNull()?.let { cached ->
                    userClass = cached
                    userUsernameGetter = cachedGetter?.apply { isAccessible = true }
                    if (userUsernameGetter != null) return
                }
            }
        }

        val resolvedUserClass = dexBridge.findMethodsUsingStrings("username_missing_during_update")
            .firstOrNull()
            ?.declaringClass
            ?: runCatching { Class.forName("com.instagram.user.model.User", false, appClassLoader) }.getOrNull()
            ?: return
        userClass = resolvedUserClass
        InstagramDexKitCache.saveString("UserClass", resolvedUserClass.name)

        val getter = dexBridge.findMethodsUsingNumbers(-265713450)
            .firstOrNull { method ->
                method.declaringClass.name == "com.instagram.user.model.User" &&
                    method.returnType == String::class.java &&
                    method.parameterTypes.isEmpty()
            }
            ?: resolvedUserClass.declaredMethods.firstOrNull { method ->
                method.name == "getUsername" &&
                    method.returnType == String::class.java &&
                    method.parameterTypes.isEmpty()
            }
        getter?.let { method ->
            method.isAccessible = true
            userUsernameGetter = method
            InstagramDexKitCache.saveMethod("UsernameGetter", method)
        }
    }

    private fun appendStoryOptions(original: Array<CharSequence>): Array<CharSequence> {
        if (!shouldOfferAnyStoryOption()) return original
        val labels = original.toMutableList()
        fun addOnce(enabled: Boolean, label: String) {
            if (enabled && labels.none { it.contentEquals(label) }) labels += label
        }
        addOnce(state.enableStoryDownload, STORY_OPTION_DOWNLOAD)
        addOnce(shouldOfferMarkSeenStoryOption(), STORY_OPTION_MARK_SEEN)
        addOnce(shouldOfferRepostStoryOption(), STORY_OPTION_REPOST)
        addOnce(state.enableStoryMentions, STORY_OPTION_MENTIONS)
        return if (labels.size == original.size) original else labels.toTypedArray()
    }

    private fun handleStoryOptionClick(param: XC_MethodHook.MethodHookParam<*>) {
        if (!shouldOfferAnyStoryOption()) return
        val tapped = param.args?.firstOrNull { it is CharSequence } as? CharSequence ?: return
        val isDownload = state.enableStoryDownload && tapped.contentEquals(STORY_OPTION_DOWNLOAD)
        val isMarkSeen = shouldOfferMarkSeenStoryOption() && tapped.contentEquals(STORY_OPTION_MARK_SEEN)
        val isRepost = shouldOfferRepostStoryOption() && tapped.contentEquals(STORY_OPTION_REPOST)
        val isMentions = state.enableStoryMentions && tapped.contentEquals(STORY_OPTION_MENTIONS)
        if (!isDownload && !isMarkSeen && !isRepost && !isMentions) return

        param.result = null
        val holder = findReelItemHolder(param) ?: param.thisObject
        val context = findContextInObjectGraph(holder) ?: findContextInObjectGraph(param.thisObject) ?: currentActivity ?: androidContext

        if (isMentions) {
            val media = findMediaObject(holder) ?: findMediaObject(param.thisObject) ?: param.args?.firstNotNullOfOrNull { findMediaObject(it) }
            showMentionsDialog(context, resolveStoryMentionsFromSources(media, holder, param.thisObject, param.args))
            return
        }

        if (isMarkSeen) {
            val ok = markStorySeen(holder, param.thisObject, param.args)
            Toast.makeText(context, if (ok) "Story marked as seen" else "Could not mark story as seen", Toast.LENGTH_SHORT).show()
            return
        }

        val url = extractStoryUrl(holder) ?: run {
            Toast.makeText(context, "Story media URL not found", Toast.LENGTH_SHORT).show()
            return
        }
        val isVideo = mimeTypeForUrl(url).startsWith("video")
        val metadata = downloadContextFrom(holder, "story")
        if (isRepost) {
            Toast.makeText(context, "Preparing story repost", Toast.LENGTH_SHORT).show()
            repostStoryMedia(context, url, isVideo)
        } else {
            Toast.makeText(context, if (isVideo) "Downloading story video" else "Downloading story photo", Toast.LENGTH_SHORT).show()
            enqueueDownload(url, metadata)
        }
    }

    private fun findReelItemHolder(param: XC_MethodHook.MethodHookParam<*>): Any? {
        if (hasFieldByTypeName(param.thisObject, "com.instagram.model.reels.ReelItem")) return param.thisObject
        param.args?.forEach { arg ->
            if (hasFieldByTypeName(arg, "com.instagram.model.reels.ReelItem")) return arg
        }
        return null
    }

    private fun hasFieldByTypeName(value: Any?, typeName: String): Boolean = readFieldByTypeName(value, typeName) != null

    private fun readFieldByTypeName(value: Any?, typeName: String): Any? {
        if (value == null) return null
        if (value.javaClass.name == typeName) return value
        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (field.type.name == typeName) {
                    return runCatching {
                        field.isAccessible = true
                        field.get(value)
                    }.getOrNull()
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun extractStoryUrl(holder: Any?): String? {
        if (holder == null) return null
        val reelItem = readFieldByTypeName(holder, "com.instagram.model.reels.ReelItem")
        val target = reelItem ?: holder
        findStoryVideoUrl(target, Collections.newSetFromMap(IdentityHashMap()), 0)?.let { return it }

        val candidates = mutableListOf<StoryImageCandidate>()
        collectStoryImageCandidates(target, candidates, Collections.newSetFromMap(IdentityHashMap()), 0)
        if (candidates.isNotEmpty()) return candidates.maxByOrNull { it.area }?.url

        val urls = collectCdnUrls(target)
        return pickBestStoryUrl(urls)
    }

    private fun pickBestStoryUrl(urls: List<String>): String? {
        val filtered = urls.filter { looksLikeMediaUrl(it) && !looksLikeProfileImageUrl(it) }.distinct()
        filtered.firstOrNull { mimeTypeForUrl(it).startsWith("video") }?.let { return it }
        return filtered.maxByOrNull { parseCdnArea(it) } ?: filtered.firstOrNull()
    }

    private fun parseCdnArea(url: String): Int {
        var max = 0
        var index = 0
        while (index < url.length) {
            if (!url[index].isDigit()) {
                index++
                continue
            }
            val start = index
            while (index < url.length && url[index].isDigit()) index++
            if (index >= url.length || url[index] != 'x') continue
            val mid = index
            index++
            val heightStart = index
            while (index < url.length && url[index].isDigit()) index++
            val width = url.substring(start, mid).toIntOrNull() ?: continue
            val height = url.substring(heightStart, index).toIntOrNull() ?: continue
            max = max.coerceAtLeast(width * height)
        }
        return max
    }

    private data class StoryImageCandidate(val url: String, val area: Int)

    private data class KeepUnsentPendingDelete(
        val deletedAt: Long,
        val baselineCounts: Map<String, Int>,
        val createdAt: Long
    )

    private data class KeepUnsentRecentText(
        val text: String,
        val atMs: Long,
        val left: Int,
        val top: Int,
        val right: Int,
        val bottom: Int
    ) {
        val hasBounds: Boolean = left >= 0 && top >= 0 && right > left && bottom > top

        fun distanceTo(x: Int, y: Int): Int {
            val clampedX = x.coerceIn(left, right)
            val clampedY = y.coerceIn(top, bottom)
            return abs(clampedX - x) + abs(clampedY - y)
        }
    }

    private fun findStoryVideoUrl(value: Any?, visited: MutableSet<Any>, depth: Int): String? {
        if (value == null || depth > 5 || !visited.add(value)) return null
        val videoClass = storyVideoVersionIntfClass
        val getUrl = storyVideoVersionGetUrl
        if (videoClass == null || getUrl == null) return null

        if (videoClass.isInstance(value)) {
            val url = runCatching { getUrl.invoke(value) as? String }.getOrNull()
            if (url != null && isStoryCdnUrl(url) && isStoryVideoUrl(url)) return url
        }

        if (!shouldInspectObject(value.javaClass)) return null

        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                runCatching {
                    field.isAccessible = true
                    val nested = field.get(value) ?: return@forEach
                    if (nested is Iterable<*>) {
                        nested.forEach { item ->
                            if (item != null && videoClass.isInstance(item)) {
                                val url = runCatching { getUrl.invoke(item) as? String }.getOrNull()
                                if (url != null && isStoryCdnUrl(url) && isStoryVideoUrl(url)) return url
                            }
                        }
                    } else if (shouldInspectObject(nested.javaClass)) {
                        findStoryVideoUrl(nested, visited, depth + 1)?.let { return it }
                    }
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun collectStoryImageCandidates(value: Any?, out: MutableList<StoryImageCandidate>, visited: MutableSet<Any>, depth: Int) {
        if (value == null || depth > 7 || out.size >= 40 || !visited.add(value)) return
        if (!shouldInspectObject(value.javaClass)) return

        var candidateUrl: String? = null
        val dims = mutableListOf<Int>()

        fun acceptDimension(raw: Long) {
            if (raw in 50L..20_000L) dims += raw.toInt()
        }

        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                runCatching {
                    field.isAccessible = true
                    when (field.type) {
                        String::class.java -> {
                            val url = field.get(value) as? String
                            if (url != null && isStoryCdnUrl(url) && !isStoryVideoUrl(url)) candidateUrl = url
                        }
                        java.lang.Integer.TYPE -> acceptDimension(field.getInt(value).toLong())
                        java.lang.Long.TYPE -> acceptDimension(field.getLong(value))
                    }
                }
            }
            cls = cls.superclass
        }

        cls = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredMethods
                .filter { it.parameterTypes.isEmpty() }
                .forEach { method ->
                    runCatching {
                        method.isAccessible = true
                        when (method.returnType) {
                            String::class.java -> {
                                val url = method.invoke(value) as? String
                                if (url != null && isStoryCdnUrl(url) && !isStoryVideoUrl(url) && candidateUrl == null) {
                                    candidateUrl = url
                                }
                            }
                            java.lang.Integer.TYPE -> acceptDimension((method.invoke(value) as? Int)?.toLong() ?: return@runCatching)
                            java.lang.Long.TYPE -> acceptDimension(method.invoke(value) as? Long ?: return@runCatching)
                        }
                    }
                }
            cls = cls.superclass
        }

        if (candidateUrl != null && dims.size >= 2) {
            val area = dims.sortedDescending().take(2).fold(1) { acc, dim -> acc * dim }
            out += StoryImageCandidate(candidateUrl.orEmpty(), area)
            return
        }

        cls = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                runCatching {
                    field.isAccessible = true
                    val nested = field.get(value) ?: return@forEach
                    when (nested) {
                        is String -> return@forEach
                        is Iterable<*> -> nested.forEach { collectStoryImageCandidates(it, out, visited, depth + 1) }
                        else -> if (shouldInspectObject(nested.javaClass)) collectStoryImageCandidates(nested, out, visited, depth + 1)
                    }
                }
            }
            cls = cls.superclass
        }
    }

    private fun isStoryCdnUrl(url: String): Boolean {
        return (url.startsWith("http://") || url.startsWith("https://")) &&
            (url.contains("cdninstagram.com") || url.contains("fbcdn.net")) &&
            !looksLikeProfileImageUrl(url)
    }

    private fun isStoryVideoUrl(url: String): Boolean {
        return url.contains("t50.") || url.contains("/o1/") || mimeTypeForUrl(url).startsWith("video")
    }

    private fun installDirectMessageContextMenuHook() {
        if (!dmContextMenuHooksInstalled.compareAndSet(false, true)) return
        runSafe("DM context menu hook") {
            fun dmStep(name: String, block: () -> Unit) {
                val started = SystemClock.uptimeMillis()
                runCatching(block)
                    .onSuccess {
                        logInfo("DM context menu step installed name=$name elapsed=${SystemClock.uptimeMillis() - started}ms")
                    }
                    .onFailure {
                        logError("DM context menu step failed name=$name elapsed=${SystemClock.uptimeMillis() - started}ms", it)
                    }
            }

            val popupClassCacheKey = "DmContextMenuPopupClass_v1"
            val lookupStarted = SystemClock.uptimeMillis()
            var lookupSource = "cache"
            val cachedMenuClass = if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadString(popupClassCacheKey)
                    ?.takeIf { it.isNotBlank() }
                    ?.let { name ->
                        runCatching { Class.forName(name, false, appClassLoader) }
                            .getOrNull()
                            ?.takeIf { PopupWindow::class.java.isAssignableFrom(it) }
                    }
            } else {
                null
            }
            val menuClass = cachedMenuClass
                ?: loadFirstClass("X.2CW", "p000X.C2CW")?.takeIf {
                    lookupSource = "direct"
                    PopupWindow::class.java.isAssignableFrom(it)
                }
                ?: run {
                    lookupSource = "dex"
                    dexBridge.findClassNamesUsingStrings("IgdsContextMenu_BadTokenException")
                        .firstNotNullOfOrNull { name ->
                            runCatching { Class.forName(name, false, appClassLoader) }
                                .getOrNull()
                                ?.takeIf { PopupWindow::class.java.isAssignableFrom(it) }
                        }
                        ?.also { resolved ->
                            if (InstagramDexKitCache.isCacheValid()) {
                                InstagramDexKitCache.saveString(popupClassCacheKey, resolved.name)
                            }
                        }
                }
            if (menuClass == null) {
                logInfo("DM context menu step skipped name=PopupClassLookup elapsed=${SystemClock.uptimeMillis() - lookupStarted}ms reason=class_not_found")
                return@runSafe
            }
            logInfo(
                "DM context menu step installed name=PopupClassLookup elapsed=${SystemClock.uptimeMillis() - lookupStarted}ms " +
                    "source=$lookupSource class=${menuClass.name}"
            )

            dmStep("ItemConstructors") {
                dmPrismItemConstructor = loadFirstClass("X.B7o", "p000X.C28700B7o")?.let { findConstructor(it, 24) }
                dmLegacyItemConstructor = loadFirstClass("X.B7N", "p000X.B7N")?.let { findConstructor(it, 10) }
                dmMenuClickInterfaceClass = loadFirstClass("X.Lhz", "p000X.InterfaceC55387Lhz")
                logInfo(
                    "DM context menu constructors prism=${dmPrismItemConstructor != null} " +
                        "legacy=${dmLegacyItemConstructor != null} clickInterface=${dmMenuClickInterfaceClass != null}"
                )
            }

            val itemHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    maybeInjectDmMenuItems(param)
                }
            }
            dmStep("LegacyMenuItems") {
                listOf("A08", "A07", "A09").forEach { methodName ->
                    runCatching { XposedBridge.hookAllMethods(menuClass, methodName, itemHook) }
                }
            }

            val anchorHook = object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (maybeSuppressOldPostReelPopupShow(param)) return
                    captureDmMenuAnchor(param)
                }
            }
            dmStep("LegacyMenuAnchor") {
                listOf("A06", "showAsDropDown", "showAtLocation").forEach { methodName ->
                    runCatching { XposedBridge.hookAllMethods(menuClass, methodName, anchorHook) }
                }
            }

            dmStep("MessageActionsFlow") { installDmMessageActionsFlow() }
            dmStep("ImageUrlCapture") { installDirectMessageImageUrlCaptureHooks() }
            dmStep("GlobalUrlCapture") { installDirectMessageUrlCaptureHooks() }
            dmStep("AudioPlaybackCapture") { installDirectMessageAudioPlaybackCaptureHooks() }
            dmStep("NativeModalSuppression") { installDmNativeModalLaunchSuppression() }
            dmStep("DeferredActionResume") { installDmDeferredActionResume() }
            logInfo("Installed DM context menu hook on ${menuClass.name} with MessageActions flow")
        }
    }

    private fun installDmMessageActionsFlow() {
        runSafe("DM MessageActions hook") {
            dmMessageActionsViewModelClass = loadFirstClass(
                "com.instagram.direct.messagethread.messageactions.model.MessageActionsViewModel"
            )
            dmLongPressActionDataClass = loadFirstClass(
                "com.instagram.direct.messagethread.interaction.longpressaction.LongPressActionData"
            )
            val viewModelClass = dmMessageActionsViewModelClass
            val actionDataClass = dmLongPressActionDataClass
            if (viewModelClass == null || actionDataClass == null) {
                logInfo("DM MessageActions classes not found")
                return@runSafe
            }

            dmLongPressActionDataConstructor = findConstructor(actionDataClass, 11)
            if (dmLongPressActionDataConstructor == null) {
                logInfo("DM LongPressActionData constructor not found")
                return@runSafe
            }

            inferDmLongPressActionTypes()
            hookDmMessageActionsBuilders()
            hookDmMessageActionsRenderers()
            hookDmMessageActionsDispatchers()
            hookDmMessageActionsControllers()
            hookDmMessageActionDelegates()
            hookDmMessageActionListenerMethods()
            hookDmMessageActionMenuBuilderRows()
            hookDmMessageActionRowModels()
            hookDmMessageActionClickWrappers()
        }
    }

    private fun inferDmLongPressActionTypes() {
        val constructor = dmLongPressActionDataConstructor ?: return
        val params = constructor.parameterTypes
        if (params.size < 5) return
        dmNormalLongPressType = findDmEnumLikeValue(params[1], "NORMAL", null, "A09")
        dmLongPressActionEnumClass = params[2]
        dmCustomLongPressEnum = findDmEnumLikeValueExact(params[2], "GOOD_RESULT", "good_result", "A0S")
            ?: findDmEnumLikeValueExact(params[2], "SAVE_MEDIA", "save_media", "A0x")
        dmPassiveLongPressEnum = findDmEnumLikeValueExact(params[2], null, "none", null)
    }

    private fun hookDmMessageActionsBuilders() {
        val viewModelClass = dmMessageActionsViewModelClass ?: return
        val builders = mutableListOf<Any>()
        viewModelClass.declaredFields.forEach { field ->
            if (!Modifier.isStatic(field.modifiers)) return@forEach
            val type = field.type
            if (type.isPrimitive || type == String::class.java || type.name.contains("Parcelable")) return@forEach
            runCatching {
                field.isAccessible = true
                field.get(null)
            }.getOrNull()?.let { value ->
                if (builders.none { it === value }) builders += value
            }
        }

        var hooked = 0
        builders.forEach { builder ->
            builder.javaClass.declaredMethods.forEach { method ->
                if (method.returnType != viewModelClass) return@forEach
                val signature = "${method.declaringClass.name}.${method.name}:dm_message_actions_builder"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            if (!state.enableDmContextMenuOptions) return
                            maybeInjectDmMessageActionsViewModel(contextFromArgs(param.args), param.result, false)
                        }
                    }
                )
                hooked++
            }
        }
        logInfo("Hooked DM MessageActions builders=$hooked")
    }

    private fun hookDmMessageActionsRenderers() {
        val viewModelClass = dmMessageActionsViewModelClass ?: return
        val classes = linkedSetOf<Class<*>>()
        loadFirstClass("X.eby", "p000X.C96758eby")?.let { classes += it }
        addDmClassesUsingString(classes, "MessageActionsHelper")

        var hooked = 0
        classes.forEach { cls ->
            cls.declaredMethods.forEach { method ->
                if (!methodHasParameter(method, viewModelClass)) return@forEach
                val signature = "${method.declaringClass.name}.${method.name}:dm_message_actions_renderer"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.enableDmContextMenuOptions) return
                            val viewModel = firstArgOfType(param.args, viewModelClass)
                            maybeInjectDmMessageActionsViewModel(contextFromArgs(param.args), viewModel, true)
                            rememberDmMessageActionLifecycle(viewModel, param.args)
                            if (shouldSuppressDmMessageActionOpenLifecycle(viewModel)) {
                                suppressDmMessageActionOpenLifecycle.set(true)
                                suppressDmMessageActionOpenLifecycleCallbacks(param.args, method.parameterTypes)
                            }
                        }

                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            suppressDmMessageActionOpenLifecycle.remove()
                        }
                    }
                )
                hooked++
            }
        }
        logInfo("Hooked DM MessageActions renderers=$hooked")
    }

    private fun hookDmMessageActionsDispatchers() {
        val enumClass = dmLongPressActionEnumClass ?: return
        val classes = linkedSetOf<Class<*>>()
        loadFirstClass("X.eby", "p000X.C96758eby")?.let { classes += it }
        addDmClassesUsingString(classes, "MessageActionsHelper")

        var hooked = 0
        classes.forEach { cls ->
            cls.declaredMethods.forEach { method ->
                if (method.returnType != Void.TYPE || !methodHasParameter(method, enumClass)) return@forEach
                val signature = "${method.declaringClass.name}.${method.name}:dm_message_actions_dispatcher"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.enableDmContextMenuOptions) return
                            val enumAction = dmActionFromCustomLongPressEnumArgs(param.args)
                            val touchAction = recentDmCustomActionRowTouchAction()
                            val action = if (touchAction >= 0) touchAction else enumAction
                            if (action < 0) return
                            val view = firstArgOfType(param.args, View::class.java) as? View
                            val anchor = recentDmMessageActionAnchor() ?: view
                            if (!shouldClaimDmCustomAction(anchor ?: view, "dispatcher")) return
                            val context = contextFromArgs(param.args) ?: view?.context ?: currentActivity ?: androidContext
                            val sources = dmMessageActionSources(
                                args = param.args,
                                owner = param.thisObject,
                                anchor = anchor,
                                view = view
                            )
                            val forcedVoiceContext = recentDmCustomActionRowVoiceContext()
                            val url = resolveDmContextUrl(null, anchor, sources)
                            logInfo(
                                "Claimed DM MessageActions dispatcher action=${dmActionLabel(action)} " +
                                    "enumAction=${dmActionLabel(enumAction)} touchAction=${dmActionLabel(touchAction)} " +
                                    "enum=${enumWire(firstDmActionEnumArg(param.args))} " +
                                    "voice=${forcedVoiceContext ?: looksLikeVoiceMessageContext(sources, anchor)} forcedVoice=$forcedVoiceContext resolvedUrl=${url != null} " +
                                    "anchor=${describeViewBrief(anchor)} view=${describeViewBrief(view)} surface=${dmSurfaceForLog()}"
                            )
                            suppressNativeDmModalLaunch(2_500L)
                            restoreDmMessageActionsUiSoon(anchor, sources)
                            handleResolvedDmAction(stableDmActionContext(context), null, anchor, action, sources, url, forcedVoiceContext)
                            restoreDmMessageActionsUiSoon(anchor, sources)
                            dismissDmActionModalSafelySoon()
                            param.result = null
                        }

                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            val pending = pendingDmDispatcherAction.get() ?: return
                            pendingDmDispatcherAction.remove()
                            restoreDmMessageActionsUiSoon(null, pending.sources)
                            mainHandler.post {
                                handleResolvedDmAction(pending.context, null, pending.anchor, pending.action, pending.sources, pending.resolvedUrl)
                                restoreDmMessageActionsUiSoon(pending.anchor, pending.sources)
                            }
                        }
                    }
                )
                hooked++
            }
        }
        logInfo("Hooked DM MessageActions dispatchers=$hooked")
    }

    private fun dmMessageActionSources(
        args: Array<Any?>? = null,
        owner: Any? = null,
        anchor: View? = null,
        view: View? = null,
        extra: Array<Any?> = emptyArray()
    ): Array<Any?> {
        val output = ArrayList<Any?>()
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun add(candidate: Any?) {
            if (candidate == null) return
            if (seen.add(candidate)) output += candidate
        }

        add(owner)
        add(anchor?.let(::getViewOnClickListener))
        if (view !== anchor) add(view?.let(::getViewOnClickListener))
        add(view)
        add(anchor)
        extra.forEach(::add)
        args?.forEach(::add)
        return output.toTypedArray()
    }

    private fun hookDmMessageActionsControllers() {
        val viewModelClass = dmMessageActionsViewModelClass ?: return
        val classes = linkedSetOf<Class<*>>()
        loadFirstClass("X.gkP", "p000X.C100034gkP")?.let { classes += it }
        addDmClassesUsingString(classes, "MessageActionsController")
        addDmClassesUsingString(classes, "direct_message_actions_fragment")

        var hooked = 0
        classes.forEach { cls ->
            if (dmMessageActionsControllerClass == null) dmMessageActionsControllerClass = cls
            cls.declaredConstructors.forEach { constructor ->
                if (!constructorHasParameter(constructor, viewModelClass)) return@forEach
                val signature = "${constructor.declaringClass.name}.<init>:dm_message_actions_controller"
                if (!hookedDexMethods.add(signature)) return@forEach
                constructor.isAccessible = true
                XposedBridge.hookMethod(
                    constructor,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (!state.enableDmContextMenuOptions) return
                            maybeInjectDmMessageActionsViewModel(
                                contextFromArgs(param.args),
                                firstArgOfType(param.args, viewModelClass),
