    private fun hookDmMessageActionClickWrappers() {
        if (dmMessageActionClickHooked) return
        dmMessageActionClickHooked = true
        XposedBridge.hookAllMethods(
            View::class.java,
            "setOnClickListener",
            object : XC_MethodHook() {
                override fun beforeHookedMethod(param: MethodHookParam<*>) {
                    if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return
                    val listener = param.args?.firstOrNull() as? View.OnClickListener ?: return
                    if (listener is DmMessageActionClickListener || listener is DmNativeUnsendClickListener) return
                    val view = param.thisObject as? View ?: return
                    if (!shouldInspectDmCustomListener(view, "listener-wrap")) return
                    if (state.keepUnsentMessages && isNativeDmUnsendListener(listener)) {
                        param.args[0] = DmNativeUnsendClickListener(listener)
                        return
                    }
                    if (!state.enableDmContextMenuOptions) return
                    val action = findDmActionInListener(listener)
                    if (action < 0) return
                    if (!shouldClaimDmCustomAction(view, "listener-wrap")) return
                    param.args[0] = DmMessageActionClickListener(action, listener)
                }
            }
        )
        XposedBridge.hookAllMethods(
            View::class.java,
            "performClick",
            object : XC_MethodHook() {
                override fun afterHookedMethod(param: MethodHookParam<*>) {
                    val view = param.thisObject as? View ?: return
                    handleNativeDmUnsendPerformClick(view)
                }
            }
        )
        runCatching {
            val viewRootImpl = Class.forName("android.view.ViewRootImpl")
            XposedBridge.hookAllMethods(
                viewRootImpl,
                "enqueueInputEvent",
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        val event = param.args?.firstOrNull() as? MotionEvent ?: return
                        handleNativeDmUnsendRootInput(event)
                    }
                }
            )
        }.onFailure { logError("Failed installing ViewRoot input hook for native DM Unsend", it) }
    }

    private fun maybeInjectDmMessageActionsViewModel(context: Context?, viewModel: Any?, fromRenderer: Boolean) {
        scheduleDmSavedStateLongPressGuardInstall(if (fromRenderer) "message-actions-renderer" else "message-actions-builder")
        val started = SystemClock.uptimeMillis()
        val viewModelClass = dmMessageActionsViewModelClass ?: return
        if (viewModel == null || !viewModelClass.isInstance(viewModel)) return
        if (dmLongPressActionDataClass == null || dmLongPressActionDataConstructor == null) return
        val ctx = context ?: currentActivity ?: androidContext
        dmLatestMessageActionsViewModel = WeakReference(viewModel)
        dmLatestMessageActionsViewModelAtMs = System.currentTimeMillis()
        ensureFreshDmLongPressAnchor("message-actions:${if (fromRenderer) "renderer" else "builder"}")
        logDmMessageActionViewModelDiagnostics(viewModel, fromRenderer)
        rememberKeepUnsentActionViewModelSnapshot(viewModel)
        if (!hasRecentKeepUnsentActionRow() || keepUnsentLastActionRowText == null) rememberNewestVisibleKeepUnsentActionRowSoon("message-actions")
        logKeepUnsentMenuSnapshotMissSoon(viewModel)
        val typeSignal = dmMessageViewModelTypeSignal(viewModel).lowercase(Locale.US)
        val likelyVisual = isLikelyDmVisualMessageTypeSignal(typeSignal)
        val likelyVoice = isLikelyDmVoiceMessageTypeSignal(typeSignal)
        if (likelyVisual && !likelyVoice) {
            val snapshotSeeds = dmSnapshotUrlsForPreference(recentDmMessageActionMediaSnapshot(), preferAudio = false)
            maybePrefetchDmMediaInfoUrls(ctx, arrayOf(viewModel), snapshotSeeds, "menu:${if (fromRenderer) "renderer" else "builder"}")
        }
        var injectedLists = 0
        var cls: Class<*>? = viewModel.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (!List::class.java.isAssignableFrom(field.type)) return@forEach
                runCatching {
                    field.isAccessible = true
                    val list = field.get(viewModel) as? List<*> ?: return@runCatching
                    if (!isDmLongPressActionList(list)) return@runCatching
                    val labelsForLog = lazy { dmMenuLabelsForLog(list) }
                    val allowedActions = dmAllowedMessageActions(viewModel, list, typeSignal, likelyVisual, likelyVoice)
                    if (allowedActions.isEmpty()) {
                        logInfo(
                            "Skipped DM MessageActions custom rows renderer=$fromRenderer visual=$likelyVisual voice=$likelyVoice labels=${labelsForLog.value}"
                        )
                        return@runCatching
                    }
                    if (!fromRenderer && allowedActions.isEmpty()) return@runCatching
                    val extended = insertDmMessageActionsAfterTimestamp(ctx, list, allowedActions) ?: return@runCatching
                    field.set(viewModel, extended)
                    injectedLists++
                    logInfo(
                        "Prepared DM MessageActions custom rows renderer=$fromRenderer visual=$likelyVisual voice=$likelyVoice actions=${dmActionLabelsForLog(allowedActions)} labels=${labelsForLog.value}"
                    )
                }.onFailure { logError("DM MessageActions list injection failed", it) }
            }
            cls = cls.superclass
        }
        if (injectedLists > 0) {
            if (!hasRecentKeepUnsentActionRow() || keepUnsentLastActionRowText == null) rememberNewestVisibleKeepUnsentActionRowSoon("message-actions-injected")
            logInfo("Injected DM MessageActions custom rows=$injectedLists renderer=$fromRenderer visual=$likelyVisual voice=$likelyVoice keep=${state.keepUnsentMessages} quickUnsend=${state.quickToggleUnsend}")
        }
        logInfoThrottled("dm:menu-inject:${viewModel.javaClass.name}:$fromRenderer", 600L) {
            "DM MessageActions injection timing renderer=$fromRenderer elapsed=${SystemClock.uptimeMillis() - started}ms " +
                "injected=$injectedLists visual=$likelyVisual voice=$likelyVoice typeSignalLength=${typeSignal.length}"
        }
    }

    private fun logDmMessageActionViewModelDiagnostics(viewModel: Any, fromRenderer: Boolean) {
        logInfoThrottled(
            "dm:action-viewmodel-diagnostics:${viewModel.javaClass.name}:$fromRenderer",
            600L
        ) {
            val started = SystemClock.uptimeMillis()
            val rowIds = extractRowBindableIds(collectUsefulIdsDeep(viewModel))
            val modelUrls = collectDmMediaObjectUrlCandidates(viewModel)
                .map { it.url }
                .filterNot(::looksLikeProfileImageUrl)
                .distinct()
                .take(8)
            "DM MessageActions viewModel diagnostics renderer=$fromRenderer class=${viewModel.javaClass.name} " +
                "elapsed=${SystemClock.uptimeMillis() - started}ms ids=${rowIds.size} fullIds=${rowIds.joinToString("|")} " +
                "modelUrls=${modelUrls.size} modelTypes=${dmUrlTypesForLog(modelUrls)} " +
                "modelFp=${dmCarouselFingerprintsForLog(modelUrls)} shape=${dmObjectShapeForLog(viewModel)}"
        }
    }

    private fun rememberKeepUnsentActionViewModelSnapshot(viewModel: Any?) {
        if (!state.keepUnsentMessages || viewModel == null) return
        if (hasRecentKeepUnsentActionRow()) return
        recentDmMessageActionAnchor()?.let { anchor ->
            rememberKeepUnsentActionRowSnapshot(anchor)
            if (hasRecentKeepUnsentActionRow()) return
        }

        val started = SystemClock.uptimeMillis()
        val texts = collectKeepUnsentActionTexts(viewModel)
            .filterNot(::isDmMessageActionMenuOrChromeText)
            .take(3)
        val rowIds = extractRowBindableIds(collectUsefulIdsDeep(viewModel))
        if (texts.isEmpty() && rowIds.isEmpty()) return

        val now = System.currentTimeMillis()
        val preservedTouchText = keepUnsentLastActionRowText
            ?.takeIf(::isPersistableKeepUnsentDeletedText)
            ?.takeIf { now - keepUnsentLastActionRowAtMs in 0..15_000L }
            ?.takeIf { keepUnsentLastActionRowAtMs >= dmLastMessageActionTouchAtMs - 250L }
        keepUnsentLastActionRowRoot = null
        keepUnsentLastActionRowText = texts.firstOrNull() ?: preservedTouchText
        keepUnsentLastActionRowIds = rowIds
        keepUnsentLastActionRowAtMs = now
        logInfo(
            "action-viewmodel-snapshot elapsed=${SystemClock.uptimeMillis() - started}ms texts=${formatKeepUnsentTexts(texts)} preserved=${formatKeepUnsentText(preservedTouchText)} " +
                "chosen=${formatKeepUnsentText(keepUnsentLastActionRowText)} ids=${formatKeepUnsentIds(rowIds)}"
        )
        if (rowIds.isNotEmpty()) {
            logInfo("action-viewmodel-snapshot-full-ids count=${rowIds.size} ids=${rowIds.joinToString("|")}")
        }
    }

    private fun rememberNewestVisibleKeepUnsentActionRowSoon(reason: String) {
        if (!state.keepUnsentMessages) return
        mainHandler.postDelayed({
            val started = SystemClock.uptimeMillis()
            rememberNewestVisibleKeepUnsentActionRow(reason)
            logInfoThrottled("keep-unsent:newest-row-fallback:$reason", 1_000L) {
                "Keep-unsent newest-row fallback finished reason=$reason elapsed=${SystemClock.uptimeMillis() - started}ms"
            }
        }, 220L)
    }

    private fun logKeepUnsentMenuSnapshotMissSoon(viewModel: Any?) {
        if (!state.keepUnsentMessages || viewModel == null) return
        val ref = WeakReference(viewModel)
        mainHandler.postDelayed({ logKeepUnsentMenuSnapshotMissOnce(ref.get()) }, 220L)
    }

    private fun logKeepUnsentMenuSnapshotMissOnce(viewModel: Any?) {
        if (!state.keepUnsentMessages) return
        if (hasRecentKeepUnsentActionRow()) return
        val now = System.currentTimeMillis()
        if (now - keepUnsentLastMenuSnapshotMissLogAtMs < 1_500L) return
        keepUnsentLastMenuSnapshotMissLogAtMs = now
        val touchAge = now - dmLastMessageActionTouchAtMs
        val texts = collectKeepUnsentActionTexts(viewModel)
            .filterNot(::isDmMessageActionMenuOrChromeText)
            .take(3)
        logInfo(
            "Keep-unsent menu snapshot has no row touchAge=$touchAge x=${dmLastMessageActionTouchX.toInt()} y=${dmLastMessageActionTouchY.toInt()} texts=${formatKeepUnsentTexts(texts)}"
        )
    }

    private fun isDmMessageActionMenuOrChromeText(text: String): Boolean {
        val value = text.trim().lowercase(Locale.US)
        if (value.isBlank()) return true
        if (value.matches(Regex("\\d{1,2}:\\d{2}\\s*(am|pm)?"))) return true
        if (looksLikeDmTimestampChromeText(value)) return true
        if (value.startsWith("double tap to") || value.startsWith("view photo") || value.startsWith("view video")) return true
        if (value.endsWith("_") && value.matches(Regex("[a-z0-9._]{3,30}"))) return true
        if (value.endsWith("reaction") || value == "see all emojis") return true
        return value in setOf(
            "download",
            "open by phone apps",
            "preview",
            "repost",
            "share to whatsapp story",
            "reply",
            "add sticker",
            "edit",
            "translate",
            "pin",
            "delete for you",
            "cancel",
            "forward",
            "copy",
            "make ai image",
            "unsend",
            "unsend for everyone",
            "more",
            "report",
            "save",
            "share",
            "select",
            "view photo",
            "view transcription"
        )
    }

    private fun looksLikeDmTimestampChromeText(value: String): Boolean {
        val dayPrefix = "(sun|mon|tue|wed|thu|fri|sat)(day)?\\.?"
        val timeSuffix = "\\d{1,2}:\\d{2}\\s*(am|pm)?"
        return value.matches(Regex("$dayPrefix\\s+$timeSuffix")) ||
            value.matches(Regex("(today|yesterday)\\s+$timeSuffix")) ||
            value.matches(Regex("$dayPrefix\\s+at\\s+$timeSuffix")) ||
            value.matches(Regex("(today|yesterday)\\s+at\\s+$timeSuffix"))
    }

    private fun isLikelyDmVisualMessageViewModel(viewModel: Any?): Boolean {
        return isLikelyDmVisualMessageTypeSignal(dmMessageViewModelTypeSignal(viewModel).lowercase(Locale.US))
    }

    private fun isLikelyDmVoiceMessageViewModel(viewModel: Any?): Boolean {
        return isLikelyDmVoiceMessageTypeSignal(dmMessageViewModelTypeSignal(viewModel).lowercase(Locale.US))
    }

    private fun isLikelyDmVisualMessageTypeSignal(type: String): Boolean {
        if (isLikelyDmVoiceMessageTypeSignal(type)) return false
        return type.contains("media") ||
            type.contains("raven") ||
            type.contains("visual") ||
            type.contains("photo") ||
            type.contains("video") ||
            type.contains("clip") ||
            type.contains("reel") ||
            type.contains("story") ||
            type.contains("xma")
    }

    private fun isStrongDmVisualMessageTypeSignal(type: String): Boolean {
        if (isLikelyDmVoiceMessageTypeSignal(type)) return false
        return type.contains("xma_media_share") ||
            type.contains("media_share") ||
            type.contains("direct_reel") ||
            type.contains("reel_share") ||
            type.contains("clips_share") ||
            type.contains("carousel") ||
            type.contains("sidecar") ||
            type.contains("album") ||
            type.contains("raven") ||
            type.contains("visual") ||
            type.contains("photo") ||
            type.contains("video") ||
            type.contains("clip") ||
            type.contains("reel") ||
            type.contains("story") ||
            type.contains("post") ||
            type.contains("view_once") ||
            type.contains("view once")
    }

    private fun isLikelyDmVoiceMessageTypeSignal(type: String): Boolean {
        return type.contains("voice") || type.contains("audio")
    }

    private fun dmMessageViewModelTypeSignal(viewModel: Any?): String {
        if (viewModel == null) return ""
        val now = SystemClock.uptimeMillis()
        dmMessageTypeSignalCache[viewModel]?.let { cached ->
            if (now - cached.atMs < 15_000L) {
                logInfoThrottled("dm:type-signal-cache:${viewModel.javaClass.name}", 2_000L) {
                    "DM MessageActions type signal cache hit class=${viewModel.javaClass.name} " +
                        "length=${cached.signal.length} previousElapsed=${cached.elapsedMs}ms"
                }
                return cached.signal
            }
        }
        val started = SystemClock.uptimeMillis()
        val parts = LinkedHashSet<String>()
        collectDmMessageTypeSignals(viewModel, parts, IdentityHashMap(), 0)
        val signal = parts.joinToString(" ")
        dmMessageTypeSignalCache[viewModel] = DmMessageTypeSignalCache(signal, now, SystemClock.uptimeMillis() - started)
        if (parts.isNotEmpty()) {
            logInfoThrottled("dm:type-signal:${viewModel.javaClass.name}:${parts.take(6).joinToString("|")}", 2_000L) {
                "DM MessageActions type signal class=${viewModel.javaClass.name} " +
                    "elapsed=${SystemClock.uptimeMillis() - started}ms values=${parts.take(12).joinToString("|")}"
            }
        }
        return signal
    }

    private fun collectDmMessageTypeSignals(
        value: Any?,
        out: MutableSet<String>,
        seen: IdentityHashMap<Any, Boolean>,
        depth: Int
    ) {
        if (value == null || depth > 2 || out.size >= 48) return
        val cls = value.javaClass
        if (Enum::class.java.isAssignableFrom(cls)) {
            enumName(value)?.let { out += it }
            enumWire(value)?.let { out += it }
            return
        }
        if (isSimpleDmUrlValue(cls) || value is Context || value is View || value is Drawable || value is Bitmap) return
        if (seen.put(value, true) != null) return
        dmNonStaticFields(cls).asSequence().take(80).forEach { field ->
            if (out.size >= 48) return@forEach
            if (looksLikeDmMediaTypeToken(field.name)) out += field.name
            if (looksLikeDmMediaTypeToken(field.type.name)) out += field.type.name
            if (!shouldInspectDmTypeSignalField(field.type)) return@forEach
            runCatching {
                collectDmMessageTypeSignals(field.get(value), out, seen, depth + 1)
            }
        }
    }

    private fun shouldInspectDmTypeSignalField(cls: Class<*>): Boolean {
        if (Enum::class.java.isAssignableFrom(cls)) return true
        if (cls.isPrimitive || Number::class.java.isAssignableFrom(cls) || cls == java.lang.Boolean::class.java) return false
        val name = cls.name
        if (name.startsWith("android.") || name.startsWith("androidx.") || name.startsWith("java.")) return false
        return name.startsWith("p000X.") || name.startsWith("X.") || name.startsWith("com.instagram.")
    }

    private fun looksLikeDmMediaTypeToken(value: String?): Boolean {
        val lower = value?.lowercase(Locale.US) ?: return false
        return lower.contains("voice") ||
            lower.contains("audio") ||
            lower.contains("media") ||
            lower.contains("raven") ||
            lower.contains("visual") ||
            lower.contains("photo") ||
            lower.contains("video") ||
            lower.contains("clip") ||
            lower.contains("reel") ||
            lower.contains("story") ||
            lower.contains("xma")
    }

    private fun isDmLongPressActionList(list: List<*>): Boolean {
        val cls = dmLongPressActionDataClass ?: return false
        return list.firstOrNull { it != null }?.let { cls.isInstance(it) } == true
    }

    private fun dmAllowedMessageActions(
        viewModel: Any?,
        original: List<*>,
        typeSignal: String,
        likelyVisual: Boolean,
        likelyVoiceViewModel: Boolean
    ): List<Int> {
        val voiceViewModel = likelyVoiceViewModel
        val voiceMenu = looksLikeDirectVoiceMessageMenu(original)
        val recentAnchor = recentDmMessageActionAnchor()
        val voiceTouch = viewHasLocalVoiceHint(recentAnchor)
        val visualMenu = looksLikeDirectVisualMessageMenu(original)
        val visualTouch = dmLocalVisualAnchorHint(recentAnchor)
        val snapshot = recentDmMessageActionMediaSnapshot()
        val snapshotVisual = snapshot?.visual == true || snapshot?.urls?.any { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) } == true
        val snapshotVoice = snapshot?.voice == true || snapshot?.urls?.any { isAudioUrl(it) || isLikelyAudioHttpUrl(it) } == true
        val freshLongPressAnchor = recentAnchor != null
        val strongVisualViewModel = isStrongDmVisualMessageTypeSignal(typeSignal)
        val likelyVisualContext = visualMenu ||
            (freshLongPressAnchor && (visualTouch.visual || snapshotVisual || strongVisualViewModel))
        val likelyVoice = voiceMenu ||
            (freshLongPressAnchor && !likelyVisualContext && (voiceViewModel || snapshotVoice || voiceTouch))
        val allowed = when {
            likelyVoice -> listOf(DM_ACTION_DOWNLOAD)
            likelyVisualContext -> allDmMessageActions()
            else -> emptyList()
        }
        rememberDmMessageActionMenuContext(allowed, typeSignal, likelyVoice, likelyVisualContext)
        logInfoThrottled("dm:classify:${viewModel?.javaClass?.name}:${allowed.joinToString(",")}", 1_500L) {
            "DM MessageActions classified viewModel=${viewModel?.javaClass?.name ?: "null"} " +
                "freshAnchor=$freshLongPressAnchor visualVm=$likelyVisual strongVisualVm=$strongVisualViewModel " +
                "visualMenu=$visualMenu visualTouch=${visualTouch.visual} visualReason=${visualTouch.reason} " +
                "snapshot=${snapshot?.urls?.size ?: 0}:${snapshot?.reason ?: "-"} " +
                "visualElapsed=${visualTouch.elapsedMs}ms voiceVm=$voiceViewModel voiceMenu=$voiceMenu voiceTouch=$voiceTouch " +
                "allowed=${dmActionLabelsForLog(allowed)} anchor=${describeViewBrief(recentAnchor)} labels=${dmMenuLabelsForLog(original)}"
        }
        return allowed
    }

    private fun rememberDmMessageActionMenuContext(
        allowedActions: List<Int>,
        typeSignal: String,
        voice: Boolean,
        visual: Boolean
    ) {
        val now = System.currentTimeMillis()
        dmLatestMessageActionMenuWasVoice = voice && !visual && allowedActions == listOf(DM_ACTION_DOWNLOAD)
        dmLatestMessageActionMenuWasVisual = visual && allowedActions.any { it != DM_ACTION_PREVIEW }
        dmLatestMessageActionMenuTypeSignal = typeSignal
        dmLatestMessageActionMenuAtMs = now
        dmLastRenderedMessageActionMenuVoiceContext = when {
            dmLatestMessageActionMenuWasVisual -> false
            dmLatestMessageActionMenuWasVoice -> true
            else -> null
        }
        dmLastRenderedMessageActionMenuAtMs = now
        if (dmLatestMessageActionMenuWasVisual) {
            dmLatestMessageActionWasVoice = false
            dmLatestMessageActionWasVisual = true
            dmLatestMessageActionVoiceAtMs = 0L
            dmLastVoiceContextAtMs = 0L
        } else if (dmLatestMessageActionMenuWasVoice) {
            dmLatestMessageActionWasVoice = true
            dmLatestMessageActionWasVisual = false
            dmLatestMessageActionVoiceAtMs = now
            dmLastVoiceContextAtMs = now
        } else {
            dmLatestMessageActionWasVoice = false
            dmLatestMessageActionWasVisual = false
            dmLatestMessageActionVoiceAtMs = 0L
            dmLastVoiceContextAtMs = 0L
        }
    }

    private fun allDmMessageActions(): List<Int> = (DM_ACTION_DOWNLOAD..DM_ACTION_WHATSAPP_STORY).toList()

    private fun insertDmMessageActionsAfterTimestamp(context: Context, original: List<*>, allowedActions: List<Int>): List<Any?>? {
        if (allowedActions.isEmpty()) return null
        if (containsCustomDmMessageAction(original) || hasInjectedDmItems(context, original)) {
            rememberExistingDmCustomActions(context, original)
            return null
        }
        val customRows = ArrayList<Any?>()
        for (action in allowedActions) {
            createDmLongPressActionData(context, action)?.let { customRows += it }
        }
        if (customRows.isEmpty()) return null
        val insertAt = dmMessageActionInsertIndex(original)
        val extended = ArrayList<Any?>(original.size + customRows.size)
        extended.addAll(original.take(insertAt))
        extended.addAll(customRows)
        extended.addAll(original.drop(insertAt))
        logInfo(
            "DM MessageActions custom rows inserted index=$insertAt custom=${dmActionLabelsForLog(allowedActions)} " +
                "original=${dmMenuLabelsForLog(original)} result=${dmMenuLabelsForLog(extended)}"
        )
        return extended
    }

    private fun dmMessageActionInsertIndex(original: List<*>): Int {
        if (original.isEmpty()) return 0
        val timestampIndex = original.indexOfFirst { item ->
            isDmMessageActionTimestampLabel(extractDmMenuLabel(item))
        }
        return when {
            timestampIndex >= 0 -> (timestampIndex + 1).coerceAtMost(original.size)
            else -> 1.coerceAtMost(original.size)
        }
    }

    private fun isDmMessageActionTimestampLabel(label: String?): Boolean {
        val value = label?.trim()?.lowercase(Locale.US).orEmpty()
        if (value.isBlank()) return false
        return timeOfDayPattern.matches(value)
    }

    private fun createDmLongPressActionData(context: Context?, action: Int): Any? {
        val constructor = dmLongPressActionDataConstructor ?: return null
        val normalType = dmNormalLongPressType ?: return null
        val customEnum = dmEnumForCustomAction(action) ?: dmPassiveLongPressEnum ?: return null
        return runCatching {
            val args = arrayOfNulls<Any>(11)
            args[0] = null
            args[1] = normalType
            args[2] = customEnum
            args[3] = null
            args[4] = null
            args[5] = dmMenuIconResourceId(context, action)
            args[6] = null
            args[7] = dmActionLabel(action)
            args[8] = "$DM_MESSAGE_ACTION_MARKER_PREFIX$action"
            args[9] = null
            args[10] = null
            constructor.newInstance(*args).also { data ->
                dmCustomLongPressActions[data] = action
                if (customEnum !== dmPassiveLongPressEnum) rememberDmCustomLongPressEnumAction(customEnum, action)
            }
        }.onFailure { logError("Create DM LongPressActionData failed", it) }.getOrNull()
    }

    private fun dmEnumForCustomAction(action: Int): Any? {
        val value = findFirstDmEnumWire(*dmCustomEnumWiresForAction(action))
            ?: findFirstUnusedDmEnumWire(
                "good_result",
                "bad_result",
                "good_response",
                "bad_response",
                "ai_subscription_manage_update",
                "creator_ai_inspect_message",
                "provide_agent_refinement_feedback",
                "regenerate_ai_response",
                "see_info",
                "ask_meta_ai",
                "summarize_with_ai",
                "save_media",
                "share",
                "forward",
                "share_to_story"
            )
            ?: dmCustomLongPressEnum
            ?: dmPassiveLongPressEnum
        if (value != null) rememberDmCustomLongPressEnumAction(value, action)
        return value
    }

    private fun dmCustomEnumWiresForAction(action: Int): Array<String> {
        return when (action) {
            DM_ACTION_DOWNLOAD -> arrayOf("good_result", "save_media", "create_cutout")
            DM_ACTION_OPEN_APPS -> arrayOf("bad_result", "good_response", "share")
            DM_ACTION_PREVIEW -> arrayOf("creator_ai_inspect_message", "see_info", "details")
            DM_ACTION_REPOST -> arrayOf("bad_response", "provide_agent_refinement_feedback", "forward")
            else -> arrayOf("ai_subscription_manage_update", "summarize_with_ai", "ask_meta_ai", "share_to_story")
        }
    }

    private fun findFirstDmEnumWire(vararg wires: String): Any? {
        val enumClass = dmLongPressActionEnumClass ?: return null
        return wires.firstNotNullOfOrNull { wire -> findDmEnumLikeValueExact(enumClass, null, wire, null) }
    }

    private fun findFirstUnusedDmEnumWire(vararg wires: String): Any? {
        return wires.firstNotNullOfOrNull { wire ->
            val value = findFirstDmEnumWire(wire) ?: return@firstNotNullOfOrNull null
            synchronized(dmCustomLongPressEnumActions) {
                if (!dmCustomLongPressEnumActions.containsKey(value)) value else null
            }
        }
    }

    private fun findDmEnumLikeValue(cls: Class<*>?, enumName: String?, wireName: String?, fieldName: String?): Any? {
        findDmEnumLikeValueExact(cls, enumName, wireName, fieldName)?.let { return it }
        return runCatching {
            val values = cls?.getDeclaredMethod("values") ?: return@runCatching null
            values.isAccessible = true
            (values.invoke(null) as? Array<*>)?.firstOrNull()
        }.getOrNull()
    }

    private fun findDmEnumLikeValueExact(cls: Class<*>?, enumName: String?, wireName: String?, fieldName: String?): Any? {
        staticFieldValue(cls, fieldName)?.let { return it }
        return runCatching {
            val values = cls?.getDeclaredMethod("values") ?: return@runCatching null
            values.isAccessible = true
            val candidates = values.invoke(null) as? Array<*> ?: return@runCatching null
            candidates.firstOrNull { candidate ->
                (enumName != null && enumName == enumName(candidate)) ||
                    (wireName != null && wireName == stringField(candidate, "A00"))
            }
        }.getOrNull()
    }

    private fun staticFieldValue(cls: Class<*>?, fieldName: String?): Any? {
        if (cls == null || fieldName == null) return null
        return runCatching {
            val field = cls.getDeclaredField(fieldName)
            field.isAccessible = true
            field.get(null)
        }.getOrNull()
    }

    private fun enumName(value: Any?): String? {
        if (value == null) return null
        return runCatching { value.javaClass.getMethod("name").invoke(value) as? String }.getOrNull()
    }

    private fun enumWire(value: Any?): String? {
        return stringField(value, "A00")?.takeIf { it.isNotBlank() } ?: enumName(value)
    }

    private fun enumWireField(item: Any?, fieldName: String): String? {
        val value = fieldValueDeep(item, fieldName)
        return enumWire(value)
    }

    private fun findDmActionInListener(listener: Any?): Int {
        val actionClass = dmLongPressActionDataClass ?: return -1
        if (listener == null) return -1
        var cls: Class<*>? = listener.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (!actionClass.isAssignableFrom(field.type)) return@forEach
                runCatching {
                    field.isAccessible = true
                    actionFromDmLongPressActionData(field.get(listener))
                }.getOrNull()?.takeIf { it >= 0 }?.let { return it }
            }
            cls = cls.superclass
        }
        return -1
    }

    private fun dmActionFromCustomLongPressEnumArgs(args: Array<Any?>?): Int {
        args?.forEach { arg ->
            dmActionFromCustomLongPressEnum(arg).takeIf { it >= 0 }?.let { return it }
        }
        return -1
    }

    private fun firstDmActionEnumArg(args: Array<Any?>?): Any? {
        return args?.firstOrNull { dmActionFromCustomLongPressEnum(it) >= 0 }
    }

    private fun dmActionFromCustomLongPressEnum(enumValue: Any?): Int {
        if (enumValue == null || enumValue === dmPassiveLongPressEnum) return -1
        return synchronized(dmCustomLongPressEnumActions) { dmCustomLongPressEnumActions[enumValue] ?: -1 }
    }

    private fun rememberDmCustomLongPressEnumAction(enumValue: Any?, action: Int) {
        if (enumValue == null || enumValue === dmPassiveLongPressEnum) return
        dmCustomLongPressEnumActions[enumValue] = action
    }

    private fun actionFromDmLongPressActionData(data: Any?): Int {
        val actionClass = dmLongPressActionDataClass ?: return -1
        if (data == null || !actionClass.isInstance(data)) return -1
        synchronized(dmCustomLongPressActions) {
            dmCustomLongPressActions[data]?.let { return it }
        }

        val markerAction = actionFromDmMessageActionMarker(markerFromDmLongPressActionData(data))
        if (markerAction >= 0) {
            rememberDmCustomLongPressAction(data, markerAction)
            rememberDmCustomEnumFromData(data, markerAction)
            clearDmLongPressSecondaryText(data)
            return markerAction
        }

        val labelAction = actionFromDmCustomLabel(extractDmMenuLabel(data))
        if (labelAction >= 0) {
            rememberDmCustomLongPressAction(data, labelAction)
            rememberDmCustomEnumFromData(data, labelAction)
        }
        return labelAction
    }

    private fun actionFromDmCustomLabel(label: String?): Int {
        return when (label?.trim()?.lowercase(Locale.US)) {
            "download" -> DM_ACTION_DOWNLOAD
            "open by phone apps" -> DM_ACTION_OPEN_APPS
            "preview" -> DM_ACTION_PREVIEW
            "repost" -> DM_ACTION_REPOST
            "share to whatsapp story" -> DM_ACTION_WHATSAPP_STORY
            else -> -1
        }
    }

    private fun containsCustomDmMessageAction(items: List<*>): Boolean = items.any { actionFromDmLongPressActionData(it) >= 0 }

    private fun rememberExistingDmCustomActions(context: Context?, items: List<*>) {
        items.forEach { item ->
            val known = actionFromDmLongPressActionData(item)
            if (known >= 0) {
                clearDmLongPressSecondaryText(item)
                return@forEach
            }
            val label = extractDmMenuLabel(item) ?: return@forEach
            for (action in DM_ACTION_DOWNLOAD..DM_ACTION_WHATSAPP_STORY) {
                if (label == dmActionLabel(action)) {
                    rememberDmCustomLongPressAction(item, action)
                    rememberDmCustomEnumFromData(item, action)
                    clearDmLongPressSecondaryText(item)
                    return@forEach
                }
            }
        }
    }

    private fun rememberDmCustomLongPressAction(data: Any?, action: Int) {
        if (data == null) return
        dmCustomLongPressActions[data] = action
    }

    private fun rememberDmCustomEnumFromData(data: Any?, action: Int) {
        fieldValueDeep(data, "A04")?.let { rememberDmCustomLongPressEnumAction(it, action) }
    }

    private fun clearDmLongPressSecondaryText(data: Any?) {
        val actionClass = dmLongPressActionDataClass ?: return
        if (data == null || !actionClass.isInstance(data)) return
        listOf("A0A", "A09", "A08").forEach { fieldName ->
            runCatching {
                val field = data.javaClass.getDeclaredField(fieldName)
                field.isAccessible = true
                val value = field.get(data) as? String
                if (isDmMessageActionMarker(value)) field.set(data, null)
            }
        }
    }

    private fun markerFromDmLongPressActionData(data: Any?): String? {
        val actionClass = dmLongPressActionDataClass ?: return null
        if (data == null || !actionClass.isInstance(data)) return null
        listOf("A0A", "A09", "A08").forEach { fieldName ->
            stringField(data, fieldName)?.takeIf { isDmMessageActionMarker(it) }?.let { return it }
        }
        data.javaClass.declaredFields.forEach { field ->
            if (field.type != String::class.java) return@forEach
            runCatching {
                field.isAccessible = true
                field.get(data) as? String
            }.getOrNull()?.takeIf { isDmMessageActionMarker(it) }?.let { return it }
        }
        return null
    }

    private fun isDmMessageActionMarker(value: String?): Boolean = value?.startsWith(DM_MESSAGE_ACTION_MARKER_PREFIX) == true

    private fun actionFromDmMessageActionMarker(marker: String?): Int {
        if (!isDmMessageActionMarker(marker)) return -1
        return marker?.substring(DM_MESSAGE_ACTION_MARKER_PREFIX.length)?.toIntOrNull() ?: -1
    }

    private fun wrapCustomDmMessageActionListenerArg(args: Array<Any?>?, labelIndex: Int, listenerIndex: Int) {
        if (args == null || listenerIndex !in args.indices) return
        val listener = args[listenerIndex] as? View.OnClickListener ?: return
        if (listener is DmMessageActionClickListener || listener is DmNativeUnsendClickListener) return
        val label = if (labelIndex >= 0 && labelIndex in args.indices) args[labelIndex] as? String else null
        if (state.keepUnsentMessages && isNativeDmUnsendLabel(label)) {
            args[listenerIndex] = DmNativeUnsendClickListener(listener)
            return
        }
        if (!state.enableDmContextMenuOptions) return
        var action = -1
        if (label != null) action = actionFromDmCustomLabel(label)
        if (action < 0) action = findDmActionInListener(listener)
        if (action < 0) return
        args[listenerIndex] = DmMessageActionClickListener(action, listener)
    }

    private fun isNativeDmUnsendListener(listener: Any?): Boolean {
        val actionClass = dmLongPressActionDataClass ?: return false
        if (listener == null) return false
        var cls: Class<*>? = listener.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (!actionClass.isAssignableFrom(field.type)) return@forEach
                val label = runCatching {
                    field.isAccessible = true
                    extractDmMenuLabel(field.get(listener))
                }.getOrNull()
                if (isNativeDmUnsendLabel(label)) return true
            }
            cls = cls.superclass
        }
        return false
    }

    private fun looksLikeSponsoredPayloadClass(className: String): Boolean {
        val lower = className.lowercase(Locale.US)
        return lower.contains("sponsored") ||
            lower.contains("advertiser") ||
            lower.contains("leadgen") ||
            lower.contains("lead_gen")
    }

    private fun isNativeDmUnsendLabel(label: String?): Boolean {
        return label?.trim()?.lowercase(Locale.US) == "unsend"
    }

    private fun hasDmLongPressActionDataField(cls: Class<*>?): Boolean {
        val actionClass = dmLongPressActionDataClass ?: return false
        var current = cls
        while (current != null && current != Any::class.java) {
            if (current.declaredFields.any { actionClass.isAssignableFrom(it.type) }) return true
            current = current.superclass
        }
        return false
    }

    private fun addDmClassesUsingString(out: MutableSet<Class<*>>, value: String) {
        val cacheKey = "DmStringClasses_${value.hashCode().toUInt().toString(16)}"
        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadString(cacheKey)?.let { cached ->
                if (cached == "-") return
                cached.split('\u0000')
                    .asSequence()
                    .filter { it.isNotBlank() }
                    .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
                    .forEach { out += it }
                return
            }
        }
        val names = dexBridge.findClassNamesUsingStrings(value).distinct()
        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.saveString(cacheKey, names.takeIf { it.isNotEmpty() }?.joinToString("\u0000") ?: "-")
        }
        names.forEach { name ->
            runCatching { Class.forName(name, false, appClassLoader) }.getOrNull()?.let { out += it }
        }
    }

    private fun methodHasParameter(method: Method, type: Class<*>): Boolean {
        return method.parameterTypes.any { it == type || type.isAssignableFrom(it) || it.isAssignableFrom(type) }
    }

    private fun constructorHasParameter(constructor: Constructor<*>, type: Class<*>): Boolean {
        return constructor.parameterTypes.any { it == type || type.isAssignableFrom(it) || it.isAssignableFrom(type) }
    }

    private fun firstArgOfType(args: Array<Any?>?, type: Class<*>): Any? {
        return args?.firstOrNull { it != null && type.isInstance(it) }
    }

    private fun contextFromArgs(args: Array<Any?>?): Context? {
        args?.forEach { arg ->
            when (arg) {
                is Context -> return arg
                is View -> return arg.context
            }
        }
        return null
    }

    private fun shouldSuppressDmMessageActionOpenLifecycle(viewModel: Any?): Boolean {
        return isLikelyDmVisualMessageViewModel(viewModel) || dmViewModelContainsCustomMessageAction(viewModel)
    }

    private fun dmViewModelContainsCustomMessageAction(viewModel: Any?): Boolean {
        if (viewModel == null) return false
        var cls: Class<*>? = viewModel.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (!List::class.java.isAssignableFrom(field.type)) return@forEach
                runCatching {
                    field.isAccessible = true
                    val list = field.get(viewModel) as? List<*> ?: return@runCatching false
                    containsCustomDmMessageAction(list)
                }.getOrDefault(false).takeIf { it }?.let { return true }
            }
            cls = cls.superclass
        }
        return false
    }

    private fun suppressDmMessageActionOpenLifecycleCallbacks(args: Array<Any?>?, paramTypes: Array<Class<*>>) {
        if (args == null) return
        args.indices.forEach { index ->
            val original = args[index] ?: return@forEach
            val paramType = paramTypes.getOrNull(index)
            val kind = dmLifecycleKind(original, paramType) ?: return@forEach
            val iface = dmLifecycleProxyInterface(original, paramType, kind) ?: return@forEach
            createDmLifecycleNoHideProxy(original, iface, kind)?.let { args[index] = it }
        }
    }

    private fun dmLifecycleKind(value: Any?, paramType: Class<*>?): String? {
        return when {
            isDmChromeLifecycleType(paramType) || isDmChromeLifecycleCallback(value) -> "chrome"
            isDmVisibilityLifecycleType(paramType) || isDmVisibilityLifecycleCallback(value) -> "visibility"
            else -> null
        }
    }

    private fun isDmChromeLifecycleCallback(value: Any?): Boolean = value != null && hasNoArgMethod(value, "EQL") && hasNoArgMethod(value, "EQf")

    private fun isDmVisibilityLifecycleCallback(value: Any?): Boolean = value != null && hasNoArgMethod(value, "Dab") && hasNoArgMethod(value, "Gj5")

    private fun isDmChromeLifecycleType(type: Class<*>?): Boolean = type != null && findNoArgMethod(type, "EQL") != null && findNoArgMethod(type, "EQf") != null

    private fun isDmVisibilityLifecycleType(type: Class<*>?): Boolean = type != null && findNoArgMethod(type, "Dab") != null && findNoArgMethod(type, "Gj5") != null

    private fun dmLifecycleProxyInterface(value: Any, paramType: Class<*>?, kind: String): Class<*>? {
        if (paramType?.isInterface == true) {
            if (kind == "chrome" && isDmChromeLifecycleType(paramType)) return paramType
            if (kind == "visibility" && isDmVisibilityLifecycleType(paramType)) return paramType
        }
        val interfaces = mutableListOf<Class<*>>()
        collectInterfaces(value.javaClass, interfaces)
        return interfaces.firstOrNull { iface ->
            (kind == "chrome" && isDmChromeLifecycleType(iface)) ||
                (kind == "visibility" && isDmVisibilityLifecycleType(iface))
        }
    }

    private fun collectInterfaces(cls: Class<*>?, out: MutableList<Class<*>>) {
        if (cls == null || cls == Any::class.java) return
        cls.interfaces.forEach { iface ->
            if (iface !in out) {
                out += iface
                collectInterfaces(iface, out)
            }
        }
        collectInterfaces(cls.superclass, out)
    }

    private fun createDmLifecycleNoHideProxy(target: Any, iface: Class<*>, kind: String): Any? {
        return runCatching {
            Proxy.newProxyInstance(iface.classLoader, arrayOf(iface)) { proxy, method, args ->
                when {
                    method.name == "toString" && method.parameterTypes.isEmpty() -> "PurrfectInstaDmLifecycleProxy($kind)"
                    method.name == "hashCode" && method.parameterTypes.isEmpty() -> System.identityHashCode(proxy)
                    method.name == "equals" && method.parameterTypes.size == 1 -> args != null && args.isNotEmpty() && proxy === args[0]
                    shouldSuppressDmLifecycleOpenMethod(kind, method) -> defaultResult(method.returnType)
                    else -> runCatching {
                        method.isAccessible = true
                        method.invoke(target, *(args ?: emptyArray()))
                    }.getOrElse { throwable ->
                        val cause = (throwable as? java.lang.reflect.InvocationTargetException)?.cause
                        throw (cause ?: throwable)
                    }
                }
            }
        }.getOrNull()
    }

    private fun shouldSuppressDmLifecycleOpenMethod(kind: String, method: Method): Boolean {
        if (suppressDmMessageActionOpenLifecycle.get() != true) return false
        if (method.parameterTypes.isNotEmpty() || method.returnType != Void.TYPE) return false
        return when (kind) {
            "visibility" -> method.name == "Dab" || method.name != "Gj5"
            "chrome" -> method.name == "EQf" || method.name != "EQL"
            else -> false
        }
    }

    private fun hasNoArgMethod(target: Any?, methodName: String): Boolean {
        return target != null && findNoArgMethod(target.javaClass, methodName) != null
    }

    private fun findNoArgMethod(cls: Class<*>?, methodName: String): Method? {
        if (cls == null) return null
        val key = "${cls.name}#$methodName()"
        dmNoArgMethodCache[key]?.let { return it }
        if (dmNoArgMethodMissingCache.contains(key)) return null
        var current = cls
        while (current != null && current != Any::class.java) {
            runCatching {
                val method = current.getDeclaredMethod(methodName)
                if (method.parameterTypes.isEmpty()) {
                    method.isAccessible = true
                    dmNoArgMethodCache[key] = method
                    return method
                }
            }
            current = current.superclass
        }
        return runCatching {
            val method = cls.getMethod(methodName)
            if (method.parameterTypes.isEmpty()) method.apply { isAccessible = true } else null
        }.getOrNull()?.also { dmNoArgMethodCache[key] = it }
            ?: run {
                dmNoArgMethodMissingCache.add(key)
                null
            }
    }

    private fun firstDmMessageActionDelegate(args: Array<Any?>?): Any? {
        args?.forEach { arg ->
            if (arg != null && findDmMessageActionsViewModel(arg) != null && (hasNoArgMethod(arg, "Edu") || hasNoArgMethod(arg, "EjE"))) {
                return arg
            }
        }
        return null
    }

    private fun rememberDmMessageActionController(viewModel: Any?, controller: Any?) {
        if (viewModel == null || controller == null) return
        dmMessageActionControllers[viewModel] = controller
        dmLatestMessageActionController = controller
    }

    private fun rememberDmMessageActionDelegate(delegate: Any?) {
        if (delegate == null) return
        val viewModel = findDmMessageActionsViewModel(delegate) ?: return
        rememberDmMessageActionController(viewModel, delegate)
        val chromeCallback = fieldValueDeep(delegate, "A0b")
        val visibilityCallback = fieldValueDeep(delegate, "A0h")
        val lifecycle = DmMessageActionLifecycle(chromeCallback, visibilityCallback, delegate)
        dmMessageActionLifecycles[viewModel] = lifecycle
        dmLatestMessageActionLifecycle = lifecycle
    }

    private fun rememberDmMessageActionLifecycle(viewModel: Any?, args: Array<Any?>?) {
        if (viewModel == null || args == null) return
        var chromeCallback: Any? = null
        var visibilityCallback: Any? = null
        val viewModelIndex = indexOfDmArg(args, viewModel)
        if (viewModelIndex >= 22) {
            args.getOrNull(viewModelIndex - 22)?.takeIf { isDmChromeLifecycleCallback(it) }?.let { chromeCallback = it }
        }
        if (chromeCallback == null && viewModelIndex >= 23) {
            args.getOrNull(viewModelIndex - 23)?.takeIf { isDmChromeLifecycleCallback(it) }?.let { chromeCallback = it }
        }
        if (visibilityCallback == null && viewModelIndex >= 17) {
            args.getOrNull(viewModelIndex - 17)?.takeIf { isDmVisibilityLifecycleCallback(it) }?.let { visibilityCallback = it }
        }
        args.forEach { arg ->
            if (arg == null) return@forEach
            if (chromeCallback == null && hasNoArgMethod(arg, "EQL") && hasNoArgMethod(arg, "EQf")) chromeCallback = arg
            if (visibilityCallback == null && hasNoArgMethod(arg, "Dab") && hasNoArgMethod(arg, "Gj5")) visibilityCallback = arg
        }
        if (chromeCallback == null && visibilityCallback == null) return
        val lifecycle = DmMessageActionLifecycle(chromeCallback, visibilityCallback, null)
        dmMessageActionLifecycles[viewModel] = lifecycle
        dmLatestMessageActionLifecycle = lifecycle
    }

    private fun indexOfDmArg(args: Array<Any?>?, target: Any?): Int {
        if (args == null || target == null) return -1
        return args.indexOfFirst { it === target }
    }

    private fun restoreDmMessageActionsUiSoon(source: Any?, sources: Array<Any?>?) {
        val now = System.currentTimeMillis()
        if (now - dmLastRestoreUiScheduleLogAtMs > 350L) {
            dmLastRestoreUiScheduleLogAtMs = now
            val root = currentActivity?.window?.decorView
            logInfo(
                "Scheduling DM MessageActions UI restore source=${describeObjectBrief(source)} sources=${sources?.size ?: 0} " +
                    "surface=${root?.let { directMessageSurfaceReason(it) } ?: "-"} " +
                    "activeOverlay=${root?.let { rootContainsActiveDmMessageActionsOverlay(it) } ?: false} " +
                    "purrfectRows=${root?.let { hasPurrfectDmActionRowsVisible(it) } ?: false} " +
                    "guardRemaining=${(dmSavedStateLongPressGuardUntilMs - now).coerceAtLeast(0L)}ms"
            )
        }
        mainHandler.post { restoreDmMessageActionsUiOnly(source, sources) }
        logInfoThrottled("dm:restore-thread-not-scheduled", 1_000L) {
            "DM thread surface restore stays lifecycle-only after custom action; no repeated delayed restore passes"
        }
    }

    private fun restoreDmMessageActionsUiOnly(source: Any?, sources: Array<Any?>?) {
        var lifecycle: DmMessageActionLifecycle? = null
        sources?.forEach { candidate ->
            lifecycle = lifecycle ?: dmMessageActionLifecycleForSource(candidate)
        }
        lifecycle = lifecycle ?: dmMessageActionLifecycleForSource(source) ?: dmLatestMessageActionLifecycle
        val root = currentActivity?.window?.decorView
        val controller = findDmMessageActionController(source, sources)
        logInfo(
            "Running DM MessageActions UI restore attempt lifecycle=${lifecycle != null} source=${describeObjectBrief(source)} " +
                "sources=${sources?.size ?: 0} controllerCandidate=${controller != null} " +
                "surface=${root?.let { directMessageSurfaceReason(it) } ?: "-"}"
        )
        restoreDmMessageActionsUiOnly(lifecycle)
        if (controller != null) {
            mainHandler.post {
                val restored = invokeDmControllerRestoreCallbacks(controller)
                logInfo("DM MessageActions controller restore callbacks restored=$restored controller=${describeObjectBrief(controller)}")
            }
        }
    }

    private fun restoreDmMessageActionsUiOnly(lifecycle: DmMessageActionLifecycle?) {
        if (lifecycle == null) {
            logInfoThrottled("dm:restore-ui-no-lifecycle", 750L) {
                "DM MessageActions lifecycle restore skipped: no lifecycle surface=${dmSurfaceForLog()}"
            }
            return
        }
        var restored = invokeNamedNoArg(lifecycle.chromeCallback, "EQL")
        restored = invokeNamedNoArg(lifecycle.visibilityCallback, "Gj5") || restored
        if (!restored) {
            restored = invokeNamedNoArg(lifecycle.delegateCallback, "EjE") || restored
            restored = invokeNamedNoArg(lifecycle.delegateCallback, "Edu") || restored
            restored = invokeNamedNoArg(lifecycle.delegateCallback, "Edd") || restored
        }
        logInfo(
            "DM MessageActions lifecycle restore callbacks restored=$restored " +
                "chrome=${describeObjectBrief(lifecycle.chromeCallback)} visibility=${describeObjectBrief(lifecycle.visibilityCallback)} " +
                "delegate=${describeObjectBrief(lifecycle.delegateCallback)}"
        )
    }

    private fun dmMessageActionLifecycleForSource(source: Any?): DmMessageActionLifecycle? {
        val viewModel = findDmMessageActionsViewModel(source) ?: return null
        return dmMessageActionLifecycles[viewModel]
    }

    private fun findDmMessageActionController(source: Any?, sources: Array<Any?>?): Any? {
        findDmControllerObject(source)?.let { return it }
        dmControllerForViewModel(findDmMessageActionsViewModel(source))?.let { return it }
        sources?.forEach { candidate ->
            findDmControllerObject(candidate)?.let { return it }
            dmControllerForViewModel(findDmMessageActionsViewModel(candidate))?.let { return it }
        }
        return dmLatestMessageActionController
    }

    private fun findDmControllerObject(source: Any?): Any? {
        if (source == null) return null
        val controllerClass = dmMessageActionsControllerClass ?: return null
        if (controllerClass.isInstance(source)) return source
        dmControllerFields(source.javaClass).forEach { field ->
            runCatching { field.get(source) }.getOrNull()?.let { return it }
        }
        return null
    }

    private fun dmControllerForViewModel(viewModel: Any?): Any? {
        if (viewModel == null) return null
        return dmMessageActionControllers[viewModel]
    }

    private fun invokeDmControllerRestoreCallbacks(controller: Any?): Boolean {
        var invoked = invokeNamedNoArg(controller, "EjE")
        invoked = invokeNamedNoArg(controller, "Edu") || invoked
        invoked = invokeNamedNoArg(controller, "Edd") || invoked
        invoked = invokeNamedNoArg(fieldValueDeep(controller, "A0h"), "Gj5") || invoked
        invoked = invokeNamedNoArg(fieldValueDeep(controller, "A0b"), "EQL") || invoked
        val callback = fieldValueDeep(controller, "A0T")
        invoked = invokeNamedNoArg(callback, "EjE") || invoked
        invoked = invokeNamedNoArg(callback, "Edu") || invoked
        invoked = invokeNamedNoArg(callback, "Edd") || invoked
        return invoked
    }

    private fun invokeNamedNoArg(target: Any?, methodName: String): Boolean {
        val method = findNoArgMethod(target?.javaClass, methodName) ?: return false
        if (method.returnType != Void.TYPE) return false
        return runCatching {
            method.invoke(target)
            true
        }.onFailure { logError("DM MessageActions callback $methodName failed", it) }.getOrDefault(false)
    }

    private fun restoreDmThreadSurface() {
        val root = currentActivity?.window?.decorView ?: return
        val reason = directMessageSurfaceReason(root)
        val activeOverlay = rootContainsActiveDmMessageActionsOverlay(root)
        val purrfectRows = hasPurrfectDmActionRowsVisible(root)
        if (reason != "direct-thread-root-id" && reason != "message-list-with-thread-chrome") {
            logInfoThrottled("dm:restore-thread-skip:${reason ?: "none"}", 2_000L) {
                "Skipped DM thread surface restore reason=${reason ?: "not-direct-thread"} activeOverlay=$activeOverlay " +
                    "purrfectRows=$purrfectRows root=${describeViewBrief(root)}"
            }
            return
        }
        logInfoThrottled("dm:restore-thread-run:$reason", 1_000L) {
            "Running DM thread surface restore reason=$reason activeOverlay=$activeOverlay purrfectRows=$purrfectRows root=${describeViewBrief(root)}"
        }
        val restored = restoreDmThreadSurfaceViews(root, 0, IntArray(1))
        if (restored > 0) logInfo("Restored DM thread surface views=$restored reason=$reason")
    }

    private fun restoreBlankDmThreadAggressivelySoon() {
        listOf(80L, 220L, 480L, 900L, 1_600L, 2_800L).forEach { delay ->
            mainHandler.postDelayed({ restoreBlankDmThreadAggressively() }, delay)
        }
    }

    private fun dismissDmActionModalSafelySoon() {
        logInfoThrottled("dm:skip-modal-back-dismiss", 2_500L) {
            "Skipped DM MessageActions ModalActivity back-dismiss after custom action; restoring thread UI via lifecycle callbacks"
        }
    }

    private fun dismissDmActionModalSafely() {
        val activity = currentActivity ?: return
        if (!activity.javaClass.name.contains("ModalActivity", ignoreCase = true)) return
        runCatching { activity.onBackPressed() }
            .onFailure { throwable ->
                if (shouldSuppressDmModalPauseCrash(activity, throwable)) {
                    logInfo("Suppressed synchronous Instagram DM modal back crash after custom action")
                } else {
                    logError("Failed to dismiss DM action modal after custom action", throwable)
                }
            }
    }

    private fun shouldSuppressDmModalPauseCrash(activity: Activity, throwable: Throwable): Boolean {
        val now = System.currentTimeMillis()
        if (now > suppressDmModalPauseCrashUntilMs) return false
        if (!activity.javaClass.name.contains("ModalActivity", ignoreCase = true)) return false
        val chain = generateSequence(throwable as Throwable?) { it.cause }.take(6).toList()
        return chain.any { it is IllegalStateException && it.message?.contains("No activity", ignoreCase = true) == true } ||
            chain.any {
                val message = it.message.orEmpty()
                message.contains("Unable to pause activity", ignoreCase = true) ||
                    message.contains("Unable to stop activity", ignoreCase = true) ||
                    message.contains("Unable to destroy activity", ignoreCase = true) ||
                    message.contains("FragmentManager has been destroyed", ignoreCase = true)
            }
    }

    private fun restoreBlankDmThreadAggressively() {
        val root = currentActivity?.window?.decorView ?: return
        val stats = DmThreadSurfaceStats()
        val restored = restoreBlankDmThreadAggressiveViews(root, 0, IntArray(1), stats)
        if (restored > 0) {
            root.requestLayout()
            root.invalidate()
            logInfo("Aggressively restored blank DM thread views=$restored header=${stats.hasHeader} composer=${stats.hasComposer} messages=${stats.hasMessageContent}")
        }
    }

    private fun restoreBlankDmThreadAggressiveViews(
        view: View?,
        depth: Int,
        visited: IntArray,
        stats: DmThreadSurfaceStats
    ): Int {
        if (view == null || depth > 16 || visited[0]++ > 2_600) return 0
        updateDmThreadSurfaceStats(view, stats)
        var restored = 0
        if (shouldAggressivelyRestoreDmThreadView(view, depth, stats)) {
            if (view.visibility != View.VISIBLE) {
                view.visibility = View.VISIBLE
                restored++
            }
            if (view.alpha < 0.99f) {
                view.alpha = 1f
                restored++
            }
            if (view.scaleX != 1f) view.scaleX = 1f
            if (view.scaleY != 1f) view.scaleY = 1f
            if (view.translationX != 0f) view.translationX = 0f
            if (view.translationY != 0f) view.translationY = 0f
            view.requestLayout()
            view.invalidate()
            (view.parent as? View)?.requestLayout()
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                restored += restoreBlankDmThreadAggressiveViews(view.getChildAt(i), depth + 1, visited, stats)
            }
        }
        return restored
    }

    private fun updateDmThreadSurfaceStats(view: View, stats: DmThreadSurfaceStats) {
        val idName = resourceEntryName(view)?.lowercase(Locale.US).orEmpty()
        val className = view.javaClass.name.lowercase(Locale.US)
        val visible = view.visibility == View.VISIBLE && view.alpha > 0.01f
        if (visible && (idName.contains("header_title") || idName.contains("direct_thread_title"))) stats.hasHeader = true
        if (visible && (idName.contains("composer") || idName.contains("row_thread_composer"))) stats.hasComposer = true
        if (visible && (
                idName.contains("message_content") ||
                    idName.contains("transcription") ||
                    idName.contains("voice_playback") ||
                    className.contains("recyclerview")
            )
        ) {
            stats.hasMessageContent = true
        }
        if (view is TextView && visible) {
            val text = view.text?.toString()?.lowercase(Locale.US).orEmpty()
            if (text.contains("view transcription") || text.matches(Regex("\\d+:\\d{2}"))) stats.hasMessageContent = true
        }
    }

    private fun shouldAggressivelyRestoreDmThreadView(view: View, depth: Int, stats: DmThreadSurfaceStats): Boolean {
        val idName = resourceEntryName(view)?.lowercase(Locale.US).orEmpty()
        val className = view.javaClass.name.lowercase(Locale.US)
        val lp = view.layoutParams
        val layoutWidth = lp?.width ?: 0
        val layoutHeight = lp?.height ?: 0
        val width = view.width.takeIf { it > 0 } ?: view.measuredWidth
        val height = view.height.takeIf { it > 0 } ?: view.measuredHeight
        val wideEnough = width >= 220 || layoutWidth == ViewGroup.LayoutParams.MATCH_PARENT
        val tallEnough = height >= 120 || layoutHeight == ViewGroup.LayoutParams.MATCH_PARENT || layoutHeight >= 240
        if (!wideEnough || !tallEnough) return false
        if (idName.contains("message_actions") || idName.contains("context_menu") || idName.contains("bottom_sheet")) return false
        val looksLikeScroller = className.contains("recyclerview") ||
            className.contains("viewpager") ||
            className.contains("scrollview") ||
            className.contains("listview") ||
            className.contains("litho") ||
            className.contains("compose")
        val looksLikeThreadSurface = idName.contains("thread") ||
            idName.contains("message") ||
            idName.contains("conversation") ||
            idName.contains("recycler") ||
            idName.contains("list") ||
            idName.contains("direct") ||
            idName.contains("content") ||
            idName.contains("scroll")
        val threadIsLikelyBlank = stats.hasHeader && stats.hasComposer && !stats.hasMessageContent
        return (looksLikeScroller || looksLikeThreadSurface) && (threadIsLikelyBlank || depth <= 12)
    }

    private fun restoreDmThreadSurfaceViews(view: View?, depth: Int, visited: IntArray): Int {
        if (view == null || depth > 12 || visited[0]++ > 1400) return 0
        var restored = 0
        if (shouldRestoreDmThreadSurfaceView(view)) {
            if (view.visibility != View.VISIBLE) {
                view.visibility = View.VISIBLE
                restored++
            }
            if (view.alpha < 0.99f) {
                view.alpha = 1f
                restored++
            }
            if (view.scaleX != 1f) view.scaleX = 1f
            if (view.scaleY != 1f) view.scaleY = 1f
            if (view.translationX != 0f) view.translationX = 0f
            if (view.translationY != 0f) view.translationY = 0f
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                restored += restoreDmThreadSurfaceViews(view.getChildAt(i), depth + 1, visited)
            }
        }
        return restored
    }

    private fun shouldRestoreDmThreadSurfaceView(view: View): Boolean {
        val width = view.width
        val height = view.height
        if (width <= 0 || height <= 0) return false
        val className = view.javaClass.name
        val idName = resourceEntryName(view)?.lowercase(Locale.US).orEmpty()
        if (idName.contains("direct_inbox") ||
            idName.contains("inbox_refreshable") ||
            idName.contains("row_inbox") ||
            idName.contains("target_thread_list") ||
            idName.contains("existing_thread_recycler") ||
            idName.contains("direct_search") ||
            idName == "search_row"
        ) {
            return false
        }
        val looksLikeScroller = className.contains("RecyclerView") ||
            className.contains("ViewPager") ||
            className.contains("ScrollView") ||
            className.contains("ListView")
        val looksLikeThreadSurface = idName.contains("thread") ||
            idName.contains("message") ||
            idName.contains("conversation") ||
            idName.contains("recycler") ||
            idName.contains("list")
        return (looksLikeScroller || looksLikeThreadSurface) && width >= 240 && height >= 160
    }

    private inner class DmMessageActionClickListener(
        private val action: Int,
        private val original: View.OnClickListener
    ) : View.OnClickListener {
        override fun onClick(view: View) {
            if (!state.enableDmContextMenuOptions) {
                original.onClick(view)
                return
            }
            if (!shouldClaimDmCustomAction(view, "listener-click")) {
                original.onClick(view)
                return
            }
            clearDmOverlayGestureDown()
            val context = stableDmActionContext(view.context ?: currentActivity ?: androidContext)
            val anchor = recentDmMessageActionAnchor() ?: view
            val sources = dmMessageActionSources(
                owner = original,
                anchor = anchor,
                view = view
            )
            val forcedVoiceContext = recentDmCustomActionRowVoiceContext()
            val url = resolveDmContextUrl(null, anchor, sources)
            logInfo("Claimed custom DM MessageActions listener action=$action voice=${forcedVoiceContext ?: looksLikeVoiceMessageContext(sources, anchor)} forcedVoice=$forcedVoiceContext")
            suppressNativeDmModalLaunch(2_500L)
            restoreDmMessageActionsUiSoon(anchor, sources)
            handleResolvedDmAction(context, null, anchor, action, sources, url, forcedVoiceContext)
            restoreDmMessageActionsUiSoon(anchor, sources)
            dismissDmActionModalSafelySoon()
        }
    }

    private inner class DmNativeUnsendClickListener(
        private val original: View.OnClickListener
    ) : View.OnClickListener {
        override fun onClick(view: View) {
            original.onClick(view)
            if (state.keepUnsentMessages) markRecentKeepUnsentNativeUnsend()
        }
    }

    private fun installDirectMessageUrlCaptureHooks() {
        runSafe("DM menu Uri capture") {
            XposedBridge.hookAllMethods(
                Uri::class.java,
                "parse",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableDmContextMenuOptions) return
                        if (!shouldUseGlobalDmUrlCapture()) return
                        val url = param.args.firstOrNull() as? String ?: return
                        val isProfileImage = looksLikeProfileImageUrl(url)
                        val mediaUrl = looksLikeMediaUrl(url) && !isProfileImage
                        val audioUrl = !isProfileImage && isLikelyAudioHttpUrl(url)
                        if (!mediaUrl && !audioUrl) return
                        val voiceStack = audioUrl && currentStackLooksLikeVoice()
                        if (!shouldCaptureDmMediaUrl(null, "uri-parse", voiceStack)) return
                        if (voiceStack) dmLastVoiceContextAtMs = System.currentTimeMillis()
                        if (audioUrl || voiceStack) rememberKnownDmAudioUrl(url)
                        if (mediaUrl) rememberMediaUrl(url, directFallback = true)
                    }
                }
            )
        }
        runSafe("DM menu URL capture") {
            XposedBridge.hookAllConstructors(
                URL::class.java,
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableDmContextMenuOptions) return
                        if (!shouldUseGlobalDmUrlCapture()) return
                        val url = param.args.firstOrNull() as? String ?: return
                        val isProfileImage = looksLikeProfileImageUrl(url)
                        val mediaUrl = looksLikeMediaUrl(url) && !isProfileImage
                        val audioUrl = !isProfileImage && isLikelyAudioHttpUrl(url)
                        if (!mediaUrl && !audioUrl) return
                        val voiceStack = audioUrl && currentStackLooksLikeVoice()
                        if (!shouldCaptureDmMediaUrl(null, "url-constructor", voiceStack)) return
                        if (voiceStack) dmLastVoiceContextAtMs = System.currentTimeMillis()
                        if (audioUrl || voiceStack) rememberKnownDmAudioUrl(url)
                        if (mediaUrl) rememberMediaUrl(url, directFallback = true)
                    }
                }
            )
        }
    }

    private fun installDirectMessageImageUrlCaptureHooks() {
        runSafe("DM ImageUrl capture") {
            dmImageUrlClass = loadFirstClass(
                "com.instagram.common.typedurl.ImageUrl",
                "com.instagram.common.p027typedurl.ImageUrl"
            )
            val imageUrlClass = dmImageUrlClass ?: return@runSafe
            val igImageViewClass = loadFirstClass(
                "com.instagram.common.ui.widget.imageview.IgImageView",
                "com.instagram.common.p066ui.widget.imageview.IgImageView"
            ) ?: return@runSafe

            var hooked = 0
            igImageViewClass.declaredMethods.forEach { method ->
                if (method.name != "setUrl" || !method.parameterTypes.any { imageUrlClass.isAssignableFrom(it) }) return@forEach
                val signature = "${method.declaringClass.name}.${method.name}:dm_image_url_capture"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun afterHookedMethod(param: MethodHookParam<*>) {
                            if (!state.enableDmContextMenuOptions) return
                            val view = param.thisObject as? View ?: return
                            param.args?.firstOrNull { it != null && imageUrlClass.isInstance(it) }
                                ?.let { urlFromTypedObject(it) }
                                ?.let { rememberDmImageUrl(view, it) }
                        }
                    }
                )
                hooked++
            }
            logInfo("Hooked DM IgImageView.setUrl overloads=$hooked")
        }
    }

    private fun installDirectMessageAudioPlaybackCaptureHooks() {
        runSafe("DM audio playback capture") {
            val candidates = linkedSetOf<Class<*>>()
            loadFirstClass("com.instagram.direct.videoplayer.service.AudioMessagePlaybackServiceConnection")?.let { candidates += it }
            addDmClassesUsingString(candidates, "com.instagram.direct.messagethread.voice.service.IAudioMessagePlaybackListener")
            addDmClassesUsingString(candidates, "com.instagram.direct.messagethread.voice.service.IAudioMessagePlaybackService")
            addDmClassesUsingString(candidates, "AudioMessagePlaybackServiceConnection")

            var hooked = 0
            candidates.forEach { cls ->
                cls.declaredMethods.forEach { method ->
                    if (!isLikelyDmVoicePlaybackMethod(method)) return@forEach
                    val signature = "${method.declaringClass.name}.${method.name}:dm_voice_playback_capture"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                                if (!shouldCaptureDmAudioPlaybackContext()) return
                                dmLastVoiceContextAtMs = System.currentTimeMillis()
                                val url = findUrlInDmActionSources(param.args, preferAudio = true)
                                if (url != null) {
                                    rememberKnownDmAudioUrl(url)
                                    rememberMediaUrl(url, directFallback = true)
                                }
                            }
                        }
                    )
                    hooked++
                }
            }
            logInfo("Hooked DM audio playback capture methods=$hooked")
        }
    }

    private fun shouldCaptureDmAudioPlaybackContext(): Boolean {
        if (!state.enableDmContextMenuOptions) return false
        if (hasActiveDmActionRuntime()) return true
        return Looper.myLooper() == Looper.getMainLooper() && isDirectMessageSurfaceActive()
    }

    private fun isLikelyDmVoicePlaybackMethod(method: Method): Boolean {
        if (method.returnType != Void.TYPE) return false
        val name = method.name
        val hay = "${method.declaringClass.name} $name".lowercase(Locale.US)
        if (name == "FnS") return true
        if (hay.contains("audio") || hay.contains("voice")) return method.parameterTypes.isNotEmpty()
        if (method.parameterTypes.size < 8) return false
        return method.parameterTypes.any {
            val p = it.name.lowercase(Locale.US)
            p.contains("media") || p.contains("direct") || p.contains("message")
        }
    }

    private fun installDmNativeModalLaunchSuppression() {
        if (dmNativeModalSuppressorHooked) return
        dmNativeModalSuppressorHooked = true
        val hook = object : XC_MethodHook() {
            override fun beforeHookedMethod(param: MethodHookParam<*>) {
                if (maybeSuppressNativeDmMessageActionModalLaunch(param.args)) param.result = null
            }
        }
        runSafe("DM native modal launch suppression") {
            fun hookLaunchMethods(cls: Class<*>, methodName: String) {
                runCatching { XposedBridge.hookAllMethods(cls, methodName, hook) }
                    .onFailure { logInfo("DM native modal launch suppression skipped ${cls.name}.$methodName: ${it.javaClass.simpleName}: ${it.message}") }
            }
            hookLaunchMethods(Activity::class.java, "startActivity")
            hookLaunchMethods(Activity::class.java, "startActivityForResult")
            hookLaunchMethods(Activity::class.java, "startActivities")
            hookLaunchMethods(ContextWrapper::class.java, "startActivity")
            hookLaunchMethods(ContextWrapper::class.java, "startActivities")
            hookLaunchMethods(Instrumentation::class.java, "execStartActivity")
            runCatching { Class.forName("android.app.ContextImpl") }.getOrNull()?.let { contextImpl ->
                hookLaunchMethods(contextImpl, "startActivity")
                hookLaunchMethods(contextImpl, "startActivities")
            }
        }
    }

    private fun scheduleDmSavedStateLongPressGuardInstall(reason: String) {
        if (!state.enableDmContextMenuOptions) return
        if (dmSavedStateLongPressGuardInstalled) return
        if (!dmSavedStateLongPressGuardInstallStarted.compareAndSet(false, true)) return
        logInfo("Scheduling DM saved-state long-press guard install reason=$reason")
        Thread({
            runCatching { Process.setThreadPriority(Process.THREAD_PRIORITY_BACKGROUND) }
            val started = SystemClock.uptimeMillis()
            runCatching { installDmSavedStateLongPressGuard() }
                .onSuccess {
                    dmSavedStateLongPressGuardInstalled = true
                    logInfo("DM saved-state long-press guard install finished off main thread elapsed=${SystemClock.uptimeMillis() - started}ms reason=$reason")
                }
                .onFailure {
                    dmSavedStateLongPressGuardInstallStarted.set(false)
                    logError("DM saved-state long-press guard background install failed reason=$reason elapsed=${SystemClock.uptimeMillis() - started}ms", it)
                }
        }, "PurrfectIgDmSavedStateGuard").apply {
            isDaemon = true
            priority = Thread.MIN_PRIORITY
        }.start()
    }

    private fun installDmSavedStateLongPressGuard() {
        runSafe("DM saved-state long-press guard") {
            val candidateMethods = LinkedHashMap<String, Method>()
            val methodSources = LinkedHashMap<String, String>()
            fun methodKey(method: Method): String {
                return "${method.declaringClass.name}.${method.name}(" +
                    method.parameterTypes.joinToString(",") { it.name } +
                    "):${method.returnType.name}"
            }
            fun addCandidateMethod(method: Method, source: String) {
                if (Modifier.isStatic(method.modifiers) || Modifier.isAbstract(method.modifiers) || Modifier.isNative(method.modifiers)) return
                val key = methodKey(method)
                if (!candidateMethods.containsKey(key)) {
                    candidateMethods[key] = method
                    methodSources[key] = source
                }
            }

            dexBridge.findMethodsUsingStrings("Can not perform this action after onSaveInstanceState")
                .forEach { method -> addCandidateMethod(method, "method-string") }

            if (candidateMethods.isEmpty()) {
                dexBridge.findClassNamesUsingStrings("Can not perform this action after onSaveInstanceState")
                    .distinct()
                    .take(16)
                    .mapNotNull { name -> runCatching { Class.forName(name, false, appClassLoader) }.getOrNull() }
                    .forEach { fragmentManagerClass ->
                        fragmentManagerClass.declaredMethods
                            .filter { method ->
                                method.parameterTypes.isEmpty() &&
                                    !Modifier.isStatic(method.modifiers) &&
                                    !Modifier.isAbstract(method.modifiers) &&
                                    !Modifier.isNative(method.modifiers)
                            }
                            .forEach { method -> addCandidateMethod(method, "class-string") }
                    }
            }

            if (candidateMethods.isEmpty()) {
                loadFirstClass("X.00gm", "p000X.C00gm")?.declaredMethods
                    ?.filter { method -> method.name == "A0v" }
                    ?.forEach { method -> addCandidateMethod(method, "legacy-name-fallback") }
            }

            var hooked = 0
            val hookedTargets = mutableListOf<String>()
            candidateMethods.forEach { (key, method) ->
                val signature = "$key:dm_saved_state_long_press_guard"
                if (!hookedDexMethods.add(signature)) return@forEach
                method.isAccessible = true
                XposedBridge.hookMethod(
                    method,
                    object : XC_MethodHook() {
                        override fun beforeHookedMethod(param: MethodHookParam<*>) {
                            if (state.enableDmContextMenuOptions) {
                                val now = System.currentTimeMillis()
                                val armed = now <= dmSavedStateLongPressGuardUntilMs
                                val fromLongPress = currentStackLooksLikeLongPress()
                                if (armed || fromLongPress) {
                                    val stack = dmStackSnippetForLog(8)
                                    logInfoThrottled("dm:saved-state-check-hit", 250L) {
                                        "Instagram FragmentManager saved-state check hit armed=$armed longPress=$fromLongPress " +
                                            "surface=${dmSurfaceForLog()} method=${method.declaringClass.name}.${method.name} " +
                                            "source=${methodSources[key] ?: "-"} stack=$stack"
                                    }
                                }
                            }
                            if (!shouldSuppressDmSavedStateLongPressCheck()) return
                            if (allowDmSavedStateLongPressMethodToContinue(param.args, method)) return
                            param.result = defaultDmSavedStateGuardResult(method.returnType)
                        }
                    }
                )
                hookedTargets += "${method.declaringClass.name}.${method.name}/${method.parameterTypes.size}:${method.returnType.simpleName}:${methodSources[key] ?: "-"}"
                hooked++
            }
            if (hooked == 0) {
                logInfo("DM saved-state long-press guard skipped: no hookable saved-state check methods discovered")
                return@runSafe
            }
            logInfo(
                "Hooked DM saved-state long-press guard methods=$hooked " +
                    "targets=${hookedTargets.take(16).joinToString("|")}"
            )
        }
    }

    private fun allowDmSavedStateLongPressMethodToContinue(args: Array<Any?>?, method: Method): Boolean {
        args ?: return false
        var changed = 0
        var hasBooleanArg = false
        method.parameterTypes.forEachIndexed { index, type ->
            if ((type != java.lang.Boolean.TYPE && type != java.lang.Boolean::class.java) || index >= args.size) return@forEachIndexed
            hasBooleanArg = true
            if (args[index] == false) {
                args[index] = true
                changed++
            }
        }
        if (!hasBooleanArg) return false
        logInfoThrottled("dm:saved-state-allow-state-loss:${method.declaringClass.name}.${method.name}", 750L) {
            "Adjusted Instagram DM saved-state long-press guard to allow state-loss continuation " +
                "method=${method.declaringClass.name}.${method.name} booleansChanged=$changed stack=${dmStackSnippetForLog(7)}"
        }
        return true
    }

    private fun armDmSavedStateLongPressGuard(origin: String) {
        if (!state.enableDmContextMenuOptions) return
        scheduleDmSavedStateLongPressGuardInstall("arm:$origin")
        val now = System.currentTimeMillis()
        dmSavedStateLongPressGuardUntilMs = now + 4_000L
        if (now - dmLastSavedStateGuardLogAtMs > 2_000L) {
            dmLastSavedStateGuardLogAtMs = now
            val root = currentActivity?.window?.decorView
            logInfo(
                "Armed DM saved-state long-press guard origin=$origin " +
                    "surface=${root?.let { directMessageSurfaceReason(it) } ?: "-"}"
            )
        }
    }

    private fun shouldSuppressDmSavedStateLongPressCheck(): Boolean {
        if (!state.enableDmContextMenuOptions) return false
        val now = System.currentTimeMillis()
        val touchAge = now - dmLastMessageActionTouchAtMs
        val armed = now <= dmSavedStateLongPressGuardUntilMs
        val root = currentActivity?.window?.decorView
        val reason = root?.let { directMessageSurfaceReason(it) }
        val hasRecentAnchor = recentDmMessageActionAnchor() != null
        val inDirectThread = reason == "direct-thread-root-id" ||
            reason == "message-list-with-thread-chrome" ||
            reason == "message-actions-id" ||
            hasRecentAnchor ||
            touchAge in 0..4_000L
        val fromLongPress = currentStackLooksLikeLongPress()
        if (!inDirectThread) {
            if (armed || fromLongPress) logDmSavedStateGuardDecision("allow-not-direct", reason, touchAge, now, armed, fromLongPress)
            return false
        }
        if (!fromLongPress) {
            if (armed) logDmSavedStateGuardDecision("allow-not-longpress", reason, touchAge, now, armed, false)
            return false
        }
        if (now - dmLastSavedStateGuardLogAtMs > 750L) {
            dmLastSavedStateGuardLogAtMs = now
            logInfo(
                "Suppressed Instagram DM saved-state fragment check during long-press " +
                    "surface=${reason ?: "-"} touchAge=$touchAge armed=$armed recentAnchor=$hasRecentAnchor"
            )
        }
        return true
    }

    private fun currentStackLooksLikeLongPress(): Boolean {
        return Thread.currentThread().stackTrace.any { frame ->
            frame.methodName == "onLongPress" ||
                frame.methodName == "dispatchLongPress" ||
                frame.className.contains("GestureDetector")
        }
    }

    private fun defaultDmSavedStateGuardResult(returnType: Class<*>): Any? {
        if (!returnType.isPrimitive || returnType == Void.TYPE) return null
        return when (returnType) {
            java.lang.Boolean.TYPE -> false
            java.lang.Byte.TYPE -> 0.toByte()
            java.lang.Short.TYPE -> 0.toShort()
            java.lang.Integer.TYPE -> 0
            java.lang.Long.TYPE -> 0L
            java.lang.Float.TYPE -> 0f
            java.lang.Double.TYPE -> 0.0
            java.lang.Character.TYPE -> 0.toChar()
            else -> null
        }
    }

    private fun logDmSavedStateGuardDecision(
        decision: String,
        surface: String?,
        touchAge: Long,
        now: Long,
        armed: Boolean,
        fromLongPress: Boolean
    ) {
        if (now - dmLastSavedStateGuardDecisionLogAtMs < 600L) return
        dmLastSavedStateGuardDecisionLogAtMs = now
        logInfo(
            "DM saved-state long-press guard decision=$decision surface=${surface ?: "-"} touchAge=$touchAge " +
                "armed=$armed longPress=$fromLongPress remaining=${(dmSavedStateLongPressGuardUntilMs - now).coerceAtLeast(0L)}ms " +
                "stack=${dmStackSnippetForLog(5)}"
        )
    }

    private fun dmSurfaceForLog(): String {
        val root = currentActivity?.window?.decorView ?: return "-"
        return directMessageSurfaceReason(root) ?: "-"
    }

    private fun dmStackSnippetForLog(limit: Int): String {
        return Thread.currentThread().stackTrace
            .asSequence()
            .drop(3)
            .filterNot { it.className.startsWith("java.lang.Thread") }
            .take(limit.coerceAtLeast(1))
            .joinToString(" > ") { "${it.className.substringAfterLast('.')}.${it.methodName}" }
    }

    private fun installDmDeferredActionResume() {
        if (dmDeferredActionResumeHooked) return
        dmDeferredActionResumeHooked = true
        runSafe("DM deferred action resume") {
            XposedBridge.hookAllMethods(
                Activity::class.java,
                "onResume",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        val activity = param.thisObject as? Activity ?: return
                        if (isInstagramModalActivity(activity) && !isActivityHistoryModal(activity)) return
                        dmLatestStableActionActivity = WeakReference(activity)
                        drainDeferredDmAction(activity)
                    }
                }
            )
        }
    }

    private fun suppressNativeDmModalLaunch(durationMs: Long) {
        val until = System.currentTimeMillis() + durationMs.coerceAtLeast(0L)
        if (until > dmSuppressModalLaunchUntilMs) {
            dmSuppressModalLaunchUntilMs = until
            logInfo("DM native modal launch suppressed for ${durationMs.coerceAtLeast(0L)}ms")
        }
    }

    private fun maybeSuppressNativeDmMessageActionModalLaunch(args: Array<Any?>?): Boolean {
        if (!state.enableDmContextMenuOptions || System.currentTimeMillis() > dmSuppressModalLaunchUntilMs) return false
        if (!shouldClaimDmCustomAction(null, "modal-suppress")) return false
        val intent = args?.firstOrNull { it is Intent } as? Intent ?: return false
        if (!intentTargetsInstagramModal(intent) || intentMentionsActivityHistory(intent)) return false
        logInfo("Suppressed native DM MessageActions ModalActivity launch")
        return true
    }

    private fun maybeInjectDmMenuItems(param: XC_MethodHook.MethodHookParam<*>) {
        if (!state.enableDmContextMenuOptions) return
        val original = param.args.firstOrNull() as? List<*> ?: return
        if (original.isEmpty()) return
        val ctx = dmContextFromPopup(param.thisObject)
        val voiceMenu = looksLikeDirectVoiceMessageMenu(original)
        val visualMenu = looksLikeDirectVisualMessageMenu(original)
        if (!voiceMenu && !visualMenu) {
            if (maybeShowOldPostReelCustomFromPopupRows(param, ctx, original)) {
                param.result = null
                return
            }
            logInfoThrottled("dm:legacy-skip-non-media", 2_500L) {
                "Skipped legacy DM context menu: no media/voice signals labels=${dmMenuLabelsForLog(original)}"
            }
            return
        }
        if (hasInjectedDmItems(ctx, original)) {
            logInfoThrottled("dm:legacy-skip-existing", 2_500L) {
                "Skipped legacy DM context menu: custom items already present labels=${dmMenuLabelsForLog(original)}"
            }
            return
        }
        inferDmMenuItemShape(original.firstOrNull())
        val legacy = dmLegacyItemConstructor?.declaringClass?.isInstance(original.firstOrNull()) == true
        val itemConstructor = if (legacy) dmLegacyItemConstructor else dmPrismItemConstructor
        if (itemConstructor == null || dmMenuClickInterfaceClass == null) {
            logInfo(
                "Skipped legacy DM context menu: shape unavailable legacy=$legacy itemCtor=${itemConstructor != null} " +
                    "clickInterface=${dmMenuClickInterfaceClass != null} labels=${dmMenuLabelsForLog(original)}"
            )
            return
        }

        val allowedActions = if (voiceMenu) {
            listOf(DM_ACTION_DOWNLOAD)
        } else {
            allDmMessageActions()
        }
        logInfo("Preparing legacy DM context menu voice=$voiceMenu visual=$visualMenu actions=${dmActionLabelsForLog(allowedActions)} labels=${dmMenuLabelsForLog(original)}")
        val extended = mutableListOf<Any>()
        for (action in allowedActions) {
            createDmMenuItem(ctx, param.thisObject, action, legacy)?.let { extended += it }
        }
        if (extended.isEmpty()) return
        extended.addAll(original.filterNotNull())
        param.args[0] = extended
    }

    private fun maybeSuppressOldPostReelPopupShow(param: XC_MethodHook.MethodHookParam<*>): Boolean {
        val popup = param.thisObject ?: return false
        val armedAtMs = oldPostReelPopupShowSuppressions.remove(popup) ?: return false
        val ageMs = SystemClock.elapsedRealtime() - armedAtMs
        if (ageMs !in 0L..8_000L) {
            logInfoThrottled("old-post-reel:popup-show-stale:${System.identityHashCode(popup)}", 600L) {
                "Ignored stale native post/reel popup suppression ageMs=$ageMs popup=${popup.javaClass.name} method=${param.method.name}"
            }
            return false
        }
        param.result = null
        dismissPopup(popup)
        logInfoThrottled("old-post-reel:popup-show-suppressed:${System.identityHashCode(popup)}", 600L) {
            "Suppressed native post/reel row popup after custom sheet ageMs=$ageMs popup=${popup.javaClass.name} method=${param.method.name}"
        }
        return true
    }

    private fun maybeShowOldPostReelCustomFromPopupRows(
        param: XC_MethodHook.MethodHookParam<*>,
        context: Context?,
        originalRows: List<*>
    ): Boolean {
        if (!state.restoreOldPostReelContextMenu) return false
        val popup = param.thisObject ?: return false
        val ctx = context ?: currentActivity ?: androidContext
        val startedAtMs = SystemClock.elapsedRealtime()
        val used = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())

        fun label(row: Any?): String = extractDmMenuLabel(row).orEmpty()
        fun normalized(row: Any?): String = oldPostReelNormalizeSheetLabel(label(row))
        fun takeRow(vararg labels: String, predicate: (String) -> Boolean = { false }): Any? {
            val wanted = labels.toSet()
            val row = originalRows.firstOrNull { candidate ->
                candidate != null &&
                    candidate !in used &&
                    (
                        normalized(candidate) in wanted ||
                            predicate(normalized(candidate))
                        )
            } ?: return null
            used += row
            return row
        }

        fun action(
            row: Any,
            optionName: String,
            displayLabel: String,
            destructive: Boolean = false,
            dividerBefore: Boolean = false
        ): OldPostReelMenuAction? {
            val listener = oldPostReelPopupRowClickListener(row, popup, displayLabel, optionName) ?: return null
            return OldPostReelMenuAction(
                optionName = optionName,
                label = displayLabel,
                icon = 0,
                listener = listener,
                destructive = destructive,
                enabled = true,
                dividerBefore = dividerBefore
            )
        }

        val shareRow = takeRow("share", "share to", "send to")
        val linkRow = takeRow("link", "copy link", "copy fundraiser link")
        val saveRow = takeRow("save", "saved", "unsave")
        val headers = listOfNotNull(
            shareRow?.let { action(it, "SHARE_LINK", "Share") },
            linkRow?.let { action(it, "COPY_LINK", "Link") },
            saveRow?.let { action(it, "SAVE", "Save") }
        )
        if (headers.size < 3) return false

        val rows = mutableListOf<OldPostReelMenuAction>()
        val nativeDownloadRow = takeRow("download")
        if (nativeDownloadRow != null) {
            action(nativeDownloadRow, "DOWNLOAD", "Download")?.let(rows::add)
        } else if (!isReelsAutoplaySurfaceActive()) {
            createOldPostReelPostDownloadAction(
                context = ctx,
                media = findMediaObject(popup),
                fallbackRoot = popup,
                source = "legacy_popup:${popup.javaClass.name}.${param.method.name}"
            )?.let(rows::add)
        }
        takeRow("why you're seeing this", "why you're seeing this post", "why you are seeing this post") { it.startsWith("why ") }
            ?.let { action(it, "WHY_AM_I_SEEING_THIS", "Why you're seeing this post")?.let(rows::add) }
        takeRow("not interested", "see fewer", "see fewer like this")
            ?.let { action(it, "SEE_FEWER", "Not interested")?.let(rows::add) }
        takeRow("interested", "see more", "see more like this")
            ?.let { action(it, "SEE_MORE", "Interested")?.let(rows::add) }
        takeRow("about this account")
            ?.let { action(it, "ABOUT_THIS_ACCOUNT", "About this account")?.let(rows::add) }
        takeRow("report")
            ?.let { action(it, "REPORT", "Report", destructive = true)?.let(rows::add) }
        takeRow("manage content preferences", "manage suggested content", "see your algorithm")
            ?.let {
                action(
                    it,
                    "MANAGE_SUGGESTED_CONTENT",
                    "Manage content preferences",
                    dividerBefore = rows.isNotEmpty()
                )?.let(rows::add)
            }
        if (rows.none { it.optionName in setOf("WHY_AM_I_SEEING_THIS", "SEE_FEWER", "SEE_MORE", "ABOUT_THIS_ACCOUNT", "REPORT") }) {
            return false
        }

        oldPostReelPopupShowSuppressions[popup] = SystemClock.elapsedRealtime()
        val shown = showOldPostReelCustomContextMenu(
            ctx,
            headers,
            rows,
            "legacy_popup:${popup.javaClass.name}.${param.method.name}",
            onDismissed = { oldPostReelPopupShowSuppressions.remove(popup) }
        )
        if (!shown) {
            oldPostReelPopupShowSuppressions.remove(popup)
            return false
        }
        logInfo(
            "Old post/reel popup custom context menu shown elapsed=${SystemClock.elapsedRealtime() - startedAtMs}ms " +
                "popup=${popup.javaClass.name} method=${param.method.name} " +
                "headers=${headers.joinToString("|") { it.optionName }} rows=${rows.joinToString("|") { it.optionName }} " +
                "labels=${dmMenuLabelsForLog(originalRows)}"
        )
        return true
    }

    private fun oldPostReelPopupRowClickListener(
        row: Any,
        popup: Any?,
        label: String,
        optionName: String
    ): View.OnClickListener? {
        val callback = oldPostReelPopupRowCallback(row) ?: return null
        val canClick = callback.javaClass.methods.firstOrNull {
            it.name == "BqR" && it.parameterTypes.isEmpty() && it.returnType == java.lang.Boolean.TYPE
        }?.apply { isAccessible = true }
        val click = callback.javaClass.methods.firstOrNull {
            it.name == "EoR" && it.parameterTypes.isEmpty() && it.returnType == java.lang.Void.TYPE
        }?.apply { isAccessible = true } ?: return null
        return View.OnClickListener {
            runCatching { dismissPopup(popup) }
            runCatching {
                val allowed = canClick?.invoke(callback) as? Boolean ?: true
                if (allowed) {
                    click.invoke(callback)
                } else {
                    logInfo("Old post/reel popup row click ignored disabled label=$label option=$optionName row=${row.javaClass.name}")
                }
            }.onFailure {
                logError("Old post/reel popup row click failed label=$label option=$optionName row=${row.javaClass.name}", it)
            }
        }
    }

    private fun oldPostReelPopupRowCallback(row: Any?): Any? {
        if (row == null) return null
        return oldPostReelDeclaredFieldsInHierarchy(row.javaClass)
            .filterNot { Modifier.isStatic(it.modifiers) }
            .firstNotNullOfOrNull { field ->
                runCatching {
                    field.isAccessible = true
                    val value = field.get(row) ?: return@firstNotNullOfOrNull null
                    if (oldPostReelLooksLikePopupCallback(value.javaClass)) value else null
                }.getOrNull()
            }
    }

    private fun oldPostReelLooksLikePopupCallback(type: Class<*>): Boolean {
        return type.methods.any {
            it.name == "EoR" && it.parameterTypes.isEmpty() && it.returnType == java.lang.Void.TYPE
        } && type.methods.any {
            it.name == "BqR" && it.parameterTypes.isEmpty() && it.returnType == java.lang.Boolean.TYPE
        }
    }

    private fun inferDmMenuItemShape(sample: Any?) {
        if (sample == null) return
        val cls = sample.javaClass
        if (dmMenuClickInterfaceClass == null) dmMenuClickInterfaceClass = findDmClickInterface(cls)
        if (dmLegacyItemConstructor == null && hasDeclaredStringField(cls, "A03")) {
            dmLegacyItemConstructor = findConstructor(cls, 10)
        }
        if (dmPrismItemConstructor == null && hasDeclaredStringField(cls, "A0G")) {
            dmPrismItemConstructor = findConstructor(cls, 24)
        }
    }

    private fun findDmClickInterface(itemClass: Class<*>): Class<*>? {
        itemClass.declaredFields.forEach { field ->
            if (isDmClickInterface(field.type)) return field.type
        }
        itemClass.declaredConstructors.forEach { constructor ->
            constructor.parameterTypes.forEach { type ->
                if (isDmClickInterface(type)) return type
            }
        }
        return null
    }

    private fun isDmClickInterface(type: Class<*>?): Boolean {
        if (type == null || !type.isInterface) return false
        val hasCanClick = type.declaredMethods.any {
            it.name == "Bbt" && it.parameterTypes.isEmpty() && it.returnType == java.lang.Boolean.TYPE
        }
        val hasClick = type.declaredMethods.any {
            it.name == "EUS" && it.parameterTypes.isEmpty() && it.returnType == java.lang.Void.TYPE
        }
        return hasCanClick && hasClick
    }

    private fun captureDmMenuAnchor(param: XC_MethodHook.MethodHookParam<*>) {
        param.args.filterIsInstance<View>().firstOrNull()?.let { view ->
            dmMenuAnchors[param.thisObject] = view
        }
    }

    private fun createDmMenuItem(context: Context?, popup: Any?, action: Int, legacy: Boolean): Any? {
        return runCatching {
            val constructor = (if (legacy) dmLegacyItemConstructor else dmPrismItemConstructor) ?: return@runCatching null
            if (legacy) {
                val args = arrayOfNulls<Any>(10)
                args[1] = loadDmMenuIcon(context, action)
                args[2] = createDmMenuClickProxy(popup, action)
                args[4] = dmActionLabel(action)
                args[6] = false
                args[7] = true
                args[8] = false
                args[9] = false
                constructor.newInstance(*args)
            } else {
                val args = arrayOfNulls<Any>(24)
                args[0] = loadDmMenuIcon(context, action)
                args[4] = createDmMenuClickProxy(popup, action)
                args[9] = -1
                args[13] = 0
                args[15] = 0
                args[16] = dmActionLabel(action)
                args[18] = false
                args[19] = true
                args[20] = false
                args[21] = false
                args[22] = true
                args[23] = false
                constructor.newInstance(*args)
            }
        }.getOrNull()
    }

    private fun createDmMenuClickProxy(popup: Any?, action: Int): Any? {
        val clickInterface = dmMenuClickInterfaceClass ?: return null
        return Proxy.newProxyInstance(clickInterface.classLoader, arrayOf(clickInterface)) { proxy, method, args ->
            when (method.name) {
                "Bbt" -> true
                "EUS" -> {
                    dismissPopup(popup)
                    handleDmContextAction(popup, action)
                    null
                }
                "toString" -> "PurrfectInstaDmMenuAction"
                "hashCode" -> System.identityHashCode(proxy)
                "equals" -> args != null && args.isNotEmpty() && proxy === args[0]
                else -> defaultResult(method.returnType)
            }
        }
    }

    private fun dismissPopup(popup: Any?) {
        runCatching {
            when (popup) {
                is PopupWindow -> popup.dismiss()
                else -> popup?.javaClass?.methods?.firstOrNull { it.name == "dismiss" && it.parameterTypes.isEmpty() }?.invoke(popup)
            }
        }
    }

    private fun handleDmContextAction(popup: Any?, action: Int) {
        val context = dmContextFromPopup(popup) ?: currentActivity ?: androidContext
        val anchor = dmMenuAnchors[popup]
        val url = resolveDmContextUrl(popup, anchor, null)
        handleResolvedDmAction(context, popup, anchor, action, null, url)
    }

    private fun rememberDmMessageActionAnchorCandidate(view: View, origin: String = "long-press") {
        if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return
        if (!isDmMessageActionAnchorCandidate(view)) return
        dmLatestMessageActionAnchor = WeakReference(view)
        dmLatestMessageActionAnchorAtMs = System.currentTimeMillis()
        dmLatestMessageActionLongPressAtMs = dmLatestMessageActionAnchorAtMs
        val voice = viewHasLocalVoiceHint(view)
        val visual = dmLocalVisualAnchorHint(view)
        dmLatestMessageActionWasVoice = voice
        dmLatestMessageActionWasVisual = visual.visual
        val mediaSnapshot = snapshotDmMessageActionMedia(view, voice, visual)
        dmLatestMessageActionMediaSnapshot = mediaSnapshot
        if (voice) {
            dmLatestMessageActionVoiceAtMs = dmLatestMessageActionAnchorAtMs
            dmLastVoiceContextAtMs = dmLatestMessageActionAnchorAtMs
        } else {
            dmLatestMessageActionVoiceAtMs = 0L
            dmLastVoiceContextAtMs = 0L
        }
        logInfoThrottled("dm:remember-anchor:${describeViewBrief(view)}", 600L) {
            "Remembered DM MessageActions anchor origin=$origin voice=$voice visual=${visual.visual} visualReason=${visual.reason} visualElapsed=${visual.elapsedMs}ms " +
                "media=${mediaSnapshot.urls.size} mediaTypes=${dmUrlTypesForLog(mediaSnapshot.urls)} mediaReason=${mediaSnapshot.reason} mediaElapsed=${mediaSnapshot.elapsedMs}ms " +
                "view=${describeViewBrief(view)} " +
                "touchAge=${System.currentTimeMillis() - dmLastMessageActionTouchAtMs} " +
                "text=${visibleTextInView(view, 0, StringBuilder()).toString().lineSequence().firstOrNull()?.take(80) ?: "-"}"
        }
        rememberKeepUnsentActionRowSnapshot(view)
    }

    private fun rememberDmPotentialLongPressTouchPoint(event: MotionEvent) {
        if (event.actionMasked != MotionEvent.ACTION_DOWN) return
        if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return
        dmLastPotentialLongPressTouchX = event.rawX
        dmLastPotentialLongPressTouchY = event.rawY
        dmLastPotentialLongPressTouchAtMs = System.currentTimeMillis()
    }

    private fun rememberDmMessageActionRootTouchPoint(root: View?, event: MotionEvent) {
        if (event.actionMasked != MotionEvent.ACTION_DOWN) return
        if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return
        if (root == null || !hasCachedDirectTouchSurface()) return
        dmLastMessageActionTouchX = event.rawX
        dmLastMessageActionTouchY = event.rawY
        dmLastMessageActionTouchAtMs = System.currentTimeMillis()
    }

    private fun ensureFreshDmLongPressAnchor(origin: String) {
        if (recentDmMessageActionAnchor(DM_LONG_PRESS_DETECTION_MAX_AGE_MS) != null) return
        val root = currentActivity?.window?.decorView ?: return
        rememberDmMessageActionLongPress(root, origin)
    }

    private fun rememberDmMessageActionLongPress(view: View, origin: String) {
        if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return
        val root = view.rootView ?: view
        if (dmMessageActionsOverlayVisible(root) || isInsideDmMessageActionsOverlay(view)) return
        val directSurface = dmDirectSurfaceActive ||
            isLikelyDirectTouchPath(view) ||
            isDirectThreadSurfaceReason(directMessageSurfaceReason(root))
        if (!directSurface) return
        val now = System.currentTimeMillis()
        val touchAge = now - dmLastMessageActionTouchAtMs
        var rawX = dmLastMessageActionTouchX
        var rawY = dmLastMessageActionTouchY
        val hasFreshTouch = touchAge in 0..DM_LONG_PRESS_DETECTION_MAX_AGE_MS
        if (!hasFreshTouch) {
            val potentialTouchAge = now - dmLastPotentialLongPressTouchAtMs
            if (potentialTouchAge in 0..DM_LONG_PRESS_DETECTION_MAX_AGE_MS) {
                rawX = dmLastPotentialLongPressTouchX
                rawY = dmLastPotentialLongPressTouchY
                dmLastMessageActionTouchX = rawX
                dmLastMessageActionTouchY = rawY
                dmLastMessageActionTouchAtMs = now
            } else {
                val rect = Rect()
                if (view !== root && view.getGlobalVisibleRect(rect) && rect.width() > 0 && rect.height() > 0) {
                    rawX = rect.centerX().toFloat()
                    rawY = rect.centerY().toFloat()
                    dmLastMessageActionTouchX = rawX
                    dmLastMessageActionTouchY = rawY
                    dmLastMessageActionTouchAtMs = now
                } else {
                    logInfoThrottled("dm:long-press-anchor-stale:$origin", 1_000L) {
                        "Skipped DM long-press anchor capture origin=$origin reason=stale-touch age=$touchAge view=${describeViewBrief(view)}"
                    }
                    return
                }
            }
        }
        clearDmMessageActionSelection("long-press:$origin")
        armDmSavedStateLongPressGuard("long-press:$origin")
        val anchor = findDmMessageActionAnchorAtScreenPoint(root, rawX, rawY, 0, intArrayOf(0))
            ?: view.takeIf { isDmMessageActionAnchorCandidate(it) }
        if (anchor == null) {
            clearDmMessageActionSelection("long-press-miss:$origin")
            logInfoThrottled("dm:long-press-anchor-miss:$origin", 900L) {
                "DM long-press anchor capture missed origin=$origin x=${rawX.toInt()} y=${rawY.toInt()} root=${describeViewBrief(root)} view=${describeViewBrief(view)}"
            }
            return
        }
        logInfo(
            "DM long-press anchor confirmed origin=$origin x=${rawX.toInt()} y=${rawY.toInt()} " +
                "view=${describeViewBrief(anchor)} bounds=${viewBoundsForLog(anchor)}"
        )
        rememberDmMessageActionAnchorCandidate(anchor, origin)
    }

    private fun findDmMessageActionAnchorAtScreenPoint(
        view: View?,
        rawX: Float,
        rawY: Float,
        depth: Int,
        visited: IntArray
    ): View? {
        if (view == null || depth > 14 || visited[0]++ > 220 || view.visibility != View.VISIBLE) return null
        val rect = Rect()
        if (!view.getGlobalVisibleRect(rect) || !rect.contains(rawX.toInt(), rawY.toInt())) return null
        if (view is ViewGroup) {
            for (i in view.childCount - 1 downTo 0) {
                findDmMessageActionAnchorAtScreenPoint(view.getChildAt(i), rawX, rawY, depth + 1, visited)?.let { return it }
            }
        }
        return view.takeIf { isDmMessageActionAnchorCandidate(it) }
    }

    private fun clearDmMessageActionSelection(reason: String) {
        dmLatestMessageActionAnchor = null
        dmLatestMessageActionAnchorAtMs = 0L
        dmLatestMessageActionLongPressAtMs = 0L
        dmLatestMessageActionWasVoice = false
        dmLatestMessageActionWasVisual = false
        dmLatestMessageActionMenuWasVoice = false
        dmLatestMessageActionMenuWasVisual = false
        dmLatestMessageActionMenuTypeSignal = ""
        dmLatestMessageActionMenuAtMs = 0L
        dmLatestMessageActionMediaSnapshot = null
        dmLatestMessageActionsViewModel = null
        dmLatestMessageActionsViewModelAtMs = 0L
        dmLatestMessageActionVoiceAtMs = 0L
        dmLastVoiceContextAtMs = 0L
        logInfoThrottled("dm:clear-selection:$reason", 1_200L) {
            "Cleared DM MessageActions selection reason=$reason"
        }
    }

    private fun rememberKeepUnsentActionRowSnapshot(anchor: View) {
        if (!state.keepUnsentMessages) return
        val rowRoot = nearestKeepUnsentRowRoot(anchor) ?: return
        if (findViewByResourceName(rowRoot, "direct_text_message_text_view") == null) return
        rememberKeepUnsentActionRowRoot(rowRoot)
    }

    private fun snapshotDmMessageActionMedia(anchor: View, voice: Boolean, visual: DmVisualAnchorHint): DmMessageActionMediaSnapshot {
        val started = SystemClock.uptimeMillis()
        dmMessageActionMediaSnapshotCache[anchor]?.let { cached ->
            if (System.currentTimeMillis() - cached.atMs in 0..1_500L) return cached
        }
        if (voice && !visual.visual) {
            return rememberDmMessageActionMediaSnapshot(anchor, DmMessageActionMediaSnapshot(emptyList(), true, false, "voice-no-visual", System.currentTimeMillis(), 0L))
        }
        if (!visual.visual && extractCachedMediaUrlFromView(anchor) == null) {
            return rememberDmMessageActionMediaSnapshot(anchor, DmMessageActionMediaSnapshot(emptyList(), false, false, "no-media", System.currentTimeMillis(), SystemClock.uptimeMillis() - started))
        }
        val row = tappedDmMessageActionMediaRow(anchor)
        val targetRow = row ?: anchor
        val localUrls = collectDmMediaUrlsInRow(targetRow)
        val urls = localUrls
            .filterNot(::looksLikeProfileImageUrl)
            .distinct()
            .take(12)
        val now = System.currentTimeMillis()
        val elapsed = SystemClock.uptimeMillis() - started
        val reason = when {
            row == null -> "anchor-only"
            urls.isNotEmpty() -> "row-local"
            visual.visual -> "visual-no-url"
            else -> "no-media"
        }
        val snapshot = DmMessageActionMediaSnapshot(
            urls = urls,
            voice = voice && !visual.visual,
            visual = visual.visual || urls.any { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) },
            reason = reason,
            atMs = now,
            elapsedMs = elapsed
        )
        if (urls.isNotEmpty()) {
            urls.forEach { url ->
                if (isAudioUrl(url) || isLikelyAudioHttpUrl(url)) rememberKnownDmAudioUrl(url)
                else rememberMediaUrl(url, directFallback = true)
            }
            logInfoThrottled("dm:row-media-snapshot:${describeViewBrief(row ?: anchor)}:${urls.size}", 900L) {
                "DM row media snapshot reason=$reason count=${urls.size} types=${dmUrlTypesForLog(urls)} " +
                    "carouselFp=${dmCarouselFingerprintsForLog(urls)} " +
                    "elapsed=${elapsed}ms row=${describeViewBrief(targetRow)} anchor=${describeViewBrief(anchor)}"
            }
        }
        return rememberDmMessageActionMediaSnapshot(anchor, snapshot)
    }

    private fun rememberDmMessageActionMediaSnapshot(anchor: View, snapshot: DmMessageActionMediaSnapshot): DmMessageActionMediaSnapshot {
        dmMessageActionMediaSnapshotCache[anchor] = snapshot
        return snapshot
    }

    private fun recentDmMessageActionMediaSnapshot(): DmMessageActionMediaSnapshot? {
        val snapshot = dmLatestMessageActionMediaSnapshot ?: return null
        if (System.currentTimeMillis() - snapshot.atMs !in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS) return null
        if (recentDmMessageActionAnchor(DM_LONG_PRESS_CONTEXT_MAX_AGE_MS) == null) return null
        return snapshot
    }

    private fun recentDmMessageActionMenuVoiceContext(): Boolean? {
        recentDmCustomActionRowVoiceContext()?.let { return it }
        val age = System.currentTimeMillis() - dmLatestMessageActionMenuAtMs
        if (age !in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS) return null
        val actionTouchAge = System.currentTimeMillis() - dmLastCustomActionRowTouchAtMs
        val activeMenu = dmOverlayRootActive ||
            actionTouchAge in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS ||
            currentActivity?.window?.decorView?.let { root ->
                rootContainsActiveDmMessageActionsOverlay(root) || hasPurrfectDmActionRowsVisible(root)
            } == true
        if (!activeMenu) return null
        if (dmLatestMessageActionMenuWasVisual || isStrongDmVisualMessageTypeSignal(dmLatestMessageActionMenuTypeSignal)) return false
        if (dmLatestMessageActionMenuWasVoice) return true
        return false
    }

    private fun recentRenderedDmMessageActionMenuVoiceContext(now: Long = System.currentTimeMillis()): Boolean? {
        if (now - dmLastRenderedMessageActionMenuAtMs !in 0..DM_RENDERED_MENU_CONTEXT_MAX_AGE_MS) return null
        return dmLastRenderedMessageActionMenuVoiceContext
    }

    private fun recentDmMessageActionsViewModel(): Any? {
        val age = System.currentTimeMillis() - dmLatestMessageActionsViewModelAtMs
        if (age !in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS) return null
        return dmLatestMessageActionsViewModel?.get()
    }

    private fun tappedDmMessageActionMediaRow(anchor: View): View? {
        var current: View? = anchor
        var specific: View? = null
        var generic: View? = null
        var depth = 0
        val root = anchor.rootView
        val rootWidth = root?.width ?: 0
        while (current != null && depth++ < 7) {
            val node = current
            val widthOk = node.width <= 960 || (rootWidth > 0 && node !== root && node.width <= rootWidth && node.height <= 1_250)
            if (node.width > 0 && node.height > 0 && widthOk && node.height <= 1_250) {
                val descriptor = monetViewDescriptor(node)
                val specificRow = descriptor.contains("media_container") ||
                    descriptor.contains("xma") ||
                    descriptor.contains("visual_message") ||
                    descriptor.contains("voice_message")
                val genericRow = descriptor.contains("message_content") ||
                    descriptor.contains("direct_text_message")
                if (specificRow && specific == null && (node !is TextView || node.width >= 320 || node.height >= 160)) {
                    specific = node
                } else if (genericRow && generic == null) {
                    generic = node
                }
            }
            current = node.parent as? View
        }
        return specific ?: generic ?: anchor
    }

    private fun collectDmMediaUrlsInRow(row: View): List<String> {
        val out = ArrayList<String>(8)
        collectDmMediaUrlsInRow(row, 0, intArrayOf(0), out)
        return out
    }

    private fun collectDmMediaUrlsInRow(view: View?, depth: Int, visited: IntArray, out: MutableList<String>) {
        if (view == null || depth > 5 || visited[0]++ > 160 || out.size >= 12) return
        if (view.visibility != View.VISIBLE || view.width <= 0 || view.height <= 0) return
        extractCachedMediaUrlFromView(view)
            ?.takeIf { !looksLikeProfileImageUrl(it) }
            ?.let(out::add)
        if (view is ViewGroup) {
            val count = minOf(view.childCount, 24)
            for (i in 0 until count) collectDmMediaUrlsInRow(view.getChildAt(i), depth + 1, visited, out)
        }
    }

    private fun extractCachedMediaUrlFromView(view: View): String? {
        dmImageViewUrls[view]?.takeIf { looksLikeMediaUrl(it) }?.let { return it }
        storyTrayImageUrls[view]?.takeIf { looksLikeMediaUrl(it) }?.let { return it }
        return extractUrlFromView(view)?.takeIf { looksLikeMediaUrl(it) || isLikelyAudioHttpUrl(it) }
    }

    private fun rememberKeepUnsentActionRowFromLongClick(view: View) {
        if (!state.keepUnsentMessages) return
        val root = view.rootView ?: view
        if (dmMessageActionsOverlayVisible(root) || hasPurrfectDmActionRowsVisible(root)) return
        val rowRoot = nearestKeepUnsentRowRoot(view)
            ?.takeIf { findViewByResourceName(it, "direct_text_message_text_view") != null }
            ?: findKeepUnsentRowNearLastMessageActionTouch()
            ?: findKeepUnsentRowNearViewCenter(view)
            ?: return
        rememberKeepUnsentActionRowRoot(rowRoot)
    }

    private fun rememberNewestVisibleKeepUnsentActionRow(reason: String) {
        if (!state.keepUnsentMessages) return
        val root = currentActivity?.window?.decorView ?: return
        if (!isKeepUnsentConversationSurfaceActive(root)) {
            logKeepUnsentDebug("newest-row fallback skipped outside Direct thread reason=$reason root=${describeViewBrief(root)}")
            return
        }
        val touchAge = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
        if (touchAge in 0..15_000L) {
            val touchedRow = findKeepUnsentRowNearLastMessageActionTouch()
            if (touchedRow != null) {
                rememberKeepUnsentActionRowRoot(touchedRow)
                logInfo("Captured keep-unsent Direct row fallback reason=$reason source=touch-near")
            } else {
                logInfo(
                    "Skipped keep-unsent newest-row fallback reason=$reason because recent touch row was unresolved " +
                        "touchAge=$touchAge x=${dmLastMessageActionTouchX.toInt()} y=${dmLastMessageActionTouchY.toInt()}"
                )
            }
            return
        }
        val textViews = ArrayList<TextView>()
        val scanRoot = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) } ?: root
        collectVisibleKeepUnsentTextViews(scanRoot, textViews, intArrayOf(650))
        val textView = textViews.lastOrNull { normalizeKeepUnsentMessageText(it.text) != null } ?: return
        val text = normalizeKeepUnsentMessageText(textView.text) ?: return
        val rowRoot = nearestKeepUnsentRowRoot(textView) ?: textView
        val rowIds = collectKeepUnsentViewRowIds(rowRoot, rowRoot) + collectKeepUnsentRecyclerHolderIds(rowRoot)
        keepUnsentLastActionRowRoot = WeakReference(rowRoot)
        keepUnsentLastActionRowText = text
        keepUnsentLastActionRowIds = rowIds
        keepUnsentLastActionRowAtMs = System.currentTimeMillis()
        rememberKeepUnsentVisibleTextRow(rowRoot)
        logInfo("Captured keep-unsent Direct row fallback reason=$reason text=${formatKeepUnsentText(keepUnsentLastActionRowText)} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)}")
    }

    private fun collectVisibleKeepUnsentTextViews(view: View?, out: MutableList<TextView>, budget: IntArray) {
        if (view == null || budget[0]-- <= 0 || !view.isShown) return
        if (view is TextView && isKeepUnsentMessageTextCandidate(view)) out += view
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                collectVisibleKeepUnsentTextViews(view.getChildAt(i), out, budget)
                if (budget[0] <= 0) return
            }
        }
    }

    private fun rememberKeepUnsentActionRowFromRawTouchDeferred(root: View?, event: MotionEvent, touchedView: View? = null) {
        if (!state.keepUnsentMessages || root == null) return
        if (!isKeepUnsentTouchCaptureSurfaceActive(touchedView ?: root)) return
        val base = root.rootView ?: root
        val eventTime = event.eventTime
        val rawX = event.rawX
        val rawY = event.rawY
        val now = System.currentTimeMillis()
        dmLastMessageActionTouchX = rawX
        dmLastMessageActionTouchY = rawY
        dmLastMessageActionTouchAtMs = now
        if (eventTime == keepUnsentDeferredRawTouchEventTime &&
            abs(rawX - keepUnsentDeferredRawTouchX) < 1f &&
            abs(rawY - keepUnsentDeferredRawTouchY) < 1f
        ) {
            return
        }
        keepUnsentDeferredRawTouchRoot = WeakReference(base)
        keepUnsentDeferredRawTouchView = touchedView?.let(::WeakReference)
        keepUnsentDeferredRawTouchEventTime = eventTime
        keepUnsentDeferredRawTouchX = rawX
        keepUnsentDeferredRawTouchY = rawY
        logInfoThrottled("keep-unsent:raw-touch-deferred", 1_000L) {
            "Deferred keep-unsent raw touch scan x=${rawX.toInt()} y=${rawY.toInt()} " +
                "view=${touchedView?.let { describeViewBrief(it) } ?: "-"} root=${describeViewBrief(base)}"
        }
        mainHandler.postDelayed({
            val scanRoot = keepUnsentDeferredRawTouchRoot?.get() ?: return@postDelayed
            if (eventTime != keepUnsentDeferredRawTouchEventTime ||
                abs(rawX - keepUnsentDeferredRawTouchX) >= 1f ||
                abs(rawY - keepUnsentDeferredRawTouchY) >= 1f
            ) {
                return@postDelayed
            }
            val started = SystemClock.uptimeMillis()
            rememberKeepUnsentActionRowFromRawTouch(
                scanRoot,
                eventTime,
                rawX,
                rawY,
                keepUnsentDeferredRawTouchView?.get()
            )
            logInfoThrottled("keep-unsent:raw-touch-deferred-elapsed", 1_000L) {
                "Deferred keep-unsent raw touch scan finished elapsed=${SystemClock.uptimeMillis() - started}ms " +
                    "x=${rawX.toInt()} y=${rawY.toInt()} root=${describeViewBrief(scanRoot)}"
            }
        }, 650L)
    }

    private fun rememberKeepUnsentActionRowFromRawTouch(root: View?, event: MotionEvent, touchedView: View? = null) {
        rememberKeepUnsentActionRowFromRawTouch(root, event.eventTime, event.rawX, event.rawY, touchedView)
    }

    private fun rememberKeepUnsentActionRowFromRawTouch(
        root: View?,
        eventTime: Long,
        rawX: Float,
        rawY: Float,
        touchedView: View? = null
    ) {
        if (!state.keepUnsentMessages || root == null) return
        if (!isKeepUnsentTouchCaptureSurfaceActive(touchedView ?: root)) return
        if (eventTime == keepUnsentLastRawTouchScanEventTime &&
            abs(rawX - keepUnsentLastRawTouchScanX) < 1f &&
            abs(rawY - keepUnsentLastRawTouchScanY) < 1f
        ) {
            return
        }
        keepUnsentLastRawTouchScanEventTime = eventTime
        keepUnsentLastRawTouchScanX = rawX
        keepUnsentLastRawTouchScanY = rawY
        if (dmMessageActionsOverlayVisible(root) ||
            rootContainsActiveDmMessageActionsOverlay(root) ||
            hasPurrfectDmActionRowsVisible(root)
        ) {
            return
        }
        dmLastMessageActionTouchX = rawX
        dmLastMessageActionTouchY = rawY
        dmLastMessageActionTouchAtMs = System.currentTimeMillis()
        val rowRoot = findKeepUnsentRowAtScreenPoint(root, rawX, rawY)
        if (rowRoot == null) {
            keepUnsentAccessibilityTextAtPoint(root, rawX.toInt(), rawY.toInt())?.let { text ->
                keepUnsentLastActionRowRoot = null
                keepUnsentLastActionRowText = text
                keepUnsentLastActionRowIds = emptySet()
                keepUnsentLastActionRowAtMs = dmLastMessageActionTouchAtMs
                logInfo("Captured keep-unsent Direct accessibility touch text=${formatKeepUnsentText(text)} x=${rawX.toInt()} y=${rawY.toInt()}")
                return
            }
            val now = System.currentTimeMillis()
            if (now - keepUnsentLastRawTouchMissLogAtMs > 1_500L) {
                keepUnsentLastRawTouchMissLogAtMs = now
                logInfo("Keep-unsent raw touch found no Direct text row x=${rawX.toInt()} y=${rawY.toInt()} root=${describeViewBrief(root)}")
            }
            return
        }
        if (!hasKeepUnsentDirectTextRow(rowRoot)) return
        rememberKeepUnsentActionRowRoot(rowRoot, rawX, rawY)
    }

    private fun rememberKeepUnsentActionRowFromTouchedView(view: View, event: MotionEvent) {
        if (!state.keepUnsentMessages) return
        if (!isKeepUnsentTouchCaptureSurfaceActive(view)) return
        val root = view.rootView ?: view
        if (dmMessageActionsOverlayVisible(root) || hasPurrfectDmActionRowsVisible(root)) return
        val rowRoot = nearestKeepUnsentRowRoot(view) ?: return
        if (findViewByResourceName(rowRoot, "direct_text_message_text_view") == null) return
        val rect = Rect()
        if (!rowRoot.getGlobalVisibleRect(rect) || !rect.contains(event.rawX.toInt(), event.rawY.toInt())) return
        rememberKeepUnsentActionRowRoot(rowRoot, event)
    }

    private fun isKeepUnsentTouchCaptureSurfaceActive(view: View? = null): Boolean {
        return isKeepUnsentConversationSurfaceActive(view)
    }

    private fun shouldAttemptKeepUnsentTouchCapture(view: View?): Boolean {
        if (!state.keepUnsentMessages || view == null) return false
        if (!hasLocalDirectTouchHint(view)) return false
        return isKeepUnsentConversationSurfaceActive(view) && isKeepUnsentDirectViewPath(view)
    }

    private fun isKeepUnsentConversationSurfaceActive(view: View? = null): Boolean {
        if (view != null && isKeepUnsentDirectViewPath(view)) return true
        val root = view?.rootView ?: currentActivity?.window?.decorView ?: return false
        val reason = directMessageSurfaceReason(root)
        if (isDirectThreadSurfaceReason(reason)) return true
        if (reason == "direct-inbox-id") return false
        return view != null && isKeepUnsentDirectViewPath(view)
    }

    private fun isDirectThreadSurfaceReason(reason: String?): Boolean {
        return reason == "direct-thread-root-id" ||
            reason == "message-list-with-thread-chrome" ||
            reason == "message-actions-id"
    }

    private val keepUnsentDirectViewPathCache = Collections.synchronizedMap(WeakHashMap<View, Boolean>())

    private fun isKeepUnsentDirectViewPath(view: View?): Boolean {
        if (view == null) return false
        val cached = keepUnsentDirectViewPathCache[view]
        if (cached != null) return cached

        var current = view
        var isPath = false
        repeat(14) {
            val node = current
            if (node == null) {
                keepUnsentDirectViewPathCache[view] = false
                return false
            }
            if (isKnownKeepUnsentDirectPathResource(node)) {
                isPath = true
                return@repeat
            }
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (name == "direct_text_message_text_view" ||
                name == "message_list" ||
                name == "thread_view_root" ||
                name == "message_thread_container" ||
                name == "direct_thread_content_below_action_bar" ||
                name == "thread_fragment_container" ||
                name == "message_actions_fragment" ||
                name == "row_thread_composer_container" ||
                name == "row_thread_composer_edittext" ||
                name == "direct_thread_header" ||
                name.contains("direct_thread") ||
                name.contains("thread_composer")
            ) {
                isPath = true
                return@repeat
            }
            val cls = node.javaClass.name.lowercase(Locale.US)
            if (cls.contains("instagram.direct.thread") ||
                cls.contains("direct.thread") ||
                cls.contains("directthreadmessagerecyclerview")
            ) {
                isPath = true
                return@repeat
            }
            current = node.parent as? View
        }
        keepUnsentDirectViewPathCache[view] = isPath
        return isPath
    }

    private val likelyDirectTouchPathCache = Collections.synchronizedMap(WeakHashMap<View, Boolean>())

    private fun isLikelyDirectTouchPath(view: View?): Boolean {
        if (view == null) return false
        if (isKeepUnsentDirectViewPath(view)) return true
        val cached = likelyDirectTouchPathCache[view]
        if (cached != null) return cached
        
        var current = view
        var isPath = false
        repeat(10) {
            val node = current
            if (node == null) {
                likelyDirectTouchPathCache[view] = false
                return false
            }
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (name.contains("direct_thread") ||
                name.contains("thread_view") ||
                name.contains("message_actions") ||
                name.contains("row_thread_composer") ||
                name == "message_list" ||
                name == "direct_inbox"
            ) {
                isPath = true
                return@repeat
            }
            val cls = node.javaClass.name.lowercase(Locale.US)
            if (cls.contains("directthread") ||
                cls.contains(".messagethread.")
            ) {
                isPath = true
                return@repeat
            }
            current = node.parent as? View
        }
        likelyDirectTouchPathCache[view] = isPath
        return isPath
    }

    private fun isKnownKeepUnsentDirectPathResource(view: View): Boolean {
        return hasInstagramResourceId(view, "direct_text_message_text_view") ||
            hasInstagramResourceId(view, "message_list") ||
            hasInstagramResourceId(view, "thread_view_root") ||
            hasInstagramResourceId(view, "message_thread_container") ||
            hasInstagramResourceId(view, "direct_thread_content_below_action_bar") ||
            hasInstagramResourceId(view, "thread_fragment_container") ||
            hasInstagramResourceId(view, "message_actions_fragment") ||
            hasInstagramResourceId(view, "row_thread_composer_container") ||
            hasInstagramResourceId(view, "row_thread_composer_edittext") ||
            hasInstagramResourceId(view, "direct_thread_header")
    }

    private fun rememberKeepUnsentActionRowRoot(rowRoot: View, event: MotionEvent) {
        rememberKeepUnsentActionRowRoot(rowRoot, event.rawX, event.rawY)
    }

    private fun rememberKeepUnsentActionRowRoot(rowRoot: View, rawX: Float? = null, rawY: Float? = null) {
        val rowText = keepUnsentRowMessageText(rowRoot)
        val rowIds = collectKeepUnsentViewRowIds(rowRoot, rowRoot) + collectKeepUnsentRecyclerHolderIds(rowRoot)
        if (rowText == null && rowIds.isEmpty()) return
        keepUnsentLastActionRowRoot = WeakReference(rowRoot)
        keepUnsentLastActionRowText = rowText
        keepUnsentLastActionRowIds = rowIds
        keepUnsentLastActionRowAtMs = System.currentTimeMillis()
        if (rawX != null && rawY != null) {
            dmLastMessageActionTouchX = rawX
            dmLastMessageActionTouchY = rawY
            dmLastMessageActionTouchAtMs = keepUnsentLastActionRowAtMs
        }
        rememberKeepUnsentVisibleTextRow(rowRoot)
        if (keepUnsentLastActionRowAtMs - keepUnsentLastRawTouchCaptureLogAtMs > 1_500L) {
            keepUnsentLastRawTouchCaptureLogAtMs = keepUnsentLastActionRowAtMs
            logInfo("Captured keep-unsent Direct row touch text=${formatKeepUnsentText(rowText)} ids=${formatKeepUnsentIds(rowIds)}")
        }
    }

    private fun rememberDmMessageActionTouchCandidate(view: View, event: MotionEvent) {
        if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return
        if (event.actionMasked != MotionEvent.ACTION_DOWN) return
        if (!dmDirectSurfaceActive && !dmOverlayRootActive && !isLikelyDirectTouchPath(view)) return
        if (!isDirectMessageSurfaceActive()) return
        if (isInsideDmMessageActionsOverlay(view) || dmMessageActionsOverlayVisible(view)) return
        if (isDmCustomActionMenuTouch(view)) {
            rememberDmCustomActionRowTouch(view)
            logInfoThrottled("dm:touch-candidate:custom-row:${describeViewBrief(view)}", 1_000L) {
                "Ignored DM action-row touch as new message candidate action=${dmActionLabel(dmLastCustomActionRowTouchAction)} " +
                    "view=${describeViewBrief(view)}"
            }
            return
        }
        dmLastMessageActionTouchX = event.rawX
        dmLastMessageActionTouchY = event.rawY
        dmLastMessageActionTouchAtMs = System.currentTimeMillis()
        clearDmMessageActionSelection("touch-down")
        armDmSavedStateLongPressGuard("touch-candidate")
        if (dmLastMessageActionTouchAtMs - dmLastTouchCandidateLogAtMs > 700L) {
            dmLastTouchCandidateLogAtMs = dmLastMessageActionTouchAtMs
            val root = view.rootView ?: view
            logInfo(
                "DM long-press touch candidate down x=${event.rawX.toInt()} y=${event.rawY.toInt()} " +
                    "view=${describeViewBrief(view)} root=${describeViewBrief(root)} surface=${directMessageSurfaceReason(root) ?: "-"}"
            )
        }
    }

    private fun findTouchedDmMessageActionAnchor(view: View, x: Float, y: Float, depth: Int): View? {
        if (depth > 8 || view.visibility != View.VISIBLE) return null
        if (view is ViewGroup) {
            for (i in view.childCount - 1 downTo 0) {
                val child = view.getChildAt(i) ?: continue
                if (child.visibility != View.VISIBLE) continue
                val cx = x - child.left + child.scrollX
                val cy = y - child.top + child.scrollY
                if (cx < 0f || cy < 0f || cx > child.width || cy > child.height) continue
                findTouchedDmMessageActionAnchor(child, cx, cy, depth + 1)?.let { return it }
                if (isDmMessageActionAnchorCandidate(child)) return child
            }
        }
        return view.takeIf { isDmMessageActionAnchorCandidate(it) }
    }

    private fun isDmMessageActionAnchorCandidate(view: View): Boolean {
        if (view.width > 960 && view.height > 1_200) return false
        val descriptor = monetViewDescriptor(view)
        val hasVoiceHint = viewContainsVoiceHint(view, 0, intArrayOf(0))
        return descriptor.contains("message_content") ||
            descriptor.contains("voice_message") ||
            descriptor.contains("direct_text_message") ||
            descriptor.contains("media_container") ||
            hasVoiceHint
    }

    private fun isDmCustomActionMenuTouch(view: View): Boolean {
        if (dmCustomActionFromMenuTouch(view) >= 0) return true
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 5) {
            val descriptor = monetViewDescriptor(current)
            if ((descriptor.contains("context_menu_item") ||
                    descriptor.contains("compose_context_menu") ||
                    descriptor.contains("popupdecorview") ||
                    descriptor.contains("message_actions")) &&
                viewContainsDmCustomActionLabel(current)
            ) {
                return true
            }
            current = current.parent as? View
        }
        return false
    }

    private fun viewContainsDmCustomActionLabel(view: View?): Boolean {
        return dmCustomActionLabelsInView(view).isNotEmpty()
    }

    private fun rememberDmCustomActionRowTouch(view: View) {
        val action = dmCustomActionFromMenuTouch(view)
        if (action < 0) return
        val now = System.currentTimeMillis()
        dmLastCustomActionRowTouchAction = action
        dmLastCustomActionRowTouchAtMs = now
        dmLastCustomActionRowTouchView = describeViewBrief(view)
        dmLastCustomActionRowVoiceContext = dmMessageActionMenuVoiceContextForRowTouch(now)
            ?: recentRenderedDmMessageActionMenuVoiceContext(now)
    }

    private fun recentDmCustomActionRowTouchAction(): Int {
        val action = dmLastCustomActionRowTouchAction
        if (action < 0) return -1
        val age = System.currentTimeMillis() - dmLastCustomActionRowTouchAtMs
        return if (age in 0..3_000L) action else -1
    }

    private fun recentDmCustomActionRowVoiceContext(): Boolean? {
        if (recentDmCustomActionRowTouchAction() < 0) return null
        return dmLastCustomActionRowVoiceContext
    }

    private fun dmMessageActionMenuVoiceContextForRowTouch(now: Long = System.currentTimeMillis()): Boolean? {
        val age = now - dmLatestMessageActionMenuAtMs
        if (age !in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS) return null
        if (dmLatestMessageActionMenuWasVisual || isStrongDmVisualMessageTypeSignal(dmLatestMessageActionMenuTypeSignal)) return false
        if (dmLatestMessageActionMenuWasVoice) return true
        return null
    }

    private fun dmCustomActionFromMenuTouch(view: View?): Int {
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 5) {
            if (current is TextView) {
                actionFromDmCustomLabel(current.text?.toString()).takeIf { it >= 0 }?.let { return it }
            }
            val labels = dmCustomActionLabelsInView(current)
            if (labels.size == 1) return actionFromDmCustomLabel(labels.first())
            current = current.parent as? View
        }
        return -1
    }

    private fun dmCustomActionLabelsInView(view: View?): List<String> {
        if (view == null) return emptyList()
        return visibleTextInView(view, 0, StringBuilder())
            .lineSequence()
            .map { it.trim().lowercase(Locale.US) }
            .filter { it.isNotBlank() }
            .take(12)
            .filter { actionFromDmCustomLabel(it) >= 0 }
            .distinct()
            .toList()
    }

    private fun handleDmMessageActionOverlayClick(view: View): Boolean {
        if (state.keepUnsentMessages && isNativeDmUnsendMenuRowView(view)) {
            markRecentKeepUnsentNativeUnsend(view.rootView ?: view)
            return false
        }
        if (!state.enableDmContextMenuOptions) return false
        if (!isInsideDmMessageActionsOverlay(view) && !rootContainsDmMessageActionsOverlay(view)) return false
        if (!hasPurrfectDmActionRowsVisible(view.rootView ?: view)) return false
        val action = dmActionFromVisibleMenuRow(view) ?: return false
        if (shouldIgnoreDmOverlayActionClick(view)) return false
        if (!claimDmOverlayAction(action, view)) return true
        val context = view.context ?: currentActivity ?: androidContext
        val anchor = recentDmMessageActionAnchor()
        val sources = dmMessageActionSources(
            anchor = anchor,
            view = view
        )
        val resolvedUrl = resolveDmContextUrl(null, anchor ?: view, sources)
        logInfo(
            "DM overlay click resolved action=${dmActionLabel(action)} resolvedUrl=${resolvedUrl != null} " +
                "view=${describeViewBrief(view)} anchor=${describeViewBrief(anchor)} surface=${dmSurfaceForLog()}"
        )
        runClaimedDmOverlayAction(context, anchor ?: view, action, sources, resolvedUrl, "click")
        clearDmOverlayGestureDown()
        return true
    }

    private fun handleDmMessageActionOverlayTouch(view: View, event: MotionEvent): Boolean {
        if (event.actionMasked == MotionEvent.ACTION_CANCEL || event.actionMasked == MotionEvent.ACTION_OUTSIDE) {
            clearDmOverlayGestureDown()
            return false
        }
        if (event.actionMasked != MotionEvent.ACTION_UP) return false
        return try {
            if (isLikelyLongPressRelease(event)) return false
            if (!state.enableDmContextMenuOptions && !state.keepUnsentMessages) return false
            if (!dmDirectSurfaceActive && !dmOverlayRootActive) return false
            val root = view.rootView ?: view
            val overlayVisible = dmMessageActionsOverlayVisible(view)
            val purrfectRowsVisible = hasPurrfectDmActionRowsVisible(root)
            if (!overlayVisible && !purrfectRowsVisible) return false
            if (shouldIgnoreDmOverlayActionGesture(root, event)) return false
            if (state.keepUnsentMessages && nativeDmUnsendMenuRowAt(root, event.rawX, event.rawY) != null) {
                markRecentKeepUnsentNativeUnsend(root, event.rawX, event.rawY)
                return false
            }
            if (!overlayVisible) return false
            if (!state.enableDmContextMenuOptions) return false
            if (!purrfectRowsVisible) return false
            val target = findTouchedDmOverlayChild(view, event.x, event.y) ?: view
            val (action, actionView) = dmActionFromVisibleMenuRowAt(view.rootView ?: view, event.rawX, event.rawY) ?: return false
            if (!isInsideDmMessageActionsOverlay(actionView) && !isInsideDmMessageActionsOverlay(target) && !isInsideDmMessageActionsOverlay(view) && !dmMessageActionsOverlayVisible(view)) return false
            if (!claimDmOverlayAction(action, actionView)) return true
            val context = actionView.context ?: target.context ?: view.context ?: currentActivity ?: androidContext
            val anchor = recentDmMessageActionAnchor()
            val sources = dmMessageActionSources(
                anchor = anchor,
                view = actionView,
                extra = arrayOf(target, view)
            )
            val resolvedUrl = resolveDmContextUrl(null, anchor ?: actionView, sources)
            logInfo(
                "DM overlay touch resolved action=${dmActionLabel(action)} resolvedUrl=${resolvedUrl != null} " +
                    "actionView=${describeViewBrief(actionView)} target=${describeViewBrief(target)} anchor=${describeViewBrief(anchor)} " +
                    "surface=${dmSurfaceForLog()}"
            )
            runClaimedDmOverlayAction(context, anchor ?: actionView, action, sources, resolvedUrl, "touch")
            true
        } finally {
            clearDmOverlayGestureDown()
        }
    }

    private fun rememberDmOverlayGestureDown(view: View, event: MotionEvent) {
        if (event.actionMasked != MotionEvent.ACTION_DOWN) return
        if (!state.enableDmContextMenuOptions) return
        val root = view.rootView ?: view
        if (!dmDirectSurfaceActive && !dmOverlayRootActive && !isLikelyDirectTouchPath(view)) return
        val directSurface = dmDirectSurfaceActive ||
            dmOverlayRootActive ||
            isDirectMessageSurfaceActive()
        if (!directSurface) return
        dmOverlayGestureDownX = event.rawX
        dmOverlayGestureDownY = event.rawY
        dmOverlayGestureDownAtMs = System.currentTimeMillis()
        dmOverlayGestureHadOverlayAtDown =
            dmMessageActionsOverlayVisible(root) ||
                hasPurrfectDmActionRowsVisible(root) ||
                isInsideDmMessageActionsOverlay(view)
    }

    private fun clearDmOverlayGestureDown() {
        dmOverlayGestureDownX = -1f
        dmOverlayGestureDownY = -1f
        dmOverlayGestureDownAtMs = 0L
        dmOverlayGestureHadOverlayAtDown = false
    }

    private fun shouldIgnoreDmOverlayActionClick(view: View): Boolean {
        val root = view.rootView ?: view
        val downAt = dmOverlayGestureDownAtMs
        if (downAt <= 0L) return false
        if (dmOverlayGestureHadOverlayAtDown) return false
        val age = System.currentTimeMillis() - downAt
        if (age <= 900L) {
            logIgnoredDmOverlayGestureOnce("click-after-menu-open age=$age root=${describeViewBrief(root)}")
            return true
        }
        return false
    }

    private fun shouldIgnoreDmOverlayActionGesture(root: View, event: MotionEvent): Boolean {
        val downAt = dmOverlayGestureDownAtMs
        if (downAt <= 0L) return true
        val slop = dp(root, 18)
        val dx = abs(event.rawX - dmOverlayGestureDownX)
        val dy = abs(event.rawY - dmOverlayGestureDownY)
        val moved = dx > slop || dy > slop
        val eventDuration = event.eventTime - event.downTime
        val wallDuration = System.currentTimeMillis() - downAt
        val menuOpenedDuringGesture = !dmOverlayGestureHadOverlayAtDown && (eventDuration > 120L || wallDuration > 120L)
        if (!moved && !menuOpenedDuringGesture) return false
        logIgnoredDmOverlayGestureOnce(
            "touch moved=$moved dx=${dx.toInt()} dy=${dy.toInt()} eventDuration=$eventDuration wallDuration=$wallDuration overlayAtDown=$dmOverlayGestureHadOverlayAtDown"
        )
        return true
    }

    private fun logIgnoredDmOverlayGestureOnce(reason: String) {
        val now = System.currentTimeMillis()
        if (now - dmLastIgnoredOverlayGestureLogAtMs < 1_500L) return
        dmLastIgnoredOverlayGestureLogAtMs = now
        logInfo("Ignored DM MessageActions overlay gesture $reason")
    }

    private fun shouldClaimDmCustomAction(view: View?, origin: String): Boolean {
        if (!state.enableDmContextMenuOptions) return false
        val root = view?.rootView ?: currentActivity?.window?.decorView
        val directReason = root?.let { directMessageSurfaceReason(it) }
        val directSurface = directReason != null
        val overlaySurface = root != null &&
            (rootContainsActiveDmMessageActionsOverlay(root) || rootContainsDmMessageActionsOverlay(root))
        val insideOverlay = view != null && isInsideDmMessageActionsOverlay(view)
        val hasRecentDirectAnchor = recentDmMessageActionAnchor() != null
        if (directSurface || overlaySurface || insideOverlay || hasRecentDirectAnchor) {
            logInfoThrottled("dm:claim:$origin", 900L) {
                "Claimed custom DM MessageActions $origin directSurface=$directSurface reason=${directReason ?: "-"} " +
                    "overlaySurface=$overlaySurface insideOverlay=$insideOverlay recentAnchor=$hasRecentDirectAnchor " +
                    "view=${view?.let { describeViewBrief(it) } ?: "-"} root=${root?.let { describeViewBrief(it) } ?: "-"}"
            }
            return true
        }

        val now = SystemClock.elapsedRealtime()
        if (now - dmLastNonDirectActionRejectLogAtMs > 1_500L) {
            dmLastNonDirectActionRejectLogAtMs = now
            logInfo(
                "Skipped custom DM MessageActions $origin outside Direct " +
                    "view=${view?.let { describeViewBrief(it) } ?: "-"} root=${root?.let { describeViewBrief(it) } ?: "-"}"
            )
        }
        return false
    }

    private fun shouldCaptureDmMediaUrl(view: View?, origin: String, voiceStack: Boolean = false): Boolean {
        if (!state.enableDmContextMenuOptions) return false
        if (voiceStack) return true
        if (hasActiveDmActionRuntime()) return true
        if (view != null && (isLikelyDirectTouchPath(view) || isInsideDmMessageActionsOverlay(view))) return true
        if (Looper.myLooper() == Looper.getMainLooper() && isDirectMessageSurfaceActive()) return true

        val now = SystemClock.elapsedRealtime()
        if (now - dmLastMediaCaptureSkipLogAtMs > 5_000L) {
            dmLastMediaCaptureSkipLogAtMs = now
            val root = view?.rootView ?: currentActivity?.window?.decorView
            logInfo(
                "Skipped DM media URL capture outside Direct origin=$origin " +
                    "view=${view?.let { describeViewBrief(it) } ?: "-"} root=${root?.let { describeViewBrief(it) } ?: "-"}"
            )
        }
        return false
    }

    private fun shouldUseGlobalDmUrlCapture(): Boolean {
        if (!state.enableDmContextMenuOptions) return false
        if (dmOverlayRootActive || dmActiveOverlayVisibleCached || dmPurrfectRowsVisibleCached) return true
        if (hasCachedDirectTouchSurface()) return true
        val now = System.currentTimeMillis()
        val recentDmContext =
            now - dmLastMessageActionTouchAtMs in 0..DM_LONG_PRESS_DETECTION_MAX_AGE_MS ||
                now - dmLatestMessageActionAnchorAtMs in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS ||
                now - dmLatestMessageActionMenuAtMs in 0..DM_RENDERED_MENU_CONTEXT_MAX_AGE_MS ||
                now - dmLastRenderedMessageActionMenuAtMs in 0..DM_RENDERED_MENU_CONTEXT_MAX_AGE_MS ||
                now - dmLatestMessageActionsViewModelAtMs in 0..DM_RENDERED_MENU_CONTEXT_MAX_AGE_MS
        return recentDmContext && hasActiveDmActionRuntime()
    }

    private fun hasActiveDmActionRuntime(): Boolean {
        recentDmMessageActionAnchor()?.let { anchor ->
            if (anchor.isAttachedToWindow && isLikelyDirectTouchPath(anchor)) return true
        }
        val root = currentActivity?.window?.decorView
        val surfaceReason = root?.let { directMessageSurfaceReason(it) }
        if (root != null && (rootContainsActiveDmMessageActionsOverlay(root) || hasPurrfectDmActionRowsVisible(root))) return true
        val touchAge = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
        return touchAge in 0..DM_LONG_PRESS_DETECTION_MAX_AGE_MS && isDirectThreadSurfaceReason(surfaceReason)
    }

    private fun isKnownNonDirectMediaSurface(root: View?): Boolean {
        if (root == null || Looper.myLooper() != Looper.getMainLooper()) return false
        val now = SystemClock.elapsedRealtime()
        val cachedRoot = dmNonDirectMediaSurfaceRoot?.get()
        if (cachedRoot === root && now - dmNonDirectMediaSurfaceCheckAtMs < 1_500L) {
            return dmNonDirectMediaSurfaceActive
        }
        dmNonDirectMediaSurfaceRoot = WeakReference(root)
        dmNonDirectMediaSurfaceCheckAtMs = now
        dmNonDirectMediaSurfaceActive = hasVisibleIdContaining(
            root,
            "clips_viewer",
            "clips_tab_view_pager",
            "clips_viewer_video_layout",
            "clips_ufi_component"
        )
        return dmNonDirectMediaSurfaceActive
    }

    private fun shouldInspectDmCustomListener(view: View, origin: String): Boolean {
        if (dmOverlayRootActive || hasCachedDirectTouchSurface()) return true
        run {
            val now = System.currentTimeMillis()
            val recentTouch = now - dmLastMessageActionTouchAtMs in 0..DM_LONG_PRESS_DETECTION_MAX_AGE_MS
            val recentAnchor = recentDmMessageActionAnchor() != null
            if (!recentTouch && !recentAnchor) return false
        }
        val ownName = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        val ownClass = view.javaClass.name.lowercase(Locale.US)
        val maybeDirectView = ownName.contains("direct") ||
            ownName.contains("message_actions") ||
            ownName.contains("message_thread") ||
            ownName.contains("thread_view") ||
            ownClass.contains("directthread") ||
            ownClass.contains(".messagethread.")
        if (!maybeDirectView) {
            val touchAge = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
            if (touchAge !in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS) return false
            if (!hasActiveDmActionRuntime()) return false
            return true
        }
        if (isLikelyDirectTouchPath(view)) return true
        if (hasActiveDmActionRuntime()) return true
        val root = view.rootView ?: view
        if (Looper.myLooper() == Looper.getMainLooper() && isDirectMessageSurfaceActive()) return true
        if (isKnownNonDirectMediaSurface(root)) {
            return false
        }

        logKeepUnsentDebug("dm listener inspection skipped $origin view=${describeViewBrief(view)} root=${describeViewBrief(root)}")
        return false
    }

    private fun handleNativeDmUnsendActivityTouch(activity: Activity, event: MotionEvent) {
        if (!state.keepUnsentMessages) return
        if (isLikelyLongPressRelease(event)) return
        val root = activity.window?.decorView ?: return
        if (!isKeepUnsentConversationSurfaceActive(root)) return
        val hasRecentKeepUnsentRow = hasRecentKeepUnsentActionRow()
        val purrfectRowsVisible = hasPurrfectDmActionRowsVisible(root)
        val overlayVisible = dmMessageActionsOverlayVisible(root)
        val bandLooksLikeUnsend = isLikelyNativeDmUnsendScreenBandTap(root, event.rawX, event.rawY)
        if (bandLooksLikeUnsend && !hasRecentKeepUnsentRow && System.currentTimeMillis() - keepUnsentLastNativeUnsendMissLogAtMs > 1_500L) {
            keepUnsentLastNativeUnsendMissLogAtMs = System.currentTimeMillis()
            logInfo("Native DM Unsend band tap had no recent keep-unsent row")
        }
        if (!overlayVisible && !purrfectRowsVisible) return
        val nativeRow = nativeDmUnsendMenuRowAt(root, event.rawX, event.rawY)
        val geometryLooksLikeUnsend = isLikelyNativeDmUnsendGeometryTap(root, event.rawX, event.rawY, purrfectRowsVisible)
        if (nativeRow != null) {
            logInfo(
                "Detected native DM Unsend tap for keep-unsent marker source=row " +
                    "x=${event.rawX.toInt()} y=${event.rawY.toInt()} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)} " +
                    "text=${formatKeepUnsentText(keepUnsentLastActionRowText)}"
            )
            markRecentKeepUnsentNativeUnsend(root, event.rawX, event.rawY)
        } else if ((bandLooksLikeUnsend || geometryLooksLikeUnsend) && System.currentTimeMillis() - keepUnsentLastNativeUnsendMissLogAtMs > 1_500L) {
            keepUnsentLastNativeUnsendMissLogAtMs = System.currentTimeMillis()
            logInfo(
                "Observed possible native DM Unsend tap without row hit source=${if (geometryLooksLikeUnsend) "geometry" else "screen-band"}; " +
                    "awaiting native listener/delete event x=${event.rawX.toInt()} y=${event.rawY.toInt()} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)}"
            )
        }
    }

    private fun handleNativeDmUnsendPerformClick(view: View) {
        if (!state.keepUnsentMessages || !hasRecentKeepUnsentActionRow()) return
        if (!isKeepUnsentConversationSurfaceActive(view)) return
        if (!isLikelyNativeDmUnsendClickView(view)) return
        logInfo("Detected native DM Unsend performClick for keep-unsent marker")
        markRecentKeepUnsentNativeUnsend(view.rootView ?: view)
    }

    private fun handleNativeDmUnsendViewTouch(view: View, event: MotionEvent) {
        if (!state.keepUnsentMessages) return
        if (isLikelyLongPressRelease(event)) return
        if (!hasCachedDirectTouchSurface()) return
        if (!hasLocalDirectTouchHint(view)) return
        if (!isKeepUnsentConversationSurfaceActive(view)) return
        val now = System.currentTimeMillis()
        if (now - keepUnsentLastActionRowAtMs !in 0..30_000L) return
        if (now - keepUnsentLastNativeUnsendMarkAtMs < 900L) return
        val root = view.rootView ?: view
        if (!dmMessageActionsOverlayVisible(root) && !hasPurrfectDmActionRowsVisible(root)) return
        val nativeRow = nativeDmUnsendMenuRowAt(root, event.rawX, event.rawY)
        val bandLooksLikeUnsend = isLikelyNativeDmUnsendScreenBandTap(root, event.rawX, event.rawY)
        val clickView = isLikelyNativeDmUnsendClickView(view)
        if (nativeRow == null && !clickView) {
            if (bandLooksLikeUnsend && now - keepUnsentLastNativeUnsendMissLogAtMs > 1_500L) {
                keepUnsentLastNativeUnsendMissLogAtMs = now
                logInfo(
                    "Observed possible native DM Unsend touch without row hit source=screen-band; awaiting native listener/delete event " +
                        "x=${event.rawX.toInt()} y=${event.rawY.toInt()} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)}"
                )
            }
            return
        }
        keepUnsentLastNativeUnsendMarkAtMs = now
        logInfo(
            "Detected native DM Unsend touch for keep-unsent marker source=${if (nativeRow != null) "row" else "click-view"} " +
                "x=${event.rawX.toInt()} y=${event.rawY.toInt()} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)}"
        )
        markRecentKeepUnsentNativeUnsend(root, event.rawX, event.rawY)
    }

    private fun handleNativeDmUnsendRootInput(event: MotionEvent) {
        if (event.actionMasked == MotionEvent.ACTION_DOWN) {
            return
        }
        if (event.actionMasked != MotionEvent.ACTION_UP || !state.keepUnsentMessages) return
        if (isLikelyLongPressRelease(event)) return
        if (!hasCachedDirectTouchSurface()) return
        val now = System.currentTimeMillis()
        if (now - keepUnsentLastActionRowAtMs !in 0..30_000L) return
        if (now - keepUnsentLastNativeUnsendMarkAtMs < 900L) return
        val root = currentActivity?.window?.decorView ?: return
        if (!isKeepUnsentConversationSurfaceActive(root)) return
        if (!dmMessageActionsOverlayVisible(root) && !hasPurrfectDmActionRowsVisible(root)) return
        val nativeRow = nativeDmUnsendMenuRowAt(root, event.rawX, event.rawY)
        val bandLooksLikeUnsend = isLikelyNativeDmUnsendScreenBandTap(root, event.rawX, event.rawY)
        val geometryLooksLikeUnsend = isLikelyNativeDmUnsendGeometryTap(root, event.rawX, event.rawY)
        if (nativeRow == null) {
            if ((bandLooksLikeUnsend || geometryLooksLikeUnsend) && now - keepUnsentLastNativeUnsendMissLogAtMs > 1_500L) {
                keepUnsentLastNativeUnsendMissLogAtMs = now
                logInfo(
                    "Observed possible native DM Unsend root input without row hit source=${if (geometryLooksLikeUnsend) "geometry" else "screen-band"}; " +
                        "awaiting native listener/delete event x=${event.rawX.toInt()} y=${event.rawY.toInt()} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)}"
                )
            }
            return
        }
        keepUnsentLastNativeUnsendMarkAtMs = now
        logInfo(
            "Detected native DM Unsend root input for keep-unsent marker source=row " +
                "x=${event.rawX.toInt()} y=${event.rawY.toInt()} ids=${formatKeepUnsentIds(keepUnsentLastActionRowIds)}"
        )
        markRecentKeepUnsentNativeUnsend(root, event.rawX, event.rawY)
    }

    private fun isLikelyLongPressRelease(event: MotionEvent): Boolean {
        return event.actionMasked == MotionEvent.ACTION_UP && event.eventTime - event.downTime > 650L
    }

    private fun isDirectMessageSurfaceActive(): Boolean {
        val activity = currentActivity ?: run {
            dmDirectSurfaceActive = false
            dmDirectSurfaceRootRef = null
            dmDirectSurfaceReasonCached = null
            return false
        }
        val root = activity.window?.decorView ?: run {
            dmDirectSurfaceActive = false
            dmDirectSurfaceRootRef = null
            dmDirectSurfaceReasonCached = null
            return false
        }
        val reason = directMessageSurfaceReason(root)
        dmDirectSurfaceActive = reason != null
        logDirectMessageSurfaceDecision(reason, root)
        return dmDirectSurfaceActive
    }

    private fun directMessageSurfaceReason(root: View, forceRefresh: Boolean = false): String? {
        val now = SystemClock.uptimeMillis()
        val cacheTtlMs = if (dmDirectSurfaceReasonCached == null) 1_600L else 520L
        if (!forceRefresh && dmDirectSurfaceRootRef?.get() === root && now - dmDirectSurfaceCheckAtMs < cacheTtlMs) {
            return dmDirectSurfaceReasonCached
        }
        val reason = computeDirectMessageSurfaceReason(root)
        dmDirectSurfaceRootRef = WeakReference(root)
        dmDirectSurfaceCheckAtMs = now
        dmDirectSurfaceReasonCached = reason
        dmDirectSurfaceActive = reason != null
        if (reason != null) {
            scheduleDmSavedStateLongPressGuardInstall("direct-surface:$reason")
        }
        return reason
    }

    private fun hasCachedDirectTouchSurface(maxAgeMs: Long = 1_500L): Boolean {
        val now = SystemClock.uptimeMillis()
        if (dmDirectSurfaceActive && now - dmDirectSurfaceCheckAtMs in 0L..maxAgeMs) return true
        if (dmDirectSurfaceActive && now - dmDirectSurfaceCheckAtMs > maxAgeMs && !dmOverlayRootActive) {
            dmDirectSurfaceActive = false
        }
        if (dmOverlayRootActive) return true
        if (dmDirectSurfaceReasonCached != null && now - dmDirectSurfaceCheckAtMs in 0L..maxAgeMs) return true
        if (dmActiveOverlayVisibleCached && now - dmActiveOverlayCheckAtMs in 0L..maxAgeMs) return true
        if (dmPurrfectRowsVisibleCached && now - dmPurrfectRowsCheckAtMs in 0L..maxAgeMs) return true
        return false
    }

    private fun hasLocalDirectTouchHint(view: View?): Boolean {
        var current = view
        repeat(8) {
            val node = current ?: return false
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (name.contains("direct") ||
                name.contains("message") ||
                name.contains("thread") ||
                name.contains("composer")
            ) {
                return true
            }
            val cls = node.javaClass.name.lowercase(Locale.US)
            if (cls.contains("directthread") ||
                cls.contains(".messagethread.") ||
                cls.contains("direct.thread")
            ) {
                return true
            }
            current = node.parent as? View
        }
        return false
    }

    private data class DirectSurfaceMarkerSnapshot(
        var reels: Boolean = false,
        var threadRoot: Boolean = false,
        var messageList: Boolean = false,
        var threadChrome: Boolean = false,
        var inbox: Boolean = false
    )

    private fun computeDirectMessageSurfaceReason(root: View): String? {
        val markers = directSurfaceMarkerSnapshot(root)
        if (markers.reels) {
            return null
        }
        val decorRoot = currentActivity?.window?.decorView?.rootView
        if (decorRoot != null && decorRoot !== root && directSurfaceMarkerSnapshot(decorRoot).reels) {
            return null
        }
        if (markers.threadRoot) {
            return "direct-thread-root-id"
        }
        if (markers.messageList && markers.threadChrome) return "message-list-with-thread-chrome"
        if (markers.inbox) {
            return "direct-inbox-id"
        }
        if (rootContainsActiveDmMessageActionsOverlay(root) || hasPurrfectDmActionRowsVisible(root)) {
            return "message-actions-id"
        }
        return null
    }

    private fun directSurfaceMarkerSnapshot(root: View?): DirectSurfaceMarkerSnapshot {
        val snapshot = DirectSurfaceMarkerSnapshot()
        if (root == null) return snapshot
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        while (stack.isNotEmpty() && visited++ < 700) {
            val current = stack.removeFirst()
            if (current.visibility != View.VISIBLE) continue
            val name = resourceEntryName(current).orEmpty().lowercase(Locale.US)
            if (!snapshot.reels && isReelsSurfaceIdName(name)) snapshot.reels = true
            if (!snapshot.threadRoot &&
                (name.contains("thread_view_root") ||
                    name.contains("message_thread_container") ||
                    name.contains("direct_thread_content_below_action_bar"))
            ) {
                snapshot.threadRoot = true
            }
            if (!snapshot.messageList && name.contains("message_list")) snapshot.messageList = true
            if (!snapshot.threadChrome &&
                (name.contains("row_thread_composer") ||
                    name.contains("direct_thread_header") ||
                    name.contains("thread_fragment_container"))
            ) {
                snapshot.threadChrome = true
            }
            if (!snapshot.inbox &&
                (name.contains("direct_inbox") ||
                    name.contains("direct_inbox_container") ||
                    name.contains("direct_search"))
            ) {
                snapshot.inbox = true
            }
            if (snapshot.reels &&
                (snapshot.threadRoot || (snapshot.messageList && snapshot.threadChrome) || snapshot.inbox)
            ) {
                break
            }
            if (current is ViewGroup) {
                val count = current.childCount.coerceAtMost(120)
                for (i in 0 until count) stack.add(current.getChildAt(i))
            }
        }
        return snapshot
    }

    private fun isReelsSurfaceIdName(name: String): Boolean =
        name.contains("root_clips_layout") ||
            name.contains("clips_linear_layout_container") ||
            name.contains("clips_viewer") ||
            name.contains("clips_viewer_container") ||
            name.contains("clips_viewer_view_pager") ||
            name.contains("clips_viewer_video_layout") ||
            name.contains("clips_media_component") ||
            name.contains("clips_item_overlay_component") ||
            name.contains("clips_tab")

    private fun hasVisibleReelsSurface(root: View?): Boolean {
        return hasVisibleIdContaining(
            root,
            "root_clips_layout",
            "clips_linear_layout_container",
            "clips_viewer",
            "clips_viewer_container",
            "clips_viewer_view_pager",
            "clips_viewer_video_layout",
            "clips_media_component",
            "clips_item_overlay_component",
            "clips_tab"
        )
    }

    private fun logDirectMessageSurfaceDecision(reason: String?, root: View) {
        val active = reason != null
        val key = if (active) "active:$reason" else "inactive"
        val now = SystemClock.elapsedRealtime()
        if (key == dmDirectSurfaceLastReason && now - dmDirectSurfaceLastLogAtMs < 5_000L) return
        dmDirectSurfaceLastReason = key
        dmDirectSurfaceLastLogAtMs = now
        logInfo("DM surface active=$active reason=${reason ?: "-"} root=${describeViewBrief(root)}")
    }

    private fun noteDirectOutgoingMessageForAutoscroll(uri: URI) {
        if (!isDirectMessageAutoscrollPreventionEnabled()) return
        if (!isDirectTextSendRequest(uri)) return
        armDirectMessageAutoscrollGuard("network")
    }

    private fun isDirectMessageAutoscrollPreventionEnabled(): Boolean {
        return InstagramFeatureStateStore.current.preventDmMessageListAutoscroll
    }

    private fun shouldRunDirectMessageMoveMaintenance(event: MotionEvent): Boolean {
        val now = SystemClock.uptimeMillis()
        val wallNow = System.currentTimeMillis()
        val activeGuard = wallNow <= dmMessageListAutoscrollSuppressUntilMs || wallNow <= dmCustomActionPositionGuardUntilMs
        val intervalMs = if (activeGuard) 64L else 180L
        val movedEnough = abs(event.rawX - dmLastMoveMaintenanceX) >= 14f ||
            abs(event.rawY - dmLastMoveMaintenanceY) >= 14f
        if (!movedEnough && now - dmLastMoveMaintenanceAtMs < intervalMs) return false
        dmLastMoveMaintenanceAtMs = now
        dmLastMoveMaintenanceX = event.rawX
        dmLastMoveMaintenanceY = event.rawY
        return true
    }

    private fun noteDirectMessageListManualScroll(touchedView: View) {
        val list = directMessageListFromTouchPath(touchedView) ?: return
        if (!isDirectMessageSurfaceActive()) return
        val now = System.currentTimeMillis()
        if (now <= dmMessageListAutoscrollSuppressUntilMs &&
            now > dmMessageListUserTouchUntilMs &&
            dmAutoscrollInternalRestore.get() != true
        ) return
        dmMessageListUserScrolledUntilMs = now + 90_000L
        dmMessageListViewRef = WeakReference(list)
        if (now - dmLastListAnchorCaptureAtMs > 120L) {
            dmLastListAnchorCaptureAtMs = now
            captureDirectMessageListAnchor(list)
        }
        if (now - dmLastManualMessageScrollLogAtMs > 2_000L) {
            dmLastManualMessageScrollLogAtMs = now
            logInfo("Direct message list manual scroll noted position=$dmMessageListAnchorPosition offset=$dmMessageListAnchorOffset scrollOffset=$dmMessageListAnchorScrollOffset")
        }
    }

    private fun hookRecyclerAdapterBindViewHolder(recyclerClass: Class<*>) {
        val adapterClass = runCatching { Class.forName("${recyclerClass.name}\$Adapter", false, recyclerClass.classLoader) }.getOrNull()
            ?: recyclerClass.declaredClasses.firstOrNull { it.simpleName == "Adapter" }
            ?: run {
                logInfo("Keep-unsent RecyclerView Adapter class not found for ${recyclerClass.name}")
                return
            }
        runCatching {
            XposedBridge.hookAllMethods(
                adapterClass,
                "bindViewHolder",
                object : XC_MethodHook() {
                    override fun afterHookedMethod(param: MethodHookParam<*>) {
                        if (!state.keepUnsentMessages) return
                        val holder = param.args.firstOrNull() ?: return
                        val rowRoot = findViewHolderRootForKeepUnsent(holder) ?: return
                        if (!isKeepUnsentDirectViewPath(rowRoot)) return
                        val position = param.args.getOrNull(1) as? Int ?: -1
                        maybeBindKeepUnsentRowFromHolder(holder, param.thisObject, position, rowRoot)
                        dmMessageListViewRef?.get()?.let { scanVisibleKeepUnsentRowsAfterListVisible("bindViewHolder", it) }
                    }
                }
            )
            logInfo("Installed keep-unsent RecyclerView bindViewHolder fallback")
        }.onFailure { logError("Failed hooking RecyclerView bindViewHolder for keep-unsent", it) }
    }

    private fun noteDirectMessageListUserTouch(touchedView: View) {
        val list = directMessageListFromTouchPath(touchedView) ?: return
        if (!isDirectMessageSurfaceActive()) return
        dmMessageListUserTouchUntilMs = System.currentTimeMillis() + 1_500L
        dmMessageListViewRef = WeakReference(list)
        scanVisibleKeepUnsentRowsAfterListVisible("list-touch", list)
    }

    private fun releaseDirectMessageAutoscrollForManualScroll(touchedView: View) {
        val list = directMessageListFromTouchPath(touchedView) ?: return
        if (!isDirectMessageSurfaceActive()) return
        releaseDirectMessageAutoscrollForManualScroll(list, "manual-scroll")
    }

    private fun releaseDirectMessageAutoscrollFromTouch(view: View, event: MotionEvent) {
        if (!isDirectMessageSurfaceActive()) return
        val root = view.rootView ?: return
        releaseDirectMessageAutoscrollFromRootTouch(root, event)
    }

    private fun noteDirectMessageListUserTouchFromRoot(root: View?, event: MotionEvent) {
        if (!isDirectMessageSurfaceActive()) return
        val list = directMessageListFromRootTouch(root, event) ?: return
        dmMessageListUserTouchUntilMs = System.currentTimeMillis() + 1_500L
        dmMessageListViewRef = WeakReference(list)
    }

    private fun releaseDirectMessageAutoscrollFromRootTouch(root: View?, event: MotionEvent) {
        if (!isDirectMessageSurfaceActive()) return
        val list = directMessageListFromRootTouch(root, event) ?: return
        releaseDirectMessageAutoscrollForManualScroll(list, "manual-touch")
    }

    private fun directMessageListFromRootTouch(root: View?, event: MotionEvent): View? {
        root ?: return null
        if (root.height <= 0) return null
        val location = IntArray(2)
        root.getLocationOnScreen(location)
        val localY = event.rawY - location[1]
        val cached = dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) }
        if (cached != null) {
            return cached.takeIf { isRawTouchInsideView(it, event) || localY < root.height * 0.74f }
        }
        if (localY < root.height * 0.06f || localY > root.height * 0.82f) return null
        return findDirectMessageListInTree(root)?.takeIf { isRawTouchInsideView(it, event) || localY < root.height * 0.74f }
    }

    private fun hasActiveDirectMessageAutoscrollGuard(): Boolean {
        val now = System.currentTimeMillis()
        return now <= dmMessageListAutoscrollSuppressUntilMs && now <= dmMessageListUserScrolledUntilMs
    }

    private fun isRawTouchInsideView(view: View, event: MotionEvent): Boolean {
        if (!view.isShown || view.width <= 0 || view.height <= 0) return false
        val location = IntArray(2)
        view.getLocationOnScreen(location)
        return event.rawX >= location[0] &&
            event.rawX <= location[0] + view.width &&
            event.rawY >= location[1] &&
            event.rawY <= location[1] + view.height
    }

    private fun releaseDirectMessageAutoscrollForManualScroll(list: View, reason: String) {
        val now = System.currentTimeMillis()
        dmMessageListUserTouchUntilMs = now + 1_500L
        dmMessageListAutoscrollSuppressUntilMs = 0L
        dmCustomActionPositionGuardUntilMs = 0L
        dmMessageListUserScrolledUntilMs = now + 90_000L
        dmMessageListViewRef = WeakReference(list)
        setDirectMessageListLayoutSuppressed(list, false, reason)
        if (now - dmLastListAnchorCaptureAtMs > 120L) {
            dmLastListAnchorCaptureAtMs = now
            captureDirectMessageListAnchor(list)
        }
        if (now - dmLastManualMessageScrollLogAtMs > 1_000L) {
            dmLastManualMessageScrollLogAtMs = now
            logInfo("Direct message list manual scroll released autoscroll guard reason=$reason position=$dmMessageListAnchorPosition offset=$dmMessageListAnchorOffset scrollOffset=$dmMessageListAnchorScrollOffset")
        }
    }

    private fun noteDirectComposerSendClick(view: View) {
        if (!isDirectMessageAutoscrollPreventionEnabled()) return
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        val desc = view.contentDescription?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
        if (!name.contains("send_button") && desc != "send" && !hasVisibleIdContaining(view, "row_thread_composer_send_button")) return
        if (!isDirectMessageSurfaceActive()) return
        armDirectMessageAutoscrollGuard("send-click")
    }

    private fun noteDirectComposerTouch(view: View, event: MotionEvent? = null) {
        if (System.currentTimeMillis() <= dmMessageListUserTouchUntilMs) return
        if (!isDirectComposerView(view) && !isDirectComposerRegionTouch(view, event)) return
        if (!isDirectMessageSurfaceActive()) return
        val list = dmMessageListViewRef?.get() ?: findDirectMessageListInTree(currentActivity?.window?.decorView)
        if (list != null) {
            dmMessageListViewRef = WeakReference(list)
            scanVisibleKeepUnsentRowsAfterListVisible("composer-touch", list)
            captureDirectMessageListAnchor(list)
        }
        armDirectMessageAutoscrollGuard("composer-touch")
    }

    private fun isDirectComposerRegionTouch(view: View, event: MotionEvent?): Boolean {
        val root = view.rootView ?: return false
        val touch = event ?: return false
        if (root.height <= 0 || root.width <= 0) return false
        dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) }?.let { list ->
            if (isRawTouchInsideView(list, touch)) return false
        }
        val location = IntArray(2)
        root.getLocationOnScreen(location)
        val localY = touch.rawY - location[1]
        val localX = touch.rawX - location[0]
        return localY >= root.height * 0.78f && localX >= 0f && localX <= root.width
    }

    private fun armDirectMessageAutoscrollGuard(reason: String) {
        val now = System.currentTimeMillis()
        if (now > dmMessageListUserScrolledUntilMs) {
            dmMessageListUserScrolledUntilMs = now + 90_000L
        }
        val guardMs = when (reason) {
            "composer-touch" -> 1_600L
            "send-click", "network" -> 6_500L
            else -> 4_000L
        }
        dmMessageListAutoscrollSuppressUntilMs = maxOf(dmMessageListAutoscrollSuppressUntilMs, now + guardMs)
        logInfo("Direct message list autoscroll guard armed reason=$reason")
        suppressDirectMessageListLayoutSoon(reason)
        restoreDirectMessageListAnchorSoon(reason)
    }

    private fun shouldBlockDirectMessageAutoscroll(view: View, targetPosition: Int?): Boolean {
        if (!isDirectMessageAutoscrollPreventionEnabled()) return false
        if (dmAutoscrollInternalRestore.get()) return false
        val now = System.currentTimeMillis()
        if (now <= dmMessageListUserTouchUntilMs) return false
        if (now > dmMessageListAutoscrollSuppressUntilMs || now > dmMessageListUserScrolledUntilMs) return false
        if (!isDirectMessageListView(view)) return false
        val count = recyclerAdapterItemCount(view)
        if (now - dmLastAutoscrollBlockAtMs > 1_500L) {
            dmLastAutoscrollBlockAtMs = now
            logInfo("Blocked Direct message list autoscroll target=${targetPosition ?: "delta"} count=$count")
        }
        return true
    }

    private fun recyclerViewFromLayoutManager(layoutManager: Any?): View? {
        if (layoutManager == null) return null
        dmNonStaticFields(layoutManager.javaClass).firstOrNull { field ->
            field.type.name.contains("RecyclerView")
        }?.let { field ->
            return runCatching { field.get(layoutManager) as? View }.getOrNull()
        }
        return null
    }

    private fun isDirectMessageListView(view: View): Boolean {
        if (!view.javaClass.name.contains("RecyclerView")) return false
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        val className = view.javaClass.name.lowercase(Locale.US)
        val maybeDirectList = name == "message_list" ||
            name.contains("message_list") ||
            name.contains("direct") ||
            name.contains("thread") ||
            className.contains("directthread")
        if (!maybeDirectList) return false
        if (!dmDirectSurfaceActive && !isDirectMessageSurfaceActive()) return false
        return name == "message_list" ||
            name.contains("message_list") ||
            hasVisibleIdContaining(view, "message", "direct", "thread")
    }

    private fun recyclerAdapterItemCount(view: View): Int {
        val adapter = runCatching { findDmMethodCached(view.javaClass, "getAdapter")?.invoke(view) }.getOrNull() ?: return -1
        return listOf("getItemCount", "getCount").firstNotNullOfOrNull { name ->
            runCatching { findDmMethodCached(adapter.javaClass, name)?.invoke(adapter) as? Int }.getOrNull()
        } ?: -1
    }

    private fun directMessageListFromTouchPath(view: View): View? {
        var current: View? = view
        repeat(10) {
            val node = current ?: return null
            if (isDirectMessageListView(node)) return node
            current = node.parent as? View
        }
        return null
    }

    private fun findDirectMessageListInTree(root: View?): View? {
        if (root == null) return null
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        while (stack.isNotEmpty() && visited++ < 450) {
            val view = stack.removeFirst()
            if (!view.isShown) continue
            if (isDirectMessageListView(view)) return view
            val group = view as? ViewGroup ?: continue
            for (index in group.childCount - 1 downTo 0) {
                group.getChildAt(index)?.let { stack.add(it) }
            }
        }
        return null
    }

    private fun isDirectComposerView(view: View): Boolean {
        var current: View? = view
        repeat(8) {
            val node = current ?: return false
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            val desc = node.contentDescription?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
            if (node is EditText) return true
            if (name.contains("row_thread_composer") ||
                name.contains("message_composer") ||
                name.contains("composer_edit") ||
                name.contains("direct_text") ||
                desc.contains("message")
            ) {
                return true
            }
            current = node.parent as? View
        }
        return false
    }

    private fun captureDirectMessageListAnchor(list: View) {
        val position = directMessageListFirstVisiblePosition(list)
        if (position < 0) return
        dmMessageListAnchorPosition = position
        dmMessageListAnchorOffset = directMessageListFirstChildOffset(list)
        dmMessageListAnchorScrollOffset = directMessageListVerticalScrollOffset(list)
    }

    private fun captureDmCustomActionPosition(anchor: View?, reason: String): DmListAnchorSnapshot? {
        val list = anchor?.let(::directMessageListFromTouchPath)
            ?: dmMessageListViewRef?.get()?.takeIf { it.isShown && isDirectMessageListView(it) }
            ?: findDirectMessageListInTree(anchor?.rootView ?: currentActivity?.window?.decorView)
            ?: return null
        if (!list.isShown || !isDirectMessageListView(list)) return null
        val position = directMessageListFirstVisiblePosition(list)
        if (position < 0) return null
        val offset = directMessageListFirstChildOffset(list)
        val scrollOffset = directMessageListVerticalScrollOffset(list)
        val now = System.currentTimeMillis()
        dmMessageListViewRef = WeakReference(list)
        dmMessageListAnchorPosition = position
        dmMessageListAnchorOffset = offset
        dmMessageListAnchorScrollOffset = scrollOffset
        dmCustomActionPositionGuardUntilMs = now + 2_000L
        dmMessageListAutoscrollSuppressUntilMs = maxOf(dmMessageListAutoscrollSuppressUntilMs, now + 1_600L)
        dmMessageListUserScrolledUntilMs = maxOf(dmMessageListUserScrolledUntilMs, now + 2_000L)
        logInfoThrottled("dm:action-position-capture:$reason", 750L) {
            "Captured DM list action position reason=$reason position=$position offset=$offset scrollOffset=$scrollOffset list=${describeViewBrief(list)}"
        }
        return DmListAnchorSnapshot(WeakReference(list), position, offset, scrollOffset, now)
    }

    private fun restoreDmCustomActionPosition(snapshot: DmListAnchorSnapshot?, reason: String) {
        if (snapshot == null) return
        val list = snapshot.list.get() ?: return
        if (System.currentTimeMillis() - snapshot.capturedAtMs > DM_CUSTOM_ACTION_RESTORE_MAX_AGE_MS) return
        val restoreDelays = longArrayOf(0L, 90L, 260L, 650L, 1_100L)
        restoreDelays.forEach { delay ->
            val restore = Runnable {
                restoreDmCustomActionScrollOffsetIfNeeded(list, snapshot, "$reason-${delay}ms")
            }
            if (delay == 0L) {
                list.post(restore)
            } else {
                list.postDelayed(restore, delay)
            }
        }
        logInfoThrottled("dm:action-position-restore:$reason", 750L) {
            "Scheduled DM list action position restore reason=$reason " +
                "position=${snapshot.position} offset=${snapshot.offset} scrollOffset=${snapshot.scrollOffset}"
        }
    }

    private fun restoreDmCustomActionScrollOffsetIfNeeded(
        list: View,
        snapshot: DmListAnchorSnapshot,
        reason: String
    ): Boolean {
        if (System.currentTimeMillis() - snapshot.capturedAtMs > DM_CUSTOM_ACTION_RESTORE_MAX_AGE_MS) return false
        if (!list.isShown || !isDirectMessageListView(list)) return false
        val savedScrollOffset = snapshot.scrollOffset
        if (savedScrollOffset < 0) return false
        val currentOffset = directMessageListVerticalScrollOffset(list)
        if (currentOffset < 0) return false
        val delta = savedScrollOffset - currentOffset
        if (abs(delta) < DM_CUSTOM_ACTION_RESTORE_MIN_DELTA_PX) return false
        return runCatching {
            dmAutoscrollInternalRestore.set(true)
            val scrollByMethod = findDmMethodCached(list.javaClass, "scrollBy", Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!)
            if (scrollByMethod != null) {
                scrollByMethod.invoke(list, 0, delta)
            } else {
                list.scrollBy(0, delta)
            }
            logInfoThrottled("dm:action-position-offset-restore:$reason", 750L) {
                "Restored DM list action scroll offset reason=$reason saved=$savedScrollOffset current=$currentOffset delta=$delta " +
                    "position=${snapshot.position} offset=${snapshot.offset}"
            }
            true
        }.onFailure { logError("Direct message action scroll offset restore failed reason=$reason", it) }
            .also { dmAutoscrollInternalRestore.set(false) }
            .getOrDefault(false)
    }

    private fun restoreDirectMessageListAnchorSoon(reason: String) {
        val list = dmMessageListViewRef?.get() ?: return
        val position = dmMessageListAnchorPosition
        val offset = dmMessageListAnchorOffset
        if (position < 0) return
        val delays = when (reason) {
            "composer-touch" -> longArrayOf(0L, 120L, 360L, 900L)
            "send-click", "network" -> longArrayOf(0L, 120L, 360L, 900L, 1_800L, 3_600L, 5_800L)
            else -> longArrayOf(0L, 160L, 480L, 1_000L)
        }
        delays.forEach { delay ->
            if (delay == 0L) {
                list.post { restoreDirectMessageListAnchor(list, position, offset, reason) }
            } else {
                list.postDelayed({ restoreDirectMessageListAnchor(list, position, offset, reason) }, delay)
            }
        }
    }

    private fun suppressDirectMessageListLayoutSoon(reason: String) {
        val list = dmMessageListViewRef?.get() ?: return
        if (!list.isShown || !isDirectMessageListView(list)) return
        val position = dmMessageListAnchorPosition
        val offset = dmMessageListAnchorOffset
        val releaseMs = when (reason) {
            "composer-touch" -> 240L
            "send-click", "network" -> 700L
            else -> 420L
        }
        val safetyMs = releaseMs + 700L
        setDirectMessageListLayoutSuppressed(list, true, reason)
        list.postDelayed({ setDirectMessageListLayoutSuppressed(list, false, "$reason-release") }, releaseMs)
        if (position >= 0) {
            list.postDelayed({ restoreDirectMessageListAnchor(list, position, offset, "$reason-release") }, releaseMs + 40L)
        }
        list.postDelayed({ setDirectMessageListLayoutSuppressed(list, false, "$reason-safety") }, safetyMs)
    }

    private fun setDirectMessageListLayoutSuppressed(list: View, suppressed: Boolean, reason: String) {
        runCatching {
            dmAutoscrollInternalRestore.set(true)
            val method = findDmMethodCached(list.javaClass, "suppressLayout", Boolean::class.javaPrimitiveType!!)
                ?: findDmMethodCached(list.javaClass, "setLayoutFrozen", Boolean::class.javaPrimitiveType!!)
            method?.invoke(list, suppressed)
            val now = System.currentTimeMillis()
            if (now - dmLastLayoutSuppressLogAtMs > 1_500L || !suppressed) {
                dmLastLayoutSuppressLogAtMs = now
                logInfo("Direct message list layout suppressed=$suppressed reason=$reason method=${method?.name ?: "none"}")
            }
        }.onFailure { logError("Direct message list layout suppression failed", it) }
            .also { dmAutoscrollInternalRestore.set(false) }
    }

    private fun restoreDirectMessageListAnchor(list: View, position: Int, offset: Int, reason: String) {
        if (!isDirectMessageAutoscrollPreventionEnabled()) return
        val now = System.currentTimeMillis()
        if (now > dmMessageListAutoscrollSuppressUntilMs || now > dmMessageListUserScrolledUntilMs) return
        if (!list.isShown || !isDirectMessageListView(list)) return
        restoreDirectMessageListAnchorUnchecked(list, position, offset, dmMessageListAnchorScrollOffset, reason)
        if (now - dmLastAutoscrollBlockAtMs > 1_500L) {
            dmLastAutoscrollBlockAtMs = now
            logInfo("Restored Direct message list anchor reason=$reason position=$position offset=$offset scrollOffset=$dmMessageListAnchorScrollOffset current=${directMessageListVerticalScrollOffset(list)}")
        }
    }

    private fun restoreDirectMessageListAnchorUnchecked(
        list: View,
        position: Int,
        offset: Int,
        savedScrollOffset: Int,
        reason: String
    ): Boolean {
        if (!list.isShown || !isDirectMessageListView(list)) return false
        return runCatching {
            dmAutoscrollInternalRestore.set(true)
            val layoutManager = findDmMethodCached(list.javaClass, "getLayoutManager")?.invoke(list)
            val offsetMethod = layoutManager?.let {
                findDmMethodCached(it.javaClass, "scrollToPositionWithOffset", Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!)
            }
            if (offsetMethod != null) {
                offsetMethod.invoke(layoutManager, position, offset)
            } else {
                findDmMethodCached(list.javaClass, "scrollToPosition", Int::class.javaPrimitiveType!!)?.invoke(list, position)
            }
            if (savedScrollOffset >= 0) {
                val currentOffset = directMessageListVerticalScrollOffset(list)
                if (currentOffset >= 0) {
                    val delta = savedScrollOffset - currentOffset
                    if (delta != 0) {
                        findDmMethodCached(list.javaClass, "scrollBy", Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!)
                            ?.invoke(list, 0, delta)
                    }
                }
            }
            true
        }.onFailure { logError("Direct message list anchor restore failed reason=$reason", it) }
            .also { dmAutoscrollInternalRestore.set(false) }
            .getOrDefault(false)
    }

    private fun directMessageListFirstVisiblePosition(list: View): Int {
        val layoutManager = runCatching { findDmMethodCached(list.javaClass, "getLayoutManager")?.invoke(list) }.getOrNull() ?: return -1
        listOf("findFirstVisibleItemPosition", "findFirstCompletelyVisibleItemPosition").forEach { name ->
            runCatching { findDmMethodCached(layoutManager.javaClass, name)?.invoke(layoutManager) as? Int }.getOrNull()?.let { position ->
                if (position >= 0) return position
            }
        }
        return runCatching {
            val method = findDmMethodCached(layoutManager.javaClass, "findFirstVisibleItemPositions", IntArray::class.java)
                ?: return@runCatching -1
            val positions = method.invoke(layoutManager, null) as? IntArray
            positions?.filter { it >= 0 }?.minOrNull() ?: -1
        }.getOrDefault(-1)
    }

    private fun directMessageListFirstChildOffset(list: View): Int {
        val group = list as? ViewGroup ?: return 0
        if (group.childCount <= 0) return 0
        return group.getChildAt(0).top - list.paddingTop
    }

    private fun directMessageListVerticalScrollOffset(list: View): Int {
        return runCatching {
            findDmMethodCached(list.javaClass, "computeVerticalScrollOffset")?.invoke(list) as? Int
        }.getOrNull() ?: -1
    }

    private fun findDmMethodCached(cls: Class<*>, name: String, vararg params: Class<*>): Method? {
        val key = buildString {
            append(cls.name).append('#').append(name).append('(')
            append(params.joinToString(",") { it.name })
            append(')')
        }
        dmRecyclerMethodCache[key]?.let { return it }
        if (dmRecyclerMethodMissingCache.contains(key)) return null
        return runCatching {
            cls.methods.firstOrNull { method ->
                method.name == name &&
                    method.parameterTypes.size == params.size &&
                    method.parameterTypes.zip(params).all { (actual, expected) -> actual == expected }
            }?.apply { isAccessible = true }
        }.getOrNull()?.also { dmRecyclerMethodCache[key] = it }
            ?: run {
                dmRecyclerMethodMissingCache.add(key)
                null
            }
    }

    private fun hasVisibleTextAny(root: View?, targets: Set<String>, limit: Int): Boolean {
        var visited = 0
        fun walk(view: View?): Boolean {
            if (view == null || visited++ > limit || !view.isShown) return false
            if (view is TextView) {
                val text = view.text?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
                if (targets.any { text == it || text.contains(it) }) return true
            }
            val desc = view.contentDescription?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
            if (targets.any { desc == it || desc.contains(it) }) return true
            val group = view as? ViewGroup ?: return false
            for (index in 0 until group.childCount) {
                if (walk(group.getChildAt(index))) return true
            }
            return false
        }
        return walk(root)
    }

    private fun claimDmOverlayAction(action: Int, view: View): Boolean {
        val key = "$action@${System.identityHashCode(view)}"
        val now = System.currentTimeMillis()
        if (dmLastOverlayActionKey == key && now - dmLastOverlayActionAtMs < 900L) {
            logInfo("Ignored duplicate DM overlay action action=${dmActionLabel(action)} view=${describeViewBrief(view)} age=${now - dmLastOverlayActionAtMs}")
            return false
        }
        dmLastOverlayActionKey = key
        dmLastOverlayActionAtMs = now
        logInfo("Claimed DM overlay action action=${dmActionLabel(action)} view=${describeViewBrief(view)} surface=${dmSurfaceForLog()}")
        return true
    }

    private fun runClaimedDmOverlayAction(
        context: Context,
        anchor: View,
        action: Int,
        sources: Array<Any?>,
        resolvedUrl: String?,
        trigger: String
    ) {
        clearDmOverlayGestureDown()
        logInfo(
            "Claimed DM MessageActions overlay $trigger action=${dmActionLabel(action)} voice=${recentDmCustomActionRowVoiceContext() ?: looksLikeVoiceMessageContext(sources, anchor)} " +
                "resolvedUrl=${resolvedUrl != null} anchor=${describeViewBrief(anchor)} sources=${sources.size} surface=${dmSurfaceForLog()}"
        )
        mainHandler.post {
            logInfo(
                "Executing DM overlay action trigger=$trigger action=${dmActionLabel(action)} " +
                    "surface=${dmSurfaceForLog()} guardRemaining=${(dmSavedStateLongPressGuardUntilMs - System.currentTimeMillis()).coerceAtLeast(0L)}ms"
            )
            handleResolvedDmAction(stableDmActionContext(context), null, anchor, action, sources, resolvedUrl, recentDmCustomActionRowVoiceContext())
            restoreDmMessageActionsUiSoon(anchor, sources)
        }
    }

    private fun findTouchedDmOverlayChild(view: View, x: Float, y: Float): View? {
        if (view !is ViewGroup) return view
        for (i in view.childCount - 1 downTo 0) {
            val child = view.getChildAt(i) ?: continue
            if (child.visibility != View.VISIBLE) continue
            val cx = x - child.left + child.scrollX
            val cy = y - child.top + child.scrollY
            if (cx < 0f || cy < 0f || cx > child.width || cy > child.height) continue
            findTouchedDmOverlayChild(child, cx, cy)?.let { return it }
            return child
        }
        return view
    }

    private fun dmActionFromVisibleMenuRowAt(root: View?, rawX: Float, rawY: Float): Pair<Int, View>? {
        if (root == null) return null
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        while (stack.isNotEmpty() && visited++ < 900) {
            val view = stack.removeFirst()
            if (view.visibility != View.VISIBLE || view.width <= 0 || view.height <= 0) continue
            val action = actionFromDmCustomLabel((view as? TextView)?.text?.toString()).takeIf { it >= 0 }
            if (action != null) {
                dmMenuRowContainingPoint(view, rawX, rawY)?.let { return action to it }
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) stack.add(view.getChildAt(i))
            }
        }
        return null
    }

    private fun isLikelyNativeDmUnsendGeometryTap(
        root: View?,
        rawX: Float,
        rawY: Float,
        purrfectRowsVisible: Boolean = hasPurrfectDmActionRowsVisible(root)
    ): Boolean {
        if (!purrfectRowsVisible) return false
        val recentRow = keepUnsentLastActionRowRoot?.get() ?: recentDmMessageActionAnchor() ?: return false
        if (System.currentTimeMillis() - keepUnsentLastActionRowAtMs !in 0..30_000L && recentDmMessageActionAnchor() == null) return false
        if (nearestKeepUnsentRowRoot(recentRow) == null) return false
        val panel = findDmMessageActionsOverlayView(root) ?: return false
        val loc = IntArray(2)
        val hasBounds = runCatching {
            panel.getLocationOnScreen(loc)
            true
        }.getOrDefault(false)
        if (!hasBounds || panel.width <= 0 || panel.height < 900) return false
        val left = loc[0]
        val top = loc[1]
        val right = left + panel.width
        val xOk = rawX >= left + dp(panel, 48) && rawX <= right - dp(panel, 24)
        val yMin = top + (panel.height * 0.78f)
        val yMax = top + (panel.height * 0.88f)
        val yOk = rawY >= yMin && rawY <= yMax
        return xOk && yOk
    }

    private fun isLikelyNativeDmUnsendScreenBandTap(root: View?, rawX: Float, rawY: Float): Boolean {
        val base = root ?: return false
        if (base.width <= 0 || base.height <= 0) return false
        if (!hasRecentKeepUnsentActionRow()) return false
        val loc = IntArray(2)
        val hasBounds = runCatching {
            base.getLocationOnScreen(loc)
            true
        }.getOrDefault(false)
        if (!hasBounds) return false
        val localX = rawX - loc[0]
        val localY = rawY - loc[1]
        val xRatio = localX / base.width.toFloat()
        val yRatio = localY / base.height.toFloat()
        if (xRatio !in 0.32f..0.88f || yRatio !in 0.77f..0.86f) return false
        return true
    }

    private fun isLikelyNativeDmUnsendClickView(view: View): Boolean {
        if (!view.isShown) return false
        var current: View? = view
        var depth = 0
        val combined = StringBuilder()
        val rect = Rect()
        var rowLikeView: View? = null
        while (current != null && depth++ < 8) {
            visibleTextInView(current, 0, combined)
            if (current.getGlobalVisibleRect(rect) && rect.width() >= dp(current, 160) && rect.height() >= dp(current, 44)) {
                rowLikeView = current
            }
            current = current.parent as? View
        }
        if (!combined.toString().split('\n').any { it.trim().equals("unsend", ignoreCase = true) }) return false
        val row = rowLikeView ?: view
        if (!row.getGlobalVisibleRect(rect)) return false
        val root = row.rootView ?: row
        if (root.width <= 0 || root.height <= 0) return false
        val rootLoc = IntArray(2)
        if (!runCatching { root.getLocationOnScreen(rootLoc); true }.getOrDefault(false)) return false
        val xRatio = (rect.centerX() - rootLoc[0]) / root.width.toFloat()
        val yRatio = (rect.centerY() - rootLoc[1]) / root.height.toFloat()
        return xRatio in 0.32f..0.88f && yRatio in 0.78f..0.88f
    }

    private fun hasRecentKeepUnsentActionRow(now: Long = System.currentTimeMillis()): Boolean {
        if (now - keepUnsentLastActionRowAtMs !in 0..30_000L) return false
        val row = keepUnsentLastActionRowRoot?.get()
        return (row != null && nearestKeepUnsentRowRoot(row) != null) ||
            keepUnsentLastActionRowText != null ||
            keepUnsentLastActionRowIds.isNotEmpty()
    }

    private fun nativeDmUnsendMenuRowAt(root: View?, rawX: Float, rawY: Float): View? {
        if (root == null) return null
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        while (stack.isNotEmpty() && visited++ < 900) {
            val view = stack.removeFirst()
            if (view.visibility != View.VISIBLE || view.width <= 0 || view.height <= 0) continue
            val text = when (view) {
                is TextView -> view.text?.toString()
                else -> view.contentDescription?.toString()
            }?.trim()?.lowercase(Locale.US)
            if (text == "unsend") {
                dmMenuRowContainingPoint(view, rawX, rawY)?.let { row ->
                    if (isInsideDmMessageActionsOverlay(row) || rootContainsDmMessageActionsOverlay(row)) return row
                }
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) stack.add(view.getChildAt(i))
            }
        }
        return null
    }

    private fun isNativeDmUnsendMenuRowView(view: View): Boolean {
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 5) {
            val hasUnsend = visibleTextInView(current, 0, StringBuilder())
                .lineSequence()
                .any { it.trim().equals("unsend", ignoreCase = true) }
            if (hasUnsend && (isInsideDmMessageActionsOverlay(current) || rootContainsDmMessageActionsOverlay(current))) return true
            current = current.parent as? View
        }
        return false
    }

    private fun hasPurrfectDmActionRowsVisible(root: View?): Boolean {
        val base = root?.rootView ?: root ?: return false
        val now = SystemClock.uptimeMillis()
        if (dmPurrfectRowsRootRef?.get() === base && now - dmPurrfectRowsCheckAtMs < 160L) {
            return dmPurrfectRowsVisibleCached
        }
        val labels = LinkedHashSet<String>()
        val stack = ArrayDeque<View>()
        stack.add(base)
        var visited = 0
        var visible = false
        while (stack.isNotEmpty() && visited++ < 500) {
            val view = stack.removeFirst()
            if (!view.isShown) continue
            val text = when (view) {
                is TextView -> view.text?.toString()
                else -> view.contentDescription?.toString()
            }?.trim()?.lowercase(Locale.US)
            if (text != null && actionFromDmCustomLabel(text) >= 0) {
                labels += text
                if (isInsideDmMessageActionsOverlay(view) || isLikelyDmActionMenuRoot(view)) {
                    visible = true
                    break
                }
            }
            if (labels.size >= 2 ||
                (labels.isNotEmpty() && isLikelyDmActionMenuRoot(base))
            ) {
                visible = true
                break
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) stack.add(view.getChildAt(i))
            }
        }
        dmPurrfectRowsRootRef = WeakReference(base)
        dmPurrfectRowsCheckAtMs = now
        dmPurrfectRowsVisibleCached = visible
        return visible
    }

    private fun isLikelyDmActionMenuRoot(view: View): Boolean {
        val descriptor = monetViewDescriptor(view)
        return descriptor.contains("popupdecorview") ||
            descriptor.contains("compose_context_menu") ||
            descriptor.contains("message_actions") ||
            descriptor.contains("context_menu")
    }

    private fun findDmMessageActionsOverlayView(root: View?): View? {
        if (root == null) return null
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        var fallback: View? = null
        while (stack.isNotEmpty() && visited++ < 900) {
            val view = stack.removeFirst()
            if (view.visibility != View.VISIBLE || view.width <= 0 || view.height <= 0) continue
            val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
            if (name.contains("message_actions_fragment") || name.contains("message_actions_container")) return view
            if (fallback == null && view.width in 420..900 && view.height in 700..2300 && view.left > 200) fallback = view
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) stack.add(view.getChildAt(i))
            }
        }
        return fallback
    }

    private fun dmMenuRowContainingPoint(labelView: View, rawX: Float, rawY: Float): View? {
        var current: View? = labelView
        var depth = 0
        while (current != null && depth++ < 5) {
            val name = resourceEntryName(current).orEmpty().lowercase(Locale.US)
            if (name.contains("message_actions_fragment") || name.contains("message_actions_container")) return null
            if (viewScreenBoundsContain(current, rawX, rawY) && isDmMenuActionRowSized(current)) return current
            current = current.parent as? View
        }
        return null
    }

    private fun isDmMenuActionRowSized(view: View): Boolean {
        if (view.width <= 0 || view.height <= 0) return false
        val minHeight = dp(view, 36)
        val maxHeight = dp(view, 180)
        val minWidth = dp(view, 120)
        val maxWidth = ((view.rootView ?: view).width * 0.92f).toInt().coerceAtLeast(minWidth)
        return view.height in minHeight..maxHeight && view.width in minWidth..maxWidth
    }

    private fun viewScreenBoundsContain(view: View, rawX: Float, rawY: Float): Boolean {
        if (view.width <= 0 || view.height <= 0) return false
        val loc = IntArray(2)
        return runCatching {
            view.getLocationOnScreen(loc)
            rawX >= loc[0] && rawX <= loc[0] + view.width && rawY >= loc[1] && rawY <= loc[1] + view.height
        }.getOrDefault(false)
    }

    private fun recentDmMessageActionAnchor(maxAgeMs: Long = 15_000L): View? {
        val now = System.currentTimeMillis()
        val effectiveMaxAge = minOf(maxAgeMs, DM_LONG_PRESS_CONTEXT_MAX_AGE_MS)
        val age = now - dmLatestMessageActionAnchorAtMs
        if (age !in 0..effectiveMaxAge) return null
        val longPressAge = now - dmLatestMessageActionLongPressAtMs
        if (longPressAge !in 0..effectiveMaxAge) return null
        val view = dmLatestMessageActionAnchor?.get() ?: return null
        if (!view.isAttachedToWindow || !view.isShown) return null
        return view
    }

    private fun isInsideDmMessageActionsOverlay(view: View): Boolean {
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 16) {
            val name = resourceEntryName(current).orEmpty().lowercase(Locale.US)
            if (name.contains("message_actions_fragment") || name.contains("message_actions_container")) return true
            current = current.parent as? View
        }
        return false
    }

    private fun rootContainsDmMessageActionsOverlay(view: View): Boolean {
        val root = view.rootView ?: return false
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        while (stack.isNotEmpty() && visited++ < 700) {
            val current = stack.removeFirst()
            val name = resourceEntryName(current).orEmpty().lowercase(Locale.US)
            if (name.contains("message_actions_fragment") || name.contains("message_actions_container")) return true
            if (current is ViewGroup) {
                for (i in 0 until current.childCount) stack.add(current.getChildAt(i))
            }
        }
        return false
    }

    private fun rootContainsActiveDmMessageActionsOverlay(view: View): Boolean {
        val root = view.rootView ?: return false
        val now = SystemClock.uptimeMillis()
        if (dmActiveOverlayRootRef?.get() === root && now - dmActiveOverlayCheckAtMs < 160L) {
            return dmActiveOverlayVisibleCached
        }
        val stack = ArrayDeque<View>()
        stack.add(root)
        var visited = 0
        var visible = false
        while (stack.isNotEmpty() && visited++ < 700) {
            val current = stack.removeFirst()
            if (current.visibility != View.VISIBLE || current.width <= 0 || current.height <= 0) continue
            val name = resourceEntryName(current).orEmpty().lowercase(Locale.US)
            if (name.contains("message_actions_container")) {
                visible = current !is ViewGroup || current.childCount > 0
                break
            }
            if (current is ViewGroup) {
                for (i in 0 until current.childCount) stack.add(current.getChildAt(i))
            }
        }
        dmActiveOverlayRootRef = WeakReference(root)
        dmActiveOverlayCheckAtMs = now
        dmActiveOverlayVisibleCached = visible
        return visible
    }

    private fun dmMessageActionsOverlayVisible(view: View): Boolean {
        val root = view.rootView ?: view
        val now = SystemClock.uptimeMillis()
        if (dmOverlayRootRef?.get() === root && now - dmOverlayRootCheckAtMs < 160L) return dmOverlayRootActive
        dmOverlayRootCheckAtMs = now
        dmOverlayRootRef = WeakReference(root)
        val previous = dmOverlayRootActive
        dmOverlayRootActive = rootContainsActiveDmMessageActionsOverlay(root)
        if (previous != dmOverlayRootActive) {
            logInfo(
                "DM MessageActions overlay active changed active=$dmOverlayRootActive " +
                    "root=${describeViewBrief(root)} purrfectRows=${hasPurrfectDmActionRowsVisible(root)}"
            )
        }
        return dmOverlayRootActive
    }

    private fun dmActionFromVisibleMenuRow(view: View): Int? {
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 5) {
            visibleTextInView(current, 0, StringBuilder()).toString()
                .lineSequence()
                .mapNotNull { actionFromDmCustomLabel(it).takeIf { action -> action >= 0 } }
                .firstOrNull()
                ?.let { return it }
            current = current.parent as? View
        }
        return null
    }

    private fun visibleTextInView(view: View?, depth: Int, out: StringBuilder): StringBuilder {
        if (view == null || depth > 4) return out
        if (view is TextView) {
            val text = view.text?.toString().orEmpty().trim()
            if (text.isNotBlank()) out.append(text).append('\n')
        }
        val description = view.contentDescription?.toString().orEmpty().trim()
        if (description.isNotBlank()) out.append(description).append('\n')
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) visibleTextInView(view.getChildAt(i), depth + 1, out)
        }
        return out
    }

    private fun runDmMessageActionAfterDismiss(action: Int, context: Context, view: View?, source: Any?, sources: Array<Any?>?) {
        val url = resolveDmContextUrl(null, view, sources)
        restoreDmMessageActionsUiSoon(source, sources)
        handleResolvedDmAction(stableDmActionContext(context), null, view, action, sources, url, recentDmCustomActionRowVoiceContext())
    }

    private fun runResolvedDmMessageAction(
        action: Int,
        context: Context,
        view: View?,
        sources: Array<Any?>?,
        resolvedUrl: String?
    ) {
        restoreDmMessageActionsUiSoon(null, sources)
        handleResolvedDmAction(stableDmActionContext(context), null, view, action, sources, resolvedUrl, recentDmCustomActionRowVoiceContext())
        restoreDmMessageActionsUiSoon(view, sources)
    }

    private fun handleResolvedDmAction(
        context: Context,
        popup: Any?,
        anchor: View?,
        action: Int,
        sources: Array<Any?>?,
        resolvedUrl: String?,
        forcedVoiceContext: Boolean? = null
    ) {
        val positionSnapshot = captureDmCustomActionPosition(anchor, "action-${dmActionLabel(action)}")
        fun preservePosition() {
            restoreDmCustomActionPosition(positionSnapshot, "action-${dmActionLabel(action)}")
        }
        val voiceContext = forcedVoiceContext ?: looksLikeVoiceMessageContext(sources, anchor)
        val rowSnapshot = recentDmMessageActionMediaSnapshot()
        val rowSnapshotUrls = dmSnapshotUrlsForPreference(rowSnapshot, voiceContext)
        val hasRowSnapshotUrls = rowSnapshotUrls.isNotEmpty()
        val hasPressedRowMediaClaim = rowSnapshot?.visual == true || rowSnapshot?.voice == true || hasRowSnapshotUrls
        val preResolvedCandidate = resolvedUrl?.takeUnless(::looksLikeProfileImageUrl)
        val directResolvedUrl = preResolvedCandidate?.takeIf { candidate ->
            !hasPressedRowMediaClaim || rowSnapshotUrls.contains(candidate)
        }
        if (resolvedUrl != null && preResolvedCandidate == null) {
            logInfo(
                "DM action rejected pre-resolved profile-image URL action=${dmActionLabel(action)} " +
                    "url=${redactCdnUrlForLog(resolvedUrl)}"
            )
        }
        if (preResolvedCandidate != null && directResolvedUrl == null) {
            logInfo(
                "DM action ignored pre-resolved URL outside pressed row action=${dmActionLabel(action)} " +
                    "url=${redactCdnUrlForLog(preResolvedCandidate)} rowTypes=${dmUrlTypesForLog(rowSnapshotUrls)}"
            )
        }
        val visualRowAction = !voiceContext && (rowSnapshot?.visual == true || hasRowSnapshotUrls)
        val needsExpandedUrls = action == DM_ACTION_DOWNLOAD || directResolvedUrl == null || visualRowAction
        val viewModelMediaObject = if (voiceContext || !needsExpandedUrls) {
            null
        } else {
            recentDmMessageActionsViewModel()?.let { findDmMediaObject(null, null, arrayOf(it)) }
        }
        val sourceMediaObject = if (voiceContext || !needsExpandedUrls || viewModelMediaObject != null) {
            null
        } else {
            findDmMediaObjectFromSources(sources)
        }
        val rowControlMediaObject = if (voiceContext || !needsExpandedUrls || viewModelMediaObject != null || sourceMediaObject != null) {
            null
        } else {
            findDmMediaObjectFromTappedRowControls(context, anchor, rowSnapshotUrls + listOfNotNull(directResolvedUrl))
        }
        val controllerMediaObject = if (voiceContext || !needsExpandedUrls || viewModelMediaObject != null || sourceMediaObject != null || rowControlMediaObject != null) {
            null
        } else {
            findDmMediaObjectFromControllerSurfaces()
        }
        val fallbackMediaObject = if (voiceContext || !needsExpandedUrls || hasPressedRowMediaClaim || viewModelMediaObject != null || sourceMediaObject != null || rowControlMediaObject != null || controllerMediaObject != null) {
            null
        } else {
            findDmMediaObject(popup, anchor, sources)
        }
        val mediaObject = viewModelMediaObject ?: sourceMediaObject ?: rowControlMediaObject ?: controllerMediaObject ?: fallbackMediaObject
        val mediaObjectUrls = if (needsExpandedUrls) {
            mediaObject
                ?.let { extractAllMediaDownloadUrls(context, it) }
                .orEmpty()
                .filterNot(::looksLikeProfileImageUrl)
        } else {
            emptyList()
        }
        val sourceCarouselUrls = if (needsExpandedUrls && !voiceContext && hasPressedRowMediaClaim && mediaObjectUrls.size < 2) {
            extractDmCarouselUrlsFromActionSources(context, sources, rowSnapshotUrls + listOfNotNull(directResolvedUrl))
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinct()
        } else {
            emptyList()
        }
        val cachedMediaGroupUrls = if (needsExpandedUrls && !voiceContext && hasPressedRowMediaClaim && (mediaObjectUrls + sourceCarouselUrls + rowSnapshotUrls).size < 3) {
            dmCachedMediaAssetGroupForUrls(mediaObjectUrls + sourceCarouselUrls + rowSnapshotUrls + listOfNotNull(directResolvedUrl))
        } else {
            emptyList()
        }
        val recentCarouselUrls = if (needsExpandedUrls && !voiceContext && hasPressedRowMediaClaim && (mediaObjectUrls + sourceCarouselUrls + cachedMediaGroupUrls + rowSnapshotUrls).size < 3) {
            relatedDmCarouselUrlsFromRecentCache(mediaObjectUrls + sourceCarouselUrls + rowSnapshotUrls + listOfNotNull(directResolvedUrl))
        } else {
            emptyList()
        }
        val mediaInfoUrls = if (needsExpandedUrls && !voiceContext && hasPressedRowMediaClaim && (mediaObjectUrls + sourceCarouselUrls + cachedMediaGroupUrls + recentCarouselUrls + rowSnapshotUrls).size < 3) {
            dmMediaInfoUrlsForActionSources(
                context,
                sources ?: arrayOf(recentDmMessageActionsViewModel()),
                mediaObjectUrls + sourceCarouselUrls + cachedMediaGroupUrls + recentCarouselUrls + rowSnapshotUrls + listOfNotNull(directResolvedUrl),
                "action:${dmActionLabel(action)}"
            )
        } else {
            emptyList()
        }
        val sourceExpandedUrls = if (needsExpandedUrls && !voiceContext && hasPressedRowMediaClaim && (mediaObjectUrls + sourceCarouselUrls + cachedMediaGroupUrls + recentCarouselUrls + mediaInfoUrls).size < 2) {
            findUrlsInDmActionSources(sources, false)
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinct()
        } else {
            emptyList()
        }
        val scopedUrls = if (needsExpandedUrls && !hasPressedRowMediaClaim) {
            resolveDmContextUrls(popup, anchor, sources, voiceContext)
        } else if (needsExpandedUrls && !hasRowSnapshotUrls) {
            findDmUrlInTappedMessageRow(anchor)
                ?.takeIf { dmUrlMatchesAudioPreference(it, voiceContext) }
                ?.let(::listOf)
                .orEmpty()
        } else {
            emptyList()
        }
        val resolvedUrls = if (needsExpandedUrls) {
            (mediaObjectUrls + sourceCarouselUrls + cachedMediaGroupUrls + recentCarouselUrls + mediaInfoUrls + sourceExpandedUrls + rowSnapshotUrls + scopedUrls)
                .filterNot(::looksLikeProfileImageUrl)
                .distinct()
        } else {
            listOfNotNull(directResolvedUrl)
        }
        if (needsExpandedUrls) {
            logInfoThrottled(
                "dm:action-media-detail:${dmActionLabel(action)}:${mediaObject?.javaClass?.name ?: "none"}:${resolvedUrls.size}",
                600L
            ) {
                val sourceTypes = sources
                    ?.take(12)
                    ?.joinToString("|") { it?.javaClass?.name?.substringAfterLast('.') ?: "null" }
                    ?: "-"
                "DM action media detail action=${dmActionLabel(action)} sourceTypes=$sourceTypes " +
                    "direct=${redactCdnUrlForLog(directResolvedUrl ?: "-")} " +
                    "mediaObject=${mediaObject?.javaClass?.name ?: "-"} " +
                    "viewModel=${viewModelMediaObject?.javaClass?.name ?: "-"} source=${sourceMediaObject?.javaClass?.name ?: "-"} " +
                    "rowControl=${rowControlMediaObject?.javaClass?.name ?: "-"} controller=${controllerMediaObject?.javaClass?.name ?: "-"} " +
                    "mediaUrls=${dmUrlsForDiagnosticLog(mediaObjectUrls)} sourceCarousel=${dmUrlsForDiagnosticLog(sourceCarouselUrls)} " +
                    "cachedGroup=${dmUrlsForDiagnosticLog(cachedMediaGroupUrls)} recentCarousel=${dmUrlsForDiagnosticLog(recentCarouselUrls)} " +
                    "mediaInfo=${dmUrlsForDiagnosticLog(mediaInfoUrls)} " +
                    "sourceExpanded=${dmUrlsForDiagnosticLog(sourceExpandedUrls)} " +
                    "rowSnapshot=${dmUrlsForDiagnosticLog(rowSnapshotUrls)} scoped=${dmUrlsForDiagnosticLog(scopedUrls)} " +
                    "resolved=${dmUrlsForDiagnosticLog(resolvedUrls)}"
            }
        }
        if (needsExpandedUrls && mediaObject != null && mediaObjectUrls.isEmpty()) {
            logDmMediaObjectUrlMiss(mediaObject, anchor, sources)
        }
        val fallbackUrl = if (directResolvedUrl == null && resolvedUrls.isEmpty() && !hasPressedRowMediaClaim) {
            resolveDmContextUrl(popup, anchor, sources)?.takeUnless(::looksLikeProfileImageUrl)
        } else {
            null
        }
        val url = directResolvedUrl ?: resolvedUrls.firstOrNull() ?: fallbackUrl
        val actionUrls = (resolvedUrls.ifEmpty { listOfNotNull(url) })
            .filterNot(::looksLikeProfileImageUrl)
            .distinctBy(::dmUrlIdentityForChoice)
        logInfo(
            "DM action resolving action=${dmActionLabel(action)} resolved=${url != null} preResolved=${resolvedUrl != null} " +
                "voiceContext=$voiceContext urlCount=${resolvedUrls.size} types=${dmUrlTypesForLog(resolvedUrls)} " +
                "rowClaim=$hasPressedRowMediaClaim rowSnapshot=${rowSnapshot?.urls?.size ?: 0}:${rowSnapshot?.reason ?: "-"} rowTypes=${dmUrlTypesForLog(rowSnapshotUrls)} " +
                "mediaObject=${mediaObject?.javaClass?.name ?: "-"} mediaUrls=${mediaObjectUrls.size} " +
                "sourceCarouselUrls=${sourceCarouselUrls.size} cachedGroupUrls=${cachedMediaGroupUrls.size} " +
                "recentCarouselUrls=${recentCarouselUrls.size} mediaInfoUrls=${mediaInfoUrls.size} sourceUrls=${sourceExpandedUrls.size} " +
                "viewModelMedia=${viewModelMediaObject != null} sourceMedia=${sourceMediaObject != null} " +
                "rowControlMedia=${rowControlMediaObject != null} " +
                "controllerMedia=${controllerMediaObject != null} " +
                "anchor=${describeViewBrief(anchor)} sources=${sources?.size ?: 0}"
        )
        if (url == null) {
            if (action == DM_ACTION_DOWNLOAD && tryDownloadVoiceFallbackForCurrentMessage(context)) {
                logInfo("DM action ${dmActionLabel(action)} used voice cache fallback after missing URL")
                preservePosition()
                return
            }
            logInfo("DM action ${dmActionLabel(action)} failed: no media URL resolved voiceContext=$voiceContext")
            Toast.makeText(context, "No media found for this message", Toast.LENGTH_SHORT).show()
            preservePosition()
            return
        }
        val isAudio = isAudioUrl(url)
        if (action == DM_ACTION_DOWNLOAD && !isAudio && voiceContext) {
            if (tryDownloadVoiceFallbackForCurrentMessage(context)) {
                logInfo("DM download used voice cache fallback after non-audio URL in voice context url=${redactCdnUrlForLog(url)}")
                preservePosition()
                return
            }
            logInfo("DM download rejected non-audio URL in voice context url=${redactCdnUrlForLog(url)}")
            Toast.makeText(context, "No media found for this message", Toast.LENGTH_SHORT).show()
            preservePosition()
            return
        }
        val isVideo = !isAudio && isVideoMediaUrl(url)
        val reelContext = !voiceContext && !isAudio && looksLikeDmReelContext(sources, anchor, mediaObject)
        val carouselContext = !voiceContext && !isAudio && looksLikeDmCarouselContext(sources, anchor, mediaObject, actionUrls)
        val reelVideo = actionUrls.firstOrNull(::isVideoMediaUrl)
            ?: mediaObject?.let(::bestMediaVideoUrl)
        val reelThumbnail = actionUrls
            .filter { !isVideoMediaUrl(it) && !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .maxWithOrNull(compareBy<String> { parseCdnArea(it) }.thenBy { it.length })
            ?: mediaObject?.let(::bestReelThumbnailUrl)
        logInfo(
            "DM action executing action=${dmActionLabel(action)} audio=$isAudio video=$isVideo " +
                "voiceContext=$voiceContext reel=$reelContext carousel=$carouselContext " +
                "urlCount=${resolvedUrls.size} actionUrls=${actionUrls.size} url=${redactCdnUrlForLog(url)}"
        )
        when (action) {
            DM_ACTION_DOWNLOAD -> {
                val rawDownloadableUrls = resolvedUrls
                    .ifEmpty { listOf(url) }
                    .filterNot(::looksLikeProfileImageUrl)
                    .filter { if (voiceContext || isAudio) isAudioUrl(it) || isLikelyAudioHttpUrl(it) else !isAudioUrl(it) }
                    .distinctBy(::dmUrlIdentityForChoice)
                val normalizedDownloadableUrls = if (carouselContext) {
                    rawDownloadableUrls.distinctBy(::dmUrlIdentityForChoice)
                } else {
                    normalizeDmDownloadUrls(rawDownloadableUrls)
                }
                val chooserUrls = if (carouselContext) {
                    normalizedDownloadableUrls
                } else if (!voiceContext && !isAudio && rawDownloadableUrls.size > normalizedDownloadableUrls.size) {
                    rawDownloadableUrls
                } else {
                    normalizedDownloadableUrls
                }
                logInfo(
                    "DM download candidates raw=${rawDownloadableUrls.size} normalized=${normalizedDownloadableUrls.size} " +
                        "chooser=${chooserUrls.size} rawTypes=${dmUrlTypesForLog(rawDownloadableUrls)} " +
                        "normalizedTypes=${dmUrlTypesForLog(normalizedDownloadableUrls)}"
                )
                val downloadReelVideo = reelVideo ?: chooserUrls.firstOrNull(::isVideoMediaUrl)
                val downloadReelThumbnail = reelThumbnail
                    ?: chooserUrls
                        .filter { !isVideoMediaUrl(it) && !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                        .maxWithOrNull(compareBy<String> { parseCdnArea(it) }.thenBy { it.length })
                if (reelContext && downloadReelVideo != null && downloadReelThumbnail != null) {
                    logInfo(
                        "DM reel download showing video/thumbnail chooser " +
                            "video=${redactCdnUrlForLog(downloadReelVideo)} thumbnail=${redactCdnUrlForLog(downloadReelThumbnail)}"
                    )
                    showDmReelDownloadChoices(context, downloadReelVideo, downloadReelThumbnail, DownloadMetadata(type = "dm_reel"))
                } else if (!voiceContext && !isAudio && chooserUrls.size > 1) {
                    logInfo("DM download showing multi-media chooser count=${chooserUrls.size} types=${dmUrlTypesForLog(chooserUrls)}")
                    showPostDownloadChoices(context, chooserUrls, DownloadMetadata(type = "dm"), 0)
                } else {
                    val selectedUrl = normalizedDownloadableUrls.firstOrNull() ?: chooserUrls.firstOrNull() ?: url
                    logInfo("DM download single candidate selected url=${redactCdnUrlForLog(selectedUrl)}")
                    enqueueDownload(selectedUrl, DownloadMetadata(type = if (isAudio) "dm_voice" else "dm"))
                }
            }
            else -> if (isAudio) {
                logInfo("DM action ${dmActionLabel(action)} blocked because resolved media is audio-only")
                Toast.makeText(context, "Voice messages can only be downloaded", Toast.LENGTH_SHORT).show()
            } else {
                val visualChoices = dmVisualActionChoices(actionUrls, carouselContext)
                if (reelContext && reelVideo != null && reelThumbnail != null) {
                    logInfo(
                        "DM reel action showing video/thumbnail chooser action=${dmActionLabel(action)} " +
                            "video=${redactCdnUrlForLog(reelVideo)} thumbnail=${redactCdnUrlForLog(reelThumbnail)}"
                    )
                    showDmMediaActionChoices(
                        context,
                        action,
                        listOf(
                            DmMediaActionChoice("Reel video", reelVideo, true),
                            DmMediaActionChoice("Thumbnail", reelThumbnail, false)
                        ),
                        anchor,
                        { preservePosition() }
                    )
                    return
                }
                if (visualChoices.size > 1) {
                    logInfo(
                        "DM action showing multi-media chooser action=${dmActionLabel(action)} " +
                            "count=${visualChoices.size} carousel=$carouselContext types=${dmUrlTypesForLog(visualChoices.map { it.url })}"
                    )
                    showDmMediaActionChoices(context, action, visualChoices, anchor) { preservePosition() }
                    return
                }
                val selected = visualChoices.firstOrNull()
                if (selected != null && selected.url != url) {
                    logInfo(
                        "DM action selected richer media URL action=${dmActionLabel(action)} " +
                            "from=${redactCdnUrlForLog(url)} to=${redactCdnUrlForLog(selected.url)}"
                    )
                }
                if (runDmVisualAction(context, action, selected?.url ?: url, selected?.isVideo ?: isVideo, anchor)) {
                    preservePosition()
                    return
                }
            }
        }
        preservePosition()
    }

    private fun resolveDmContextUrl(popup: Any?, explicitAnchor: View?, actionSources: Array<Any?>? = null): String? {
        val anchor = dmPreferredActionAnchor(explicitAnchor, popup)
        val preferAudio = looksLikeVoiceMessageContext(actionSources, anchor)
        if (preferAudio) dmLastVoiceContextAtMs = System.currentTimeMillis()
        dmSnapshotUrlsForPreference(recentDmMessageActionMediaSnapshot(), preferAudio).firstOrNull()?.let {
            logInfo("DM URL resolved from pressed-row snapshot preferAudio=$preferAudio url=${redactCdnUrlForLog(it)}")
            return it
        }
        if (preferAudio) {
            findRecentDmAudioUrl()?.let {
                logInfo("DM URL resolved from recent audio cache url=${redactCdnUrlForLog(it)}")
                return it
            }
            logInfo("DM voice context detected but no audio URL was resolved")
            return null
        }
        findDmUrlInTappedMessageRow(anchor)?.let {
            if (!dmUrlMatchesAudioPreference(it, preferAudio)) {
                logInfo(
                    "DM URL from tapped row rejected for action preference preferAudio=$preferAudio " +
                        "type=${dmUrlTypeForLog(it)} anchor=${describeViewBrief(anchor)}"
                )
                return@let
            }
            logInfo("DM URL resolved from tapped row anchor=${describeViewBrief(anchor)} url=${redactCdnUrlForLog(it)}")
            return it
        }
        findUrlInDmActionSources(actionSources, preferAudio)?.let {
            logInfo("DM URL resolved from action sources preferAudio=$preferAudio url=${redactCdnUrlForLog(it)}")
            return it
        }
        logInfo("DM URL unresolved with tapped/scoped sources anchor=${describeViewBrief(anchor)} sources=${actionSources?.size ?: 0}")
        return null
    }

    private fun findDmMediaObject(popup: Any?, anchor: View?, sources: Array<Any?>?): Any? {
        findDmMediaObjectFromSources(sources)?.let { return it }
        findMediaObject(anchor)?.let {
            logInfoThrottled("dm:media-object:anchor:${it.javaClass.name}", 1_500L) {
                "DM media object resolved from anchor class=${it.javaClass.name}"
            }
            return it
        }
        findMediaObject(anchor?.let(::getViewOnClickListener))?.let {
            logInfoThrottled("dm:media-object:anchor-listener:${it.javaClass.name}", 1_500L) {
                "DM media object resolved from anchor listener class=${it.javaClass.name}"
            }
            return it
        }
        findMediaObject(popup)?.let {
            logInfoThrottled("dm:media-object:popup:${it.javaClass.name}", 1_500L) {
                "DM media object resolved from popup class=${it.javaClass.name}"
            }
            return it
        }
        return null
    }

    private fun findDmMediaObjectFromSources(sources: Array<Any?>?): Any? {
        sources?.forEachIndexed { index, source ->
            findMediaObject(source)?.let {
                logInfoThrottled("dm:media-object:source:$index:${it.javaClass.name}", 1_500L) {
                    "DM media object resolved from source[$index] class=${it.javaClass.name}"
                }
                return it
            }
        }
        return null
    }

    private fun findDmMediaObjectFromTappedRowControls(context: Context, anchor: View?, seedUrls: List<String>): Any? {
        anchor ?: return null
        val started = SystemClock.uptimeMillis()
        val visualSeeds = seedUrls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        val roots = ArrayList<View>(6)
        fun addRoot(view: View?) {
            if (view != null && roots.none { it === view }) roots += view
        }
        addRoot(anchor)
        addRoot(tappedDmMessageActionMediaRow(anchor))
        addRoot(nearestKeepUnsentRowRoot(anchor))
        var current: View? = anchor.parent as? View
        repeat(5) {
            val node = current ?: return@repeat
            if (node.width in 1..1080 && node.height in 1..1_400) addRoot(node)
            if (node.parent?.javaClass?.name?.contains("RecyclerView") == true) return@repeat
            current = node.parent as? View
        }
        val seenViews = Collections.newSetFromMap(IdentityHashMap<View, Boolean>())
        val seenObjects = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        var inspectedViews = 0
        fun inspectObject(source: Any?, reason: String, allowDeep: Boolean = false): Any? {
            if (source == null || !seenObjects.add(source)) return null
            findMediaObjectFast(source)?.let {
                logInfo(
                    "DM media object resolved from tapped-row $reason class=${it.javaClass.name} " +
                        "source=${source.javaClass.name} views=$inspectedViews elapsed=${SystemClock.uptimeMillis() - started}ms"
                )
                return it
            }
            if (allowDeep) {
                val deepStarted = SystemClock.uptimeMillis()
                findMediaObject(source)?.let {
                    logInfo(
                        "DM media object resolved from tapped-row deep $reason class=${it.javaClass.name} " +
                            "source=${source.javaClass.name} views=$inspectedViews " +
                            "deepElapsed=${SystemClock.uptimeMillis() - deepStarted}ms elapsed=${SystemClock.uptimeMillis() - started}ms"
                    )
                    return it
                }
                logInfoThrottled("dm:media-object:deep-miss:$reason:${source.javaClass.name}", 1_500L) {
                    "DM tapped-row deep media miss reason=$reason source=${source.javaClass.name} " +
                        "shape=${dmObjectShapeForLog(source)} deepElapsed=${SystemClock.uptimeMillis() - deepStarted}ms"
                }
            }
            return null
        }
        roots.forEach { root ->
            dmTappedRowModelSources(root).forEach { (reason, source) ->
                inspectObject(source, reason)?.let { return it }
                if (source !is View && visualSeeds.isNotEmpty()) {
                    findDmMediaObjectInAdapterCandidate(context, source, visualSeeds, reason, started)?.let { return it }
                }
                logInfoThrottled("dm:media-object:model-miss:$reason:${source.javaClass.name}", 1_500L) {
                    "DM tapped-row model source had no fast media object reason=$reason " +
                        "class=${source.javaClass.name} shape=${dmObjectShapeForLog(source)} " +
                        "elapsed=${SystemClock.uptimeMillis() - started}ms"
                }
            }
        }
        fun scan(view: View?, depth: Int): Any? {
            if (view == null || depth > 6 || inspectedViews++ > 120 || !seenViews.add(view)) return null
            val highValueMediaControl = isHighValueDmMediaControl(view)
            inspectObject(
                getViewOnClickListener(view),
                "listener:${resourceEntryName(view).orEmpty().ifBlank { view.javaClass.name.substringAfterLast('.') }.take(36)}",
                allowDeep = highValueMediaControl
            )?.let { return it }
            val tagObjects = dmViewTagObjects(view)
            if (tagObjects.isNotEmpty()) {
                logInfoThrottled("dm:row-tags:${describeViewBrief(view)}", 1_200L) {
                    "DM tapped-row view tags view=${describeViewBrief(view)} tags=" +
                        tagObjects.take(8).joinToString("|") { (name, value) ->
                            "$name:${value.javaClass.name.substringAfterLast('.')}"
                        }
                }
            }
            tagObjects.forEach { (name, value) ->
                inspectObject(value, "tag:$name", allowDeep = highValueMediaControl)?.let { return it }
            }
            if (view is ViewGroup) {
                val count = minOf(view.childCount, 32)
                for (index in 0 until count) {
                    scan(view.getChildAt(index), depth + 1)?.let { return it }
                }
            }
            return null
        }
        roots.forEach { root ->
            scan(root, 0)?.let { return it }
        }
        logInfoThrottled("dm:media-object:row-controls-miss:${roots.size}", 1_500L) {
            "DM tapped-row media object miss roots=${roots.size} views=$inspectedViews seeds=${dmUrlsForDiagnosticLog(visualSeeds)} " +
                "elapsed=${SystemClock.uptimeMillis() - started}ms"
        }
        return null
    }

    private fun findDmMediaObjectInAdapterCandidate(
        context: Context,
        source: Any,
        seedUrls: List<String>,
        reason: String,
        startedAtMs: Long
    ): Any? {
        val adapterPosition = reason.substringAfter("adapter:", "").toIntOrNull() ?: return null
        val candidates = dmAdapterNearbyMediaCandidates(source, seedUrls, listOf(adapterPosition))
        if (candidates.isEmpty()) return null
        var best: Pair<String, Any>? = null
        var bestUrls: List<String> = emptyList()
        val debug = ArrayList<String>(12)
        candidates.take(28).forEach { (candidateReason, candidate) ->
            val media = findMediaObjectFast(candidate) ?: findMediaObject(candidate)
            if (media == null) {
                debug += "$candidateReason:${candidate.javaClass.name.substringAfterLast('.')}:no-media"
                return@forEach
            }
            val urls = extractAllMediaDownloadUrls(context, media)
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinctBy(::dmUrlIdentityForChoice)
            val match = dmMediaUrlsMatchSeeds(urls, seedUrls)
            debug += "$candidateReason:${candidate.javaClass.name.substringAfterLast('.')}:media=${media.javaClass.name.substringAfterLast('.')}:urls=${urls.size}:match=$match:fp=${dmCarouselFingerprintsForLog(urls)}"
            if (match && urls.size > bestUrls.size) {
                best = candidateReason to media
                bestUrls = urls
            }
        }
        logInfo(
            "DM adapter media candidate scan reason=$reason candidates=${candidates.size} " +
                "seed=${dmUrlsForDiagnosticLog(seedUrls)} best=${best?.first ?: "-"} bestUrls=${dmUrlsForDiagnosticLog(bestUrls)} " +
                "elapsed=${SystemClock.uptimeMillis() - startedAtMs}ms scan=${debug.take(12).joinToString("|")}"
        )
        best?.let { (candidateReason, media) ->
            logInfo(
                "DM media object resolved from adapter candidate reason=$candidateReason " +
                    "class=${media.javaClass.name} urls=${dmUrlsForDiagnosticLog(bestUrls)} " +
                    "elapsed=${SystemClock.uptimeMillis() - startedAtMs}ms"
            )
            return media
        }
        return null
    }

    private fun dmAdapterNearbyMediaCandidates(adapter: Any, seedUrls: List<String>, indexes: List<Int>): List<Pair<String, Any>> {
        val exactIndexes = indexes.filter { it >= 0 }.distinct().take(4)
        if (exactIndexes.isEmpty()) return emptyList()
        val out = ArrayList<Pair<String, Any>>(32)
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun add(reason: String, value: Any?) {
            if (value == null || value is View || value is Context || value is Activity || isPrimitiveLike(value)) return
            if (!seen.add(value)) return
            out += reason to value
        }
        fun addFromContainer(reason: String, container: Any) {
            exactIndexes.forEach { index ->
                dmIndexedItemFromContainer(container, listOf(index))?.let { add("$reason[$index]", it) }
            }
        }
        arrayOf("getItem", "getItemAt", "getItemAtPosition").forEach { name ->
            exactIndexes.forEach { index ->
                add("$name($index)", invokeOneArgDeep(adapter, name, index))
            }
        }
        var cls: Class<*>? = adapter.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 5 && out.size < 32) {
            dmNonStaticFields(cls).asSequence().take(48).forEach { field ->
                if (out.size >= 32) return@forEach
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                val value = runCatching { field.get(adapter) }.getOrNull() ?: return@forEach
                if (value === adapter || value is View || value is Context || value is Activity) return@forEach
                if (dmContainerSize(value) >= 0) {
                    addFromContainer(field.name, value)
                } else if (!isPrimitiveLike(value)) {
                    add(field.name, value)
                }
            }
            cls = cls.superclass
        }
        logInfoThrottled("dm:adapter-candidates:${adapter.javaClass.name}:${seedUrls.size}", 1_200L) {
            "DM adapter exact-position candidates adapter=${adapter.javaClass.name} indexes=${exactIndexes.joinToString(",")} count=${out.size} " +
                "seed=${dmUrlsForDiagnosticLog(seedUrls)} sample=${out.take(12).joinToString("|") { (reason, value) -> "$reason:${value.javaClass.name.substringAfterLast('.')}" }}"
        }
        return out
    }

    private fun dmMediaUrlsMatchSeeds(urls: List<String>, seeds: List<String>): Boolean {
        if (urls.isEmpty() || seeds.isEmpty()) return false
        val urlIdentities = urls.mapTo(HashSet(), ::dmUrlIdentityForChoice)
        val seedIdentities = seeds.mapTo(HashSet(), ::dmUrlIdentityForChoice)
        if (urlIdentities.any { it in seedIdentities }) return true
        val urlFingerprints = urls.mapNotNull(::dmCarouselCdnFingerprint)
        val seedFingerprints = seeds.mapNotNull(::dmCarouselCdnFingerprint)
        return urlFingerprints.any { urlFp ->
            seedFingerprints.any { seedFp ->
                urlFp.cid == seedFp.cid ||
                    (urlFp.sid == seedFp.sid && urlFp.oc.isNotBlank() && urlFp.oc == seedFp.oc) ||
                    (urlFp.sid == seedFp.sid && urlFp.host == seedFp.host && urlFp.cat == seedFp.cat && urlFp.zt == seedFp.zt)
            }
        }
    }

    private fun isHighValueDmMediaControl(view: View): Boolean {
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        val cls = view.javaClass.name.lowercase(Locale.US)
        val desc = view.contentDescription?.toString()?.lowercase(Locale.US).orEmpty()
        val hay = "$name $cls $desc"
        return hay.contains("xma") ||
            hay.contains("media") ||
            hay.contains("image") ||
            hay.contains("photo") ||
            hay.contains("video") ||
            hay.contains("share") ||
            hay.contains("reel") ||
            hay.contains("carousel") ||
            hay.contains("clips")
    }

    private fun dmViewTagObjects(view: View): List<Pair<String, Any>> {
        val out = ArrayList<Pair<String, Any>>(4)
        runCatching { view.tag }.getOrNull()?.let { out += "default" to it }
        val keyedTags = runCatching {
            val field = View::class.java.getDeclaredField("mKeyedTags").apply { isAccessible = true }
            field.get(view) as? SparseArray<*>
        }.getOrNull()
        if (keyedTags != null) {
            val count = keyedTags.size().coerceAtMost(12)
            for (index in 0 until count) {
                val value = keyedTags.valueAt(index) ?: continue
                out += "key:${keyedTags.keyAt(index)}" to value
            }
        }
        return out.filterNot { (_, value) -> isPrimitiveLike(value) || value is Context || value is View }
    }

    private fun dmTappedRowModelSources(row: View?): List<Pair<String, Any>> {
        row ?: return emptyList()
        val out = ArrayList<Pair<String, Any>>(4)
        var child: View? = row
        var parent = child?.parent
        while (child != null && parent is View) {
            val recycler = parent as View
            if (recycler.javaClass.name.contains("RecyclerView")) {
                val holder = invokeRecyclerChildViewHolder(recycler, child)
                val position = invokeRecyclerChildPosition(recycler, child)
                val childIndex = (recycler as? ViewGroup)?.indexOfChild(child) ?: -1
                val adapter = invokeNoArgDeep(recycler, "getAdapter")
                    ?: invokeNoArgDeep(recycler, "getBindingAdapter")
                if (holder != null) out += "holder" to holder
                val item = adapter?.let { dmAdapterItemAt(it, position) }
                if (item != null) out += "adapter-item" to item
                if (adapter != null && position >= 0) out += "adapter:$position" to adapter
                logInfoThrottled("dm:row-model:${describeViewBrief(row)}", 1_200L) {
                    "DM tapped-row model lookup row=${describeViewBrief(row)} child=${describeViewBrief(child)} " +
                        "recycler=${describeViewBrief(recycler)} position=$position childIndex=$childIndex " +
                        "holder=${holder?.javaClass?.name ?: "-"} adapter=${adapter?.javaClass?.name ?: "-"} " +
                        "item=${item?.javaClass?.name ?: "-"} " +
                        "containers=${adapter?.let { dmAdapterIndexedContainersForLog(it, intArrayOf(position)) } ?: "-"}"
                }
                return out.distinctBy { System.identityHashCode(it.second) }
            }
            child = parent as? View
            parent = child?.parent
        }
        logInfoThrottled("dm:row-model-no-recycler:${describeViewBrief(row)}", 1_500L) {
            "DM tapped-row model lookup skipped: no RecyclerView parent row=${describeViewBrief(row)}"
        }
        return out
    }

    private fun dmAdapterItemAt(adapter: Any, position: Int): Any? {
        val indexes = intArrayOf(position).filter { it >= 0 }.distinct()
        if (indexes.isEmpty()) return null
        arrayOf("getItem", "getItemAt", "getItemAtPosition").forEach { name ->
            indexes.forEach { index ->
                invokeOneArgDeep(adapter, name, index)?.let { return it }
            }
        }
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        var cls: Class<*>? = adapter.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 4) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                val value = runCatching {
                    field.isAccessible = true
                    field.get(adapter)
                }.getOrNull() ?: return@forEach
                if (!seen.add(value)) return@forEach
                dmIndexedItemFromContainer(value, indexes)?.let { return it }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun dmIndexedItemFromContainer(container: Any, indexes: List<Int>): Any? {
        if (indexes.isEmpty()) return null
        when (container) {
            is List<*> -> {
                indexes.forEach { index -> if (index in container.indices) container[index]?.let { return it } }
                return null
            }
            is SparseArray<*> -> {
                indexes.forEach { index -> if (index in 0 until container.size()) container.valueAt(index)?.let { return it } }
                return null
            }
            is Map<*, *> -> {
                val maxIndex = indexes.maxOrNull() ?: return null
                if (maxIndex > 120) return null
                val values = container.values.asSequence().take(maxIndex + 1).toList()
                indexes.forEach { index -> if (index in values.indices) values[index]?.let { return it } }
                return null
            }
            is Iterable<*> -> {
                val maxIndex = indexes.maxOrNull() ?: return null
                if (maxIndex > 120) return null
                val items = container.asSequence().take(maxIndex + 1).toList()
                indexes.forEach { index -> if (index in items.indices) items[index]?.let { return it } }
                return null
            }
            else -> if (container.javaClass.isArray) {
                val length = runCatching { java.lang.reflect.Array.getLength(container) }.getOrDefault(0)
                indexes.forEach { index ->
                    if (index in 0 until length) java.lang.reflect.Array.get(container, index)?.let { return it }
                }
            }
        }
        return null
    }

    private fun dmContainerSize(container: Any): Int {
        return when (container) {
            is Collection<*> -> container.size
            is Map<*, *> -> container.size
            is SparseArray<*> -> container.size()
            is Iterable<*> -> {
                var count = 0
                val iterator = runCatching { container.iterator() }.getOrNull() ?: return -1
                while (count <= 60 && runCatching { iterator.hasNext() }.getOrDefault(false)) {
                    runCatching { iterator.next() }.getOrNull() ?: break
                    count++
                }
                count
            }
            else -> if (container.javaClass.isArray) {
                runCatching { java.lang.reflect.Array.getLength(container) }.getOrDefault(-1)
            } else {
                -1
            }
        }
    }

    private fun dmContainerItemsNoInvoke(container: Any?, limit: Int = 20): List<Any?> {
        if (container == null || limit <= 0) return emptyList()
        return when (container) {
            is List<*> -> container.take(limit)
            is Collection<*> -> container.asSequence().take(limit).toList()
            is Map<*, *> -> container.values.asSequence().take(limit).toList()
            is SparseArray<*> -> {
                val count = minOf(container.size(), limit)
                (0 until count).map { index -> container.valueAt(index) }
            }
            is Iterable<*> -> {
                val out = ArrayList<Any?>(limit)
                val iterator = runCatching { container.iterator() }.getOrNull() ?: return emptyList()
                while (out.size < limit && runCatching { iterator.hasNext() }.getOrDefault(false)) {
                    out += runCatching { iterator.next() }.getOrNull()
                }
                out
            }
            else -> if (container.javaClass.isArray) {
                val count = runCatching { java.lang.reflect.Array.getLength(container) }.getOrDefault(0).coerceAtMost(limit)
                (0 until count).map { index -> java.lang.reflect.Array.get(container, index) }
            } else {
                emptyList()
            }
        }
    }

    private fun dmAdapterIndexedContainersForLog(adapter: Any, rawIndexes: IntArray): String {
        val indexes = rawIndexes.filter { it >= 0 }.distinct()
        if (indexes.isEmpty()) return "no-index"
        val parts = ArrayList<String>(10)
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        var cls: Class<*>? = adapter.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 5 && parts.size < 10) {
            cls.declaredFields.forEach { field ->
                if (parts.size >= 10 || Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                val value = runCatching {
                    field.isAccessible = true
                    field.get(adapter)
                }.getOrNull() ?: return@forEach
                if (!seen.add(value)) return@forEach
                val size = dmContainerSize(value)
                if (size < 0 && value !is Iterable<*>) return@forEach
                val item = dmIndexedItemFromContainer(value, indexes)
                parts += "${field.name}:${value.javaClass.name.substringAfterLast('.')}:size=$size:item=${item?.javaClass?.name?.substringAfterLast('.') ?: "-"}"
            }
            cls = cls.superclass
        }
        return parts.joinToString("|").ifBlank { "none" }
    }

    private fun dmObjectShapeForLog(value: Any): String {
        val parts = ArrayList<String>(14)
        var cls: Class<*>? = value.javaClass
        var depth = 0
        while (cls != null && cls != Any::class.java && depth++ < 3 && parts.size < 14) {
            cls.declaredFields.forEach { field ->
                if (parts.size >= 14 || Modifier.isStatic(field.modifiers) || field.isSynthetic) return@forEach
                val fieldValue = runCatching {
                    field.isAccessible = true
                    field.get(value)
                }.getOrNull()
                val summary = when (fieldValue) {
                    null -> "null"
                    is CharSequence -> "str:${fieldValue.length}"
                    is Number, is Boolean -> fieldValue.toString()
                    is Collection<*> -> "collection:${fieldValue.size}"
                    is Map<*, *> -> "map:${fieldValue.size}"
                    is Array<*> -> "array:${fieldValue.size}"
                    is View -> describeViewBrief(fieldValue)
                    else -> fieldValue.javaClass.name.substringAfterLast('.')
                }
                parts += "${field.name}:${field.type.name.substringAfterLast('.')}=$summary"
            }
            cls = cls.superclass
        }
        return parts.joinToString(",").ifBlank { "-" }
    }

    private fun findDmMediaObjectFromControllerSurfaces(): Any? {
        val candidates = arrayOf(
            dmLatestMessageActionController,
            dmLatestMessageActionLifecycle?.delegateCallback,
            dmLatestMessageActionLifecycle?.chromeCallback,
            dmLatestMessageActionLifecycle?.visibilityCallback
        )
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        val started = SystemClock.uptimeMillis()
        candidates.forEachIndexed { index, candidate ->
            if (candidate == null || !seen.add(candidate)) return@forEachIndexed
            findMediaObjectFast(candidate)?.let {
                logInfo(
                    "DM media object resolved from controller surface[$index] class=${it.javaClass.name} " +
                        "source=${candidate.javaClass.name} elapsed=${SystemClock.uptimeMillis() - started}ms"
                )
                return it
            }
        }
        logInfoThrottled("dm:media-object:controller-miss", 1_500L) {
            "DM controller media object miss candidates=${seen.size} elapsed=${SystemClock.uptimeMillis() - started}ms"
        }
        return null
    }

    private fun resolveDmContextUrls(
        popup: Any?,
        explicitAnchor: View?,
        actionSources: Array<Any?>?,
        preferAudio: Boolean
    ): List<String> {
        dmSnapshotUrlsForPreference(recentDmMessageActionMediaSnapshot(), preferAudio).takeIf { it.isNotEmpty() }?.let {
            logInfo("DM URLs resolved from pressed-row snapshot count=${it.size} preferAudio=$preferAudio types=${dmUrlTypesForLog(it)}")
            return it
        }
        val anchor = dmPreferredActionAnchor(explicitAnchor, popup)
        findDmUrlInTappedMessageRow(anchor)?.let {
            if (!dmUrlMatchesAudioPreference(it, preferAudio)) {
                logInfo(
                    "DM URL from tapped row rejected for list preference preferAudio=$preferAudio " +
                        "type=${dmUrlTypeForLog(it)} anchor=${describeViewBrief(anchor)}"
                )
                return@let
            }
            logInfo("DM URL resolved from tapped row anchor=${describeViewBrief(anchor)} url=${redactCdnUrlForLog(it)}")
            return listOf(it)
        }
        val fromSources = findUrlsInDmActionSources(actionSources, preferAudio)
        if (fromSources.isNotEmpty()) {
            logInfo("DM URLs resolved from action sources count=${fromSources.size} preferAudio=$preferAudio types=${dmUrlTypesForLog(fromSources)}")
            return fromSources
        }
        return emptyList()
    }

    private fun dmPreferredActionAnchor(explicitAnchor: View?, popup: Any?): View? {
        val recent = recentDmMessageActionAnchor(DM_LONG_PRESS_CONTEXT_MAX_AGE_MS)
        if (explicitAnchor == null) return recent ?: popup?.let { dmMenuAnchors[it] }
        val root = explicitAnchor.rootView ?: explicitAnchor
        val overlayScope =
            isInsideDmMessageActionsOverlay(explicitAnchor) ||
                rootContainsDmMessageActionsOverlay(explicitAnchor) ||
                dmMessageActionsOverlayVisible(explicitAnchor) ||
                hasPurrfectDmActionRowsVisible(root)
        return if (recent != null && overlayScope) recent else explicitAnchor
    }

    private fun dmSnapshotUrlsForPreference(snapshot: DmMessageActionMediaSnapshot?, preferAudio: Boolean): List<String> {
        return snapshot?.urls.orEmpty()
            .filterNot(::looksLikeProfileImageUrl)
            .filter { if (preferAudio) isAudioUrl(it) || isLikelyAudioHttpUrl(it) else !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinct()
    }

    private fun dmUrlMatchesAudioPreference(url: String, preferAudio: Boolean): Boolean {
        val audio = isAudioUrl(url) || isLikelyAudioHttpUrl(url)
        return if (preferAudio) audio else !audio
    }

    private fun findDmUrlInTappedMessageRow(anchor: View?): String? {
        if (anchor == null) return null
        val row = tappedDmMessageActionMediaRow(anchor) ?: anchor
        return collectDmUrlInTappedMessageRow(row, 0, intArrayOf(0))
    }

    private fun collectDmUrlInTappedMessageRow(view: View?, depth: Int, visited: IntArray): String? {
        if (view == null || depth > 5 || visited[0]++ > 160) return null
        if (view.visibility != View.VISIBLE || view.width <= 0 || view.height <= 0) return null
        val url = extractMediaUrlFromView(view)
        if (url != null && !looksLikeProfileImageUrl(url)) return url
        if (view is ViewGroup) {
            for (i in 0 until minOf(view.childCount, 24)) {
                val childUrl = collectDmUrlInTappedMessageRow(view.getChildAt(i), depth + 1, visited)
                if (childUrl != null) return childUrl
            }
        }
        return null
    }

    private fun extractMediaUrlFromView(view: View): String? {
        dmImageViewUrls[view]?.takeIf { looksLikeMediaUrl(it) }?.let { return it }
        storyTrayImageUrls[view]?.takeIf { looksLikeMediaUrl(it) }?.let { return it }
        invokeUrlGetter(view, "getTypedUrl")?.let { return it }
        invokeUrlGetter(view, "getTrackingUrl")?.let { return it }
        extractUrlFromView(view)?.takeIf { looksLikeMediaUrl(it) }?.let { return it }
        runCatching {
            view.javaClass.methods
                .filter { it.parameterTypes.isEmpty() && (it.returnType == String::class.java || it.returnType == Uri::class.java) }
                .forEach { method ->
                    method.isAccessible = true
                    val value = method.invoke(view)?.toString()
                    if (value != null && looksLikeMediaUrl(value)) return value
                }
        }
        return null
    }

    private fun distanceBetween(a: View, b: View): Int {
        val aLoc = IntArray(2)
        val bLoc = IntArray(2)
        a.getLocationOnScreen(aLoc)
        b.getLocationOnScreen(bLoc)
        val ax = aLoc[0] + a.width / 2
        val ay = aLoc[1] + a.height / 2
        val bx = bLoc[0] + b.width / 2
        val by = bLoc[1] + b.height / 2
        return kotlin.math.abs(ax - bx) + kotlin.math.abs(ay - by)
    }

    private fun previewDmMedia(context: Context, url: String, isVideo: Boolean, preferredRoot: ViewGroup? = null) {
        val activity = findPreviewHostActivity(context)
        if (activity == null) {
            logInfo(
                "DM preview failed: no host activity context=${context.javaClass.name} " +
                    "current=${currentActivity?.javaClass?.name ?: "-"} stable=${dmLatestStableActionActivity?.get()?.javaClass?.name ?: "-"} " +
                    "fragment=${lastInstagramFragmentActivity?.get()?.javaClass?.name ?: "-"} url=${redactCdnUrlForLog(url)}"
            )
            Toast.makeText(context, "Cannot preview media here", Toast.LENGTH_SHORT).show()
            return
        }
        logInfo(
            "DM preview showing dialog video=$isVideo activity=${activity.javaClass.name} " +
                "preferredRoot=${preferredRoot?.javaClass?.name ?: "none"} " +
                "url=${redactCdnUrlForLog(url)}"
        )
        if (isVideo) showVideoPreview(activity, dmActionLabel(DM_ACTION_PREVIEW), url, preferredRoot)
        else showImagePreview(activity, dmActionLabel(DM_ACTION_PREVIEW), url, preferredRoot)
    }

    private fun scheduleDmMediaPreview(context: Context, url: String, isVideo: Boolean, anchor: View? = null) {
        val rootRef = (anchor?.rootView as? ViewGroup)?.let { WeakReference(it) }
        val stableContext = anchor?.context ?: context
        logInfo(
            "DM preview scheduled dialog video=$isVideo nextFrame=true " +
                "anchor=${anchor?.javaClass?.name ?: "none"} root=${rootRef?.get()?.javaClass?.name ?: "none"} " +
                "url=${redactCdnUrlForLog(url)}"
        )
        mainHandler.post {
            previewDmMedia(stableContext, url, isVideo, rootRef?.get())
        }
    }

    private fun previewDmAudio(context: Context, source: String, preferredRoot: ViewGroup? = null) {
        val activity = findPreviewHostActivity(context)
        if (activity == null) {
            logInfo(
                "DM audio preview failed: no host activity context=${context.javaClass.name} " +
                    "current=${currentActivity?.javaClass?.name ?: "-"} source=${redactCdnUrlForLog(source)}"
            )
            Toast.makeText(context, "Cannot preview voice here", Toast.LENGTH_SHORT).show()
            return
        }
        showAudioPreview(activity, dmActionLabel(DM_ACTION_PREVIEW), source, preferredRoot)
    }

    private fun scheduleDmAudioPreview(context: Context, source: String, anchor: View? = null) {
        val rootRef = (anchor?.rootView as? ViewGroup)?.let { WeakReference(it) }
        val stableContext = anchor?.context ?: context
        logInfo(
            "DM audio preview scheduled nextFrame=true anchor=${anchor?.javaClass?.name ?: "none"} " +
                "root=${rootRef?.get()?.javaClass?.name ?: "none"} source=${redactCdnUrlForLog(source)}"
        )
        mainHandler.post {
            previewDmAudio(stableContext, source, rootRef?.get())
        }
    }

    private fun findPreviewHostActivity(context: Context): Activity? {
        val activity = findActivity(context)
        activity?.takeIf(::isActivityUsable)?.let { return it }
        currentActivity?.takeIf(::isActivityUsable)?.let { return it }
        return null
    }

    private fun normalizeDmDownloadUrls(urls: List<String>): List<String> {
        val filtered = urls
            .filter { looksLikeMediaUrl(it) || isLikelyAudioHttpUrl(it) }
            .filterNot(::looksLikeProfileImageUrl)
            .distinct()
        if (filtered.size <= 1) return filtered
        val videos = filtered.filter(::isVideoMediaUrl)
        val images = filtered.filter { !isVideoMediaUrl(it) && !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
        val audio = filtered.filter { isAudioUrl(it) || isLikelyAudioHttpUrl(it) }
        return buildList {
            if (videos.isNotEmpty()) addAll(videos.distinctBy(::dmUrlIdentityForChoice))
            if (images.isNotEmpty()) addAll(images.distinctBy(::dmUrlIdentityForChoice))
            if (audio.isNotEmpty()) addAll(audio.distinctBy(::dmUrlIdentityForChoice))
        }.ifEmpty { filtered }
    }

    private fun dmUrlIdentityForChoice(url: String): String {
        val path = Uri.parse(url).path.orEmpty()
        return path.substringAfterLast('/').substringBefore('?').substringBeforeLast('.').ifBlank { path }
    }

    private fun dmUrlTypesForLog(urls: List<String>): String =
        urls.take(8).joinToString(prefix = "[", postfix = "]") { dmUrlTypeForLog(it) }

    private fun dmUrlTypeForLog(url: String): String = when {
        isAudioUrl(url) || isLikelyAudioHttpUrl(url) -> "audio"
        isVideoMediaUrl(url) -> "video"
        mimeTypeForUrl(url).startsWith("image") || looksLikeMediaUrl(url) -> "image"
        else -> "unknown"
    }

    private fun dmUrlsForDiagnosticLog(urls: List<String>): String {
        if (urls.isEmpty()) return "0:-"
        val compact = urls
            .take(6)
            .joinToString("|") { "${dmUrlTypeForLog(it)}:${dmUrlIdentityForChoice(it).take(42)}" }
        val fp = dmCarouselFingerprintsForLog(urls)
        return "${urls.size}:$compact fp=$fp"
    }

    private fun collectDmMediaObjectDownloadUrls(media: Any): List<String> {
        val candidates = collectDmMediaObjectUrlCandidates(media)
        if (candidates.isEmpty()) return emptyList()
        val ordered = candidates
            .filterNot { looksLikeProfileImageUrl(it.url) }
            .sortedWith(compareByDescending<MediaUrlCandidate> { it.score }.thenByDescending { it.url.length })
        val videos = ordered.filter { it.video || isVideoMediaUrl(it.url) }
        val images = ordered.filter {
            !it.video && !it.audio && !isVideoMediaUrl(it.url) && !isAudioUrl(it.url) && !isLikelyAudioHttpUrl(it.url)
        }
        val audio = ordered.filter { it.audio || isAudioUrl(it.url) || isLikelyAudioHttpUrl(it.url) }
        val selected = buildList {
            videos.distinctBy { dmUrlIdentityForChoice(it.url) }.forEach { add(it.url) }
            images.distinctBy { dmUrlIdentityForChoice(it.url) }.forEach { add(it.url) }
            audio.distinctBy { dmUrlIdentityForChoice(it.url) }.forEach { add(it.url) }
        }.ifEmpty { ordered.map { it.url }.distinct() }
            .distinct()
            .take(12)
        if (selected.isNotEmpty()) {
            logInfoThrottled("dm:media-object-download:${media.javaClass.name}:${selected.size}", 1_500L) {
                "DM media object reflected download URLs class=${media.javaClass.name} " +
                    "count=${selected.size}/${candidates.size} types=${dmUrlTypesForLog(selected)} " +
                    "top=${ordered.take(4).joinToString(" | ") { "${dmUrlTypeForLog(it.url)}:${it.score}:${it.path.take(72)}" }}"
            }
        }
        return selected
    }

    private fun collectDmMediaObjectUrlCandidates(media: Any?): List<MediaUrlCandidate> {
        if (media == null) return emptyList()
        val candidates = ArrayList<MediaUrlCandidate>(32)
        collectDmObjectUrlCandidates(media, candidates, IdentityHashMap(), 0, "media", 0)
        return candidates
            .filterNot { looksLikeProfileImageUrl(it.url) }
            .distinctBy { it.url }
    }

    private fun logDmMediaObjectUrlMiss(mediaObject: Any, anchor: View?, sources: Array<Any?>?) {
        logInfoThrottled("dm:media-object-url-miss:${mediaObject.javaClass.name}", 1_500L) {
            val fields = dmNonStaticFields(mediaObject.javaClass)
                .take(20)
                .joinToString("|") { "${it.name}:${it.type.name.substringAfterLast('.')}" }
            val methods = dmUrlGetterMethods(mediaObject.javaClass)
                .take(12)
                .joinToString("|") { "${it.name}:${it.returnType.name.substringAfterLast('.')}" }
            val sourceTypes = sources
                ?.take(8)
                ?.joinToString("|") { it?.javaClass?.name?.substringAfterLast('.') ?: "null" }
                ?: "-"
            "DM media object URL miss class=${mediaObject.javaClass.name} " +
                "anchor=${describeViewBrief(anchor)} sources=${sources?.size ?: 0} sourceTypes=$sourceTypes " +
                "fields=$fields getters=$methods"
        }
    }

    private fun showDmReelDownloadChoices(context: Context, videoUrl: String, thumbnailUrl: String, metadata: DownloadMetadata) {
        val activity = findActivity(context) ?: currentActivity
        if (activity == null || activity.isFinishing || activity.isDestroyed) {
            logInfo("DM reel chooser missing host activity; downloading reel video directly")
            enqueueDownload(videoUrl, metadata.copy(type = "dm_reel"))
            return
        }
        logInfo("DM reel chooser showing activity=${activity.javaClass.name}")
        AlertDialog.Builder(activity)
            .setTitle("Download")
            .setItems(arrayOf("Reel video", "Thumbnail")) { _, which ->
                if (which == 0) {
                    logInfo("DM reel chooser selected video url=${redactCdnUrlForLog(videoUrl)}")
                    enqueueDownload(videoUrl, metadata.copy(type = "dm_reel"))
                } else {
                    logInfo("DM reel chooser selected thumbnail url=${redactCdnUrlForLog(thumbnailUrl)}")
                    enqueueDownload(thumbnailUrl, metadata.copy(type = "dm_reel_thumbnail"))
                }
            }
            .show()
    }

    private fun dmVisualActionChoices(urls: List<String>, carouselContext: Boolean): List<DmMediaActionChoice> {
        val visualUrls = urls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .filter { looksLikeMediaUrl(it) || isLikelyInstagramHostedMediaUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        if (visualUrls.isEmpty()) return emptyList()
        val ordered = if (carouselContext) {
            visualUrls
        } else {
            normalizeDmDownloadUrls(visualUrls)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
        }
        return ordered.mapIndexed { index, choiceUrl ->
            val video = isVideoMediaUrl(choiceUrl)
            val label = if (carouselContext) {
                if (video) "Video slide ${index + 1}" else "Slide ${index + 1}"
            } else {
                if (video) "Video ${index + 1}" else "Image ${index + 1}"
            }
            DmMediaActionChoice(label, choiceUrl, video)
        }
    }

    private fun showDmMediaActionChoices(
        context: Context,
        action: Int,
        choices: List<DmMediaActionChoice>,
        anchor: View?,
        preservePosition: () -> Unit
    ) {
        val distinctChoices = choices.distinctBy { dmUrlIdentityForChoice(it.url) }
        if (distinctChoices.isEmpty()) {
            Toast.makeText(context, "No media found for this message", Toast.LENGTH_SHORT).show()
            preservePosition()
            return
        }
        if (distinctChoices.size == 1) {
            val only = distinctChoices.first()
            runDmVisualAction(context, action, only.url, only.isVideo, anchor)
            preservePosition()
            return
        }
        val activity = findActivity(anchor?.context ?: context) ?: findActivity(context) ?: currentActivity
        if (activity == null || activity.isFinishing || activity.isDestroyed) {
            val first = distinctChoices.first()
            logInfo(
                "DM media action chooser missing host; using first action=${dmActionLabel(action)} " +
                    "url=${redactCdnUrlForLog(first.url)}"
            )
            runDmVisualAction(context, action, first.url, first.isVideo, anchor)
            preservePosition()
            return
        }
        val labels = distinctChoices.map { it.label }.toTypedArray()
        preservePosition()
        mainHandler.postDelayed({
            val host = findActivity(anchor?.context ?: context) ?: activity
            if (!isActivityUsable(host)) {
                val first = distinctChoices.first()
                logInfo(
                    "DM media action chooser host became unavailable; using first action=${dmActionLabel(action)} " +
                        "url=${redactCdnUrlForLog(first.url)}"
                )
                runDmVisualAction(context, action, first.url, first.isVideo, anchor)
                preservePosition()
                return@postDelayed
            }
            logInfo(
                "DM media action chooser showing action=${dmActionLabel(action)} " +
                    "count=${distinctChoices.size} activity=${host.javaClass.name}"
            )
            AlertDialog.Builder(host)
                .setTitle(dmActionLabel(action))
                .setItems(labels) { _, which ->
                    val selected = distinctChoices[which.coerceIn(distinctChoices.indices)]
                    logInfo(
                        "DM media action chooser selected action=${dmActionLabel(action)} label=${selected.label} " +
                            "video=${selected.isVideo} url=${redactCdnUrlForLog(selected.url)}"
                    )
                    runDmVisualAction(host, action, selected.url, selected.isVideo, anchor, allowModalDefer = false)
                    preservePosition()
                }
                .show()
        }, 260L)
    }

    private fun runDmVisualAction(
        context: Context,
        action: Int,
        url: String,
        isVideo: Boolean,
        anchor: View?,
        allowModalDefer: Boolean = true
    ): Boolean {
        val video = isVideo || isVideoMediaUrl(url)
        logInfo(
            "DM visual action dispatch action=${dmActionLabel(action)} video=$video " +
                "allowModalDefer=$allowModalDefer url=${redactCdnUrlForLog(url)}"
        )
        when (action) {
            DM_ACTION_OPEN_APPS -> openDmMediaByPhoneApps(context, url, video)
            DM_ACTION_PREVIEW -> {
                if (allowModalDefer && maybeDeferDmModalAction(context, action, url)) return true
                scheduleDmMediaPreview(context, url, video, anchor)
            }
            DM_ACTION_REPOST -> {
                if (allowModalDefer && maybeDeferDmModalAction(context, action, url)) return true
                shareDmMediaToPackage(context, url, video, context.packageName, "Share failed")
            }
            DM_ACTION_WHATSAPP_STORY -> {
                if (allowModalDefer && maybeDeferDmModalAction(context, action, url)) return true
                shareDmMediaToWhatsAppStory(context, url, video)
            }
            else -> return false
        }
        return true
    }

    private fun looksLikeDmReelContext(sources: Array<Any?>?, anchor: View?, mediaObject: Any? = null): Boolean {
        val tokens = arrayOf(
            "clips",
            "clips_media",
            "clips_share",
            "directreel",
            "direct_reel",
            "reel_share",
            "xdtclips"
        )
        val anchorHit = anchor?.let { viewContainsAnyToken(it, tokens) } == true
        val sourceHit = sources?.any { objectContainsAnyToken(it, tokens, IdentityHashMap(), 0) } == true
        val mediaHit = mediaObject?.let { objectContainsAnyToken(it, tokens, IdentityHashMap(), 0) } == true
        if (anchorHit || sourceHit || mediaHit) {
            logInfo(
                "DM reel context detected anchorHit=$anchorHit sourceHit=$sourceHit mediaHit=$mediaHit " +
                    "anchor=${describeViewBrief(anchor)} sources=${sources?.size ?: 0}"
            )
        }
        return anchorHit || sourceHit || mediaHit
    }

    private fun looksLikeReelMediaObject(mediaObject: Any?): Boolean {
        val tokens = arrayOf(
            "clips",
            "clips_media",
            "clips_share",
            "directreel",
            "direct_reel",
            "reel_share",
            "xdtclips"
        )
        return mediaObject?.let { objectContainsAnyToken(it, tokens, IdentityHashMap(), 0) } == true
    }

    private fun looksLikeDmCarouselContext(sources: Array<Any?>?, anchor: View?, mediaObject: Any?, urls: List<String>): Boolean {
        val tokens = arrayOf(
            "carousel",
            "carousel_media",
            "carousel_item",
            "sidecar",
            "album",
            "album_media",
            "child_media",
            "childmedias",
            "slides"
        )
        val anchorHit = anchor?.let { viewContainsAnyToken(it, tokens) } == true
        val sourceHit = sources?.any { objectContainsAnyToken(it, tokens, IdentityHashMap(), 0) } == true
        val mediaHit = mediaObject?.let { objectContainsAnyToken(it, tokens, IdentityHashMap(), 0) } == true
        val urlHit = urls
            .filterNot(::looksLikeProfileImageUrl)
            .count { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) } >= 2
        if (anchorHit || sourceHit || mediaHit || urlHit) {
            logInfo(
                "DM carousel context detected anchorHit=$anchorHit sourceHit=$sourceHit mediaHit=$mediaHit urlHit=$urlHit " +
                    "count=${urls.size} types=${dmUrlTypesForLog(urls)} anchor=${describeViewBrief(anchor)} sources=${sources?.size ?: 0}"
            )
        }
        return anchorHit || sourceHit || mediaHit || urlHit
    }

    private fun looksLikeCarouselMediaObject(mediaObject: Any?): Boolean {
        if (mediaObject == null) return false
        if (mediaClass?.isInstance(mediaObject) == true) {
            return true
        }
        val clazz = mediaObject.javaClass
        if (clazz.declaredFields.any { it.type == java.util.List::class.java } &&
            clazz.declaredFields.any { it.type == java.lang.String::class.java } &&
            clazz.declaredFields.count() > 20) {
            return true
        }
        val tokens = arrayOf(
            "carousel",
            "carousel_media",
            "carousel_item",
            "sidecar",
            "album",
            "album_media",
            "child_media",
            "childmedias",
            "slides"
        )
        return mediaObject?.let { objectContainsAnyToken(it, tokens, IdentityHashMap(), 0) } == true
    }

    private fun looksLikeCarouselName(name: String?): Boolean {
        val lower = name?.lowercase(Locale.US) ?: return false
        return lower.contains("carousel") ||
            lower.contains("sidecar") ||
            lower.contains("album") ||
            lower.contains("childmedia") ||
            lower.contains("child_media") ||
            lower.contains("slides")
    }

    private fun viewContainsAnyToken(anchor: View, tokens: Array<String>): Boolean {
        var current: View? = anchor
        var depth = 0
        while (current != null && depth++ < 8) {
            val resourceName = resourceEntryName(current).orEmpty()
            val className = current.javaClass.name
            val tagText = current.tag?.toString().orEmpty().take(240)
            val contentText = current.contentDescription?.toString().orEmpty().take(240)
            if (tokens.any { token ->
                    resourceName.contains(token, ignoreCase = true) ||
                        className.contains(token, ignoreCase = true) ||
                        tagText.contains(token, ignoreCase = true) ||
                        contentText.contains(token, ignoreCase = true)
                }
            ) {
                return true
            }
            current = current.parent as? View
        }
        return false
    }

    private fun objectContainsAnyToken(
        value: Any?,
        tokens: Array<String>,
        seen: IdentityHashMap<Any, Boolean>,
        depth: Int
    ): Boolean {
        if (value == null || depth > 4) return false
        when (value) {
            is CharSequence -> return tokens.any { value.contains(it, ignoreCase = true) }
            is Uri -> return tokens.any { value.toString().contains(it, ignoreCase = true) }
            is View -> return viewContainsAnyToken(value, tokens)
        }
        val cls = value.javaClass
        if (tokens.any { cls.name.contains(it, ignoreCase = true) }) return true
        if (isSimpleDmUrlValue(cls) || shouldSkipDmUrlObject(value, cls) || seen.containsKey(value)) return false
        seen[value] = true

        if (cls.isArray) {
            val length = java.lang.reflect.Array.getLength(value).coerceAtMost(24)
            for (i in 0 until length) {
                if (objectContainsAnyToken(java.lang.reflect.Array.get(value, i), tokens, seen, depth + 1)) return true
            }
            return false
        }

        if (value is Iterable<*>) {
            var index = 0
            for (item in value) {
                if (index++ >= 24) break
                if (objectContainsAnyToken(item, tokens, seen, depth + 1)) return true
            }
            return false
        }

        if (value is Map<*, *>) {
            var index = 0
            for ((key, item) in value) {
                if (index++ >= 24) break
                if (objectContainsAnyToken(key, tokens, seen, depth + 1)) return true
                if (objectContainsAnyToken(item, tokens, seen, depth + 1)) return true
            }
            return false
        }

        dmNonStaticFields(cls).asSequence().take(80).forEach { field ->
            if (tokens.any { field.name.contains(it, ignoreCase = true) || field.type.name.contains(it, ignoreCase = true) }) {
                return true
            }
            if (!shouldInspectDmUrlFields(field.type)) return@forEach
            runCatching {
                if (objectContainsAnyToken(field.get(value), tokens, seen, depth + 1)) return true
            }
        }
        return false
    }

    private fun findUrlInDmActionSources(actionSources: Array<Any?>?, preferAudio: Boolean): String? {
        return findUrlsInDmActionSources(actionSources, preferAudio).firstOrNull()
    }

    private fun findUrlsInDmActionSources(actionSources: Array<Any?>?, preferAudio: Boolean): List<String> {
        if (actionSources.isNullOrEmpty()) return emptyList()
        val candidates = mutableListOf<MediaUrlCandidate>()
        val seen = IdentityHashMap<Any, Boolean>()
        actionSources.forEach { source ->
            collectDmObjectUrlCandidates(source, candidates, seen, 0, "arg", 0)
        }
        val filtered = candidates
            .filter { if (preferAudio) it.audio || isLikelyAudioHttpUrl(it.url) else !it.audio }
            .let { list -> if (list.isNotEmpty()) list else if (preferAudio) candidates.filter { !it.video && !mimeTypeForUrl(it.url).startsWith("image") } else list }
            .sortedWith(compareByDescending<MediaUrlCandidate> { it.score }.thenByDescending { it.url.length })
        val urls = filtered
            .map { it.url }
            .filterNot(::looksLikeProfileImageUrl)
            .distinct()
            .take(12)
        urls.forEach { found ->
            if (isAudioUrl(found) || isLikelyAudioHttpUrl(found)) rememberKnownDmAudioUrl(found)
            rememberMediaUrl(found, directFallback = true)
        }
        if (urls.isNotEmpty()) {
            logInfo(
                "DM URL candidates selected count=${urls.size}/${candidates.size} preferAudio=$preferAudio " +
                    "top=${filtered.take(5).joinToString(" | ") { "${dmUrlTypeForLog(it.url)}:${it.score}:${it.path.take(80)}" }}"
            )
        }
        return urls
    }

    private fun extractDmCarouselUrlsFromActionSources(
        context: Context,
        actionSources: Array<Any?>?,
        seedUrls: List<String> = emptyList()
    ): List<String> {
        if (actionSources.isNullOrEmpty()) return emptyList()
        initMediaDownloadReflection()
        val seen = IdentityHashMap<Any, Boolean>()
        val debug = ArrayList<String>(16)
        actionSources.take(16).forEachIndexed { index, source ->
            val candidate = source ?: return@forEachIndexed
            if (candidate is View || candidate is Context || candidate is Activity || seen.containsKey(candidate)) {
                debug += "$index:${candidate.javaClass.name.substringAfterLast('.')}:skipped"
                return@forEachIndexed
            }
            val sourceSkipReason = dmCarouselActionSourceSkipReason(candidate)
            if (sourceSkipReason != null) {
                debug += "$index:${candidate.javaClass.name.substringAfterLast('.')}:skip=$sourceSkipReason"
                return@forEachIndexed
            }
            seen[candidate] = true
            val urls = extractCarouselMediaDownloadUrls(context, candidate)
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinctBy(::dmUrlIdentityForChoice)
                .take(12)
            val directMatch = seedUrls.isEmpty() || dmMediaUrlsMatchSeeds(urls, seedUrls)
            debug += "$index:${candidate.javaClass.name.substringAfterLast('.')}:direct=${urls.size}:match=$directMatch:${dmCarouselFingerprintsForLog(urls)}"
            if (urls.size >= 2 && directMatch) {
                logInfo(
                    "DM carousel URLs resolved from action source[$index] class=${candidate.javaClass.name} " +
                        "count=${urls.size} types=${dmUrlTypesForLog(urls)} carouselFp=${dmCarouselFingerprintsForLog(urls)}"
                )
                rememberDmMediaAssetGroup(urls, "dm-action-source:${candidate.javaClass.name.substringAfterLast('.')}")
                return urls
            }
            val genericSkipReason = dmGenericCarouselSourceSkipReason(candidate, seedUrls)
            if (genericSkipReason != null) {
                debug += "$index:${candidate.javaClass.name.substringAfterLast('.')}:generic-skip=$genericSkipReason:${dmGenericCarouselSourceSignalForLog(candidate)}"
                return@forEachIndexed
            }
            val genericUrls = extractDmGenericCarouselUrlsFromObjectGraph(context, candidate, seedUrls)
            debug += "$index:${candidate.javaClass.name.substringAfterLast('.')}:generic=${genericUrls.size}:${dmCarouselFingerprintsForLog(genericUrls)}"
            if (genericUrls.size >= 2) {
                logInfo(
                    "DM carousel URLs resolved from generic action source[$index] class=${candidate.javaClass.name} " +
                        "count=${genericUrls.size} types=${dmUrlTypesForLog(genericUrls)} carouselFp=${dmCarouselFingerprintsForLog(genericUrls)}"
                )
                rememberDmMediaAssetGroup(genericUrls, "dm-action-generic:${candidate.javaClass.name.substringAfterLast('.')}")
                return genericUrls
            }
        }
        logInfoThrottled("dm:carousel-source-miss:${actionSources.size}", 1_500L) {
            val sourceTypes = actionSources
                .take(10)
                .joinToString("|") { it?.javaClass?.name?.substringAfterLast('.') ?: "null" }
            "DM carousel source extraction miss sources=${actionSources.size} sourceTypes=$sourceTypes " +
                "scan=${debug.take(10).joinToString("|")} shareHints=${dmSharedPostHintsForLog(actionSources)}"
        }
        logInfoThrottled("dm:carousel-source-diagnostics:${actionSources.size}", 1_500L) {
            "DM carousel source diagnostics ${dmActionSourceDiagnosticsForLog(actionSources)}"
        }
        logInfoThrottled("dm:carousel-source-deep-hints:${actionSources.size}", 1_500L) {
            "DM carousel source deep hints ${dmCarouselSourceDeepHintsForLog(actionSources, seedUrls)}"
        }
        return emptyList()
    }

    private fun dmCarouselActionSourceSkipReason(candidate: Any): String? {
        val cls = candidate.javaClass
        val lowerName = cls.name.lowercase(Locale.US)
        val hardSkip = arrayOf(
            "usersession",
            "directthreadanalytics",
            "analytics",
            "logger",
            "logging",
            "fragment",
            "activity",
            "controller",
            "adapter",
            "recyclerview",
            "layoutmanager",
            "drawable",
            "bitmap",
            "coroutine",
            "executor",
            "handler",
            "looper"
        )
        hardSkip.firstOrNull { lowerName.contains(it) }?.let { return "class:$it" }
        if (!shouldInspectObject(cls) || shouldSkipDmUrlObject(candidate, cls)) return "object"
        val shape = dmObjectShapeForLog(candidate)
        val lowerShape = shape.lowercase(Locale.US)
        val runtimeShape = lowerShape.contains("usersession=") ||
            lowerShape.contains("activity=") ||
            lowerShape.contains("fragmentactivity=") ||
            lowerShape.contains("context=") ||
            lowerShape.contains("view\$") ||
            lowerShape.contains("view=") ||
            lowerShape.contains("adapter=")
        val hasSignal = dmHasShallowCarouselMediaSignal(candidate, shape)
        if (runtimeShape && !hasSignal) return "shape:runtime"
        if (!hasSignal) return "shape:no-media-signal"
        return null
    }

    private fun dmGenericCarouselSourceSkipReason(candidate: Any, seedUrls: List<String>): String? {
        val seedVisuals = seedUrls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        if (seedVisuals.isEmpty()) return "no-seed"
        val shape = dmObjectShapeForLog(candidate)
        val hasSignal = dmHasShallowCarouselMediaSignal(candidate, shape)
        if (!hasSignal) return "no-shallow-media-signal"
        return null
    }

    private fun dmHasShallowCarouselMediaSignal(candidate: Any, shape: String = dmObjectShapeForLog(candidate)): Boolean {
        val lowerName = candidate.javaClass.name.lowercase(Locale.US)
        val lowerShape = shape.lowercase(Locale.US)
        val tokens = arrayOf(
            "imageurl",
            "image_url",
            "mediaurl",
            "media_url",
            "video",
            "thumbnail",
            "carousel",
            "sidecar",
            "album",
            "xma",
            "share",
            "post",
            "reel",
            "clips",
            "direct"
        )
        if (tokens.any { lowerName.contains(it) || lowerShape.contains(it) }) return true
        var cls: Class<*>? = candidate.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 2) {
            dmNonStaticFields(cls).asSequence().take(28).forEach { field ->
                val fieldName = field.name.lowercase(Locale.US)
                val typeName = field.type.name.lowercase(Locale.US)
                if (tokens.any { fieldName.contains(it) || typeName.contains(it) }) return true
                runCatching { urlFromTypedObject(field.get(candidate)) }.getOrNull()?.let { return true }
            }
            cls = cls.superclass
        }
        return false
    }

    private fun dmImmediateCarouselContainerHint(candidate: Any): Int {
        var hints = 0
        var cls: Class<*>? = candidate.javaClass
        var classDepth = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 2 && hints < 3) {
            dmNonStaticFields(cls).asSequence().take(28).forEach { field ->
                if (hints >= 3 || field.type.isPrimitive || field.type == String::class.java) return@forEach
                val value = runCatching { field.get(candidate) }.getOrNull() ?: return@forEach
                val size = dmContainerSize(value)
                if (size in 2..20) hints++
            }
            cls = cls.superclass
        }
        return hints
    }

    private fun dmGenericCarouselSourceSignalForLog(candidate: Any): String {
        val shape = dmObjectShapeForLog(candidate)
        val tokens = arrayOf("imageurl", "media", "video", "carousel", "sidecar", "album", "xma", "share", "post", "reel", "clips", "direct")
        val hay = "${candidate.javaClass.name} $shape".lowercase(Locale.US)
        val hits = tokens.filter { hay.contains(it) }.take(5).joinToString(",").ifBlank { "-" }
        return "signals=$hits containers=${dmImmediateCarouselContainerHint(candidate)} shape=${shape.take(160)}"
    }

    private fun extractDmGenericCarouselUrlsFromObjectGraph(
        context: Context,
        root: Any?,
        seedUrls: List<String>
    ): List<String> {
        if (root == null || root is View || root is Context || root is Activity) return emptyList()
        val started = SystemClock.uptimeMillis()
        val maxElapsedMs = 70L
        val seedVisuals = seedUrls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        if (seedVisuals.isEmpty()) return emptyList()
        val seen = IdentityHashMap<Any, Boolean>()
        val candidates = ArrayList<List<String>>(4)
        var objects = 0
        var fields = 0
        var budgetStop = "-"

        fun overBudget(reason: String): Boolean {
            if (budgetStop != "-") return true
            val elapsed = SystemClock.uptimeMillis() - started
            if (elapsed > maxElapsedMs) {
                budgetStop = "time:$elapsed"
                return true
            }
            when (reason) {
                "objects" -> if (objects >= 80) {
                    budgetStop = "objects:$objects"
                    return true
                }
                "fields" -> if (fields >= 260) {
                    budgetStop = "fields:$fields"
                    return true
                }
            }
            return false
        }

        fun maybeAccept(reason: String, items: List<Any?>): Boolean {
            if (overBudget("time")) return candidates.isNotEmpty()
            if (items.size !in 2..20) return false
            val mediaLikeItems = items.asSequence()
                .filterNotNull()
                .take(8)
                .count { item ->
                    when (item) {
                        is String -> looksLikeMediaUrl(item) && !looksLikeProfileImageUrl(item)
                        is Uri -> item.toString().let { looksLikeMediaUrl(it) && !looksLikeProfileImageUrl(it) }
                        is CharSequence, is Number, is Boolean, is Enum<*> -> false
                        else -> dmHasShallowCarouselMediaSignal(item, dmObjectShapeForLog(item))
                    }
                }
            if (mediaLikeItems == 0) {
                logInfoThrottled("dm:generic-carousel-list-skip:${root.javaClass.name}:$reason", 1_500L) {
                    "DM generic carousel list skipped reason=$reason root=${root.javaClass.name} " +
                        "items=${items.size} itemTypes=${items.take(5).joinToString("|") { it?.javaClass?.name?.substringAfterLast('.') ?: "null" }} " +
                        "elapsed=${SystemClock.uptimeMillis() - started}ms"
                }
                return false
            }
            val urls = carouselUrlsFromItems(context, items)
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinctBy(::dmUrlIdentityForChoice)
                .take(12)
            if (urls.size < 2 || !dmMediaUrlsMatchSeeds(urls, seedVisuals)) return false
            candidates += urls
            logInfoThrottled("dm:generic-carousel-candidate:${root.javaClass.name}:${reason}:${urls.size}", 1_500L) {
                "DM generic carousel candidate reason=$reason root=${root.javaClass.name} count=${urls.size} " +
                    "types=${dmUrlTypesForLog(urls)} fp=${dmCarouselFingerprintsForLog(urls)} " +
                    "elapsed=${SystemClock.uptimeMillis() - started}ms"
            }
            return true
        }

        fun containerItems(value: Any?): List<Any?> {
            if (value == null) return emptyList()
            val items = dmContainerItemsNoInvoke(value, 20)
            return if (items.size in 2..20) items else emptyList()
        }

        fun scan(value: Any?, depth: Int, path: String): Boolean {
            if (value == null || depth > 4 || candidates.size >= 2) return candidates.isNotEmpty()
            if (overBudget("time") || overBudget("objects") || overBudget("fields")) return candidates.isNotEmpty()
            objects++
            if (value is View || value is Context || value is Activity) return false
            when (value) {
                is CharSequence, is Uri, is Number, is Boolean, is Enum<*> -> return false
            }
            val items = containerItems(value)
            if (maybeAccept(path, items)) return true
            if (items.isNotEmpty()) {
                items.take(20).forEachIndexed { index, item ->
                    if (scan(item, depth + 1, "$path[$index]")) return true
                }
            }
            val cls = value.javaClass
            if (!shouldInspectObject(cls) || shouldSkipDmUrlObject(value, cls) || seen.containsKey(value)) return false
            seen[value] = true
            dmNonStaticFields(cls).asSequence().take(48).forEach { field ->
                if (overBudget("fields")) return@forEach
                fields++
                if (field.type.isPrimitive || field.type == String::class.java) return@forEach
                val fieldValue = runCatching { field.get(value) }.getOrNull() ?: return@forEach
                if (scan(fieldValue, depth + 1, "$path.${field.name}")) return true
            }
            return candidates.isNotEmpty()
        }

        scan(root, 0, "root")
        val best = candidates.maxWithOrNull(compareBy<List<String>> { it.size }.thenBy { it.joinToString("|").length }).orEmpty()
        if (best.isNotEmpty()) {
            logInfo(
                "DM generic carousel graph hit root=${root.javaClass.name} count=${best.size} " +
                    "objects=$objects fields=$fields budget=$budgetStop elapsed=${SystemClock.uptimeMillis() - started}ms"
            )
        } else {
            logInfoThrottled("dm:generic-carousel-miss:${root.javaClass.name}", 1_500L) {
                "DM generic carousel graph miss root=${root.javaClass.name} objects=$objects fields=$fields " +
                    "budget=$budgetStop seed=${dmUrlsForDiagnosticLog(seedVisuals)} elapsed=${SystemClock.uptimeMillis() - started}ms"
            }
        }
        return best
    }

    private fun dmActionSourceDiagnosticsForLog(actionSources: Array<Any?>?): String {
        if (actionSources.isNullOrEmpty()) return "-"
        val parts = ArrayList<String>(8)
        actionSources.take(8).forEachIndexed { index, source ->
            if (source == null) {
                parts += "$index:null"
                return@forEachIndexed
            }
            if (source is View || source is Context || source is Activity) {
                parts += "$index:${source.javaClass.name.substringAfterLast('.')}:view"
                return@forEachIndexed
            }
            val ids = extractRowBindableIds(collectUsefulIdsDeep(source))
                .take(4)
                .joinToString(",") { it.take(24) }
                .ifBlank { "-" }
            parts += "$index:${source.javaClass.name.substringAfterLast('.')}:ids=$ids:shape=${dmObjectShapeForLog(source).take(240)}"
        }
        return parts.joinToString(" || ")
    }

    private fun dmCarouselSourceDeepHintsForLog(actionSources: Array<Any?>?, seedUrls: List<String>): String {
        if (actionSources.isNullOrEmpty()) return "-"
        val parts = ArrayList<String>(6)
        actionSources.take(12).forEachIndexed { index, source ->
            if (parts.size >= 6 || source == null || source is View || source is Context || source is Activity) return@forEachIndexed
            val shape = dmObjectShapeForLog(source)
            if (!dmHasShallowCarouselMediaSignal(source, shape) && dmImmediateCarouselContainerHint(source) == 0) return@forEachIndexed
            val fieldHints = ArrayList<String>(12)
            var cls: Class<*>? = source.javaClass
            var classDepth = 0
            var fields = 0
            while (cls != null && cls != Any::class.java && classDepth++ < 2 && fieldHints.size < 12) {
                dmNonStaticFields(cls).asSequence().take(42).forEach { field ->
                    if (fieldHints.size >= 12 || fields++ >= 64) return@forEach
                    val value = runCatching { field.get(source) }.getOrNull()
                    fieldHints += "${field.name}:${field.type.name.substringAfterLast('.')}=${dmCarouselHintValueForLog(value)}"
                }
                cls = cls.superclass
            }
            val ids = extractRowBindableIds(collectUsefulIdsDeep(source))
                .take(5)
                .joinToString(",") { it.take(28) }
                .ifBlank { "-" }
            parts += "src$index:${source.javaClass.name.substringAfterLast('.')}:ids=$ids:seed=${dmUrlsForDiagnosticLog(seedUrls)}:fields=${fieldHints.joinToString(";").take(820)}"
        }
        return parts.joinToString(" || ").ifBlank { "-" }
    }

    private fun dmCarouselHintValueForLog(value: Any?): String {
        return when (value) {
            null -> "null"
            is CharSequence -> {
                val urls = dmInlineMediaUrlsForLog(value.toString())
                if (urls.isNotEmpty()) "str:${value.length}:urls=${dmUrlsForDiagnosticLog(urls)}" else "str:${value.length}:${value.take(48)}"
            }
            is Uri -> "uri:${redactCdnUrlForLog(value.toString())}"
            is Number, is Boolean -> value.toString()
            is View -> describeViewBrief(value)
            is Activity -> value.javaClass.name.substringAfterLast('.')
            is Context -> value.javaClass.name.substringAfterLast('.')
            else -> {
                val size = dmContainerSize(value)
                val ids = dmShallowIdsForLog(value)
                val urls = dmShallowInlineUrlsForLog(value)
                val className = value.javaClass.name.substringAfterLast('.')
                buildString {
                    append(className)
                    if (size >= 0) append(":size=").append(size)
                    if (ids.isNotBlank()) append(":ids=").append(ids)
                    if (urls.isNotEmpty()) append(":urls=").append(dmUrlsForDiagnosticLog(urls))
                }
            }
        }.replace('\n', ' ').take(180)
    }

    private fun dmInlineMediaUrlsForLog(text: String): List<String> {
        if (text.isBlank()) return emptyList()
        val urls = ArrayList<String>(4)
        val matcher = urlPattern.matcher(text)
        while (matcher.find() && urls.size < 4) {
            val url = matcher.group()
            if (looksLikeMediaUrl(url) || isLikelyInstagramHostedMediaUrl(url) || isLikelyAudioHttpUrl(url)) urls += url
        }
        return urls
    }

    private fun dmShallowInlineUrlsForLog(value: Any): List<String> {
        val urls = LinkedHashSet<String>()
        if (value is CharSequence) return dmInlineMediaUrlsForLog(value.toString())
        if (value is Uri) return listOf(value.toString())
        if (value is View || value is Activity || value is Context || isPrimitiveLike(value)) return emptyList()
        var cls: Class<*>? = value.javaClass
        var classDepth = 0
        var fields = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 2 && urls.size < 4) {
            dmNonStaticFields(cls).asSequence().take(32).forEach { field ->
                if (urls.size >= 4 || fields++ >= 48) return@forEach
                val fieldValue = runCatching { field.get(value) }.getOrNull()
                when (fieldValue) {
                    is CharSequence -> urls += dmInlineMediaUrlsForLog(fieldValue.toString())
                    is Uri -> urls += fieldValue.toString()
                }
            }
            cls = cls.superclass
        }
        return urls.take(4)
    }

    private fun dmShallowIdsForLog(value: Any): String {
        if (value is View || value is Activity || value is Context || isPrimitiveLike(value)) return ""
        val ids = LinkedHashSet<String>()
        fun remember(candidate: Any?) {
            when (candidate) {
                is String -> addUsefulId(candidate, ids)
                is Number -> if (candidate.toLong() > 1_000_000_000L) addUsefulId(candidate.toString(), ids)
            }
        }
        remember(value)
        var cls: Class<*>? = value.javaClass
        var classDepth = 0
        var fields = 0
        while (cls != null && cls != Any::class.java && classDepth++ < 2 && ids.size < 5) {
            dmNonStaticFields(cls).asSequence().take(32).forEach { field ->
                if (ids.size >= 5 || fields++ >= 48) return@forEach
                remember(runCatching { field.get(value) }.getOrNull())
            }
            cls = cls.superclass
        }
        return extractRowBindableIds(ids).take(4).joinToString(",") { it.take(24) }
    }

    private fun dmSharedPostHintsForLog(actionSources: Array<Any?>?): String {
        if (actionSources.isNullOrEmpty()) return "-"
        val hints = LinkedHashSet<String>()
        val seen = IdentityHashMap<Any, Boolean>()
        var objects = 0
        var fields = 0
        fun addHint(path: String, value: String) {
            val text = value.take(240)
            val lower = text.lowercase(Locale.US)
            val interesting = lower.contains("instagram.com/p/") ||
                lower.contains("instagram.com/reel/") ||
                lower.contains("instagram.com/tv/") ||
                lower.contains("shortcode") ||
                lower.contains("media_id") ||
                lower.contains("mediaid") ||
                lower.contains("pk=") ||
                lower.matches(Regex(".*\\b\\d{12,}\\b.*"))
            if (!interesting) return
            hints += "${path.take(36)}=${text.replace('\n', ' ').take(160)}"
        }
        fun scan(value: Any?, depth: Int, path: String) {
            if (value == null || depth > 3 || objects++ > 80 || fields > 260 || hints.size >= 8) return
            when (value) {
                is CharSequence -> {
                    addHint(path, value.toString())
                    return
                }
                is Uri -> {
                    addHint(path, value.toString())
                    return
                }
                is View, is Context, is Activity -> return
            }
            val cls = value.javaClass
            if (cls.isArray) {
                val count = java.lang.reflect.Array.getLength(value).coerceAtMost(8)
                for (index in 0 until count) scan(java.lang.reflect.Array.get(value, index), depth + 1, "$path[$index]")
                return
            }
            if (value is Iterable<*>) {
                var index = 0
                for (item in value) {
                    if (index >= 8) break
                    scan(item, depth + 1, "$path[$index]")
                    index++
                }
                return
            }
            if (!shouldInspectObject(cls) || seen.containsKey(value)) return
            seen[value] = true
            dmNonStaticFields(cls).asSequence().take(48).forEach { field ->
                if (fields++ > 260 || hints.size >= 8) return@forEach
                if (field.type.isPrimitive && field.type != java.lang.Long.TYPE && field.type != java.lang.Integer.TYPE) return@forEach
                val fieldValue = runCatching { field.get(value) }.getOrNull() ?: return@forEach
                if (fieldValue is Number && fieldValue.toLong() > 1_000_000_000_000L) {
                    addHint("$path.${field.name}", fieldValue.toString())
                } else {
                    scan(fieldValue, depth + 1, "$path.${field.name}")
                }
            }
        }
        actionSources.take(8).forEachIndexed { index, source ->
            scan(source, 0, "src$index")
        }
        return if (hints.isEmpty()) "-" else hints.joinToString(" | ")
    }

    private fun relatedDmCarouselUrlsFromRecentCache(seedUrls: List<String>): List<String> {
        val seeds = seedUrls.mapNotNull(::dmCarouselCdnFingerprint).distinctBy { it.url }
        if (seeds.isEmpty()) return emptyList()
        val seedIdentities = seeds.mapTo(HashSet()) { dmUrlIdentityForChoice(it.url) }
        val sinceMs = System.currentTimeMillis() - 90_000L
        val recent = recentMediaUrlsSince(sinceMs)
        val recentFingerprints = recent.mapNotNull(::dmCarouselCdnFingerprint)
        val strictFingerprints = recentFingerprints.filter { candidate ->
            seeds.any { seed ->
                candidate.cid == seed.cid &&
                    candidate.sid == seed.sid &&
                    (
                        candidate.oc.isNotBlank() && candidate.oc == seed.oc ||
                            candidate.host == seed.host && candidate.cat == seed.cat && candidate.zt == seed.zt
                        )
            }
        }
        val relaxedOcFingerprints = recentFingerprints.filter { candidate ->
            seeds.any { seed ->
                candidate.sid == seed.sid &&
                    candidate.oc.isNotBlank() &&
                    candidate.oc == seed.oc
            }
        }
        val relaxedHostFingerprints = recentFingerprints.filter { candidate ->
            seeds.any { seed ->
                candidate.sid == seed.sid &&
                    candidate.host == seed.host &&
                    candidate.cat == seed.cat &&
                    candidate.zt == seed.zt
            }
        }
        val matches = strictFingerprints
            .map { it.url }
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
            .take(12)

        fun normalizedCarouselGroupUrls(group: List<DmCarouselCdnFingerprint>): List<String> {
            return group
                .map { it.url }
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinctBy(::dmUrlIdentityForChoice)
                .let { urls ->
                    val seedUrlsFirst = urls.filter { dmUrlIdentityForChoice(it) in seedIdentities }
                    seedUrlsFirst + urls.filterNot { dmUrlIdentityForChoice(it) in seedIdentities }
                }
                .take(12)
        }

        fun acceptedCarouselGroup(urls: List<String>, minSize: Int = 2, maxSize: Int = 20): Boolean {
            return urls.size in minSize..maxSize && urls.any { dmUrlIdentityForChoice(it) in seedIdentities }
        }

        fun bestCarouselGroup(groups: List<List<String>>, minSize: Int = 2, maxSize: Int = 20): List<String> {
            return groups
                .filter { acceptedCarouselGroup(it, minSize, maxSize) }
                .maxWithOrNull(compareBy<List<String>> { it.size }.thenBy { it.joinToString("|").length })
                .orEmpty()
        }

        val relaxedCidHostGroups = recentFingerprints
            .filter { candidate -> seeds.any { seed -> candidate.cid == seed.cid && candidate.host == seed.host } }
            .groupBy { "${it.cid}/${it.host}" }
            .values
            .map(::normalizedCarouselGroupUrls)
        val relaxedCidHostMatches = bestCarouselGroup(relaxedCidHostGroups)

        val seedIndexes = recentFingerprints.mapIndexedNotNull { index, fingerprint ->
            val identityMatch = dmUrlIdentityForChoice(fingerprint.url) in seedIdentities
            val fingerprintMatch = seeds.any { seed ->
                fingerprint.cid == seed.cid &&
                    (
                        fingerprint.sid == seed.sid ||
                            fingerprint.oc.isNotBlank() && fingerprint.oc == seed.oc ||
                            fingerprint.host == seed.host
                        )
            }
            if (identityMatch || fingerprintMatch) index else null
        }
        val relaxedCidWindowGroups = seedIndexes.flatMap { seedIndex ->
            seeds.map { seed ->
                val start = (seedIndex - 12).coerceAtLeast(0)
                val endExclusive = (seedIndex + 13).coerceAtMost(recentFingerprints.size)
                recentFingerprints
                    .subList(start, endExclusive)
                    .filter { it.cid == seed.cid }
                    .let(::normalizedCarouselGroupUrls)
            }
        }
        val relaxedCidWindowMatches = bestCarouselGroup(relaxedCidWindowGroups)

        val relaxedCidOnlyGroups = recentFingerprints
            .filter { candidate -> seeds.any { seed -> candidate.cid == seed.cid } }
            .groupBy { it.cid }
            .values
            .map(::normalizedCarouselGroupUrls)
        val relaxedCidOnlyMatches = bestCarouselGroup(relaxedCidOnlyGroups, minSize = 3, maxSize = 8)

        val acceptedCandidates = listOf(
            Triple("strict", 4, matches),
            Triple("cid-host", 3, relaxedCidHostMatches),
            Triple("cid-window", 2, relaxedCidWindowMatches),
            Triple("cid-only", 1, relaxedCidOnlyMatches)
        ).filter { (_, _, urls) -> acceptedCarouselGroup(urls) }
        val acceptedCandidate = acceptedCandidates.maxWithOrNull(
            compareBy<Triple<String, Int, List<String>>> { it.third.size }.thenBy { it.second }
        )
        val acceptedReason = acceptedCandidate?.first ?: "none"
        val accepted = acceptedCandidate?.third.orEmpty()
        val groups = recentFingerprints
            .groupBy { fingerprint ->
                listOf(
                    fingerprint.cid.ifBlank { "-" },
                    fingerprint.sid.ifBlank { "-" },
                    fingerprint.oc.ifBlank { "-" },
                    fingerprint.host,
                    fingerprint.cat.ifBlank { "-" },
                    fingerprint.zt.ifBlank { "-" }
                ).joinToString("/")
            }
            .entries
            .sortedWith(compareByDescending<Map.Entry<String, List<DmCarouselCdnFingerprint>>> { it.value.size }.thenBy { it.key })
            .take(5)
            .joinToString("|") { entry ->
                "${entry.value.size}:${entry.key.take(90)}"
            }
        val cidGroups = recentFingerprints
            .groupBy { it.cid.ifBlank { "-" } }
            .entries
            .sortedWith(compareByDescending<Map.Entry<String, List<DmCarouselCdnFingerprint>>> { it.value.size }.thenBy { it.key })
            .take(5)
            .joinToString("|") { entry -> "${entry.value.size}:${entry.key.take(30)}" }
        logInfo(
            "DM recent carousel cache diagnostic seeds=${seeds.size} recent=${recent.size} carouselRecent=${recentFingerprints.size} " +
                "strict=${strictFingerprints.size} relaxedOc=${relaxedOcFingerprints.size} relaxedHost=${relaxedHostFingerprints.size} " +
                "matches=${matches.size} cidHost=${relaxedCidHostMatches.size} cidWindow=${relaxedCidWindowMatches.size} " +
                "cidOnly=${relaxedCidOnlyMatches.size} accepted=${accepted.size}:$acceptedReason seedIndexes=${seedIndexes.take(8).joinToString(",")} " +
                "seedFp=${seeds.joinToString("|") { dmCarouselFingerprintForLog(it) }} " +
                "strictFp=${strictFingerprints.take(6).joinToString("|") { dmCarouselFingerprintForLog(it) }} " +
                "acceptedFp=${accepted.mapNotNull(::dmCarouselCdnFingerprint).take(8).joinToString("|") { dmCarouselFingerprintForLog(it) }} " +
                "groups=$groups cidGroups=$cidGroups types=${dmUrlTypesForLog(accepted)}"
        )
        return accepted
    }

    private fun rememberDmMediaAssetGroup(urls: List<String>, source: String) {
        val visualUrls = urls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .filter { looksLikeMediaUrl(it) || isLikelyInstagramHostedMediaUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
            .take(20)
        if (visualUrls.size < 2) return
        val now = System.currentTimeMillis()
        val group = DmMediaAssetGroup(visualUrls, now, source)
        visualUrls.forEach { url ->
            dmMediaAssetGroupsByIdentity[dmUrlIdentityForChoice(url)] = group
        }
        pruneDmMediaAssetGroups(now)
        logInfoThrottled("dm:asset-group-remember:${source}:${visualUrls.size}:${dmUrlIdentityForChoice(visualUrls.first()).take(24)}", 1_500L) {
            "DM media asset group remembered source=$source count=${visualUrls.size} " +
                "types=${dmUrlTypesForLog(visualUrls)} fp=${dmCarouselFingerprintsForLog(visualUrls)} " +
                "keys=${visualUrls.take(6).joinToString("|") { dmUrlIdentityForChoice(it).take(36) }}"
        }
    }

    private fun dmCachedMediaAssetGroupForUrls(seedUrls: List<String>): List<String> {
        val seeds = seedUrls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .map(::dmUrlIdentityForChoice)
            .filter { it.isNotBlank() }
            .distinct()
        if (seeds.isEmpty()) return emptyList()
        val now = System.currentTimeMillis()
        pruneDmMediaAssetGroups(now)
        val groups = seeds.mapNotNull { dmMediaAssetGroupsByIdentity[it] }
            .filter { now - it.timeMs in 0..1_800_000L }
            .distinctBy { it.urls.joinToString("|", transform = ::dmUrlIdentityForChoice) }
        val group = groups.maxWithOrNull(compareBy<DmMediaAssetGroup> { it.urls.size }.thenBy { it.timeMs }) ?: run {
            logInfoThrottled("dm:asset-group-miss:${seeds.joinToString("|").take(80)}", 1_500L) {
                "DM media asset group miss seeds=${seeds.take(6).joinToString("|") { it.take(36) }} " +
                    "cacheKeys=${dmMediaAssetGroupsByIdentity.size}"
            }
            return emptyList()
        }
        val ordered = group.urls
            .distinctBy(::dmUrlIdentityForChoice)
            .let { urls ->
                val seedSet = seeds.toHashSet()
                urls.filter { dmUrlIdentityForChoice(it) in seedSet } +
                    urls.filterNot { dmUrlIdentityForChoice(it) in seedSet }
            }
            .take(20)
        logInfo(
            "DM media asset group hit source=${group.source} count=${ordered.size} age=${now - group.timeMs}ms " +
                "seeds=${seeds.take(6).joinToString("|") { it.take(36) }} " +
                "types=${dmUrlTypesForLog(ordered)} fp=${dmCarouselFingerprintsForLog(ordered)}"
        )
        return ordered
    }

    private fun dmMediaInfoUrlsForActionSources(
        context: Context,
        actionSources: Array<Any?>?,
        seedUrls: List<String>,
        reason: String
    ): List<String> {
        val ids = dmMediaInfoCandidateIdsFromSources(actionSources)
        if (ids.isEmpty()) {
            logInfoThrottled("dm:media-info:no-ids:$reason", 1_500L) {
                "DM media-info lookup skipped reason=$reason ids=0 seeds=${dmUrlsForDiagnosticLog(seedUrls)}"
            }
            return emptyList()
        }
        val seedVisuals = seedUrls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        val now = System.currentTimeMillis()
        pruneDmMediaInfoCache(now)
        val cached = ids.mapNotNull { id ->
            val entry = dmMediaInfoUrlsById[id] ?: return@mapNotNull null
            if (now - entry.timeMs !in 0..15 * 60_000L) return@mapNotNull null
            val match = seedVisuals.isEmpty() || dmMediaUrlsMatchSeeds(entry.urls, seedVisuals)
            if (match) id to entry else {
                logInfoThrottled("dm:media-info:cache-seed-miss:$id", 1_500L) {
                    "DM media-info cache seed mismatch id=${id.take(18)} reason=$reason " +
                        "cached=${dmUrlsForDiagnosticLog(entry.urls)} seeds=${dmUrlsForDiagnosticLog(seedVisuals)} source=${entry.source}"
                }
                null
            }
        }
        val best = cached.maxWithOrNull(compareBy<Pair<String, DmMediaInfoCacheEntry>> { it.second.urls.size }.thenBy { it.second.timeMs })
        if (best != null) {
            val ordered = orderDmMediaInfoUrlsForSeeds(best.second.urls, seedVisuals)
            logInfo(
                "DM media-info cache hit reason=$reason id=${best.first.take(18)} count=${ordered.size} " +
                    "age=${now - best.second.timeMs}ms ids=${ids.take(5).joinToString("|") { it.take(18) }} " +
                    "types=${dmUrlTypesForLog(ordered)} fp=${dmCarouselFingerprintsForLog(ordered)} source=${best.second.source}"
            )
            return ordered
        }
        maybePrefetchDmMediaInfoUrls(context, actionSources, seedVisuals, reason)
        logInfoThrottled("dm:media-info:cache-miss:$reason:${ids.joinToString("|").take(80)}", 1_500L) {
            "DM media-info cache miss reason=$reason ids=${ids.take(5).joinToString("|") { "${it.take(18)}:${dmMediaInfoIdScore(it)}" }} " +
                "inFlight=${ids.count { dmMediaInfoFetchesInFlight.contains(it) }} seeds=${dmUrlsForDiagnosticLog(seedVisuals)}"
        }
        return emptyList()
    }

    private fun maybePrefetchDmMediaInfoUrls(
        context: Context?,
        actionSources: Array<Any?>?,
        seedUrls: List<String>,
        reason: String
    ) {
        if (context == null || actionSources.isNullOrEmpty()) return
        val ids = dmMediaInfoCandidateIdsFromSources(actionSources)
        if (ids.isEmpty()) return
        val seedVisuals = seedUrls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        logInfoThrottled("dm:media-info:prefetch:$reason:${ids.joinToString("|").take(80)}", 1_200L) {
            "DM media-info prefetch scheduled reason=$reason ids=${ids.take(5).joinToString("|") { "${it.take(18)}:${dmMediaInfoIdScore(it)}" }} " +
                "seeds=${dmUrlsForDiagnosticLog(seedVisuals)}"
        }
        ids.take(5).forEach { id -> startDmMediaInfoFetch(context, id, seedVisuals, reason) }
    }

    private fun startDmMediaInfoFetch(context: Context, mediaId: String, seedUrls: List<String>, reason: String) {
        val now = System.currentTimeMillis()
        dmMediaInfoUrlsById[mediaId]?.takeIf { now - it.timeMs in 0..15 * 60_000L }?.let { cached ->
            if (seedUrls.isEmpty() || dmMediaUrlsMatchSeeds(cached.urls, seedUrls)) return
        }
        if (!dmMediaInfoFetchesInFlight.add(mediaId)) return
        val appContext = context.applicationContext ?: context
        Thread({
            val started = SystemClock.uptimeMillis()
            try {
                val urls = InstagramFollowerListLogger.fetchMediaInfoDownloadUrls(appContext, mediaId)
                    .filterNot(::looksLikeProfileImageUrl)
                    .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                    .filter { looksLikeMediaUrl(it) || isLikelyInstagramHostedMediaUrl(it) }
                    .distinctBy(::dmUrlIdentityForChoice)
                    .take(20)
                val match = seedUrls.isEmpty() || dmMediaUrlsMatchSeeds(urls, seedUrls)
                if (urls.isNotEmpty() && match) {
                    dmMediaInfoUrlsById[mediaId] = DmMediaInfoCacheEntry(urls, System.currentTimeMillis(), reason)
                    rememberDmMediaAssetGroup(urls, "dm-media-info:$reason:${mediaId.take(12)}")
                }
                logInfo(
                    "DM media-info fetch complete reason=$reason id=${mediaId.take(18)} count=${urls.size} match=$match " +
                        "elapsed=${SystemClock.uptimeMillis() - started}ms seeds=${dmUrlsForDiagnosticLog(seedUrls)} " +
                        "types=${dmUrlTypesForLog(urls)} fp=${dmCarouselFingerprintsForLog(urls)}"
                )
            } catch (throwable: Throwable) {
                logError("DM media-info fetch failed reason=$reason id=${mediaId.take(18)}", throwable)
            } finally {
                dmMediaInfoFetchesInFlight.remove(mediaId)
                pruneDmMediaInfoCache()
            }
        }, "PurrfectDmMediaInfo").apply { isDaemon = true }.start()
    }

    private fun dmMediaInfoCandidateIdsFromSources(actionSources: Array<Any?>?): List<String> {
        if (actionSources.isNullOrEmpty()) return emptyList()
        val ids = LinkedHashSet<String>()
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun remember(raw: String?) {
            if (raw.isNullOrBlank()) return
            val matcher = dmMediaInfoIdPattern.matcher(raw)
            while (matcher.find() && ids.size < 12) {
                val candidate = matcher.group()?.trim().orEmpty()
                if (isDmMediaInfoCandidateId(candidate)) ids += candidate
            }
        }
        actionSources.take(12).forEach { source ->
            if (source == null || source is View || source is Context || source is Activity || isPrimitiveLike(source)) return@forEach
            if (!seen.add(source)) return@forEach
            remember(source.toString())
            dmShallowIdsForLog(source).split(',').forEach(::remember)
            val shape = dmObjectShapeForLog(source)
            if (dmHasShallowCarouselMediaSignal(source, shape)) {
                collectUsefulIdsDeep(source).take(8).forEach(::remember)
            }
        }
        return ids
            .sortedWith(compareByDescending<String> { dmMediaInfoIdScore(it) }.thenBy { it.length }.thenBy { it })
            .take(5)
    }

    private fun isDmMediaInfoCandidateId(value: String): Boolean {
        return value.length in 8..120 && value.matches(Regex("\\d+(?:_\\d+)?"))
    }

    private fun dmMediaInfoIdScore(id: String): Int {
        val base = id.substringBefore('_')
        var score = 0
        if ('_' in id) score += 8
        score += when (base.length) {
            in 15..22 -> 12
            in 12..14 -> 6
            in 23..26 -> 3
            in 8..11 -> 1
            else -> -4
        }
        if (base.startsWith("3402823668")) score -= 9
        if (base.startsWith("7477") || base.startsWith("1811")) score -= 2
        return score
    }

    private fun orderDmMediaInfoUrlsForSeeds(urls: List<String>, seedUrls: List<String>): List<String> {
        val distinct = urls
            .filterNot(::looksLikeProfileImageUrl)
            .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            .distinctBy(::dmUrlIdentityForChoice)
        if (distinct.isEmpty() || seedUrls.isEmpty()) return distinct
        val seedIdentities = seedUrls.mapTo(HashSet(), ::dmUrlIdentityForChoice)
        return (distinct.filter { dmUrlIdentityForChoice(it) in seedIdentities } +
            distinct.filterNot { dmUrlIdentityForChoice(it) in seedIdentities })
            .distinctBy(::dmUrlIdentityForChoice)
    }

    private fun pruneDmMediaInfoCache(now: Long = System.currentTimeMillis()) {
        dmMediaInfoUrlsById.entries.removeIf { now - it.value.timeMs > 15 * 60_000L }
        if (dmMediaInfoUrlsById.size <= 80) return
        val keep = dmMediaInfoUrlsById.entries
            .sortedByDescending { it.value.timeMs }
            .take(60)
            .mapTo(HashSet()) { it.key }
        dmMediaInfoUrlsById.keys.removeIf { it !in keep }
    }

    private fun pruneDmMediaAssetGroups(now: Long = System.currentTimeMillis()) {
        if (dmMediaAssetGroupsByIdentity.size <= 240) {
            dmMediaAssetGroupsByIdentity.entries.removeIf { now - it.value.timeMs > 1_800_000L }
            return
        }
        dmMediaAssetGroupsByIdentity.entries.removeIf { now - it.value.timeMs > 300_000L }
        if (dmMediaAssetGroupsByIdentity.size > 320) {
            val newest = dmMediaAssetGroupsByIdentity.entries
                .sortedByDescending { it.value.timeMs }
                .take(220)
                .mapTo(HashSet()) { it.key }
            dmMediaAssetGroupsByIdentity.keys.removeIf { it !in newest }
        }
    }

    private fun dmCarouselCdnFingerprint(url: String): DmCarouselCdnFingerprint? {
        if (!looksLikeMediaUrl(url) || looksLikeProfileImageUrl(url)) return null
        val uri = runCatching { Uri.parse(url) }.getOrNull() ?: return null
        val efg = runCatching { uri.getQueryParameter("efg").orEmpty() }.getOrDefault("")
        if (!looksLikeCarouselEfg(efg) && !url.contains("CAROUSEL_ITEM", ignoreCase = true)) return null
        val cid = runCatching { uri.getQueryParameter("_nc_cid").orEmpty() }.getOrDefault("")
        val sid = runCatching { uri.getQueryParameter("_nc_sid").orEmpty() }.getOrDefault("")
        if (cid.isBlank() || sid.isBlank()) return null
        return DmCarouselCdnFingerprint(
            url = url,
            host = uri.host.orEmpty(),
            cid = cid,
            oc = runCatching { uri.getQueryParameter("_nc_oc").orEmpty() }.getOrDefault(""),
            sid = sid,
            cat = runCatching { uri.getQueryParameter("_nc_cat").orEmpty() }.getOrDefault(""),
            zt = runCatching { uri.getQueryParameter("_nc_zt").orEmpty() }.getOrDefault("")
        )
    }

    private fun looksLikeCarouselEfg(efg: String): Boolean {
        if (efg.isBlank()) return false
        if (efg.contains("carousel", ignoreCase = true)) return true
        return runCatching {
            val decoded = String(android.util.Base64.decode(efg, android.util.Base64.DEFAULT))
            decoded.contains("CAROUSEL_ITEM", ignoreCase = true) ||
                decoded.contains("carousel", ignoreCase = true)
        }.getOrDefault(false)
    }

    private fun dmCarouselFingerprintsForLog(urls: List<String>): String {
        if (urls.isEmpty()) return "-"
        return urls
            .mapNotNull(::dmCarouselCdnFingerprint)
            .take(6)
            .joinToString("|") { dmCarouselFingerprintForLog(it) }
            .ifBlank { "-" }
    }

    private fun dmCarouselFingerprintForLog(fingerprint: DmCarouselCdnFingerprint): String {
        return "cid=${fingerprint.cid.ifBlank { "-" }}" +
            ",sid=${fingerprint.sid.ifBlank { "-" }}" +
            ",oc=${fingerprint.oc.takeLast(14).ifBlank { "-" }}" +
            ",cat=${fingerprint.cat.ifBlank { "-" }}" +
            ",zt=${fingerprint.zt.ifBlank { "-" }}" +
            ",host=${fingerprint.host.substringBefore('.')}" +
            ",id=${dmUrlIdentityForChoice(fingerprint.url).take(48)}"
    }

    private fun collectDmObjectUrlCandidates(
        value: Any?,
        out: MutableList<MediaUrlCandidate>,
        seen: IdentityHashMap<Any, Boolean>,
        depth: Int,
        path: String,
        score: Int
    ) {
        if (value == null || depth > 5 || out.size > 80) return
        when (value) {
            is String -> {
                addDmUrlCandidate(value, out, path, score + 10)
                return
            }
            is Uri -> {
                addDmUrlCandidate(value.toString(), out, path, score + 10)
                return
            }
        }

        val cls = value.javaClass
        if (isSimpleDmUrlValue(cls) || shouldSkipDmUrlObject(value, cls) || seen.containsKey(value)) return
        seen[value] = true

        val classPath = "$path@${cls.name}"
        val localScore = score + scoreDmUrlName(cls.name) + scoreDmUrlName(path)
        urlFromTypedObject(value)?.let { addDmUrlCandidate(it, out, classPath, localScore + 70) }
        if (isInstagramImageUrlLikeObject(cls)) {
            imageUrlFromObject(value)
                ?.takeIf { looksLikeMediaUrl(it) || isLikelyInstagramHostedMediaUrl(it) }
                ?.let { addDmUrlCandidate(it, out, classPath, localScore + 85) }
        }

        if (cls.isArray) {
            val length = java.lang.reflect.Array.getLength(value).coerceAtMost(30)
            for (i in 0 until length) {
                collectDmObjectUrlCandidates(java.lang.reflect.Array.get(value, i), out, seen, depth + 1, "$path[$i]", localScore)
            }
            return
        }

        if (value is Iterable<*>) {
            var index = 0
            value.forEach { item ->
                if (index >= 30) return@forEach
                collectDmObjectUrlCandidates(item, out, seen, depth + 1, "$path[$index]", localScore)
                index++
            }
            return
        }

        if (value is Map<*, *>) {
            var index = 0
            value.values.forEach { item ->
                if (index >= 30) return@forEach
                collectDmObjectUrlCandidates(item, out, seen, depth + 1, "$path.value$index", localScore)
                index++
            }
            return
        }

        collectDmGetterUrlCandidates(value, out, seen, depth, path, localScore)
        if (!shouldInspectDmUrlFields(cls)) return

        dmNonStaticFields(cls).asSequence().take(120).forEach { field ->
            runCatching {
                collectDmObjectUrlCandidates(
                    field.get(value),
                    out,
                    seen,
                    depth + 1,
                    "$path.${field.name}:${field.type.name}",
                    localScore + scoreDmUrlName(field.name) + scoreDmUrlName(field.type.name)
                )
            }
        }
    }

    private fun collectDmGetterUrlCandidates(
        value: Any,
        out: MutableList<MediaUrlCandidate>,
        seen: IdentityHashMap<Any, Boolean>,
        depth: Int,
        path: String,
        score: Int
    ) {
        if (!shouldInspectDmUrlMethods(value.javaClass)) return
        dmUrlGetterMethods(value.javaClass).forEach { method ->
            runCatching {
                collectDmObjectUrlCandidates(method.invoke(value), out, seen, depth + 1, "$path#${method.name}", score + scoreDmUrlName(method.name) + scoreDmUrlName(method.returnType.name))
            }
        }
    }

    private fun dmUrlGetterMethods(cls: Class<*>): List<Method> {
        return dmUrlGetterMethodCache.getOrPut(cls) { computeDmUrlGetterMethods(cls) }
    }

    private fun computeDmUrlGetterMethods(cls: Class<*>): List<Method> {
        val methods = LinkedHashMap<String, Method>()
        fun remember(method: Method) {
            runCatching { method.isAccessible = true }
            methods[dmMethodKey(method)] = method
        }

        arrayOf(
            "getUrl",
            "getUri",
            "getTypedUrl",
            "getTrackingUrl",
            "getMediaUrl",
            "getImageUrl",
            "getVideoUrl",
            "getThumbnailUrl",
            "getDownloadUrl",
            "getPlaybackUrl"
        )
            .forEach { name ->
                runCatching { cls.getMethod(name) }.getOrNull()
                    ?.takeIf(::isSafeDmUrlGetterMethod)
                    ?.let(::remember)
            }

        val discovered = ArrayList<Method>(128)
        runCatching { cls.methods.toList() }.getOrDefault(emptyList())
            .asSequence()
            .filter(::isSafeDmUrlGetterMethod)
            .forEach { discovered += it }
        var current: Class<*>? = cls
        var declaredSeen = 0
        while (current != null && current != Any::class.java && declaredSeen < 128) {
            runCatching { current.declaredMethods.toList() }.getOrDefault(emptyList())
                .asSequence()
                .filter { declaredSeen++ < 128 }
                .filter(::isSafeDmUrlGetterMethod)
                .forEach { discovered += it }
            current = current.superclass
        }

        discovered
            .distinctBy(::dmMethodKey)
            .sortedWith(
                compareByDescending<Method> { dmUrlGetterPriority(it) }
                    .thenBy { it.name.length }
                    .thenBy { it.name }
            )
            .take(80)
            .forEach(::remember)
        return methods.values.take(80)
    }

    private fun dmMethodKey(method: Method): String =
        "${method.declaringClass.name}#${method.name}:${method.returnType.name}"

    private fun dmUrlGetterPriority(method: Method): Int {
        val returnType = method.returnType
        var score = scoreDmUrlName(method.name) + scoreDmUrlName(returnType.name)
        if (CharSequence::class.java.isAssignableFrom(returnType) || Uri::class.java.isAssignableFrom(returnType)) {
            score += 50
        }
        if (method.name.startsWith("get", ignoreCase = true)) {
            score += 12
        }
        val returnTypeName = returnType.name
        if (returnTypeName.startsWith("com.instagram.")) {
            score += 6
        } else if (returnTypeName.startsWith("p000X.") || returnTypeName.startsWith("X.")) {
            score += 2
        }
        return score
    }

    private fun isSafeDmUrlGetterMethod(method: Method): Boolean {
        if (method.parameterTypes.isNotEmpty()) return false
        if (Modifier.isStatic(method.modifiers) || method.isSynthetic || method.returnType == Void.TYPE) return false
        if (method.declaringClass == Any::class.java || method.declaringClass == Object::class.java) return false
        val name = method.name
        if (name in setOf("hashCode", "toString", "clone", "getClass", "wait", "notify", "notifyAll")) return false
        val returnType = method.returnType
        if (returnType.isPrimitive || returnType == java.lang.Boolean::class.java || Number::class.java.isAssignableFrom(returnType)) return false
        if (returnType == Class::class.java || returnType == Context::class.java) return false
        return CharSequence::class.java.isAssignableFrom(returnType) ||
            Uri::class.java.isAssignableFrom(returnType) ||
            shouldInspectDmUrlFields(returnType)
    }

    private fun addDmUrlCandidate(url: String?, out: MutableList<MediaUrlCandidate>, path: String, score: Int) {
        if (url.isNullOrBlank() || looksLikeProfileImageUrl(url)) return
        val mime = mimeTypeForUrl(url)
        val audio = isLikelyAudioHttpUrl(url) || (looksLikeAudioPath(path) && looksLikeMediaUrl(url) && mime.startsWith("audio"))
        val hosted = isLikelyInstagramHostedMediaUrl(url)
        if (!looksLikeMediaUrl(url) && !audio && !hosted) return
        val video = !audio && (mime.startsWith("video") || url.lowercase(Locale.US).contains(".mp4"))
        val adjusted = score + scoreDmUrlName(url) + if (audio) 90 else if (video) 80 else 20
        out += MediaUrlCandidate(url, adjusted, video, audio, path)
    }

    private fun bestDmMediaUrlCandidate(candidates: List<MediaUrlCandidate>, preferAudio: Boolean): MediaUrlCandidate? {
        return candidates
            .filter { if (preferAudio) it.audio else !it.audio }
            .maxWithOrNull(compareBy<MediaUrlCandidate> { it.score }.thenBy { it.url.length })
    }

    private fun bestDmAudioFallbackCandidate(candidates: List<MediaUrlCandidate>): MediaUrlCandidate? {
        return candidates
            .filter { !it.video && !looksLikeProfileImageUrl(it.url) && !mimeTypeForUrl(it.url).startsWith("image") && (it.audio || isLikelyAudioHttpUrl(it.url)) }
            .maxWithOrNull(compareBy<MediaUrlCandidate> { it.score }.thenBy { it.url.length })
    }

    private fun shouldInspectDmUrlFields(cls: Class<*>): Boolean {
        val name = cls.name
        if (name.startsWith("com.instagram.common.session")) return false
        if (name.startsWith("com.instagram.direct.thread.analytics")) return false
        if (name.startsWith("android.") || name.startsWith("androidx.")) return false
        return name.startsWith("p000X.") || name.startsWith("X.") || name.startsWith("com.instagram.")
    }

    private fun shouldInspectDmUrlMethods(cls: Class<*>): Boolean {
        val name = cls.name
        return name.startsWith("p000X.") || name.startsWith("X.") || name.startsWith("com.instagram.")
    }

    private fun shouldSkipDmUrlObject(value: Any, cls: Class<*>): Boolean {
        if (value is Context || value is View || value is Drawable || value is Bitmap) return true
        val name = cls.name
        return name.contains("UserSession") ||
            name.contains("DirectThreadAnalytics") ||
            name.contains("Logger") ||
            name.contains("Logging") ||
            name.contains("Coroutine") ||
            name.contains("Fragment") ||
            name.contains("Activity") ||
            name.startsWith("java.lang.reflect.")
    }

    private fun isSimpleDmUrlValue(cls: Class<*>): Boolean {
        return cls.isPrimitive ||
            Number::class.java.isAssignableFrom(cls) ||
            cls == java.lang.Boolean::class.java ||
            cls == java.lang.Character::class.java ||
            Enum::class.java.isAssignableFrom(cls) ||
            cls == Class::class.java
    }

    private fun scoreDmUrlName(value: String?): Int {
        val lower = value?.lowercase(Locale.US) ?: return 0
        var score = 0
        if (lower.contains("video") || lower.contains("playback") || lower.contains("progressive") || lower.contains("download")) score += 60
        if (lower.contains("audio") || lower.contains("voice") || lower.contains("sound") || lower.contains("audioclip")) score += 70
        if (lower.contains("image") || lower.contains("photo") || lower.contains("media") || lower.contains("url")) score += 25
        if (lower.contains("imageurl") || lower.contains("extendedimageurl")) score += 35
        if (lower.contains("thumbnail") || lower.contains("cover") || lower.contains("avatar") || lower.contains("profile") || lower.contains("sticker") || lower.contains("emoji")) score -= 45
        if (lower.contains("direct") || lower.contains("messagethread")) score += 25
        if (lower.contains("3tp") || lower.contains("8uj") || lower.contains("kfy")) score += 30
        return score
    }

    private fun invokeUrlGetter(value: Any, methodName: String): String? {
        return runCatching {
            val method = value.javaClass.getMethod(methodName)
            if (method.parameterTypes.isNotEmpty()) return@runCatching null
            urlFromTypedObject(method.invoke(value))
        }.getOrNull()
    }

    private fun urlFromTypedObject(value: Any?): String? {
        return when (value) {
            is String -> value.takeIf { looksLikeMediaUrl(it) || isLikelyAudioHttpUrl(it) }
            null -> null
            else -> runCatching {
                val method = value.javaClass.getMethod("getUrl")
                val url = method.invoke(value) as? String
                url?.takeIf { looksLikeMediaUrl(it) || isLikelyAudioHttpUrl(it) }
            }.getOrNull()
        }
    }

    private fun isInstagramImageUrlLikeObject(cls: Class<*>): Boolean {
        val lower = cls.name.lowercase(Locale.US)
        return lower.contains("imageurl") ||
            lower.contains("image_url") ||
            lower.contains("typedurl")
    }

    private fun rememberDmImageUrl(view: View, url: String) {
        if (!shouldCaptureDmMediaUrl(view, "image-url")) return
        dmImageViewUrls[view] = url
        if (!looksLikeProfileImageUrl(url)) {
            rememberMediaUrl(url, directFallback = true)
            logDmCarouselUrlCapture("image-url", view, url)
        }
    }

    private fun logDmCarouselUrlCapture(origin: String, view: View?, url: String) {
        val fingerprint = dmCarouselCdnFingerprint(url) ?: return
        logInfoThrottled(
            "dm:carousel-url-capture:$origin:${fingerprint.sid}:${fingerprint.cid}:${fingerprint.oc.takeLast(10)}:${describeViewBrief(view)}",
            1_000L
        ) {
            "DM carousel URL captured origin=$origin fp=${dmCarouselFingerprintForLog(fingerprint)} " +
                "view=${describeViewBrief(view)} directActive=$dmDirectSurfaceActive overlay=$dmOverlayRootActive " +
                "runtime=${hasActiveDmActionRuntime()} url=${redactCdnUrlForLog(url)}"
        }
    }

    private fun rememberKnownDmAudioUrl(url: String?) {
        if (url.isNullOrBlank() || !url.startsWith("http") || looksLikeProfileImageUrl(url)) return
        synchronized(dmKnownAudioUrls) {
            dmKnownAudioUrls.remove(url)
            dmKnownAudioUrls.addFirst(url)
            while (dmKnownAudioUrls.size > 40) dmKnownAudioUrls.removeLast()
        }
    }

    private fun findRecentDmAudioUrl(): String? {
        synchronized(dmKnownAudioUrls) {
            if (dmKnownAudioUrls.isNotEmpty()) return dmKnownAudioUrls.peekFirst()
        }
        synchronized(dmRecentUrls) {
            pruneDmRecentUrls()
            return dmRecentUrls.firstOrNull { isAudioUrl(it.url) }?.url
        }
    }

    private fun looksLikeVoiceMessageContext(sources: Array<Any?>?, anchor: View?): Boolean {
        recentDmMessageActionMenuVoiceContext()?.let { return it }
        recentDmMessageActionMediaSnapshot()?.let { snapshot ->
            val hasVisualUrl = snapshot.urls.any { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            val hasAudioUrl = snapshot.urls.any { isAudioUrl(it) || isLikelyAudioHttpUrl(it) }
            if (snapshot.visual && hasVisualUrl) return false
            if (snapshot.voice || hasAudioUrl) return true
        }
        val actionAge = System.currentTimeMillis() - dmLatestMessageActionAnchorAtMs
        val latchedAge = System.currentTimeMillis() - dmLatestMessageActionVoiceAtMs
        if (viewHasScopedVoiceHint(anchor)) return true
        if (actionAge in 0..DM_LONG_PRESS_CONTEXT_MAX_AGE_MS && hasActiveDmMessageActionMenu(anchor)) {
            return dmLatestMessageActionWasVoice
        }
        if (dmLatestMessageActionWasVoice && latchedAge in 0..4_000L && recentTouchLooksLikeVoiceMessage(anchor)) return true
        if (sources == null) return false
        val seen = IdentityHashMap<Any, Boolean>()
        sources.forEach { source ->
            val viewModel = findDmMessageActionsViewModel(source)
            if (looksLikeVoiceToken(enumWireField(viewModel, "A07"))) return true
            if (source is View) {
                if (viewHasScopedVoiceHint(source)) return true
                return@forEach
            }
            if (objectContainsVoiceHint(source, seen, 0)) return true
        }
        return false
    }

    private fun hasActiveDmMessageActionMenu(anchor: View?): Boolean {
        if (dmOverlayRootActive) return true
        val root = anchor?.rootView ?: currentActivity?.window?.decorView ?: return false
        return rootContainsActiveDmMessageActionsOverlay(root) || hasPurrfectDmActionRowsVisible(root)
    }

    private fun viewHasLocalVoiceHint(view: View?): Boolean {
        var current = view
        repeat(5) {
            val node = current ?: return false
            if (viewNodeHasVoiceHint(node)) return true
            if (shouldScanLocalVoiceChildren(node) && viewContainsVoiceHint(node, 0, intArrayOf(0))) return true
            current = node.parent as? View
        }
        return false
    }

    private fun shouldScanLocalVoiceChildren(view: View): Boolean {
        if (!view.isShown || view.width <= 0 || view.height <= 0) return false
        if (view.width > 900 && view.height > 720) return false
        val rootWidth = view.rootView?.width ?: 0
        val nearFullWidth = rootWidth > 0 && view.width >= (rootWidth * 0.85f).toInt()
        return !(nearFullWidth && view.height >= 560)
    }

    private fun dmLocalVisualAnchorHint(view: View?): DmVisualAnchorHint {
        val now = SystemClock.uptimeMillis()
        if (view == null) return DmVisualAnchorHint(false, "no-anchor", now, 0L)
        dmVisualAnchorHintCache[view]?.let { cached ->
            if (now - cached.atMs < 2_500L) return cached
        }

        val started = now
        var current: View? = view
        var level = 0
        while (current != null && level < 6) {
            val node = current
            dmVisualMediaReasonForNode(node)?.let { reason ->
                return rememberDmVisualAnchorHint(view, true, "ancestor$level:$reason", started)
            }
            if (shouldScanLocalDmVisualChildren(node)) {
                dmVisualMediaReasonInView(node, 0, intArrayOf(0))?.let { reason ->
                    return rememberDmVisualAnchorHint(view, true, "children$level:$reason", started)
                }
            }
            current = node.parent as? View
            level++
        }
        return rememberDmVisualAnchorHint(view, false, "none", started)
    }

    private fun rememberDmVisualAnchorHint(
        key: View,
        visual: Boolean,
        reason: String,
        started: Long
    ): DmVisualAnchorHint {
        val finished = SystemClock.uptimeMillis()
        val hint = DmVisualAnchorHint(visual, reason, finished, finished - started)
        dmVisualAnchorHintCache[key] = hint
        if (visual) {
            logInfoThrottled("dm:visual-anchor:${reason}:${describeViewBrief(key)}", 1_000L) {
                "DM visual anchor hint reason=$reason elapsed=${hint.elapsedMs}ms view=${describeViewBrief(key)} bounds=${viewBoundsForLog(key)}"
            }
        }
        return hint
    }

    private fun shouldScanLocalDmVisualChildren(view: View): Boolean {
        if (!view.isShown || view.width <= 0 || view.height <= 0) return false
        if (view.width > 960 && view.height > 1_250) return false
        val rootWidth = view.rootView?.width ?: 0
        val nearFullWidth = rootWidth > 0 && view.width >= (rootWidth * 0.9f).toInt()
        return !(nearFullWidth && view.height >= 900)
    }

    private fun dmVisualMediaReasonInView(view: View?, depth: Int, visited: IntArray): String? {
        if (view == null || depth > 3 || visited[0]++ > 120 || view.visibility != View.VISIBLE) return null
        dmVisualMediaReasonForNode(view)?.let { return it }
        if (view is ViewGroup) {
            val count = minOf(view.childCount, 18)
            for (i in 0 until count) {
                dmVisualMediaReasonInView(view.getChildAt(i), depth + 1, visited)?.let { return it }
            }
        }
        return null
    }

    private fun dmVisualMediaReasonForNode(view: View): String? {
        if (!view.isShown || view.width <= 0 || view.height <= 0) return null
        val ownName = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        val className = view.javaClass.name.lowercase(Locale.US)
        val description = view.contentDescription?.toString().orEmpty().take(180).lowercase(Locale.US)
        val tag = view.tag?.toString().orEmpty().take(180).lowercase(Locale.US)
        val text = (view as? TextView)?.text?.toString().orEmpty().trim().take(80).lowercase(Locale.US)
        val hay = "$ownName $className $description $tag $text"
        if (dmNodeLooksLikeProfileOnlyShare(hay)) return null
        firstMatchingToken(hay, dmVisualStrongNodeTokens)?.let { token -> return "strong:$token" }

        val visualContext = dmViewHasVisualMediaContext(view)
        if (!visualContext) return null

        firstMatchingToken(hay, dmVisualImageNodeTokens)?.let { token ->
            if (dmNodeLooksLikeAvatarThumbnail(hay, view)) return null
            return "media-node:$token"
        }
        if (description.contains("view photo") || description.contains("view video")) return "description:view-media"
        if (text == "photo" || text == "video" || text == "reel") return "label:$text"
        return null
    }

    private fun firstMatchingToken(value: String, tokens: Array<String>): String? {
        tokens.forEach { token ->
            if (value.contains(token)) return token
        }
        return null
    }

    private fun dmViewHasVisualMediaContext(view: View): Boolean {
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 6) {
            val node = current
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            val className = node.javaClass.name.lowercase(Locale.US)
            val tag = node.tag?.toString().orEmpty().take(120).lowercase(Locale.US)
            val description = node.contentDescription?.toString().orEmpty().take(120).lowercase(Locale.US)
            val hay = "$name $className $tag $description"
            if (dmNodeLooksLikeProfileOnlyShare(hay)) return false
            if (firstMatchingToken(hay, dmVisualContextTokens) != null) return true
            current = node.parent as? View
        }
        return false
    }

    private fun dmNodeLooksLikeProfileOnlyShare(value: String): Boolean {
        return value.contains("profile_share_card") ||
            value.contains("direct_profile_share") ||
            value.contains("shared_profile_card") ||
            value.contains("profilecard")
    }

    private fun dmNodeLooksLikeAvatarThumbnail(value: String, view: View): Boolean {
        if (value.contains("avatar") ||
            value.contains("profile_pic") ||
            value.contains("profile_picture") ||
            value.contains("profile_photo") ||
            value.contains("presence")
        ) {
            return true
        }
        val avatarMax = dp(view, 96)
        val squareSlop = dp(view, 14)
        return view.width <= avatarMax &&
            view.height <= avatarMax &&
            abs(view.width - view.height) <= squareSlop
    }

    private fun viewHasScopedVoiceHint(view: View?): Boolean {
        if (view == null) return false
        if (viewHasLocalVoiceHint(view)) return true
        if (!isBroadDmMessageContentContainer(view) && viewContainsVoiceHint(view, 0, intArrayOf(0))) return true
        return recentTouchLooksLikeVoiceMessage(view)
    }

    private fun isBroadDmMessageContentContainer(view: View): Boolean {
        val descriptor = monetViewDescriptor(view)
        if (!descriptor.contains("message_content")) return false
        val root = view.rootView
        val rootWidth = root?.width ?: 0
        val nearFullWidth = rootWidth > 0 && view.width >= (rootWidth * 0.85f).toInt()
        return nearFullWidth && view.height >= 520
    }

    private fun currentDmThreadContainsVoiceHint(): Boolean {
        val root = currentActivity?.window?.decorView ?: return false
        return rootHasAnyVoiceHint(root, 0, intArrayOf(0))
    }

    private fun rootHasAnyVoiceHint(view: View?, depth: Int, visited: IntArray): Boolean {
        if (view == null || depth > 14 || visited[0]++ > 1_600 || view.visibility != View.VISIBLE) return false
        if (viewContainsVoiceHint(view, 0, intArrayOf(0))) return true
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                if (rootHasAnyVoiceHint(view.getChildAt(i), depth + 1, visited)) return true
            }
        }
        return false
    }

    private fun recentTouchLooksLikeVoiceMessage(anchor: View?): Boolean {
        val age = System.currentTimeMillis() - dmLastMessageActionTouchAtMs
        if (age !in 0..15_000L) return false
        val x = dmLastMessageActionTouchX
        val y = dmLastMessageActionTouchY
        if (x < 0f || y < 0f) return false
        val root = anchor?.rootView ?: currentActivity?.window?.decorView ?: return false
        return rootHasVoiceHintNearTouch(root, x, y, 0, intArrayOf(0))
    }

    private fun rootHasVoiceHintNearTouch(view: View?, x: Float, y: Float, depth: Int, visited: IntArray): Boolean {
        if (view == null || depth > 10 || visited[0]++ > 900 || view.visibility != View.VISIBLE) return false
        if (viewContainsVoiceHint(view, 0, intArrayOf(0)) && isTouchNearView(view, x, y, 180)) return true
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                if (rootHasVoiceHintNearTouch(view.getChildAt(i), x, y, depth + 1, visited)) return true
            }
        }
        return false
    }

    private fun isTouchNearView(view: View, x: Float, y: Float, padding: Int): Boolean {
        if (view.width > 960 && view.height > 1_200) return false
        val loc = IntArray(2)
        runCatching { view.getLocationOnScreen(loc) }.getOrElse { return false }
        return x >= loc[0] - padding &&
            x <= loc[0] + view.width + padding &&
            y >= loc[1] - padding &&
            y <= loc[1] + view.height + padding
    }

    private fun viewContainsVoiceHint(view: View?, depth: Int, visited: IntArray): Boolean {
        if (view == null || depth > 4 || visited[0]++ > 80) return false
        if (viewNodeHasVoiceHint(view)) return true
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                if (viewContainsVoiceHint(view.getChildAt(i), depth + 1, visited)) return true
            }
        }
        return false
    }

    private fun viewNodeHasVoiceHint(view: View): Boolean {
        if (looksLikeVoiceToken(view.javaClass.name)) return true
        if (looksLikeVoiceToken(view.contentDescription?.toString())) return true
        if (looksLikeVoiceToken(view.tag?.toString())) return true
        runCatching {
            if (view.id != View.NO_ID && view.id > 0x00FFFFFF && looksLikeVoiceToken(view.resources.getResourceEntryName(view.id))) return true
        }
        return view is TextView && looksLikeVoiceToken(view.text?.toString())
    }

    private fun objectContainsVoiceHint(value: Any?, seen: IdentityHashMap<Any, Boolean>, depth: Int): Boolean {
        if (value == null || depth > 4) return false
        if (value is CharSequence || value is Uri) return looksLikeVoiceToken(value.toString())
        if (value is View) return viewContainsVoiceHint(value, 0, intArrayOf(0))
        val cls = value.javaClass
        if (Enum::class.java.isAssignableFrom(cls)) return looksLikeVoiceToken(enumName(value)) || looksLikeVoiceToken(enumWire(value))
        if (isSimpleDmUrlValue(cls) || value is Context || value is Drawable || value is Bitmap) return false
        if (seen.containsKey(value)) return false
        seen[value] = true
        if (looksLikeVoiceToken(cls.name)) return true
        if (cls.isArray) {
            val length = java.lang.reflect.Array.getLength(value).coerceAtMost(20)
            for (i in 0 until length) if (objectContainsVoiceHint(java.lang.reflect.Array.get(value, i), seen, depth + 1)) return true
            return false
        }
        if (value is Iterable<*>) {
            var index = 0
            value.forEach { item ->
                if (index++ >= 20) return@forEach
                if (objectContainsVoiceHint(item, seen, depth + 1)) return true
            }
            return false
        }
        if (!shouldInspectDmUrlFields(cls)) return false
        dmNonStaticFields(cls).asSequence().take(80).forEach { field ->
            if (looksLikeVoiceToken(field.name) || looksLikeVoiceToken(field.type.name)) return true
            runCatching {
                if (objectContainsVoiceHint(field.get(value), seen, depth + 1)) return true
            }
        }
        return false
    }

    private fun looksLikeVoiceToken(value: String?): Boolean {
        val lower = value?.lowercase(Locale.US) ?: return false
        return lower.contains("voice_message") ||
            lower.contains("voicemessage") ||
            lower.contains("voice message") ||
            lower.contains("voice_note") ||
            lower.contains("voice note") ||
            lower.contains("voice_visualizer") ||
            lower.contains("voicevisualizer") ||
            lower.contains("voice_playback") ||
            lower.contains("message_content_voice") ||
            lower.contains("audio_message") ||
            lower.contains("audiomessage") ||
            lower.contains("audio message") ||
            lower.contains("audio_clip") ||
            lower.contains("audioclip") ||
            lower.contains("audio clip") ||
            lower.contains("audio_playback") ||
            lower.contains("message_content_audio") ||
            lower.contains("view transcription") ||
            lower.contains("transcription") ||
            lower.contains("waveform") ||
            lower == "voice" ||
            lower == "audio"
    }

    private fun looksLikeAudioPath(path: String?): Boolean {
        val lower = path?.lowercase(Locale.US) ?: return false
        return lower.contains("voice") || lower.contains("audio") || lower.contains("audioclip")
    }

    private fun currentStackLooksLikeVoice(): Boolean {
        return Thread.currentThread().stackTrace.any {
            looksLikeVoiceToken(it.className) || looksLikeVoiceToken(it.methodName)
        }
    }

    private fun isAudioUrl(url: String?): Boolean {
        val lower = url?.lowercase(Locale.US) ?: return false
        val known = synchronized(dmKnownAudioUrls) { dmKnownAudioUrls.contains(url) }
        return known ||
            lower.contains(".m4a") ||
            lower.contains(".aac") ||
            lower.contains(".mp3") ||
            lower.contains(".opus") ||
            lower.contains(".ogg") ||
            lower.contains("audio") ||
            lower.contains("voice") ||
            lower.contains("audioclip") ||
            lower.contains("/audio/")
    }

    private fun isLikelyAudioHttpUrl(url: String?): Boolean {
        val lower = url?.lowercase(Locale.US) ?: return false
        if (!lower.startsWith("http://") && !lower.startsWith("https://")) return false
        if (!isAudioUrl(lower)) return false
        return lower.contains("cdninstagram.com") ||
            lower.contains("fbcdn.net") ||
            lower.contains("fbsbx.com") ||
            lower.contains("facebook.com")
    }

    private fun isLikelyInstagramHostedMediaUrl(url: String?): Boolean {
        val lower = url?.lowercase(Locale.US) ?: return false
        if (!lower.startsWith("http://") && !lower.startsWith("https://")) return false
        if (looksLikeProfileImageUrl(lower)) return false
        return lower.contains("cdninstagram.com") || lower.contains("fbcdn.net") || lower.contains("fbsbx.com")
    }

    private fun tryDownloadVoiceFallbackForCurrentMessage(context: Context): Boolean {
        if (!hasFreshDmVoiceContext()) return false
        findRecentDmAudioUrl()?.let { url ->
            rememberKnownDmAudioUrl(url)
            enqueueDownload(url)
            return true
        }
        return tryDownloadRecentVoiceCache(context, requireVoiceContext = true)
    }

    private fun tryPreviewVoiceFallbackForCurrentMessage(context: Context, anchor: View?): Boolean {
        if (!hasFreshDmVoiceContext()) return false
        findRecentDmAudioUrl()?.let { url ->
            rememberKnownDmAudioUrl(url)
            scheduleDmAudioPreview(context, url, anchor)
            return true
        }
        return tryPreviewRecentVoiceCache(context, anchor, requireVoiceContext = true)
    }

    private fun hasFreshDmVoiceContext(): Boolean {
        val age = System.currentTimeMillis() - dmLastVoiceContextAtMs
        return age in 0..3_500L
    }

    private fun tryDownloadRecentVoiceCache(context: Context, requireVoiceContext: Boolean): Boolean {
        val age = System.currentTimeMillis() - dmLastVoiceContextAtMs
        if (requireVoiceContext && (age < 0 || age > 15_000L)) return false
        Thread({
            val source = runCatching { findRecentVoiceCacheFile(context, if (requireVoiceContext) 20 * 60_000L else 4 * 60_000L) }.getOrNull()
            if (source == null) {
                logInfo("DM voice cache fallback found no source requireVoiceContext=$requireVoiceContext")
                mainHandler.post { Toast.makeText(context, "No media found for this message", Toast.LENGTH_SHORT).show() }
                return@Thread
            }
            logInfo("DM voice cache fallback saving ${source.absolutePath} size=${source.length()} modified=${source.lastModified()}")
            runCatching { saveLocalVoiceFile(context, source) }
                .onSuccess { mainHandler.post { Toast.makeText(context, "Voice message saved", Toast.LENGTH_SHORT).show() } }
                .onFailure {
                    logError("DM voice cache fallback failed", it)
                    mainHandler.post { Toast.makeText(context, "Download failed", Toast.LENGTH_SHORT).show() }
                }
        }, "PurrfectInstaVoiceExport").start()
        return true
    }

    private fun tryPreviewRecentVoiceCache(context: Context, anchor: View?, requireVoiceContext: Boolean): Boolean {
        val age = System.currentTimeMillis() - dmLastVoiceContextAtMs
        if (requireVoiceContext && (age < 0 || age > 15_000L)) return false
        Thread({
            val source = runCatching { findRecentVoiceCacheFile(context, if (requireVoiceContext) 20 * 60_000L else 4 * 60_000L) }.getOrNull()
            if (source == null) {
                logInfo("DM voice preview cache fallback found no source requireVoiceContext=$requireVoiceContext")
                mainHandler.post { Toast.makeText(context, "No media found for this message", Toast.LENGTH_SHORT).show() }
                return@Thread
            }
            logInfo("DM voice preview cache fallback source=${source.absolutePath} size=${source.length()} modified=${source.lastModified()}")
            mainHandler.post { scheduleDmAudioPreview(context, source.absolutePath, anchor) }
        }, "PurrfectInstaVoicePreview").start()
        return true
    }

    private fun findRecentVoiceCacheFile(context: Context, windowMs: Long): File? {
        val roots = mutableListOf<File>()
        fun add(root: File?) {
            if (root != null && root.exists() && roots.none { it.absolutePath == root.absolutePath }) roots += root
        }
        add(context.cacheDir)
        add(context.filesDir)
        add(context.noBackupFilesDir)
        add(runCatching { File(context.applicationInfo.dataDir) }.getOrNull())
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) add(context.codeCacheDir)
        add(context.externalCacheDir)
        context.externalCacheDirs?.forEach { add(it) }
        context.getExternalFilesDirs(null)?.forEach { add(it) }
        val cutoff = System.currentTimeMillis() - windowMs.coerceAtLeast(60_000L)
        val best = VoiceCacheCandidate()
        val visited = intArrayOf(0)
        roots.forEach { scanVoiceCache(it, cutoff, 0, visited, best) }
        return best.file
    }

    private fun scanVoiceCache(file: File?, cutoff: Long, depth: Int, visited: IntArray, best: VoiceCacheCandidate) {
        if (file == null || !file.exists() || depth > 10 || visited[0]++ > 12_000) return
        if (file.isDirectory) {
            val lower = file.absolutePath.lowercase(Locale.US)
            val childLimit = if (
                lower.contains("cache") || lower.contains("exo") || lower.contains("audio") ||
                lower.contains("voice") || lower.contains("direct") || lower.contains("media")
            ) 320 else 120
            file.listFiles()?.take(childLimit)?.forEach { child -> scanVoiceCache(child, cutoff, depth + 1, visited, best) }
            return
        }

        val length = file.length()
        val modified = file.lastModified()
        if (length < 512L || modified < cutoff) return
        val lower = file.absolutePath.lowercase(Locale.US)
        if (lower.endsWith(".jpg") || lower.endsWith(".jpeg") || lower.endsWith(".png") ||
            lower.endsWith(".webp") || lower.endsWith(".gif") || lower.contains("/image") || lower.contains("\\image")
        ) return
        if (lower.endsWith(".json") || lower.endsWith(".txt") || lower.endsWith(".xml") ||
            lower.endsWith(".db") || lower.endsWith(".db-wal") || lower.endsWith(".db-shm") ||
            lower.endsWith(".sql") || lower.endsWith(".sql-wal") || lower.endsWith(".sql-shm") ||
            lower.endsWith(".sqlite") || lower.endsWith(".sqlite-wal") || lower.endsWith(".sqlite-shm") ||
            lower.endsWith(".lock") || lower.endsWith(".lck") || lower.endsWith(".tmp") ||
            lower.contains("/app_analytics/") || lower.contains("\\app_analytics\\") ||
            lower.contains("/fflogger/") || lower.contains("\\fflogger\\") ||
            lower.contains("/ras_blobs/") || lower.contains("\\ras_blobs\\")
        ) return

        var score = 0
        if (lower.contains("voice")) score += 120
        if (lower.contains("audio")) score += 100
        if (lower.contains("audioclip")) score += 120
        if (lower.contains("direct")) score += 35
        if (lower.contains("exo")) score += 25
        if (lower.contains("media")) score += 10
        if (lower.endsWith(".m4a") || lower.endsWith(".aac") || lower.endsWith(".opus") || lower.endsWith(".ogg") || lower.endsWith(".mp3")) score += 140
        if (lower.endsWith(".mp4") || lower.endsWith(".exo")) score += 45
        if (lower.contains("okhttp") || lower.contains("http") || lower.contains("media_cache")) score += 20
        score += (length / 65_536L).toInt().coerceAtMost(50)
        score += ((modified - cutoff) / 60_000L).toInt().coerceIn(0, 50)
        if (score > best.score || (score == best.score && modified > best.modified)) {
            best.file = file
            best.score = score
            best.modified = modified
        }
    }

    private fun saveLocalVoiceFile(context: Context, source: File) {
        val filename = "purrfect_insta_voice_${System.currentTimeMillis()}${voiceExtension(source)}"
        val mime = voiceMimeType(source)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
                put(MediaStore.MediaColumns.MIME_TYPE, mime)
                put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_MUSIC + "/PurrfectInsta/Voice Messages")
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
            val uri = context.contentResolver.insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, values)
                ?: error("Audio MediaStore insert failed")
            try {
                java.io.FileInputStream(source).use { input ->
                    context.contentResolver.openOutputStream(uri)?.use { output -> copyStream(input, output) }
                        ?: error("Audio output stream unavailable")
                }
            } catch (throwable: Throwable) {
                runCatching { context.contentResolver.delete(uri, null, null) }
                throw throwable
            }
            ContentValues().apply {
                put(MediaStore.MediaColumns.IS_PENDING, 0)
                context.contentResolver.update(uri, this, null, null)
            }
            return
        }

        val root = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_MUSIC)
        val dir = File(root, "PurrfectInsta/Voice Messages")
        if (!dir.exists() && !dir.mkdirs()) error("Cannot create voice folder")
        val outFile = File(dir, filename)
        java.io.FileInputStream(source).use { input ->
            java.io.FileOutputStream(outFile).use { output -> copyStream(input, output) }
        }
        outFile.setReadable(true, false)
    }

    private fun voiceExtension(file: File): String {
        val lower = file.name.lowercase(Locale.US)
        return when {
            lower.endsWith(".opus") -> ".opus"
            lower.endsWith(".ogg") -> ".ogg"
            lower.endsWith(".mp3") -> ".mp3"
            lower.endsWith(".aac") -> ".aac"
            else -> ".m4a"
        }
    }

    private fun voiceMimeType(file: File): String {
        return when (voiceExtension(file)) {
            ".opus", ".ogg" -> "audio/ogg"
            ".mp3" -> "audio/mpeg"
            ".aac" -> "audio/aac"
            else -> "audio/mp4"
        }
    }

    private fun maybeDeferDmModalAction(context: Context, action: Int, url: String): Boolean {
        if (action !in listOf(DM_ACTION_OPEN_APPS, DM_ACTION_PREVIEW, DM_ACTION_REPOST, DM_ACTION_WHATSAPP_STORY)) return false
        val activity = findActivity(context)
        if (!isInstagramModalActivity(activity) || isActivityHistoryModal(activity)) return false
        dmPendingDeferredAction = DeferredDmAction(
            action,
            url,
            System.currentTimeMillis(),
            dmLatestMessageActionAnchorAtMs,
            dmLastMessageActionTouchAtMs,
            lastDirectThreadId
        )
        logInfo("DM deferred action queued action=${dmActionLabel(action)} url=${redactCdnUrlForLog(url)}")
        dismissDmModalWithBack(activity)
        mainHandler.postDelayed({ drainDeferredDmAction(dmLatestStableActionActivity?.get()) }, 900L)
        return true
    }

    private fun dismissDmModalWithBack(activity: Activity?) {
        if (activity == null) return
        mainHandler.post {
            runCatching {
                if (activity.isFinishing || activity.isDestroyed) return@post
                runCatching { activity.onBackPressed() }.getOrElse {
                    activity.dispatchKeyEvent(KeyEvent(KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_BACK))
                    activity.dispatchKeyEvent(KeyEvent(KeyEvent.ACTION_UP, KeyEvent.KEYCODE_BACK))
                }
            }.onFailure { logError("Failed to dismiss DM modal", it) }
        }
    }

    private fun drainDeferredDmAction(hostActivity: Activity?) {
        val pending = dmPendingDeferredAction ?: return
        val now = System.currentTimeMillis()
        if (hostActivity == null || hostActivity.isFinishing || hostActivity.isDestroyed) {
            if (now - pending.createdAtMs > 5_000L) {
                dmPendingDeferredAction = null
                logInfo("DM deferred action dropped action=${dmActionLabel(pending.action)} reason=no-host")
            }
            return
        }
        val foreground = currentActivity
        if ((isInstagramModalActivity(hostActivity) && !isActivityHistoryModal(hostActivity)) ||
            (isInstagramModalActivity(foreground) && !isActivityHistoryModal(foreground))
        ) {
            if (now - pending.createdAtMs < 2_500L) return
            dmPendingDeferredAction = null
            logInfo("DM deferred action dropped action=${dmActionLabel(pending.action)} reason=modal-still-foreground")
            return
        }
        val root = hostActivity.window?.decorView
        val surfaceReason = root?.let(::directMessageSurfaceReason)
        val contextAtMs = maxOf(pending.anchorAtMs, pending.touchAtMs)
        val contextAge = if (contextAtMs > 0L) now - contextAtMs else 0L
        val currentThreadId = lastDirectThreadId
        if (!pending.threadId.isNullOrBlank() && !currentThreadId.isNullOrBlank() && pending.threadId != currentThreadId) {
            dmPendingDeferredAction = null
            logInfo(
                "DM deferred action dropped action=${dmActionLabel(pending.action)} " +
                    "reason=thread-changed original=${pending.threadId} current=$currentThreadId"
            )
            return
        }
        if (surfaceReason == null || surfaceReason == "direct-inbox-id" || contextAge !in 0..6_000L) {
            dmPendingDeferredAction = null
            logInfo(
                "DM deferred action dropped action=${dmActionLabel(pending.action)} " +
                    "reason=${surfaceReason ?: "not-direct-thread"} contextAge=$contextAge"
            )
            return
        }
        dmPendingDeferredAction = null
        logInfo(
            "DM deferred action resuming action=${dmActionLabel(pending.action)} " +
                "surface=$surfaceReason contextAge=$contextAge"
        )
        mainHandler.postDelayed({
            if (!hostActivity.isFinishing && !hostActivity.isDestroyed) {
                handleResolvedDmAction(hostActivity, null, null, pending.action, null, pending.url)
            }
        }, 220L)
    }

    private fun stableDmActionContext(context: Context): Context {
        val activity = findActivity(context)
        if (isInstagramModalActivity(activity) && !isActivityHistoryModal(activity)) {
            context.applicationContext?.let { return it }
        }
        return context
    }

    private fun isInstagramModalActivity(activity: Activity?): Boolean {
        return activity?.javaClass?.name == "com.instagram.modal.ModalActivity"
    }

    private fun isActivityHistoryModal(activity: Activity?): Boolean {
        if (!isInstagramModalActivity(activity)) return false
        return runCatching {
            val text = "${activity?.intent?.data} ${activity?.intent?.extras}".lowercase(Locale.US)
            text.contains("instaeclipse_activity_history") || text.contains("purrfect_activity_history")
        }.getOrDefault(false)
    }

    private fun intentTargetsInstagramModal(intent: Intent?): Boolean {
        if (intent == null) return false
        return runCatching { intent.component?.className == "com.instagram.modal.ModalActivity" }.getOrDefault(false) ||
            intent.toString().contains("com.instagram.modal.ModalActivity")
    }

    private fun intentMentionsActivityHistory(intent: Intent?): Boolean {
        if (intent == null) return false
        return runCatching {
            val text = "$intent ${intent.data} ${intent.extras}".lowercase(Locale.US)
            text.contains("instaeclipse_activity_history") || text.contains("purrfect_activity_history")
        }.getOrDefault(false)
    }

    private fun findDmMessageActionsViewModel(source: Any?): Any? {
        val viewModelClass = dmMessageActionsViewModelClass ?: return null
        if (source == null) return null
        if (viewModelClass.isInstance(source)) return source
        dmMessageViewModelFields(source.javaClass).forEach { field ->
            runCatching { field.get(source) }.getOrNull()?.let { return it }
        }
        return null
    }

    private fun fieldValueDeep(item: Any?, name: String?): Any? {
        if (item == null || name == null) return null
        return dmNamedField(item.javaClass, name)?.let { field ->
            runCatching { field.get(item) }.getOrNull()
        }
    }

    private fun dmNonStaticFields(cls: Class<*>): List<Field> {
        return dmNonStaticFieldCache.getOrPut(cls) {
            val fields = ArrayList<Field>(96)
            var current: Class<*>? = cls
            var visited = 0
            while (current != null && current != Any::class.java && visited < 160) {
                runCatching { current.declaredFields.toList() }.getOrDefault(emptyList()).forEach { field ->
                    if (Modifier.isStatic(field.modifiers) || field.isSynthetic || visited++ >= 160) return@forEach
                    runCatching { field.isAccessible = true }
                    fields += field
                }
                current = current.superclass
            }
            fields
        }
    }

    private fun dmNamedField(cls: Class<*>, name: String): Field? {
        val key = "${cls.name}#$name"
        dmNamedFieldCache[key]?.let { return it }
        if (dmNamedFieldMissingCache.contains(key)) return null
        var current: Class<*>? = cls
        while (current != null && current != Any::class.java) {
            runCatching {
                val field = current.getDeclaredField(name)
                field.isAccessible = true
                dmNamedFieldCache[key] = field
                return field
            }
            current = current.superclass
        }
        dmNamedFieldMissingCache.add(key)
        return null
    }

    private fun dmMessageViewModelFields(cls: Class<*>): List<Field> {
        val viewModelClass = dmMessageActionsViewModelClass ?: return emptyList()
        return dmMessageViewModelFieldCache.getOrPut(cls) {
            dmNonStaticFields(cls)
                .asSequence()
                .filter { viewModelClass.isAssignableFrom(it.type) }
                .take(8)
                .toList()
        }
    }

    private fun dmControllerFields(cls: Class<*>): List<Field> {
        val controllerClass = dmMessageActionsControllerClass ?: return emptyList()
        return dmControllerFieldCache.getOrPut(cls) {
            dmNonStaticFields(cls)
                .asSequence()
                .filter { controllerClass.isAssignableFrom(it.type) }
                .take(8)
                .toList()
        }
    }

    private fun dmMenuIconResourceId(context: Context?, action: Int): Int {
        val ctx = context ?: currentActivity ?: androidContext
        val names = when (action) {
            DM_ACTION_DOWNLOAD -> arrayOf("fb_ic_download_outline_24", "fb_ic_photo_download_outline_24")
            DM_ACTION_OPEN_APPS -> arrayOf("fb_ic_share_external_outline_24", "fb_ic_share_android_outline_24")
            DM_ACTION_PREVIEW -> arrayOf("fb_ic_eye_outline_24", "instagram_eye_pano_outline_24")
            DM_ACTION_REPOST -> arrayOf(
                "instagram_reshare_outline_24",
                "instagram_reshare_pano_outline_24",
                "instagram_reshare_pano_filled_24",
                "instagram_reshare_filled_24",
                "fb_ic_reshare_24",
                "fb_ic_reshare_outline_20",
                "fb_ic_reshare_20",
                "groups_reshare_send_icon",
                "fb_ic_share_android_outline_24"
            )
            else -> arrayOf(
                "fb_ic_app_whatsapp_status_plus_outline_24",
                "fb_ic_app_whatsapp_status_outline_20",
                "fb_ic_app_whatsapp_outline_24"
            )
        }
        names.forEach { name ->
            runCatching { ctx.resources.getIdentifier(name, "drawable", ctx.packageName) }
                .getOrDefault(0)
                .takeIf { it != 0 }
                ?.let { return it }
        }
        return when (action) {
            DM_ACTION_DOWNLOAD -> android.R.drawable.stat_sys_download_done
            DM_ACTION_OPEN_APPS -> android.R.drawable.ic_menu_share
            DM_ACTION_PREVIEW -> android.R.drawable.ic_menu_view
            DM_ACTION_REPOST -> android.R.drawable.ic_menu_upload
            else -> android.R.drawable.ic_menu_send
        }
    }

    private fun openDmMediaByPhoneApps(context: Context, url: String, isVideo: Boolean) {
        withExportedDmMedia(context, url, isVideo, { uri ->
            val intent = Intent(Intent.ACTION_VIEW).apply {
                setDataAndType(uri, dmMimeType(url, isVideo))
                applyReadGrant(context, this, uri)
            }
            val chooser = Intent.createChooser(intent, dmActionLabel(DM_ACTION_OPEN_APPS))
            applyReadGrant(context, chooser, uri)
            launchExternal(context, chooser) { openUrlFallback(context, url) }
        }, {
            openUrlFallback(context, url)
        })
    }

    private fun shareDmMediaToPackage(context: Context, url: String, isVideo: Boolean, packageName: String?, errorText: String) {
        withExportedDmMedia(context, url, isVideo, { uri ->
            val intent = buildDmSendIntent(context, uri, dmMimeType(url, isVideo)).apply {
                if (!packageName.isNullOrBlank()) setPackage(packageName)
            }
            launchExternal(context, intent) {
                val chooser = Intent.createChooser(buildDmSendIntent(context, uri, dmMimeType(url, isVideo)), dmActionLabel(DM_ACTION_REPOST))
                applyReadGrant(context, chooser, uri)
                launchExternal(context, chooser) { Toast.makeText(context, errorText, Toast.LENGTH_SHORT).show() }
            }
        }, {
            Toast.makeText(context, errorText, Toast.LENGTH_SHORT).show()
        })
    }

    private fun repostStoryMedia(context: Context, url: String, isVideo: Boolean) {
        withExportedStoryRepostMedia(context, url, isVideo, { uri ->
            val mimeType = if (isVideo) "video/mp4" else "image/jpeg"
            val storyIntent = Intent("com.instagram.share.ADD_TO_STORY").apply {
                setPackage(context.packageName)
                setDataAndType(uri, mimeType)
                putExtra(Intent.EXTRA_STREAM, uri)
                putExtra("interactive_asset_uri", uri)
                putExtra("top_background_color", "#000000")
                putExtra("bottom_background_color", "#000000")
                applyReadGrant(context, this, uri)
            }
            launchExternal(context, storyIntent) {
                val fallback = buildDmSendIntent(context, uri, mimeType).apply {
                    setPackage(context.packageName)
                }
                launchExternal(context, fallback) {
                    Toast.makeText(context, "Story repost failed", Toast.LENGTH_SHORT).show()
                }
            }
        }, {
            Toast.makeText(context, "Story repost failed", Toast.LENGTH_SHORT).show()
        })
    }

    private fun shareDmMediaToWhatsAppStory(context: Context, url: String, isVideo: Boolean) {
        withExportedDmMedia(context, url, isVideo, { uri ->
            val whatsapp = buildDmSendIntent(context, uri, dmMimeType(url, isVideo)).apply {
                setPackage("com.whatsapp")
                putExtra("jid", "status@broadcast")
            }
            launchExternal(context, whatsapp) {
                val business = buildDmSendIntent(context, uri, dmMimeType(url, isVideo)).apply {
                    setPackage("com.whatsapp.w4b")
                    putExtra("jid", "status@broadcast")
                }
                launchExternal(context, business) {
                    Toast.makeText(context, "WhatsApp share failed", Toast.LENGTH_SHORT).show()
                }
            }
        }, {
            Toast.makeText(context, "WhatsApp share failed", Toast.LENGTH_SHORT).show()
        })
    }

    private fun withExportedDmMedia(
        context: Context,
        url: String,
        isVideo: Boolean,
        onReady: (Uri) -> Unit,
        onError: () -> Unit
    ) {
        Thread({
            runCatching { createExportedDmMediaUri(context, url, isVideo) }
                .onSuccess { uri -> mainHandler.post { onReady(uri) } }
                .onFailure {
                    logError("DM context media export failed", it)
                    mainHandler.post(onError)
                }
        }, "PurrfectInstaDmExport").start()
    }

    private fun withExportedStoryRepostMedia(
        context: Context,
        url: String,
        isVideo: Boolean,
        onReady: (Uri) -> Unit,
        onError: () -> Unit
    ) {
        Thread({
            runCatching { createExportedStoryRepostUri(context, url, isVideo) }
                .onSuccess { uri -> mainHandler.post { onReady(uri) } }
                .onFailure {
                    logError("Story repost media export failed", it)
                    mainHandler.post(onError)
                }
        }, "PurrfectInstaStoryRepostExport").start()
    }

    private fun createExportedStoryRepostUri(context: Context, url: String, isVideo: Boolean): Uri {
        val mimeType = if (isVideo) "video/mp4" else "image/jpeg"
        val extension = if (isVideo) "mp4" else "jpg"
        val filename = buildDownloadFilename(url, DownloadMetadata(username = "story", type = "repost"), extension)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
                put(MediaStore.MediaColumns.MIME_TYPE, mimeType)
                put(
                    MediaStore.MediaColumns.RELATIVE_PATH,
                    (if (isVideo) Environment.DIRECTORY_MOVIES else Environment.DIRECTORY_PICTURES) + "/PurrfectInsta/Story Repost"
                )
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
            val collection = if (isVideo) MediaStore.Video.Media.EXTERNAL_CONTENT_URI else MediaStore.Images.Media.EXTERNAL_CONTENT_URI
            val itemUri = context.contentResolver.insert(collection, values)
                ?: error("MediaStore insert failed")
            try {
                context.contentResolver.openOutputStream(itemUri)?.use { out -> downloadToStream(url, out) }
                    ?: error("MediaStore output stream unavailable")
            } catch (throwable: Throwable) {
                runCatching { context.contentResolver.delete(itemUri, null, null) }
                throw throwable
            }
            ContentValues().apply {
                put(MediaStore.MediaColumns.IS_PENDING, 0)
                context.contentResolver.update(itemUri, this, null, null)
            }
            return itemUri
        }

        val root = Environment.getExternalStoragePublicDirectory(if (isVideo) Environment.DIRECTORY_MOVIES else Environment.DIRECTORY_PICTURES)
        val dir = File(root, "PurrfectInsta/Story Repost")
        if (!dir.exists() && !dir.mkdirs()) error("Cannot create export folder")
        val file = File(dir, filename)
        java.io.FileOutputStream(file).use { out -> downloadToStream(url, out) }
        file.setReadable(true, false)
        disableFileUriExposure()
        return Uri.fromFile(file)
    }

    private fun createExportedDmMediaUri(context: Context, url: String, isVideo: Boolean): Uri {
        val mimeType = dmMimeType(url, isVideo)
        val filename = "purrfect_insta_dm_${System.currentTimeMillis()}.${extensionForUrl(url)}"
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
                put(MediaStore.MediaColumns.MIME_TYPE, mimeType)
                put(
                    MediaStore.MediaColumns.RELATIVE_PATH,
                    (if (isVideo) Environment.DIRECTORY_MOVIES else Environment.DIRECTORY_PICTURES) + "/PurrfectInsta/DM Context"
                )
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
            val collection = if (isVideo) MediaStore.Video.Media.EXTERNAL_CONTENT_URI else MediaStore.Images.Media.EXTERNAL_CONTENT_URI
            val itemUri = context.contentResolver.insert(collection, values)
                ?: error("MediaStore insert failed")
            try {
                context.contentResolver.openOutputStream(itemUri)?.use { out -> downloadToStream(url, out) }
                    ?: error("MediaStore output stream unavailable")
            } catch (throwable: Throwable) {
                runCatching { context.contentResolver.delete(itemUri, null, null) }
                throw throwable
            }
            ContentValues().apply {
                put(MediaStore.MediaColumns.IS_PENDING, 0)
                context.contentResolver.update(itemUri, this, null, null)
            }
            return itemUri
        }

        val root = Environment.getExternalStoragePublicDirectory(if (isVideo) Environment.DIRECTORY_MOVIES else Environment.DIRECTORY_PICTURES)
        val dir = File(root, "PurrfectInsta/DM Context")
        if (!dir.exists() && !dir.mkdirs()) error("Cannot create export folder")
        val file = File(dir, filename)
        java.io.FileOutputStream(file).use { out -> downloadToStream(url, out) }
        file.setReadable(true, false)
        disableFileUriExposure()
        return Uri.fromFile(file)
    }

    private fun downloadToStream(url: String, output: OutputStream) {
        val connection = URL(url).openConnection() as HttpURLConnection
        connection.connectTimeout = 15_000
        connection.readTimeout = 30_000
        connection.instanceFollowRedirects = true
        connection.setRequestProperty("User-Agent", "Instagram 300.0.0.0 Android")
        connection.setRequestProperty("Accept", "video/*,image/*,*/*")
        connection.setRequestProperty("Referer", "https://www.instagram.com/")
        try {
            val code = connection.responseCode
            if (code >= 400) {
                logInfo("Instagram media download HTTP $code url=${redactCdnUrlForLog(url)}")
                error("HTTP $code")
            }
            connection.inputStream.use { input -> copyStream(input, output) }
        } finally {
            connection.disconnect()
        }
    }

    private fun copyStream(input: InputStream, output: OutputStream) {
        val buffer = ByteArray(64 * 1024)
        while (true) {
            val read = input.read(buffer)
            if (read == -1) break
            output.write(buffer, 0, read)
        }
    }

    private fun buildDmSendIntent(context: Context, uri: Uri, mimeType: String): Intent {
        return Intent(Intent.ACTION_SEND).apply {
            type = mimeType
            putExtra(Intent.EXTRA_STREAM, uri)
            applyReadGrant(context, this, uri)
        }
    }

    private fun applyReadGrant(context: Context, intent: Intent, uri: Uri) {
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION)
        runCatching {
            intent.clipData = ClipData.newUri(context.contentResolver, "PurrfectInsta media", uri)
        }
        runCatching {
            context.grantUriPermission(context.packageName, uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
    }

    private fun launchExternal(context: Context, intent: Intent, onError: () -> Unit) {
        val launchContext = context.applicationContext ?: context
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        mainHandler.postDelayed({
            runCatching { launchContext.startActivity(intent) }
                .onFailure {
                    logError("DM context launch failed", it)
                    onError()
                }
        }, 350L)
    }

    private fun openUrlFallback(context: Context, url: String) {
        runCatching {
            val chooser = Intent.createChooser(Intent(Intent.ACTION_VIEW, Uri.parse(url)), dmActionLabel(DM_ACTION_OPEN_APPS))
            launchExternal(context, chooser) {
                Toast.makeText(context, "Cannot open media", Toast.LENGTH_SHORT).show()
            }
        }.onFailure {
            Toast.makeText(context, "Cannot open media", Toast.LENGTH_SHORT).show()
        }
    }

    private fun dmMimeType(url: String, isVideo: Boolean): String {
        val detected = mimeTypeForUrl(url)
        return when {
            detected != "application/octet-stream" -> detected
            isVideo -> "video/mp4"
            else -> "image/jpeg"
        }
    }

    private fun disableFileUriExposure() {
        runCatching {
            val vmRuntime = Class.forName("android.os.StrictMode").getMethod("disableDeathOnFileUriExposure")
            vmRuntime.invoke(null)
        }
    }

    private fun dmContextFromPopup(popup: Any?): Context? {
        if (popup is PopupWindow) popup.contentView?.context?.let { return it }
        return findContextInObjectGraph(popup) ?: currentActivity ?: androidContext
    }

    private fun dmActionLabel(action: Int): String {
        return dmActionLabels.getOrNull(action) ?: "Action"
    }

    private fun loadDmMenuIcon(context: Context?, action: Int): Drawable? {
        val ctx = context ?: currentActivity ?: androidContext
        val names = when (action) {
            DM_ACTION_DOWNLOAD -> arrayOf("fb_ic_download_outline_24", "fb_ic_photo_download_outline_24")
            DM_ACTION_OPEN_APPS -> arrayOf("fb_ic_share_external_outline_24", "fb_ic_share_android_outline_24")
            DM_ACTION_PREVIEW -> arrayOf("fb_ic_eye_outline_24", "instagram_eye_pano_outline_24")
            DM_ACTION_REPOST -> arrayOf(
                "instagram_reshare_outline_24",
                "instagram_reshare_pano_outline_24",
                "instagram_reshare_pano_filled_24",
                "instagram_reshare_filled_24",
                "fb_ic_reshare_24",
                "fb_ic_reshare_outline_20",
                "fb_ic_reshare_20",
                "groups_reshare_send_icon",
                "fb_ic_share_android_outline_24"
            )
            else -> arrayOf(
                "fb_ic_app_whatsapp_status_plus_outline_24",
                "fb_ic_app_whatsapp_status_outline_20",
                "fb_ic_app_whatsapp_outline_24"
            )
        }
        names.forEach { name ->
            val id = runCatching { ctx.resources.getIdentifier(name, "drawable", ctx.packageName) }.getOrDefault(0)
            if (id != 0) {
                return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                    ctx.resources.getDrawable(id, ctx.theme)
                } else {
                    @Suppress("DEPRECATION")
                    ctx.resources.getDrawable(id)
                }
            }
        }
        val fallback = when (action) {
            DM_ACTION_DOWNLOAD -> android.R.drawable.stat_sys_download_done
            DM_ACTION_OPEN_APPS -> android.R.drawable.ic_menu_share
            DM_ACTION_PREVIEW -> android.R.drawable.ic_menu_view
            DM_ACTION_REPOST -> android.R.drawable.ic_menu_upload
            else -> android.R.drawable.ic_menu_send
        }
        return runCatching {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                ctx.resources.getDrawable(fallback, ctx.theme)
            } else {
                @Suppress("DEPRECATION")
                ctx.resources.getDrawable(fallback)
            }
        }.getOrNull()
    }

    private fun looksLikeDirectVisualMessageMenu(items: List<*>): Boolean {
        var hasVisualMessage = false
        var hasViewPhoto = false
        var hasVisualAction = false
        items.forEach { item ->
            val wire = extractLongPressActionWire(item)?.lowercase(Locale.US).orEmpty()
            if (!wire.contains("voice") && !wire.contains("audio")) {
                when (wire) {
                    "camera_reply_for_expiring_media", "report_bug_for_vm" -> hasVisualAction = true
                }
                if (wire.contains("visual") ||
                    wire.contains("photo") ||
                    wire.contains("video") ||
                    wire.contains("media") ||
                    wire.contains("raven") ||
                    wire.contains("clip") ||
                    wire.contains("reel")
                ) {
                    hasVisualAction = true
                }
            }
            val label = extractDmMenuLabel(item)?.lowercase(Locale.US) ?: return@forEach
            if (label.contains("visual") && label.contains("message")) hasVisualMessage = true
            if (label.contains("view photo") ||
                label.contains("view video") ||
                label.contains("view media") ||
                label.contains("save photo") ||
                label.contains("save video") ||
                label.contains("save media")
            ) {
                hasViewPhoto = true
            }
        }
        return hasVisualMessage || hasViewPhoto || hasVisualAction
    }

    private fun looksLikeDirectVoiceMessageMenu(items: List<*>): Boolean {
        return items.any { item ->
            val label = extractDmMenuLabel(item)?.lowercase(Locale.US).orEmpty()
            val wire = extractLongPressActionWire(item)?.lowercase(Locale.US).orEmpty()
            label.contains("voice") ||
                label.contains("audio") ||
                label.contains("transcription") ||
                wire.contains("voice") ||
                wire.contains("audio")
        }
    }

    private fun dmActionLabelsForLog(actions: List<Int>): String {
        return actions.joinToString("|") { dmActionLabel(it) }
    }

    private fun dmMenuLabelsForLog(items: List<*>): String {
        return items.asSequence()
            .mapNotNull { extractDmMenuLabel(it)?.trim()?.takeIf { label -> label.isNotBlank() } }
            .take(8)
            .joinToString("|")
            .ifBlank { "-" }
    }

    private fun extractLongPressActionWire(item: Any?): String? {
        val actionClass = dmLongPressActionDataClass ?: return null
        if (item == null || !actionClass.isInstance(item)) return null
        return enumWireField(item, "A04")
    }

    private fun hasInjectedDmItems(context: Context?, items: List<*>): Boolean {
        val labels = (DM_ACTION_DOWNLOAD..DM_ACTION_WHATSAPP_STORY).map { dmActionLabel(it) }.toSet()
        return items.any { item -> extractDmMenuLabel(item)?.let { it in labels } == true }
    }

    private fun extractDmMenuLabel(item: Any?): String? {
        if (item == null) return null
        listOf("A07", "A0G", "A03").forEach { name ->
            stringField(item, name)?.takeIf { it.isNotBlank() }?.let { return it }
        }
        item.javaClass.declaredFields.forEach { field ->
            if (field.type != String::class.java) return@forEach
            runCatching {
                field.isAccessible = true
                field.get(item) as? String
            }.getOrNull()?.takeIf { it.isNotBlank() }?.let { return it }
        }
        return null
    }

    private fun stringField(item: Any?, name: String): String? {
        if (item == null) return null
        return runCatching {
            val field = item.javaClass.getDeclaredField(name)
            field.isAccessible = true
            field.get(item) as? String
        }.getOrNull()
    }

    private fun hasDeclaredStringField(cls: Class<*>, name: String): Boolean {
        return runCatching { cls.getDeclaredField(name).type == String::class.java }.getOrDefault(false)
    }

    private fun findConstructor(cls: Class<*>, parameterCount: Int): Constructor<*>? {
        return cls.declaredConstructors.firstOrNull { it.parameterTypes.size == parameterCount }?.apply { isAccessible = true }
    }

    private fun loadFirstClass(vararg classNames: String): Class<*>? {
        return classNames.firstNotNullOfOrNull { name ->
            runCatching { Class.forName(name, false, appClassLoader) }.getOrNull()
        }
    }

    private fun installStoryMentionHook() {
        runSafe("Story mention hook") {
            val buttonMethod = (if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethod("MentionButton", appClassLoader)
            } else {
                null
            }) ?: dexBridge.findMethodsUsingStrings("[INTERNAL] Pause Playback")
                .firstOrNull { method ->
                    method.returnType.isArray &&
                        CharSequence::class.java.isAssignableFrom(method.returnType.componentType)
                }?.also { InstagramDexKitCache.saveMethod("MentionButton", it) }
            buttonMethod?.let { method ->
                method.isAccessible = true
                val signature = "${method.declaringClass.name}.${method.name}:mentions-button"
                if (hookedDexMethods.add(signature)) {
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun afterHookedMethod(param: MethodHookParam<*>) {
                                if (!state.enableStoryMentions) return
                                val original = param.result as? Array<*> ?: return
                                if (original.any { it?.toString() == "View Mentions" }) return
                                param.result = original.map { it as? CharSequence ?: it.toString() }
                                    .plus("View Mentions")
                                    .toTypedArray<CharSequence>()
                            }
                        }
                    )
                }
            }

            val clickMethod = (if (InstagramDexKitCache.isCacheValid()) {
                InstagramDexKitCache.loadMethod("MentionClick", appClassLoader)
            } else {
                null
            }) ?: dexBridge.findMethodsUsingStrings(
                "explore_viewer",
                "friendships/mute_friend_reel/%s/",
                "[INTERNAL] Pause Playback"
            ).firstOrNull { it.returnType == java.lang.Void.TYPE }?.also { InstagramDexKitCache.saveMethod("MentionClick", it) }
                ?: return@runSafe
            clickMethod.isAccessible = true
            val clickSignature = "${clickMethod.declaringClass.name}.${clickMethod.name}:mentions-click"
            if (!hookedDexMethods.add(clickSignature)) return@runSafe
            XposedBridge.hookMethod(
                clickMethod,
                object : XC_MethodHook() {
                    override fun beforeHookedMethod(param: MethodHookParam<*>) {
                        if (!state.enableStoryMentions) return
                        val tapped = param.args.firstOrNull { it is CharSequence }?.toString() ?: return
                        if (tapped != "View Mentions") return
                        param.result = null
                        val media = findMediaObject(param.thisObject) ?: param.args.firstNotNullOfOrNull { findMediaObject(it) }
                        val context = findContextInObjectGraph(param.thisObject)
                            ?: param.args.firstNotNullOfOrNull { findContextInObjectGraph(it) }
                            ?: currentActivity
                            ?: androidContext
                        resolveStoryMentionGetters()
                        showMentionsDialog(context, resolveStoryMentionsFromSources(media, param.thisObject, param.args))
                    }
                }
            )
        }
    }

    private fun resolveStoryMentionGetters() {
        if (storyMentionGetterCandidates.isNotEmpty()) return
        if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.loadMethods("MentionGetter", appClassLoader)
                ?.takeIf { it.isNotEmpty() }
                ?.let { cached ->
                    storyMentionGetterCandidates.addAll(cached)
                    storyMentionGetterMethod = cached.firstOrNull()
                    logInfo("Loaded story mention getters from cache=${cached.size}")
                    return
                }
            if (InstagramDexKitCache.loadString("MentionGetter_missing_v1") == "1") {
                logInfo("Story mention getter discovery skipped; cached missing")
                return
            }
        }
        dexBridge.findMethodsUsingStrings("Required value was null.")
            .filter { method ->
                method.declaringClass.name == "com.instagram.feed.media.MediaExtKt" &&
                    method.returnType == java.util.List::class.java &&
                    method.parameterTypes.size == 1
            }
            .forEach { method ->
                method.isAccessible = true
                if (storyMentionGetterCandidates.none { it.declaringClass.name == method.declaringClass.name && it.name == method.name && it.parameterTypes.contentEquals(method.parameterTypes) }) {
                    storyMentionGetterCandidates += method
                }
            }
        storyMentionGetterMethod = storyMentionGetterCandidates.firstOrNull()
        if (storyMentionGetterCandidates.isNotEmpty()) {
            InstagramDexKitCache.saveMethods("MentionGetter", storyMentionGetterCandidates.toList())
            if (InstagramDexKitCache.isCacheValid()) InstagramDexKitCache.saveString("MentionGetter_missing_v1", "0")
        } else if (InstagramDexKitCache.isCacheValid()) {
            InstagramDexKitCache.saveString("MentionGetter_missing_v1", "1")
            logInfo("Story mention getter discovery found no candidates")
        }
    }

    private fun resolveStoryMentions(media: Any?): List<String> {
        if (media == null) return emptyList()
        val candidates = synchronized(storyMentionGetterCandidates) { storyMentionGetterCandidates.toList() }
        if (candidates.isEmpty()) return emptyList()
        if (storyMentionGetterMethod == null || storyMentionGetterMethod == candidates.firstOrNull()) {
            candidates.forEach { candidate ->
                val probe = runCatching { candidate.invoke(null, media) as? List<*> }.getOrNull()
                val first = probe?.firstOrNull()
                if (first != null && first !is String) {
                    storyMentionGetterMethod = candidate
                    return@forEach
                }
            }
        }
        val result = runCatching { storyMentionGetterMethod?.invoke(null, media) as? List<*> }.getOrNull().orEmpty()
        return result.mapNotNull { item ->
            when (item) {
                null, is String -> null
                else -> usernameFromUserObject(item)
            }
        }.distinct()
    }

    private fun resolveStoryMentionsFromSources(vararg roots: Any?): List<String> {
        val output = linkedSetOf<String>()
        var getterCount = 0
        var mediaCount = 0
        roots.forEach { root ->
            findStoryMentionMediaObject(root)?.let { media ->
                mediaCount++
                val mentions = resolveStoryMentions(media)
                getterCount += mentions.size
                output += mentions
            }
        }
        val resolved = output
            .mapNotNull { normalizeUsername(it).takeIf(String::isNotBlank) }
            .distinct()
        logInfo("Story mentions resolved total=${resolved.size} getter=$getterCount media=$mediaCount getters=${storyMentionGetterCandidates.size} result=${resolved.joinToString(limit = 6)}")
        return resolved
    }

    private fun findStoryMentionMediaObject(root: Any?): Any? {
        val visited = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun scan(value: Any?, depth: Int): Any? {
            if (value == null || depth > 6 || !visited.add(value)) return null
            val className = value.javaClass.name
            if (className == "com.instagram.feed.media.Media") return value
            if (!className.startsWith("com.instagram.") &&
                !className.startsWith("com.facebook.") &&
                !className.startsWith("X.") &&
                !className.startsWith("p000X.")
            ) return null
            var cls: Class<*>? = value.javaClass
            while (cls != null && cls != Any::class.java) {
                cls.declaredFields.forEach { field ->
                    if (Modifier.isStatic(field.modifiers) || field.type.isPrimitive || field.type.isArray) return@forEach
                    runCatching {
                        field.isAccessible = true
                        val child = field.get(value) ?: return@runCatching null
                        if (child.javaClass.name == "com.instagram.feed.media.Media") return child
                        scan(child, depth + 1)
                    }.getOrNull()?.let { return it }
                }
                cls = cls.superclass
            }
            return null
        }
        return scan(root, 0)
    }

    private fun collectVisibleStoryOwnerCandidates(): Set<String> {
        val root = currentActivity?.window?.decorView ?: return emptySet()
        val output = linkedSetOf<String>()
        fun addFromText(raw: CharSequence?) {
            val text = raw?.toString()?.trim().orEmpty()
            if (text.isBlank()) return
            normalizeUsername(text).takeIf(String::isNotBlank)?.let {
                output += it
                return
            }
            val firstToken = text.split(Regex("\\s+")).firstOrNull().orEmpty()
            normalizeUsername(firstToken).takeIf(String::isNotBlank)?.let { output += it }
        }
        fun scan(view: View, depth: Int) {
            if (depth > 6 || output.size >= 4) return
            if (view is TextView) {
                addFromText(view.text)
                addFromText(view.contentDescription)
            }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) scan(view.getChildAt(i), depth + 1)
            }
        }
        scan(root, 0)
        return output
    }

    private fun collectVisibleStoryMentionCandidates(): List<String> {
        val root = currentActivity?.window?.decorView ?: return emptyList()
        val output = linkedSetOf<String>()
        fun scan(view: View, depth: Int) {
            if (depth > 8 || output.size >= 12) return
            if (view is TextView) output += extractMentionUsernamesFromText(view.text?.toString(), visibleText = true)
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) scan(view.getChildAt(i), depth + 1)
            }
        }
        scan(root, 0)
        return output.toList()
    }

    private fun collectStoryMentionCandidatesFromObject(root: Any?): List<String> {
        val output = linkedSetOf<String>()
        val traces = mutableListOf<String>()
        val visited = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun addCandidate(username: String?, source: String) {
            val clean = username?.let(::normalizeUsername).orEmpty()
            if (!isLikelyStoryMentionUsername(clean)) return
            if (output.add(clean) && traces.size < 10) {
                traces += "$clean<$source>"
            }
        }
        fun contextLooksLikeMention(text: String): Boolean {
            val lower = text.lowercase(Locale.US)
            return lower.contains("mention") ||
                lower.contains("tag") ||
                lower.contains("tappable") ||
                lower.contains("sticker") ||
                lower.contains("overlay") ||
                lower.contains("attribution") ||
                lower.contains("reelitem")
        }
        fun contextLooksLikeUser(text: String): Boolean {
            val lower = text.lowercase(Locale.US)
            return lower.contains("username") ||
                lower.contains("user_name") ||
                lower.endsWith(".user") ||
                lower.endsWith("user") ||
                lower.contains(".user.")
        }
        fun scan(value: Any?, depth: Int, hint: String) {
            if (value == null || depth > 8 || output.size >= 16) return
            if (value is String) {
                val mentionContext = contextLooksLikeMention(hint)
                val userContext = contextLooksLikeUser(hint)
                if (value.contains("@") || mentionContext || userContext) {
                    extractMentionUsernamesFromText(value, visibleText = false, allowBare = mentionContext || userContext)
                        .forEach { addCandidate(it, "string:$hint") }
                }
                return
            }
            if (!visited.add(value) || !shouldInspectObject(value.javaClass)) return
            val className = value.javaClass.name
            val nextHint = if (hint.isBlank()) className else "$hint.${className.substringAfterLast('.')}"
            val mentionLikeObject = contextLooksLikeMention(nextHint)
            if (mentionLikeObject) addCandidate(usernameFromUserObject(value), "object:$nextHint")
            if (value is Iterable<*>) {
                value.take(40).forEach { scan(it, depth + 1, nextHint) }
                return
            }
            if (value is Map<*, *>) {
                value.entries.take(40).forEach { entry ->
                    scan(entry.key, depth + 1, "$nextHint.key")
                    scan(entry.value, depth + 1, "$nextHint.value")
                }
                return
            }
            if (value.javaClass.isArray) {
                val count = java.lang.reflect.Array.getLength(value).coerceAtMost(40)
                for (i in 0 until count) scan(java.lang.reflect.Array.get(value, i), depth + 1, nextHint)
                return
            }
            var cls: Class<*>? = value.javaClass
            var fields = 0
            while (cls != null && cls != Any::class.java && fields < 140) {
                cls.declaredFields.forEach { field ->
                    if (fields++ >= 140 || Modifier.isStatic(field.modifiers) || field.type.isPrimitive) return@forEach
                    runCatching {
                        field.isAccessible = true
                        scan(field.get(value), depth + 1, "$nextHint.${field.name}")
                    }
                }
                cls = cls.superclass
            }
        }
        scan(root, 0, "")
        if (traces.isNotEmpty()) logInfo("Story mention candidates ${traces.joinToString(limit = 10)}")
        return output.toList()
    }

    private fun extractMentionUsernamesFromText(raw: String?, visibleText: Boolean): List<String> {
        return extractMentionUsernamesFromText(raw, visibleText, allowBare = false)
    }

    private fun extractMentionUsernamesFromText(raw: String?, visibleText: Boolean, allowBare: Boolean): List<String> {
        val text = raw?.trim().orEmpty()
        if (text.length !in 2..300) return emptyList()
        val mentionLike = text.contains("@") ||
            text.contains(" and ", ignoreCase = true) ||
            text.contains("\n") ||
            text.contains(",")
        if (!mentionLike && !allowBare) return emptyList()
        val output = linkedSetOf<String>()
        Regex("@?([A-Za-z0-9._]{2,30})").findAll(text).forEach { match ->
            val token = normalizeUsername(match.groupValues[1])
            if (token.isBlank()) return@forEach
            val lower = token.lowercase(Locale.US)
            if (!isLikelyStoryMentionUsername(token)) return@forEach
            if (lower in setOf("and", "with", "from", "watch", "full", "reel", "story", "mention", "mentions", "profile", "username")) return@forEach
            if (visibleText && !match.value.startsWith("@") && !token.contains('_') && !token.contains('.')) return@forEach
            if (!allowBare && !mentionLike) return@forEach
            output += token
        }
        return output.toList()
    }

    private fun isLikelyStoryMentionUsername(username: String): Boolean {
        val clean = normalizeUsername(username)
        if (clean.isBlank()) return false
        if (clean.length < 3) return false
        val lower = clean.lowercase(Locale.US).trim('\u200e', '\u200f', ' ')
        if (lower in setOf(
                "en", "in", "us", "uk", "ig", "id", "ar", "de", "es", "fr", "hi", "pt", "ru", "tr",
                "true", "false", "null", "none", "http", "https", "com", "www"
            )
        ) return false
        return true
    }

    private fun usernameFromUserObject(user: Any): String? {
        listOf("getUsername", "getUserName", "Aso", "BKR").forEach { methodName ->
            runCatching {
                val method = user.javaClass.methods.firstOrNull { it.name == methodName && it.parameterTypes.isEmpty() && it.returnType == String::class.java }
                method?.invoke(user) as? String
            }.getOrNull()?.takeIf { isValidInstagramUsername(it) }?.let { return it }
        }
        user.javaClass.declaredMethods.forEach { method ->
            if (method.parameterTypes.isNotEmpty() || method.returnType != String::class.java) return@forEach
            runCatching {
                method.isAccessible = true
                method.invoke(user) as? String
            }.getOrNull()?.takeIf { isValidInstagramUsername(it) }?.let {
                userUsernameGetter = method
                InstagramDexKitCache.saveMethod("UsernameGetter", method)
                return it
            }
        }
        user.javaClass.declaredFields.forEach { field ->
            if (field.type != String::class.java) return@forEach
            val name = field.name.lowercase(Locale.US)
            if (!name.contains("username") && name !in setOf("bkr", "aso", "a0b", "a0c")) return@forEach
            runCatching {
                field.isAccessible = true
                field.get(user) as? String
            }.getOrNull()?.takeIf { isValidInstagramUsername(it) }?.let { return it }
        }
        return null
    }

    private fun isValidInstagramUsername(value: String?): Boolean {
        val text = value.orEmpty()
        return text.matches(Regex("^[a-z0-9._]{2,30}$"))
    }

    private fun showMentionsDialog(context: Context, usernames: List<String>) {
        mainHandler.post {
            val dialogContext = findActivity(context) ?: currentActivity
            if (dialogContext == null || dialogContext.isFinishing) {
                Toast.makeText(context, if (usernames.isEmpty()) "No mentions found" else usernames.joinToString(", ") { "@$it" }, Toast.LENGTH_SHORT).show()
                return@post
            }
            showStoryMentionsBottomSheet(dialogContext, usernames)
        }
    }

    private fun showStoryMentionsBottomSheet(context: Activity, usernames: List<String>) {
        val density = context.resources.displayMetrics.density
        val dark = (context.resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
        val sheetBg = if (dark) Color.parseColor("#1C1C1E") else Color.parseColor("#F2F2F7")
        val cardBg = if (dark) Color.parseColor("#2C2C2E") else Color.WHITE
        val textPrimary = if (dark) Color.WHITE else Color.parseColor("#1C1C1E")
        val textSecondary = if (dark) Color.parseColor("#AEAEB2") else Color.parseColor("#6C6C70")
        val accentBg = Color.parseColor("#0A84FF")
        val secondaryBg = if (dark) Color.parseColor("#3A3A3C") else Color.parseColor("#E5E5EA")
        val handleColor = if (dark) Color.parseColor("#48484A") else Color.parseColor("#C7C7CC")
        val dialog = Dialog(context).apply { requestWindowFeature(Window.FEATURE_NO_TITLE) }
        val sheet = LinearLayout(context).apply {
            orientation = LinearLayout.VERTICAL
            background = roundedDrawable(sheetBg, 20f)
            val horizontal = (20 * density).roundToInt()
            setPadding(horizontal, (12 * density).roundToInt(), horizontal, (28 * density).roundToInt())
        }
        sheet.addView(View(context).apply {
            background = roundedDrawable(handleColor, 2f)
            layoutParams = LinearLayout.LayoutParams((40 * density).roundToInt(), (4 * density).roundToInt()).apply {
                gravity = Gravity.CENTER_HORIZONTAL
                bottomMargin = (16 * density).roundToInt()
            }
        })
        sheet.addView(TextView(context).apply {
            text = "Story Mentions"
            setTextColor(textPrimary)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)
            typeface = Typeface.DEFAULT_BOLD
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = (4 * density).roundToInt()
            }
        })
        sheet.addView(TextView(context).apply {
            text = if (usernames.isEmpty()) "No mentions found in this story" else "${usernames.size} mention(s)"
            setTextColor(textSecondary)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = (14 * density).roundToInt()
            }
        })
        if (usernames.isNotEmpty()) {
            val list = LinearLayout(context).apply { orientation = LinearLayout.VERTICAL }
            usernames.forEach { username ->
                list.addView(makeStoryMentionRow(context, dialog, username, cardBg, secondaryBg, textPrimary, density))
            }
            sheet.addView(ScrollView(context).apply {
                addView(list)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            })
            sheet.addView(makeDownloadPillButton(context, "Copy all", accentBg, Color.WHITE, density).apply {
                setOnClickListener {
                    dialog.dismiss()
                    copyTextToClipboard(context, "Story mentions", usernames.joinToString("\n") { "@$it" }, "Mentions copied")
                }
            })
        }
        dialog.setContentView(sheet)
        dialog.window?.let { window ->
            window.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
            window.setGravity(Gravity.BOTTOM)
            window.setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.WRAP_CONTENT)
            val attrs = window.attributes
            val margin = (12 * density).roundToInt()
            attrs.x = margin
            attrs.y = margin
            window.attributes = attrs
        }
        dialog.show()
    }

    private fun makeStoryMentionRow(
        context: Context,
        dialog: Dialog,
        username: String,
        cardBg: Int,
        copyBg: Int,
        textColor: Int,
        density: Float
    ): View {
        return LinearLayout(context).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            background = roundedDrawable(cardBg, 12f)
            val pad = (12 * density).roundToInt()
            setPadding(pad, pad, pad, pad)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = (8 * density).roundToInt()
            }
            isClickable = true
            setOnClickListener {
                dialog.dismiss()
                openInstagramProfile(context, username)
            }
            addView(TextView(context).apply {
                text = "@$username"
                setTextColor(textColor)
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 15f)
                typeface = Typeface.DEFAULT_BOLD
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            addView(Button(context).apply {
                text = "Copy"
                setAllCaps(false)
                setTextColor(textColor)
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)
                background = roundedDrawable(copyBg, 10f)
                minHeight = 0
                minWidth = 0
                setPadding((14 * density).roundToInt(), (8 * density).roundToInt(), (14 * density).roundToInt(), (8 * density).roundToInt())
                setOnClickListener {
                    copyTextToClipboard(context, "username", "@$username", "@$username copied")
                }
            })
        }
    }

    private fun openInstagramProfile(context: Context, username: String) {
        val clean = normalizeUsername(username)
        if (clean.isBlank()) return
        val appIntent = Intent(Intent.ACTION_VIEW, Uri.parse("instagram://user?username=$clean")).apply {
            setPackage("com.instagram.android")
            putExtra(EXTRA_INTERNAL_PROFILE_OPEN, true)
            if (context !is Activity) addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        runCatching { context.startActivity(appIntent) }
            .onFailure {
                val fallback = Intent(Intent.ACTION_VIEW, Uri.parse("https://www.instagram.com/_u/$clean/")).apply {
                    setPackage("com.instagram.android")
                    putExtra(EXTRA_INTERNAL_PROFILE_OPEN, true)
                    if (context !is Activity) addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                runCatching { context.startActivity(fallback) }
            }
    }

    private fun showConfirmRefreshDialog(surface: String, onConfirm: () -> Unit, onCancel: () -> Unit) {
        mainHandler.post {
            val activity = currentActivity
            if (activity == null || activity.isFinishing) {
                onCancel()
                return@post
            }
            val surfaceLabel = if (surface == "feed") "Refresh feed" else "Refresh reels"
            AlertDialog.Builder(activity)
                .setTitle("Confirm refresh")
                .setMessage("Refresh ${if (surface == "feed") "feed" else "reels"}?")
                .setPositiveButton(surfaceLabel) { _, _ -> onConfirm() }
                .setNegativeButton(android.R.string.cancel) { _, _ -> onCancel() }
                .setOnCancelListener { onCancel() }
                .show()
        }
    }

    private fun allowRefreshSurface(surface: String, windowMs: Long) {
        val until = System.currentTimeMillis() + windowMs.coerceAtLeast(1_000L)
        if (surface == "feed") allowFeedRefreshUntilMs = until else allowReelsRefreshUntilMs = until
    }

    private fun isRefreshAllowed(surface: String): Boolean {
        val now = System.currentTimeMillis()
        return if (surface == "feed") now <= allowFeedRefreshUntilMs else now <= allowReelsRefreshUntilMs
    }

    private fun isRefreshDialogPending(surface: String): Boolean {
        return if (surface == "feed") feedRefreshDialogPending else reelsRefreshDialogPending
    }

    private fun setRefreshDialogPending(surface: String, pending: Boolean) {
        if (surface == "feed") feedRefreshDialogPending = pending else reelsRefreshDialogPending = pending
    }

    private fun setRefreshing(refreshView: Any?, refreshing: Boolean) {
        runCatching {
            refreshView?.javaClass?.methods
                ?.firstOrNull { it.name == "setRefreshing" && it.parameterTypes.contentEquals(arrayOf(java.lang.Boolean.TYPE)) }
                ?.invoke(refreshView, refreshing)
        }
    }

    private fun clearVisibleRefreshSpinners(activity: Activity?) {
        val root = activity?.window?.decorView ?: return
        fun visit(view: View, depth: Int) {
            if (depth > 10) return
            setRefreshing(view, false)
            if (view is ViewGroup) {
                val count = view.childCount.coerceAtMost(120)
                for (i in 0 until count) visit(view.getChildAt(i), depth + 1)
            }
        }
        visit(root, 0)
    }

    private fun surfaceForRefreshView(view: View?): String? {
        val haystack = refreshHierarchySignal(view)
        if (haystack.contains("direct") || haystack.contains("inbox") || haystack.contains("message_list") ||
            haystack.contains("search") || haystack.contains("profile")
        ) {
            return null
        }
        if (haystack.contains("clips") || haystack.contains("reels") || haystack.contains("mixed_media")) return "reels"
        if (haystack.contains("feed") || haystack.contains("timeline") || haystack.contains("refresh")) return "feed"
        if (isRefreshSurfaceForeground("feed")) return "feed"
        if (isRefreshSurfaceForeground("reels")) return "reels"
        return null
    }

    private fun currentForegroundOrLikelyRefreshSurface(): String? {
        if (isRefreshSurfaceForeground("feed")) return "feed"
        if (isRefreshSurfaceForeground("reels")) return "reels"
        return null
    }

    private fun isRefreshSurfaceForeground(surface: String): Boolean {
        val activity = currentActivity ?: return false
        if (activity.isFinishing) return false
        if (surface == "feed") {
            val root = activity.window?.decorView
            if (hasVisibleIdContaining(root, "message_list", "direct_inbox", "direct_search", "clips_tab_view_pager")) {
                return false
            }
            return isAnySelected(activity, "feed_tab", "current_feed_tab") ||
                (isAnyVisible(activity, "feed_tab", "current_feed_tab") &&
                    !isAnySelected(activity, "direct_tab", "search_tab", "clips_tab"))
        }
        return isAnySelected(activity, "clips_tab") ||
            (isAnyVisible(activity, "clips_tab") &&
                !isAnySelected(activity, "direct_tab", "search_tab", "feed_tab", "current_feed_tab"))
    }

    private fun isClearlyBackgroundRefresh(surface: String): Boolean {
        val root = currentActivity?.window?.decorView ?: return false
        return if (surface == "feed") {
            hasVisibleIdContaining(
                root,
                "message_list",
                "direct_inbox",
                "direct_search",
                "clips_tab_view_pager",
                "profile_header",
                "search_tab_bar"
            )
        } else {
            hasVisibleIdContaining(
                root,
                "message_list",
                "direct_inbox",
                "direct_search",
                "feed_view",
                "feed_tab",
                "profile_header",
                "search_tab_bar"
            )
        }
    }

    private fun refreshHierarchySignal(view: View?): String {
        val out = StringBuilder()
        var current = view
        repeat(10) {
            val node = current ?: return@repeat
            out.append(' ').append(resourceEntryName(node).orEmpty())
            out.append(' ').append(node.javaClass.name)
            current = node.parent as? View
        }
        return out.toString().lowercase(Locale.US)
    }

    private fun hasVisibleIdContaining(view: View?, vararg needles: String): Boolean {
        if (view == null || view.visibility != View.VISIBLE) return false
        val id = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        if (needles.any { id.contains(it) }) return true
        if (view is ViewGroup) {
            val count = view.childCount.coerceAtMost(120)
            for (i in 0 until count) {
                if (hasVisibleIdContaining(view.getChildAt(i), *needles)) return true
            }
        }
        return false
    }

    private fun isAnySelected(activity: Activity, vararg ids: String): Boolean {
        return ids.any { idName ->
            val id = activity.resources.getIdentifier(idName, "id", activity.packageName)
            id != 0 && isSelectedLike(activity.findViewById(id), 0)
        }
    }

    private fun isAnyVisible(activity: Activity, vararg ids: String): Boolean {
        return ids.any { idName ->
            val id = activity.resources.getIdentifier(idName, "id", activity.packageName)
            id != 0 && (activity.findViewById<View>(id)?.visibility == View.VISIBLE)
        }
    }

    private fun isSelectedLike(view: View?, depth: Int): Boolean {
        if (view == null || view.visibility != View.VISIBLE || depth > 4) return false
        if (view.isSelected || view.isActivated || view.isPressed) return true
        val desc = view.contentDescription?.toString()?.lowercase(Locale.US).orEmpty()
        if (desc.contains("selected") || desc.contains("current")) return true
        if (view is ViewGroup) {
            val count = view.childCount.coerceAtMost(16)
            for (i in 0 until count) {
                if (isSelectedLike(view.getChildAt(i), depth + 1)) return true
            }
        }
        return false
    }

    private fun refreshVisibleRoots(reason: String) {
        ensureRuntimeHooksForCurrentState("refresh:$reason")
        mainHandler.post {
            restoreKnownHiddenViewsIfNoHideRules()
            val roots = LinkedHashSet<View>()
            currentActivity?.window?.decorView?.rootView?.let { roots += it }
            synchronized(trackedRoots) { roots += trackedRoots.filter { it.isAttachedToWindow } }
            if (needsRefreshRootScan(state, reason)) {
                roots.forEach { root ->
                    if (!root.isAttachedToWindow) return@forEach
                    scanTree(root, "refresh:$reason", REFRESH_VIEW_SCAN_LIMIT)
                }
            }
            currentActivity?.let { activity ->
                wireInstagramEntryPoints(activity)
                applyGhostIndicator(activity)
                applyCaptureOverlay(activity)
                clickDefaultNavigationTab(activity)
            }
        }
    }

    private fun refreshActivity(activity: Activity, reason: String) {
        val root = activity.window?.decorView ?: return
        if (needsRefreshRootScan(state, reason)) {
            root.post { scanTree(root, reason, REFRESH_VIEW_SCAN_LIMIT) }
        }
        root.post { wireInstagramEntryPoints(activity) }
        root.post { applyCaptureOverlay(activity) }
    }

    private fun hasExplicitHiddenUiRules(current: InstagramFeatureState = state): Boolean {
        return hiddenUiRules(current).hasExplicit
    }

    private fun hasBroadViewHideRule(current: InstagramFeatureState = state): Boolean {
        return current.isExtremeMode ||
            current.disableStories ||
            current.disableFeed ||
            current.disableExplore ||
            current.disableComments
    }

    private fun hasAnyViewHideRule(current: InstagramFeatureState = state): Boolean {
        return hasExplicitHiddenUiRules(current) || hasBroadViewHideRule(current)
    }

    private fun hiddenUiRules(current: InstagramFeatureState = state): HiddenUiRules {
        val cached = cachedHiddenUiRules
        if (cached.rawIds == current.hiddenUiElementIds &&
            cached.rawSelectors == current.hiddenUiElementSelectors
        ) {
            return cached
        }
        val next = HiddenUiRules(
            rawIds = current.hiddenUiElementIds,
            rawSelectors = current.hiddenUiElementSelectors,
            ids = current.hiddenUiElementIdSet,
            selectors = parseHiddenUiSelectors(current.hiddenUiElementSelectors)
        )
        hiddenUiLoggedKeys.clear()
        cachedHiddenUiRules = next
        return next
    }

    private fun parseHiddenUiSelectors(raw: String): List<ParsedSelector> {
        if (raw.isBlank()) return emptyList()
        return raw.lineSequence()
            .map { it.trim() }
            .filter { it.startsWith("selector:v1|") }
            .mapNotNull(::parseAnchoredSelector)
            .distinct()
            .toList()
    }

    private fun needsRefreshRootScan(current: InstagramFeatureState = state, reason: String): Boolean {
        if (needsRootScan(current)) return true
        if (hiddenUiRowAdjustments.isNotEmpty()) return true
        if (!hasExplicitHiddenUiRules(current)) return false
        return reason.startsWith("broadcast") ||
            reason.startsWith("async-load") ||
            reason.startsWith("settings-restore") ||
            reason.startsWith("local-settings") ||
            reason.startsWith("onResume") ||
            reason.startsWith("capture-ui")
    }

    private fun hasAnyTextHideRule(current: InstagramFeatureState = state): Boolean {
        return current.disableComments ||
            current.disableStories
    }

    private fun hasAnyTextViewWork(current: InstagramFeatureState = state): Boolean {
        return current.localInstagramPlus || hasBroadTextViewWork(current)
    }

    private fun hasBroadTextViewWork(current: InstagramFeatureState = state): Boolean {
        return current.isAdBlockEnabled ||
            current.keepUnsentMessages ||
            current.enableCustomDateFormat ||
            current.enableHideChats ||
            current.enableCopyBio ||
            current.enableCopyComment ||
            hasAnyTextHideRule(current)
    }

    private fun hasKnownHiddenUiState(view: View): Boolean {
        return hiddenUiOriginalStates.containsKey(view) ||
            hiddenUiCollapsedWrappers.containsKey(view) ||
            hiddenUiComposerAdjustments.containsKey(view) ||
            hiddenUiRowAdjustments.containsKey(view)
    }

    private fun needsContinuousLayoutWork(view: View): Boolean {
        val current = state
        return hasAnyViewHideRule(current) ||
            hasKnownHiddenUiState(view) ||
            storyRingScaleFactor(current) != 1f
    }

    private fun needsHiddenUiCallbackWork(view: View): Boolean {
        if (hasKnownHiddenUiState(view)) return true
        val current = state
        val rules = hiddenUiRules(current)
        if (rules.ids.isNotEmpty() && view.id != View.NO_ID && view.id != 0) return true
        if (rules.selectors.isNotEmpty() && view.javaClass.name in rules.selectorLeafClasses) return true
        return hasBroadViewHideRule(current)
    }

    private fun shouldInstallHiddenUiCallbackHooks(current: InstagramFeatureState = state): Boolean {
        return hasAnyViewHideRule(current)
    }

    private fun processView(view: View, reason: String) {
        val fromLayout = reason == "layout"
        val current = state
        if (!hasAnyProcessViewWork(current)) return
        val isStoryViewerSurface = isStoryViewerSurfaceFast(view)
        if (shouldDeferScrollSensitiveWork()) {
            if (applyExplicitHiddenUiFast(view, "deferred:$reason")) return
            noteScrollDeferredWork(view, "view", reason)
            return
        }
        if (fromLayout && shouldSkipRecentLayoutProcess(view)) return
        if (!fromLayout && shouldSkipRecentAttachedProcess(view)) return
        maybeAutoEnableInstagramSound(view, current)
        if (view is TextView && current.enableHighQualityStoryUpload) maybeRememberStoryComposerText(view)
        if (view is TextView && hasAnyTextViewWork(current)) {
            processTextViewFastOrBroad(view, current, view.text, view.contentDescription, isStoryViewerSurface)
        }
        if (!fromLayout && current.doNotSaveRecentSearches) clearVisibleRecentSearchRowIfNeeded(view)
        if (!fromLayout && !isStoryViewerSurface) processEntryPointCandidate(view)
        if (!fromLayout && !isStoryViewerSurface) maybeActivateDmTouchDispatchHooksFromView(view, current)
        if (current.isAdBlockEnabled && !isStoryViewerSurface && shouldCheckSponsoredContainerView(view)) hideSponsoredSurfaceIfNeeded(view)
        if (current.isGhostLive) hideLivePresenceIfNeeded(view)
        if (current.keepUnsentMessages &&
            !isStoryViewerSurface &&
            isKeepUnsentConversationSurfaceActive(view) &&
            shouldInspectKeepUnsentRowBinding(view) &&
            !(view is TextView && isKeepUnsentDirectTextMessageTextView(view)) &&
            isKeepUnsentMessageContentCandidate(view)
        ) {
            maybeBindKeepUnsentRowFromView(view, knownCandidate = true)
        }
        if (!fromLayout) {
            if (!isStoryViewerSurface) applyDirectGhostSeenControls(view)
            if (!isStoryViewerSurface && (current.enablePostDownload || current.enableReelDownload || current.enableReelThumbnailDownload)) {
                applyFeedPostDownloadControls(view, current)
            }
            if (!isStoryViewerSurface) applyDmAnyFileUploadButton(view)
            if (current.enableUploadInstantsFromGallery &&
                !isStoryViewerSurface &&
                isPotentialInstantUploadSurface(view) &&
                isInstantUploadSignalView(view)
            ) {
                applyInstantGalleryUploadButton(view)
                maybeScheduleInstantUploadButtonPass(view)
            }
            if (!isStoryViewerSurface) applyProfilePictureDownload(view)
        }
        if (!enforceHiddenUiState(view) && hasAnyViewHideRule(current) && shouldHideView(view)) hideView(view, reason)
        if (storyRingScaleFactor(current) != 1f && isStoryRingCandidateFast(view)) {
            applyStoryRingScale(view)
            if (looksLikeHomeStoryTrayContainerName(resourceEntryName(view)) ||
                looksLikeHomeStoryTrayContainerName(view.contentDescription?.toString())
            ) {
                applyStoryRingTreeSoon(view, 120L)
                applyStoryRingTreeSoon(view, 450L)
            }
        }
        if (!fromLayout && !isStoryViewerSurface && current.enableStoryTrayLongPressActions && isStoryTraySurface(view)) {
            view.isLongClickable = true
        }
        if (isNavigationCustomizationActive(current) && isLikelyNavigationCustomizationTarget(view)) {
            applyNavigationTabRules(view)
        }
        if (!fromLayout && !isStoryViewerSurface) scheduleScan(view, reason)
    }

    private fun applyExplicitHiddenUiFast(view: View, reason: String): Boolean {
        val rules = hiddenUiRules()
        if (!rules.hasExplicit) return false
        if (shouldEnforceHiddenUiView(view, rules)) {
            hideView(view, reason)
            return true
        }
        return false
    }

    private fun hasAnyProcessViewWork(current: InstagramFeatureState): Boolean {
        return current.isAdBlockEnabled ||
            current.isGhostLive ||
            current.isGhostSeen ||
            current.enableHighQualityStoryUpload ||
            current.keepUnsentMessages ||
            current.doNotSaveRecentSearches ||
            current.enableDmAnyFileUpload ||
            current.enableUploadInstantsFromGallery ||
            current.enableProfileDownload ||
            current.enableStoryTrayLongPressActions ||
            current.customizeStoryRingSize ||
            current.disableComments ||
            current.enableHideChats ||
            current.enableCopyBio ||
            current.enableCustomDateFormat ||
            current.enableNavigationTabCustomization ||
            current.enablePostDownload ||
            current.enableReelDownload ||
            current.enableReelThumbnailDownload ||
            hasHiddenNavigationTargets(current) ||
            hasAnyViewHideRule(current) ||
            hasBroadTextViewWork(current) ||
            current.isGhostTyping ||
            current.showFollowerToast
    }

    private fun shouldSkipRecentLayoutProcess(view: View): Boolean {
        val now = System.currentTimeMillis()
        val last = processedLayoutViews[view] ?: 0L
        if (now - last < 1_000L) return true
        processedLayoutViews[view] = now
        return false
    }

    private fun shouldSkipRecentAttachedProcess(view: View): Boolean {
        val now = System.currentTimeMillis()
        val last = processedAttachedViews[view] ?: 0L
        if (now - last < 300L) return true
        processedAttachedViews[view] = now
        return false
    }

    private fun clearVisibleRecentSearchRowIfNeeded(view: View) {
        val description = view.contentDescription?.toString()?.lowercase(Locale.US) ?: return
        if (!description.startsWith("clear recent search")) return
        val name = resourceEntryName(view)?.lowercase(Locale.US).orEmpty()
        if (name.isNotEmpty() && name != "dismiss_button" && !name.contains("clear")) return
        if (!recentSearchClearButtons.add(view)) return
        hideRecentSearchRowBeforeFirstDraw(view)
        view.post {
            if (!state.doNotSaveRecentSearches || !view.isAttachedToWindow) return@post
            runCatching {
                view.performClick()
                logInfo("Cleared visible Instagram recent search row")
            }.onFailure { logError("Failed clearing visible Instagram recent search row", it) }
        }
    }

    private fun hideRecentSearchRowBeforeFirstDraw(clearButton: View) {
        clearButton.alpha = 0f
        val row = recentSearchRowForClearButton(clearButton)
        row?.alpha = 0f
        row?.visibility = View.INVISIBLE
    }

    private fun recentSearchRowForClearButton(clearButton: View): View? {
        var current = clearButton.parent as? View
        var depth = 0
        while (current != null && depth++ < 4) {
            val height = current.height.takeIf { it > 0 } ?: current.layoutParams?.height ?: 0
            val name = resourceEntryName(current)?.lowercase(Locale.US).orEmpty()
            if ((name.contains("row") || name.contains("search")) && height in dp(36)..dp(96) && containsRecentSearchText(current)) {
                return current
            }
            current = current.parent as? View
        }
        return null
    }

    private fun containsRecentSearchText(view: View): Boolean {
        if (view is TextView) {
            val text = view.text?.toString()?.trim().orEmpty()
            val name = resourceEntryName(view)?.lowercase(Locale.US).orEmpty()
            if (text.isNotEmpty() && name != "title_text_view" && !text.equals("Suggestions", true)) return true
        }
        if (view !is ViewGroup) return false
        for (i in 0 until view.childCount) {
            if (containsRecentSearchText(view.getChildAt(i))) return true
        }
        return false
    }

    private fun processTextViewFastOrBroad(
        textView: TextView,
        current: InstagramFeatureState,
        rawCandidate: CharSequence?,
        descriptionCandidate: CharSequence?,
        isStoryViewerSurface: Boolean = isStoryViewerSurfaceFast(textView)
    ) {
        if (!hasAnyTextViewWork(current)) return
        if (current.localInstagramPlus &&
            maybeHideLocalInstagramPlusStoryPeekUpsellTextFast(textView, rawCandidate, descriptionCandidate)
        ) {
            return
        }
        if (isStoryViewerSurface) {
            if (hasAnyTextHideRule(current)) {
                val raw = rawCandidate?.toString().orEmpty()
                val rawDescription = descriptionCandidate?.toString().orEmpty()
                if (shouldHideText(raw) || shouldHideText(rawDescription)) hideView(textView, "text")
            }
            return
        }
        if (hasBroadTextViewWork(current)) processTextView(textView)
    }

    private fun isStoryViewerSurfaceFast(view: View?): Boolean {
        val start = view ?: return false
        val ownName = resourceEntryName(start).orEmpty()
        if (isStoryViewerResourceName(ownName)) {
            noteStoryViewerSurfaceSeen()
            return true
        }
        if (SystemClock.uptimeMillis() > storyViewerSurfaceActiveUntilMs) return false
        var current = start.parent as? View
        var depth = 0
        while (current != null && depth++ < 12) {
            val name = resourceEntryName(current).orEmpty()
            if (isStoryViewerResourceName(name)) {
                noteStoryViewerSurfaceSeen()
                return true
            }
            current = current.parent as? View
        }
        return false
    }

    private fun noteStoryViewerSurfaceSeen() {
        val until = SystemClock.uptimeMillis() + 20_000L
        if (until > storyViewerSurfaceActiveUntilMs) storyViewerSurfaceActiveUntilMs = until
    }

    private fun isStoryViewerResourceName(name: String): Boolean {
        if (name.isBlank()) return false
        val lower = name.lowercase(Locale.US)
        return lower.contains("reel_viewer") ||
            lower.contains("viewer_reel_item") ||
            lower == "reel_view_group" ||
            lower == "header_menu_button" ||
            lower == "reel_header_extras_container" ||
            lower.contains("story_viewer")
    }

    private fun processTextView(textView: TextView) {
        val current = state
        if (!hasAnyTextViewWork(current)) return
        if (shouldDeferScrollSensitiveWork()) {
            noteScrollDeferredWork(textView, "text", "text")
            return
        }
        if (current.keepUnsentMessages) handleKeepUnsentDirectTextViewChanged(textView)
        val needsRawText = current.isAdBlockEnabled ||
            current.enableCustomDateFormat ||
            current.enableHideChats ||
            current.enableCopyBio ||
            current.enableCopyComment ||
            current.localInstagramPlus ||
            hasAnyTextHideRule(current)
        if (!needsRawText) return
        val raw = textView.text?.toString().orEmpty()
        val rawDescription = textView.contentDescription?.toString().orEmpty()
        if (current.localInstagramPlus && maybeHideLocalInstagramPlusStoryPeekUpsellText(textView, raw, rawDescription)) return
        val dateRaw = raw.ifBlank { textView.contentDescription?.toString().orEmpty() }
        if (current.enableCustomDateFormat && current.customDateFormatComments && isCommentDateSurfaceMarker(dateRaw)) {
            commentDateSurfaceActiveUntilMs = SystemClock.uptimeMillis() + 30_000L
        }
        if (current.enableCustomDateFormat && current.customDateFormatComments && !isCommentDateSurfaceContextActive() && isCommentDateSurfaceByView(textView)) {
            commentDateSurfaceActiveUntilMs = SystemClock.uptimeMillis() + 30_000L
        }
        val isAdDisclosure = isAdDisclosureText(raw) || isAdDisclosureText(rawDescription)
        if (current.isAdBlockEnabled && (isSponsoredText(raw) ||
                isSponsoredText(rawDescription) ||
                (isAdDisclosure && (hasFeedAdDisclosureContext(textView) || hasAdDisclosureNeighborContext(textView)))
            )
        ) {
            hideSponsoredContainer(textView)
        } else if (current.isAdBlockEnabled && shouldCheckSponsoredContainerView(textView)) {
            hideSponsoredSurfaceIfNeeded(textView)
        }
        if (current.enableCustomDateFormat) rewriteRelativeDate(textView, dateRaw)
        if (current.enableHideChats && maybeCollectOrHideChatRow(textView, raw)) return
        if (shouldHideText(raw)) hideView(textView, "text")
        if (current.enableCopyBio) {
            maybeRememberProfileBioCandidate(textView)
            maybeInjectProfileMenuCopyBio(textView)
            maybeInstallCopyBioLongPress(textView)
        }
        if ((current.enableCopyComment || current.enableCopyBio) && shouldMakeCopyable(textView, raw)) {
            textView.setTextIsSelectable(true)
        }
    }

    private fun scheduleScan(view: View, reason: String) {
        if (!needsRootScan(state)) return
        val root = view.rootView ?: view
        val now = System.currentTimeMillis()
        val last = scannedRoots[root] ?: 0L
        if (now - last < 5_000L || !pendingRootScans.add(root)) return
        scannedRoots[root] = now
        mainHandler.post {
            try {
                scanTree(root, reason)
            } finally {
                pendingRootScans.remove(root)
            }
        }
    }

    private fun needsRootScan(current: InstagramFeatureState = state): Boolean {
        return hasBroadViewHideRule(current) ||
            needsNavigationRootScan(current)
    }

    private fun needsNavigationRootScan(current: InstagramFeatureState = state): Boolean {
        return false
    }

    private fun scanTree(root: View, reason: String, visitLimit: Int = DEFAULT_VIEW_SCAN_LIMIT) {
        if (!root.isAttachedToWindow) return
        if (shouldDeferScrollSensitiveWork()) {
            noteScrollDeferredWork(root, "view", "scan:$reason")
            return
        }
        var visited = 0
        fun visit(view: View) {
            if (visited++ > visitLimit) return
            processViewWithoutScheduling(view, reason)
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) visit(view.getChildAt(i))
            }
        }
        visit(root)
    }

    private fun processViewWithoutScheduling(view: View, reason: String) {
        val current = state
        if (!hasAnyViewWork(current)) return
        if (shouldDeferScrollSensitiveWork()) {
            if (applyExplicitHiddenUiFast(view, "scan-deferred:$reason")) return
            noteScrollDeferredWork(view, "view", reason)
            return
        }
        maybeAutoEnableInstagramSound(view, current)
        val isStoryViewerSurface = isStoryViewerSurfaceFast(view)
        if (view is TextView && hasAnyTextViewWork(current)) {
            processTextViewFastOrBroad(view, current, view.text, view.contentDescription, isStoryViewerSurface)
        }
        if (current.doNotSaveRecentSearches) clearVisibleRecentSearchRowIfNeeded(view)
        if (!isStoryViewerSurface) processEntryPointCandidate(view)
        if (!isStoryViewerSurface) maybeActivateDmTouchDispatchHooksFromView(view, current)
        if (current.isAdBlockEnabled && !isStoryViewerSurface && shouldCheckSponsoredContainerView(view)) hideSponsoredSurfaceIfNeeded(view)
        if (current.isGhostLive) hideLivePresenceIfNeeded(view)
        if (current.keepUnsentMessages &&
            !isStoryViewerSurface &&
            isKeepUnsentConversationSurfaceActive(view) &&
            shouldInspectKeepUnsentRowBinding(view) &&
            !(view is TextView && isKeepUnsentDirectTextMessageTextView(view)) &&
            isKeepUnsentMessageContentCandidate(view)
        ) {
            maybeBindKeepUnsentRowFromView(view, knownCandidate = true)
        }
        if (!isStoryViewerSurface) {
            applyDirectGhostSeenControls(view)
            applyDmAnyFileUploadButton(view)
            applyProfilePictureDownload(view)
        }
        if (!enforceHiddenUiState(view) && hasAnyViewHideRule(current) && shouldHideView(view)) hideView(view, reason)
        if (storyRingScaleFactor(current) != 1f) applyStoryRingScale(view)
        if (isNavigationCustomizationActive(current) && isLikelyNavigationCustomizationTarget(view)) {
            applyNavigationTabRules(view)
        }
    }

    private fun hasAnyViewWork(current: InstagramFeatureState): Boolean {
        return current.isAdBlockEnabled ||
            current.isGhostLive ||
            current.isGhostSeen ||
            current.isGhostStory ||
            current.keepUnsentMessages ||
            current.doNotSaveRecentSearches ||
            current.enableNavigationTabCustomization ||
            current.enableCustomDateFormat ||
            current.enableHideChats ||
            current.enableCopyBio ||
            current.enableCopyComment ||
            current.enableDmAnyFileUpload ||
            current.enableUploadInstantsFromGallery ||
            current.enableProfileDownload ||
            current.disableComments ||
            current.disableStories ||
            current.disableFeed ||
            current.disableExplore ||
            hasHiddenNavigationTargets(current) ||
            hasAnyViewHideRule(current) ||
            storyRingScaleFactor(current) != 1f
    }

    private fun rememberRoot(view: View?) {
        val root = view?.rootView ?: return
        trackedRoots += root
    }

    private fun enforceHiddenUiState(view: View): Boolean {
        val rules = hiddenUiRules()
        if (shouldEnforceHiddenUiView(view, rules)) {
            forceHiddenUiView(view)
            return true
        }
        if (hasKnownHiddenUiState(view)) {
            restoreHiddenUiView(view)
            enforceComposerUiAdjustment(view)
            enforceHiddenUiRowAdjustment(view)
        }
        return false
    }

    private fun shouldEnforceHiddenUiView(view: View?, rules: HiddenUiRules = hiddenUiRules()): Boolean {
        if (view == null || shouldSkipHiddenUiInContext(view.context)) return false
        if (matchesExplicitHiddenUiRule(view, rules)) return true
        val source = hiddenUiCollapsedWrappers[view] ?: return false
        val keepHidden = source !== view && matchesExplicitHiddenUiRule(source, rules)
        if (!keepHidden) hiddenUiCollapsedWrappers.remove(view)
        return keepHidden
    }

    private fun shouldSkipHiddenUiInContext(context: Context?): Boolean {
        return state.enableDmContextMenuOptions &&
            findActivity(context)?.javaClass?.name == "com.instagram.modal.ModalActivity"
    }

    private fun matchesExplicitHiddenUiRule(view: View?, rules: HiddenUiRules = hiddenUiRules()): Boolean {
        if (view == null || shouldSkipHiddenUiInContext(view.context)) return false
        if (!rules.hasExplicit) return false
        if (rules.ids.isNotEmpty()) {
            val resourceId = resourceEntryName(view)
            if (resourceId != null && resourceId in rules.ids) return true
        }
        if (rules.selectors.isEmpty()) return false
        if (view.javaClass.name !in rules.selectorLeafClasses) return false
        return rules.selectors.any { selector -> selectorMatches(view, selector) }
    }

    private fun rememberHiddenUiState(view: View) {
        if (hiddenUiOriginalStates.containsKey(view)) return
        hiddenUiOriginalStates[view] = HiddenUiState(view)
    }

    private fun forceHiddenUiView(view: View) {
        rememberHiddenUiState(view)
        runCatching {
            hiddenUiInternalChange.set(true)
            view.alpha = 0f
            view.isEnabled = false
            view.isClickable = false
            if (view.visibility != View.GONE) view.visibility = View.GONE
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
                view.importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS
            }
            collapseHiddenUiFootprint(view)
        }.onFailure { logError("Failed to hide explicit Instagram UI view", it) }
        hiddenUiInternalChange.remove()
        if (matchesExplicitHiddenUiRule(view) && !isInstagramScrollHot()) collapseHiddenUiNeighbors(view)
    }

    private fun restoreHiddenUiView(view: View) {
        if (hiddenUiCollapsedWrappers.containsKey(view)) return
        val original = hiddenUiOriginalStates.remove(view) ?: return
        runCatching {
            hiddenUiInternalChange.set(true)
            restoreHiddenUiFootprint(view, original)
            view.visibility = original.visibility
            view.alpha = original.alpha
            view.isEnabled = original.enabled
            view.isClickable = original.clickable
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
                view.importantForAccessibility = original.importantForAccessibility
            }
        }.onFailure { logError("Failed to restore explicit Instagram UI view", it) }
        hiddenUiInternalChange.remove()
    }

    private fun restoreKnownHiddenViewsIfNoHideRules() {
        if (hasAnyViewHideRule()) return
        val views = LinkedHashSet<View>()
        synchronized(hiddenUiCollapsedWrappers) {
            views += hiddenUiCollapsedWrappers.keys
            views += hiddenUiCollapsedWrappers.values
            hiddenUiCollapsedWrappers.clear()
        }
        synchronized(hiddenUiOriginalStates) { views += hiddenUiOriginalStates.keys }
        synchronized(hiddenUiComposerAdjustments) { views += hiddenUiComposerAdjustments.keys }
        synchronized(hiddenUiRowAdjustments) { views += hiddenUiRowAdjustments.keys }
        views.forEach { view ->
            restoreHiddenUiView(view)
            restoreComposerUiAdjustment(view)
            hiddenUiRowAdjustments.remove(view)?.let { restoreHiddenUiRowAdjustment(view, it) }
            requestHiddenUiLayout(view)
        }
    }

    private fun collapseHiddenUiNeighbors(source: View) {
        collapseHiddenUiWrapper(source)
        collapseGenericActionSlot(source)
        collapseCompoundActionItem(source)
        collapseComposerActionParent(source)
        collapseComposerActionSlot(source)
        adjustComposerUiForHiddenAction(source)
        compactRowsAroundHiddenUiView(source, null)
    }

    private fun collapseHiddenUiWrapper(source: View) {
        val target = findHiddenUiCollapseTarget(source)
        if (target === source) return
        hiddenUiCollapsedWrappers[target] = source
        forceHiddenUiView(target)
    }

    private fun findHiddenUiCollapseTarget(source: View): View {
        var best = source
        var current = source
        var depth = 0
        while (depth < 3) {
            val parent = current.parent as? ViewGroup ?: break
            if (resourceEntryName(parent) != null || !isHiddenUiLayoutShell(parent, current)) break
            best = parent
            current = parent
            depth++
        }
        return best
    }

    private fun isHiddenUiLayoutShell(parent: ViewGroup, child: View): Boolean {
        var usefulChildren = 0
        for (index in 0 until parent.childCount) {
            val candidate = parent.getChildAt(index) ?: continue
            if (candidate === child) {
                usefulChildren++
                continue
            }
            if (candidate.visibility == View.GONE || candidate.alpha <= 0.01f) continue
            if (candidate.width <= 0 || candidate.height <= 0) continue
            usefulChildren++
        }
        return usefulChildren <= 1 || hasSameHiddenUiBounds(parent, child)
    }

    private fun hasSameHiddenUiBounds(parent: View, child: View): Boolean {
        if (parent.width <= 0 || parent.height <= 0 || child.width <= 0 || child.height <= 0) return false
        if (kotlin.math.abs(parent.width - child.width) > 2 || kotlin.math.abs(parent.height - child.height) > 2) return false
        val parentLocation = IntArray(2)
        val childLocation = IntArray(2)
        parent.getLocationOnScreen(parentLocation)
        child.getLocationOnScreen(childLocation)
        return kotlin.math.abs(parentLocation[0] - childLocation[0]) <= 2 &&
            kotlin.math.abs(parentLocation[1] - childLocation[1]) <= 2
    }

    private fun collapseHiddenUiFootprint(view: View) {
        view.layoutParams?.let { params ->
            var changed = false
            if (params.width != 0) {
                params.width = 0
                changed = true
            }
            if (params.height != 0) {
                params.height = 0
                changed = true
            }
            if (params is ViewGroup.MarginLayoutParams &&
                (params.leftMargin != 0 || params.topMargin != 0 || params.rightMargin != 0 || params.bottomMargin != 0)
            ) {
                params.setMargins(0, 0, 0, 0)
                changed = true
            }
            if (changed) view.layoutParams = params
        }
        view.minimumWidth = 0
        view.minimumHeight = 0
        forceHiddenUiMeasuredSize(view)
        requestHiddenUiLayout(view)
    }

    private fun restoreHiddenUiFootprint(view: View, original: HiddenUiState) {
        view.layoutParams?.let { params ->
            var changed = false
            if (original.hasLayoutParams && params.width != original.layoutWidth) {
                params.width = original.layoutWidth
                changed = true
            }
            if (original.hasLayoutParams && params.height != original.layoutHeight) {
                params.height = original.layoutHeight
                changed = true
            }
            if (params is ViewGroup.MarginLayoutParams && original.hasMargins &&
                (params.leftMargin != original.leftMargin || params.topMargin != original.topMargin ||
                    params.rightMargin != original.rightMargin || params.bottomMargin != original.bottomMargin)
            ) {
                params.setMargins(original.leftMargin, original.topMargin, original.rightMargin, original.bottomMargin)
                changed = true
            }
            if (changed) view.layoutParams = params
        }
        view.minimumWidth = original.minWidth
        view.minimumHeight = original.minHeight
        requestHiddenUiLayout(view)
    }

    private fun forceHiddenUiMeasuredSize(view: View) {
        runCatching {
            hiddenUiInternalChange.set(true)
            View::class.java.getDeclaredMethod(
                "setMeasuredDimension",
                java.lang.Integer.TYPE,
                java.lang.Integer.TYPE
            ).apply { isAccessible = true }.invoke(view, 0, 0)
        }
        hiddenUiInternalChange.remove()
    }

    private fun requestHiddenUiLayout(view: View) {
        view.requestLayout()
        view.invalidate()
        (view.parent as? View)?.let {
            it.requestLayout()
            it.invalidate()
        }
    }

    private fun collapseGenericActionSlot(source: View) {
        if (isComposerOrTextInputUiContext(source)) return
        var current = source
        var depth = 0
        while (depth < 3) {
            val parent = current.parent as? ViewGroup ?: break
            if (!isGenericActionUiSlot(parent, current)) break
            hiddenUiCollapsedWrappers[parent] = source
            forceHiddenUiView(parent)
            current = parent
            depth++
        }
    }

    private fun collapseCompoundActionItem(source: View) {
        if (isComposerOrTextInputUiContext(source)) return
        var current = source
        var depth = 0
        while (depth < 3) {
            val parent = current.parent as? ViewGroup ?: break
            if (isCompoundActionUiItem(parent, current)) {
                hiddenUiCollapsedWrappers[parent] = source
                forceHiddenUiView(parent)
                current = parent
                depth++
                continue
            }
            if (!isHiddenUiLayoutShell(parent, current) && !hasSameHiddenUiBounds(parent, current)) break
            current = parent
            depth++
        }
    }

    private fun isGenericActionUiSlot(parent: ViewGroup, child: View): Boolean {
        if (isComposerOrTextInputUiContext(parent) || !isHiddenUiLayoutShell(parent, child)) return false
        val width = maxOf(parent.width, parent.measuredWidth)
        val height = maxOf(parent.height, parent.measuredHeight)
        if (width <= 0 || height <= 0 || width > dp(parent, 240) || height > dp(parent, 180)) return false
        return hasActionUiName(parent) || hasActionUiName(child) || isIconLikeUiView(child)
    }

    private fun isCompoundActionUiItem(parent: ViewGroup, child: View): Boolean {
        if (isComposerOrTextInputUiContext(parent)) return false
        val width = maxOf(parent.width, parent.measuredWidth)
        val height = maxOf(parent.height, parent.measuredHeight)
        if (width <= 0 || height <= 0 || width > dp(parent, 220) || height > dp(parent, 240)) return false
        val parentName = resourceEntryName(parent).orEmpty().lowercase(Locale.US)
        if (!parentName.contains("item") && !parentName.contains("cell") &&
            (parentName.contains("buttons") || parentName.contains("toolbar") || parentName.contains("navigation") || parentName.contains("tab_bar"))
        ) return false
        var usefulChildren = 0
        var labels = 0
        var iconControls = 0
        for (index in 0 until parent.childCount) {
            val candidate = parent.getChildAt(index) ?: continue
            if (candidate !== child && candidate.visibility == View.GONE && !shouldEnforceHiddenUiView(candidate)) continue
            if (candidate !== child && candidate.alpha <= 0.01f) continue
            usefulChildren++
            if (isIconLikeUiView(candidate) || hasActionUiName(candidate)) iconControls++
            if (isActionTextUiLabel(candidate)) labels++
        }
        return usefulChildren in 2..5 && labels > 0 && (iconControls > 0 || hasActionUiName(parent))
    }

    private fun isIconLikeUiView(view: View): Boolean {
        var width = maxOf(view.width, view.measuredWidth)
        var height = maxOf(view.height, view.measuredHeight)
        hiddenUiOriginalStates[view]?.let {
            if (width <= 0) width = maxOf(width, it.width)
            if (height <= 0) height = maxOf(height, it.height)
        }
        if (width <= 0 || height <= 0 || width > dp(view, 132) || height > dp(view, 132)) return false
        val className = view.javaClass.name.lowercase(Locale.US)
        return className.contains("image") || className.contains("button") ||
            className.contains("textview") || view.isClickable || view.isLongClickable
    }

    private fun isActionTextUiLabel(view: View): Boolean {
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        return name.contains("count") || name.contains("label") || name.contains("text") ||
            name.contains("title") || name.contains("subtitle") || name.contains("number") ||
            view.javaClass.name.lowercase(Locale.US).contains("textview")
    }

    private fun hasActionUiName(view: View): Boolean {
        val name = "${resourceEntryName(view).orEmpty()} ${view.javaClass.name}".lowercase(Locale.US)
        return name.contains("button") || name.contains("action") || name.contains("icon") ||
            name.contains("ufi") || name.contains("menu") || name.contains("share") ||
            name.contains("save") || name.contains("like") || name.contains("comment")
    }

    private fun isComposerOrTextInputUiContext(view: View): Boolean {
        var current: View? = view
        repeat(8) {
            val node = current ?: return false
            val name = "${resourceEntryName(node).orEmpty()} ${node.javaClass.name}".lowercase(Locale.US)
            if (name.contains("edittext") || name.contains("textarea") || name.contains("text_area") || name.contains("composer")) return true
            current = node.parent as? View
        }
        return false
    }

    private fun collapseComposerActionParent(source: View) {
        val action = findComposerUiActionView(source) ?: return
        if (action === source) return
        hiddenUiCollapsedWrappers[action] = source
        forceHiddenUiView(action)
    }

    private fun collapseComposerActionSlot(source: View) {
        var current = findComposerUiActionView(source) ?: return
        var depth = 0
        while (depth < 3) {
            val parent = current.parent as? ViewGroup ?: break
            if (!isComposerUiActionSlot(parent, current)) break
            hiddenUiCollapsedWrappers[parent] = source
            forceHiddenUiView(parent)
            current = parent
            depth++
        }
    }

    private fun isComposerUiActionSlot(parent: ViewGroup, child: View): Boolean {
        val name = resourceEntryName(parent).orEmpty().lowercase(Locale.US)
        if (!name.contains("composer")) return false
        if (name.contains("textarea") || name.contains("text_area") || name.contains("edittext") ||
            name.contains("edit_text") || name.contains("buttons_container")
        ) return false
        return name.contains("shortcut_viewgroup") ||
            (name.contains("button") && (name.contains("container") || name.contains("stub")) && isHiddenUiLayoutShell(parent, child)) ||
            (name.contains("viewgroup") && isHiddenUiLayoutShell(parent, child))
    }

    private fun findComposerUiActionView(source: View): View? {
        var current: View? = source
        repeat(8) {
            val node = current ?: return null
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (isComposerUiActionName(name)) return node
            if (isComposerUiContainerName(name)) return null
            current = node.parent as? View
        }
        return null
    }

    private fun isComposerUiActionName(name: String): Boolean {
        if (!name.contains("composer")) return false
        if (name.contains("container") || name.contains("edittext") || name.contains("edit_text") ||
            name.contains("textarea") || name.contains("text_area")
        ) return false
        return name.contains("button") || name.contains("icon") || name.contains("camera") ||
            name.contains("gallery") || name.contains("voice") || name.contains("sticker") ||
            name.contains("emoji") || name.contains("overflow")
    }

    private fun isComposerUiContainerName(name: String): Boolean {
        if (!name.contains("composer")) return false
        if (name.contains("button") || name.contains("icon") || name.contains("shortcut_viewgroup")) return false
        if ((name.contains("edittext") || name.contains("edit_text")) && !name.contains("container")) return false
        return name.contains("container") || name.contains("bar") || name.contains("controls") ||
            name.contains("textarea") || name.contains("text_area")
    }

    private fun adjustComposerUiForHiddenAction(source: View) {
        val action = findComposerUiActionView(source) ?: return
        val actionState = hiddenUiOriginalStates[action] ?: hiddenUiOriginalStates[source] ?: return
        if (actionState.width <= 0 || actionState.height <= 0) return
        val root = findComposerUiRoot(action) ?: return
        val targets = mutableListOf<View>()
        collectComposerUiTextTargets(root, action, targets)
        targets.filterNot { target -> targets.any { other -> other !== target && isHiddenUiDescendant(target, other) } }
            .forEach { target ->
                val shift = calculateComposerUiShift(actionState, target)
                if (shift > 0) adjustComposerUiTarget(target, shift)
            }
    }

    private fun enforceComposerUiAdjustment(target: View?) {
        if (target == null || !isComposerUiTextTarget(target)) return
        val root = findComposerUiRoot(target)
        if (root == null) {
            restoreComposerUiAdjustment(target)
            return
        }
        val hiddenActions = mutableListOf<View>()
        collectHiddenComposerUiActions(root, hiddenActions)
        var bestShift = 0
        hiddenActions.forEach { source ->
            val action = findComposerUiActionView(source) ?: return@forEach
            val sourceState = hiddenUiOriginalStates[action] ?: hiddenUiOriginalStates[source] ?: return@forEach
            bestShift = maxOf(bestShift, calculateComposerUiShift(sourceState, target))
        }
        if (bestShift > 0) adjustComposerUiTarget(target, bestShift) else restoreComposerUiAdjustment(target)
    }

    private fun collectHiddenComposerUiActions(view: View, out: MutableList<View>) {
        if (matchesExplicitHiddenUiRule(view) && findComposerUiActionView(view) != null) out += view
        if (view !is ViewGroup) return
        for (index in 0 until view.childCount) collectHiddenComposerUiActions(view.getChildAt(index), out)
    }

    private fun findComposerUiRoot(source: View): ViewGroup? {
        var current: View? = source
        var fallback = source.parent as? ViewGroup
        repeat(12) {
            val node = current ?: return fallback
            val group = node as? ViewGroup
            if (group != null && isComposerUiContainerName(resourceEntryName(group).orEmpty().lowercase(Locale.US))) {
                if (containsComposerUiTextTarget(group, source)) return group
                fallback = fallback ?: group
            }
            current = node.parent as? View
        }
        return fallback
    }

    private fun containsComposerUiTextTarget(root: ViewGroup, source: View): Boolean {
        if (root !== source && !isHiddenUiDescendant(root, source) && isComposerUiTextTarget(root)) return true
        for (index in 0 until root.childCount) {
            val child = root.getChildAt(index)
            if (child === source || isHiddenUiDescendant(child, source)) continue
            if (isComposerUiTextTarget(child)) return true
            if (child is ViewGroup && containsComposerUiTextTarget(child, source)) return true
        }
        return false
    }

    private fun collectComposerUiTextTargets(view: View, source: View, out: MutableList<View>) {
        if (view === source || isHiddenUiDescendant(view, source)) return
        if (isComposerUiTextTarget(view)) out += view
        if (view !is ViewGroup) return
        for (index in 0 until view.childCount) collectComposerUiTextTargets(view.getChildAt(index), source, out)
    }

    private fun isComposerUiTextTarget(view: View): Boolean {
        if (view.visibility == View.GONE) return false
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        if (name.contains("composer") && !name.contains("button") && !name.contains("icon") && !name.contains("send") &&
            (name.contains("edittext") || name.contains("edit_text") || name.contains("textarea") ||
                name.contains("text_area") || name.endsWith("_text"))
        ) return true
        return view.javaClass.name.lowercase(Locale.US).contains("edittext")
    }

    private fun calculateComposerUiShift(source: HiddenUiState, target: View): Int {
        val location = IntArray(2)
        target.getLocationOnScreen(location)
        val top = location[1]
        val bottom = top + maxOf(target.height, target.measuredHeight)
        if (bottom <= source.screenTop || top >= source.screenBottom) return 0
        if (location[0] <= source.screenLeft + 2) return 0
        val rawShift = location[0] - source.screenLeft
        val sourceFootprint = source.width + source.leftMargin + source.rightMargin
        return minOf(rawShift, maxOf(sourceFootprint, (72f * source.density.coerceAtLeast(1f)).roundToInt()))
    }

    private fun adjustComposerUiTarget(target: View, shift: Int) {
        if (shift <= 0) return
        val original = hiddenUiComposerAdjustments.getOrPut(target) { ComposerUiAdjustment(target) }
        runCatching {
            hiddenUiInternalChange.set(true)
            var remaining = shift
            val params = target.layoutParams
            if (params is ViewGroup.MarginLayoutParams && original.hasMargins) {
                val leftMargin = maxOf(0, original.leftMargin - remaining)
                remaining -= maxOf(0, original.leftMargin - leftMargin)
                params.setMargins(leftMargin, original.topMargin, original.rightMargin, original.bottomMargin)
                target.layoutParams = params
            }
            val leftPadding = maxOf(0, original.paddingLeft - remaining)
            remaining -= maxOf(0, original.paddingLeft - leftPadding)
            target.setPadding(leftPadding, original.paddingTop, original.paddingRight, original.paddingBottom)
            target.translationX = original.translationX - maxOf(0, remaining)
            requestHiddenUiLayout(target)
        }.onFailure { logError("Failed to adjust Instagram composer after hidden action", it) }
        hiddenUiInternalChange.remove()
    }

    private fun restoreComposerUiAdjustment(target: View) {
        val original = hiddenUiComposerAdjustments.remove(target) ?: return
        runCatching {
            hiddenUiInternalChange.set(true)
            val params = target.layoutParams
            if (params is ViewGroup.MarginLayoutParams && original.hasMargins) {
                params.setMargins(original.leftMargin, original.topMargin, original.rightMargin, original.bottomMargin)
                target.layoutParams = params
            }
            target.setPadding(original.paddingLeft, original.paddingTop, original.paddingRight, original.paddingBottom)
            target.translationX = original.translationX
            requestHiddenUiLayout(target)
        }.onFailure { logError("Failed to restore Instagram composer hidden-action adjustment", it) }
        hiddenUiInternalChange.remove()
    }

    private fun collectHiddenUiRowCompactions(view: View, activeTargets: MutableSet<View>) {
        if (view is ViewGroup) {
            compactHiddenUiRowGroup(view, activeTargets)
            for (index in 0 until view.childCount) collectHiddenUiRowCompactions(view.getChildAt(index), activeTargets)
        }
    }

    private fun compactRowsAroundHiddenUiView(source: View?, activeTargets: MutableSet<View>?) {
        var current = source ?: return
        var depth = 0
        while (depth < 8) {
            val parent = current.parent as? ViewGroup ?: break
            compactHiddenUiRowGroup(parent, activeTargets)
            current = parent
            depth++
        }
    }

    private fun compactHiddenUiRowGroup(group: ViewGroup, activeTargets: MutableSet<View>?) {
        if (!isCompactableHiddenUiRowGroup(group)) return
        val elements = mutableListOf<HiddenUiRowElement>()
        var hasHidden = false
        for (index in 0 until group.childCount) {
            val element = hiddenUiRowElementFrom(group.getChildAt(index), group) ?: continue
            elements += element
            hasHidden = hasHidden || element.hidden
        }
        if (!hasHidden || elements.size < 2) return
        val broadGroup = isBroadHiddenUiCompactionGroup(group)
        buildHiddenUiRows(elements).forEach { applyHiddenUiRowCompaction(group, it, activeTargets, broadGroup) }
        buildHiddenUiColumns(elements).forEach { applyHiddenUiColumnCompaction(group, it, activeTargets, broadGroup) }
    }

    private fun hiddenUiRowElementFrom(view: View?, group: ViewGroup): HiddenUiRowElement? {
        if (view == null) return null
        val hidden = shouldEnforceHiddenUiView(view)
        if (hidden) {
            val original = hiddenUiOriginalStates[view] ?: return null
            if (original.width <= 0 || original.height <= 0) return null
            if (!isHiddenUiRowCompactionCandidate(view, original.width, original.height, group, true)) return null
            return HiddenUiRowElement(view, true, original.screenLeft, original.screenTop, original.width, original.height)
        }

        if (view.visibility != View.VISIBLE || view.alpha <= 0.01f) return null
        hiddenUiRowAdjustments[view]?.let { state ->
            if (state.width > 0 && state.height > 0) {
                return HiddenUiRowElement(view, false, state.screenLeft, state.screenTop, state.width, state.height)
            }
        }
        val width = maxOf(view.width, view.measuredWidth)
        val height = maxOf(view.height, view.measuredHeight)
        if (width <= 0 || height <= 0) return null
        if (!isHiddenUiRowCompactionCandidate(view, width, height, group, false)) return null
        val location = IntArray(2)
        view.getLocationOnScreen(location)
        return HiddenUiRowElement(view, false, location[0], location[1], width, height)
    }

    private fun isCompactableHiddenUiRowGroup(group: ViewGroup): Boolean {
        val childCount = group.childCount
        if (childCount < 2 || childCount > 36) return false
        if (isComposerOrTextInputUiContext(group)) return false
        val width = group.width
        val height = group.height
        if (width <= 0 || height <= 0) return false
        val className = group.javaClass.name
        return !className.contains("RecyclerView") &&
            !className.contains("ScrollView") &&
            !className.contains("ViewPager") &&
            !className.contains("NestedScroll") &&
            !className.contains("SwipeRefresh")
    }

    private fun isBroadHiddenUiCompactionGroup(group: ViewGroup): Boolean {
        val width = maxOf(group.width, group.measuredWidth)
        val height = maxOf(group.height, group.measuredHeight)
        return height > dp(group, 160) && width > dp(group, 220)
    }

    private fun buildHiddenUiRows(elements: List<HiddenUiRowElement>): List<List<HiddenUiRowElement>> {
        val sorted = elements.sortedWith { left, right ->
            var topCompare = left.centerY().compareTo(right.centerY())
            if (kotlin.math.abs(left.centerY() - right.centerY()) <= maxOf(8, minOf(left.height, right.height))) topCompare = 0
            if (topCompare != 0) topCompare else left.left.compareTo(right.left)
        }
        val rows = mutableListOf<MutableList<HiddenUiRowElement>>()
        sorted.forEach { element ->
            val row = rows.firstOrNull { it.isNotEmpty() && isSameHiddenUiRow(it[0], element) }
                ?: mutableListOf<HiddenUiRowElement>().also { rows += it }
            row += element
        }
        return rows
    }

    private fun isSameHiddenUiRow(a: HiddenUiRowElement, b: HiddenUiRowElement): Boolean {
        val overlap = minOf(a.bottom, b.bottom) - maxOf(a.top, b.top)
        if (overlap > minOf(a.height, b.height) / 3) return true
        return kotlin.math.abs(a.centerY() - b.centerY()) <= maxOf(24, minOf(a.height, b.height))
    }

    private fun buildHiddenUiColumns(elements: List<HiddenUiRowElement>): List<List<HiddenUiRowElement>> {
        val sorted = elements.sortedWith { left, right ->
            var leftCompare = left.centerX().compareTo(right.centerX())
            if (kotlin.math.abs(left.centerX() - right.centerX()) <= maxOf(8, minOf(left.width, right.width))) leftCompare = 0
            if (leftCompare != 0) leftCompare else left.top.compareTo(right.top)
        }
        val columns = mutableListOf<MutableList<HiddenUiRowElement>>()
        sorted.forEach { element ->
            val column = columns.firstOrNull { it.isNotEmpty() && isSameHiddenUiColumn(it[0], element) }
                ?: mutableListOf<HiddenUiRowElement>().also { columns += it }
            column += element
        }
        return columns
    }

    private fun isSameHiddenUiColumn(a: HiddenUiRowElement, b: HiddenUiRowElement): Boolean {
        val overlap = minOf(a.right, b.right) - maxOf(a.left, b.left)
        if (overlap > minOf(a.width, b.width) / 3) return true
        return kotlin.math.abs(a.centerX() - b.centerX()) <= maxOf(24, minOf(a.width, b.width))
    }

    private fun applyHiddenUiRowCompaction(group: ViewGroup, row: List<HiddenUiRowElement>, activeTargets: MutableSet<View>?, broadGroup: Boolean) {
        if (row.size < 2) return
        buildHiddenUiRowClusters(group, row.sortedBy { it.left }).forEach { cluster ->
            applyHiddenUiRowClusterCompaction(group, cluster, activeTargets, broadGroup)
        }
    }

    private fun buildHiddenUiRowClusters(group: ViewGroup, row: List<HiddenUiRowElement>): List<List<HiddenUiRowElement>> {
        val clusters = mutableListOf<MutableList<HiddenUiRowElement>>()
        val gapThreshold = maxOf(dp(group, 72), hiddenUiMedianPositiveGap(row) * 3)
        var current: MutableList<HiddenUiRowElement>? = null
        var previous: HiddenUiRowElement? = null
        row.forEach { element ->
            val gap = previous?.let { element.left - it.right } ?: 0
            if (current == null || gap > gapThreshold) {
                current = mutableListOf()
                clusters += current!!
            }
            current!! += element
            previous = element
        }
        return clusters
    }

    private fun hiddenUiMedianPositiveGap(row: List<HiddenUiRowElement>): Int {
        val gaps = row.zipWithNext().map { (left, right) -> right.left - left.right }.filter { it > 0 }.sorted()
        return gaps.getOrNull(gaps.size / 2) ?: 0
    }

    private fun applyHiddenUiRowClusterCompaction(group: ViewGroup, row: List<HiddenUiRowElement>, activeTargets: MutableSet<View>?, broadGroup: Boolean) {
        if (row.size < 2 || row.none { it.hidden } || row.none { !it.hidden }) return
        if (isRedistributableHiddenUiSlotCluster(group, row, horizontal = true, broadGroup = broadGroup)) {
            applyDistributedHiddenUiSlotCompaction(group, row, horizontal = true, activeTargets = activeTargets)
            return
        }
        if (broadGroup && !isHiddenUiActionCluster(group, row, horizontal = true, broadGroup = true)) return
        var cumulativeShift = 0
        var hiddenRunStart: Int? = null
        row.forEach { element ->
            if (element.hidden) {
                if (hiddenRunStart == null) hiddenRunStart = element.left
                return@forEach
            }
            hiddenRunStart?.let { start ->
                val removedWidth = element.left - start
                if (removedWidth > 0) cumulativeShift += minOf(removedWidth, dp(group, 180))
                hiddenRunStart = null
            }
            if (cumulativeShift > 0) adjustHiddenUiRowTarget(group, element.view, cumulativeShift, activeTargets)
        }
    }

    private fun applyHiddenUiColumnCompaction(group: ViewGroup, column: List<HiddenUiRowElement>, activeTargets: MutableSet<View>?, broadGroup: Boolean) {
        if (column.size < 2) return
        buildHiddenUiColumnClusters(group, column.sortedBy { it.top }).forEach { cluster ->
            applyHiddenUiColumnClusterCompaction(group, cluster, activeTargets, broadGroup)
        }
    }

    private fun buildHiddenUiColumnClusters(group: ViewGroup, column: List<HiddenUiRowElement>): List<List<HiddenUiRowElement>> {
        val clusters = mutableListOf<MutableList<HiddenUiRowElement>>()
        val gapThreshold = maxOf(dp(group, 64), hiddenUiMedianPositiveVerticalGap(column) * 3)
        var current: MutableList<HiddenUiRowElement>? = null
        var previous: HiddenUiRowElement? = null
        column.forEach { element ->
            val gap = previous?.let { element.top - it.bottom } ?: 0
            if (current == null || gap > gapThreshold) {
                current = mutableListOf()
                clusters += current!!
            }
            current!! += element
            previous = element
        }
        return clusters
    }

    private fun hiddenUiMedianPositiveVerticalGap(column: List<HiddenUiRowElement>): Int {
        val gaps = column.zipWithNext().map { (top, bottom) -> bottom.top - top.bottom }.filter { it > 0 }.sorted()
        return gaps.getOrNull(gaps.size / 2) ?: 0
    }

    private fun applyHiddenUiColumnClusterCompaction(group: ViewGroup, column: List<HiddenUiRowElement>, activeTargets: MutableSet<View>?, broadGroup: Boolean) {
        if (column.size < 2 || column.none { it.hidden } || column.none { !it.hidden }) return
        if (isRedistributableHiddenUiSlotCluster(group, column, horizontal = false, broadGroup = broadGroup)) {
            applyDistributedHiddenUiSlotCompaction(group, column, horizontal = false, activeTargets = activeTargets)
            return
        }
        if (broadGroup && !isHiddenUiActionCluster(group, column, horizontal = false, broadGroup = true)) return
        var cumulativeShift = 0
        var hiddenRunStart: Int? = null
        column.forEach { element ->
            if (element.hidden) {
                if (hiddenRunStart == null) hiddenRunStart = element.top
                return@forEach
            }
            hiddenRunStart?.let { start ->
                val removedHeight = element.top - start
                if (removedHeight > 0) cumulativeShift += minOf(removedHeight, dp(group, 180))
                hiddenRunStart = null
            }
            if (cumulativeShift > 0) adjustHiddenUiColumnTarget(group, element.view, cumulativeShift, activeTargets)
        }
    }

    private fun isRedistributableHiddenUiSlotCluster(group: ViewGroup, cluster: List<HiddenUiRowElement>, horizontal: Boolean, broadGroup: Boolean): Boolean {
        if (cluster.size !in 3..12) return false
        val hiddenCount = cluster.count { it.hidden }
        val visibleCount = cluster.size - hiddenCount
        if (hiddenCount == 0 || visibleCount < 2) return false
        if (!isHiddenUiActionCluster(group, cluster, horizontal, broadGroup)) return false
        val primarySpan = if (horizontal) clusterRight(cluster) - clusterLeft(cluster) else clusterBottom(cluster) - clusterTop(cluster)
        val crossSpan = if (horizontal) clusterBottom(cluster) - clusterTop(cluster) else clusterRight(cluster) - clusterLeft(cluster)
        return if (horizontal) primarySpan >= dp(group, 96) && crossSpan <= dp(group, 150)
        else primarySpan >= dp(group, 120) && crossSpan <= dp(group, 170)
    }

    private fun isHiddenUiActionCluster(group: ViewGroup, cluster: List<HiddenUiRowElement>, horizontal: Boolean, broadGroup: Boolean): Boolean {
        var actionLike = if (hasHiddenUiSlotContainerName(group)) 1 else 0
        var iconLike = 0
        var textLike = 0
        cluster.forEach { element ->
            if (hasHiddenUiActionLikeName(element.view)) actionLike++
            if (isIconLikeUiView(element.view)) iconLike++
            if (isActionTextUiLabel(element.view)) textLike++
        }
        if (actionLike >= 2 || iconLike >= 2) return true
        if (!broadGroup && actionLike + iconLike + textLike >= 2) return true
        return if (horizontal) isHiddenUiHorizontalEdgeSlotCluster(group, cluster) && actionLike + iconLike >= 1
        else isHiddenUiVerticalEdgeSlotCluster(group, cluster) && actionLike + iconLike >= 1
    }

    private fun isHiddenUiHorizontalEdgeSlotCluster(group: ViewGroup, cluster: List<HiddenUiRowElement>): Boolean {
        val location = IntArray(2)
        group.getLocationOnScreen(location)
        val groupTop = location[1]
        val groupBottom = groupTop + maxOf(group.height, group.measuredHeight)
        val clusterHeight = clusterBottom(cluster) - clusterTop(cluster)
        if (clusterHeight > dp(group, 150)) return false
        return kotlin.math.abs(clusterTop(cluster) - groupTop) <= dp(group, 96) ||
            kotlin.math.abs(groupBottom - clusterBottom(cluster)) <= dp(group, 160)
    }

    private fun isHiddenUiVerticalEdgeSlotCluster(group: ViewGroup, cluster: List<HiddenUiRowElement>): Boolean {
        val location = IntArray(2)
        group.getLocationOnScreen(location)
        val groupLeft = location[0]
        val groupRight = groupLeft + maxOf(group.width, group.measuredWidth)
        val clusterWidth = clusterRight(cluster) - clusterLeft(cluster)
        if (clusterWidth > dp(group, 170)) return false
        return kotlin.math.abs(clusterLeft(cluster) - groupLeft) <= dp(group, 96) ||
            kotlin.math.abs(groupRight - clusterRight(cluster)) <= dp(group, 120)
    }

    private fun applyDistributedHiddenUiSlotCompaction(group: ViewGroup, cluster: List<HiddenUiRowElement>, horizontal: Boolean, activeTargets: MutableSet<View>?) {
        val visible = cluster.filterNot { it.hidden }.sortedBy { if (horizontal) it.centerX() else it.centerY() }
        if (visible.size < 2) return
        val startCenter = if (horizontal) cluster.minOf { it.centerX() } else cluster.minOf { it.centerY() }
        val endCenter = if (horizontal) cluster.maxOf { it.centerX() } else cluster.maxOf { it.centerY() }
        val span = endCenter - startCenter
        if (span <= 0) return
        val step = span / (visible.size - 1).toFloat()
        val maxOffset = maxOf(dp(group, 260), span / 2)
        visible.forEachIndexed { index, element ->
            val targetCenter = (startCenter + step * index).roundToInt()
            val offset = targetCenter - if (horizontal) element.centerX() else element.centerY()
            if (kotlin.math.abs(offset) <= 2 || kotlin.math.abs(offset) > maxOffset) return@forEachIndexed
            if (horizontal) {
                moveHiddenUiRowTargetBy(element.view, offset, 0, updateX = true, updateY = false, activeTargets = activeTargets)
            } else {
                moveHiddenUiRowTargetBy(element.view, 0, offset, updateX = false, updateY = true, activeTargets = activeTargets)
            }
        }
    }

    private fun clusterLeft(elements: List<HiddenUiRowElement>) = elements.minOfOrNull { it.left } ?: 0
    private fun clusterTop(elements: List<HiddenUiRowElement>) = elements.minOfOrNull { it.top } ?: 0
    private fun clusterRight(elements: List<HiddenUiRowElement>) = elements.maxOfOrNull { it.right } ?: 0
    private fun clusterBottom(elements: List<HiddenUiRowElement>) = elements.maxOfOrNull { it.bottom } ?: 0

    private fun adjustHiddenUiRowTarget(group: ViewGroup, target: View, shift: Int, activeTargets: MutableSet<View>?) {
        if (shift > 0) moveHiddenUiRowTargetBy(target, -shift, 0, updateX = true, updateY = false, activeTargets = activeTargets)
    }

    private fun adjustHiddenUiColumnTarget(group: ViewGroup, target: View, shift: Int, activeTargets: MutableSet<View>?) {
        if (shift > 0) moveHiddenUiRowTargetBy(target, 0, -shift, updateX = false, updateY = true, activeTargets = activeTargets)
    }

    private fun moveHiddenUiRowTargetBy(target: View, offsetX: Int, offsetY: Int, updateX: Boolean, updateY: Boolean, activeTargets: MutableSet<View>?) {
        activeTargets?.add(target)
        val original = hiddenUiRowAdjustments.getOrPut(target) { HiddenUiRowAdjustment(target) }
        if (updateX) original.appliedShiftX = -offsetX
        if (updateY) original.appliedShiftY = -offsetY
        runCatching {
            hiddenUiInternalChange.set(true)
            target.translationX = original.translationX - original.appliedShiftX
            target.translationY = original.translationY - original.appliedShiftY
            requestHiddenUiLayout(target)
        }.onFailure { logError("Failed to compact Instagram hidden UI row", it) }
        hiddenUiInternalChange.remove()
    }

    private fun enforceHiddenUiRowAdjustment(target: View?) {
        val original = target?.let { hiddenUiRowAdjustments[it] } ?: return
        if (original.appliedShiftX == 0 && original.appliedShiftY == 0) return
        runCatching {
            hiddenUiInternalChange.set(true)
            target.translationX = original.translationX - original.appliedShiftX
            target.translationY = original.translationY - original.appliedShiftY
        }
        hiddenUiInternalChange.remove()
    }

    private fun restoreInactiveHiddenUiRowAdjustments(root: View, activeTargets: Set<View>) {
        val entries = synchronized(hiddenUiRowAdjustments) { hiddenUiRowAdjustments.entries.toList() }
        entries.forEach { (target, original) ->
            if (target == null || (target !== root && !isHiddenUiDescendant(target, root))) return@forEach
            if (target in activeTargets) return@forEach
            restoreHiddenUiRowAdjustment(target, original)
            hiddenUiRowAdjustments.remove(target)
        }
    }

    private fun restoreHiddenUiRowAdjustment(target: View, original: HiddenUiRowAdjustment) {
        runCatching {
            hiddenUiInternalChange.set(true)
            target.translationX = original.translationX
            target.translationY = original.translationY
            requestHiddenUiLayout(target)
        }.onFailure { logError("Failed to restore Instagram hidden UI row compaction", it) }
        hiddenUiInternalChange.remove()
    }

    private fun isHiddenUiRowCompactionCandidate(view: View, width: Int, height: Int, group: ViewGroup, hidden: Boolean): Boolean {
        if (width <= 0 || height <= 0 || isComposerOrTextInputUiContext(view)) return false
        val groupWidth = maxOf(group.width, group.measuredWidth)
        val maxWidth = maxOf(dp(group, 220), (groupWidth * 0.42f).roundToInt())
        if (width > maxWidth) return false
        if (height > maxOf(dp(group, 96), (maxOf(group.height, group.measuredHeight) * 0.9f).roundToInt())) return false
        val className = view.javaClass.name.lowercase(Locale.US)
        if (className.contains("recyclerview") || className.contains("scrollview") ||
            className.contains("viewpager") || className.contains("nestedscroll") || className.contains("edittext")
        ) return false
        if (className.contains("textview") && width > dp(group, 180)) return false
        if (view is ViewGroup) {
            if (view.childCount > 6) return false
            if (!hidden && width > dp(group, 180) && !hasHiddenUiActionLikeName(view)) return false
        }
        return true
    }

    private fun hasHiddenUiActionLikeName(view: View): Boolean {
        val lower = "${resourceEntryName(view).orEmpty()} ${view.javaClass.name}".lowercase(Locale.US)
        return lower.contains("action") || lower.contains("button") || lower.contains("icon") ||
            lower.contains("like") || lower.contains("comment") || lower.contains("share") ||
            lower.contains("send") || lower.contains("bookmark") || lower.contains("save") ||
            lower.contains("search") || lower.contains("home") || lower.contains("profile") ||
            lower.contains("avatar") || lower.contains("direct") || lower.contains("message") ||
            lower.contains("camera") || lower.contains("gallery") || lower.contains("voice") ||
            lower.contains("reply") || lower.contains("reaction") || lower.contains("follow") ||
            lower.contains("more") || lower.contains("overflow") || lower.contains("ufi")
    }

    private fun hasHiddenUiSlotContainerName(view: View): Boolean {
        val lower = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        if (lower.contains("composer")) return false
        return lower.contains("actions") || lower.contains("action_bar") || lower.contains("button_bar") ||
            lower.contains("buttons") || lower.contains("navigation") || lower.contains("nav_bar") ||
            lower.contains("tab_bar") || lower.contains("tabs") || lower.contains("toolbar") ||
            lower.contains("header") || lower.contains("footer") || lower.contains("rail") ||
            lower.contains("tray") || lower.contains("controls") || lower.contains("ufi")
    }

    private fun isHiddenUiDescendant(view: View, ancestor: View): Boolean {
        var current: View? = view
        while (current != null) {
            if (current === ancestor) return view !== ancestor
            current = current.parent as? View
        }
        return false
    }

    private fun shouldHideView(view: View): Boolean {
        val current = state
        val rules = hiddenUiRules(current)
        if (!rules.hasExplicit && !hasBroadViewHideRule(current)) return false
        if (matchesExplicitHiddenUiRule(view, rules)) return true
        if (!hasBroadViewHideRule(current)) return false
        val resourceId = resourceEntryName(view)
        val content = view.contentDescription?.toString().orEmpty()
        val haystack = listOfNotNull(resourceId, content, view.javaClass.name)
            .joinToString(" ")
            .lowercase()
        return when {
            current.isExtremeMode && (haystack.contains("feed") || haystack.contains("reel") || haystack.contains("explore") || haystack.contains("story")) -> true
            current.disableStories && (haystack.contains("story") || looksLikeHomeStoryTrayHaystack(haystack)) -> true
            current.disableFeed && haystack.contains("feed") -> true
            current.disableReels && shouldHideForDisabledReels(haystack, current) -> true
            current.disableExplore && (haystack.contains("explore") || haystack.contains("search_tab")) -> true
            current.disableComments && haystack.contains("comment") -> true
            else -> false
        }
    }

    private fun looksLikeHomeStoryTrayHaystack(haystack: String): Boolean {
        return haystack.contains("story_tray") ||
            haystack.contains("stories_tray") ||
            haystack.contains("stories_in_feed_tray") ||
            haystack.contains("reel_tray") ||
            haystack.contains("reels_tray") ||
            haystack.contains("tray_pulsing_avatar") ||
            haystack.contains("avatar_reel")
    }

    private fun shouldHideForDisabledReels(haystack: String, current: InstagramFeatureState): Boolean {
        if (current.disableReelsExceptDM && haystack.contains("direct")) return false
        if (looksLikeHomeStoryTrayHaystack(haystack)) return false
        if (haystack.contains("feed_preview") ||
            haystack.contains("row_feed") ||
            haystack.contains("main_feed") ||
            haystack.contains("feed_timeline")
        ) return false
        return haystack.contains("reels_tab") ||
            haystack.contains("reel_tab") ||
            haystack.contains("clips_tab") ||
            haystack.contains("clips_viewer") ||
            haystack.contains("root_clips_layout") ||
            haystack.contains("clips_linear_layout_container") ||
            haystack.contains("clips_ufi")
    }

    private fun shouldHideText(text: String): Boolean {
        val lower = text.lowercase()
        if (lower.isBlank()) return false
        return when {
            state.disableComments && (lower == "comments" || lower.contains("add a comment")) -> true
            state.disableReels && lower == "reels" -> true
            state.disableStories && lower == "stories" -> true
            else -> false
        }
    }

    private fun hideLivePresenceIfNeeded(view: View) {
        val name = resourceEntryName(view)
        if (!isLivePresenceName(name)) return

        var target: View = view
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 3) {
            val parent = current.parent as? View ?: break
            val parentName = resourceEntryName(parent)
            if (parentName != null && (
                    parentName.contains("recycler") ||
                        parentName.contains("viewer") ||
                        parentName.contains("broadcast")
                    )
            ) {
                break
            }
            target = parent
            current = parent
        }

        target.alpha = 0f
        target.visibility = View.GONE
    }

    private fun isLivePresenceName(name: String?): Boolean {
        return name != null && (
            name.startsWith("iglive_presence") ||
                name.contains("layout_iglive_presence") ||
                name.contains("live_presence_overlay")
            )
    }

    private fun hideView(view: View, reason: String) {
        if (view.visibility == View.GONE) return
        val logKey = resourceEntryName(view) ?: view.javaClass.name
        rememberHiddenUiState(view)
        runCatching {
            hiddenUiInternalChange.set(true)
            view.visibility = View.GONE
            view.alpha = 0f
            view.isEnabled = false
            view.isClickable = false
            view.isLongClickable = false
            forceHiddenLayout(view)
        }.onFailure { throwable ->
            logError("Failed to hide Instagram UI view", throwable)
        }
        hiddenUiInternalChange.remove()
        if (hiddenUiLoggedKeys.add(logKey)) {
            logInfo("Hidden Instagram UI element from $reason: $logKey")
        }
    }

    private fun forceHiddenLayout(view: View) {
        view.layoutParams?.let { params ->
            if (params.width == 0 && params.height == 0) return
            params.width = 0
            params.height = 0
            view.layoutParams = params
        }
    }

    private fun hideSponsoredSurfaceIfNeeded(view: View?) {
        if (view == null || sponsoredHiddenViews.contains(view)) return
        val name = resourceEntryName(view)
        if (isSponsoredResourceName(name) || isAdDisclosureResourceName(name)) hideSponsoredContainer(view)
    }

    private fun shouldCheckSponsoredContainerView(view: View): Boolean {
        val name = resourceEntryName(view)
        return isSponsoredResourceName(name) || isAdDisclosureResourceName(name)
    }

    private fun hasDirectSponsoredSignal(view: View): Boolean {
        val name = resourceEntryName(view)
        if (isSponsoredResourceName(name) || isAdDisclosureResourceName(name)) return true
        if (view is TextView) {
            val text = view.text?.toString().orEmpty()
            val description = view.contentDescription?.toString().orEmpty()
            return isSponsoredText(text) || isSponsoredText(description) ||
                isAdDisclosureText(text) || isAdDisclosureText(description)
        }
        if (view !is ViewGroup) return false
        val limit = minOf(view.childCount, 6)
        for (index in 0 until limit) {
            val child = view.getChildAt(index) ?: continue
            val childName = resourceEntryName(child)
            if (isSponsoredResourceName(childName) || isAdDisclosureResourceName(childName)) return true
            if (child is TextView) {
                val childText = child.text?.toString().orEmpty()
                val childDescription = child.contentDescription?.toString().orEmpty()
                if (isSponsoredText(childText) || isSponsoredText(childDescription) ||
                    isAdDisclosureText(childText) || isAdDisclosureText(childDescription)
                ) return true
            }
        }
        return false
    }

    private fun hideSponsoredContainer(anchor: View) {
        var target = findSponsoredHideTarget(anchor)
        var allowLargeSponsoredTarget = target != null &&
            target !== anchor &&
            runCatching { isSponsoredViewTree(target) }.getOrDefault(false)
        if (target == null || isUnsafeHideTarget(target, allowLargeSponsoredTarget)) {
            target = anchor
            allowLargeSponsoredTarget = false
        }
        if (isUnsafeHideTarget(target, allowLargeSponsoredTarget)) return
        sponsoredHiddenViews += target
        target.alpha = 0f
        target.visibility = View.GONE
    }

    private fun findSponsoredHideTarget(anchor: View): View? {
        val anchorText = (anchor as? TextView)?.text?.toString()
        val anchorIsDisclosure = isSponsoredText(anchorText) || isAdDisclosureText(anchorText)
        var target: View? = if (isUnsafeHideTarget(anchor)) null else anchor
        var current: View? = anchor
        var depth = 0
        while (depth++ < 12 && current != null) {
            val parentView = current.parent as? View ?: break
            val parentName = resourceEntryName(parentView)
            if (isHardListBoundary(parentView)) break
            if (isStrongSponsoredCardContainer(parentName)) {
                target = parentView
                break
            }
            if (anchorIsDisclosure &&
                !isUnsafeGlobalResourceName(parentName) &&
                isSponsoredViewTree(parentView)
            ) {
                target = parentView
                current = parentView
                continue
            }
            if (isUnsafeHideTarget(parentView)) break
            if (isLikelySponsoredCardContainer(parentName) && !isTooLargeToHide(parentView)) target = parentView
            if (depth <= 1 && isSponsoredResourceName(parentName) && !isTooLargeToHide(parentView)) target = parentView
            current = parentView
        }
        return target
    }

    private fun isSponsoredViewTree(root: View): Boolean {
        val scan = SponsoredViewScan()
        scanSponsoredViewTree(root, scan, 0)
        return scan.hasSponsoredText ||
            scan.hasSponsoredResource ||
            (scan.hasAdDisclosureText && (scan.hasAdDisclosureResource || scan.hasAdCtaText || scan.hasFeedContainer))
    }

    private fun scanSponsoredViewTree(view: View?, scan: SponsoredViewScan, depth: Int) {
        if (view == null || scan.visited > 220 || depth > 16) return
        scan.visited++
        val name = resourceEntryName(view)
        if (isSponsoredResourceName(name)) scan.hasSponsoredResource = true
        if (isAdDisclosureResourceName(name)) scan.hasAdDisclosureResource = true
        if (isLikelySponsoredCardContainer(name) || isStrongSponsoredCardContainer(name)) scan.hasFeedContainer = true
        if (view is TextView) {
            val text = view.text?.toString().orEmpty()
            val description = view.contentDescription?.toString().orEmpty()
            if (isSponsoredText(text) || isSponsoredText(description)) scan.hasSponsoredText = true
            if (isAdDisclosureText(text) || isAdDisclosureText(description)) scan.hasAdDisclosureText = true
            if (isAdCtaText(text)) scan.hasAdCtaText = true
        }
        if (view !is ViewGroup) return
        for (i in 0 until view.childCount) {
            scanSponsoredViewTree(view.getChildAt(i), scan, depth + 1)
            if (scan.hasSponsoredText || scan.hasSponsoredResource ||
                (scan.hasAdDisclosureText && (scan.hasAdDisclosureResource || scan.hasAdCtaText || scan.hasFeedContainer))
            ) return
        }
    }

    private data class SponsoredViewScan(
        var visited: Int = 0,
        var hasSponsoredText: Boolean = false,
        var hasSponsoredResource: Boolean = false,
        var hasAdDisclosureText: Boolean = false,
        var hasAdDisclosureResource: Boolean = false,
        var hasAdCtaText: Boolean = false,
        var hasFeedContainer: Boolean = false
    )

    private fun isAdCtaText(text: String?): Boolean {
        return when (text?.trim()?.lowercase(Locale.US)) {
            "learn more", "shop now", "sign up", "install", "download", "book now",
            "apply now", "contact us", "send message", "chat on whatsapp", "watch more",
            "get offer", "order now", "subscribe", "follow", "message", "view profile",
            "visit profile", "visit instagram profile", "see more", "try now", "use app",
            "get quote", "view shop" -> true
            else -> false
        }
    }

    private fun isHardListBoundary(view: View): Boolean {
        val className = view.javaClass.name
        return className.contains("RecyclerView") ||
            className.contains("ViewPager") ||
            className.contains("ViewPager2") ||
            className.contains("NestedScrollView")
    }

    private fun isLikelySponsoredCardContainer(name: String?): Boolean {
        val value = name?.lowercase(Locale.US) ?: return false
        return value.startsWith("row_feed") ||
            value.contains("feed_item") ||
            value.contains("feed_timeline") ||
            value.startsWith("clips_item") ||
            value.startsWith("clips_viewer_item") ||
            value.startsWith("reel_item") ||
            value.contains("sponsored_card") ||
            value.contains("sponsored_item") ||
            value.contains("sponsored_unit")
    }

    private fun isStrongSponsoredCardContainer(name: String?): Boolean {
        val value = name?.lowercase(Locale.US) ?: return false
        return value == "in_feed_item_container" ||
            value == "product_feed_item" ||
            value == "shopping_ads_grid_item_sponsored" ||
            value == "custom_ad_row" ||
            value == "on_feed_advertiser_disclosure_view" ||
            value.startsWith("ad_card_") ||
            value.startsWith("collection_ad_") ||
            value.startsWith("intent_aware_ad_") ||
            value.startsWith("lead_gen_card") ||
            value == "lead_ad_multi_submit_row" ||
            value == "promote_ad_messaging_post_selector_card" ||
            value == "profile_extension_ad_two_by_two_grid_card" ||
            value == "sponsored_clips_showreel_view" ||
            value == "sponsored_reel_showreel_composition_view" ||
            value == "story_interstitial_reel_item_container"
    }

    private fun isSponsoredResourceName(name: String?): Boolean {
        val value = name?.lowercase(Locale.US) ?: return false
        return value.contains("sponsored") ||
            value.contains("advertiser_disclosure") ||
            value.contains("ad_label") ||
            value == "row_feed_cta" ||
            value == "row_feed_cta_stub" ||
            value == "row_feed_cta_wrapper" ||
            value == "row_feed_cta_redesign" ||
            value == "row_feed_cta_overlay" ||
            value.contains("feed_delayed_skip_ad") ||
            value.contains("story_delayed_skip_ad") ||
            value.contains("reel_bottom_ad_banner") ||
            value.contains("reel_item_ad_label") ||
            value.contains("messaging_ad_suggested_post") ||
            value.contains("inbox_messaging_ad_response") ||
            value.contains("ad_overlay") ||
            value.contains("feed_ad_end_card") ||
            value.contains("lead_ad_multi_submit") ||
            value.contains("intent_aware_ad") ||
            value.contains("collection_ad") ||
            value.contains("shopping_ads_grid_item_sponsored") ||
            value.contains("sponsored_label") ||
            value.contains("sponsored_content") ||
            value.contains("clips_sponsored") ||
            value.contains("feed_sponsored") ||
            value.contains("reel_sponsored") ||
            value.contains("on_media_sponsored") ||
            value.contains("bottom_right_sponsored")
    }

    private val sponsoredTextRegex = Regex("^sponsored\\s*[·.]*\\s*$", RegexOption.IGNORE_CASE)
    private val sponsoredLabelTexts = setOf(
        "sponsored",
        "anzeige",
        "gesponsert",
        "werbung",
        "publicidad",
        "patrocinado",
        "sponsorizzato",
        "reklama",
        "reklame",
        "advertentie",
        "anuncio",
        "annuncio",
        "promocionado",
        "promovido"
    )
    private val adDisclosureTextRegex = Regex("^ad\\s*\\W{0,2}\\s*$", RegexOption.IGNORE_CASE)
    private val emailPattern = Regex("[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,}")
    private val displayNamePattern = Regex("[\\p{L} ._'-]+")
    private val dimensionPattern = Regex("""(?:s|p)?(\d{2,4})x(\d{2,4})""")
    private val whitespacePattern = Regex("\\s+")

    private fun isSponsoredText(text: String?): Boolean {
        val clean = text?.trim()?.replace("\u00C2\u00B7", "\u00B7").orEmpty()
        if (clean.isEmpty()) return false
        val normalized = clean.trimEnd('.', '\u00B7', '\u2022').trim().lowercase(Locale.US)
        return normalized in sponsoredLabelTexts ||
            clean.equals("Sponsored ·", ignoreCase = true) ||
            clean.matches(sponsoredTextRegex)
    }

    private fun isAdDisclosureText(text: String?): Boolean {
        val clean = text?.trim().orEmpty()
        if (clean.isEmpty()) return false
        return clean.equals("Ad", ignoreCase = true) ||
            clean.matches(adDisclosureTextRegex)
    }

    private fun isAdDisclosureResourceName(name: String?): Boolean {
        val value = name?.lowercase(Locale.US) ?: return false
        return value == "on_feed_advertiser_disclosure_view" ||
            value == "label_top_sponsored" ||
            value == "reel_item_ad_label_media_bottom_right" ||
            value.contains("advertiser_disclosure") ||
            value.contains("sponsored_label") ||
            value.contains("_ad_label")
    }

    private fun hasFeedAdDisclosureContext(view: View): Boolean {
        val ownName = resourceEntryName(view)
        if (isAdDisclosureResourceName(ownName)) return true
        var current: View? = view
        var depth = 0
        while (depth++ < 6 && current != null) {
            val parentView = current.parent as? View ?: break
            val parentName = resourceEntryName(parentView)
            if (parentName != null) {
                val lowerName = parentName.lowercase(Locale.US)
                if (lowerName == "row_feed_profile_header" ||
                    lowerName == "on_feed_profile_header_view" ||
                    lowerName == "row_feed_media_profile_header" ||
                    lowerName.contains("sponsored_label")
                ) return true
                if (isHardListBoundary(parentView) || isUnsafeGlobalResourceName(parentName)) return false
            }
            current = parentView
        }
        return false
    }

    private fun hasAdDisclosureNeighborContext(view: View): Boolean {
        var current: View? = view
        var depth = 0
        while (depth++ < 8 && current != null) {
            val parentView = current.parent as? View ?: break
            val parentName = resourceEntryName(parentView)
            if (isHardListBoundary(parentView) || isUnsafeGlobalResourceName(parentName)) return false
            val lowerName = parentName?.lowercase(Locale.US).orEmpty()
            if (lowerName.contains("clips") ||
                lowerName.contains("reel") ||
                lowerName.contains("feed") ||
                lowerName.contains("media") ||
                lowerName.contains("profile_header")
            ) return true
            if (isSponsoredViewTree(parentView)) return true
            current = parentView
        }
        return false
    }

    private fun isUnsafeHideTarget(view: View?, allowLargeSponsored: Boolean = false): Boolean {
        if (view == null) return true
        val name = resourceEntryName(view)
        if (isStrongSponsoredCardContainer(name)) return false
        if (view.rootView == view || isHardListBoundary(view)) return true
        if (!allowLargeSponsored && isTooLargeToHide(view)) return true
        if (isUnsafeGlobalResourceName(name)) return true
        val className = view.javaClass.name
        return className.contains("CoordinatorLayout") ||
            className.contains("DrawerLayout") ||
            className.contains("SwipeRefreshLayout") ||
            className.contains("FragmentContainerView")
    }

    private fun isUnsafeGlobalResourceName(name: String?): Boolean {
        val lowerName = name?.lowercase(Locale.US) ?: return false
        return lowerName == "content" ||
            lowerName == "android:id/content" ||
            lowerName.contains("root") ||
            lowerName.contains("fragment") ||
            lowerName.contains("main_container") ||
            lowerName.contains("navigation") ||
            lowerName.contains("nav_bar") ||
            lowerName.contains("tab_bar") ||
            lowerName.contains("feed_view") ||
            lowerName.contains("view_pager")
    }

    private fun isTooLargeToHide(view: View): Boolean {
        val width = view.width
        val height = view.height
        if (width <= 0 || height <= 0) return false
        val metrics = view.resources.displayMetrics
        return width >= metrics.widthPixels * 0.92f && height >= metrics.heightPixels * 0.82f
    }

    private fun getViewHolderItemView(holder: Any?): View? {
        if (holder == null) return null
        return runCatching {
            val field = holder.javaClass.getField("itemView")
            field.get(holder) as? View
        }.getOrNull()
    }

    private fun hideConversationRow(textView: TextView) {
        val row = findConversationRowContainer(textView) ?: textView
        row.visibility = View.GONE
        row.alpha = 0f
        row.layoutParams?.let { params ->
            params.height = 0
            row.layoutParams = params
        }
    }

    private fun findConversationRowContainer(start: View): View? {
        var current: View? = start
        repeat(10) {
            val active = current ?: return@repeat
            val parent = active.parent as? View ?: return active
            val parentId = resourceEntryName(parent).orEmpty()
            val parentClass = parent.javaClass.name
            if (parentId == "inbox_refreshable_thread_list_recyclerview" ||
                parentId == "target_thread_list" ||
                parentId == "existing_thread_recycler_view" ||
                parentClass.contains("RecyclerView") ||
                parentClass.contains("ListView")
            ) {
                return active
            }
            current = parent
        }
        return current
    }

    private fun maybeCollectOrHideChatRow(textView: TextView, raw: String): Boolean {
        rememberCurrentDirectAccountNameIfAny(textView, raw)
        purgeDirectNoteTrayNameIfAny(textView, raw)
        if (!isDirectConversationNameTextView(textView)) return false
        val displayName = cleanChatName(raw)
        if (displayName.isBlank()) return false
        if (!isInboxConversationListView(textView) || isSearchSurface(textView)) return false
        if (!isDirectThreadNameView(textView) && !isPlausibleChatName(displayName)) return false

        scheduleDirectChatDatabaseSnapshot("direct_inbox", 1_500L)

        recordObservedDirectInboxChatName(displayName)
        recordKnownChatName(displayName)

        if (!state.enableHideChats) return false
        val hiddenNames = parseChatNameLines(state.hiddenChatNames).map { it.lowercase(Locale.US) }.toSet()
        if (hiddenNames.isEmpty() || displayName.lowercase(Locale.US) !in hiddenNames) return false
        hideConversationRow(textView)
        return true
    }

    private fun rememberCurrentDirectAccountNameIfAny(textView: TextView, raw: String) {
        val ownName = resourceEntryName(textView).orEmpty().lowercase(Locale.US)
        if (ownName != "igds_action_bar_title") return
        if (!hasAncestorNamed(textView, "direct_inbox_action_bar", 6)) return
        val accountName = cleanChatName(raw).takeIf { isPlausibleChatName(it) } ?: return
        purgeKnownChatName(accountName, "direct_account_header")
    }

    private fun purgeDirectNoteTrayNameIfAny(textView: TextView, raw: String) {
        if (!hasAncestorNamed(textView, "cf_hub_recycler_view", 8)) return
        val name = cleanChatName(raw).takeIf { isPlausibleChatName(it) } ?: return
        purgeKnownChatName(name, "direct_note_tray")
    }

    private fun isDirectConversationNameTextView(textView: TextView): Boolean {
        val ownName = resourceEntryName(textView).orEmpty().lowercase(Locale.US)
        if (ownName == "ig_text" && hasAncestorNamed(textView, "igds_people_cell", 5)) return false
        if (hasAncestorNamed(textView, "direct_inbox_action_bar", 6)) return false
        if (hasAncestorNamed(textView, "cf_hub_recycler_view", 8)) return false
        if (hasAncestorNamed(textView, "igds_people_cell", 6)) return false
        if (ownName == "row_inbox_username") return hasAncestorNamed(textView, "row_inbox_container", 6)
        if (ownName == "thread_name" ||
            ownName == "thread_title" ||
            ownName == "direct_action_row_name" ||
            ownName == "direct_inbox_campaign_thread_name" ||
            ownName == "direct_unsupported_thread_name"
        ) {
            return hasAncestorNamed(textView, "inbox_refreshable_thread_list_recyclerview", 12) ||
                hasAncestorNamed(textView, "target_thread_list", 12) ||
                hasAncestorNamed(textView, "existing_thread_recycler_view", 12)
        }
        return false
    }

    private fun hasAncestorNamed(view: View, name: String, maxDepth: Int): Boolean {
        var current: View? = view
        repeat(maxDepth) {
            val active = current ?: return false
            if (resourceEntryName(active).orEmpty().equals(name, ignoreCase = true)) return true
            current = active.parent as? View
        }
        return false
    }

    private fun isPotentialDirectChatTextView(textView: TextView): Boolean {
        val ownName = resourceEntryName(textView).orEmpty().lowercase(Locale.US)
        if (ownName == "thread_name" ||
            ownName == "thread_title" ||
            ownName == "direct_action_row_name" ||
            ownName == "direct_inbox_campaign_thread_name" ||
            ownName == "direct_unsupported_thread_name" ||
            ownName.contains("direct") ||
            ownName.contains("inbox") ||
            ownName.contains("thread")
        ) return true
        var current = textView.parent as? View
        repeat(4) {
            val view = current ?: return@repeat
            val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
            val cls = view.javaClass.name.lowercase(Locale.US)
            if (name.contains("direct") || name.contains("inbox") || name.contains("thread") ||
                cls.contains("direct") || cls.contains("inbox") || cls.contains("thread")
            ) return true
            current = view.parent as? View
        }
        return false
    }

    private fun purgeKnownChatName(displayName: String, reason: String) {
        val normalized = cleanChatName(displayName).lowercase(Locale.US)
        if (normalized.isBlank()) return
        var changed = false
        synchronized(knownChatNames) {
            if (knownChatNames.isEmpty()) knownChatNames.addAll(parseChatNameLines(state.knownChatNames))
            changed = knownChatNames.removeAll { it.lowercase(Locale.US) == normalized }
        }
        if (changed) {
            scheduleKnownChatNamesPersist()
            logInfo("Removed non-conversation Instagram Direct picker entry reason=$reason")
        }
    }

    private fun recordObservedDirectInboxChatName(displayName: String) {
        val clean = cleanChatName(displayName).takeIf { isPlausibleChatName(it) } ?: return
        lastObservedDirectInboxChatNameMs = System.currentTimeMillis()
        synchronized(observedDirectInboxChatNames) {
            if (observedDirectInboxChatNames.none { it.equals(clean, ignoreCase = true) }) {
                observedDirectInboxChatNames += clean
            }
        }
        scheduleDirectChatPruneToObservedInbox()
    }

    private fun scheduleDirectChatPruneToObservedInbox() {
        if (directChatPruneScheduled) return
        directChatPruneScheduled = true
        mainHandler.postDelayed({
            directChatPruneScheduled = false
            if (System.currentTimeMillis() - lastObservedDirectInboxChatNameMs < 2_000L) {
                scheduleDirectChatPruneToObservedInbox()
                return@postDelayed
            }
            pruneKnownChatNamesToObservedInbox()
        }, 3_000L)
    }

    private fun pruneKnownChatNamesToObservedInbox() {
        collectVisibleDirectInboxRowNames(currentActivity?.window?.decorView)
        val observed = synchronized(observedDirectInboxChatNames) {
            observedDirectInboxChatNames.map { it.lowercase(Locale.US) }.toSet()
        }
        if (observed.size < 2) return
        val hidden = parseChatNameLines(state.hiddenChatNames).map { it.lowercase(Locale.US) }.toSet()
        var removed = 0
        synchronized(knownChatNames) {
            if (knownChatNames.isEmpty()) knownChatNames.addAll(parseChatNameLines(state.knownChatNames))
            removed = knownChatNames.count { name ->
                val key = name.lowercase(Locale.US)
                key !in observed && key !in hidden
            }
            if (removed > 0) knownChatNames.removeAll { name ->
                val key = name.lowercase(Locale.US)
                key !in observed && key !in hidden
            }
        }
        if (removed > 0) {
            scheduleKnownChatNamesPersist()
            logInfo("Pruned $removed non-visible Instagram Direct picker entries to match inbox rows")
        }
    }

    private fun collectVisibleDirectInboxRowNames(root: View?) {
        if (root == null) return
        var visited = 0
        fun visit(view: View) {
            if (visited++ > 900 || view.visibility != View.VISIBLE) return
            if (view is TextView && isDirectConversationNameTextView(view)) {
                val name = cleanChatName(view.text?.toString().orEmpty())
                if (isPlausibleChatName(name)) {
                    synchronized(observedDirectInboxChatNames) {
                        if (observedDirectInboxChatNames.none { it.equals(name, ignoreCase = true) }) {
                            observedDirectInboxChatNames += name
                        }
                    }
                }
            }
            if (view is ViewGroup) {
                val count = view.childCount.coerceAtMost(120)
                for (i in 0 until count) visit(view.getChildAt(i))
            }
        }
        visit(root)
    }

    private fun recordKnownChatName(displayName: String) {
        val normalized = cleanChatName(displayName).lowercase(Locale.US)
        if (normalized.isBlank()) return
        synchronized(knownChatNames) {
            if (knownChatNames.isEmpty()) knownChatNames.addAll(parseChatNameLines(state.knownChatNames))
            if (knownChatNames.any { it.lowercase(Locale.US) == normalized }) return
            knownChatNames += displayName
            scheduleKnownChatNamesPersist()
            logInfo("Collected Instagram Direct chat for picker: $displayName")
        }
    }

    private fun scheduleKnownChatNamesPersist() {
        if (knownChatNamesPersistScheduled) return
        knownChatNamesPersistScheduled = true
        mainHandler.postDelayed({
            val snapshot = synchronized(knownChatNames) { knownChatNames.joinToString("\n") }
            knownChatNamesPersistScheduled = false
            persistStringFeatureUpdate("knownChatNames", snapshot)
        }, 1_000L)
    }

    private fun scheduleDirectChatDatabaseSnapshot(reason: String, delayMs: Long = 0L) {
        if (!state.enableHideChats) return
        val now = System.currentTimeMillis()
        if (directChatDatabaseSnapshotScheduled) return
        if (!reason.startsWith("direct_") &&
            now - lastDirectChatDatabaseSnapshotMs < 10 * 60_000L &&
            lastDirectChatDatabaseSnapshotSource == "database"
        ) return
        directChatDatabaseSnapshotScheduled = true
        mainHandler.postDelayed({
            Thread({
                try {
                    val names = snapshotDirectChatNamesFromDatabases()
                    lastDirectChatDatabaseSnapshotMs = System.currentTimeMillis()
                    if (names.isNotEmpty()) {
                        lastDirectChatDatabaseSnapshotSource = "database"
                        mergeKnownChatNames(names)
                        logInfo("Instagram Direct chat database snapshot collected ${names.size} names reason=$reason")
                    } else {
                        lastDirectChatDatabaseSnapshotSource = "empty"
                        logInfo("Instagram Direct chat database snapshot found no names reason=$reason")
                    }
                } finally {
                    directChatDatabaseSnapshotScheduled = false
                }
            }, "Purrfect-InstagramDirectDbSnapshot").start()
        }, delayMs)
    }

    private fun mergeKnownChatNames(names: Collection<String>) {
        val cleanNames = names.map(::cleanChatName)
            .filter(::isPlausibleChatName)
            .distinctBy { it.lowercase(Locale.US) }
        if (cleanNames.isEmpty()) return
        var changed = false
        synchronized(knownChatNames) {
            if (knownChatNames.isEmpty()) knownChatNames.addAll(parseChatNameLines(state.knownChatNames))
            cleanNames.forEach { name ->
                if (knownChatNames.none { it.equals(name, ignoreCase = true) }) {
                    knownChatNames += name
                    changed = true
                }
            }
        }
        if (changed) scheduleKnownChatNamesPersist()
    }

    private fun maybeCollectDirectChatNamesFromStorageWrite(table: String, values: ContentValues?) {
        if (values == null || values.size() == 0) return
        val keys = values.keySet().map { it.toString() }
        if (!looksLikeDirectChatStorage(table, keys)) return
        val names = keys.mapNotNull { key ->
            if (!looksLikeDirectChatNameColumn(key)) return@mapNotNull null
            values.getAsString(key)?.let(::cleanChatName)?.takeIf(::isPlausibleChatName)
        }.distinctBy { it.lowercase(Locale.US) }
        if (names.isEmpty()) return
        mergeKnownChatNames(names)
        logInfo("Collected Instagram Direct chats from SQLite write: count=${names.size} table=$table")
    }

    private fun looksLikeDirectChatStorage(table: String, keys: Collection<String>): Boolean {
        val lowerTable = table.lowercase(Locale.US)
        if (lowerTable.contains("direct") ||
            lowerTable.contains("inbox") ||
            lowerTable.contains("thread") ||
            lowerTable.contains("conversation") ||
            lowerTable.contains("recipient") ||
            lowerTable.contains("participant")
        ) return true
        return keys.any { key ->
            val lower = key.lowercase(Locale.US)
            lower.contains("direct") ||
                lower.contains("thread") ||
                lower.contains("conversation") ||
                lower.contains("recipient") ||
                lower.contains("participant")
        }
    }

    private fun looksLikeDirectChatNameColumn(column: String): Boolean {
        val lower = column.lowercase(Locale.US)
        return lower == "username" ||
            lower == "user_name" ||
            lower == "full_name" ||
            lower == "display_name" ||
            lower == "thread_title" ||
            lower == "thread_name" ||
            lower == "conversation_title" ||
            lower == "conversation_name" ||
            lower == "recipient_name" ||
            lower == "participant_name" ||
            lower.endsWith("_username") ||
            lower.endsWith("_full_name")
    }

    private fun snapshotDirectChatNamesFromDatabases(): List<String> {
        val dbDir = androidContext.getDatabasePath("purrfect-probe").parentFile ?: return emptyList()
        val files = dbDir.listFiles().orEmpty()
            .filter { file ->
                file.isFile &&
                    !file.name.endsWith("-wal") &&
                    !file.name.endsWith("-shm") &&
                    !file.name.endsWith("-journal") &&
                    file.length() > 0L
            }
            .sortedByDescending { file -> if (file.name.contains("direct", ignoreCase = true) || file.name.contains("thread", ignoreCase = true)) 1 else 0 }
            .take(24)
        val result = linkedSetOf<String>()
        files.forEach { file ->
            if (result.size >= 250) return@forEach
            scanDirectChatDatabaseFile(file, result)
        }
        return result.toList()
    }

    private fun scanDirectChatDatabaseFile(file: File, out: MutableSet<String>) {
        val db = runCatching {
            SQLiteDatabase.openDatabase(file.absolutePath, null, SQLiteDatabase.OPEN_READONLY or SQLiteDatabase.NO_LOCALIZED_COLLATORS)
        }.getOrElse { return }
        try {
            val tables = mutableListOf<String>()
            db.rawQuery("SELECT name FROM sqlite_master WHERE type='table'", null).use { cursor ->
                while (cursor.moveToNext()) cursor.getStringOrNullSafe("name")?.let { tables += it }
            }
            var schemaLogBudget = 18
            tables.take(220).forEach { table ->
                if (out.size >= 250) return@forEach
                schemaLogBudget = scanDirectChatTable(db, file.name, table, out, schemaLogBudget)
            }
        } catch (t: Throwable) {
            logError("Failed scanning Instagram Direct database ${file.name}", t)
        } finally {
            runCatching { db.close() }
        }
    }

    private fun scanDirectChatTable(
        db: SQLiteDatabase,
        dbName: String,
        table: String,
        out: MutableSet<String>,
        schemaLogBudget: Int
    ): Int {
        var remainingSchemaLogs = schemaLogBudget
        val columns = tableColumns(db, table)
        if (columns.isEmpty()) return remainingSchemaLogs
        val lowerTable = table.lowercase(Locale.US)
        val lowerColumns = columns.map { it.lowercase(Locale.US) }
        val sourceLooksDirect = lowerTable.contains("direct") ||
            lowerTable.contains("inbox") ||
            lowerTable.contains("thread") ||
            lowerTable.contains("conversation") ||
            lowerTable.contains("recipient") ||
            lowerTable.contains("participant") ||
            lowerColumns.any { column ->
                column.contains("thread") ||
                    column.contains("conversation") ||
                    column.contains("recipient") ||
                    column.contains("participant") ||
                    column.contains("direct")
            }
        if (!sourceLooksDirect) return remainingSchemaLogs
        val nameColumns = columns.filter { column ->
            looksLikeDirectChatNameColumn(column)
        }.take(8)
        val payloadColumns = columns.filter { column ->
            looksLikeDirectChatPayloadColumn(column) && column !in nameColumns
        }.take(6)
        if (remainingSchemaLogs > 0 && (nameColumns.isNotEmpty() || payloadColumns.isNotEmpty())) {
            logInfo(
                "Instagram Direct DB candidate db=$dbName table=$table " +
                    "nameColumns=${nameColumns.joinToString("|")} payloadColumns=${payloadColumns.joinToString("|")}"
            )
            remainingSchemaLogs--
        }
        val trustedInboxSource = isTrustedDirectInboxDatabaseSource(dbName, table)
        if (!trustedInboxSource) return remainingSchemaLogs
        val scanColumns = (nameColumns + payloadColumns).distinct()
        if (scanColumns.isEmpty()) return remainingSchemaLogs
        val quotedTable = quoteSqlIdentifier(table)
        val projection = scanColumns.joinToString(",") { quoteSqlIdentifier(it) }
        runCatching {
            db.rawQuery("SELECT $projection FROM $quotedTable LIMIT 600", null).use { cursor ->
                while (cursor.moveToNext() && out.size < 250) {
                    nameColumns.indices.forEach { index ->
                        val value = cursor.getStringOrNull(index)?.let(::cleanChatName) ?: return@forEach
                        if (isPlausibleChatName(value)) out += value
                    }
                    payloadColumns.indices.forEach { payloadIndex ->
                        val index = nameColumns.size + payloadIndex
                        val payload = cursor.getStringOrNull(index) ?: return@forEach
                        extractDirectChatNamesFromPayload(payload).forEach { out += it }
                    }
                }
            }
        }
        return remainingSchemaLogs
    }

    private fun isTrustedDirectInboxDatabaseSource(dbName: String, table: String): Boolean {
        val source = "${dbName.lowercase(Locale.US)} ${table.lowercase(Locale.US)}"
        if (source.contains("ranked") ||
            source.contains("call_") ||
            source.contains("call-") ||
            source.contains("recipient") ||
            source.contains("user_model") ||
            source.contains("media_key") ||
            source.contains("crypto") ||
            source.contains("incoming_db") ||
            source.contains("pending") ||
            source.contains("message_persistence") ||
            source.contains("deleted_message") ||
            source.contains("sequence")
        ) return false
        return source.contains("direct") &&
            (source.contains("inbox") || source.contains("thread") || source.contains("conversation")) &&
            !source.contains("suggest")
    }

    private fun looksLikeDirectChatPayloadColumn(column: String): Boolean {
        val lower = column.lowercase(Locale.US)
        return lower.contains("json") ||
            lower.contains("data") ||
            lower.contains("payload") ||
            lower.contains("blob") ||
            lower.contains("serialized") ||
            lower.contains("value") ||
            lower.contains("response")
    }

    private fun extractDirectChatNamesFromPayload(payload: String): List<String> {
        if (payload.length < 8 || payload.length > 250_000) return emptyList()
        val readable = payload.replace("\\\"", "\"")
        val names = linkedSetOf<String>()
        Regex(
            "\"(?:username|user_name|full_name|display_name|thread_title|thread_name|conversation_title|conversation_name|recipient_name|participant_name)\"\\s*:\\s*\"([^\"\\\\]{2,120})\""
        ).findAll(readable).forEach { match ->
            val value = cleanChatName(match.groupValues.getOrNull(1).orEmpty())
            if (isPlausibleChatName(value)) names += value
        }
        return names.toList()
    }

    private fun tableColumns(db: SQLiteDatabase, table: String): List<String> {
        return runCatching {
            val columns = mutableListOf<String>()
            db.rawQuery("PRAGMA table_info(${quoteSqlIdentifier(table)})", null).use { cursor ->
                while (cursor.moveToNext()) cursor.getStringOrNullSafe("name")?.let { columns += it }
            }
            columns
        }.getOrDefault(emptyList())
    }

    private fun quoteSqlIdentifier(value: String): String {
        return "\"" + value.replace("\"", "\"\"") + "\""
    }

    private fun Cursor.getStringOrNull(index: Int): String? {
        if (index < 0 || index >= columnCount || isNull(index)) return null
        return runCatching { getString(index) }.getOrNull()
    }

    private fun Cursor.getStringOrNullSafe(column: String): String? {
        return getStringOrNull(getColumnIndex(column))
    }

    private fun isDirectThreadNameView(textView: TextView): Boolean {
        return when (resourceEntryName(textView).orEmpty()) {
            "thread_name",
            "thread_title",
            "direct_action_row_name",
            "direct_inbox_campaign_thread_name",
            "direct_unsupported_thread_name",
            "meta_ai_voice_thread_name" -> true
            else -> false
        }
    }

    private fun isInboxConversationListView(view: View): Boolean {
        var current: View? = view
        repeat(12) {
            val id = current?.let { resourceEntryName(it) }.orEmpty()
            if (id == "inbox_refreshable_thread_list_recyclerview" ||
                id == "thread_list_container" ||
                id == "target_thread_list" ||
                id == "existing_thread_recycler_view" ||
                id == "direct_inbox_action_bar"
            ) return true
            current = current?.parent as? View
        }
        return false
    }

    private fun isSearchSurface(view: View): Boolean {
        if (hasActiveSearchInput(view.rootView ?: view)) return true
        var current: View? = view
        repeat(12) {
            val id = current?.let { resourceEntryName(it) }.orEmpty().lowercase(Locale.US)
            val cls = current?.javaClass?.name.orEmpty().lowercase(Locale.US)
            if (id.contains("search") || cls.contains("search")) return true
            current = current?.parent as? View
        }
        return false
    }

    private fun hasActiveSearchInput(view: View?): Boolean {
        if (view == null || view.visibility != View.VISIBLE) return false
        val id = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        if ((id.contains("search") || id.contains("target_thread_search")) &&
            view is EditText &&
            (view.hasFocus() || (view.text?.isNotEmpty() == true))
        ) return true
        if (view is ViewGroup) {
            val count = view.childCount.coerceAtMost(120)
            for (i in 0 until count) {
                if (hasActiveSearchInput(view.getChildAt(i))) return true
            }
        }
        return false
    }

    private fun isPlausibleChatName(value: String): Boolean {
        val clean = cleanChatName(value)
        if (clean.length !in 2..80) return false
        val lower = clean.lowercase(Locale.US)
        if (lower.contains("sent ") ||
            lower.contains("you:") ||
            lower.contains("seen") ||
            lower.contains("active") ||
            lower.contains("typing") ||
            lower.contains("replied") ||
            lower.contains("liked") ||
            lower.contains("shared") ||
            lower.contains("turned on disappearing messages") ||
            lower.contains("turned off disappearing messages") ||
            lower.contains(" ·") ||
            lower.contains("·") ||
            timeAgoPattern.matches(lower) ||
            isoDatePattern.matches(lower) ||
            timeOfDayPattern.matches(lower) ||
            lower.endsWith("...") ||
            lower.endsWith("…") ||
            lower == "notes" ||
            lower == "note" ||
            lower == "your note" ||
            lower == "add note" ||
            lower == "map" ||
            lower == "play" ||
            lower == "just curious" ||
            lower == "inspo needed" ||
            lower == "start your first note" ||
            lower == "try sharing a song" ||
            lower == "make this space yours" ||
            lower == "ask friends anything" ||
            lower == "your thoughts go here" ||
            lower == "can't decide" ||
            lower == "obsessed with" ||
            lower == "ready for" ||
            lower == "today's vibe" ||
            lower == "unpopular opinion" ||
            lower == "central park" ||
            lower == "civic center" ||
            lower == "rabindra sarovar" ||
            lower == "reply?" ||
            lower == "reply" ||
            lower == "requests" ||
            lower == "messages"
        ) return false
        return true
    }

    private fun parseChatNameLines(raw: String): List<String> {
        if (raw.isBlank()) return emptyList()
        return raw.split('\n', ',')
            .map { cleanChatName(it) }
            .filter { isPlausibleChatName(it) }
            .distinctBy { it.lowercase(Locale.US) }
    }

    private fun cleanChatName(value: String): String = value
        .replace('\n', ' ')
        .replace('\u00A0', ' ')
        .replace("Â", "")
        .trim()
        .trim('\u200e', '\u200f', ' ')

    private fun matchesHiddenSelector(view: View): Boolean {
        val rules = hiddenUiRules()
        if (rules.selectors.isEmpty()) return false
        if (view.javaClass.name !in rules.selectorLeafClasses) return false
        return rules.selectors.any { selector -> selectorMatches(view, selector) }
    }

    private fun installNavigationNativeTabFactoryHook() {
        runSafe("Navigation native tab factory hook") {
            val candidates = linkedSetOf<Class<*>>()
            runCatching { Class.forName("com.instagram.mainactivity.InstagramMainActivity", false, appClassLoader) }
                .getOrNull()
                ?.let(candidates::add)
            if (candidates.isEmpty()) {
                listOf("InstagramMainActivity.createTabButton(", "feed_tab", "clips_tab").forEach { marker ->
                    dexBridge.findClassNamesUsingStrings(marker).forEach { className ->
                        runCatching { Class.forName(className, false, appClassLoader) }.getOrNull()?.let(candidates::add)
                    }
                }
            }
            var hooked = 0
            candidates.forEach { cls ->
                cls.declaredMethods.filter(::looksLikeNavigationTabFactory).forEach { method ->
                    val signature = "${method.declaringClass.name}.${method.name}:navigation_native_tab_factory"
                    if (!hookedDexMethods.add(signature)) return@forEach
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun afterHookedMethod(param: MethodHookParam<*>) {
                                val tabView = param.result as? View ?: return
                                val enumArg = findNavigationTabEnumArg(param.args)
                                val key = inferNavigationTabKey(tabView, -1, -1) ?: mapNavigationTabEnum(enumArg) ?: return
                                nativeNavigationTabKeys[tabView] = key
                                navigationObservedTabKeys += key
                                applySingleNavigationTabVisibility(tabView, key)
                                val parent = findViewGroupArg(param.args) ?: tabView.parent as? ViewGroup
                                if (parent != null) {
                                    nativeNavigationTabBars += parent
                                    listOf(0L, 96L, 420L).forEach { delay ->
                                        mainHandler.postDelayed({
                                            applyNavigationTabBar(parent)
                                            (findActivity(parent.context) ?: currentActivity)?.let { clickDefaultNavigationTab(it) }
                                        }, delay)
                                    }
                                }
                                maybeClickDefaultNavigationTab(tabView, key)
                                mainHandler.post { applyNearNativeNavigationTab(tabView) }
                                mainHandler.postDelayed({ applyNearNativeNavigationTab(tabView) }, 160L)
                            }
                        }
                    )
                    hooked++
                }
            }
            logInfo("Installed native navigation tab factories=$hooked classes=${candidates.size}")
        }
    }

    private fun looksLikeNavigationTabFactory(method: Method): Boolean {
        if (!View::class.java.isAssignableFrom(method.returnType) || method.parameterTypes.size < 3) return false
        val hasViewGroup = method.parameterTypes.any { ViewGroup::class.java.isAssignableFrom(it) }
        val hasEnumish = method.parameterTypes.any { type ->
            val name = type.name.lowercase(Locale.US)
            type.isEnum || name.contains("enumc") || name.contains("tab") || name.contains("76162") || name.contains("2rs")
        }
        val owner = "${method.declaringClass.name} ${method.name}".lowercase(Locale.US)
        return hasViewGroup && (hasEnumish || owner.contains("instagrammainactivity"))
    }

    private fun findNavigationTabEnumArg(args: Array<Any?>?): Any? {
        args?.forEach { arg ->
            if (arg == null || arg is Context || arg is View || arg is ViewGroup) return@forEach
            val desc = describeNavigationTabEnum(arg)
            if (desc.length <= 320 &&
                (mapNavigationTabEnum(arg) != null || desc.contains("fragment_") ||
                    desc.contains("_tab") || desc.contains("direct_inbox") || desc.contains("clips"))
            ) return arg
        }
        return null
    }

    private fun findViewGroupArg(args: Array<Any?>?): ViewGroup? = args?.firstOrNull { it is ViewGroup } as? ViewGroup

    private fun applyNearNativeNavigationTab(tabView: View) {
        val bar = findNativeNavigationSiblingBar(tabView) ?: return
        nativeNavigationTabBars += bar
        applyNavigationTabBar(bar)
        (findActivity(bar.context) ?: currentActivity)?.let { clickDefaultNavigationTab(it) }
    }

    private fun findNativeNavigationSiblingBar(tabView: View): ViewGroup? {
        var current: View? = tabView
        var best: ViewGroup? = null
        repeat(10) {
            val group = current as? ViewGroup
            if (group != null) {
                val nativeCount = countNativeNavigationTabs(group, 0)
                val tabs = directNavigationTabChildren(group)
                if (nativeCount >= 3 || tabs.count { it.key != null } >= 3) {
                    best = group
                    if (tabs.size in 3..8) return best
                }
            }
            current = current?.parent as? View
        }
        return best
    }

    private fun countNativeNavigationTabs(view: View, depth: Int): Int {
        if (depth > 9) return 0
        var count = if (nativeNavigationTabKeys.containsKey(view)) 1 else 0
        if (view is ViewGroup) {
            for (index in 0 until view.childCount) count += countNativeNavigationTabs(view.getChildAt(index), depth + 1)
        }
        return count
    }

    private fun mapNavigationTabEnum(value: Any?): String? {
        val desc = describeNavigationTabEnum(value)
        if (desc.isBlank() || desc.length > 500 || (desc.contains("activity_task") && desc.contains("window"))) return null
        return when {
            desc.contains("direct") || desc.contains("inbox") || desc.contains("messenger") -> "direct"
            desc.contains("clips") || desc.contains("reels") || desc.contains("reel") -> "reels"
            desc.contains("search") || desc.contains("explore") -> "search"
            desc.contains("profile") || desc.contains("account") -> "profile"
            desc.contains("creation") || desc.contains("share") || desc.contains("gallery_camera") ||
                desc.contains("new_post") || desc.contains("camera") -> "create"
            desc.contains("shopping") || desc.contains("shop") -> "shop"
            desc.contains("feed_switcher") || desc.contains("fragment_feed") || desc.contains("feed_tab") || desc.contains("feed") -> "home"
            else -> null
        }
    }

    private fun describeNavigationTabEnum(value: Any?): String {
        if (value == null) return ""
        val output = StringBuilder(value.toString())
        runCatching { value.javaClass.getMethod("name").invoke(value)?.let { output.append(' ').append(it) } }
        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (field.type != String::class.java || Modifier.isStatic(field.modifiers)) return@forEach
                runCatching {
                    field.isAccessible = true
                    field.get(value)?.let { output.append(' ').append(it) }
                }
            }
            cls = cls.superclass
        }
        return output.toString().lowercase(Locale.US)
    }

    private fun applyMonetThemeToView(view: View) {
        if (!monetActive() || !isInstagramView(view)) return
        recolorMonetView(view)
        if (view is TextView) handleMonetTextSignal(view)
    }

    private fun applyMonetToActivity(activity: Activity) {
        if (!monetActiveActivity(activity)) return
        val palette = monetPalette() ?: return
        activity.window?.let { window ->
            applyMonetSystemBars(window, palette)
            val decor = window.decorView
            decor.post { applyMonetSystemBars(window, palette) }
            decor.postDelayed({ applyMonetSystemBars(window, palette) }, 80L)
            decor.postDelayed({ applyMonetSystemBars(window, palette) }, 250L)
        }
    }

    private fun applyMonetSystemBars(window: Window, palette: MonetPalette) {
        window.statusBarColor = palette.surface
        window.navigationBarColor = palette.surface
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            window.navigationBarDividerColor = palette.outline
        }
        val decor = window.decorView
        var flags = decor.systemUiVisibility
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            flags = if (palette.light) flags or View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR
            else flags and View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR.inv()
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            flags = if (palette.light) flags or View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR
            else flags and View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR.inv()
        }
        decor.systemUiVisibility = flags
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            val mask = android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS or
                android.view.WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS
            val appearance = if (palette.light) mask else 0
            window.insetsController?.setSystemBarsAppearance(appearance, mask)
        }
    }

    private fun handleMonetTextSignal(textView: TextView) {
        val palette = monetPalette() ?: return
        if (!isInstagramView(textView)) return
        if (isPrimaryActionText(textView)) {
            textView.setTextColor(monetReadableOn(palette.primary))
            findPrimaryActionTarget(textView)?.let { tintOrPaintMonetBackground(it, palette.primary, roundedFallback = false, allowMissing = false) }
            return
        }
        val descriptor = monetViewDescriptor(textView)
        if (isSearchPromptText(textView) || isSearchSurfaceRole(textView, descriptor) || isCommentTextSignal(textView) ||
            isNotificationTextSignal(textView) || isDiscoveryTextSignal(textView)
        ) {
            var current: View? = textView
            var depth = 0
            while (current != null && depth++ < 5) {
                val name = monetViewDescriptor(current)
                if (isSearchContainer(current, name) || isSurfaceViewName(name) || isSurfaceContainerName(name) ||
                    isElevatedViewName(name) || isUtilitySurface(current, name, drawableDefaultColor(current.background) ?: palette.surface)
                ) {
                    tintOrPaintMonetBackground(
                        current,
                        if (isElevatedViewName(name) || isSearchContainer(current, name)) palette.surfaceElevated else palette.surfaceContainer,
                        roundedFallback = isRoundedSurfaceName(name),
                        allowMissing = true
                    )
                }
                current = current.parent as? View
            }
        }
    }

    private fun recolorMonetView(view: View) {
        val palette = monetPalette() ?: return
        val name = monetViewDescriptor(view)
        if (isMediaScoped(name) || isMediaViewName(name) || isDirectThreadBodySurface(name) || isTransientDirectOverlay(name)) return
        val backgroundColor = drawableDefaultColor(view.background)
        when {
            view is TextView && isPrimaryActionText(view) -> handleMonetTextSignal(view)
            backgroundColor != null && isInsetSpacerCandidate(view, backgroundColor) ->
                tintOrPaintMonetBackground(view, palette.surfaceContainer, roundedFallback = false, allowMissing = true)
            isButtonLikeView(view, name) || isAccentViewName(name) ->
                tintOrPaintMonetBackground(view, palette.primary, roundedFallback = false, allowMissing = false)
            isElevatedViewName(name) ->
                tintOrPaintMonetBackground(view, palette.surfaceElevated, roundedFallback = isRoundedSurfaceName(name), allowMissing = true)
            isSearchSurfaceRole(view, name) || isSearchContainer(view, name) ->
                tintOrPaintMonetBackground(view, palette.surfaceElevated, roundedFallback = true, allowMissing = true)
            isCommentSurfaceName(name) || isNotificationScreenSurface(view, name) ->
                tintOrPaintMonetBackground(view, palette.surfaceContainer, roundedFallback = isRoundedSurfaceName(name), allowMissing = true)
            backgroundColor != null && isUtilitySurface(view, name, backgroundColor) ->
                tintOrPaintMonetBackground(view, palette.surfaceContainer, roundedFallback = shouldRoundUtilitySurface(view, name), allowMissing = true)
            isSurfaceViewName(name) || isAnonymousNeutralPanel(view, name) ->
                tintOrPaintMonetBackground(view, palette.surfaceContainer, roundedFallback = false, allowMissing = shouldPaintMissingBackground(view, name))
            backgroundColor != null && isSafeNeutralContainer(view, name, backgroundColor) ->
                tintOrPaintMonetBackground(view, palette.surfaceContainer, roundedFallback = false, allowMissing = true)
        }
    }

    private fun recolorMonetAssignedBackground(view: View, drawable: Drawable?) {
        if (drawable == null || !isInstagramView(view)) return
        val color = drawableDefaultColor(drawable)
        val name = monetViewDescriptor(view)
        val actionRole = isPrimaryActionRole(view, name)
        val searchRole = isSearchSurfaceRole(view, name)
        if (color != null && !isNeutralColor(color) && colorForKnownInstagramBlue(color) == null && !actionRole && !searchRole) return
        if (isMediaScoped(name) || isMediaViewName(name) || isDirectThreadBodySurface(name) || isTransientDirectOverlay(name)) return
        if (drawable is ColorDrawable || drawable is GradientDrawable || actionRole || searchRole ||
            isAccentViewName(name) || isElevatedViewName(name) || isSurfaceViewName(name)
        ) {
            recolorMonetView(view)
            if (view.width <= 0 || view.height <= 0) view.post { recolorMonetView(view) }
        }
    }

    private fun tintOrPaintMonetBackground(view: View?, color: Int, roundedFallback: Boolean, allowMissing: Boolean) {
        if (view == null || !isInstagramView(view)) return
        val marker = monetBackgroundMarker(color, roundedFallback)
        if (monetAppliedBackgrounds[view] == marker && view.background != null) return
        val background = view.background
        var changed = false
        runCatching {
            when (background) {
                is ColorDrawable -> {
                    background.mutate()
                    background.color = color
                    view.invalidate()
                    changed = true
                }
                is GradientDrawable -> {
                    background.mutate()
                    background.setColor(color)
                    view.invalidate()
                    changed = true
                }
                null -> {
                    if (allowMissing && view is ViewGroup) {
                        view.background = if (roundedFallback) roundedMonetBackground(view, color) else ColorDrawable(color)
                        changed = true
                    }
                }
                else -> {
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                        view.backgroundTintList = ColorStateList.valueOf(color)
                        changed = true
                    }
                }
            }
        }
        if (changed) monetAppliedBackgrounds[view] = marker
    }

    private fun clearMonetAppliedBackground(view: View) {
        monetAppliedBackgrounds.remove(view)
    }

    private fun monetBackgroundMarker(color: Int, roundedFallback: Boolean): Int {
        return color xor if (roundedFallback) 0x40000000 else 0
    }

    private fun monetBackgroundColorForView(view: View, original: Int): Int? {
        if (!isInstagramView(view)) return null
        val palette = monetPalette() ?: return null
        val knownBlue = colorForKnownInstagramBlue(original) != null
        val name = monetViewDescriptor(view)
        val actionRole = isPrimaryActionRole(view, name)
        val searchRole = isSearchSurfaceRole(view, name)
        if (!knownBlue && !isNeutralColor(original) && !actionRole && !searchRole) return null
        if (isMediaScoped(name) || isMediaViewName(name) || isDirectThreadBodySurface(name) || isTransientDirectOverlay(name)) return null
        if (isReelsScopedAction(view, name) && actionRole) return null
        if (isInsetSpacerCandidate(view, original)) return withOriginalAlpha(palette.surfaceContainer, original)
        if (actionRole || isAccentViewName(name)) return colorForKnownInstagramBlue(original) ?: withOriginalAlpha(palette.primary, original)
        if (searchRole || (isSearchContainer(view, name) && isNeutralColor(original))) return withOriginalAlpha(palette.surfaceElevated, original)
        if (isElevatedViewName(name) && isNeutralColor(original)) return withOriginalAlpha(palette.surfaceElevated, original)
        if (isUtilitySurface(view, name, original)) return withOriginalAlpha(palette.surfaceContainer, original)
        if ((isSurfaceViewName(name) || isAnonymousNeutralPanel(view, name)) && isNeutralColor(original)) return withOriginalAlpha(palette.surfaceContainer, original)
        if (isSafeNeutralContainer(view, name, original)) return withOriginalAlpha(palette.surfaceContainer, original)
        return null
    }

    private fun monetBackgroundTintForView(view: View, original: ColorStateList): ColorStateList? {
        return monetBackgroundColorForView(view, original.defaultColor)?.let { ColorStateList.valueOf(it) }
    }

    private fun monetColorForTypedValue(resources: Resources, value: TypedValue?, original: Int): Int? {
        return value?.resourceId?.takeIf { it != 0 }?.let { monetColorForResource(resources, it, original) }
    }

    private fun monetColorForResource(resources: Resources, resId: Int, original: Int?): Int? {
        if (!isInstagramResource(resources, resId)) return null
        return monetColorForName(resourceEntryName(resources, resId), original)
    }

    private fun monetColorForThemeAttr(attrName: String?, original: Int?): Int? {
        val palette = monetPalette() ?: return null
        val name = normalized(attrName)
        if (isMediaScoped(name)) return null
        return when {
            isAccentAttr(name) -> withOriginalAlpha(palette.primary, original)
            isAccentContainerAttr(name) -> withOriginalAlpha(palette.primaryContainer, original)
            isElevatedAttr(name) -> withOriginalAlpha(palette.surfaceElevated, original)
            isSurfaceContainerAttr(name) -> withOriginalAlpha(palette.surfaceContainer, original)
            isSurfaceAttr(name) -> withOriginalAlpha(palette.surface, original)
            isOutlineAttr(name) -> withOriginalAlpha(palette.outline, original)
            else -> null
        }
    }

    private fun monetColorForName(resourceName: String?, original: Int?): Int? {
        val palette = monetPalette() ?: return null
        val name = normalized(resourceName)
        if (name.isBlank() || isMediaScoped(name)) return null
        return when {
            isAccentName(name) -> withOriginalAlpha(palette.primary, original)
            isAccentContainerName(name) -> withOriginalAlpha(palette.primaryContainer, original)
            isElevatedName(name) -> withOriginalAlpha(palette.surfaceElevated, original)
            isSurfaceContainerName(name) -> withOriginalAlpha(palette.surfaceContainer, original)
            isSurfaceName(name) -> withOriginalAlpha(palette.surface, original)
            isOutlineName(name) -> withOriginalAlpha(palette.outline, original)
            else -> null
        }
    }

    private fun monetColorStateListForName(resourceName: String?, original: ColorStateList?): ColorStateList? {
        val color = monetColorForName(resourceName, original?.defaultColor) ?: return null
        val name = normalized(resourceName)
        if (!isAccentName(name) && !isAccentContainerName(name)) return ColorStateList.valueOf(color)
        val palette = monetPalette() ?: return ColorStateList.valueOf(color)
        val disabled = withAlpha(color, 0x61)
        return ColorStateList(
            arrayOf(
                intArrayOf(android.R.attr.state_enabled, android.R.attr.state_checked),
                intArrayOf(android.R.attr.state_enabled, android.R.attr.state_pressed),
                intArrayOf(-android.R.attr.state_enabled),
                intArrayOf()
            ),
            intArrayOf(palette.primary, palette.primaryStrong, disabled, color)
        )
    }

    private fun monetShapeColorReplacement(color: Int, palette: MonetPalette): Int? {
        if (Color.alpha(color) < 0xc0 || !isNeutralColor(color)) return null
        return withOriginalAlpha(palette.surfaceContainer, color)
    }

    private fun refreshMonetPalette(context: Context?) {
        context ?: return
        monetPalette = MonetPalette.from(context)
        monetAppliedBackgrounds.clear()
    }

    private fun monetPalette(): MonetPalette? {
        monetPalette?.let { return it }
        refreshMonetPalette(currentActivity ?: androidContext)
        return monetPalette
    }

    private fun monetActive(): Boolean = false

    private fun monetActiveActivity(activity: Activity?): Boolean {
        return false
    }

    private fun monetReadableOn(color: Int): Int {
        return if (luminance(color) > 0.62) Color.BLACK else Color.WHITE
    }

    private fun roundedMonetBackground(view: View, color: Int): GradientDrawable {
        return GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            setColor(color)
            cornerRadius = if (view.height in 1..dp(view, 56)) maxOf(dp(view, 8).toFloat(), view.height / 2f) else dp(view, 8).toFloat()
        }
    }

    private fun drawableDefaultColor(drawable: Drawable?): Int? {
        return when (drawable) {
            is ColorDrawable -> drawable.color
            else -> null
        }
    }

    private fun isColorValue(value: TypedValue?): Boolean {
        return value != null && value.type >= TypedValue.TYPE_FIRST_COLOR_INT && value.type <= TypedValue.TYPE_LAST_COLOR_INT
    }

    private fun isInstagramResource(resources: Resources, resId: Int): Boolean {
        if (resId <= 0x00FFFFFF) return false
        return runCatching { isSupportedInstagramPackage(resources.getResourcePackageName(resId)) }.getOrDefault(false)
    }

    private fun isInstagramView(view: View?): Boolean {
        view ?: return false
        return isSupportedInstagramPackage(view.context?.packageName)
    }

    private fun isSupportedInstagramPackage(packageName: String?): Boolean {
        packageName ?: return false
        if (packageName in Constants.INSTAGRAM_PACKAGE_NAMES) return true
        val lower = packageName.lowercase(Locale.US)
        return lower.contains("insta") || lower == "cc.honista.app"
    }

    private fun instagramResourceId(context: Context?, name: String): Int {
        val ctx = context ?: return 0
        val pkg = ctx.packageName
        val key = "$pkg:id:$name"
        instagramResourceIdCache[key]?.let { return it }
        val id = runCatching { ctx.resources.getIdentifier(name, "id", pkg) }.getOrDefault(0)
        instagramResourceIdCache[key] = id
        return id
    }

    private fun hasInstagramResourceId(view: View?, name: String): Boolean {
        view ?: return false
        val id = view.id
        if (id == View.NO_ID || id == 0) return false
        val expected = instagramResourceId(view.context, name)
        return expected != 0 && id == expected
    }

    private fun resourceEntryName(resources: Resources, resId: Int): String? {
        if (resId <= 0x00FFFFFF) return null
        return runCatching { resources.getResourceEntryName(resId) }.getOrNull()
    }

    private fun monetViewDescriptor(view: View?): String {
        view ?: return ""
        val builder = StringBuilder()
        var current: View? = view
        var depth = 0
        while (current != null && depth++ < 4) {
            builder.append(' ').append(resourceEntryName(current).orEmpty())
            builder.append(' ').append(current.javaClass.name)
            builder.append(' ').append(current.contentDescription?.toString().orEmpty())
            if (current is TextView) {
                builder.append(' ').append(current.text?.toString().orEmpty())
                builder.append(' ').append(current.hint?.toString().orEmpty())
            }
            current = current.parent as? View
        }
        return builder.toString().lowercase(Locale.US)
    }

    private fun primaryTextOrHint(textView: TextView): String {
        val text = textView.text?.toString().orEmpty()
        if (text.isNotBlank()) return text
        return textView.hint?.toString().orEmpty()
    }

    private fun findPrimaryActionTarget(textView: TextView): View? {
        var current: View? = textView
        var depth = 0
        while (current != null && depth++ < 4) {
            val name = monetViewDescriptor(current)
            if (current.background != null && (isPrimaryActionRole(current, name) || isPrimaryActionContainer(current, name))) return current
            current = current.parent as? View
        }
        return null
    }

    private fun isPrimaryActionContainer(view: View, name: String): Boolean {
        if (view !is ViewGroup) return false
        return isPrimaryActionName(name) || name.contains("button_container") || name.contains("action_container")
    }

    private fun isPrimaryActionText(view: View?): Boolean {
        val textView = view as? TextView ?: return false
        val text = normalized(primaryTextOrHint(textView)).trim()
        return text == "follow" || text == "follow back" || text == "get app" || text == "install" ||
            text == "create" || text == "connect" || (text == "search" && isSearchActionText(textView)) ||
            text == "confirm" || text == "done" || text == "send" || text == "message"
    }

    private fun isSearchActionText(view: View): Boolean {
        return monetViewDescriptor(view).contains("search")
    }

    private fun normalized(value: String?): String = value?.lowercase(Locale.US).orEmpty()

    private fun isMediaScoped(name: String): Boolean {
        return name.contains("on_media") || name.contains("media_background") ||
            name.contains("photo_overlay") || name.contains("photo_placeholder") ||
            name.contains("camera_") || name.contains("clips_progress") || name.contains("shutter")
    }

    private fun isMediaViewName(name: String): Boolean {
        return name.contains("avatar") ||
            name.contains("profile_pic") ||
            name.contains("profile_photo") ||
            name.contains("profile_picture") ||
            name.contains("user_picture") ||
            name.contains("media_item") ||
            name.contains("media_container") ||
            name.contains("photo_grid") ||
            name.contains("cover_photo") ||
            name.contains("thumbnail") ||
            name.contains("igimageview") ||
            name.contains("drawee") ||
            name.contains("video_container") ||
            name.contains("video_preview") ||
            name.contains("video_player") ||
            name.contains("video_surface") ||
            name.contains("story_tray_item") ||
            name.contains("camera_preview") ||
            name.contains("gallery_grid") ||
            name.contains("gallery_item") ||
            name.contains("feed_media_preview") ||
            name.contains("feed_preview") ||
            name.contains("media_group") ||
            name.contains("row_feed_carousel_media") ||
            name.contains("row_feed_media_image") ||
            name.contains("row_feed_media_video") ||
            name.contains("row_feed_collection_thumbnail_media") ||
            name.contains("row_feed_collection_main_media") ||
            name.contains("textureview") ||
            name.contains("surfaceview") ||
            name.contains("photo_view") ||
            name.contains("video_view") ||
            name.contains("media_view") ||
            name.contains("reel_viewer") ||
            name.contains("clips_viewer") ||
            name.contains("story_viewer")
    }

    private fun isDirectThreadBodySurface(name: String): Boolean {
        return name.contains("direct_thread_content_below_action_bar") ||
            name.contains("thread_toggle_child_fragment_container") ||
            name.contains("thread_view_root") ||
            name.contains("message_thread_container") ||
            name.contains("message_list_refresh_container") ||
            name.contains("message_list") || name.contains("thread_message_list") ||
            name.contains("direct_thread_recycler") || name.contains("direct_thread_view") ||
            name.contains("messagethread") && !name.contains("actionbar") && !name.contains("composer")
    }

    private fun isTransientDirectOverlay(name: String): Boolean {
        return name.contains("message_actions_fragment") ||
            name.contains("composer_overlay_top") ||
            name.contains("drag_and_drop_reaction_overlay") ||
            name.contains("direct_suggested_media_overlay") ||
            name.contains("thread_background_view_overlay") ||
            name.contains("direct_visual_message") || name.contains("view_once") ||
            name.contains("ephemeral") || name.contains("replay") || name.contains("media_overlay")
    }

    private fun isForegroundColorName(name: String): Boolean {
        return name.contains("text") || name.contains("label") || name.contains("icon") ||
            name.contains("glyph") || name.contains("foreground") || name.contains("control") ||
            name.contains("tint") || name.contains("link") || name.contains("action_color") ||
            name.contains("indicator") || name.contains("ripple") || name.contains("graph")
    }

    private fun isGenericBackgroundName(name: String): Boolean {
        if (isMediaScoped(name) || isForegroundColorName(name)) return false
        if (name.contains("action_bar_default_button") || name.contains("igds_action_bar_default_button") ||
            name.contains("default_button_background") || name.contains("dialog_button") ||
            name.contains("secondary_button") || name.contains("transparent_button") ||
            name.contains("borderless_button") || name.contains("icon_button") ||
            name.contains("camera_button") || name.contains("close_button") ||
            name.contains("more_button") || name.contains("like_button") ||
            name.contains("share_button") || name.contains("save_button") ||
            name.contains("comment_button")
        ) return false
        return name.contains("background") || name.contains("_bg") ||
            name.contains("bg_color") || name.contains("bgcolor") || name.contains("surface")
    }

    private fun isAccentAttr(name: String): Boolean {
        if (isForegroundColorName(name)) return false
        return name == "igds_color_primary_button" || name == "igds_color_primary_button_indigo" ||
            name == "igds_color_prism_primary_button_background_indigo" ||
            name == "igds_search_meta_ai_send_button_background_color" ||
            name == "ig_search_meta_ai_send_button_background_color" ||
            name == "igds_color_list_badge" ||
            name.contains("primarybuttonbackground") || name.contains("primary_button_background") ||
            name.contains("primary_pill_button_background") || name.contains("ctabuttonbackground") ||
            name.contains("cta_button_background") || name.contains("confirmbuttonbackground") ||
            name.contains("confirm_button_background") || name.contains("sendbuttonbackground") ||
            name.contains("send_button_background") || name.contains("badgebackground") ||
            name.contains("badge_background")
