    private fun findHostFeatureSection(title: String): HostFeatureSection? {
        return if (title == "Customize Quick Toggle") {
            hostQuickToggleSection()
        } else {
            hostFeatureSections().firstOrNull { it.title == title }
        }
    }

    private fun findHostFeatureSectionContaining(key: String): HostFeatureSection? {
        return (hostFeatureSections() + hostQuickToggleSection())
            .firstOrNull { section -> section.features.any { it.key == key } }
    }

    private fun persistBooleanFeatureUpdate(key: String, value: Boolean) {
        updateLocalFeatureState(key, value)
        androidContext.sendBroadcast(
            Intent(Constants.INSTAGRAM_FEATURE_PREF_UPDATE_ACTION)
                .setPackage(Constants.MODULE_PACKAGE_NAME)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_KEY_EXTRA, key)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_BOOLEAN_EXTRA, value)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_IS_STRING_EXTRA, false)
        )
    }

    private fun persistBooleanFeatureUpdates(values: Map<String, Boolean>) {
        if (values.isEmpty()) return
        val batch = JSONObject()
        values.forEach { (key, value) -> batch.put(key, value) }
        androidContext.sendBroadcast(
            Intent(Constants.INSTAGRAM_FEATURE_PREF_UPDATE_ACTION)
                .setPackage(Constants.MODULE_PACKAGE_NAME)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_BATCH_JSON_EXTRA, batch.toString())
        )
    }

    private fun persistStringFeatureUpdate(key: String, value: String) {
        val persistedValue = if (key == "shareLinkReplacementDomain") cleanShareReplacementDomain(value) else value
        updateLocalFeatureState(key, persistedValue)
        androidContext.sendBroadcast(
            Intent(Constants.INSTAGRAM_FEATURE_PREF_UPDATE_ACTION)
                .setPackage(Constants.MODULE_PACKAGE_NAME)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_KEY_EXTRA, key)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_STRING_EXTRA, persistedValue)
                .putExtra(Constants.INSTAGRAM_FEATURE_PREF_IS_STRING_EXTRA, true)
        )
    }

    private fun showNotesLocationChooser(activity: Activity) {
        val presets = arrayOf<CharSequence>(
            "New York, USA",
            "Bengaluru, India",
            "London, UK",
            "Tokyo, Japan",
            "Manual coordinates"
        )
        AlertDialog.Builder(activity)
            .setTitle("Notes spoof location")
            .setItems(presets) { _, which ->
                when (which) {
                    0 -> persistNotesSpoofLocation("40.7128", "-74.0060", activity)
                    1 -> persistNotesSpoofLocation("12.9716", "77.5946", activity)
                    2 -> persistNotesSpoofLocation("51.5074", "-0.1278", activity)
                    3 -> persistNotesSpoofLocation("35.6762", "139.6503", activity)
                    else -> showManualNotesLocationDialog(activity)
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showManualNotesLocationDialog(activity: Activity) {
        val form = LinearLayout(activity).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(8), dp(20), dp(2))
        }
        val lat = EditText(activity).apply {
            hint = "Latitude"
            setText(state.notesSpoofLatitude)
            setSingleLine(true)
            setTextColor(Color.WHITE)
        }
        val lon = EditText(activity).apply {
            hint = "Longitude"
            setText(state.notesSpoofLongitude)
            setSingleLine(true)
            setTextColor(Color.WHITE)
        }
        form.addView(lat)
        form.addView(lon)
        AlertDialog.Builder(activity)
            .setTitle("Manual coordinates")
            .setView(form)
            .setPositiveButton("Save") { _, _ ->
                val latitude = lat.text?.toString()?.trim().orEmpty()
                val longitude = lon.text?.toString()?.trim().orEmpty()
                val latValue = latitude.toDoubleOrNull()
                val lonValue = longitude.toDoubleOrNull()
                if (latValue != null && lonValue != null && latValue in -90.0..90.0 && lonValue in -180.0..180.0) {
                    persistNotesSpoofLocation(latitude, longitude, activity)
                } else {
                    Toast.makeText(activity, "Invalid coordinates", Toast.LENGTH_SHORT).show()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun persistNotesSpoofLocation(latitude: String, longitude: String, activity: Activity? = null) {
        persistStringFeatureUpdate("notesSpoofLatitude", latitude)
        persistStringFeatureUpdate("notesSpoofLongitude", longitude)
        Toast.makeText(activity ?: androidContext, "Notes spoof location updated", Toast.LENGTH_SHORT).show()
        activity?.let { findHostFeatureSectionContaining("notesSpoofLatitude")?.let { section -> showFeatureSectionDialog(activity, section) } }
    }

    private fun storyRingSizePercent(raw: String): Float {
        raw.trim().removeSuffix("%").toFloatOrNull()?.let { return it.coerceIn(60f, 160f) }
        return when (raw.lowercase(Locale.US)) {
            "small" -> 85f
            "large" -> 115f
            "huge" -> 130f
            else -> 100f
        }
    }

    private fun storyRingSizeValue(percent: Float): String {
        val rounded = ((percent / 5f).roundToInt() * 5).coerceIn(60, 160)
        return if (rounded == 100) "default" else rounded.toString()
    }

    private fun cleanShareReplacementDomain(raw: String): String {
        var value = raw.trim().lowercase(Locale.US)
        if (value.isEmpty()) return "kkinstagram.com"
        value = value.removePrefix("https://").removePrefix("http://")
        val slash = value.indexOf('/')
        if (slash >= 0) value = value.substring(0, slash)
        value = value.replace(Regex("[^a-z0-9.-]"), "")
        return if (value.isNotEmpty() && value.contains(".")) value else "kkinstagram.com"
    }

    private fun updateLocalFeatureState(key: String, value: Any) {
        runCatching {
            val snapshot = JSONObject()
            val stateClass = InstagramFeatureState::class.java
            InstagramFeatureState.booleanFeatureKeys.forEach { featureKey ->
                snapshot.put(featureKey, readFeatureField(stateClass, state, featureKey) as? Boolean ?: false)
            }
            InstagramFeatureState.stringFeatureKeys.forEach { featureKey ->
                snapshot.put(featureKey, readFeatureField(stateClass, state, featureKey) as? String ?: "")
            }
            snapshot.put(key, value)
            val previous = state
            val next = InstagramFeatureState.fromJson(snapshot.toString(), "local-settings:$key")
            InstagramFeatureStateStore.update(next)
            InstagramCustomEmojiFontHooks.syncAfterStateUpdate(androidContext, previous, next)
            refreshActiveHooks("local-settings:$key")
        }.onFailure { throwable ->
            logError("Failed to update local feature state for $key", throwable)
        }
    }

    private fun readFeatureField(stateClass: Class<InstagramFeatureState>, value: InstagramFeatureState, key: String): Any? {
        return runCatching {
            stateClass.getDeclaredField(key).apply { isAccessible = true }.get(value)
        }.getOrNull()
    }

    private fun isGhostQuickToggleActive(value: InstagramFeatureState): Boolean {
        return (value.quickToggleSeen && value.isGhostSeen) ||
            (value.quickToggleTyping && value.isGhostTyping) ||
            (value.quickToggleScreenshot && value.isGhostScreenshot) ||
            (value.quickToggleViewOnce && value.isGhostViewOnce) ||
            (value.quickToggleStory && value.isGhostStory) ||
            (value.quickToggleLive && value.isGhostLive) ||
            (value.quickToggleEphemeral && value.keepEphemeralMessages) ||
            (value.quickToggleUnsend && value.keepUnsentMessages) ||
            (value.quickToggleReplays && value.enableUnlimitedReplays) ||
            (value.quickTogglePermanentView && value.permanentViewMode) ||
            (value.quickToggleAllowScreenshots && value.allowScreenshots)
    }

    private fun openPurrfectManager(context: Context) {
        runCatching {
            val intent = context.packageManager.getLaunchIntentForPackage(Constants.MODULE_PACKAGE_NAME)
                ?: Intent().setPackage(Constants.MODULE_PACKAGE_NAME)
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
            context.startActivity(intent)
        }.onFailure {
            Toast.makeText(context, "Unable to open Purrfect", Toast.LENGTH_SHORT).show()
        }
    }

    private fun openInstagramDevOptions(context: Context) {
        if (!state.isDevEnabled) {
            persistBooleanFeatureUpdate("isDevEnabled", true)
        }
        installActivityHooks()
        ensureDevOptionsStableHooks("manual-open")
        val starter = (context as? Activity)?.takeUnless { it.isFinishing }
            ?: currentActivity?.takeUnless { it.isFinishing }
            ?: context
        val packageName = androidContext.packageName
        var opened = tryOpenDevOptionsFragmentDirectly(starter, "manual")
        val uris = listOf(
            "instagram://settings_devoptions",
            "instagram://developer_options",
            "instagram://settings/developer_options",
            "instagram://internal_settings",
            "instagram://settings/internal",
            "instagram://debug",
            "instagram://debug_settings",
            "instagram://settings/debug",
            "instagram://settings/account/dev_options",
            "instagram://settings/dev_options"
        )
        if (!opened) {
            for (uri in uris) {
                val intent = Intent(Intent.ACTION_VIEW, Uri.parse(uri)).setPackage(packageName)
                if (starter !is Activity) {
                    intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                val result = runCatching { starter.startActivity(intent) }
                if (result.isSuccess) {
                    opened = true
                    logInfo("Opened Instagram Dev Options with URI: $uri")
                    (starter as? Activity ?: currentActivity)?.let { activity ->
                        val now = SystemClock.uptimeMillis()
                        pendingDevOptionsIntentUri = uri
                        pendingDevOptionsOpenUntilMs = now + 10_000L
                        scheduleDevOptionsOpenRetries(activity, "post-uri", uri)
                    }
                    break
                }
            }
        }

        if (!opened) {
            logInfo("Deep link attempts failed; trying direct activity launch")
            opened = tryOpenDevOptionsActivityDirectly(starter, packageName)
        }

        if (!opened) {
            logInfo("Failed to open Instagram Dev Options with any known URI")
            Toast.makeText(context, "Unable to open Instagram developer options. Try enabling Developer Mode first.", Toast.LENGTH_SHORT).show()
        }
    }

    private fun tryOpenDevOptionsActivityDirectly(starter: Any, packageName: String): Boolean {
        val ctx = starter as? Context ?: return false
        val isActivity = starter is Activity

        val candidateClasses = listOf(
            "com.instagram.debug.devoptions.DeveloperOptionsActivity",
            "com.instagram.debug.devoptions.DevOptionsActivity",
            "com.instagram.debug.quickexperiment.QuickExperimentSettingsActivity",
            "com.instagram.debug.devoptions.DeveloperOptionsFragment",
            "com.instagram.debug.devoptions.internal.DeveloperOptionsActivity"
        )

        candidateClasses.forEach { className ->
            val result = runCatching {
                val cls = Class.forName(className, false, appClassLoader)
                val intent = Intent(ctx, cls)
                if (!isActivity) {
                    intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                ctx.startActivity(intent)
                logInfo("Opened Instagram Dev Options via direct activity: $className")
                true
            }
            if (result.getOrDefault(false)) return true
        }

        return false
    }

    private fun maybeHandleDevOptionsIntent(activity: Activity, intent: Intent?, source: String) {
        if (!state.isDevEnabled) return
        val uri = extractInstagramDevOptionsUri(intent) ?: return
        ensureDevOptionsStableHooks("intent:$source")
        val now = SystemClock.uptimeMillis()
        if (uri == lastDevOptionsIntentUri && now - lastDevOptionsIntentAtMs < 2_500L) return
        lastDevOptionsIntentUri = uri
        lastDevOptionsIntentAtMs = now
        pendingDevOptionsIntentUri = uri
        pendingDevOptionsOpenUntilMs = now + 10_000L
        logInfo("DevOptions intent detected source=$source activity=${activity.javaClass.name} uri=$uri")
        scheduleDevOptionsOpenRetries(activity, "intent:$source", uri)
    }

    private fun maybeOpenPendingDevOptions(activity: Activity, source: String) {
        val uri = pendingDevOptionsIntentUri ?: return
        val now = SystemClock.uptimeMillis()
        if (now > pendingDevOptionsOpenUntilMs) {
            pendingDevOptionsIntentUri = null
            pendingDevOptionsOpenUntilMs = 0L
            return
        }
        if (!isActivityUsable(activity) || isDeveloperOptionsSurfaceVisible()) return
        scheduleDevOptionsOpenRetries(activity, "pending:$source", uri)
    }

    private fun scheduleDevOptionsOpenRetries(activity: Activity, source: String, uri: String) {
        val delays = longArrayOf(0L, 120L, 350L, 800L, 1_600L, 3_000L, 5_000L)
        delays.forEach { delay ->
            mainHandler.postDelayed({
                if (!state.isDevEnabled) return@postDelayed
                if (pendingDevOptionsIntentUri != uri) return@postDelayed
                val now = SystemClock.uptimeMillis()
                if (now > pendingDevOptionsOpenUntilMs) {
                    pendingDevOptionsIntentUri = null
                    pendingDevOptionsOpenUntilMs = 0L
                    return@postDelayed
                }
                if (!isActivityUsable(activity)) return@postDelayed
                if (isDeveloperOptionsSurfaceVisible()) {
                    pendingDevOptionsIntentUri = null
                    pendingDevOptionsOpenUntilMs = 0L
                    return@postDelayed
                }
                if (tryOpenDevOptionsFragmentDirectly(activity, "$source+$delay")) {
                    pendingDevOptionsIntentUri = null
                    pendingDevOptionsOpenUntilMs = 0L
                    logInfo("DevOptions retry opened source=$source delayMs=$delay uri=$uri")
                } else if (delay == delays.last()) {
                    logInfo("DevOptions retry exhausted source=$source uri=$uri")
                }
            }, delay)
        }
    }

    private fun ensureRuntimeHooksForCurrentState(reason: String) {
        val current = state
        if (shouldInstallActivityHooks(current)) installActivityHooks()
        if (shouldInstallViewHooks(current)) installViewHooks()
        if (shouldInstallScrollBusyHooks(current)) installFlickPerfRecyclerHooks()
        if (current.isDevEnabled) ensureDevOptionsStableHooks(reason)
        if (current.keepUnsentMessages) installKeepUnsentRecyclerViewHooks()
        if (current.enableStoryTrayLongPressActions) installMenuInjectionHooks()
        if (current.enableDmContextMenuOptions || current.keepUnsentMessages) installDirectMessageContextMenuHook()
        if (current.isAdBlockEnabled) installSponsoredRecyclerHook()
        if (current.keepUnsentMessages || hasAnyTextViewWork(current)) installTextHooks()
        if (current.enableCustomDateFormat && current.customDateFormatComments) installStaticLayoutDateFormatHooks()
        if (shouldInstallIntentAndClipboardHooks(current)) installIntentAndClipboardHooks()
        if (hasValidNotesLocationSpoof(current)) installInstagramMapLocationSpoofHooks()
        if (current.enableConfirmRefresh) installConfirmRefreshHooks()
        if (shouldInstallPreferenceHooks(current)) installPreferenceHooks()
        if (storyRingScaleFactor(current) != 1f) installResourceHooks()
        if (current.disableVideoAutoPlay) installManualVideoPlayOverlayHooks()
        if (shouldInstallImageUrlHooks(current)) installInstagramImageHooks()
        if (shouldInstallGenericPostMediaUrlCapture(current)) installPostMediaUrlCaptureHooks()
        if (current.enableHighQualityStoryUpload) {
            installHighQualityUploadHooks()
            installHeicUploadFallbackHooks()
        }
        if (current.feedVideosStartWithSound || current.storiesStartWithSound) installStartVideosWithSoundHooks()
        if (current.enableStoryDownload || current.enablePostDownload || current.enableReelDownload || current.enableReelThumbnailDownload) {
            initStoryVideoVersionReflection()
        }
        if (hasAnyDownloadFeature(current) || current.enableDmContextMenuOptions) initMediaDownloadReflection()
        if (current.customEmojiFontEnabled) InstagramCustomEmojiFontHooks.install(androidContext, appClassLoader)
        if (current.enableShareSheetEmojiShortcuts) InstagramShareSheetEmojiShortcutHooks.install(appClassLoader)
        if (current.enableActivityHistory) InstagramActivityHistoryHooks.install(androidContext, appClassLoader)
        if (shouldInstallNetworkHooks(current)) {
            installOkHttpHooks()
            installTigonHooks()
        }
        if (shouldInstallDexKitHooks(current)) installDexKitHooks()
        if (current.enableHideChats) scheduleDirectChatDatabaseSnapshot(reason, 1_000L)
    }

    private fun extractInstagramDevOptionsUri(intent: Intent?): String? {
        if (intent == null) return null
        val direct = listOfNotNull(intent.dataString, intent.data?.toString())
            .firstOrNull(::isInstagramDevOptionsUri)
        if (direct != null) return direct
        val seen = Collections.newSetFromMap(IdentityHashMap<Any, Boolean>())
        fun search(value: Any?, depth: Int): String? {
            if (value == null || depth > 3 || !seen.add(value)) return null
            when (value) {
                is String -> if (isInstagramDevOptionsUri(value)) return value
                is Uri -> value.toString().takeIf(::isInstagramDevOptionsUri)?.let { return it }
                is Intent -> extractInstagramDevOptionsUri(value)?.let { return it }
                is Bundle -> runCatching {
                    value.keySet().forEach { key ->
                        search(value.get(key), depth + 1)?.let { return it }
                    }
                }
            }
            return null
        }
        return runCatching { search(intent.extras, 0) }.getOrNull()
    }

    private fun isInstagramDevOptionsUri(uri: String): Boolean {
        val clean = uri.lowercase(Locale.US).substringBefore('?').substringBefore('#').trimEnd('/')
        return clean == "instagram://settings_devoptions" ||
            clean == "instagram://developer_options" ||
            clean == "instagram://settings/developer_options" ||
            clean == "instagram://settings/account/dev_options" ||
            clean == "instagram://settings/dev_options" ||
            clean == "instagram://internal_settings" ||
            clean == "instagram://settings/internal" ||
            clean == "instagram://debug" ||
            clean == "instagram://debug_settings" ||
            clean == "instagram://settings/debug"
    }

    private fun tryOpenDevOptionsFragmentDirectly(starter: Any, source: String): Boolean {
        if (!state.isDevEnabled) return false
        val hostActivity = candidateDevOptionsHostActivities(starter)
            .firstOrNull { isActivityUsable(it) }
            ?: run {
                logInfo("DevOptions direct fragment skipped; no usable Activity source=$source")
                return false
            }
        val session = lastInstagramUserSession
            ?: findUserSession(lastDirectFileBroadcaster)
            ?: findUserSession(lastDirectMediaCoordinator)
            ?: findUserSession(hostActivity)
            ?: run {
                logInfo("DevOptions direct fragment skipped; Instagram UserSession unavailable source=$source activity=${hostActivity.javaClass.name}")
                return false
            }
        val fragmentCandidates = listOfNotNull(
            InstagramDexKitCache.loadString("DevOptionsFragment"),
            "com.instagram.debug.devoptions.DeveloperOptionsFragment"
        )
            .plus(discoverDevOptionsFragmentCandidates())
            .plus(
                listOf(
                    "X.10S5",
                    "X.C10S5",
                    "X.10T4",
                    "X.C10T4",
                    "com.instagram.debug.devoptions.IgVoltronDevOptionsFragment"
                )
            )
            .distinct()
        logInfo(
            "DevOptions direct fragment fallback source=$source activity=${hostActivity.javaClass.name} " +
                "session=${session.javaClass.name} candidates=${fragmentCandidates.joinToString()}"
        )
        fragmentCandidates.forEach { fragmentClassName ->
            if (tryOpenInstagramFragmentWithNavigator(hostActivity, session, fragmentClassName, source)) return true
        }
        return false
    }

    private fun tryOpenInstagramFragmentWithNavigator(
        activity: Activity,
        session: Any,
        fragmentClassName: String,
        source: String
    ): Boolean {
        return runCatching {
            val fragmentClass = loadDevOptionsFragmentClass(fragmentClassName)
            val fragmentCtor = fragmentClass.getDeclaredConstructor().apply { isAccessible = true }
            val fragment = fragmentCtor.newInstance()
            applyDevOptionsFragmentSessionArguments(fragment, session, source)
            val navigatorClass = loadDevOptionsNavigatorClass(fragmentClass)
            val navigatorCtor = findCompatibleConstructor(navigatorClass, listOf(activity, session))
                ?: error("no ${navigatorClass.name}(Activity, Session) constructor for ${activity.javaClass.name}/${session.javaClass.name}")
            val navigator = navigatorCtor.newInstance(activity, session)
            val pushMethod = findCompatibleMethod(navigator.javaClass, "A0F", listOf(fragment))
                ?: error("no navigator A0F method for ${fragment.javaClass.name}")
            val commitMethod = findCompatibleMethod(navigator.javaClass, "A05", emptyList())
                ?: error("no navigator A05 commit method")
            pushMethod.invoke(navigator, fragment)
            commitMethod.invoke(navigator)
            logInfo("DevOptions direct fragment opened $fragmentClassName via ${navigator.javaClass.name} source=$source")
            true
        }.onFailure {
            if (it is ClassNotFoundException) {
                return@onFailure
            } else {
                logInfo("DevOptions direct fragment candidate failed $fragmentClassName source=$source: ${it.javaClass.simpleName}: ${it.message}")
            }
        }.getOrDefault(false)
    }

    private fun loadDevOptionsNavigatorClass(fragmentClass: Class<*>): Class<*> {
        val cachedName = InstagramDexKitCache.loadString("DevOptionsNavigatorClass")
        val names = listOfNotNull(
            cachedName,
            "X.3Uo",
            "p000X.C3Uo",
            "X.C3Uo",
            "X.05sX",
            "p000X.C05sX",
            "X.C05sX"
        ).distinct()
        val loaders = listOfNotNull(
            fragmentClass.classLoader,
            devOptionsAssetClassLoader,
            appClassLoader,
            Thread.currentThread().contextClassLoader
        ).distinct()
        var firstFailure: Throwable? = null
        loaders.forEach { loader ->
            names.forEach { name ->
                val loaded = runCatching { Class.forName(name, false, loader) }
                    .onFailure { firstFailure = firstFailure ?: it }
                    .getOrNull()
                    ?: return@forEach
                InstagramDexKitCache.saveString("DevOptionsNavigatorClass", loaded.name)
                return loaded
            }
        }
        throw ClassNotFoundException(
            "DevOptions navigator ${names.joinToString()} not found in fragment/app loaders",
            firstFailure
        )
    }

    private fun applyDevOptionsFragmentSessionArguments(fragment: Any, session: Any, source: String) {
        val bundle = Bundle()
        val seeded = seedInstagramSessionBundle(bundle, session)
        if (!seeded) {
            logInfo(
                "DevOptions fragment session args helper unavailable source=$source " +
                    "fragment=${fragment.javaClass.name} session=${session.javaClass.name}"
            )
        }
        runCatching {
            val setArguments = findCompatibleMethod(fragment.javaClass, "setArguments", listOf(bundle))
                ?: fragment.javaClass.methods.firstOrNull { method ->
                    method.name == "setArguments" &&
                        method.parameterTypes.size == 1 &&
                        Bundle::class.java.isAssignableFrom(method.parameterTypes[0])
                }
                ?: error("setArguments(Bundle) unavailable")
            setArguments.invoke(fragment, bundle)
            logInfo(
                "DevOptions fragment session args applied source=$source fragment=${fragment.javaClass.name} " +
                    "session=${session.javaClass.name} seeded=$seeded"
            )
        }.onFailure {
            logInfo(
                "DevOptions fragment session args failed source=$source fragment=${fragment.javaClass.name}: " +
                    "${it.javaClass.simpleName}: ${it.message}"
            )
        }
    }

    private fun seedInstagramSessionBundle(bundle: Bundle, session: Any): Boolean {
        val helperCandidates = listOf("X.02Pz", "p000X.C02Pz")
        helperCandidates.forEach { className ->
            runCatching {
                val helperClass = Class.forName(className, false, appClassLoader)
                val method = helperClass.declaredMethods.firstOrNull { method ->
                    method.name == "A03" &&
                        Modifier.isStatic(method.modifiers) &&
                        method.parameterTypes.size == 2 &&
                        Bundle::class.java.isAssignableFrom(method.parameterTypes[0]) &&
                        method.parameterTypes[1].isAssignableFrom(session.javaClass)
                } ?: return@runCatching false
                method.isAccessible = true
                method.invoke(null, bundle, session)
                logInfo("DevOptions seeded session Bundle with ${helperClass.name}.${method.name}")
                true
            }.getOrDefault(false).let { seeded ->
                if (seeded) return true
            }
        }
        return false
    }

    private fun loadDevOptionsFragmentClass(className: String): Class<*> {
        return runCatching { Class.forName(className, true, appClassLoader) }
            .getOrElse {
                val loader = getDevOptionsAssetClassLoader()
                    ?: throw ClassNotFoundException("$className (devoptions asset loader unavailable)", it)
                Class.forName(className, true, loader)
            }
    }

    private fun getDevOptionsAssetClassLoader(): ClassLoader? {
        devOptionsAssetClassLoader?.let { return it }
        return synchronized(this) {
            devOptionsAssetClassLoader?.let { return@synchronized it }
            runCatching {
                val splitApk = findDevOptionsSplitApk() ?: error("devoptions asset dex not found")
                val dexFile = extractDevOptionsAssetDex(splitApk)
                devOptionsAssetDexFile = dexFile
                val optimizedDir = File(androidContext.codeCacheDir, "purrfect_devoptions_opt").apply { mkdirs() }
                DexClassLoader(dexFile.absolutePath, optimizedDir.absolutePath, null, appClassLoader).also {
                    devOptionsAssetClassLoader = it
                    logInfo("DevOptions asset DexClassLoader ready apk=${splitApk.name} dex=${dexFile.name}")
                }
            }.onFailure {
                logInfo("DevOptions asset DexClassLoader failed: ${it.javaClass.simpleName}: ${it.message}")
            }.getOrNull()
        }
    }

    private fun discoverDevOptionsFragmentCandidates(): List<String> {
        devOptionsAssetFragmentClassCandidates?.let { return it }
        return synchronized(this) {
            devOptionsAssetFragmentClassCandidates?.let { return@synchronized it }
            val loader = getDevOptionsAssetClassLoader()
            val dexFile = devOptionsAssetDexFile
            if (loader == null || dexFile == null) {
                devOptionsAssetFragmentClassCandidates = emptyList()
                return@synchronized emptyList()
            }
            val discovered = readDexClassNames(dexFile)
                .asSequence()
                .filter { className ->
                    className.startsWith("X.") ||
                        className.startsWith("p000X.") ||
                        className.startsWith("com.instagram.debug.")
                }
                .filter { isDevOptionsFragmentCandidateClass(it, loader) }
                .distinct()
                .toList()
            devOptionsAssetFragmentClassCandidates = discovered
            if (discovered.isNotEmpty()) {
                logInfo("DevOptions discovered fragment candidate(s) from asset dex: ${discovered.joinToString()}")
            } else {
                logInfo("DevOptions asset dex discovery found no fragment candidates")
            }
            discovered
        }
    }

    private fun isDevOptionsFragmentCandidateClass(className: String, loader: ClassLoader): Boolean {
        return runCatching {
            val clazz = Class.forName(className, false, loader)
            val originalName = readStaticStringField(clazz, "__redex_internal_original_name")
            originalName == "DeveloperOptionsFragment" || originalName == "IgVoltronDevOptionsFragment"
        }.getOrDefault(false)
    }

    private fun readStaticStringField(clazz: Class<*>, fieldName: String): String? {
        var current: Class<*>? = clazz
        while (current != null) {
            runCatching { current.getDeclaredField(fieldName) }.getOrNull()?.let { field ->
                if (Modifier.isStatic(field.modifiers) && field.type == String::class.java) {
                    return runCatching {
                        field.isAccessible = true
                        field.get(null) as? String
                    }.getOrNull()
                }
            }
            current = current.superclass
        }
        return null
    }

    private fun readDexClassNames(dexFile: File): List<String> {
        return runCatching {
            val bytes = dexFile.readBytes()
            if (bytes.size < 112 || String(bytes, 0, 3, Charsets.US_ASCII) != "dex") return@runCatching emptyList()
            val stringIdsSize = readDexInt(bytes, 56)
            val stringIdsOff = readDexInt(bytes, 60)
            val typeIdsSize = readDexInt(bytes, 64)
            val typeIdsOff = readDexInt(bytes, 68)
            if (!isDexRangeValid(bytes, stringIdsOff, stringIdsSize, 4) ||
                !isDexRangeValid(bytes, typeIdsOff, typeIdsSize, 4)
            ) {
                return@runCatching emptyList()
            }

            val strings = arrayOfNulls<String>(stringIdsSize)
            for (index in 0 until stringIdsSize) {
                val stringDataOff = readDexInt(bytes, stringIdsOff + index * 4)
                strings[index] = readDexString(bytes, stringDataOff)
            }

            val classNames = ArrayList<String>(typeIdsSize)
            for (index in 0 until typeIdsSize) {
                val stringIndex = readDexInt(bytes, typeIdsOff + index * 4)
                val descriptor = strings.getOrNull(stringIndex) ?: continue
                dexDescriptorToClassName(descriptor)?.let { classNames.add(it) }
            }
            classNames.distinct()
        }.onFailure {
            logInfo("DevOptions asset dex class scan failed: ${it.javaClass.simpleName}: ${it.message}")
        }.getOrDefault(emptyList())
    }

    private fun readDexInt(bytes: ByteArray, offset: Int): Int {
        if (offset < 0 || offset + 4 > bytes.size) return 0
        return (bytes[offset].toInt() and 0xFF) or
            ((bytes[offset + 1].toInt() and 0xFF) shl 8) or
            ((bytes[offset + 2].toInt() and 0xFF) shl 16) or
            ((bytes[offset + 3].toInt() and 0xFF) shl 24)
    }

    private fun isDexRangeValid(bytes: ByteArray, offset: Int, count: Int, itemSize: Int): Boolean {
        if (offset < 0 || count < 0 || itemSize <= 0) return false
        val size = count.toLong() * itemSize.toLong()
        return offset.toLong() + size <= bytes.size.toLong()
    }

    private fun readDexString(bytes: ByteArray, offset: Int): String? {
        if (offset < 0 || offset >= bytes.size) return null
        var index = offset
        var lebBytes = 0
        var value: Int
        do {
            if (index >= bytes.size || lebBytes++ >= 5) return null
            value = bytes[index++].toInt() and 0xFF
        } while ((value and 0x80) != 0)
        val start = index
        while (index < bytes.size && bytes[index].toInt() != 0) index++
        if (index <= start || index > bytes.size) return null
        return String(bytes, start, index - start, Charsets.UTF_8)
    }

    private fun dexDescriptorToClassName(descriptor: String): String? {
        if (!descriptor.startsWith("L") || !descriptor.endsWith(";")) return null
        return descriptor.substring(1, descriptor.length - 1).replace('/', '.')
    }

    private fun findDevOptionsSplitApk(): File? {
        val candidates = buildList {
            androidContext.applicationInfo.splitSourceDirs?.forEach { add(File(it)) }
            add(File(androidContext.applicationInfo.sourceDir))
        }.filter { it.exists() && it.isFile }
        return candidates.firstOrNull { file ->
            file.name.contains("devoptions", ignoreCase = true) &&
                findDevOptionsAssetDexEntry(file) != null
        } ?: candidates.firstOrNull { findDevOptionsAssetDexEntry(it) != null }
    }

    private fun findDevOptionsAssetDexEntry(file: File): String? {
        return runCatching {
            ZipFile(file).use { zip ->
                zip.getEntry("assets/devoptions/classes.dex")?.let { return@use it.name }
                val entries = zip.entries()
                while (entries.hasMoreElements()) {
                    val entry = entries.nextElement()
                    if (entry.isDirectory) continue
                    val lowerName = entry.name.lowercase(Locale.US)
                    if (!lowerName.startsWith("assets/") || !lowerName.endsWith(".dex")) continue
                    if (
                        lowerName.contains("devoptions") ||
                        lowerName.contains("dev_options") ||
                        lowerName.contains("developer_options")
                    ) {
                        return@use entry.name
                    }
                }
                null
            }
        }.getOrNull()
    }

    private fun extractDevOptionsAssetDex(splitApk: File): File {
        val outputDir = File(androidContext.codeCacheDir, "purrfect_devoptions").apply { mkdirs() }
        val entryName = findDevOptionsAssetDexEntry(splitApk) ?: error("devoptions asset dex missing")
        val safeEntryName = entryName.replace(Regex("[^A-Za-z0-9._-]"), "_")
        val safeName = "${splitApk.nameWithoutExtension}_${safeEntryName}_${splitApk.length()}_${splitApk.lastModified()}.dex"
        val output = File(outputDir, safeName)
        if (output.exists() && output.length() > 0L) {
            output.setWritable(false, false)
            output.setReadOnly()
            return output
        }
        ZipFile(splitApk).use { zip ->
            val entry = zip.getEntry(entryName) ?: error("$entryName missing")
            zip.getInputStream(entry).use { input ->
                output.outputStream().use { out -> input.copyTo(out) }
            }
        }
        output.setWritable(false, false)
        output.setReadOnly()
        return output
    }

    private fun candidateDevOptionsHostActivities(starter: Any): List<Activity> {
        val fromStarter = when (starter) {
            is Activity -> starter
            is Context -> findActivity(starter)
            else -> null
        }
        return listOfNotNull(fromStarter, currentActivity, lastInstagramFragmentActivity?.get())
            .distinctBy { System.identityHashCode(it) }
    }

    private fun rememberInstagramFragmentActivity(activity: Activity) {
        if (isInstagramFragmentActivity(activity)) {
            lastInstagramFragmentActivity = WeakReference(activity)
        }
    }

    private fun isInstagramFragmentActivity(activity: Activity?): Boolean {
        activity ?: return false
        return runCatching {
            val loader = activity.javaClass.classLoader ?: appClassLoader
            val clazz = fragmentActivityClass ?: Class.forName("androidx.fragment.app.FragmentActivity", false, loader)
                .also { fragmentActivityClass = it }
            clazz.isInstance(activity)
        }.getOrDefault(false)
    }

    private fun isActivityUsable(activity: Activity): Boolean {
        if (activity.isFinishing) return false
        return Build.VERSION.SDK_INT < Build.VERSION_CODES.JELLY_BEAN_MR1 || !activity.isDestroyed
    }

    private fun findCompatibleConstructor(type: Class<*>, args: List<Any>): Constructor<*>? {
        return type.declaredConstructors.firstOrNull { constructor ->
            val params = constructor.parameterTypes
            params.size == args.size && params.indices.all { index -> params[index].isAssignableFrom(args[index].javaClass) }
        }?.apply { isAccessible = true }
    }

    private fun findCompatibleMethod(type: Class<*>, name: String, args: List<Any>): Method? {
        var current: Class<*>? = type
        while (current != null && current != Any::class.java) {
            current.declaredMethods.firstOrNull { method ->
                val params = method.parameterTypes
                method.name == name &&
                    params.size == args.size &&
                    params.indices.all { index -> params[index].isAssignableFrom(args[index].javaClass) }
            }?.let { method ->
                method.isAccessible = true
                return method
            }
            current = current.superclass
        }
        return null
    }

    private fun isDeveloperOptionsSurfaceVisible(): Boolean {
        val root = currentActivity?.window?.decorView
            ?: lastInstagramFragmentActivity?.get()?.window?.decorView
            ?: return false
        return findView(root) { view ->
            val text = when (view) {
                is TextView -> view.text?.toString()
                else -> view.contentDescription?.toString()
            }?.lowercase(Locale.US).orEmpty()
            text.contains("developer options") ||
                text.contains("search developer options") ||
                text.contains("quick experiment")
        } != null
    }

