    private fun openUrl(context: Context, url: String) {
        runCatching {
            context.startActivity(
                Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
            )
        }.onFailure { throwable ->
            logError("Failed to open URL $url", throwable)
        }
    }

    private fun restartInstagram(context: Context) {
        val launchIntent = context.packageManager.getLaunchIntentForPackage(context.packageName)
        if (launchIntent != null) {
            clearAppCache(context)
            launchIntent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_NEW_TASK)
            context.startActivity(launchIntent)
        } else {
            Toast.makeText(context, "Could not find the app to restart.", Toast.LENGTH_SHORT).show()
        }
        android.os.Process.killProcess(android.os.Process.myPid())
    }

    private fun clearAppCache(context: Context) {
        runCatching {
            deleteRecursive(context.cacheDir)
            logInfo("Cache cleared for ${context.packageName}")
        }.onFailure { throwable ->
            logError("Failed to clear app cache for ${context.packageName}", throwable)
        }
    }

    private fun deleteRecursive(file: File?) {
        if (file == null || !file.exists()) return
        if (file.isDirectory) file.listFiles()?.forEach(::deleteRecursive)
        if (file != androidContext.cacheDir) file.delete()
    }

    private fun vibrate(context: Context) {
        val vibrator = context.getSystemService(Context.VIBRATOR_SERVICE) as? Vibrator ?: return
        runCatching {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                vibrator.vibrate(VibrationEffect.createOneShot(35L, VibrationEffect.DEFAULT_AMPLITUDE))
            } else {
                @Suppress("DEPRECATION")
                vibrator.vibrate(35L)
            }
        }
    }

    private fun findActivity(context: Context?): Activity? {
        var current = context
        while (current is ContextWrapper) {
            if (current is Activity) return current
            current = current.baseContext
        }
        return current as? Activity
    }

    private fun installQuickToggle(activity: Activity) {
        if (!hasAnyQuickToggle() || quickToggleButtons.contains(activity)) return
        val root = activity.window?.decorView as? ViewGroup ?: return
        quickToggleButtons += activity
        val button = TextView(activity).apply {
            text = "PI"
            setTextColor(Color.WHITE)
            textSize = 12f
            gravity = Gravity.CENTER
            typeface = Typeface.DEFAULT_BOLD
            background = GradientDrawable().apply {
                shape = GradientDrawable.OVAL
                setColor(Color.rgb(225, 48, 108))
                setStroke(2, Color.WHITE)
            }
            setOnClickListener {
                toggleQuickFeatures()
                Toast.makeText(activity, "PurrfectInsta quick toggled", Toast.LENGTH_SHORT).show()
            }
        }
        val params = FrameLayout.LayoutParams(dp(42), dp(42), Gravity.END or Gravity.CENTER_VERTICAL).apply {
            marginEnd = dp(8)
        }
        runCatching { root.addView(button, params) }
    }

    private fun toggleQuickFeatures() {
        val old = state
        val next = old.copy(
            isGhostSeen = if (old.quickToggleSeen) !old.isGhostSeen else old.isGhostSeen,
            isGhostTyping = if (old.quickToggleTyping) !old.isGhostTyping else old.isGhostTyping,
            isGhostScreenshot = if (old.quickToggleScreenshot) !old.isGhostScreenshot else old.isGhostScreenshot,
            isGhostViewOnce = if (old.quickToggleViewOnce) !old.isGhostViewOnce else old.isGhostViewOnce,
            isGhostStory = if (old.quickToggleStory) !old.isGhostStory else old.isGhostStory,
            isGhostLive = if (old.quickToggleLive) !old.isGhostLive else old.isGhostLive,
            keepEphemeralMessages = if (old.quickToggleEphemeral) !old.keepEphemeralMessages else old.keepEphemeralMessages,
            keepUnsentMessages = if (old.quickToggleUnsend) !old.keepUnsentMessages else old.keepUnsentMessages,
            enableUnlimitedReplays = if (old.quickToggleReplays) !old.enableUnlimitedReplays else old.enableUnlimitedReplays,
            permanentViewMode = if (old.quickTogglePermanentView) !old.permanentViewMode else old.permanentViewMode,
            allowScreenshots = if (old.quickToggleAllowScreenshots) !old.allowScreenshots else old.allowScreenshots,
            source = "quick-toggle"
        )
        InstagramFeatureStateStore.update(next)
        refreshActiveHooks("quick-toggle")
    }

    private fun handleStoryTrayLongPress(view: View): Boolean {
        if (!state.enableStoryTrayLongPressActions) return false
        if (!isStoryTraySurface(view)) return false
        val activity = findActivity(view.context) ?: currentActivity ?: return false
        val media = findStoryTrayMedia(view)
        if (media.profileUrl == null && media.coverUrl == null) return false
        pendingStoryTrayMenu = PendingStoryTrayMenu(activity, media, System.currentTimeMillis())
        scheduleNativeMenuInjection(activity.window?.decorView)
        logInfo("Primed Story tray menu actions from long press")
        return false
    }

    private fun primeStoryTrayMenuFromTouch(view: View, event: MotionEvent) {
        if (!state.enableStoryTrayLongPressActions || event.actionMasked != MotionEvent.ACTION_DOWN) return
        if (event.rawY > dp(view, 720)) return
        if (!isStoryTraySurface(view)) return
        val activity = findActivity(view.context) ?: currentActivity ?: return
        val media = findStoryTrayMedia(view)
        if (media.profileUrl == null && media.coverUrl == null) return
        pendingStoryTrayMenu = PendingStoryTrayMenu(activity, media, System.currentTimeMillis())
        scheduleNativeMenuInjection(activity.window?.decorView)
        logInfo("Primed Story tray menu actions from touch")
    }

    private fun findStoryTrayMedia(pressed: View): StoryTrayMedia {
        val container = nearestStoryTrayContainer(pressed) ?: pressed
        val candidates = mutableListOf<Pair<View, String>>()
        fun collect(view: View, depth: Int) {
            if (depth > 8 || candidates.size > 120) return
            storyTrayImageUrls[view]?.takeIf { isHttpImageUrl(it) }?.let { candidates += view to it }
            if (view is ViewGroup) {
                for (i in 0 until view.childCount) collect(view.getChildAt(i), depth + 1)
            }
        }
        collect(container, 0)
        if (candidates.isEmpty() && container != pressed) collect(pressed, 0)

        var bestProfile: Pair<View, String>? = null
        var bestCover: Pair<View, String>? = null
        fun score(candidate: Pair<View, String>): Int {
            val (candidateView, url) = candidate
            var value = candidateView.width.coerceAtLeast(1) * candidateView.height.coerceAtLeast(1)
            val name = resourceEntryName(candidateView).orEmpty().lowercase(Locale.US)
            if (looksLikeProfileImageUrl(url)) value += 2_000_000
            if (name.contains("profile") || name.contains("avatar")) value += 1_000_000
            if (name.contains("cover") || name.contains("thumbnail") || name.contains("preview")) value += 500_000
            return value
        }
        candidates.forEach { candidate ->
            if (looksLikeProfileImageUrl(candidate.second)) {
                if (bestProfile == null || score(candidate) > score(bestProfile!!)) bestProfile = candidate
            } else if (bestCover == null || score(candidate) > score(bestCover!!)) {
                bestCover = candidate
            }
        }
        val profileUrl = bestProfile?.second
        return StoryTrayMedia(profileUrl, bestCover?.second ?: profileUrl)
    }

    private fun nearestStoryTrayContainer(view: View): View? {
        var current: View? = view
        repeat(10) {
            val name = resourceEntryName(current ?: return@repeat).orEmpty().lowercase(Locale.US)
            if (isStoryTrayName(name)) return current
            current = current?.parent as? View
        }
        return null
    }

    private fun isStoryTraySurface(view: View): Boolean {
        storyTraySurfaceViews[view]?.let { return it }
        var current: View? = view
        repeat(10) {
            val name = resourceEntryName(current ?: return@repeat).orEmpty().lowercase(Locale.US)
            if (isStoryTrayName(name)) {
                storyTraySurfaceViews[view] = true
                return true
            }
            current = current?.parent as? View
        }
        storyTraySurfaceViews[view] = false
        return false
    }

    private fun isStoryTrayName(name: String): Boolean {
        return name.contains("story_tray") ||
            name.contains("reel_tray") ||
            name.contains("reels_tray") ||
            name.contains("tray_item") ||
            name.contains("story_ring") ||
            name.contains("reel_ring") ||
            name.contains("highlight") ||
            name.contains("avatar_reel") ||
            name.contains("top_serp_story")
    }

    private fun attachMediaPreviewOverlay(
        activity: Activity,
        title: String,
        kind: String,
        preferredRoot: ViewGroup? = null
    ): PreviewOverlayHandle? {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            logInfo("DM preview overlay attach requested off-main kind=$kind")
            return null
        }
        if (activity.isFinishing || (Build.VERSION.SDK_INT >= 17 && activity.isDestroyed)) {
            logInfo("DM preview overlay skipped kind=$kind reason=activity_finished activity=${activity.javaClass.name}")
            return null
        }
        val preferredVisibleRoot = preferredRoot?.takeIf {
            it.isShown &&
                it.width > 0 &&
                it.height > 0 &&
                (Build.VERSION.SDK_INT < 19 || it.isAttachedToWindow)
        }
        val contentRoot = activity.findViewById<ViewGroup>(android.R.id.content)?.takeIf {
            it.isShown && it.width > 0 && it.height > 0
        }
        val root = preferredVisibleRoot ?: contentRoot ?: activity.window?.decorView as? ViewGroup
        if (root == null) {
            logInfo("DM preview overlay skipped kind=$kind reason=no_decor activity=${activity.javaClass.name}")
            return null
        }

        val density = activity.resources.displayMetrics.density
        val rootWidth = root.width.takeIf { it > 0 } ?: activity.resources.displayMetrics.widthPixels
        val dark = (activity.resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
        val panelBg = if (dark) Color.rgb(28, 28, 30) else Color.WHITE
        val textPrimary = if (dark) Color.WHITE else Color.rgb(28, 28, 30)
        val actionBg = if (dark) Color.rgb(58, 58, 60) else Color.rgb(229, 229, 234)
        val actionText = if (dark) Color.WHITE else Color.rgb(28, 28, 30)
        val callbacks = ArrayList<() -> Unit>()
        val overlay = FrameLayout(activity).apply {
            setBackgroundColor(Color.argb(188, 0, 0, 0))
            isClickable = true
            isFocusable = true
            isFocusableInTouchMode = true
            alpha = 0f
        }
        val panel = LinearLayout(activity).apply {
            orientation = LinearLayout.VERTICAL
            background = roundedDrawable(panelBg, 16f)
            isClickable = true
            setPadding((14 * density).roundToInt(), (12 * density).roundToInt(), (14 * density).roundToInt(), (14 * density).roundToInt())
        }
        var removed = false
        fun dismissOverlay() {
            if (removed) return
            removed = true
            callbacks.forEach { callback ->
                runCatching { callback() }.onFailure { logError("DM preview overlay dismiss callback failed", it) }
            }
            runCatching { root.removeView(overlay) }
            logInfo(
                "DM preview overlay dismissed kind=$kind " +
                    "surface=${runCatching { directMessageSurfaceReason(root) }.getOrNull() ?: "-"}"
            )
        }
        overlay.setOnKeyListener { _, keyCode, event ->
            if (keyCode != KeyEvent.KEYCODE_BACK) return@setOnKeyListener false
            if (event.action == KeyEvent.ACTION_UP) {
                logInfo("DM preview overlay back dismissed kind=$kind")
                dismissOverlay()
            }
            true
        }

        val header = LinearLayout(activity).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        header.addView(TextView(activity).apply {
            text = title
            setTextColor(textPrimary)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 17f)
            typeface = Typeface.DEFAULT_BOLD
            maxLines = 1
        }, LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f))
        val closeButton = Button(activity).apply {
            text = "Close"
            setTextColor(actionText)
            background = roundedDrawable(actionBg, 12f)
            minWidth = 0
            minHeight = 0
            setPadding((14 * density).roundToInt(), (7 * density).roundToInt(), (14 * density).roundToInt(), (7 * density).roundToInt())
            setOnClickListener {
                logInfo("DM preview overlay close tapped kind=$kind")
                dismissOverlay()
            }
            setOnTouchListener { view, event ->
                when (event.actionMasked) {
                    MotionEvent.ACTION_DOWN -> {
                        view.isPressed = true
                        true
                    }
                    MotionEvent.ACTION_UP -> {
                        view.isPressed = false
                        view.performClick()
                        true
                    }
                    MotionEvent.ACTION_CANCEL -> {
                        view.isPressed = false
                        true
                    }
                    else -> true
                }
            }
        }
        header.addView(closeButton, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT))
        panel.addView(header, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            bottomMargin = (10 * density).roundToInt()
        })

        val content = FrameLayout(activity).apply {
            background = roundedDrawable(Color.BLACK, 10f)
            clipToPadding = true
        }
        panel.addView(content, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT))
        overlay.addView(panel, FrameLayout.LayoutParams(
            minOf(rootWidth - (32 * density).roundToInt(), (430 * density).roundToInt()).coerceAtLeast((260 * density).roundToInt()),
            ViewGroup.LayoutParams.WRAP_CONTENT,
            Gravity.CENTER
        ))
        overlay.setOnClickListener {
            logInfo("DM preview overlay outside tapped kind=$kind")
            dismissOverlay()
        }
        panel.setOnClickListener { }

        runCatching {
            root.addView(overlay, ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT))
            root.bringChildToFront(overlay)
            overlay.bringToFront()
            overlay.requestFocus()
            root.invalidate()
            overlay.animate().alpha(1f).setDuration(90L).start()
            logInfo(
                "DM preview overlay attached kind=$kind activity=${activity.javaClass.name} " +
                    "root=${root.javaClass.name} preferred=${root === preferredVisibleRoot} size=${root.width}x${root.height}"
            )
        }.onFailure {
            logError("DM preview overlay attach failed kind=$kind", it)
            return null
        }

        return PreviewOverlayHandle(overlay, content, callbacks) { dismissOverlay() }
    }

    private fun showImagePreview(activity: Activity, title: String, url: String, preferredRoot: ViewGroup? = null) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            mainHandler.post { showImagePreview(activity, title, url, preferredRoot) }
            return
        }
        val overlay = attachMediaPreviewOverlay(activity, title, "image", preferredRoot)
        if (overlay == null) {
            Toast.makeText(activity, "No media found", Toast.LENGTH_SHORT).show()
            return
        }
        val maxHeight = (activity.resources.displayMetrics.heightPixels * 0.68f).roundToInt().coerceAtLeast(dp(260))
        val imageView = ImageView(activity).apply {
            adjustViewBounds = true
            scaleType = ImageView.ScaleType.FIT_CENTER
            minimumHeight = dp(220)
            setBackgroundColor(Color.BLACK)
        }
        overlay.content.addView(imageView, FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(300), Gravity.CENTER))
        logInfo("Image preview dialog shown title=$title url=${redactCdnUrlForLog(url)}")
        Thread({
            runCatching {
                val connection = URL(url).openConnection() as HttpURLConnection
                connection.connectTimeout = 10_000
                connection.readTimeout = 15_000
                connection.instanceFollowRedirects = true
                connection.setRequestProperty("User-Agent", "Instagram 300.0.0.0 Android")
                try {
                    connection.inputStream.use { BitmapFactory.decodeStream(it) ?: error("bitmap decode failed") }
                } finally {
                    connection.disconnect()
                }
            }.onSuccess { bitmap ->
                mainHandler.post {
                    if (overlay.overlay.parent != null) {
                        val width = overlay.content.width.takeIf { it > 0 }
                            ?: (activity.resources.displayMetrics.widthPixels - dp(64)).coerceAtLeast(dp(240))
                        val targetHeight = ((width.toFloat() * bitmap.height.toFloat()) / bitmap.width.coerceAtLeast(1).toFloat())
                            .roundToInt()
                            .coerceIn(dp(180), maxHeight)
                        imageView.layoutParams = (imageView.layoutParams as FrameLayout.LayoutParams).apply {
                            height = targetHeight
                        }
                        imageView.setImageBitmap(bitmap)
                        logInfo("Image preview bitmap loaded size=${bitmap.width}x${bitmap.height} target=${width}x$targetHeight")
                    } else {
                        logInfo("Image preview bitmap loaded after dialog closed size=${bitmap.width}x${bitmap.height}")
                    }
                }
            }.onFailure {
                logError("Image preview load failed url=${redactCdnUrlForLog(url)}", it)
                mainHandler.post {
                    overlay.dismiss()
                    Toast.makeText(activity, "No media found", Toast.LENGTH_SHORT).show()
                }
            }
        }, "PurrfectInstaImagePreview").start()
    }

    private fun showVideoPreview(activity: Activity, title: String, url: String, preferredRoot: ViewGroup? = null) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            mainHandler.post { showVideoPreview(activity, title, url, preferredRoot) }
            return
        }
        val overlay = attachMediaPreviewOverlay(activity, title, "video", preferredRoot)
        if (overlay == null) {
            Toast.makeText(activity, "Cannot preview this video", Toast.LENGTH_SHORT).show()
            return
        }
        val density = activity.resources.displayMetrics.density
        val minHeight = (240 * density).roundToInt()
        val maxHeight = (activity.resources.displayMetrics.heightPixels * 0.70f).roundToInt().coerceAtLeast(minHeight)
        val videoView = VideoView(activity).apply {
            setBackgroundColor(Color.BLACK)
        }
        overlay.content.addView(videoView, FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, minOf((420 * density).roundToInt(), maxHeight), Gravity.CENTER))
        val controller = MediaController(activity).apply { setAnchorView(videoView) }
        videoView.setMediaController(controller)
        videoView.setOnPreparedListener { player ->
            player.isLooping = true
            val width = overlay.content.width.takeIf { it > 0 }
                ?: (activity.resources.displayMetrics.widthPixels - dp(64)).coerceAtLeast(dp(240))
            val targetHeight = if (player.videoWidth > 0 && player.videoHeight > 0) {
                ((width.toFloat() * player.videoHeight.toFloat()) / player.videoWidth.toFloat()).roundToInt().coerceIn(minHeight, maxHeight)
            } else {
                minOf((420 * density).roundToInt(), maxHeight)
            }
            videoView.layoutParams = (videoView.layoutParams as FrameLayout.LayoutParams).apply {
                height = targetHeight
            }
            logInfo("DM video preview prepared size=${player.videoWidth}x${player.videoHeight} target=${width}x$targetHeight")
            if (overlay.overlay.parent != null) {
                videoView.start()
                controller.show(1_500)
            }
        }
        videoView.setOnErrorListener { _, what, extra ->
            logInfo("DM video preview failed what=$what extra=$extra url=${redactCdnUrlForLog(url)}")
            Toast.makeText(activity, "Cannot preview this video", Toast.LENGTH_SHORT).show()
            overlay.dismiss()
            true
        }
        overlay.onDismissCallbacks += {
            runCatching { videoView.stopPlayback() }
        }
        runCatching {
            videoView.setVideoURI(
                Uri.parse(url),
                mapOf(
                    "User-Agent" to "Instagram 300.0.0.0 Android",
                    "Referer" to "https://www.instagram.com/"
                )
            )
        }.onFailure {
            logError("DM video preview setup failed", it)
            overlay.dismiss()
            Toast.makeText(activity, "Cannot preview this video", Toast.LENGTH_SHORT).show()
        }
    }

    private fun showAudioPreview(activity: Activity, title: String, source: String, preferredRoot: ViewGroup? = null) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            mainHandler.post { showAudioPreview(activity, title, source, preferredRoot) }
            return
        }
        val overlay = attachMediaPreviewOverlay(activity, title, "audio", preferredRoot)
        if (overlay == null) {
            Toast.makeText(activity, "Cannot preview this voice message", Toast.LENGTH_SHORT).show()
            return
        }
        val density = activity.resources.displayMetrics.density
        val dark = (activity.resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
        val textPrimary = if (dark) Color.WHITE else Color.rgb(28, 28, 30)
        val textSecondary = if (dark) Color.rgb(199, 199, 204) else Color.rgb(99, 99, 102)
        val buttonBg = if (dark) Color.rgb(58, 58, 60) else Color.rgb(229, 229, 234)
        val body = LinearLayout(activity).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER_HORIZONTAL
            setPadding((18 * density).roundToInt(), (22 * density).roundToInt(), (18 * density).roundToInt(), (20 * density).roundToInt())
            setBackgroundColor(Color.BLACK)
        }
        val status = TextView(activity).apply {
            text = "Loading voice message"
            setTextColor(textPrimary)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)
            gravity = Gravity.CENTER
        }
        val position = TextView(activity).apply {
            text = "0:00 / 0:00"
            setTextColor(textSecondary)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)
            gravity = Gravity.CENTER
        }
        val seek = SeekBar(activity).apply {
            max = 1000
            progress = 0
            isEnabled = false
        }
        val playPause = Button(activity).apply {
            text = "Play"
            isEnabled = false
            setTextColor(textPrimary)
            background = roundedDrawable(buttonBg, 12f)
            minWidth = 0
            minHeight = 0
            setPadding((22 * density).roundToInt(), (8 * density).roundToInt(), (22 * density).roundToInt(), (8 * density).roundToInt())
        }
        body.addView(status, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT))
        body.addView(position, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            topMargin = (8 * density).roundToInt()
        })
        body.addView(seek, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            topMargin = (12 * density).roundToInt()
        })
        body.addView(playPause, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            topMargin = (12 * density).roundToInt()
        })
        overlay.content.addView(body, FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(210), Gravity.CENTER))

        var player: MediaPlayer? = null
        var prepared = false
        var userSeeking = false
        fun formatMs(ms: Int): String {
            val safe = ms.coerceAtLeast(0) / 1000
            return "${safe / 60}:${(safe % 60).toString().padStart(2, '0')}"
        }
        val progressUpdater = object : Runnable {
            override fun run() {
                val current = player ?: return
                if (prepared && !userSeeking) {
                    val duration = runCatching { current.duration }.getOrDefault(0).coerceAtLeast(0)
                    val currentPosition = runCatching { current.currentPosition }.getOrDefault(0).coerceAtLeast(0)
                    if (duration > 0) seek.progress = ((currentPosition.toFloat() / duration.toFloat()) * seek.max).roundToInt().coerceIn(0, seek.max)
                    position.text = "${formatMs(currentPosition)} / ${formatMs(duration)}"
                    playPause.text = if (runCatching { current.isPlaying }.getOrDefault(false)) "Pause" else "Play"
                }
                if (overlay.overlay.parent != null) mainHandler.postDelayed(this, 250L)
            }
        }
        seek.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {
            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) {
                if (!fromUser || !prepared) return
                val current = player ?: return
                val duration = runCatching { current.duration }.getOrDefault(0).coerceAtLeast(0)
                if (duration > 0) position.text = "${formatMs((duration * (progress / seek.max.toFloat())).roundToInt())} / ${formatMs(duration)}"
            }

            override fun onStartTrackingTouch(seekBar: SeekBar?) {
                userSeeking = true
            }

            override fun onStopTrackingTouch(seekBar: SeekBar?) {
                val current = player ?: return
                val duration = runCatching { current.duration }.getOrDefault(0).coerceAtLeast(0)
                if (prepared && duration > 0) {
                    current.seekTo((duration * ((seekBar?.progress ?: 0) / seek.max.toFloat())).roundToInt())
                }
                userSeeking = false
            }
        })
        playPause.setOnClickListener {
            val current = player ?: return@setOnClickListener
            if (!prepared) return@setOnClickListener
            if (current.isPlaying) current.pause() else current.start()
            playPause.text = if (current.isPlaying) "Pause" else "Play"
            mainHandler.post(progressUpdater)
        }
        overlay.onDismissCallbacks += {
            mainHandler.removeCallbacks(progressUpdater)
            runCatching { player?.release() }
            player = null
        }
        runCatching {
            val mediaPlayer = MediaPlayer()
            player = mediaPlayer
            mediaPlayer.setOnPreparedListener {
                prepared = true
                seek.isEnabled = true
                playPause.isEnabled = true
                status.text = "Voice message"
                position.text = "0:00 / ${formatMs(it.duration)}"
                it.start()
                playPause.text = "Pause"
                mainHandler.post(progressUpdater)
                logInfo("DM audio preview prepared duration=${it.duration} source=${redactCdnUrlForLog(source)}")
            }
            mediaPlayer.setOnCompletionListener {
                seek.progress = 0
                playPause.text = "Play"
                runCatching { it.seekTo(0) }
                mainHandler.post(progressUpdater)
            }
            mediaPlayer.setOnErrorListener { _, what, extra ->
                logInfo("DM audio preview failed what=$what extra=$extra source=${redactCdnUrlForLog(source)}")
                Toast.makeText(activity, "Cannot preview this voice message", Toast.LENGTH_SHORT).show()
                overlay.dismiss()
                true
            }
            if (source.startsWith("http://") || source.startsWith("https://")) {
                mediaPlayer.setDataSource(
                    activity,
                    Uri.parse(source),
                    mapOf(
                        "User-Agent" to "Instagram 300.0.0.0 Android",
                        "Referer" to "https://www.instagram.com/"
                    )
                )
            } else {
                mediaPlayer.setDataSource(source)
            }
            mediaPlayer.prepareAsync()
        }.onFailure {
            logError("DM audio preview setup failed", it)
            overlay.dismiss()
            Toast.makeText(activity, "Cannot preview this voice message", Toast.LENGTH_SHORT).show()
        }
    }

    private fun redactCdnUrlForLog(url: String): String {
        val clean = url.substringBefore("&se=").substringBefore("?se=").substringBefore("&oe=").substringBefore("?oe=")
        return clean.take(420)
    }

    private fun isCommentSurface(view: View): Boolean {
        commentSurfaceViews[view]?.let { return it }
        if (isCommentActionEntryPoint(view)) {
            commentSurfaceViews[view] = false
            return false
        }
        var current: View? = view
        repeat(10) {
            val node = current ?: return@repeat
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (isCommentActionEntryPoint(node)) {
                commentSurfaceViews[view] = false
                return false
            }
            if (name.contains("comment") || name.contains("comments") || name.contains("ufi") ||
                name.contains("reply_row") || name.contains("media_comment")
            ) {
                commentSurfaceViews[view] = true
                return true
            }
            current = node.parent as? View
        }
        commentSurfaceViews[view] = false
        return false
    }

    private fun isCommentActionEntryPoint(view: View): Boolean {
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        if (name == "row_feed_button_comment" ||
            name == "comment_button" ||
            name == "clips_comment_button" ||
            name == "reel_viewer_comment_button" ||
            name.contains("row_feed_button_comment") ||
            name.contains("ufi_comment_button")
        ) {
            return true
        }
        val desc = view.contentDescription?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
        if (desc == "comment" || desc == "view comments" || desc.matches(Regex("\\d+[,.]?\\d*\\s+comments?"))) return true
        var current = view.parent as? View
        repeat(3) {
            val node = current ?: return@repeat
            val parentName = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (parentName == "row_feed_view_group_buttons" ||
                parentName.contains("clips_ufi_component") ||
                parentName.contains("ufi_component") ||
                parentName.contains("action_bar")
            ) {
                return true
            }
            current = node.parent as? View
        }
        return false
    }

    private fun applyProfilePictureDownload(view: View) {
        if (!state.enableProfileDownload) return
        ensureProfileResourceIds(view.context)
        val id = view.id
        if (id != expandedProfilePicId &&
            id != profileShareCardId &&
            id != profileShareCardDownloadButtonId &&
            (id == View.NO_ID || !resourceEntryName(view).orEmpty().contains("profile_share_card"))
        ) {
            return
        }
        when {
            isExpandedProfilePicView(view) -> {
                injectProfilePictureLongPress(view)
                scheduleProfileDownloadButtonInjection(view.rootView)
                rememberExpandedProfilePictureUrl(view)
            }
            view is ViewGroup && isProfileShareCard(view) -> {
                scheduleProfileCardInjection(view, 0L)
            }
            isExistingNativeProfileDownloadButton(view) -> {
                hideNativeProfileDownloadButton(view)
            }
        }
    }

    private fun injectProfilePictureLongPress(view: View) {
        if (!profileDownloadHookedPics.add(view)) return
        view.isLongClickable = true
        view.setOnLongClickListener {
            downloadCurrentProfilePicture(it.context, it)
            true
        }
    }

    private fun scheduleProfileDownloadButtonInjection(rootOrCard: View?) {
        if (rootOrCard == null) return
        ensureProfileResourceIds(rootOrCard.context)
        if (rootOrCard is ViewGroup && isProfileShareCardFast(rootOrCard)) {
            scheduleProfileCardInjection(rootOrCard, 0L)
            return
        }
        if (!profilePendingRootInjections.add(rootOrCard)) return
        rootOrCard.postDelayed({
            profilePendingRootInjections.remove(rootOrCard)
            maybeInjectProfileDownloadButton(rootOrCard)
        }, 96L)
    }

    private fun scheduleProfileCardInjection(card: ViewGroup?, delayMs: Long) {
        card ?: return
        if (!profilePendingCardInjections.add(card)) return
        card.postDelayed({
            profilePendingCardInjections.remove(card)
            injectProfileDownloadButton(card)
        }, delayMs.coerceAtLeast(0L))
    }

    private fun maybeInjectProfileDownloadButton(rootOrCard: View?) {
        if (!state.enableProfileDownload || rootOrCard == null) return
        ensureProfileResourceIds(rootOrCard.context)
        val card = when {
            rootOrCard is ViewGroup && isProfileShareCard(rootOrCard) -> rootOrCard
            else -> findViewByIdOrName(rootOrCard, profileShareCardId, "profile_share_card") as? ViewGroup
        } ?: return
        scheduleProfileCardInjection(card, 0L)
    }

    private fun injectProfileDownloadButton(rootOrCard: View?) {
        val card = rootOrCard as? ViewGroup ?: return
        if (!state.enableProfileDownload || card.childCount == 0) return
        hideNativeProfileDownloadButton(card)
        card.findViewWithTag<View>("purrfect_insta_profile_download_button")?.let {
            bindProfileDownloadClick(it)
            normalizeProfileShareCard(card)
            return
        }
        val context = card.context
        val item = inflateProfileDownloadItem(context, card).apply {
            tag = "purrfect_insta_profile_download_button"
            layoutParams = profileActionItemLayoutParams(card)
        }
        bindProfileDownloadClick(item)
        val spacer = Space(context).apply { layoutParams = profileSpacerLayoutParams(card) }
        val insertIndex = profileTrailingSpaceIndex(card)
        runCatching {
            suppressProfileActionBarChildHook.set(true)
            card.addView(spacer, insertIndex)
            card.addView(item, insertIndex + 1)
        }.onFailure { logError("Failed injecting profile download button", it) }
        suppressProfileActionBarChildHook.remove()
        normalizeProfileShareCard(card)
    }

    private fun inflateProfileDownloadItem(context: Context, parent: ViewGroup): View {
        val inflated = profileInteractionLayoutId.takeIf { it != 0 }?.let { layoutId ->
            runCatching { LayoutInflater.from(context).inflate(layoutId, parent, false) }.getOrNull()
        }
        val item = inflated ?: createFallbackProfileDownloadItem(context)
        item.visibility = View.VISIBLE
        item.isEnabled = true
        item.isClickable = true
        item.isFocusable = true
        item.contentDescription = "Download"
        findImageViewByIdOrName(item, profileInteractionIconId, "profile_interaction_item_icon")?.apply {
            setImageResource(android.R.drawable.stat_sys_download_done)
            setColorFilter(Color.WHITE)
            contentDescription = "Download"
        }
        normalizeProfileDownloadItemText(item)
        return item
    }

    private fun createFallbackProfileDownloadItem(context: Context): View {
        return LinearLayout(context).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setPadding(dp(4), dp(4), dp(4), dp(4))
            addView(ImageView(context).apply {
                setImageResource(android.R.drawable.stat_sys_download_done)
                setColorFilter(Color.WHITE)
            }, LinearLayout.LayoutParams(dp(32), dp(32)).apply { gravity = Gravity.CENTER_HORIZONTAL })
            addView(TextView(context).apply {
                text = "Download"
                setTextColor(Color.WHITE)
                gravity = Gravity.CENTER
                textSize = 14f
                maxLines = 2
                setSingleLine(false)
            }, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
            })
        }
    }

    private fun profileSpacerLayoutParams(parent: ViewGroup): ViewGroup.LayoutParams {
        return if (parent is LinearLayout) LinearLayout.LayoutParams(0, 0, 0f) else ViewGroup.LayoutParams(0, 0)
    }

    private fun profileActionItemLayoutParams(parent: ViewGroup): ViewGroup.LayoutParams {
        return if (parent is LinearLayout) {
            LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                gravity = Gravity.TOP or Gravity.CENTER_HORIZONTAL
            }
        } else {
            ViewGroup.LayoutParams(dp(74), ViewGroup.LayoutParams.WRAP_CONTENT)
        }
    }

    private fun bindProfileDownloadClick(button: View) {
        button.setOnClickListener { downloadCurrentProfilePicture(it.context, it.rootView) }
        button.setOnLongClickListener {
            downloadCurrentProfilePicture(it.context, it.rootView)
            true
        }
    }

    private fun normalizeProfileShareCard(card: ViewGroup) {
        if (card !is LinearLayout) return
        for (index in 0 until card.childCount) {
            val child = card.getChildAt(index)
            if (child is Space) {
                child.visibility = View.GONE
                child.layoutParams = LinearLayout.LayoutParams(0, 0, 0f)
                continue
            }
            if (child.visibility == View.GONE) continue
            child.minimumWidth = 0
            child.layoutParams = profileActionItemLayoutParams(card)
            normalizeProfileDownloadItemText(child)
        }
        card.clipToPadding = false
        card.clipChildren = false
        (card.parent as? ViewGroup)?.clipChildren = false
    }

    private fun normalizeProfileDownloadItemText(item: View) {
        findTextViewByIdOrName(item, profileInteractionLabelId, "profile_interaction_item_label")?.apply {
            text = if (item.tag == "purrfect_insta_profile_download_button") "Download" else text
            gravity = Gravity.CENTER
            setSingleLine(false)
            maxLines = 2
        }
    }

    private fun profileTrailingSpaceIndex(card: ViewGroup): Int {
        val count = card.childCount
        if (count <= 0) return 0
        return if (card.getChildAt(count - 1) is Space) count - 1 else count
    }

    private fun hideNativeProfileDownloadButton(rootOrButton: View?) {
        rootOrButton ?: return
        val button = if (isExistingNativeProfileDownloadButton(rootOrButton)) {
            rootOrButton
        } else {
            findViewByIdOrName(rootOrButton, profileShareCardDownloadButtonId, "profile_share_card_download_button")
        }
        if (button?.tag == "purrfect_insta_profile_download_button") return
        button?.apply {
            visibility = View.GONE
            isEnabled = false
            setOnClickListener(null)
            setOnLongClickListener(null)
        }
        findViewByIdOrName(rootOrButton.rootView, profileShareCardDownloadSpacerId, "profile_share_card_download_button_spacer")
            ?.let { it.visibility = View.GONE }
    }

    private fun downloadCurrentProfilePicture(context: Context, anchor: View?) {
        val url = resolveProfilePictureUrl(anchor)?.let(::highQualityProfilePictureUrl) ?: run {
            Toast.makeText(context, "Profile picture URL not found", Toast.LENGTH_SHORT).show()
            return
        }
        val activity = findActivity(context)
        val username = findVisibleProfileUsername(activity?.window?.decorView ?: anchor?.rootView)
        enqueueDownload(url, DownloadMetadata(username = username, type = "profile"))
    }

    private fun resolveProfilePictureUrl(anchor: View?): String? {
        val root = anchor?.rootView ?: anchor
        findViewByIdOrName(root, expandedProfilePicId, "expanded_profile_pic")?.let { expanded ->
            profilePictureUrlForView(expanded)?.let { return it }
            if (expanded is ViewGroup) findProfileImageUrlInTree(expanded, 0, intArrayOf(80))?.let { return it }
        }
        anchor?.let { view ->
            profilePictureUrlForView(view)?.let { return it }
            if (view is ViewGroup) findProfileImageUrlInTree(view, 0, intArrayOf(120))?.let { return it }
        }
        return lastExpandedProfilePicUrl?.takeIf { isHttpImageUrl(it) && looksLikeProfileImageUrl(it) }
    }

    private fun rememberExpandedProfilePictureUrl(view: View) {
        val url = profilePictureUrlForView(view)
            ?: (view as? ViewGroup)?.let { findProfileImageUrlInTree(it, 0, intArrayOf(120)) }
            ?: return
        highQualityProfilePictureUrl(url).let { upgraded ->
            lastExpandedProfilePicUrl = upgraded
            lastProfilePicUrl = upgraded
        }
    }

    private fun ensureProfileResourceIds(context: Context?) {
        if (profileResourceIdsResolved || context == null) return
        synchronized(this) {
            if (profileResourceIdsResolved) return
            fun id(name: String, type: String, fallback: Int): Int {
                return runCatching { context.resources.getIdentifier(name, type, context.packageName) }
                    .getOrDefault(0)
                    .takeIf { it != 0 } ?: fallback
            }
            expandedProfilePicId = id("expanded_profile_pic", "id", expandedProfilePicId)
            profileShareCardId = id("profile_share_card", "id", profileShareCardId)
            profileShareCardDownloadButtonId = id("profile_share_card_download_button", "id", profileShareCardDownloadButtonId)
            profileShareCardDownloadSpacerId = id("profile_share_card_download_button_spacer", "id", profileShareCardDownloadSpacerId)
            profileInteractionIconId = id("profile_interaction_item_icon", "id", profileInteractionIconId)
            profileInteractionLabelId = id("profile_interaction_item_label", "id", profileInteractionLabelId)
            profileInteractionLayoutId = id("layout_expanded_profile_picture_interaction_bar_item_view", "layout", profileInteractionLayoutId)
            profileResourceIdsResolved = true
        }
    }

    private fun isExpandedProfilePicView(view: View?): Boolean {
        view ?: return false
        ensureProfileResourceIds(view.context)
        return view.id != View.NO_ID && view.id == expandedProfilePicId
    }

    private fun isProfileShareCardFast(view: View?): Boolean {
        view ?: return false
        return view.id != View.NO_ID && view.id == profileShareCardId
    }

    private fun isProfileShareCard(view: View?): Boolean {
        view ?: return false
        ensureProfileResourceIds(view.context)
        return isProfileShareCardFast(view) || resourceEntryName(view).orEmpty().contains("profile_share_card")
    }

    private fun isExistingNativeProfileDownloadButton(view: View?): Boolean {
        view ?: return false
        ensureProfileResourceIds(view.context)
        return (view.id != View.NO_ID && view.id == profileShareCardDownloadButtonId) ||
            resourceEntryName(view).orEmpty().contains("profile_share_card_download_button")
    }

    private fun findViewByIdOrName(root: View?, id: Int, name: String): View? {
        root ?: return null
        runCatching {
            if (id != 0) root.findViewById<View>(id)?.let { return it }
        }
        if (resourceEntryName(root) == name) return root
        if (root is ViewGroup) {
            for (i in 0 until root.childCount) {
                findViewByIdOrName(root.getChildAt(i), id, name)?.let { return it }
            }
        }
        return null
    }

    private fun findImageViewByIdOrName(root: View?, id: Int, name: String): ImageView? =
        findViewByIdOrName(root, id, name) as? ImageView

    private fun findTextViewByIdOrName(root: View?, id: Int, name: String): TextView? =
        findViewByIdOrName(root, id, name) as? TextView

    private fun profilePictureUrlForView(view: View): String? {
        storyTrayImageUrls[view]
            ?.takeIf { isProfilePictureCandidateUrl(view, it) }
            ?.let { return it }
        extractMediaUrlFromView(view)
            ?.takeIf { isProfilePictureCandidateUrl(view, it) }
            ?.let { return it }
        return null
    }

    private fun findProfileImageUrlInTree(view: View, depth: Int, budget: IntArray): String? {
        var bestUrl: String? = null
        var bestScore = Int.MIN_VALUE
        fun visit(node: View, currentDepth: Int) {
            if (currentDepth > 8 || budget[0]-- <= 0 || node.visibility != View.VISIBLE) return
            profilePictureUrlForView(node)?.let { url ->
                val score = profilePictureCandidateScore(node, url)
                if (score > bestScore) {
                    bestScore = score
                    bestUrl = url
                }
            }
            if (node is ViewGroup) {
                for (i in 0 until node.childCount.coerceAtMost(24)) visit(node.getChildAt(i), currentDepth + 1)
            }
        }
        visit(view, depth)
        return bestUrl
    }

    private fun isProfilePictureCandidateUrl(view: View, url: String): Boolean {
        if (!isHttpImageUrl(url)) return false
        val trustedContext = isTrustedProfilePictureContext(view)
        if (isProfilePictureDistractorContext(view) && !trustedContext) return false
        if (looksLikeProfileImageUrl(url)) return trustedContext || hasProfilePictureContext(view)
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        return name.contains("expanded_profile_pic") ||
            name.contains("profile_pic") ||
            name.contains("profile_picture")
    }

    private fun isTrustedProfilePictureContext(view: View): Boolean {
        val context = profilePictureViewContext(view, 7)
        return context.contains("expanded_profile_pic") ||
            context.contains("profile_share_card") ||
            context.contains("profile_header") ||
            context.contains("profile_picture") ||
            context.contains("profile_pic")
    }

    private fun hasProfilePictureContext(view: View): Boolean {
        val context = profilePictureViewContext(view, 5)
        return context.contains("profile") ||
            context.contains("avatar") ||
            context.contains("user_pic")
    }

    private fun isProfilePictureDistractorContext(view: View): Boolean {
        val context = profilePictureViewContext(view, 7)
        return context.contains("story") ||
            context.contains("tray") ||
            context.contains("highlight") ||
            context.contains("cover") ||
            context.contains("thumbnail") ||
            context.contains("clips") ||
            context.contains("reel")
    }

    private fun profilePictureViewContext(view: View, maxDepth: Int): String {
        val builder = StringBuilder()
        var node: View? = view
        repeat(maxDepth) {
            val current = node ?: return@repeat
            val name = resourceEntryName(current).orEmpty()
            if (name.isNotBlank()) builder.append(name.lowercase(Locale.US)).append(' ')
            val description = current.contentDescription?.toString().orEmpty()
            if (description.isNotBlank()) builder.append(description.lowercase(Locale.US)).append(' ')
            node = current.parent as? View
        }
        return builder.toString()
    }

    private fun profilePictureCandidateScore(view: View, url: String): Int {
        val name = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        var score = view.width.coerceAtLeast(1) * view.height.coerceAtLeast(1)
        if (name.contains("expanded_profile_pic")) score += 5_000_000
        if (name.contains("profile_pic") || name.contains("profile_picture")) score += 3_000_000
        if (looksLikeProfileImageUrl(url)) score += 2_000_000
        if (name.contains("avatar")) score += 500_000
        if (name.contains("highlight") || name.contains("cover") || name.contains("thumbnail") || name.contains("tray")) score -= 3_000_000
        score += profilePictureUrlSizeScore(url)
        return score
    }

    private fun profilePictureUrlSizeScore(url: String): Int {
        val lower = url.lowercase(Locale.US)
        val match = Regex("[sp](\\d{2,4})x(\\d{2,4})").find(lower) ?: return 0
        val width = match.groupValues.getOrNull(1)?.toIntOrNull() ?: 0
        val height = match.groupValues.getOrNull(2)?.toIntOrNull() ?: 0
        return width.coerceAtMost(1080) * height.coerceAtMost(1080)
    }

    private fun highQualityProfilePictureUrl(url: String): String {
        var upgraded = url
        upgraded = upgraded.replace(Regex("([?&]stp=[^&]*?)[sp]\\d{2,4}x\\d{2,4}")) { match ->
            match.groupValues[1] + "s1080x1080"
        }
        upgraded = upgraded.replace(Regex("([/_-])[sp]\\d{2,4}x\\d{2,4}(?=[/_-])")) { match ->
            match.groupValues[1] + "s1080x1080"
        }
        upgraded = upgraded.replace(Regex("([=&])s\\d{2,4}x\\d{2,4}")) { match ->
            match.groupValues[1] + "s1080x1080"
        }
        return upgraded
    }

    private fun handleCopyLongPress(view: View): Boolean {
        if (!state.enableCopyComment && !state.enableCopyBio) return false
        val textView = view as? TextView ?: return false
        val text = textView.text?.toString()?.trim()?.takeIf { it.isNotBlank() } ?: return false
        if (!shouldMakeCopyable(textView, text)) return false
        val clipboard = androidContext.getSystemService(Context.CLIPBOARD_SERVICE) as? ClipboardManager ?: return false
        clipboard.setPrimaryClip(ClipData.newPlainText("Instagram", text))
        Toast.makeText(androidContext, "Copied", Toast.LENGTH_SHORT).show()
        return true
    }

    private fun handleCaptureLongPress(view: View): Boolean {
        if (!state.captureUiElementIdsEnabled) return false
        val id = resourceEntryName(view)
        val selector = buildSelector(view)
        val value = id ?: selector ?: return false
        androidContext.sendBroadcast(
            Intent(Constants.INSTAGRAM_UI_ELEMENT_CAPTURED_ACTION)
                .setPackage(Constants.MODULE_PACKAGE_NAME)
                .putExtra(Constants.INSTAGRAM_UI_ELEMENT_CAPTURED_VALUE_EXTRA, value)
                .putExtra(Constants.INSTAGRAM_UI_ELEMENT_CAPTURED_IS_SELECTOR_EXTRA, id == null)
        )
        Toast.makeText(androidContext, "Captured Instagram UI element", Toast.LENGTH_SHORT).show()
        return true
    }

    private fun enqueueDownload(url: String, metadata: DownloadMetadata = DownloadMetadata()) {
        runCatching {
            val uri = Uri.parse(url)
            val extension = uri.lastPathSegment?.substringAfterLast('.', "bin")?.substringBefore('?')?.takeIf { it.length in 2..5 } ?: extensionForUrl(url)
            val fileName = buildDownloadFilename(url, metadata, extension)
            val safeUsername = sanitizePathSegment(metadata.folderName ?: metadata.username)
            val mimeType = mimeTypeForUrl(url)
            val customTreeUri = state.downloaderCustomUri.ifBlank {
                state.downloaderCustomPath.takeIf { it.startsWith("content://") }.orEmpty()
            }
            if (customTreeUri.isNotBlank()) {
                val serviceIntent = Intent(Constants.INSTAGRAM_DOWNLOAD_SAVE_ACTION)
                    .setClassName(Constants.MODULE_PACKAGE_NAME, "me.eternal.purrfect.instagram.InstagramDownloadSaveService")
                    .putExtra(Constants.INSTAGRAM_DOWNLOAD_URL_EXTRA, url)
                    .putExtra(Constants.INSTAGRAM_DOWNLOAD_AUDIO_URL_EXTRA, metadata.audioUrl)
                    .putExtra(Constants.INSTAGRAM_DOWNLOAD_FILENAME_EXTRA, fileName)
                    .putExtra(Constants.INSTAGRAM_DOWNLOAD_MIME_TYPE_EXTRA, mimeType)
                    .putExtra(Constants.INSTAGRAM_DOWNLOAD_USERNAME_EXTRA, safeUsername)
                    .putExtra(Constants.INSTAGRAM_DOWNLOAD_TREE_URI_EXTRA, customTreeUri)
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                    androidContext.startForegroundService(serviceIntent)
                } else {
                    androidContext.startService(serviceIntent)
                }
                Toast.makeText(androidContext, "Instagram download started", Toast.LENGTH_SHORT).show()
                return
            }

            Thread({
                runCatching {
                    val output = openDownloadOutputStream(androidContext, fileName, mimeType, safeUsername)
                    try {
                        downloadToStream(url, output)
                    } catch (throwable: Throwable) {
                        (output as? PendingMediaStoreOutputStream)?.discard()
                        throw throwable
                    } finally {
                        output.close()
                    }
                }.onSuccess {
                    mainHandler.post { Toast.makeText(androidContext, "Saved: $fileName", Toast.LENGTH_SHORT).show() }
                }.onFailure { throwable ->
                    logError("Instagram direct media save failed", throwable)
                    mainHandler.post { Toast.makeText(androidContext, "Download failed: ${throwable.message}", Toast.LENGTH_SHORT).show() }
                }
            }, "PurrfectInstaDownload").start()
            Toast.makeText(androidContext, "Instagram download started", Toast.LENGTH_SHORT).show()
        }.onFailure { logError("Failed to enqueue Instagram media download", it) }
    }

    private fun openDownloadOutputStream(context: Context, filename: String, mimeType: String, username: String?): OutputStream {
        val rawPath = state.downloaderCustomPath.takeIf { it.isNotBlank() && !it.startsWith("content://") }
        if (rawPath != null) {
            runCatching {
                var dir = File(rawPath)
                if (state.downloaderUsernameFolder && !username.isNullOrBlank()) dir = File(dir, username)
                if (!dir.exists() && !dir.mkdirs()) error("Cannot create dir: ${dir.absolutePath}")
                return java.io.FileOutputStream(File(dir, filename))
            }.onFailure { logError("Instagram raw download path failed; falling back to MediaStore", it) }
        }

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, filename)
                put(MediaStore.MediaColumns.MIME_TYPE, mimeType.ifBlank { "application/octet-stream" })
                put(MediaStore.MediaColumns.RELATIVE_PATH, buildDownloadRelativePath(username))
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
            val uri = context.contentResolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)
                ?: error("MediaStore insert failed")
            return PendingMediaStoreOutputStream(
                context,
                uri,
                context.contentResolver.openOutputStream(uri) ?: error("MediaStore openOutputStream failed")
            )
        }

        var dir = File(Environment.getExternalStorageDirectory(), "PurrfectInsta")
        if (state.downloaderUsernameFolder && !username.isNullOrBlank()) dir = File(dir, username)
        if (!dir.exists() && !dir.mkdirs()) error("Cannot create dir: ${dir.absolutePath}")
        return java.io.FileOutputStream(File(dir, filename))
    }

    private fun buildDownloadRelativePath(username: String?): String {
        var base = "Download/PurrfectInsta"
        val customPath = state.downloaderCustomPath
        if (customPath.isNotBlank() && !customPath.startsWith("content://")) {
            val externalRoot = Environment.getExternalStorageDirectory().absolutePath
            if (customPath.startsWith("$externalRoot/")) {
                val relative = customPath.substring(externalRoot.length + 1).trim('/')
                if (relative.isNotBlank()) {
                    val topLevel = relative.substringBefore('/')
                    base = if (topLevel in mediaStoreDownloadRoots) relative else "Download/$relative"
                }
            }
        }
        if (state.downloaderUsernameFolder && !username.isNullOrBlank()) base += "/$username"
        return base
    }

    private fun buildDownloadFilename(url: String, metadata: DownloadMetadata, extension: String): String {
        val username = sanitizePathSegment(metadata.username).ifBlank { "unknown" }
        val type = metadata.type.ifBlank { if (mimeTypeForUrl(url).startsWith("video")) "video" else "image" }
        val mediaId = sanitizePathSegment(metadata.mediaId).ifBlank {
            val segment = Uri.parse(url).lastPathSegment?.substringBefore('?').orEmpty()
            segment.substringBeforeLast('.').takeIf { it.isNotBlank() } ?: System.currentTimeMillis().toString()
        }
        val ext = extension.trimStart('.').ifBlank { extensionForUrl(url) }
        return buildString {
            append(username).append('_').append(type).append('_').append(mediaId)
            if (state.downloaderAddTimestamp) {
                append('_').append(java.text.SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(java.util.Date()))
            }
            append('.').append(ext)
        }
    }

    private fun sanitizePathSegment(value: String?): String {
        return value?.trim()
            ?.removePrefix("@")
            ?.replace(Regex("[\\\\/:*?\"<>|\\s]+"), "_")
            ?.trim('_')
            ?.take(80)
            .orEmpty()
    }

    private fun mimeTypeForUrl(url: String): String {
        val lower = url.substringBefore('?').lowercase(Locale.US)
        return when {
            lower.endsWith(".mp4") || lower.endsWith(".mov") -> "video/mp4"
            lower.endsWith(".m4a") || lower.endsWith(".aac") -> "audio/mp4"
            lower.endsWith(".png") -> "image/png"
            lower.endsWith(".webp") -> "image/webp"
            lower.endsWith(".gif") -> "image/gif"
            lower.endsWith(".jpg") || lower.endsWith(".jpeg") -> "image/jpeg"
            else -> if (looksLikeMediaUrl(url) && lower.contains(".mp4")) "video/mp4" else "application/octet-stream"
        }
    }

    private fun extensionForUrl(url: String): String {
        return when (mimeTypeForUrl(url)) {
            "video/mp4" -> "mp4"
            "audio/mp4" -> "m4a"
            "image/png" -> "png"
            "image/webp" -> "webp"
            "image/gif" -> "gif"
            "image/jpeg" -> "jpg"
            else -> "bin"
        }
    }

    private fun shouldBlockNotification(@Suppress("UNUSED_PARAMETER") notification: Notification): Boolean = false

    private fun sanitizeIntent(intent: Intent): Boolean {
        if (intent.getBooleanExtra(EXTRA_INTERNAL_PROFILE_OPEN, false)) return false
        var changed = false
        if (state.enableDmAnyFileUpload && widenFilePicker(intent)) changed = true
        @Suppress("DEPRECATION")
        runCatching { intent.getParcelableExtra<Intent>(Intent.EXTRA_INTENT) }.getOrNull()?.let { nested ->
            if (sanitizeIntent(nested)) {
                intent.putExtra(Intent.EXTRA_INTENT, nested)
                changed = true
            }
        }
        sanitizeUri(intent.data, allowShareDomainRewrite = false)?.let {
            intent.data = it
            changed = true
        }
        sanitizeClipData(intent.clipData)?.let {
            intent.clipData = it
            changed = true
        }
        intent.extras?.keySet()?.forEach { key ->
            val value = runCatching { intent.extras?.get(key) }.getOrNull()
            when (value) {
                is String -> {
                    val clean = sanitizeTextForSharing(value)
                    if (clean != value) {
                        intent.putExtra(key, clean)
                        changed = true
                    }
                }
                is CharSequence -> {
                    val clean = sanitizeTextForSharing(value.toString())
                    if (clean != value.toString()) {
                        intent.putExtra(key, clean as CharSequence)
                        changed = true
                    }
                }
                is Uri -> {
                    val clean = sanitizeUri(value)
                    if (clean != null) {
                        intent.putExtra(key, clean)
                        changed = true
                    }
                }
                is Intent -> {
                    if (sanitizeIntent(value)) {
                        intent.putExtra(key, value)
                        changed = true
                    }
                }
                is ArrayList<*> -> {
                    var listChanged = false
                    val rewritten = ArrayList<Uri>()
                    value.forEach { item ->
                        val uri = item as? Uri ?: return@forEach
                        rewritten += sanitizeUri(uri)?.also { listChanged = true } ?: uri
                    }
                    if (listChanged && rewritten.size == value.size) {
                        intent.putParcelableArrayListExtra(key, rewritten)
                        changed = true
                    }
                }
            }
        }
        if (changed) logInfo("Sanitized Instagram Intent link payload")
        return changed
    }

    private fun launchExternalBrowserIfNeeded(context: Context, intent: Intent): Boolean {
        if (intent.getBooleanExtra(EXTRA_INTERNAL_PROFILE_OPEN, false)) return false
        if (intent.getBooleanExtra("me.eternal.purrfect.internal_intent", false)) return false
        if (launchingExternalBrowser.get()) return false
        if (isInstagramInternalNavigationIntent(context, intent)) return false
        val url = extractHttpUrl(intent) ?: return false
        if (!looksInternalBrowserIntent(context, intent)) return false
        return runCatching {
            val external = Intent(Intent.ACTION_VIEW, Uri.parse(url))
                .addCategory(Intent.CATEGORY_BROWSABLE)
                .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
            if (context !is Activity) external.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            launchingExternalBrowser.set(true)
            context.startActivity(external)
            true
        }.onFailure {
            Toast.makeText(context, "Could not open external browser", Toast.LENGTH_SHORT).show()
        }.also {
            launchingExternalBrowser.set(false)
        }.getOrDefault(false)
    }

    private fun looksInternalBrowserIntent(context: Context, intent: Intent): Boolean {
        val action = intent.action.orEmpty().lowercase(Locale.US)
        val hostPackage = context.packageName.lowercase(Locale.US)
        val targetPackage = intent.`package`.orEmpty().lowercase(Locale.US)
        val component = intent.component?.flattenToString().orEmpty().lowercase(Locale.US)
        val extras = extrasSummary(intent).lowercase(Locale.US)
        return component.contains("browserlite") ||
            component.contains("webview") ||
            component.contains("igbrowser") ||
            component.contains("inappbrowser") ||
            component.contains("web_view") ||
            (component.contains("modalactivity") && (extras.contains("browser") || extras.contains("webview") || extras.contains("web_view") || extras.contains("url"))) ||
            (intent.action == Intent.ACTION_VIEW && isWebUri(intent.data) && targetPackage == hostPackage) ||
            (action != Intent.ACTION_VIEW.lowercase(Locale.US) && isHttp(intent.dataString) &&
                ((targetPackage.isNotBlank() && targetPackage == hostPackage) || component.contains(hostPackage)))
    }

    private fun isInstagramInternalNavigationIntent(context: Context, intent: Intent): Boolean {
        if (intent.getBooleanExtra(EXTRA_INTERNAL_PROFILE_OPEN, false)) return true
        val data = intent.data ?: return false
        if (!isInstagramShareHost(data.host)) return false
        val hostPackage = context.packageName.lowercase(Locale.US)
        val targetPackage = intent.`package`.orEmpty().lowercase(Locale.US)
        val component = intent.component
        val componentPackage = component?.packageName.orEmpty().lowercase(Locale.US)
        if (targetPackage == hostPackage || componentPackage == hostPackage) return true
        return component?.flattenToString().orEmpty().lowercase(Locale.US).contains("urlhandler")
    }

    private fun extractHttpUrl(intent: Intent): String? {
        intent.dataString?.takeIf { isHttp(it) }?.let { return it }
        return valueToHttpUrl(intent.extras)
    }

    private fun valueToHttpUrl(value: Any?): String? {
        return when (value) {
            null -> null
            is Uri -> value.toString().takeIf { isHttp(it) }
            is String -> value.takeIf { isHttp(it) }
            is CharSequence -> value.toString().takeIf { isHttp(it) }
            is Bundle -> {
                value.keySet().firstNotNullOfOrNull { key ->
                    runCatching { valueToHttpUrl(value.get(key)) }.getOrNull()
                }
            }
            else -> null
        }
    }

    private fun extrasSummary(intent: Intent): String {
        val extras = intent.extras ?: return ""
        return buildString {
            extras.keySet().forEach { key ->
                append(' ').append(key)
                val value = runCatching { extras.get(key) }.getOrNull()
                if (value is CharSequence) append(' ').append(value)
            }
        }
    }

    private fun isHttp(value: String?): Boolean {
        val lower = value?.trim()?.lowercase(Locale.US).orEmpty()
        return lower.startsWith("http://") || lower.startsWith("https://")
    }

    private fun widenFilePicker(intent: Intent?): Boolean {
        if (intent == null) return false
        var changed = false
        @Suppress("DEPRECATION")
        val nested = runCatching { intent.getParcelableExtra<Intent>(Intent.EXTRA_INTENT) }.getOrNull()
        if (nested != null && widenFilePicker(nested)) changed = true

        if (!looksLikePicker(intent)) return changed
        val oldType = intent.type
        if (shouldWidenType(oldType)) {
            intent.type = "*/*"
            changed = true
        }
        intent.putExtra(Intent.EXTRA_MIME_TYPES, mergeMimeTypes(intent.getStringArrayExtra(Intent.EXTRA_MIME_TYPES)))
        intent.addCategory(Intent.CATEGORY_OPENABLE)
        return true
    }

    private fun looksLikePicker(intent: Intent?): Boolean {
        if (intent == null) return false
        val action = intent.action
        if (action in pickerActions) return true
        val combined = "${lower(action)} ${lower(intent.type)} ${lower(intent.data?.toString())}"
        return combined.contains("content") &&
            (combined.contains("image") || combined.contains("video") || combined.contains("audio"))
    }

    private fun shouldWidenType(type: String?): Boolean {
        val clean = lower(type)
        return clean.isBlank() ||
            clean == "*/*" ||
            clean.startsWith("image/") ||
            clean.startsWith("video/") ||
            clean.startsWith("audio/") ||
            clean.contains("octet-stream")
    }

    private fun mergeMimeTypes(existing: Array<String>?): Array<String> {
        val merged = linkedSetOf<String>()
        merged += broadMimeTypes
        existing.orEmpty().forEach { type ->
            if (type.isNotBlank()) merged += type
        }
        return merged.toTypedArray()
    }

    private fun sanitizeClipData(original: ClipData?): ClipData? {
        if (original == null || original.itemCount == 0) return null
        var sanitized: ClipData? = null
        var changed = false
        val description: ClipDescription = original.description
        for (i in 0 until original.itemCount) {
            val item = original.getItemAt(i)
            val text = item.text
            val uri = item.uri
            val cleanText = text?.toString()?.let { sanitizeTextForSharing(it) }
            val cleanUri = sanitizeUri(uri)
            val cleanIntent = item.intent?.also { nested -> if (sanitizeIntent(nested)) changed = true }
            val cleanItem = ClipData.Item(
                cleanText ?: text,
                item.htmlText,
                cleanIntent,
                cleanUri ?: uri
            )
            if (sanitized == null) sanitized = ClipData(description, cleanItem) else sanitized.addItem(cleanItem)
            if ((cleanText != null && cleanText != text?.toString()) || cleanUri != null) changed = true
        }
        if (changed) logInfo("Sanitized Instagram ClipData link payload")
        return if (changed) sanitized else null
    }

    private fun sanitizeTextForSharing(text: String): String {
        var input = text
        if (state.shouldRewriteShareDomain()) input = rewriteShareDomainText(input)
        if (input.indexOf("http", ignoreCase = true) < 0) return input
        val matcher = urlPattern.matcher(input)
        val out = StringBuffer()
        var changed = false
        while (matcher.find()) {
            val raw = matcher.group()
            val clean = sanitizeUri(Uri.parse(raw))
            if (clean != null) {
                matcher.appendReplacement(out, java.util.regex.Matcher.quoteReplacement(clean.toString()))
                changed = true
            }
        }
        matcher.appendTail(out)
        return if (changed) out.toString() else input
    }

    private fun sanitizeUri(uri: Uri?, allowShareDomainRewrite: Boolean = true): Uri? {
        if (uri == null || !isWebUri(uri)) return null
        val replacedDomain = if (allowShareDomainRewrite && state.shouldRewriteShareDomain() && isInstagramShareHost(uri.host)) {
            uri.buildUpon().authority(sanitizedShareReplacementDomain()).build()
        } else {
            uri
        }
        if (!state.disableTrackingLinks && !state.stripShareTrackingParameters && replacedDomain == uri) return null
        val names = runCatching { replacedDomain.queryParameterNames }.getOrNull().orEmpty()
        if (names.isEmpty()) return if (replacedDomain != uri) replacedDomain else null
        val builder = replacedDomain.buildUpon().clearQuery()
        var removed = false
        val removedNames = ArrayList<String>()
        names.forEach { name ->
            if (isTrackingParam(name)) {
                removed = true
                if (!removedNames.contains(name)) removedNames += name
            } else {
                replacedDomain.getQueryParameters(name).forEach { value -> builder.appendQueryParameter(name, value) }
            }
        }
        val result = builder.build()
        if (removed) logInfo("Sanitized Instagram link tracking params removed=${removedNames.joinToString(",")} result=$result")
        return if (removed || result != uri) result else null
    }

    private fun rewriteShareDomainText(input: String): String {
        if (input.isEmpty()) return input
        val domain = sanitizedShareReplacementDomain()
        val matcher = instagramShareLinkPattern.matcher(input)
        val out = StringBuffer()
        var changed = false
        while (matcher.find()) {
            var match = matcher.group()
            var suffix = ""
            while (match.isNotEmpty() && isShareLinkTrailingPunctuation(match.last())) {
                suffix = match.last() + suffix
                match = match.dropLast(1)
            }
            val replacement = rewriteSingleShareUrl(match, domain) + suffix
            matcher.appendReplacement(out, java.util.regex.Matcher.quoteReplacement(replacement))
            changed = true
        }
        matcher.appendTail(out)
        return if (changed) out.toString() else input
    }

    private fun rewriteSingleShareUrl(original: String, domain: String): String {
        return runCatching {
            Uri.parse(original).buildUpon().authority(domain).build().toString()
        }.getOrElse {
            original.replaceFirst(
                Regex("(?i)://(?:www\\.|m\\.)?(instagram\\.com|instagr\\.am)"),
                "://$domain"
            )
        }
    }

    private fun isInstagramShareHost(host: String?): Boolean {
        val lowerHost = host?.lowercase(Locale.US) ?: return false
        return lowerHost == "instagram.com" ||
            lowerHost == "www.instagram.com" ||
            lowerHost == "m.instagram.com" ||
            lowerHost == "instagr.am" ||
            lowerHost == "www.instagr.am" ||
            lowerHost == "m.instagr.am"
    }

    private fun sanitizedShareReplacementDomain(): String {
        return cleanShareReplacementDomain(state.shareLinkReplacementDomain)
    }

    private fun isShareLinkTrailingPunctuation(char: Char): Boolean {
        return char == '.' || char == ',' || char == '!' || char == '?' || char == ')' || char == ']'
    }

    private fun maybeUpgradeUploadQuality(param: XC_MethodHook.MethodHookParam<*>, qualityIndex: Int, source: String) {
        if (qualityIndex !in param.args.indices) return
        val current = param.args[qualityIndex] as? Int ?: return
        val surface = currentUploadSurface()
        val allowed = (surface == UploadSurface.STORY || surface == UploadSurface.UNKNOWN) &&
            state.enableHighQualityStoryUpload
        if (current >= TARGET_STORY_UPLOAD_QUALITY) {
            if (allowed && uploadQualityLogCount++ < 12) {
                logInfo("$source upload quality already $current surface=$surface")
            }
            return
        }
        if (!allowed) {
            if (state.enableHighQualityStoryUpload && uploadQualitySkippedLogCount++ < 10) {
                logInfo("Saw $source upload quality=$current surface=$surface; left unchanged")
            }
            return
        }
        param.args[qualityIndex] = TARGET_STORY_UPLOAD_QUALITY
        if (uploadQualityLogCount++ < 12) {
            logInfo("$source upload quality $current -> $TARGET_STORY_UPLOAD_QUALITY surface=$surface")
        }
    }

    private fun storyUploadQualityPreferenceOverride(key: String): Int? {
        if (!state.enableHighQualityStoryUpload) return null
        if (!key.contains("story") && !key.contains("stories") && !recentStoryShareTap() && !recentStoryComposerSeen()) return null
        if (!key.contains("quality") && !key.contains("highres") && !key.contains("high_res")) return null
        return when {
            key.contains("level") -> 700
            key.contains("percent") || key.contains("jpeg") || key.contains("image") || key.contains("upload") -> 100
            else -> null
        }?.also { value ->
            if (uploadQualityLogCount++ < 12) logInfo("Story upload quality preference $key -> $value")
        }
    }

    private fun maybeLogHighQualityUploadNetwork(uri: URI) {
        if (!state.enableHighQualityStoryUpload) return
        if (uploadNetworkLogCount >= 20) return
        val path = lower(uri.path)
        val query = lower(uri.query)
        if (!path.contains("upload") && !path.contains("rupload") && !query.contains("upload")) return
        uploadNetworkLogCount++
        val surface = when {
            path.contains("direct") || query.contains("direct") -> UploadSurface.DIRECT
            path.contains("story") || path.contains("reel") || query.contains("story") -> UploadSurface.STORY
            else -> currentUploadSurface()
        }
        logInfo("Observed Instagram upload request path=$path surface=$surface highQualityStory=${state.enableHighQualityStoryUpload}")
    }

    private fun isHeicMime(mime: String): Boolean {
        val value = mime.lowercase(Locale.US)
        return value == "image/vnd.android.heic" || value == "image/heic" || value == "image/heif"
    }

    private fun shouldUseHeicUploadFallback(): Boolean {
        when (heicUploadEncoderState) {
            HEIC_ENCODER_WORKING -> return false
            HEIC_ENCODER_BROKEN -> return true
        }
        synchronized(this) {
            when (heicUploadEncoderState) {
                HEIC_ENCODER_WORKING -> return false
                HEIC_ENCODER_BROKEN -> return true
            }
            probingHeicUploadEncoder.set(true)
            val broken = try {
                runCatching {
                    val format = MediaFormat.createVideoFormat("image/vnd.android.heic", 64, 64).apply {
                        setInteger(MediaFormat.KEY_COLOR_FORMAT, MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface)
                        setInteger(MediaFormat.KEY_BIT_RATE, 1_000_000)
                        setInteger(MediaFormat.KEY_FRAME_RATE, 1)
                        setInteger(MediaFormat.KEY_I_FRAME_INTERVAL, 1)
                    }
                    val codec = MediaCodec.createEncoderByType("image/vnd.android.heic")
                    try {
                        codec.configure(format, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE)
                    } finally {
                        runCatching { codec.release() }
                    }
                }.fold(
                    onSuccess = { false },
                    onFailure = {
                        logInfo("HEIC upload encoder probe failed; JPEG upload fallback enabled: ${it.javaClass.simpleName}: ${it.message.orEmpty()}")
                        true
                    }
                )
            } finally {
                probingHeicUploadEncoder.set(false)
            }
            heicUploadEncoderState = if (broken) HEIC_ENCODER_BROKEN else HEIC_ENCODER_WORKING
            if (!broken) logInfo("HEIC upload encoder probe passed; using Instagram's normal HEIC upload path")
            return broken
        }
    }

    private fun stackLooksLikeUploadPreparation(): Boolean {
        var upload = false
        var playback = false
        Thread.currentThread().stackTrace.forEach { frame ->
            val s = "${frame.className}.${frame.methodName}".lowercase(Locale.US)
            if (s.contains("savephotoutil") || s.contains("onecameraimagerenderer") ||
                s.contains("privatestorysharesheet") || s.contains("one_tap_send") ||
                s.contains("upload") || s.contains("pendingmedia") || s.contains("composer") ||
                s.contains("share") || s.contains("directsend")
            ) {
                upload = true
            }
            if (s.contains("player") || s.contains("decoder") || s.contains("exoplayer")) playback = true
        }
        return upload && !playback
    }

    private fun currentUploadSurface(): UploadSurface {
        if (recentStoryShareTap() || recentStoryComposerSeen()) return UploadSurface.STORY
        var direct = false
        var story = false
        var strongStory = false
        Thread.currentThread().stackTrace.forEach { frame ->
            val s = "${frame.className}.${frame.methodName}".lowercase(Locale.US)
            if (s.contains("direct") || s.contains("armadillo") || s.contains("messagethread") ||
                s.contains("thread") || s.contains("inbox") || s.contains("dm") ||
                s.contains("directsend") || s.contains("directshare")
            ) {
                direct = true
            }
            if (s.contains("story") || s.contains("stories") || s.contains("reel") ||
                s.contains("reels") || s.contains("camera") || s.contains("creation") ||
                s.contains("pendingmedia") || s.contains("composer") || s.contains("capture") ||
                s.contains("share") || s.contains("upload")
            ) {
                story = true
            }
            if (s.contains("privatestory") || s.contains("stories") || s.contains("story") ||
                s.contains("reel_composer") || s.contains("quickcapture") ||
                s.contains("onecamera") || s.contains("savephotoutil")
            ) {
                strongStory = true
            }
        }
        return when {
            strongStory -> UploadSurface.STORY
            direct -> UploadSurface.DIRECT
            story -> UploadSurface.STORY
            else -> UploadSurface.UNKNOWN
        }
    }

    private fun logRefreshDecision(key: String, surface: String?, result: String, detail: String) {
        logInfoThrottled("refresh:$key", 1_500L) {
            val foreground = surface?.let { isRefreshSurfaceForeground(it) } ?: false
            val pending = surface?.let { isRefreshDialogPending(it) } ?: false
            val allowed = surface?.let { isRefreshAllowed(it) } ?: false
            "Refresh decision result=$result surface=${surface ?: "none"} foreground=$foreground pending=$pending " +
                "allowed=$allowed scope=${state.confirmRefreshScope} uiGuards=$confirmRefreshUiGuardHookedClasses " +
                "activity=${currentActivity?.javaClass?.simpleName ?: "none"} detail=$detail"
        }
    }

    private fun refreshUriForLog(uri: URI): String {
        val path = uri.path.orEmpty().take(180)
        val query = uri.rawQuery ?: uri.query
        return "path=$path queryKeys=${queryKeysForLog(query)}"
    }

    private fun queryKeysForLog(query: String?): String {
        if (query.isNullOrBlank()) return "[]"
        val keys = query.split('&')
            .asSequence()
            .map { it.substringBefore('=').take(48) }
            .filter { it.isNotBlank() }
            .distinct()
            .take(10)
            .toList()
        return "[${keys.joinToString(",")}]"
    }

    private fun maybeConfirmOrBlockRefresh(
        service: Any?,
        method: Method,
        args: Array<Any?>?,
        requestObj: Any,
        uriFieldName: String,
        uri: URI
    ): Boolean {
        if (!state.enableConfirmRefresh) return false
        val detail = refreshRequestLogDetail(uri, requestObj)
        val surface = refreshSurfaceForRequest(uri, requestObj, detail) ?: return false
        if (!state.shouldConfirmRefresh(surface)) {
            logRefreshDecision("network-scope-$surface", surface, "allowed", "scope=${state.confirmRefreshScope} $detail")
            return false
        }
        if (isRefreshAllowed(surface)) {
            logRefreshDecision("network-allowed-$surface", surface, "allowed", "recent user confirmation $detail")
            return false
        }
        if (currentActivity == null) {
            logRefreshDecision("network-no-activity-$surface", surface, "allowed", "no current activity $detail")
            return false
        }
        val foreground = isRefreshSurfaceForeground(surface)
        clearVisibleRefreshSpinners(currentActivity)
        if (!foreground) {
            logRefreshDecision("network-hidden-$surface", surface, "blocked", "hidden tab $detail")
            return true
        }
        if (isRefreshDialogPending(surface)) {
            logRefreshDecision("network-pending-$surface", surface, "blocked", "dialog already pending $detail")
            return true
        }
        setRefreshDialogPending(surface, true)
        val blocked = BlockedRefreshRequest(
            service = service,
            method = method,
            args = args?.copyOf() ?: emptyArray(),
            requestObj = requestObj,
            uriFieldName = uriFieldName,
            originalUri = uri,
            surface = surface
        )
        logRefreshDecision("network-dialog-$surface", surface, "dialog", "blocked replacement $detail")
        showConfirmRefreshDialog(
            surface,
            onConfirm = {
                setRefreshDialogPending(surface, false)
                allowRefreshSurface(surface, 3_000L)
                logRefreshDecision("network-confirm-$surface", surface, "allowed", "user confirmed $detail")
                replayRefreshRequest(blocked)
            },
            onCancel = {
                setRefreshDialogPending(surface, false)
                clearVisibleRefreshSpinners(currentActivity)
                logRefreshDecision("network-cancel-$surface", surface, "blocked", "user cancelled $detail")
            }
        )
        return true
    }

    private fun refreshSurfaceForRequest(uri: URI, requestObj: Any?, detail: String): String? {
        val path = lower(uri.path)
        val query = lower(uri.rawQuery ?: uri.query)
        if (path.contains("write_seen_state") ||
            path.contains("media/seen") ||
            path.contains("reel_seen") ||
            path.contains("/item_seen/")
        ) {
            return null
        }
        val surface = when {
            path.contains("/feed/timeline") ||
                path.contains("/feed/text_post_app_timeline") -> "feed"
            path.contains("/clips/feed") ||
                path.contains("/clips/home") ||
                path.contains("/clips/discover") ||
                path.contains("/clips/for_you") ||
                path.contains("/clips/reels_media") ||
                path.contains("/clips/netego_reels_media") -> "reels"
            else -> null
        }
        if (surface != null && isRefreshPaginationRequest(path, query, requestObj)) {
            logRefreshDecision("network-pagination-$surface", surface, "ignored", "pagination/load-more $detail")
            return null
        }
        if (surface != null) {
            logRefreshDecision("network-candidate-$surface", surface, "candidate", detail)
        }
        return surface
    }

    private fun isRefreshPaginationRequest(path: String, query: String, requestObj: Any?): Boolean {
        if (path.contains("/pagination/") || path.contains("/page_info/")) return true
        val combined = buildString {
            if (query.isNotBlank()) append(query)
            val bodySignal = refreshRequestSignal(requestObj)
            if (bodySignal.isNotBlank()) {
                if (isNotEmpty()) append('&')
                append(bodySignal)
            }
        }
        if (combined.isBlank()) return false
        if (listOf(
                "pull_to_refresh",
                "manual_refresh",
                "refresh_reason",
                "cold_start_fetch",
                "initial_fetch"
            ).any(combined::contains)
        ) {
            return false
        }
        return listOf(
            "max_id=",
            "max_id:",
            "min_id=",
            "min_id:",
            "next_max_id=",
            "next_max_id:",
            "pagination_token=",
            "pagination_token:",
            "page_token=",
            "page_token:",
            "paging_token=",
            "paging_token:",
            "end_cursor=",
            "end_cursor:",
            "cursor=",
            "cursor:",
            "after=",
            "after:",
            "offset=",
            "offset:",
            "last_media_id=",
            "last_media_id:",
            "next_media_ids=",
            "next_media_ids:",
            "seen_posts=",
            "seen_posts:",
            "seen_media_ids=",
            "seen_media_ids:",
            "older_than=",
            "older_than:"
        ).any(combined::contains)
    }

    private fun refreshRequestLogDetail(uri: URI, requestObj: Any?): String {
        val signal = refreshRequestSignal(requestObj).take(900)
        val requestClass = requestObj?.javaClass?.name?.take(120) ?: "none"
        return if (signal.isBlank()) {
            "${refreshUriForLog(uri)} requestClass=$requestClass"
        } else {
            "${refreshUriForLog(uri)} requestClass=$requestClass requestSignal=$signal"
        }
    }

    private fun refreshRequestSignal(requestObj: Any?): String {
        requestObj ?: return ""
        val out = LinkedHashSet<String>()
        val seen = IdentityHashMap<Any, Boolean>()
        collectRefreshRequestSignal(requestObj, null, depth = 0, seen = seen, out = out)
        return out.joinToString("&").lowercase(Locale.US)
    }

    private fun collectRefreshRequestSignal(
        value: Any?,
        name: String?,
        depth: Int,
        seen: IdentityHashMap<Any, Boolean>,
        out: MutableSet<String>
    ) {
        if (value == null || depth > 2 || out.size >= 80) return
        val cls = value.javaClass
        if (cls.isPrimitiveLikeForRefreshSignal()) {
            addRefreshSignalPart(out, name, value.toString())
            return
        }
        if (value is URI || value is Uri) {
            addRefreshSignalPart(out, name, value.toString())
            return
        }
        if (value is ByteArray) {
            val text = decodeRefreshSignalBytes(value)
            addRefreshSignalText(out, name, text)
            return
        }
        if (value is CharArray) {
            addRefreshSignalText(out, name, String(value))
            return
        }
        if (value is Map<*, *>) {
            if (seen.put(value, true) != null) return
            value.entries.asSequence().take(40).forEach { entry ->
                addRefreshSignalPart(out, entry.key?.toString(), entry.value?.toString())
                collectRefreshRequestSignal(entry.value, entry.key?.toString(), depth + 1, seen, out)
            }
            return
        }
        if (value is Iterable<*>) {
            if (seen.put(value, true) != null) return
            value.asSequence().take(30).forEachIndexed { index, item ->
                collectRefreshRequestSignal(item, "${name ?: "item"}_$index", depth + 1, seen, out)
            }
            return
        }
        if (cls.isArray) {
            if (seen.put(value, true) != null) return
            val count = java.lang.reflect.Array.getLength(value).coerceAtMost(30)
            for (i in 0 until count) {
                collectRefreshRequestSignal(java.lang.reflect.Array.get(value, i), "${name ?: "item"}_$i", depth + 1, seen, out)
            }
            return
        }
        val className = cls.name
        if (className.startsWith("android.view.") ||
            className.startsWith("android.content.") ||
            className.startsWith("java.lang.Class") ||
            className.startsWith("dalvik.")
        ) {
            return
        }
        if (seen.put(value, true) != null) return
        var current: Class<*>? = cls
        var fieldsSeen = 0
        while (current != null && current != Any::class.java && fieldsSeen < 50 && out.size < 80) {
            current.declaredFields.forEach { field ->
                if (fieldsSeen >= 50 || out.size >= 80) return@forEach
                val modifiers = field.modifiers
                if (Modifier.isStatic(modifiers) || field.isSynthetic) return@forEach
                val fieldName = field.name
                fieldsSeen++
                addRefreshSignalPart(out, fieldName, null)
                val fieldValue = runCatching {
                    field.isAccessible = true
                    field.get(value)
                }.getOrNull() ?: return@forEach
                collectRefreshRequestSignal(fieldValue, fieldName, depth + 1, seen, out)
            }
            current = current.superclass
        }
    }

    private fun Class<*>.isPrimitiveLikeForRefreshSignal(): Boolean {
        return isPrimitive ||
            this == java.lang.Boolean::class.java ||
            Number::class.java.isAssignableFrom(this) ||
            CharSequence::class.java.isAssignableFrom(this) ||
            this == java.lang.Character::class.java ||
            isEnum
    }

    private fun addRefreshSignalText(out: MutableSet<String>, name: String?, raw: String?) {
        val text = raw?.take(1_200)?.replace(Regex("\\p{Cntrl}+"), " ")?.replace(Regex("\\s+"), " ").orEmpty()
        if (text.isBlank()) {
            addRefreshSignalPart(out, name, null)
            return
        }
        Regex("""(?:^|[?&,\s{])([A-Za-z0-9_.-]{2,64})[=:]""")
            .findAll(text)
            .take(30)
            .forEach { match -> addRefreshSignalPart(out, match.groupValues[1], null) }
        addRefreshSignalPart(out, name, text.take(160))
    }

    private fun addRefreshSignalPart(out: MutableSet<String>, name: String?, rawValue: String?) {
        val cleanName = name
            ?.replace(Regex("[^A-Za-z0-9_.-]"), "_")
            ?.take(64)
            ?.takeIf { it.isNotBlank() }
        val cleanValue = rawValue
            ?.replace(Regex("\\s+"), " ")
            ?.replace(Regex("""([?&][^=&]*token=)[^&]+""", RegexOption.IGNORE_CASE), "$1<redacted>")
            ?.take(160)
            ?.takeIf { it.isNotBlank() }
        when {
            cleanName != null && cleanValue != null -> out += "$cleanName=$cleanValue"
            cleanName != null -> out += "$cleanName:"
            cleanValue != null -> out += cleanValue
        }
    }

    private fun decodeRefreshSignalBytes(bytes: ByteArray): String {
        if (bytes.isEmpty()) return ""
        val decoded = runCatching {
            if (bytes.size >= 2 && bytes[0] == 0x1f.toByte() && bytes[1] == 0x8b.toByte()) {
                GZIPInputStream(java.io.ByteArrayInputStream(bytes)).use { gzip ->
                    val out = ByteArray(4_096)
                    val count = gzip.read(out)
                    if (count > 0) String(out, 0, count, Charsets.UTF_8) else ""
                }
            } else {
                String(bytes.copyOfRange(0, bytes.size.coerceAtMost(1_200)), Charsets.UTF_8)
            }
        }.getOrDefault("")
        val printable = decoded.count { !it.isISOControl() || it == '\n' || it == '\r' || it == '\t' }
        return if (decoded.isNotBlank() && printable * 100 / decoded.length.coerceAtLeast(1) >= 70) decoded else ""
    }

    private fun replayRefreshRequest(request: BlockedRefreshRequest) {
        runCatching {
            setUriField(request.requestObj, request.uriFieldName, request.originalUri)
            XposedBridge.invokeOriginalMethod(request.method, request.service, request.args)
            logInfo("Replayed ${request.surface} refresh ${request.originalUri.path}")
        }.onFailure { logError("Refresh replay failed", it) }
    }

    private fun blockTigonUriIfNeeded(
        uri: URI,
        service: Any?,
        method: Method,
        args: Array<Any?>?,
        requestObj: Any,
        uriFieldName: String
    ): Boolean {
        if (isInstagramMobileConfigUri(uri)) {
            logInfo("Allowed Instagram Tigon mobile config request: ${uri.path}")
            return false
        }
        val reason = dropReasonForNetworkUri(uri)
        if (reason != null) {
            when (reason) {
                "dm_seen" -> recordBlockedDmSeenNetworkRequest(service, method, args, requestObj, uriFieldName, uri)
                "story_seen" -> recordBlockedStorySeenNetworkRequest(service, method, args, requestObj, uriFieldName, uri)
            }
            if (reason == "ad" || reason == "analytics" || reason == "reels" || reason == "explore") {
                logInfo("Blocked Instagram Tigon request: ${uri.path} reason=$reason")
            }
            return true
        }
        return false
    }

    private fun isCommentSurfaceTree(root: View?): Boolean {
        fun scan(node: View?, depth: Int, budget: IntArray): Boolean {
            if (node == null || depth > 10 || budget[0]-- <= 0) return false
            val name = resourceEntryName(node).orEmpty().lowercase(Locale.US)
            if (name.contains("comment") || name.contains("comments") || name.contains("ufi") ||
                name.contains("reply_row") || name.contains("media_comment")
            ) {
                return true
            }
            if (node is ViewGroup) {
                for (i in 0 until node.childCount) {
                    if (scan(node.getChildAt(i), depth + 1, budget)) return true
                }
            }
            return false
        }
        return scan(root, 0, intArrayOf(350))
    }

    private fun rewriteOrBlockNetworkUrl(url: String): String? {
        val clean = url
        val uri = runCatching { URI(clean) }.getOrNull()
        if (uri != null && isInstagramMobileConfigUri(uri)) {
            logInfo("Allowed Instagram OkHttp mobile config request: ${uri.path}")
            return null
        }
        val exactReason = uri?.let(::dropReasonForNetworkUri)
        if (exactReason != null) {
            return "https://127.0.0.1/404?reason=$exactReason"
        }
        val lower = clean.lowercase()
        val blockReason = when {
            state.isGhostSeen && (lower.contains("mark_thread_seen") || lower.contains("/item_seen/")) -> "dm_seen"
            state.isGhostTyping && lower.contains("typing") -> "typing"
            state.isGhostStory && (lower.contains("media/seen") || lower.contains("reel_seen") || lower.contains("write_seen_state")) -> "story_seen"
            state.isGhostScreenshot && lower.contains("screenshot") -> "screenshot"
            state.isGhostViewOnce && lower.contains("visual_item_seen") -> "view_once"
            state.hideVoiceMessageSeen && lower.contains("voice_item_seen") -> "voice_seen"
            state.isGhostLive && (lower.contains("live_presence") || lower.contains("/presence/")) -> "live_presence"
            state.keepEphemeralMessages && lower.contains("mark_ephemeral_item_ranges_viewed") -> "ephemeral_seen"
            state.permanentViewMode && (lower.contains("view_mode") || lower.contains("seen_count")) -> "permanent_view"
            state.doNotSaveRecentSearches && looksLikeRecentSearchPersistenceUrl(lower) -> "recent_search"
            state.isAdBlockEnabled && uri?.let(::isAdOrSponsoredRequest) == true -> "ad"
            state.isAnalyticsBlocked && uri?.let { parsed ->
                val host = lower(parsed.host)
                host.contains("graph.instagram.com") ||
                    host.contains("graph.facebook.com") ||
                    lower(parsed.path).contains("/logging_client_events")
            } == true -> "analytics"
            else -> null
        }
        if (blockReason != null) {
            return "https://i.instagram.com/api/v1/purrfect/blocked/?reason=$blockReason"
        }
        return if (clean != url) clean else null
    }

    private fun dropReasonForNetworkUri(uri: URI): String? {
        val path = lower(uri.path)
        val query = lower(uri.query)
        val host = lower(uri.host)

        if (isInstagramMobileConfigUri(uri)) return null

        noteDirectOutgoingMessageForAutoscroll(uri)
        if (state.markTextsSeenAfterReply && isDirectTextSendRequest(uri)) {
            logInfo("Detected outgoing Direct text/reply while seen-after-reply is enabled: $path")
            markDmSeenAfterReply(currentActivity, currentActivity?.window?.decorView)
        }
        if (state.storyInteractionSendsSeen && isStoryInteractionRequest(uri)) {
            logInfo("Detected story interaction while story-interaction seen is enabled: $path")
            allowStorySeenUntilMs = System.currentTimeMillis() + 30_000L
            markStorySeen(currentActivity, currentActivity?.window?.decorView)
        }

        if (state.isGhostSeen && isDmSeenRequest(uri)) {
            if (consumeSeenAllowance(isStory = false)) return null
            return "dm_seen"
        }
        if (state.keepEphemeralMessages && path.contains("/mark_ephemeral_item_ranges_viewed")) return "ephemeral_seen"
        if (state.isGhostScreenshot && (path.endsWith("/screenshot/") || path.endsWith("/ephemeral_screenshot/"))) return "screenshot"
        if (state.isGhostViewOnce && (path.endsWith("/item_replayed/") || (path.contains("/direct") && path.endsWith("/item_seen/")))) return "view_once"
        if (state.isGhostStory && path.contains("/media/seen/")) {
            if (consumeSeenAllowance(isStory = true)) return null
            return "story_seen"
        }
        if (state.isGhostLive && isLivePresenceRequest(uri)) return "live_presence"
        if (state.hideVoiceMessageSeen && isVoiceSeenRequest(uri)) return "voice_seen"

        if (state.disableStories && (
                path.contains("/feed/reels_tray/") ||
                    path.contains("feed/get_latest_reel_media/") ||
                    path.contains("direct_v2/pending_inbox/?visual_message") ||
                    path.contains("stories/hallpass/") ||
                    path.contains("/api/v1/feed/reels_media_stream/")
            )
        ) return "stories"
        if (state.disableFeed && path.endsWith("/feed/timeline/")) return "feed"
        if (state.disableReels && !state.disableReelsExceptDM && shouldDropDedicatedReelsNetworkRequest(path, query)) return "reels"
        if (state.disableReelsExceptDM && !path.startsWith("/api/v1/direct_v2/") && (
                (path.startsWith("/api/v1/clips/") && isReelsPaginationQuery(query)) ||
                    path.contains("/clips/discover/") ||
                    path.contains("/mixed_media/discover/stream/")
            )
        ) return "reels"
        if (state.disableExplore && (
                path.contains("/discover/topical_explore") ||
                    path.contains("/discover/topical_explore_stream") ||
                    (host.contains("i.instagram.com") && path.contains("/api/v1/fbsearch/top_serp/"))
            )
        ) return "explore"
        if (state.disableComments && path.contains("/api/v1/media/") && path.contains("comments/")) return "comments"
        if (state.isAdBlockEnabled && isAdOrSponsoredRequest(uri)) return "ad"
        if (state.isAnalyticsBlocked && (
                host.contains("graph.instagram.com") ||
                    host.contains("graph.facebook.com") ||
                    path.contains("/logging_client_events")
            )
        ) return "analytics"
        if (state.doNotSaveRecentSearches && isRecentSearchPersistenceRequest(uri)) return "recent_search"
        return null
    }

    private fun shouldDropDedicatedReelsNetworkRequest(path: String, query: String): Boolean {
        if (path.contains("/feed/reels_tray/") ||
            path.contains("feed/get_latest_reel_media/") ||
            path.contains("/api/v1/feed/reels_media_stream/")
        ) {
            return false
        }
        return path.contains("/clips/discover/") ||
            path.contains("/clips/for_you") ||
            path.contains("/clips/feed") ||
            path.contains("/clips/home") ||
            path.contains("/clips/reels_media") ||
            path.contains("/clips/netego_reels_media") ||
            path.contains("/mixed_media/discover/stream/") ||
            (path.startsWith("/api/v1/clips/") && isReelsPaginationQuery(query))
    }

    private fun isReelsPaginationQuery(query: String): Boolean {
        return query.contains("next_media_ids=") ||
            query.contains("max_id=") ||
            query.contains("paging_token=") ||
            query.contains("clips_tab") ||
            query.contains("clips_viewer") ||
            query.contains("reels")
    }

    private fun isInstagramMobileConfigUri(uri: URI): Boolean {
        val path = lower(uri.path)
        val host = lower(uri.host)
        if (!host.contains("instagram.com") && !host.contains("facebook.com")) return false
        return path.contains("/launcher/mobileconfigqeinfo") ||
            path.contains("/launcher/mobileconfig/") ||
            path.contains("/launcher/mobileconfigtaskimport/") ||
            path.contains("/mobileconfigqeinfo/") ||
            path.endsWith("/mobileconfigqeinfo")
    }

    private fun isDmSeenRequest(uri: URI): Boolean {
        val path = lower(uri.path)
        val combined = "$path?${lower(uri.query)}"
        if (!combined.contains("direct")) return false
        return (path.contains("/threads/") && path.contains("/opened")) ||
            combined.contains("mark_thread_seen") ||
            combined.contains("send_thread_seen_marker") ||
            combined.contains("thread_seen_marker") ||
            (combined.contains("thread") && (combined.contains("/seen") || combined.contains("opened")))
    }

    private fun isDirectTextSendRequest(uri: URI): Boolean {
        val path = lower(uri.path)
        val combined = "$path?${lower(uri.query)}"
        if (!combined.contains("direct") && !combined.contains("notes_send_text_response")) return false
        return combined.contains("send_text_message") ||
            combined.contains("broadcast/text") ||
            combined.contains("/text/") ||
            combined.contains("text_message") ||
            combined.contains("reply_text") ||
            combined.contains("send_repost_reply_message") ||
            combined.contains("notes_send_text_response") ||
            combined.contains("send_link_message") ||
            combined.contains("broadcast/link")
    }

    private fun isStoryInteractionRequest(uri: URI): Boolean {
        val path = lower(uri.path)
        val combined = "$path?${lower(uri.query)}"
        val storySurface = combined.contains("story") || combined.contains("reel") || combined.contains("reels_media")
        if (!storySurface) return false
        return combined.contains("story_interaction") ||
            combined.contains("send_story_interaction_reply") ||
            combined.contains("story_like") ||
            combined.contains("reel/react") ||
            combined.contains("reel/reply") ||
            combined.contains("reel_comment") ||
            (path.contains("/media/") && (path.contains("/like") || path.contains("/comment")))
    }

    private fun isLivePresenceRequest(uri: URI): Boolean {
        val path = lower(uri.path)
        val query = lower(uri.query)
        if (!path.contains("/live/")) return false
        return path.contains("/heartbeat_and_get_viewer_count/") ||
            path.contains("/get_viewer_count/") ||
            path.contains("/get_viewer_list/") ||
            path.contains("/viewer_list/") ||
            path.contains("/viewer_presence/") ||
            path.contains("/live_presence/") ||
            path.contains("/broadcast_viewer/") ||
            path.contains("/presence/") ||
            query.contains("live_presence") ||
            query.contains("viewer_presence")
    }

    private fun isVoiceSeenRequest(uri: URI): Boolean {
        val combined = "${lower(uri.path)}?${lower(uri.query)}"
        if (!combined.contains("direct")) return false
        val voice = combined.contains("voice") ||
            combined.contains("audio_clip") ||
            combined.contains("audioclip") ||
            combined.contains("audio_message")
        val seen = combined.contains("seen") ||
            combined.contains("opened") ||
            combined.contains("played") ||
            combined.contains("listened") ||
            combined.contains("playback")
        return voice && seen
    }

    private fun isAdOrSponsoredRequest(uri: URI): Boolean {
        val path = lower(uri.path)
        val query = lower(uri.query)
        if (path.contains("/ads/promote/")) return false
        return path.contains("profile_ads/get_profile_ads/") ||
            path.contains("/async_ads/") ||
            path.contains("async_ads") ||
            path.contains("/feed/injected_reels_media/") ||
            path.contains("injected_story") ||
            path.contains("prefetched_ads") ||
            path.contains("/api/v1/ads/") ||
            path == "/api/v1/ads/graphql/" ||
            path.contains("/sponsored/") ||
            query.contains("is_sponsored=true") ||
            query.contains("is_ad=true") ||
            query.contains("sponsored_label")
    }

    private fun isRecentSearchPersistenceRequest(uri: URI): Boolean {
        val combined = "${lower(uri.path)}?${lower(uri.query)}"
        if (combined.contains("clear_recent_searches") ||
            combined.contains("remove_recent_search") ||
            combined.contains("delete_recent_search")
        ) return false
        return looksLikeRecentSearchPersistenceUrl(combined)
    }

    private fun looksLikeRecentSearchPersistenceUrl(combined: String): Boolean {
        if (combined.contains("clear_recent_searches") ||
            combined.contains("remove_recent_search") ||
            combined.contains("delete_recent_search")
        ) return false
        return combined.contains("register_recent_search") ||
            combined.contains("recent_search_click") ||
            combined.contains("save_recent_search") ||
            combined.contains("recent_search") ||
            combined.contains("recent_searches/register") ||
            combined.contains("map/register_recent_search") ||
            combined.contains("fbsearch/register_recent_search") ||
            combined.contains("fbsearch/search_register") ||
            combined.contains("fbsearch") && combined.contains("register") && combined.contains("search") ||
            combined.contains("search") && combined.contains("click") && combined.contains("entity") ||
            combined.contains("typeahead") && (combined.contains("click") || combined.contains("register")) ||
            combined.contains("keyword_search") && combined.contains("register") ||
            combined.contains("search_history") && (combined.contains("save") || combined.contains("register") || combined.contains("mutation")) ||
            (combined.contains("search") && combined.contains("mutation") && combined.contains("recent"))
    }

    private fun consumeSeenAllowance(isStory: Boolean): Boolean {
        val now = System.currentTimeMillis()
        val until = if (isStory) allowStorySeenUntilMs else allowDmSeenUntilMs
        if (until <= now) {
            if (isStory) allowStorySeenUntilMs = 0L else allowDmSeenUntilMs = 0L
            return false
        }
        logInfo("Allowing manual ${if (isStory) "story" else "DM"} seen request")
        return true
    }

    private fun markDmSeenAfterReply(vararg roots: Any?): Boolean {
        allowManualDmSeen.set(true)
        return try {
            replayBlockedDmSeenMethod() ||
                replayBlockedNetworkRequest(lastBlockedDmSeenNetworkRequest, isStory = false) ||
                run {
                    allowDmSeenUntilMs = System.currentTimeMillis() + 30_000L
                    true
                }
        } finally {
            allowManualDmSeen.remove()
        }
    }

    private fun recordBlockedDmSeenNetworkRequest(
        service: Any?,
        method: Method,
        args: Array<Any?>?,
        requestObj: Any?,
        uriFieldName: String?,
        originalUri: URI?
    ) {
        if (service == null || requestObj == null || uriFieldName.isNullOrBlank() || originalUri == null) return
        lastBlockedDmSeenNetworkRequest = BlockedSeenNetworkRequest(
            service,
            method,
            args?.copyOf() ?: emptyArray(),
            requestObj,
            uriFieldName,
            originalUri,
            System.currentTimeMillis()
        )
    }

    private fun recordBlockedStorySeenNetworkRequest(
        service: Any?,
        method: Method,
        args: Array<Any?>?,
        requestObj: Any?,
        uriFieldName: String?,
        originalUri: URI?
    ) {
        if (service == null || requestObj == null || uriFieldName.isNullOrBlank() || originalUri == null) return
        lastBlockedStorySeenNetworkRequest = BlockedSeenNetworkRequest(
            service,
            method,
            args?.copyOf() ?: emptyArray(),
            requestObj,
            uriFieldName,
            originalUri,
            System.currentTimeMillis()
        )
    }

    private fun replayBlockedDmSeenMethod(): Boolean {
        val call = lastBlockedDmSeenMethodCall ?: return false
        if (System.currentTimeMillis() - call.atMs > 180_000L) return false
        return runCatching {
            allowDmSeenUntilMs = System.currentTimeMillis() + 30_000L
            XposedBridge.invokeOriginalMethod(call.method, call.owner, call.args)
            true
        }.getOrElse {
            logError("Failed replaying blocked DM seen method", it)
            false
        }
    }

    private fun replayBlockedNetworkRequest(request: BlockedSeenNetworkRequest?, isStory: Boolean): Boolean {
        val req = request ?: return false
        if (System.currentTimeMillis() - req.atMs > 180_000L) return false
        return runCatching {
            setUriField(req.requestObj, req.uriFieldName, req.originalUri)
            if (isStory) allowStorySeenUntilMs = System.currentTimeMillis() + 30_000L else allowDmSeenUntilMs = System.currentTimeMillis() + 30_000L
            XposedBridge.invokeOriginalMethod(req.method, req.service, req.args)
            true
        }.getOrElse {
            logError("Failed replaying blocked ${if (isStory) "story" else "DM"} seen request", it)
            false
        }
    }

    private fun setUriField(requestObj: Any, uriFieldName: String, uri: URI) {
        var cls: Class<*>? = requestObj.javaClass
        while (cls != null && cls != Any::class.java) {
            val field = runCatching { cls.getDeclaredField(uriFieldName) }.getOrNull()
            if (field != null) {
                field.isAccessible = true
                field.set(requestObj, uri)
                return
            }
            cls = cls.superclass
        }
        throw NoSuchFieldException(uriFieldName)
    }

    private fun markStorySeen(vararg roots: Any?): Boolean {
        if (storySeenMethods.isEmpty() && storySeenBuilderMethods.isEmpty() && lastBlockedStorySeenNetworkRequest == null) {
            return false
        }
        allowManualStorySeen.set(true)
        return try {
            val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
            val cachedOwner = lastBlockedStorySeenOwner?.get()
            invokeStorySeenInGraph(cachedOwner, visited, 0) ||
                roots.any { invokeStorySeenInGraph(it, visited, 0) } ||
                replayBlockedNetworkRequest(lastBlockedStorySeenNetworkRequest, isStory = true) ||
                invokeStorySeenBuilder() ||
                run {
                    allowStorySeenUntilMs = System.currentTimeMillis() + 30_000L
                    true
                }
        } finally {
            allowManualStorySeen.remove()
        }
    }

    private fun invokeStorySeenBuilder(): Boolean {
        val owner = lastSeenStoryBuilderOwner?.get() ?: return false
        val args = lastSeenStoryBuilderArgs ?: return false
        storySeenBuilderMethods.forEach { method ->
            if (!method.declaringClass.isAssignableFrom(owner.javaClass)) return@forEach
            if (method.parameterTypes.size != args.size) return@forEach
            val ok = runCatching {
                allowStorySeenUntilMs = System.currentTimeMillis() + 30_000L
                method.invoke(owner, *args)
                true
            }.getOrDefault(false)
            if (ok) return true
        }
        return false
    }

    private fun invokeStorySeenInGraph(value: Any?, visited: MutableSet<Any>, depth: Int): Boolean {
        if (value == null || depth > 8) return false
        if (value is Array<*>) return value.any { invokeStorySeenInGraph(it, visited, depth + 1) }
        val cls = value.javaClass
        if (cls.isArray) {
            val count = java.lang.reflect.Array.getLength(value).coerceAtMost(20)
            for (index in 0 until count) {
                if (invokeStorySeenInGraph(java.lang.reflect.Array.get(value, index), visited, depth + 1)) return true
            }
            return false
        }
        if (isSimpleOrFramework(cls) || !visited.add(value)) return false

        storySeenMethods.forEach { method ->
            if (method.declaringClass.isAssignableFrom(cls)) {
                val ok = runCatching {
                    allowStorySeenUntilMs = System.currentTimeMillis() + 30_000L
                    method.invoke(value)
                    true
                }.getOrDefault(false)
                if (ok) return true
            }
        }

        if (value is Collection<*>) {
            value.take(25).forEach { if (invokeStorySeenInGraph(it, visited, depth + 1)) return true }
            return false
        }
        if (!shouldInspectObject(cls)) return false
        var current: Class<*>? = cls
        var fields = 0
        while (current != null && current != Any::class.java && fields < 80) {
            current.declaredFields.forEach { field ->
                if (fields++ >= 80) return@forEach
                runCatching {
                    field.isAccessible = true
                    if (invokeStorySeenInGraph(field.get(value), visited, depth + 1)) return true
                }
            }
            current = current.superclass
        }
        return false
    }

    private fun isSimpleOrFramework(cls: Class<*>): Boolean {
        return cls.isPrimitive ||
            cls == String::class.java ||
            Number::class.java.isAssignableFrom(cls) ||
            cls == java.lang.Boolean::class.java ||
            cls == java.lang.Character::class.java ||
            Enum::class.java.isAssignableFrom(cls) ||
            cls.name.startsWith("android.view.") ||
            cls.name.startsWith("android.widget.") ||
            cls.name.startsWith("android.content.") ||
            cls.name.startsWith("java.lang.reflect.")
    }

    private fun handleFollowStatusRequest(uri: URI, args: Array<Any?>?) {
        val request = uri.toString()
        val path = uri.path.orEmpty()
        val isFriendshipShow = path.contains("/friendships/show")
        if (!isFriendshipShow) return
        val userId = extractFollowStatusUserId(uri)
            ?: currentProfileUsername?.takeIf { it.isNotBlank() }
            ?: return
        currentFollowStatusUserId = userId
        if (pendingFollowCallbacks.size > 64) pendingFollowCallbacks.clear()
        listOfNotNull(args?.getOrNull(1), args?.getOrNull(2)).forEach { arg ->
            if (!isSimpleOrFramework(arg.javaClass)) registerFollowStatusCallback(arg, userId)
        }
    }

    private fun mightBeFollowStatusRequest(uri: URI): Boolean {
        val path = uri.path.orEmpty()
        return path.contains("/friendships/show")
    }

    private fun extractFollowStatusUserId(uri: URI): String? {
        uri.path.orEmpty()
            .split('/')
            .lastOrNull { it.isNotBlank() && it.all(Char::isDigit) }
            ?.let { return it }
        val query = uri.rawQuery.orEmpty()
        listOf("user_id", "target_user_id", "recipient_id", "id").forEach { key ->
            Regex("(?:^|&)$key=(\\d+)(?:&|$)").find(query)?.groupValues?.getOrNull(1)?.let { return it }
        }
        return null
    }

    private fun registerFollowStatusCallback(callback: Any, userId: String) {
        pendingFollowCallbacks[System.identityHashCode(callback)] = userId
        val className = callback.javaClass.name
        if (!hookedFollowCallbackClasses.add(className)) return
        logInfo("Hooking follow-status callback class=$className")
        callback.javaClass.declaredMethods
            .filter { !Modifier.isStatic(it.modifiers) && it.parameterTypes.isNotEmpty() }
            .forEach { method ->
                runCatching {
                    method.isAccessible = true
                    XposedBridge.hookMethod(
                        method,
                        object : XC_MethodHook() {
                            override fun afterHookedMethod(param: MethodHookParam<*>) {
                                if (!state.showFollowerToast) return
                                val hash = System.identityHashCode(param.thisObject)
                                val pendingUserId = pendingFollowCallbacks[hash] ?: return
                                param.args.forEach { arg ->
                                    parseFollowedBy(arg)?.let { followedBy ->
                                        pendingFollowCallbacks.remove(hash)
                                        showFollowStatusToast(pendingUserId, followedBy)
                                        return
                                    }
                                }
                                parseFollowedBy(param.thisObject)?.let { followedBy ->
                                    pendingFollowCallbacks.remove(hash)
                                    showFollowStatusToast(pendingUserId, followedBy)
                                }
                            }
                        }
                    )
                }
            }
    }

    private fun parseFollowedBy(value: Any?): Boolean? {
        val body = toJsonString(value, 3)?.takeIf { it.contains("\"followed_by\"") } ?: return null
        return runCatching { org.json.JSONObject(body).optBoolean("followed_by", false) }
            .getOrElse { body.contains("\"followed_by\":true") || body.contains("\"followed_by\": true") }
    }

    private val toJsonStringCache = Collections.synchronizedMap(object : LinkedHashMap<String, String?>(64, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, String?>?): Boolean = size > 64
    })

    private fun toJsonString(value: Any?, depth: Int): String? {
        if (value == null || depth < 0) return null
        when (value) {
            is String -> return value.takeIf { it.contains("followed_by") }
            is ByteArray -> return runCatching { String(value, Charsets.UTF_8) }.getOrNull()?.takeIf { it.contains("followed_by") }
            is java.nio.ByteBuffer -> {
                return runCatching {
                    val duplicate = value.duplicate()
                    val bytes = ByteArray(duplicate.remaining())
                    duplicate.get(bytes)
                    String(bytes, Charsets.UTF_8)
                }.getOrNull()?.takeIf { it.contains("followed_by") }
            }
        }
        if (depth == 0) return null
        val cacheKey = "${System.identityHashCode(value)}@${value.javaClass.name}"
        toJsonStringCache[cacheKey]?.let { return it }
        var cls: Class<*>? = value.javaClass
        var visited = 0
        while (cls != null && cls != Any::class.java && visited < 40) {
            cls.declaredFields.forEach { field ->
                if (visited++ >= 40 || Modifier.isStatic(field.modifiers) || field.type.isPrimitive) return@forEach
                runCatching {
                    field.isAccessible = true
                    val nested = field.get(value)
                    if (nested !== value && nested !is Number) toJsonString(nested, depth - 1) else null
                }.getOrNull()?.takeIf { it.contains("followed_by") }?.let { result ->
                    toJsonStringCache[cacheKey] = result
                    return result
                }
            }
            cls = cls.superclass
        }
        toJsonStringCache[cacheKey] = null
        return null
    }

    private fun rememberFollowDisplayName(user: Any?, username: String?) {
        if (user == null) return
        val userId = extractUserPk(user) ?: return
        val fullName = extractFullNameFromUser(user)
        val displayName = fullName?.takeIf { it.isNotBlank() }
            ?: username?.takeIf { it.isNotBlank() }?.let { "@$it" }
            ?: return
        followDisplayNames[userId] = displayName
        if (followDisplayNames.size > 200) {
            val excess = followDisplayNames.keys.take(followDisplayNames.size - 100)
            excess.forEach { followDisplayNames.remove(it) }
        }
    }

    private fun extractUserPk(user: Any?): String? {
        if (user == null) return null
        arrayOf("getId", "id", "getPk", "pk").forEach { methodName ->
            invokeNoArgDeep(user, methodName)?.toString()?.takeIf { it.all(Char::isDigit) && it.isNotBlank() }?.let { return it }
        }
        val dict = userDict(user)
        if (dict != null) {
            arrayOf("getId", "id", "getPk", "pk").forEach { methodName ->
                invokeNoArgDeep(dict, methodName)?.toString()?.takeIf { it.all(Char::isDigit) && it.isNotBlank() }?.let { return it }
            }
        }
        var cls: Class<*>? = user.javaClass
        var checked = 0
        while (cls != null && cls != Any::class.java && checked < 20) {
            cls.declaredFields.forEach { field ->
                if (checked++ >= 20 || Modifier.isStatic(field.modifiers)) return@forEach
                if (field.type == java.lang.Long.TYPE || field.type == java.lang.Long::class.java || field.type == String::class.java) {
                    val name = field.name.lowercase(Locale.US)
                    if (name.contains("pk") || name.contains("userid") || name.contains("user_id")) {
                        runCatching {
                            field.isAccessible = true
                            val value = field.get(user)?.toString()
                            if (!value.isNullOrBlank() && value.all(Char::isDigit) && value.length >= 3) return value
                        }
                    }
                }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun extractFullNameFromUser(user: Any?): String? {
        if (user == null) return null
        invokeStringNoArg(user, "getFullName")?.takeIf { it.isNotBlank() }?.let { return it }
        val dict = userDict(user)
        if (dict != null) {
            invokeStringNoArg(dict, "getFullName")?.takeIf { it.isNotBlank() }?.let { return it }
        }
        return null
    }

    private fun extractFollowedByFromFriendshipStatus(status: Any?): Boolean? {
        if (status == null) return null
        // Try known method names first
        runCatching { status.javaClass.getMethod("isFollowedBy").invoke(status) as? Boolean }?.getOrNull()?.let { return it }
        // Try getMappings approach (like Piko)
        var cls: Class<*>? = status.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (Modifier.isStatic(field.modifiers)) return@forEach
                val name = field.name.lowercase(Locale.US)
                if (field.type == java.lang.Boolean.TYPE || field.type == java.lang.Boolean::class.java) {
                    if (name.contains("followed_by") || name.contains("followedby") || name.contains("is_followed")) {
                        runCatching {
                            field.isAccessible = true
                            return field.getBoolean(status)
                        }
                    }
                }
            }
            cls = cls.superclass
        }
        // Try converting to map
        cls = status.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredMethods.forEach { method ->
                if (method.parameterTypes.isEmpty() && Map::class.java.isAssignableFrom(method.returnType)) {
                    runCatching {
                        method.isAccessible = true
                        @Suppress("UNCHECKED_CAST")
                        val map = method.invoke(status) as? Map<String, Any?>
                        map?.get("followed_by")?.let { value ->
                            return when (value) {
                                is Boolean -> value
                                is String -> value.equals("true", ignoreCase = true)
                                else -> null
                            }
                        }
                    }
                }
            }
            cls = cls.superclass
        }
        // Last resort: scan all boolean fields, pick one that looks relevant based on field index position
        status.javaClass.declaredFields
            .filter { !Modifier.isStatic(it.modifiers) && (it.type == java.lang.Boolean.TYPE || it.type == java.lang.Boolean::class.java) }
            .firstOrNull()?.let { field ->
                runCatching {
                    field.isAccessible = true
                    return field.getBoolean(status)
                }
            }
        return null
    }

    private fun showFollowStatusToast(userId: String, followedBy: Boolean, displayName: String? = null) {
        mainHandler.post {
            val now = System.currentTimeMillis()
            if (userId == lastFollowToastUserId && now - lastFollowToastAtMs < 3000L) return@post
            if (currentFollowStatusUserId != null && currentFollowStatusUserId != userId && displayName == null) return@post
            lastFollowToastUserId = userId
            lastFollowToastAtMs = now
            val name = displayName
                ?: followDisplayNames[userId]
                ?: currentProfileUsername?.takeIf { it.isNotBlank() }?.let { "@$it" }
                ?: userId
            val message = if (followedBy) "$name follows you" else "$name isn't following you"
            Toast.makeText(androidContext, message, Toast.LENGTH_SHORT).show()
            currentFollowStatusUserId = null
        }
    }

    private fun requestUrl(request: Any): String? {
        val cls = request.javaClass
        val method = requestUrlMethodCache[cls] ?: run {
            if (requestUrlMethodMissing.contains(cls)) return null
            val found = cls.methods.firstOrNull { it.name == "url" && it.parameterTypes.isEmpty() }
                ?: cls.methods.firstOrNull { it.name == "getUrl" && it.parameterTypes.isEmpty() }
            if (found == null) {
                requestUrlMethodMissing.add(cls)
                return null
            }
            found.isAccessible = true
            requestUrlMethodCache[cls] = found
            found
        }
        return method.invoke(request)?.toString()
    }

    private fun buildRequestWithUrl(request: Any, url: String): Any? {
        return runCatching {
            val builder = request.javaClass.getMethod("newBuilder").invoke(request)
            val urlMethod = builder.javaClass.methods.firstOrNull {
                it.name == "url" && it.parameterTypes.size == 1 && it.parameterTypes[0] == String::class.java
            } ?: return@runCatching null
            urlMethod.invoke(builder, url)
            builder.javaClass.getMethod("build").invoke(builder)
        }.getOrNull()
    }

    private fun rememberMediaUrl(url: String, directFallback: Boolean = false) {
        if (!looksLikeMediaUrl(url)) return
        val now = System.currentTimeMillis()
        val rememberGeneric = !directFallback && shouldRememberGenericMediaUrlNow()
        if (!rememberGeneric) {
            rememberMediaUrlSideCaches(url, now, directFallback)
            return
        }
        if (now - (recentMediaUrlLastSeen[url] ?: 0L) in 0..750L) {
            mediaUrlDuplicateSkips++
            mediaUrlFastDuplicateSkips++
            rememberMediaUrlSideCaches(url, now, directFallback)
            maybeLogMediaUrlCaptureStats(now)
            return
        }
        var duplicateRecent = false
        synchronized(recentMediaUrlEvents) {
            duplicateRecent = now - (recentMediaUrlLastSeen[url] ?: 0L) in 0..750L
            if (!duplicateRecent) {
                recentMediaUrlLastSeen[url] = now
                recentMediaUrlEvents.addFirst(RecentMediaUrl(url, now))
                val cutoff = now - 90_000L
                while (recentMediaUrlEvents.size > 120) {
                    val removed = recentMediaUrlEvents.removeLast()
                    if (recentMediaUrlLastSeen[removed.url] == removed.timeMs) recentMediaUrlLastSeen.remove(removed.url)
                }
                while (recentMediaUrlEvents.isNotEmpty() && recentMediaUrlEvents.peekLast().timeMs < cutoff) {
                    val removed = recentMediaUrlEvents.removeLast()
                    if (recentMediaUrlLastSeen[removed.url] == removed.timeMs) recentMediaUrlLastSeen.remove(removed.url)
                }
                if (recentMediaUrlLastSeen.size > 180) {
                    val keep = recentMediaUrlEvents.mapTo(HashSet()) { it.url }
                    recentMediaUrlLastSeen.entries.removeIf { it.key !in keep }
                }
            }
        }
        if (duplicateRecent) {
            mediaUrlDuplicateSkips++
        } else {
            mediaUrlGenericRemembers++
            synchronized(recentMediaUrls) {
                recentMediaUrls.remove(url)
                recentMediaUrls.add(url)
                while (recentMediaUrls.size > 60) recentMediaUrls.removeAt(0)
            }
        }
        rememberMediaUrlSideCaches(url, now, directFallback)
        maybeLogMediaUrlCaptureStats(now)
    }

    private fun rememberMediaUrlSideCaches(url: String, now: Long, directFallback: Boolean) {
        if (now - lastInstantViewerSeenAtMs in 0L..12_000L) {
            rememberInstantViewerMediaUrl(url, now)
        }
        if (directFallback && shouldRememberDmMediaFallback()) {
            mediaUrlDmFallbackRemembers++
            synchronized(dmRecentUrls) {
                dmRecentUrls.removeAll { it.url == url }
                dmRecentUrls.addFirst(RecentMediaUrl(url, now))
                pruneDmRecentUrls()
            }
        }
    }

    private fun pruneDmRecentUrls() {
        val cutoff = System.currentTimeMillis() - 90_000L
        while (dmRecentUrls.size > 60) dmRecentUrls.removeLast()
        while (dmRecentUrls.isNotEmpty() && dmRecentUrls.peekLast().timeMs < cutoff) dmRecentUrls.removeLast()
    }

    private fun shouldRememberDmMediaFallback(): Boolean {
        return state.enableDmContextMenuOptions && hasCachedDirectTouchSurface()
    }

    private fun shouldRememberGenericMediaUrlNow(): Boolean {
        if (!ENABLE_GENERIC_MEDIA_URL_CAPTURE) return false
        val current = state
        if (!current.enablePostDownload &&
            !current.enableStoryDownload &&
            !current.enableReelDownload &&
            !current.enableReelThumbnailDownload
        ) {
            return false
        }
        val now = SystemClock.uptimeMillis()
        if (shouldDeferGenericMediaCaptureForScroll(now)) {
            noteGenericMediaCaptureSkippedForScroll()
            return false
        }
        return true
    }

    private fun maybeRememberGenericMediaUrl(url: String) {
        if (shouldBypassGenericMediaCaptureForScroll()) return
        if (!maybeLooksLikeMediaUrlFast(url)) return
        if (!shouldRememberGenericMediaUrlNow()) return
        rememberMediaUrl(url)
    }

    private fun shouldBypassGenericMediaCaptureForScroll(view: View? = null): Boolean {
        if (!shouldDeferGenericMediaCaptureForScroll(SystemClock.uptimeMillis())) return false
        if (dmDirectSurfaceActive || dmOverlayRootActive) return false
        if (view != null && hasCachedDirectTouchSurface() && hasLocalDirectTouchHint(view)) return false
        noteGenericMediaCaptureSkippedForScroll()
        return true
    }

    private fun noteGenericMediaCaptureSkippedForScroll() {
        if (mediaUrlInputBusySkips < 1_000_000) mediaUrlInputBusySkips++
    }

    private fun shouldRememberIgImageDmFallback(view: View): Boolean {
        if (!state.enableDmContextMenuOptions) return false
        if (dmDirectSurfaceActive || dmOverlayRootActive) return true
        if (!hasCachedDirectTouchSurface()) return false
        if (!hasLocalDirectTouchHint(view)) return false
        val ownName = resourceEntryName(view).orEmpty().lowercase(Locale.US)
        val ownClass = view.javaClass.name.lowercase(Locale.US)
        val maybeDirectView = ownName.contains("direct") ||
            ownName.contains("message") ||
            ownClass.contains("directthread") ||
            ownClass.contains(".messagethread.")
        return maybeDirectView && isLikelyDirectTouchPath(view)
    }

    private fun maybeLogMediaUrlCaptureStats(now: Long) {
        if (now - mediaUrlStatsLastLogAtMs < 8_000L) return
        mediaUrlStatsLastLogAtMs = now
        val genericSize = synchronized(recentMediaUrlEvents) { recentMediaUrlEvents.size }
        val directSize = synchronized(dmRecentUrls) { dmRecentUrls.size }
        val instantSize = synchronized(instantViewerRecentUrls) { instantViewerRecentUrls.size }
        logInfo(
            "Media URL cache stats generic=$genericSize direct=$directSize instant=$instantSize " +
                "adds=$mediaUrlGenericRemembers directAdds=$mediaUrlDmFallbackRemembers dupSkips=$mediaUrlDuplicateSkips " +
                "fastDupSkips=$mediaUrlFastDuplicateSkips inputBusySkips=$mediaUrlInputBusySkips " +
                "directRuntime=${hasCachedDirectTouchSurface()}"
        )
    }

    private fun looksLikeMediaUrl(url: String): Boolean {
        if (!url.trimStart().startsWith("http", ignoreCase = true)) return false
        val lower = url.lowercase()
        return lower.contains(".cdninstagram.com") ||
            lower.contains(".fbcdn.net") ||
            lower.contains(".fbsbx.com") ||
            lower.contains("scontent") ||
            lower.contains(".mp4") ||
            lower.contains(".m4a") ||
            lower.contains(".aac") ||
            lower.contains(".opus") ||
            lower.contains("googlevideo.com") ||
            lower.contains(".mp3") ||
            lower.contains(".jpg") ||
            lower.contains(".jpeg") ||
            lower.contains(".webp") ||
            lower.contains(".png")
    }

    private fun maybeLooksLikeMediaUrlFast(url: String): Boolean {
        if (url.length < 12 || !url.startsWith("http")) return false
        return url.indexOf("cdninstagram", ignoreCase = true) >= 0 ||
            url.indexOf("fbcdn", ignoreCase = true) >= 0 ||
            url.indexOf("scontent", ignoreCase = true) >= 0 ||
            url.indexOf(".mp4", ignoreCase = true) >= 0 ||
            url.indexOf(".m4a", ignoreCase = true) >= 0 ||
            url.indexOf(".jpg", ignoreCase = true) >= 0 ||
            url.indexOf(".jpeg", ignoreCase = true) >= 0 ||
            url.indexOf(".webp", ignoreCase = true) >= 0
    }

    private fun imageUrlFromObjectFast(value: Any?): String? {
        return when (value) {
            is String -> value.takeIf { it.startsWith("http") }
            is Uri -> value.toString().takeIf { it.startsWith("http") }
            else -> {
                val className = value?.javaClass?.name ?: return null
                if (className.indexOf("url", ignoreCase = true) < 0 &&
                    className.indexOf("uri", ignoreCase = true) < 0
                ) {
                    return null
                }
                value.toString().takeIf { it.startsWith("http") }
            }
        }
    }

    private fun isHttpImageUrl(url: String?): Boolean {
        val lower = url?.lowercase(Locale.US) ?: return false
        if (!lower.startsWith("http://") && !lower.startsWith("https://")) return false
        return lower.contains("cdninstagram.com") ||
            lower.contains("fbcdn.net") ||
            lower.contains("scontent") ||
            lower.contains(".jpg") ||
            lower.contains(".jpeg") ||
            lower.contains(".png") ||
            lower.contains(".webp")
    }

    private fun looksLikeProfileImageUrl(url: String?): Boolean {
        val lower = url?.lowercase(Locale.US) ?: return false
        return (lower.contains("/t51.") && lower.contains("-19/")) ||
            (lower.contains("t51.") && lower.contains("-19")) ||
            lower.matches(Regex(".*t51\\.[0-9]+-19.*")) ||
            (lower.contains("/v/t51.") && lower.contains("-19")) ||
            lower.contains("profile_pic") ||
            lower.contains("profilepic") ||
            lower.contains("profilepicture") ||
            lower.contains("profile_picture") ||
            lower.contains("profile_photo") ||
            lower.contains("profilephoto") ||
            lower.contains("avatar") ||
            lower.contains("profile%5fpic") ||
            lower.contains("profile%2f") ||
            lower.contains("/profile/") ||
            (lower.contains("ig_cache_key") && lower.contains("profile")) ||
            lower.contains("s150x150") ||
            lower.contains("s320x320")
    }

    private fun imageUrlFromObject(value: Any?): String? {
        if (value == null) return null
        if (value is String && value.startsWith("http")) return value
        if (value is Uri && value.toString().startsWith("http")) return value.toString()
        val valueClassName = value.javaClass.name.lowercase(Locale.US)
        if (valueClassName.contains("url") || valueClassName.contains("uri")) {
            value.toString().takeIf { it.startsWith("http") }?.let { return it }
        }
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        fun scan(obj: Any?, depth: Int): String? {
            if (obj == null || depth > 2 || !visited.add(obj)) return null
            when (obj) {
                is String -> return obj.takeIf { it.startsWith("http") }
                is Uri -> return obj.toString().takeIf { it.startsWith("http") }
            }
            val cls = obj.javaClass
            if (!shouldInspectImageUrlObject(cls)) return null
            imageUrlGetterMethods(cls).forEach { method ->
                    runCatching {
                        scan(method.invoke(obj), depth + 1)
                    }.getOrNull()?.let { return it }
            }
            imageUrlFields(cls).forEach { field ->
                    runCatching {
                        scan(field.get(obj), depth + 1)
                    }.getOrNull()?.let { return it }
            }
            return null
        }
        return scan(value, 0)
    }

    private fun shouldInspectImageUrlObject(cls: Class<*>): Boolean {
        val name = cls.name
        if (name.startsWith("android.view.") || name.startsWith("android.widget.") || name.startsWith("android.content.")) return false
        if (name.startsWith("java.") || name.startsWith("kotlin.")) return false
        return name.startsWith("com.instagram.") ||
            name.startsWith("p000X.") ||
            name.startsWith("X.") ||
            name.contains("Url") ||
            name.contains("Uri")
    }

    private fun imageUrlGetterMethods(cls: Class<*>): List<Method> {
        return imageUrlMethodCache.getOrPut(cls) {
            cls.declaredMethods
                .asSequence()
                .filter { method ->
                    method.parameterTypes.isEmpty() &&
                        !Modifier.isStatic(method.modifiers) &&
                        (method.returnType == String::class.java || method.returnType == Uri::class.java)
                }
                .take(24)
                .onEach { method -> runCatching { method.isAccessible = true } }
                .toList()
        }
    }

    private fun imageUrlFields(cls: Class<*>): List<Field> {
        return imageUrlFieldCache.getOrPut(cls) {
            cls.declaredFields
                .asSequence()
                .filter { field ->
                    !Modifier.isStatic(field.modifiers) &&
                        (field.type == String::class.java ||
                            field.type == Uri::class.java ||
                            shouldInspectImageUrlObject(field.type))
                }
                .take(48)
                .onEach { field -> runCatching { field.isAccessible = true } }
                .toList()
        }
    }

    private fun resolveMediaOptionDownloadIcon(context: Context): Int {
        return runCatching {
            val optionClass = Class.forName("com.instagram.feed.media.mediaoption.MediaOption\$Option", false, context.classLoader)
            optionClass.enumConstants
                ?.firstOrNull { it.toString().contains("DOWNLOAD") }
                ?.let { option ->
                    option.javaClass.getField("iconDrawable").get(option) as? Int
                }
        }.getOrNull() ?: 0
    }

    private fun handleReelDownloadClick(activity: Activity, media: Any, controller: Any) {
        if (!shouldOfferDownloadContextMenu()) {
            logDownloadControlGate("reel_menu_click", "suppressed")
            return
        }
        logDownloadControlGate("reel_menu_click", "accepted")
        if (state.enableReelDownload) {
            AlertDialog.Builder(activity)
                .setTitle("Download")
                .setItems(arrayOf("Reel video", "Thumbnail")) { _, which ->
                    if (which == 0) startReelVideoDownload(activity, media, controller)
                    else startReelThumbnailDownload(activity, media)
                }
                .show()
            return
        }
        if (state.enableReelThumbnailDownload) startReelThumbnailDownload(activity, media)
    }

    private fun startReelVideoDownload(context: Context, media: Any, controller: Any) {
        val metadata = downloadContextFrom(media, "reel")
        bestMediaVideoUrl(media)?.let {
            enqueueDownload(it, metadata)
            return
        }

        val urls = extractAllMediaDownloadUrls(context, media)
        if (urls.isEmpty()) {
            Toast.makeText(context, "No reel media found", Toast.LENGTH_SHORT).show()
            return
        }
        val viewIndex = findCarouselIndexFromView(context, urls.size)
        val controllerIndex = findReelControllerCarouselIndex(controller, urls.size)
        showPostDownloadChoices(context, urls, metadata, if (viewIndex >= 0) viewIndex else controllerIndex)
    }

    private fun startReelThumbnailDownload(context: Context, media: Any) {
        val url = bestReelThumbnailUrl(media)
        if (url == null) {
            Toast.makeText(context, "Reel thumbnail URL not found", Toast.LENGTH_SHORT).show()
            return
        }
        enqueueDownload(url, downloadContextFrom(media, "reel_thumbnail"))
    }

    private fun bestReelThumbnailUrl(media: Any): String? {
        val reflected = collectDmMediaObjectUrlCandidates(media)
            .filter { !it.video && !it.audio && !isVideoMediaUrl(it.url) && !isAudioUrl(it.url) && !isLikelyAudioHttpUrl(it.url) }
            .map { it.url }
        val urls = (collectCdnUrls(media) + reflected).distinct()
        return urls
            .filterNot(::isVideoMediaUrl)
            .filterNot(::looksLikeProfileImageUrl)
            .maxWithOrNull(compareBy<String> { parseCdnArea(it) }.thenBy { it.length })
            ?: urls.firstOrNull { !isVideoMediaUrl(it) && !looksLikeProfileImageUrl(it) }
    }

    private fun extractAllMediaDownloadUrls(context: Context, media: Any): List<String> {
        initMediaDownloadReflection()
        extractCarouselMediaDownloadUrls(context, media).takeIf { it.size >= 2 }?.let {
            logInfoThrottled("download:carousel:${media.javaClass.name}:${it.size}", 1_500L) {
                "Detected carousel download media class=${media.javaClass.name} count=${it.size} types=${dmUrlTypesForLog(it)}"
            }
            rememberDmMediaAssetGroup(it, "extract-carousel:${media.javaClass.name.substringAfterLast('.')}")
            return it
        }
        val reflectedUrls = collectDmMediaObjectDownloadUrls(media)
        if (looksLikeReelMediaObject(media)) {
            val video = reflectedUrls.firstOrNull(::isVideoMediaUrl) ?: bestMediaVideoUrl(media)
            val reelUrls = if (video != null) {
                listOf(video)
            } else {
                val thumbnail = reflectedUrls
                    .filter { !isVideoMediaUrl(it) && !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                    .maxWithOrNull(compareBy<String> { parseCdnArea(it) }.thenBy { it.length })
                    ?: bestReelThumbnailUrl(media)
                listOfNotNull(thumbnail)
            }
                .filterNot(::looksLikeProfileImageUrl)
                .distinct()
            if (reelUrls.isNotEmpty()) {
                logInfoThrottled("download:reel-assets:${media.javaClass.name}:${reelUrls.size}", 1_500L) {
                    "Detected reel download media class=${media.javaClass.name} count=${reelUrls.size} types=${dmUrlTypesForLog(reelUrls)}"
                }
                rememberDmMediaAssetGroup(reelUrls, "extract-reel:${media.javaClass.name.substringAfterLast('.')}")
                return reelUrls
            }
        }
        if (looksLikeCarouselMediaObject(media)) {
            val carouselFallback = reflectedUrls
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .distinctBy(::dmUrlIdentityForChoice)
            if (carouselFallback.size >= 2) {
                logInfoThrottled("download:carousel-reflected:${media.javaClass.name}:${carouselFallback.size}", 1_500L) {
                    "Detected reflected carousel media class=${media.javaClass.name} count=${carouselFallback.size} types=${dmUrlTypesForLog(carouselFallback)}"
                }
                rememberDmMediaAssetGroup(carouselFallback, "extract-carousel-reflected:${media.javaClass.name.substringAfterLast('.')}")
                return carouselFallback
            }
        }
        bestMediaVideoUrl(media)?.let { return listOf(it) }

        imageUrlFromMedia(context, media)?.let { return listOf(it) }
        reflectedUrls.takeIf { it.isNotEmpty() }?.let { return it }
        val fallback = collectCdnUrls(media).distinct()
        return when {
            fallback.isEmpty() -> emptyList()
            fallback.any(::isVideoMediaUrl) -> listOf(fallback.first(::isVideoMediaUrl))
            else -> listOf(pickBestImageMediaUrl(fallback) ?: fallback.first())
        }
    }

    private fun extractCarouselMediaDownloadUrls(context: Context, media: Any): List<String> {
        val started = SystemClock.uptimeMillis()
        val dictClass = mutableMediaDictIntfClass
        val dict = findAssignableInObjectGraph(media, dictClass)
        val debug = ArrayList<String>(8)
        if (dict != null && mediaCarouselCandidates.isNotEmpty()) {
            val carouselCandidates = ArrayList<List<String>>()
            mediaCarouselCandidates.forEach { candidate ->
                val items = runCatching { candidate.invoke(dict) as? List<*> }.getOrNull().orEmpty()
                if (items.size < 2) {
                    debug += "${candidate.name}:items=${items.size}:skip"
                    return@forEach
                }
                val videoClass = storyVideoVersionIntfClass
                if (videoClass != null && videoClass.isInstance(items.firstOrNull())) {
                    debug += "${candidate.name}:items=${items.size}:videoVersions"
                    return@forEach
                }
                val parentDictClass = dict.javaClass
                val carouselUrls = items.mapNotNull { item ->
                    item ?: return@mapNotNull null
                    bestMediaVideoUrl(item)
                        ?: imageUrlFromMedia(context, item)
                        ?: probeCdnUrlViaStringMethods(item)
                        ?: collectCdnUrls(item, parentDictClass)
                            .filterNot(::isVideoMediaUrl)
                            .let(::pickBestImageMediaUrl)
                }
                val distinctUrls = carouselUrls.distinct()
                debug += "${candidate.name}:items=${items.size}:urls=${distinctUrls.size}:types=${dmUrlTypesForLog(distinctUrls)}:fp=${dmCarouselFingerprintsForLog(distinctUrls)}"
                if (distinctUrls.size >= 2) {
                    carouselCandidates += distinctUrls
                }
            }
            val largestCarousel = carouselCandidates.maxWithOrNull(
                compareBy<List<String>> { it.size }.thenBy { it.joinToString("|").length }
            )
            if (largestCarousel != null) {
                logInfoThrottled("download:carousel-list:${dict.javaClass.name}:${largestCarousel.size}", 1_500L) {
                    "Detected carousel list media class=${media.javaClass.name} dict=${dict.javaClass.name} " +
                        "count=${largestCarousel.size} candidates=${carouselCandidates.map { it.size }.joinToString(",")} " +
                        "elapsed=${SystemClock.uptimeMillis() - started}ms types=${dmUrlTypesForLog(largestCarousel)} " +
                        "fp=${dmCarouselFingerprintsForLog(largestCarousel)} scan=${debug.take(8).joinToString("|")}"
                }
                return largestCarousel
            }
            logInfoThrottled("download:carousel-list-miss:${media.javaClass.name}:${dict.javaClass.name}", 1_500L) {
                "Carousel list extraction miss media=${media.javaClass.name} dict=${dict.javaClass.name} " +
                    "methods=${mediaCarouselCandidates.size} elapsed=${SystemClock.uptimeMillis() - started}ms " +
                    "scan=${debug.take(8).joinToString("|").ifBlank { "-" }}"
            }
        }
        val graphUrls = extractCarouselMediaDownloadUrlsFromGraph(context, media)
            .distinctBy(::dmUrlIdentityForChoice)
        if (graphUrls.isNotEmpty()) {
            logInfoThrottled("download:carousel-graph:${media.javaClass.name}:${graphUrls.size}", 1_500L) {
                "Carousel graph extraction media=${media.javaClass.name} dict=${dict?.javaClass?.name ?: "-"} " +
                    "count=${graphUrls.size} elapsed=${SystemClock.uptimeMillis() - started}ms " +
                    "types=${dmUrlTypesForLog(graphUrls)} fp=${dmCarouselFingerprintsForLog(graphUrls)}"
            }
            rememberDmMediaAssetGroup(graphUrls, "extract-carousel-graph:${media.javaClass.name.substringAfterLast('.')}")
        } else if (dict != null || looksLikeCarouselMediaObject(media)) {
            logInfoThrottled("download:carousel-empty:${media.javaClass.name}:${dict?.javaClass?.name ?: "no-dict"}", 1_500L) {
                "Carousel extraction empty media=${media.javaClass.name} dict=${dict?.javaClass?.name ?: "-"} " +
                    "candidates=${mediaCarouselCandidates.size} elapsed=${SystemClock.uptimeMillis() - started}ms " +
                    "scan=${debug.take(8).joinToString("|").ifBlank { "-" }}"
            }
        }
        return graphUrls
    }

    private fun extractCarouselMediaDownloadUrlsFromGraph(context: Context, media: Any): List<String> {
        if (!looksLikeCarouselMediaObject(media)) return emptyList()
        return findCarouselMediaUrlsInGraph(context, media, IdentityHashMap(), 0)
    }

    private fun findCarouselMediaUrlsInGraph(
        context: Context,
        value: Any?,
        seen: IdentityHashMap<Any, Boolean>,
        depth: Int
    ): List<String> {
        if (value == null || depth > 4) return emptyList()
        if (value is Iterable<*>) {
            carouselUrlsFromItems(context, value.take(20)).takeIf { it.size >= 2 }?.let { return it }
            value.take(20).forEach { item ->
                findCarouselMediaUrlsInGraph(context, item, seen, depth + 1).takeIf { it.size >= 2 }?.let { return it }
            }
            return emptyList()
        }
        val cls = value.javaClass
        if (cls.isArray) {
            val items = ArrayList<Any?>(minOf(java.lang.reflect.Array.getLength(value), 20))
            val count = java.lang.reflect.Array.getLength(value).coerceAtMost(20)
            for (index in 0 until count) items += java.lang.reflect.Array.get(value, index)
            carouselUrlsFromItems(context, items).takeIf { it.size >= 2 }?.let { return it }
            items.forEach { item ->
                findCarouselMediaUrlsInGraph(context, item, seen, depth + 1).takeIf { it.size >= 2 }?.let { return it }
            }
            return emptyList()
        }
        if (!shouldInspectObject(cls) || seen.containsKey(value)) return emptyList()
        seen[value] = true
        dmNonStaticFields(cls).asSequence().take(90).forEach { field ->
            val fieldValue = runCatching { field.get(value) }.getOrNull() ?: return@forEach
            if (looksLikeCarouselName(field.name) || looksLikeCarouselName(field.type.name)) {
                carouselUrlsFromItems(context, iterableItems(fieldValue)).takeIf { it.size >= 2 }?.let { return it }
            }
            findCarouselMediaUrlsInGraph(context, fieldValue, seen, depth + 1).takeIf { it.size >= 2 }?.let { return it }
        }
        return emptyList()
    }

    private fun iterableItems(value: Any?): List<Any?> {
        if (value == null) return emptyList()
        if (value is Iterable<*>) return value.take(20)
        val cls = value.javaClass
        if (!cls.isArray) return emptyList()
        val count = java.lang.reflect.Array.getLength(value).coerceAtMost(20)
        return (0 until count).map { index -> java.lang.reflect.Array.get(value, index) }
    }

    private fun carouselUrlsFromItems(context: Context, items: List<Any?>, parentDictClass: Class<*>? = null): List<String> {
        if (items.size < 2) return emptyList()
        val first = items.firstOrNull { it != null } ?: return emptyList()
        val videoClass = storyVideoVersionIntfClass
        if (videoClass != null && videoClass.isInstance(first)) return emptyList()
        return items
            .mapNotNull { carouselItemDownloadUrl(context, it, parentDictClass) }
            .filterNot(::looksLikeProfileImageUrl)
            .distinctBy(::dmUrlIdentityForChoice)
            .take(12)
    }

    private fun carouselItemDownloadUrl(context: Context, item: Any?, parentDictClass: Class<*>? = null): String? {
        item ?: return null
        when (item) {
            is String -> return item.takeIf { looksLikeMediaUrl(it) && !looksLikeProfileImageUrl(it) }
            is Uri -> return item.toString().takeIf { looksLikeMediaUrl(it) && !looksLikeProfileImageUrl(it) }
        }
        return bestMediaVideoUrl(item)
            ?: imageUrlFromMedia(context, item)
            ?: collectDmMediaObjectDownloadUrls(item).firstOrNull { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
            ?: probeCdnUrlViaStringMethods(item)
            ?: collectCdnUrls(item, parentDictClass)
                .filterNot(::looksLikeProfileImageUrl)
                .filter { !isAudioUrl(it) && !isLikelyAudioHttpUrl(it) }
                .let(::pickBestImageMediaUrl)
    }

    private fun imageUrlFromMedia(context: Context, media: Any): String? {
        val mediaType = mediaClass
        val method = mediaImageUrlMethod
        if (mediaType == null || method == null || !mediaType.isInstance(media)) return null
        return runCatching { method.invoke(null, context, media) as? String }
            .getOrNull()
            ?.takeIf { looksLikeMediaUrl(it) && !isVideoMediaUrl(it) }
    }

    private fun applyFeedPostDownloadControls(view: View, current: InstagramFeatureState = state) {
        val target = feedDownloadControlTarget(view, current) ?: return
        val parent = view.parent as? ViewGroup ?: return
        if (!shouldOfferDownloadLikeLongPress()) {
            feedDownloadButtonUrls.remove(view)
            removeInjectedFeedDownloadButton(parent)
            feedDownloadControlSignatures.remove(view)
            return
        }
        val signature = "${target}|${downloadTriggerMode()}|${current.enablePostDownload}|${current.enableReelDownload}|${current.enableReelThumbnailDownload}"
        if (feedDownloadControlSignatures[view] == signature) return
        feedDownloadControlSignatures[view] = signature

        if (target == "feed_like") {
            if (!current.enablePostDownload) {
                feedDownloadButtonUrls.remove(view)
                removeInjectedFeedDownloadButton(parent)
                feedDownloadControlSignatures.remove(view)
                return
            }
            val existing = parent.findViewWithTag<View>(FEED_DOWNLOAD_BUTTON_TAG)
            if (existing != null) removeInjectedFeedDownloadButton(parent)
            installFeedLikeLongPress(view)
        } else {
            if (!current.enableReelDownload && !current.enableReelThumbnailDownload) return
            installReelLikePostDownloadLongPress(view)
        }
    }

    private fun feedDownloadControlTarget(view: View, current: InstagramFeatureState): String? {
        val id = view.id
        if (id == View.NO_ID || id == 0) return null

        if (current.enablePostDownload && isInstagramResourceIdOrFallback(view, "row_feed_button_like")) {
            return "feed_like"
        }
        if ((current.enableReelDownload || current.enableReelThumbnailDownload) &&
            isInstagramResourceIdOrFallback(view, "like_button") &&
            hasAncestorInstagramResourceIdOrFallback(view, "clips_ufi_component")
        ) {
            return "reel_like"
        }
        return null
    }

    private fun isInstagramResourceIdOrFallback(view: View, name: String): Boolean {
        val id = view.id
        if (id == View.NO_ID || id == 0) return false
        val expected = instagramResourceId(view.context, name)
        if (expected != 0) return id == expected
        return resourceEntryName(view) == name
    }

    private fun hasAncestorInstagramResourceIdOrFallback(view: View, name: String): Boolean {
        val expected = instagramResourceId(view.context, name)
        if (expected == 0) return hasAncestorNamed(view, name)
        var current: View? = view
        repeat(8) {
            val candidate = current ?: return@repeat
            if (candidate.id == expected) return true
            current = candidate.parent as? View
        }
        return false
    }

    private fun removeInjectedFeedDownloadButton(parent: ViewGroup) {
        val existing = parent.findViewWithTag<View>(FEED_DOWNLOAD_BUTTON_TAG) ?: return
        feedDownloadButtonUrls.remove(existing)
        parent.post {
            runCatching {
                if (existing.parent === parent) parent.removeView(existing)
            }
        }
    }

    private fun injectFeedDownloadButton(likeButton: View, parent: ViewGroup, snapshot: List<String>) {
        val context = likeButton.context ?: return
        val button = ImageButton(context).apply {
            tag = FEED_DOWNLOAD_BUTTON_TAG
            setImageResource(android.R.drawable.stat_sys_download)
            setColorFilter(Color.WHITE)
            background = null
            contentDescription = "Download media"
            val size = dp(34)
            layoutParams = if (parent is LinearLayout) {
                LinearLayout.LayoutParams(size, size).apply {
                    gravity = Gravity.CENTER_VERTICAL
                    setMargins(dp(4), 0, dp(4), 0)
                }
            } else {
                FrameLayout.LayoutParams(size, size).apply {
                    gravity = Gravity.CENTER_VERTICAL or Gravity.END
                    setMargins(0, 0, dp(8), 0)
                }
            }
            setOnClickListener { handleFeedPostDownload(likeButton, this) }
        }
        feedDownloadButtonUrls[button] = snapshot
        installFeedLikeLongPress(likeButton)
        parent.post {
            if (button.parent == null && parent.findViewWithTag<View>(FEED_DOWNLOAD_BUTTON_TAG) == null) {
                runCatching {
                    parent.addView(button)
                    button.bringToFront()
                }.onFailure { logError("Feed download button injection failed", it) }
            }
        }
    }

    private fun installFeedLikeLongPress(likeButton: View) {
        likeButton.isLongClickable = true
        likeButton.setOnLongClickListener {
            if (!state.enablePostDownload || !shouldOfferDownloadLikeLongPress()) {
                logDownloadControlGate("post_like_long_press", "suppressed")
                return@setOnLongClickListener false
            }
            logDownloadControlGate("post_like_long_press", "accepted")
            handleFeedPostDownload(likeButton, null)
            true
        }
    }

    private fun installReelLikePostDownloadLongPress(likeButton: View) {
        likeButton.isLongClickable = true
        likeButton.setOnLongClickListener { view ->
            if ((!state.enableReelDownload && !state.enableReelThumbnailDownload) ||
                !shouldOfferDownloadLikeLongPress()
            ) {
                logDownloadControlGate("reel_like_long_press", "suppressed")
                return@setOnLongClickListener false
            }
            logDownloadControlGate("reel_like_long_press", "accepted")
            val taggedMedia = runCatching { view.getTag(TAG_REEL_MEDIA) }.getOrNull()
            if (taggedMedia != null) {
                if (!state.enableReelDownload && state.enableReelThumbnailDownload) {
                    startReelThumbnailDownload(view.context, taggedMedia)
                    return@setOnLongClickListener true
                }
                bestMediaVideoUrl(taggedMedia)?.let { url ->
                    enqueueDownload(url, downloadContextFrom(taggedMedia, "reel"))
                    return@setOnLongClickListener true
                }
            }
            val all = recentMediaUrlsSince(System.currentTimeMillis() - 60_000L)
            val m86 = all.filter { it.contains("/m86/") || it.contains("%2Fm86%2F", ignoreCase = true) }
            val pick = (m86.ifEmpty { all }).firstOrNull()
            if (pick == null) {
                Toast.makeText(view.context, "No reel URL found. Scroll a bit and try again.", Toast.LENGTH_SHORT).show()
            } else {
                enqueueDownload(pick, DownloadMetadata(type = "reel"))
            }
            true
        }
    }

    private fun handleFeedPostDownload(anchor: View, downloadButton: View?) {
        val context = anchor.context ?: currentActivity ?: androidContext
        val media = resolveFeedControlMedia(anchor)
        val urls = when {
            media != null -> extractAllMediaDownloadUrls(context, media)
            downloadButton != null -> feedDownloadButtonUrls[downloadButton].orEmpty()
            else -> feedDownloadButtonUrls[anchor].orEmpty()
        }.ifEmpty {
            recentMediaUrlsSince(System.currentTimeMillis() - 30_000L)
        }.filterNot(::looksLikeProfileImageUrl).distinct()

        if (urls.isEmpty()) {
            Toast.makeText(context, "No media found for post", Toast.LENGTH_SHORT).show()
            return
        }
        showPostDownloadChoices(context, urls, downloadContextFrom(media ?: anchor, "post"), 0)
    }

    private fun handlePostDownloadFromMedia(context: Context, media: Any?, fallbackRoot: Any?) {
        val roots = listOfNotNull(media, fallbackRoot).distinctBy { System.identityHashCode(it) }
        val reflectedUrls = media?.let { extractAllMediaDownloadUrls(context, it) }.orEmpty()
        val fallbackUrls = if (reflectedUrls.isEmpty()) {
            roots.flatMap { collectCdnUrls(it) }
        } else {
            emptyList()
        }
        val urls = (reflectedUrls + fallbackUrls)
            .ifEmpty { recentMediaUrlsSince(System.currentTimeMillis() - 30_000L) }
            .filter(::looksLikeMediaUrl)
            .filterNot(::looksLikeProfileImageUrl)
            .distinct()

        if (urls.isEmpty()) {
            Toast.makeText(context, "No media found for post", Toast.LENGTH_SHORT).show()
            return
        }
        showPostDownloadChoices(context, urls, downloadContextFrom(media ?: fallbackRoot, "post"), 0)
    }

    private fun resolveFeedControlMedia(anchor: View): Any? {
        findMediaObject(getViewOnClickListener(anchor))?.let { return it }
        val saveButton = findFeedSaveButtonNear(anchor)
        findMediaObject(getViewOnClickListener(saveButton))?.let { return it }
        return null
    }

    private fun findFeedSaveButtonNear(anchor: View): View? {
        var parent = anchor.parent
        repeat(4) {
            val group = parent as? ViewGroup ?: return@repeat
            findDescendantByResourceName(group, "row_feed_button_save", 5)?.let { return it }
            parent = group.parent
        }
        return null
    }

    private fun findDescendantByResourceName(root: View, name: String, maxDepth: Int): View? {
        if (resourceEntryName(root) == name) return root
        if (root !is ViewGroup || maxDepth <= 0) return null
        val count = root.childCount.coerceAtMost(80)
        for (index in 0 until count) {
            findDescendantByResourceName(root.getChildAt(index), name, maxDepth - 1)?.let { return it }
        }
        return null
    }

    private fun getViewOnClickListener(view: View?): Any? {
        view ?: return null
        return runCatching {
            val getListenerInfo = View::class.java.getDeclaredMethod("getListenerInfo").apply { isAccessible = true }
            val listenerInfo = getListenerInfo.invoke(view) ?: return@runCatching null
            val field = listenerInfo.javaClass.getDeclaredField("mOnClickListener").apply { isAccessible = true }
            field.get(listenerInfo)
        }.getOrNull()
    }

    private fun recentMediaUrlsSince(sinceMs: Long): List<String> {
        synchronized(recentMediaUrlEvents) {
            val cutoff = System.currentTimeMillis() - 90_000L
            while (recentMediaUrlEvents.size > 120) recentMediaUrlEvents.removeLast()
            while (recentMediaUrlEvents.isNotEmpty() && recentMediaUrlEvents.peekLast().timeMs < cutoff) {
                recentMediaUrlEvents.removeLast()
            }
            return recentMediaUrlEvents
                .filter { it.timeMs >= sinceMs && looksLikeMediaUrl(it.url) && !looksLikeProfileImageUrl(it.url) }
                .map { it.url }
                .distinct()
        }
    }

    private fun hasAncestorNamed(view: View, name: String): Boolean {
        var current: View? = view
        repeat(8) {
            if (resourceEntryName(current ?: return@repeat) == name) return true
            current = current?.parent as? View
        }
        return false
    }

    private fun bestMediaVideoUrl(media: Any): String? {
        val urls = linkedSetOf<String>()
        collectVideoVersionUrls(media, urls, Collections.newSetFromMap(IdentityHashMap()), 0)
        return urls.firstOrNull { it.contains("/m86/") || it.contains("%2Fm86%2F") }
            ?: urls.firstOrNull()
            ?: collectDmMediaObjectUrlCandidates(media)
                .filter { it.video || isVideoMediaUrl(it.url) }
                .maxWithOrNull(compareBy<MediaUrlCandidate> { it.score }.thenBy { it.url.length })
                ?.url
    }

    private fun collectVideoVersionUrls(value: Any?, out: MutableSet<String>, visited: MutableSet<Any>, depth: Int) {
        if (value == null || depth > 5 || !visited.add(value)) return
        val videoClass = storyVideoVersionIntfClass ?: return
        val getUrl = storyVideoVersionGetUrl ?: return
        if (videoClass.isInstance(value)) {
            runCatching { getUrl.invoke(value) as? String }
                .getOrNull()
                ?.takeIf { looksLikeMediaUrl(it) }
                ?.let(out::add)
            return
        }
        if (!shouldInspectObject(value.javaClass)) return
        when (value) {
            is Iterable<*> -> {
                value.forEach { collectVideoVersionUrls(it, out, visited, depth + 1) }
                return
            }
        }
        if (value.javaClass.isArray) {
            val count = java.lang.reflect.Array.getLength(value).coerceAtMost(40)
            for (index in 0 until count) collectVideoVersionUrls(java.lang.reflect.Array.get(value, index), out, visited, depth + 1)
            return
        }
        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (field.type.isPrimitive || Modifier.isStatic(field.modifiers)) return@forEach
                runCatching {
                    field.isAccessible = true
                    collectVideoVersionUrls(field.get(value), out, visited, depth + 1)
                }
            }
            cls = cls.superclass
        }
    }

    private fun findAssignableInObjectGraph(root: Any?, type: Class<*>?, depth: Int = 0, visited: MutableSet<Any> = Collections.newSetFromMap(IdentityHashMap())): Any? {
        if (root == null || type == null || depth > 4 || !visited.add(root)) return null
        if (type.isInstance(root)) return root
        if (!shouldInspectObject(root.javaClass)) return null
        if (root is Iterable<*>) {
            root.forEach { findAssignableInObjectGraph(it, type, depth + 1, visited)?.let { found -> return found } }
            return null
        }
        if (root.javaClass.isArray) {
            val count = java.lang.reflect.Array.getLength(root).coerceAtMost(30)
            for (index in 0 until count) {
                findAssignableInObjectGraph(java.lang.reflect.Array.get(root, index), type, depth + 1, visited)?.let { return it }
            }
            return null
        }
        var cls: Class<*>? = root.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { field ->
                if (field.type.isPrimitive || field.type == String::class.java || Modifier.isStatic(field.modifiers)) return@forEach
                runCatching {
                    field.isAccessible = true
                    findAssignableInObjectGraph(field.get(root), type, depth + 1, visited)
                }.getOrNull()?.let { return it }
            }
            cls = cls.superclass
        }
        return null
    }

    private fun probeCdnUrlViaStringMethods(value: Any): String? {
        var cls: Class<*>? = value.javaClass
        while (cls != null && cls != Any::class.java) {
            if (!shouldInspectObject(cls)) break
            cls.declaredMethods
                .filter { it.parameterTypes.isEmpty() && it.returnType == String::class.java }
                .forEach { method ->
                    runCatching {
                        method.isAccessible = true
                        method.invoke(value) as? String
                    }.getOrNull()?.takeIf { looksLikeMediaUrl(it) }?.let { return it }
                }
            cls = cls.superclass
        }
        return null
    }

    private fun pickBestImageMediaUrl(urls: List<String>): String? {
        return urls.firstOrNull { url ->
            !url.contains("/s150x") &&
                !url.contains("/s240x") &&
                !url.contains("/s320x") &&
                !url.contains("/s480x") &&
                !url.contains("/s640x") &&
                !url.contains("_s.jpg")
        } ?: urls.maxByOrNull(::parseCdnArea)
    }

    private fun isVideoMediaUrl(url: String): Boolean {
        val lower = url.lowercase(Locale.US)
        return mimeTypeForUrl(url).startsWith("video") ||
            lower.contains("t50.") ||
            lower.contains("/o1/") ||
            lower.contains("/m86/") ||
            lower.contains("%2fm86%2f")
    }

    private fun showPostDownloadChoices(context: Context, urls: List<String>, metadata: DownloadMetadata, currentIndex: Int) {
        val choices = urls.distinctBy(::dmUrlIdentityForChoice)
        logInfo(
            "Download chooser requested type=${metadata.type} count=${choices.size} " +
                "currentIndex=$currentIndex types=${dmUrlTypesForLog(choices)}"
        )
        if (choices.isEmpty()) {
            Toast.makeText(context, "No media found for post", Toast.LENGTH_SHORT).show()
            return
        }
        if (choices.size == 1) {
            logInfo("Download chooser single item type=${metadata.type} url=${redactCdnUrlForLog(choices.first())}")
            enqueueDownload(choices.first(), metadata)
            return
        }
        val safeIndex = currentIndex.takeIf { it in choices.indices } ?: 0
        var activity = if (metadata.type.startsWith("dm")) {
            findActivity(context) ?: currentActivity
        } else {
            findActivity(context) ?: currentActivity
        }
        if (activity == null) {
            activity = activeActivities.firstOrNull { !it.isFinishing && !it.isDestroyed }
        }
        if (activity == null) {
            logInfo("Download chooser missing activity; downloading safeIndex=$safeIndex type=${metadata.type}")
            enqueueDownload(choices[safeIndex], metadata)
            return
        }
        logInfo("Download chooser showing carousel sheet type=${metadata.type} count=${choices.size} safeIndex=$safeIndex")
        showCarouselDownloadBottomSheet(activity, choices, metadata, safeIndex)
    }

    private fun showCarouselDownloadBottomSheet(context: Context, urls: List<String>, metadata: DownloadMetadata, safeIndex: Int) {
        runCatching {
            val density = context.resources.displayMetrics.density
            val dark = (context.resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
            val sheetBg = if (dark) Color.rgb(28, 28, 30) else Color.rgb(242, 242, 247)
            val textPrimary = if (dark) Color.WHITE else Color.rgb(28, 28, 30)
            val textSecondary = if (dark) Color.rgb(174, 174, 178) else Color.rgb(108, 108, 112)
            val accentBg = Color.rgb(10, 132, 255)
            val secondaryBg = if (dark) Color.rgb(58, 58, 60) else Color.rgb(229, 229, 234)
            val secondaryText = if (dark) Color.WHITE else Color.rgb(28, 28, 30)
            val handleColor = if (dark) Color.rgb(72, 72, 74) else Color.rgb(199, 199, 204)

            val dialog = Dialog(context)
            dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
            val sheet = LinearLayout(context).apply {
                orientation = LinearLayout.VERTICAL
                background = roundedDrawable(sheetBg, 20f)
                setPadding((20 * density).roundToInt(), (12 * density).roundToInt(), (20 * density).roundToInt(), (28 * density).roundToInt())
            }
            sheet.addView(View(context).apply {
                background = roundedDrawable(handleColor, 2f)
            }, LinearLayout.LayoutParams((40 * density).roundToInt(), (4 * density).roundToInt()).apply {
                gravity = Gravity.CENTER_HORIZONTAL
                bottomMargin = (16 * density).roundToInt()
            })
            sheet.addView(TextView(context).apply {
                text = "Download"
                setTextColor(textPrimary)
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)
                typeface = Typeface.DEFAULT_BOLD
            }, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = (4 * density).roundToInt()
            })
            sheet.addView(TextView(context).apply {
                text = "${urls.size} items in this carousel"
                setTextColor(textSecondary)
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)
            }, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = (14 * density).roundToInt()
            })
            sheet.addView(makeDownloadPillButton(context, "Download current (${safeIndex + 1}/${urls.size})", accentBg, Color.WHITE, density).apply {
                setOnClickListener {
                    dialog.dismiss()
                    enqueueDownload(urls[safeIndex], metadata)
                }
            })
            sheet.addView(makeDownloadPillButton(context, "Download all (${urls.size})", secondaryBg, secondaryText, density).apply {
                setOnClickListener {
                    dialog.dismiss()
                    urls.forEach { enqueueDownload(it, metadata) }
                }
            })
            dialog.setContentView(sheet)
            dialog.show()
            dialog.window?.let { window ->
                window.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                window.setGravity(Gravity.BOTTOM)
                window.setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.WRAP_CONTENT)
                val attrs = window.attributes
                val margin = (12 * density).roundToInt()
                attrs.x = margin
                attrs.y = margin
                window.attributes = attrs
            }
        }.onFailure {
            AlertDialog.Builder(context)
                .setTitle("Download")
                .setItems(arrayOf("Download current (${safeIndex + 1}/${urls.size})", "Download all (${urls.size})")) { _, which ->
                    if (which == 0) enqueueDownload(urls[safeIndex], metadata) else urls.forEach { url -> enqueueDownload(url, metadata) }
                }
                .show()
        }
    }

    private fun makeDownloadPillButton(context: Context, label: String, bgColor: Int, textColor: Int, density: Float): Button {
        return Button(context).apply {
            text = label
            setTextColor(textColor)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 15f)
            typeface = Typeface.DEFAULT_BOLD
            background = roundedDrawable(bgColor, 14f)
            setAllCaps(false)
            setPadding((20 * density).roundToInt(), (14 * density).roundToInt(), (20 * density).roundToInt(), (14 * density).roundToInt())
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = (10 * density).roundToInt()
            }
        }
    }

    private fun roundedDrawable(color: Int, radiusDp: Float): GradientDrawable {
        return GradientDrawable().apply {
            setColor(color)
            cornerRadius = radiusDp * androidContext.resources.displayMetrics.density
        }
    }

    private fun adapterCount(adapter: Any): Int {
        return runCatching { adapter.javaClass.getMethod("getItemCount").invoke(adapter) as Int }
            .recoverCatching { adapter.javaClass.getMethod("getCount").invoke(adapter) as Int }
            .getOrDefault(-1)
    }

    private fun collectCarouselMatches(view: View, carouselSize: Int, out: MutableList<Pair<Int, View>>) {
        val cn = view.javaClass.name
        if (cn.contains("ViewPager")) {
            runCatching {
                val adapter = view.javaClass.getMethod("getAdapter").invoke(view)
                if (adapter != null && adapterCount(adapter) >= 2) {
                    val getters = arrayOf("getCurrentItem", "getCurrentDataIndex", "getCurrentWrappedDataIndex", "getCurrentRawDataIndex")
                    for (getter in getters) {
                        runCatching {
                            val cur = view.javaClass.getMethod(getter).invoke(view) as Int
                            if (cur >= 0) { out.add(cur to view); return }
                        }
                    }
                }
            }
        }
        if (cn.contains("RecyclerView")) {
            runCatching {
                val adapter = view.javaClass.getMethod("getAdapter").invoke(view)
                if (adapter != null && adapterCount(adapter) >= 2) {
                    var lm = view.javaClass.getMethod("getLayoutManager").invoke(view)
                    if (lm != null) {
                        runCatching {
                            val orientation = lm.javaClass.getMethod("getOrientation").invoke(lm) as Int
                            if (orientation != 0 /* HORIZONTAL */) lm = null
                        }
                        if (lm != null) {
                            var pos: Int? = null
                            runCatching {
                                val p = lm.javaClass.getMethod("findFirstCompletelyVisibleItemPosition").invoke(lm) as Int
                                if (p >= 0) pos = p
                            }
                            if (pos == null) {
                                runCatching {
                                    val p = lm.javaClass.getMethod("findFirstVisibleItemPosition").invoke(lm) as Int
                                    if (p >= 0) pos = p
                                }
                            }
                            if (pos != null) out.add(pos to view)
                        }
                    }
                }
            }
        }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                collectCarouselMatches(view.getChildAt(i), carouselSize, out)
            }
        }
    }

    private fun findCarouselIndexFromView(ctx: Context?, carouselSize: Int): Int {
        if (ctx == null || carouselSize <= 1) return -1
        return runCatching {
            var act: Activity? = null
            if (ctx is Activity) act = ctx
            else if (ctx is ContextWrapper) {
                val base = ctx.baseContext
                if (base is Activity) act = base
            }
            if (act == null) return -1
            val root = act.window.decorView.rootView
            val matches = mutableListOf<Pair<Int, View>>()
            collectCarouselMatches(root, carouselSize, matches)
            if (matches.size == 1) return matches[0].first
            if (matches.size > 1) {
                val displayMetrics = act.resources.displayMetrics
                val screenCenterY = displayMetrics.heightPixels / 2
                var bestMatch = -1
                var minDistance = Int.MAX_VALUE
                for ((index, view) in matches) {
                    val location = IntArray(2)
                    view.getLocationOnScreen(location)
                    val viewCenterY = location[1] + view.height / 2
                    val distance = Math.abs(viewCenterY - screenCenterY)
                    if (distance < minDistance) {
                        minDistance = distance
                        bestMatch = index
                    }
                }
                return bestMatch
            }
            return -1
        }.getOrDefault(-1)
    }

    private fun findObjectCarouselIndex(value: Any?, count: Int): Int {
        if (value == null || count <= 1) return 0
        fun readIndex(field: Field): Int? {
            if (field.type != java.lang.Integer.TYPE) return null
            return runCatching {
                field.isAccessible = true
                field.getInt(value).takeIf { it in 0 until count }
            }.getOrNull()
        }
        value.javaClass.declaredFields.firstOrNull { it.name == "A00" }?.let { readIndex(it)?.let { index -> return index } }
        value.javaClass.declaredFields.forEach { field ->
            readIndex(field)?.takeIf { it > 0 }?.let { return it }
        }
        return 0
    }

    private fun findReelControllerCarouselIndex(controller: Any?, count: Int): Int {
        if (controller == null || count <= 1) return 0
        var best: Int? = null
        var cls: Class<*>? = controller.javaClass
        while (cls != null && cls != Any::class.java) {
            cls.declaredFields.forEach { outer ->
                if (outer.type.isPrimitive || !shouldInspectObject(outer.type)) return@forEach
                val nested = runCatching {
                    outer.isAccessible = true
                    outer.get(controller)
                }.getOrNull() ?: return@forEach
                val ints = nested.javaClass.declaredFields.filter { it.type == java.lang.Integer.TYPE }
                if (ints.size != 1) return@forEach
                val index = runCatching {
                    ints.first().isAccessible = true
                    ints.first().getInt(nested)
                }.getOrNull() ?: return@forEach
                if (index in 0 until count && (best == null || index < best!!)) best = index
            }
            cls = cls.superclass
        }
        return best ?: 0
    }

    private fun showDownloadChoices(context: Context, urls: List<String>, metadata: DownloadMetadata = DownloadMetadata()) {
        if (urls.size == 1) {
            enqueueDownload(urls.first(), metadata)
            return
        }
        val activity = findActivity(context) ?: currentActivity
        if (activity == null) {
            enqueueDownload(urls.first(), metadata)
            return
        }
        val labels = urls.mapIndexed { index, url ->
            val type = if (mimeTypeForUrl(url).startsWith("video")) "Video" else "Image"
            "$type ${index + 1}"
        }.toTypedArray()
        AlertDialog.Builder(activity)
            .setTitle("Download")
            .setItems(labels) { _, which -> enqueueDownload(urls[which.coerceIn(urls.indices)], metadata) }
            .show()
    }

    private fun downloadContextFrom(root: Any?, type: String): DownloadMetadata {
        return DownloadMetadata(
            username = findUsernameInObjectGraph(root),
            mediaId = findMediaIdInObjectGraph(root),
            type = type
        )
    }

    private fun findUsernameInObjectGraph(root: Any?): String? {
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        fun scan(value: Any?, depth: Int): String? {
            if (value == null || depth > 5 || !visited.add(value)) return null
            if (value.javaClass.name == "com.instagram.user.model.User" || userClass?.isInstance(value) == true) {
                extractUsernameFromUser(value)?.let { return it }
            }
            findUsernameOnModel(value)?.let { return it }
            listOf("getUser", "A0C", "A0r", "BKR").forEach { methodName ->
                val user = invokeNoArgDeep(value, methodName)
                if (user != null && user !== value) scan(user, depth + 1)?.let { return it }
            }
            if (!shouldInspectObject(value.javaClass)) return null
            if (value is Iterable<*>) {
                value.take(20).forEach { scan(it, depth + 1)?.let { username -> return username } }
            }
            if (value.javaClass.isArray) {
                val count = java.lang.reflect.Array.getLength(value).coerceAtMost(20)
                for (i in 0 until count) scan(java.lang.reflect.Array.get(value, i), depth + 1)?.let { return it }
            }
            var cls: Class<*>? = value.javaClass
            var fields = 0
            while (cls != null && cls != Any::class.java && fields < 80) {
                cls.declaredFields.forEach { field ->
                    if (fields++ >= 80) return@forEach
                    if (field.type.isPrimitive || Modifier.isStatic(field.modifiers)) return@forEach
                    runCatching {
                        field.isAccessible = true
                        scan(field.get(value), depth + 1)
                    }.getOrNull()?.let { return it }
                }
                cls = cls.superclass
            }
            return null
        }
        return normalizeUsername(scan(root, 0)).takeIf { it.isNotBlank() }
    }

    private fun findMediaIdInObjectGraph(root: Any?): String? {
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        fun normalizeId(value: Any?): String? {
            val raw = value?.toString()?.trim().orEmpty()
            if (raw.isBlank()) return null
            val clean = raw.substringBefore('_')
            return clean.takeIf { it.length in 3..80 && it.matches(Regex("[A-Za-z0-9_-]+")) }
        }
        fun scan(value: Any?, depth: Int): String? {
            if (value == null || depth > 4 || !visited.add(value)) return null
            listOf("getId", "getPk", "A0Y", "A0W").forEach { methodName ->
                normalizeId(invokeNoArgDeep(value, methodName))?.let { return it }
            }
            if (!shouldInspectObject(value.javaClass)) return null
            var cls: Class<*>? = value.javaClass
            var fields = 0
            while (cls != null && cls != Any::class.java && fields < 70) {
                cls.declaredFields.forEach { field ->
                    if (fields++ >= 70) return@forEach
                    if (Modifier.isStatic(field.modifiers)) return@forEach
                    val name = field.name.lowercase(Locale.US)
                    runCatching {
                        field.isAccessible = true
                        val fieldValue = field.get(value)
                        if ((name.contains("id") || name.contains("pk")) && (fieldValue is String || fieldValue is Number)) {
                            normalizeId(fieldValue)?.let { return it }
                        }
                        if (!field.type.isPrimitive) scan(fieldValue, depth + 1)?.let { return it }
                    }
                }
                cls = cls.superclass
            }
            return null
        }
        return scan(root, 0)
    }

    private fun findContextInObjectGraph(root: Any?): Context? {
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        fun scan(value: Any?, depth: Int): Context? {
            if (value == null || depth > 4 || !visited.add(value)) return null
            if (value is Context) return value
            if (!shouldInspectObject(value.javaClass)) return null
            var cls: Class<*>? = value.javaClass
            var fields = 0
            while (cls != null && cls != Any::class.java && fields < 80) {
                cls.declaredFields.forEach { field ->
                    if (fields++ >= 80) return@forEach
                    if (field.type.isPrimitive) return@forEach
                    runCatching {
                        field.isAccessible = true
                        scan(field.get(value), depth + 1)
                    }.getOrNull()?.let { return it }
                }
                cls = cls.superclass
            }
            return null
        }
        return scan(root, 0)
    }

    private fun findMediaViaMenuCreator(clickHandler: Any?): Any? {
        if (clickHandler == null) return null
        return runCatching {
            var cls: Class<*>? = clickHandler.javaClass
            while (cls != null && cls != Any::class.java) {
                for (f in cls.declaredFields) {
                    f.isAccessible = true
                    val creator = runCatching { f.get(clickHandler) }.getOrNull() ?: continue
                    var cCls: Class<*>? = creator.javaClass
                    while (cCls != null && cCls != Any::class.java) {
                        for (cf in cCls.declaredFields) {
                            if (cf.type.name == "com.instagram.feed.media.Media" || mediaClass?.isAssignableFrom(cf.type) == true) {
                                cf.isAccessible = true
                                val media = runCatching { cf.get(creator) }.getOrNull()
                                if (media != null) return media
                            }
                        }
                        cCls = cCls.superclass
                    }
                }
                cls = cls.superclass
            }
            null
        }.getOrNull()
    }

    private fun findMediaObject(root: Any?): Any? {
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        fun scan(value: Any?, depth: Int): Any? {
            if (value == null || depth > 6 || !visited.add(value)) return null
            if (value.javaClass.name == "com.instagram.feed.media.Media" || mediaClass?.isInstance(value) == true) return value
            if (mutableMediaDictIntfClass?.isInstance(value) == true) return value
            if (!shouldInspectObject(value.javaClass)) return null
            if (value is Iterable<*>) {
                value.take(24).forEach { item -> scan(item, depth + 1)?.let { return it } }
            }
            if (value.javaClass.isArray) {
                val count = java.lang.reflect.Array.getLength(value).coerceAtMost(24)
                for (i in 0 until count) scan(java.lang.reflect.Array.get(value, i), depth + 1)?.let { return it }
            }
            var cls: Class<*>? = value.javaClass
            var fields = 0
            while (cls != null && cls != Any::class.java && fields < 90) {
                cls.declaredFields.forEach { field ->
                    if (fields++ >= 90) return@forEach
                    if (field.type.isPrimitive) return@forEach
                    runCatching {
                        field.isAccessible = true
                        scan(field.get(value), depth + 1)
                    }.getOrNull()?.let { return it }
                }
                cls = cls.superclass
            }
            return null
        }
        return scan(root, 0)
    }

    private fun findMediaObjectFast(root: Any?): Any? {
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        var inspectedFields = 0
        fun scan(value: Any?, depth: Int): Any? {
            if (value == null || depth > 4 || !visited.add(value)) return null
            if (value is View || value is Context || value is Activity) return null
            if (value.javaClass.name == "com.instagram.feed.media.Media" || mediaClass?.isInstance(value) == true) return value
            if (mutableMediaDictIntfClass?.isInstance(value) == true) return value
            if (!shouldInspectObject(value.javaClass)) return null
            if (value is Iterable<*>) {
                value.take(12).forEach { item -> scan(item, depth + 1)?.let { return it } }
                return null
            }
            if (value.javaClass.isArray) {
                val count = java.lang.reflect.Array.getLength(value).coerceAtMost(12)
                for (i in 0 until count) scan(java.lang.reflect.Array.get(value, i), depth + 1)?.let { return it }
                return null
            }
            var cls: Class<*>? = value.javaClass
            while (cls != null && cls != Any::class.java && inspectedFields < 180) {
                dmNonStaticFields(cls).asSequence().take(40).forEach { field ->
                    if (inspectedFields++ >= 180) return@forEach
                    if (field.type.isPrimitive || field.type == String::class.java) return@forEach
                    runCatching {
                        scan(field.get(value), depth + 1)
                    }.getOrNull()?.let { return it }
                }
                cls = cls.superclass
            }
            return null
        }
        return scan(root, 0)
    }

    private fun collectCdnUrls(root: Any?, ignoreClass: Class<*>? = null): List<String> {
        val output = linkedSetOf<String>()
        val visited = Collections.newSetFromMap(java.util.IdentityHashMap<Any, Boolean>())
        fun scan(value: Any?, depth: Int) {
            if (value == null || depth > 5 || output.size >= 40) return
            if (ignoreClass != null && value !== root && ignoreClass.isInstance(value)) return
            when (value) {
                is String -> {
                    urlPattern.matcher(value).let { matcher ->
                        while (matcher.find()) {
                            val url = matcher.group()
                            if (looksLikeMediaUrl(url)) output += url
                        }
                    }
                    if (looksLikeMediaUrl(value)) output += value
                    return
                }
                is Uri -> {
                    value.toString().takeIf { looksLikeMediaUrl(it) }?.let { output += it }
                    return
                }
                is Iterable<*> -> {
                    value.take(40).forEach { scan(it, depth + 1) }
                    return
                }
            }
            val cls = value.javaClass
            if (cls.isArray) {
                val count = java.lang.reflect.Array.getLength(value).coerceAtMost(40)
                for (i in 0 until count) scan(java.lang.reflect.Array.get(value, i), depth + 1)
                return
            }
            if (!visited.add(value) || !shouldInspectObject(cls)) return
            cls.declaredMethods
                .filter { it.parameterTypes.isEmpty() && !it.returnType.isPrimitive && it.returnType != java.lang.Void.TYPE }
                .take(40)
                .forEach { method ->
                    runCatching {
                        method.isAccessible = true
                        scan(method.invoke(value), depth + 1)
                    }
                }
            var current: Class<*>? = cls
            var fields = 0
            while (current != null && current != Any::class.java && fields < 100) {
                current.declaredFields.forEach { field ->
                    if (fields++ >= 100) return@forEach
                    if (field.type.isPrimitive) return@forEach
                    runCatching {
                        field.isAccessible = true
                        scan(field.get(value), depth + 1)
                    }
                }
                current = current.superclass
            }
        }
        scan(root, 0)
        return output.toList()
    }

    private fun shouldInspectObject(cls: Class<*>): Boolean {
        val name = cls.name
        return name.startsWith("X.") ||
            name.startsWith("p000X.") ||
            name.startsWith("com.instagram.") ||
            name.startsWith("com.facebook.") ||
            name.startsWith("java.util.")
    }

    private fun extractUrlFromView(view: View): String? {
        val candidates = mutableListOf<String>()
        candidates += view.contentDescription?.toString().orEmpty()
        candidates += (view as? TextView)?.text?.toString().orEmpty()
        candidates += view.tag?.toString().orEmpty()
        candidates += runCatching { view.getTag(android.R.id.text1)?.toString().orEmpty() }.getOrDefault("")
        candidates.forEach { text ->
            val matcher = urlPattern.matcher(text)
            if (matcher.find()) return matcher.group()
        }
        return null
    }

    private fun findTextForCopy(view: View): String? {
        if (view is TextView) return view.text?.toString()?.takeIf { it.isNotBlank() }
        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                findTextForCopy(view.getChildAt(i))?.let { return it }
            }
        }
        return null
    }

    private fun shouldMakeCopyable(textView: TextView, raw: String): Boolean {
        if (raw.length < 12) return false
        val id = resourceEntryName(textView).orEmpty().lowercase()
        return (state.enableCopyComment && (id.contains("comment") || isCommentSurface(textView))) ||
            (state.enableCopyBio && (id.contains("bio") || id.contains("profile")))
    }

    private fun applyCustomEmojiFont(textView: TextView) {
        if (!state.customEmojiFontEnabled) return
        val text = textView.text ?: return
        val wrapped = InstagramCustomEmojiFontHooks.wrapEmojiText(text) ?: return
        if (wrapped !== text) textView.text = wrapped
    }

    private fun rewriteRelativeDate(textView: TextView, raw: String) {
        val clean = cleanInstagramDateText(raw)
        if (clean.isEmpty() || clean.length > 32 || clean.contains('\n')) return
        if (formattedDateLikePattern.matches(clean)) return
        if (!looksLikeInstagramDate(clean)) return
        val date = parseInstagramDate(clean) ?: return
        if (!dateSurfaceAllowed(textView)) return
        val formatted = formatCustomInstagramDate(date)
        if (formatted != textView.text?.toString().orEmpty()) textView.text = formatted
        if (cleanInstagramDateText(textView.contentDescription?.toString().orEmpty()) == clean &&
            formatted != textView.contentDescription?.toString().orEmpty()
        ) {
            textView.contentDescription = formatted
        }
    }

    private fun cleanInstagramDateText(raw: String): String {
        return raw.trim()
            .filterNot { it == '\u200E' || it == '\u200F' || it == '\u200B' || it == '\uFEFF' || it in '\u202A'..'\u202E' || it in '\u2066'..'\u2069' }
            .trim()
    }

    private fun parseInstagramRelativeDate(raw: String): Date? {
        if (exactCurrentDatePattern.matches(raw)) return Date()
        when (raw.lowercase(Locale.US)) {
            "today" -> return Calendar.getInstance().apply {
                set(Calendar.HOUR_OF_DAY, 0)
                set(Calendar.MINUTE, 0)
                set(Calendar.SECOND, 0)
                set(Calendar.MILLISECOND, 0)
            }.time
            "yesterday" -> return Calendar.getInstance().apply {
                add(Calendar.DAY_OF_YEAR, -1)
                set(Calendar.HOUR_OF_DAY, 0)
                set(Calendar.MINUTE, 0)
                set(Calendar.SECOND, 0)
                set(Calendar.MILLISECOND, 0)
            }.time
        }
        val match = relativeDatePattern.matchEntire(raw) ?: return null
        val amount = match.groupValues[1].toIntOrNull() ?: return null
        val unit = match.groupValues[2].lowercase(Locale.US)
        return Calendar.getInstance().apply {
            when {
                unit == "s" || unit.startsWith("sec") -> add(Calendar.SECOND, -amount)
                unit == "m" || unit.startsWith("min") -> add(Calendar.MINUTE, -amount)
                unit.startsWith("h") -> add(Calendar.HOUR_OF_DAY, -amount)
                unit.startsWith("d") -> add(Calendar.DAY_OF_YEAR, -amount)
                unit.startsWith("w") -> add(Calendar.WEEK_OF_YEAR, -amount)
                unit.startsWith("mo") || unit.startsWith("mon") -> add(Calendar.MONTH, -amount)
                unit.startsWith("y") -> add(Calendar.YEAR, -amount)
                else -> return null
            }
        }.time
    }

    private fun parseInstagramDate(raw: String): Date? {
        parseInstagramRelativeDate(raw)?.let { return it }
        val clean = raw.trim()
        absoluteDatePatterns.forEach { pattern ->
            val parsed = parseInstagramAbsoluteDate(clean, pattern)
            if (parsed != null) return parsed
        }
        return null
    }

    private val cachedAbsoluteFormatters = ConcurrentHashMap<String, ThreadLocal<SimpleDateFormat>>()
    private val cachedCustomDateFormatter = object : ThreadLocal<SimpleDateFormat>() {
        override fun initialValue(): SimpleDateFormat = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault())
    }
    @Volatile private var lastCustomDateFormatPattern: String = "yyyy-MM-dd HH:mm"

    private fun parseInstagramAbsoluteDate(raw: String, pattern: String, ): Date? {
        return runCatching {
            val formatter = cachedAbsoluteFormatters.getOrPut(pattern) {
                ThreadLocal.withInitial { SimpleDateFormat(pattern, Locale.US).apply { isLenient = false } }
            }.get()
            val position = ParsePosition(0)
            val parsed = formatter.parse(raw, position) ?: return@runCatching null
            if (position.index != raw.length) return@runCatching null
            Calendar.getInstance().apply {
                time = parsed
                if (!pattern.contains("yyyy")) {
                    val now = Calendar.getInstance()
                    set(Calendar.YEAR, now.get(Calendar.YEAR))
                    if (after(now.apply { add(Calendar.DAY_OF_YEAR, 1) })) add(Calendar.YEAR, -1)
                }
                set(Calendar.HOUR_OF_DAY, 0)
                set(Calendar.MINUTE, 0)
                set(Calendar.SECOND, 0)
                set(Calendar.MILLISECOND, 0)
            }.time
        }.getOrNull()
    }

    private fun formatCustomInstagramDate(date: Date): String {
        val pattern = state.customDateFormat.ifBlank { "yyyy-MM-dd HH:mm" }
        val formatter = if (pattern == lastCustomDateFormatPattern) {
            cachedCustomDateFormatter.get()
        } else {
            lastCustomDateFormatPattern = pattern
            SimpleDateFormat(pattern, Locale.getDefault()).also { cachedCustomDateFormatter.set(it) }
        }
        return runCatching {
            formatter.format(date)
        }.getOrElse {
            SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault()).format(date)
        }
    }

    private fun looksLikeInstagramDate(raw: String): Boolean {
        if (raw.isEmpty()) return false
        val lower = raw.lowercase(Locale.US)
        if (lower == "now" || lower == "just now" || lower == "moments ago" || lower == "today" || lower == "yesterday") return true
        val hasDigit = lower.any { it.isDigit() }
        if (hasDigit && relativeDateNeedles.any { lower.contains(it) }) return true
        if (hasDigit && lower.length <= 3) {
            val last = lower.last()
            if (last == 's' || last == 'm' || last == 'h' || last == 'd' || last == 'w' || last == 'y') return true
        }
        return absoluteMonthNeedles.any { lower.contains(it) }
    }

    private val dateSurfaceCache = Collections.synchronizedMap(WeakHashMap<View, Boolean>())

    private fun dateSurfaceAllowed(view: View): Boolean {
        dateSurfaceCache[view]?.let { return it }
        val sb = StringBuilder()
        var current: View? = view
        var depth = 0
        while (current != null && depth < 6) {
            val entryName = resourceEntryName(current)
            if (entryName != null) sb.append(' ').append(entryName)
            sb.append(' ').append(current.javaClass.name)
            current = current.parent as? View
            depth++
        }
        var context: Context? = view.context
        depth = 0
        while (context != null && depth < 5) {
            sb.append(' ').append(context.javaClass.name)
            context = (context as? ContextWrapper)?.baseContext
            depth++
        }
        val surface = sb.toString().lowercase(Locale.US)
        val result = when {
            surface.contains("comment") || surface.contains("ufi") -> state.customDateFormatComments
            surface.contains("direct") || surface.contains("inbox") || surface.contains("thread") ||
                surface.contains("message") || surface.contains("mailbox") -> state.customDateFormatDirect
            surface.contains("story") || surface.contains("reel_tray") || surface.contains("tray_item") -> state.customDateFormatStories
            surface.contains("clips") || surface.contains("reels") || surface.contains("reel_viewer") -> state.customDateFormatReels
            else -> state.customDateFormatFeed
        }
        dateSurfaceCache[view] = result
        return result
    }

    private fun buildSelector(view: View, root: View = view.rootView ?: view): String? {
        if (view == root) return null
        val anchor = findNearestNamedAncestor(view, root) as? ViewGroup ?: return null
        val anchorId = resourceEntryName(anchor)?.takeIf { it.isNotBlank() } ?: return null
        val indexes = mutableListOf<Int>()
        val classes = mutableListOf<String>()
        var current: View? = view
        while (current != null && current != anchor) {
            val parent = current.parent as? ViewGroup ?: return null
            val index = parent.indexOfChild(current)
            if (index < 0) return null
            indexes += index
            classes += current.javaClass.name
            current = parent
        }
        if (indexes.isEmpty()) return null
        indexes.reverse()
        classes.reverse()
        return "selector:v1|anchor=${escapeSelectorPart(anchorId)}|indexes=${indexes.joinToString("/")}|classes=${escapeSelectorPart(classes.joinToString("/"))}"
    }

    private fun selectorMatches(view: View, selector: String): Boolean {
        val parsed = parseAnchoredSelector(selector) ?: return false
        return selectorMatches(view, parsed)
    }

    private fun selectorMatches(view: View, parsed: ParsedSelector): Boolean {
        if (parsed.classes.lastOrNull() != view.javaClass.name) return false
        var current: View = view
        for (i in parsed.indexes.indices.reversed()) {
            val parent = current.parent as? ViewGroup ?: return false
            if (parent.indexOfChild(current) != parsed.indexes[i]) return false
            if (parsed.classes.getOrNull(i) != current.javaClass.name) return false
            current = parent
        }
        return resourceEntryName(current) == parsed.anchorId
    }

    private fun parseAnchoredSelector(selector: String): ParsedSelector? {
        val clean = selector.trim()
        if (!clean.startsWith("selector:v1|")) return null
        var anchor = ""
        var indexes = ""
        var classes = ""
        clean.removePrefix("selector:v1|").split("|").forEach { part ->
            val equals = part.indexOf('=')
            if (equals <= 0) return@forEach
            val key = part.substring(0, equals)
            val value = unescapeSelectorPart(part.substring(equals + 1))
            when (key) {
                "anchor" -> anchor = value
                "indexes" -> indexes = value
                "classes" -> classes = value
            }
        }
        if (anchor.isBlank() || indexes.isBlank() || classes.isBlank()) return null
        val parsedIndexes = indexes.split("/").mapNotNull { it.toIntOrNull() }
        val parsedClasses = classes.split("/")
        if (parsedIndexes.isEmpty() || parsedIndexes.size != parsedClasses.size || parsedClasses.any { it.isBlank() }) return null
        return ParsedSelector(anchor, parsedIndexes, parsedClasses)
    }

    private fun selectorDisplayName(selector: String): String {
        val parsed = parseAnchoredSelector(selector) ?: return selector
        val leaf = parsed.classes.lastOrNull()?.substringAfterLast('.') ?: "View"
        return "Captured $leaf under #${parsed.anchorId}\n${parsed.indexes.joinToString("/")}"
    }

    private fun findNearestNamedAncestor(target: View, root: View): View? {
        var current: View? = target
        while (current != null) {
            if (resourceEntryName(current) != null) return current
            if (current == root) break
            current = current.parent as? View
        }
        return null
    }

    private fun describeViewPath(target: View, root: View): String {
        val parts = mutableListOf<String>()
        var current: View? = target
        var depth = 0
        while (current != null && depth++ < 8) {
            parts += buildString {
                append(current.javaClass.simpleName)
                resourceEntryName(current)?.let { append('#').append(it) }
            }
            if (current == root) break
            current = current.parent as? View
        }
        return parts.joinToString(" <- ")
    }

    private fun escapeSelectorPart(value: String): String {
        return value.replace("%", "%25")
            .replace("|", "%7C")
            .replace("=", "%3D")
            .replace("\n", "%0A")
    }

    private fun unescapeSelectorPart(value: String): String {
        return value.replace("%0A", "\n")
            .replace("%3D", "=")
            .replace("%7C", "|")
            .replace("%25", "%")
    }

    private fun applyNotesLocationSpoof(param: XC_MethodHook.MethodHookParam<*>) {
        val (latitude, longitude) = notesSpoofCoordinates() ?: return
        var changed = applyNotesLocationSpoofToObject(param.thisObject, latitude, longitude)
        param.args.indices.forEach { index ->
            changed = applyNotesLocationSpoofToObject(param.args[index], latitude, longitude) || changed
        }
        if (changed && notesSpoofLogCount++ < 30) logInfo("Applied Notes location spoof before ${param.method}")
    }

    private fun notesSpoofCoordinates(): Pair<Double, Double>? {
        if (!hasValidNotesLocationSpoof()) return null
        val latitude = parsedNotesSpoofLatitude() ?: return null
        val longitude = parsedNotesSpoofLongitude() ?: return null
        return latitude to longitude
    }

    private fun hasValidNotesLocationSpoof(current: InstagramFeatureState = state): Boolean {
        return current.enableNotesLocationSpoof &&
            parsedNotesSpoofLatitude(current) != null &&
            parsedNotesSpoofLongitude(current) != null
    }

    private fun parsedNotesSpoofLatitude(current: InstagramFeatureState = state): Double? {
        return current.notesSpoofLatitude.trim().toDoubleOrNull()?.takeIf { it in -90.0..90.0 }
    }

    private fun parsedNotesSpoofLongitude(current: InstagramFeatureState = state): Double? {
        return current.notesSpoofLongitude.trim().toDoubleOrNull()?.takeIf { it in -180.0..180.0 }
    }

    private fun spoofLocation(location: Location?): Location? {
        val (latitude, longitude) = notesSpoofCoordinates() ?: return null
        val target = location ?: Location(LocationManager.GPS_PROVIDER)
        target.latitude = latitude
        target.longitude = longitude
        if (target.time <= 0L) target.time = System.currentTimeMillis()
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1 && target.elapsedRealtimeNanos <= 0L) {
            target.elapsedRealtimeNanos = android.os.SystemClock.elapsedRealtimeNanos()
        }
        return target
    }

    private fun applyNotesLocationSpoofToObject(target: Any?, latitude: Double, longitude: Double): Boolean {
        if (target == null) return false
        when (target) {
            is JSONObject -> return applyNotesLocationSpoofToJson(target, latitude, longitude)
            is ContentValues -> return applyNotesLocationSpoofToContentValues(target, latitude, longitude)
            is MutableMap<*, *> -> return applyNotesLocationSpoofToMutableMap(target, latitude, longitude)
        }
        val name = target.javaClass.name.lowercase(Locale.US)
        val noteLike = name.contains("note") || name.contains("location") || name.contains("graphqloptimisticpostoperation")
        var changed = setCoordinateFieldIfPresent(target, "A0I", latitude)
        changed = setCoordinateFieldIfPresent(target, "A0J", longitude) || changed
        changed = setCoordinateFieldIfPresent(target, "latitude", latitude) || changed
        changed = setCoordinateFieldIfPresent(target, "longitude", longitude) || changed
        changed = setCoordinateFieldIfPresent(target, "lat", latitude) || changed
        changed = setCoordinateFieldIfPresent(target, "lng", longitude) || changed
        return if (!changed && noteLike) setFirstTwoCoordinateFields(target, latitude, longitude) else changed
    }

    private fun setCoordinateFieldIfPresent(target: Any, fieldName: String, value: Double): Boolean {
        var cls: Class<*>? = target.javaClass
        while (cls != null && cls != Any::class.java) {
            try {
                val field = cls.getDeclaredField(fieldName)
                field.isAccessible = true
                return setCoordinateFieldValue(target, field, value)
            } catch (_: NoSuchFieldException) {
                cls = cls.superclass
            } catch (_: Throwable) {
                return false
            }
        }
        return false
    }

    private fun setFirstTwoCoordinateFields(target: Any, latitude: Double, longitude: Double): Boolean {
        var cls: Class<*>? = target.javaClass
        var set = 0
        while (cls != null && cls != Any::class.java && set < 2) {
            cls.declaredFields.forEach { field ->
                if (set >= 2 || !isCoordinateField(field)) return@forEach
                runCatching {
                    field.isAccessible = true
                    if (setCoordinateFieldValue(target, field, if (set == 0) latitude else longitude)) set++
                }
            }
            cls = cls.superclass
        }
        return set == 2
    }

    private fun isCoordinateField(field: Field): Boolean {
        return field.type == java.lang.Float.TYPE || field.type == java.lang.Float::class.java ||
            field.type == java.lang.Double.TYPE || field.type == java.lang.Double::class.java ||
            field.type == String::class.java
    }

    private fun setCoordinateFieldValue(target: Any, field: Field, value: Double): Boolean {
        return runCatching {
            when (field.type) {
                java.lang.Float.TYPE, java.lang.Float::class.java -> field.set(target, value.toFloat())
                java.lang.Double.TYPE, java.lang.Double::class.java -> field.set(target, value)
                String::class.java -> field.set(target, value.toString())
                else -> return false
            }
            true
        }.getOrDefault(false)
    }

    @Suppress("UNCHECKED_CAST")
    private fun applyNotesLocationSpoofToMutableMap(target: MutableMap<*, *>, latitude: Double, longitude: Double): Boolean {
        val map = target as MutableMap<Any?, Any?>
        var changed = false
        map.keys.toList().forEach { key ->
            val text = key?.toString()?.lowercase(Locale.US) ?: return@forEach
            val value = when {
                text == "latitude" || text == "lat" || text.endsWith(".latitude") -> latitude
                text == "longitude" || text == "lng" || text == "lon" || text.endsWith(".longitude") -> longitude
                else -> null
            } ?: return@forEach
            map[key] = coordinateValueForExisting(map[key], value)
            changed = true
        }
        return changed
    }

    private fun applyNotesLocationSpoofToJson(target: JSONObject, latitude: Double, longitude: Double): Boolean {
        var changed = false
        listOf("latitude", "lat").forEach { key ->
            if (target.has(key)) {
                target.put(key, coordinateValueForExisting(target.opt(key), latitude))
                changed = true
            }
        }
        listOf("longitude", "lng", "lon").forEach { key ->
            if (target.has(key)) {
                target.put(key, coordinateValueForExisting(target.opt(key), longitude))
                changed = true
            }
        }
        return changed
    }

    private fun applyNotesLocationSpoofToContentValues(target: ContentValues, latitude: Double, longitude: Double): Boolean {
        var changed = false
        listOf("latitude", "lat").forEach { key ->
            if (target.containsKey(key)) {
                target.put(key, latitude)
                changed = true
            }
        }
        listOf("longitude", "lng", "lon").forEach { key ->
            if (target.containsKey(key)) {
                target.put(key, longitude)
                changed = true
            }
        }
        return changed
    }

    private fun coordinateValueForExisting(existing: Any?, value: Double): Any {
        return when (existing) {
            is Float -> value.toFloat()
            is String -> value.toString()
            else -> value
        }
    }

    private fun defaultResult(type: Class<*>): Any? {
        return when {
            type == java.lang.Boolean.TYPE -> false
            type == java.lang.Byte.TYPE -> 0.toByte()
            type == java.lang.Short.TYPE -> 0.toShort()
            type == java.lang.Integer.TYPE -> 0
            type == java.lang.Long.TYPE -> 0L
            type == java.lang.Float.TYPE -> 0f
            type == java.lang.Double.TYPE -> 0.0
            type == java.lang.Character.TYPE -> 0.toChar()
            type == java.lang.Void.TYPE -> null
            type.isInterface -> Proxy.newProxyInstance(type.classLoader ?: appClassLoader, arrayOf(type)) { proxy, method, args ->
                when (method.name) {
                    "toString" -> "PurrfectInstaNoOpRefreshRequest"
                    "hashCode" -> System.identityHashCode(proxy)
                    "equals" -> args != null && args.isNotEmpty() && proxy === args[0]
                    else -> defaultResult(method.returnType)
                }
            }
            else -> null
        }
    }

    private fun findView(root: View, predicate: (View) -> Boolean): View? {
        if (predicate(root)) return root
        if (root is ViewGroup) {
            for (i in 0 until root.childCount) {
                findView(root.getChildAt(i), predicate)?.let { return it }
            }
        }
        return null
    }

    private fun resourceEntryName(view: View): String? {
        val id = view.id
        if (id <= 0x00FFFFFF) return null
        resourceEntryNameCache[id]?.let { return it }
        val name = runCatching { view.resources.getResourceEntryName(id) }.getOrNull() ?: return null
        resourceEntryNameCache[id] = name
        return name
    }

