    private fun isHomeEntryPointView(view: View, activity: Activity, viewName: String = resourceEntryName(view).orEmpty()): Boolean {
        ensureEntryPointIdsCached(activity)
        if ((entryFeedTabId != 0 && view.id == entryFeedTabId) || viewName == "feed_tab" || viewName == "home_tab") return true
        var parent = view.parent as? View
        repeat(8) {
            val node = parent ?: return@repeat
            val name = resourceEntryName(node).orEmpty()
            if ((entryFeedTabId != 0 && node.id == entryFeedTabId) || name == "feed_tab" || name == "home_tab") return true
            parent = node.parent as? View
        }
        return false
    }

