    private class OldPostReelLineIconDrawable(
        private val type: Int,
        private val lineColor: Int
    ) : android.graphics.drawable.Drawable() {
        companion object {
            const val TYPE_EYE_SLASH = 1
            const val TYPE_EYE = 2
        }

        private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            color = lineColor
            style = Paint.Style.STROKE
            strokeCap = Paint.Cap.ROUND
            strokeJoin = Paint.Join.ROUND
        }

        override fun draw(canvas: Canvas) {
            val b = bounds
            val size = minOf(b.width(), b.height()).toFloat()
            if (size <= 0f) return
            val cx = b.left + b.width() / 2f
            val cy = b.top + b.height() / 2f
            val width = size * 0.86f
            val height = size * 0.52f
            val oval = android.graphics.RectF(
                cx - width / 2f,
                cy - height / 2f,
                cx + width / 2f,
                cy + height / 2f
            )
            paint.color = lineColor
            paint.style = Paint.Style.STROKE
            paint.strokeWidth = maxOf(2.5f, size * 0.085f)
            canvas.drawArc(oval, 200f, 140f, false, paint)
            canvas.drawArc(oval, 20f, 140f, false, paint)
            if (type == TYPE_EYE) {
                canvas.drawCircle(cx, cy, size * 0.115f, paint)
            } else {
                canvas.drawLine(cx - width * 0.46f, cy + height * 0.63f, cx + width * 0.46f, cy - height * 0.63f, paint)
            }
        }

        override fun setAlpha(alpha: Int) {
            paint.alpha = alpha
            invalidateSelf()
        }

        override fun setColorFilter(colorFilter: ColorFilter?) {
            paint.colorFilter = colorFilter
            invalidateSelf()
        }

        override fun getOpacity(): Int = PixelFormat.TRANSLUCENT
    }

    private class UploadGlyphDrawable : android.graphics.drawable.Drawable() {
        private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            color = Color.WHITE
            style = Paint.Style.STROKE
            strokeCap = Paint.Cap.ROUND
            strokeJoin = Paint.Join.ROUND
        }

        override fun draw(canvas: Canvas) {
            val b = bounds
            val w = b.width().toFloat()
            val h = b.height().toFloat()
            val cx = b.left + w / 2f
            val top = b.top + h * 0.20f
            val mid = b.top + h * 0.34f
            val shaftBottom = b.top + h * 0.62f
            val trayTop = b.top + h * 0.66f
            val trayBottom = b.top + h * 0.80f
            val left = b.left + w * 0.26f
            val right = b.left + w * 0.74f
            paint.strokeWidth = maxOf(2.5f, w * 0.075f)

            canvas.drawLine(cx, top, cx, shaftBottom, paint)
            canvas.drawLine(cx, top, b.left + w * 0.37f, mid, paint)
            canvas.drawLine(cx, top, b.left + w * 0.63f, mid, paint)
            canvas.drawLine(left, trayTop, left, trayBottom, paint)
            canvas.drawLine(left, trayBottom, right, trayBottom, paint)
            canvas.drawLine(right, trayBottom, right, trayTop, paint)
        }

        override fun setAlpha(alpha: Int) {
            paint.alpha = alpha
        }

        override fun setColorFilter(colorFilter: ColorFilter?) {
            paint.colorFilter = colorFilter
        }

        override fun getOpacity(): Int = PixelFormat.TRANSLUCENT
    }

    private class DownloadGlyphDrawable : android.graphics.drawable.Drawable() {
        private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            color = Color.WHITE
