            val cx = b.left + w / 2f
            val top = b.top + h * 0.20f
            val tip = b.top + h * 0.62f
            val arrowY = b.top + h * 0.48f
            val trayTop = b.top + h * 0.68f
            val trayBottom = b.top + h * 0.82f
            val left = b.left + w * 0.26f
